(window.GIM_TP=window.GIM_TP||{})["Beitzah.0"]={"from":0,"a":[[["מתני׳ \u0001ביצה\u0002 שנולדה ביום טוב בית שמאי אומרים תאכל ובית הלל אומרים לא תאכל בית שמאי אומרים שאור בכזית וחמץ בככותבת ובית הלל אומרים זה וזה בכזית","השוחט חיה ועוף ביום טוב בית שמאי אומרים יחפור בדקר ויכסה ובית הלל אומרים לא ישחוט אלא אם כן היה לו עפר מוכן מבעוד יום ומודים שאם שחט שיחפור בדקר ויכסה שאפר כירה מוכן הוא:","\u0001גמ׳\u0002 במאי עסקינן אילימא בתרנגולת העומדת לאכילה מאי טעמייהו דבית הלל אוכלא דאפרת הוא","אלא בתרנגולת העומדת לגדל ביצים","מאי טעמייהו דבית שמאי מוקצה היא ומאי קושיא דלמא בית שמאי לית להו מוקצה","קא סלקא דעתין אפילו מאן דשרי במוקצה בנולד אסר מאי טעמייהו דבית שמאי","אמר רב נחמן לעולם בתרנגולת העומדת לגדל ביצים ודאית ליה מוקצה אית ליה נולד ודלית ליה מוקצה לית ליה נולד בית שמאי כרבי שמעון ובית הלל כרבי יהודה","ומי אמר רב נחמן הכי והתנן בית שמאי אומרים מגביהין מעל השלחן עצמות וקליפין ובית הלל אומרים מסלק את הטבלא כולה ומנערה","ואמר רב נחמן אנו אין לנו אלא בית שמאי כרבי יהודה ובית הלל כרבי שמעון","אמר לך רב נחמן גבי שבת דסתם לן תנא כרבי שמעון דתנן מחתכין את הדלועין לפני הבהמה ואת הנבלה לפני הכלבים","מוקים לה לבית הלל כרבי שמעון אבל"],[[0,"ביצה לא תאכל","בו ביום בגמרא מפרש טעמא:"],[0,"שאור בכזית","משום דהני תלת מילי הוו מקולי בית שמאי ומחומרי בית הלל גבי יו\"ט תנא להו גבי הדדי ובגמרא מפרש טעמייהו:"],[0,"בככותבת","תמרה:"],[1,"יחפור בדקר","פיל\"א בלע\"ז:"],[1,"ומודים שאם שחט כו'","כדמפרש טעמא בגמ' כשיש לו דקר נעוץ מבעוד יום:"],[1,"שאפר כירה מוכן הוא","בגמרא בעי מאי קאמר:"],[2,"גמ' העומדת לאכילה","שאינה מוקצת:"],[2,"אוכלא דאפרת","אוכל שנפרד וחבירו במנחות חבורי אוכלין כמאן דמפרתי דמו וכן בשחיטת חולין (דף עג.):"],[4,"לית להו מוקצה","דדלמא כר' שמעון סבירא להו דאמר בפרק [כירה] (שבת דף מד.) מותר השמן שבנר ושבקערה אסור (דברי רבי יהודה) ור\"ש מתיר:"],[5,"קא סלקא דעתין","להכי פרכינן מאי טעמייהו דבית שמאי דקא סלקא דעתין דאפי' לר' שמעון דשרי במוקצה בנולד אסיר דאילו במוקצה סבירא ליה לא מקצי איניש מדעתיה מידי דחזי ליה אבל נולד לא הוה ידע דנהוי דעתיה עלויה:"],[7,"ומי אמר רב נחמן הכי","דבית הלל כר' יהודה:"],[7,"מגביהין","בשבת מעל השלחן עצמות שאינן ראוין לאכילה וקליפי אגוזים ולא חיישינן למוקצה:"],[7,"ובית הלל אומרים","אין מטלטלין אותן בידים שמוקצה הן:"],[7,"אלא מסלק הטבלא","שיש תורת כלי עליה ומנערה:"],[8,"ואמר רב נחמן אנו אין לנו","בשיטת משנה זו לפי שמוחלפת שיטתה אלא כך שמעתי מרבותינו דבית שמאי כרבי יהודה ומחמרי ובית הלל כרבי שמעון:"],[9,"מחתכין דלועין","תלושין לפני הבהמה ולא אמרינן טרחא דלאו צורך הוא:"],[9,"ואת הנבילה לפני הכלבים","ואע\"פ שנתנבלה בשבת דבין השמשות לא היתה עומדת לאכילת כלבים אפילו הכי שרי דלית לן מוקצה בשבת הלכך מגביהין מעל השלחן דמיירי בשבת מוקים לבית הלל דנימרו כר' שמעון כי היכי דלא תקשי הלכתא אהלכתא דקיימא לן הלכה כסתם משנה וקיימא הלכה כבית הלל אבל גבי יום טוב דאשכחן דסתם רבי כרבי יהודה:"]],[[0,"","ביצה שנולדה בי\"ט בש\"א תאכל ובה\"א לא תאכל. וא\"ת אמאי לא תנא אוסרין ומתירין וכי תימא אוסרין משמע שאסור לעולם זה אינו דאמרינן לקמן (ביצה דף ו.) אפרוח שנולד בי\"ט אסור והיינו ביומו ועוד דאמרינן (לקמן ביצה ל:) מותר שמן שבנר רבי יהודה אוסר והיינו דוקא באותו יום ויש לומר דאי הוה תני אוסרין ומתירין הייתי אומר שמה שמתירין הביצה היינו לטלטל אבל באכילה אסורה והכי אמרינן (לקמן ביצה דף כד.) גבי נכרי אחד שהביא דגים לפני רבן גמליאל ואמר מותרים הם אלא שאין רצוני לקבל הימנו ומסיק מאי מותרים לטלטל אבל באכילה אסורים ואם תאמר לבית הלל דאמרי לא תאכל אבל לטלטל שרי והא קי\"ל (לקמן ביצה ד.) דאף לטלטל אסור לכן פירש ר\"י דנקט כי האי לישנא דסתם ביצה לאכילה קיימא עוד יש לומר דנקט לבית שמאי תאכל משום דמשמע אכילה וטלטול דאין אכילה בלא טלטול ובית הלל אסרי אף בטלטול אלא אגב דנקטי ב\"ש תאכל נקטי אינהו לא תאכל:"],[0,"","שאור בכזית. לא שייך הכא מידי אלא מייתי כאן תלת מילי גבי יום טוב דבית הלל לחומרא וב\"ש לקולא:"],[2,"","אוכלא דאפרת הוא. פירוש אוכל הנפרד מן האוכל הוא דהביצה שנולדה נפרדה היא מן התרנגולת ואי בעי שחיט לה ואכיל כל שבגוה:"],[4,"","דלמא בית שמאי לית להו מוקצה. תימה במתני' קאמר בהדיא דבית שמאי אית להו מוקצה דקתני (לקמן ביצה דף י.) לא יטול אלא אם כן נענע מבעוד יום ויש לומר דמוקצה דבעלי חיים חמיר טפי ומוקצה ביותר והתם הוא דאית ליה מוקצה כדחזינא ר\"ש דאע\"ג דלית ליה מוקצה אית ליה (שבת דף מה.) גבי גרוגרת וצמוקים דאתקצאי טפי:"],[5,"","קא סלקא דעתין דאפי' מאן דשרי מוקצה בנולד אסיר. דלא מקצי איניש מאי דחזי ליה אבל בנולד לא הוה ידע מאתמול ותימה דהא רבי שמעון דשרי במוקצה שרי בנולד כדאמרינן בשבת (דף כט.) רבי יהודה אומר אין מסיקין בשברי כלים ור\"ש מתיר אע\"ג דהוי נולד וי\"ל דלא דמי דהאי נולד דהכא הוי נולד טפי שמתחילה לא היה בעולם אבל התם הכלי היה בעולם רק שנשבר וכן משמע נמי בעירובין (דף מה: ושם) מיא בעיבא מיבלע בליעי ופריך כל שכן דהוי נולד ואסור ומאי פריך ודלמא ההוא כר' שמעון דהא רבי שמעון מתיר בנולד אלא ודאי היינו טעמא כדפרישית דכיון דבליעי לא היו כלל בעולם ואפי' ר' שמעון מודה דהאי נולד אסור:"],[7,"","מגביהין מעל השלחן עצמות וקליפין. פ\"ה אע\"ג דאין ראוין לא למאכל אדם ולא למאכל בהמה ולא נהירא דהא איכא בסיפא ושער של אפונין ושער של עדשים מפני שהן ראוין למאכל בהמה לכך נ\"ל שהם ראוים למאכל בהמה כגון עצמות רכים וקליפי תפוחים ובית הלל סברי כיון דלא חזי למאכל אדם לא:"],[7,"","ובית הלל אומרים מסלק את הטבלא ומנערה. תימה והלא היא בסיס לדבר האסור דהא לא שכח הואיל והניחם שם מדעתו ויש לומר דלפירוש רבינו תם ניחא דפירש במסכת שבת דלא הוי בסיס לדבר האסור אלא כשדעתו להניחם שם כל היום אי נמי כיון דהוו שם אוכלין הוה ליה בסיס לדבר האסור ולדבר המותר ושרי כדמוכח פרק נוטל (שבת דף קמב.) ועוד דאין זה מניח בכוונה דהא אינו חושש היכן יפלו:"],[9,"","דתנן מחתכין את הדלועין לפני הבהמה ואת כו'. וא\"ת היכי דמי אי בדלועין שהיו מחוברין בין השמשות בהא ודאי מודה ר' שמעון גזרה שמא יעלה ויתלוש וי\"ל דמיירי בתלושין וסלקא דעתך דאסור דמשוה להו אוכלין לפי שהן קשין והחתוך מרכך אותם:"],[9,"","ואת הנבלה כו'. אנו צריכין לפרש שנתנבלה בשבת ומכל מקום תני להו בהדי הדדי דאע\"ג דבדלועין לא הוי טעמא משום מוקצה כמו בנבלה משום דבשניהם שייך לשון מחתכין:"]]],[["גבי יום טוב דסתם לן תנא כרבי יהודה דתנן אין מבקעין עצים מן הקורות ולא מן הקורה שנשברה ביום טוב מוקים לה לבית הלל כרבי יהודה","מכדי מאן סתמיה למתני' רבי מאי שנא בשבת דסתם לן כרבי שמעון ומאי שנא ביו\"ט דסתם לן כרבי יהודה","אמרי שבת דחמירא ולא אתי לזלזולי בה סתם לן כרבי שמעון דמיקל יום טוב דקיל ואתי לזלזולי ביה סתם לן כרבי יהודה דמחמיר","במאי אוקימתא בתרנגולת העומדת לגדל ביצים ומשום מוקצה אי הכי אדמפלגי בביצה לפלגו בתרנגולת","להודיעך כחן דבית שמאי דבנולד שרי","ולפלוגי בתרנגולת להודיעך כחן דבית הלל דבמוקצה אסרי וכי תימא כח דהתירא עדיף ונפלוג בתרוייהו","תרנגולת העומדת לגדל ביצים היא וביצתה בית שמאי אומרים תאכל ובית הלל אומרים לא תאכל","אלא אמר רבה לעולם בתרנגולת העומדת לאכילה וביום טוב שחל להיות אחר השבת עסקינן ומשום הכנה","וקסבר רבה כל ביצה דמתילדא האידנא מאתמול גמרה לה","ורבה לטעמיה דאמר רבה מאי דכתיב (שמות טז, ה) והיה ביום הששי והכינו את אשר יביאו חול מכין לשבת וחול מכין ליום טוב ואין יום טוב מכין לשבת ואין שבת מכינה ליום טוב","א\"ל אביי אלא מעתה יום טוב בעלמא תשתרי גזרה משום יום טוב אחר השבת שבת דעלמא תשתרי גזרה משום שבת אחר יום טוב","ומי גזרינן והא תניא השוחט את התרנגולת ומצא בה ביצים גמורות מותרות לאכלן ביום טוב ואם איתא ליגזר משום הנך דמתילדן ביומיהן","אמר ליה ביצים גמורות במעי אמן מילתא דלא שכיחא היא ומילתא דלא שכיחא לא גזרו בה רבנן","רב יוסף אמר גזרה משום פירות הנושרין","א\"ל אביי פירות הנושרין טעמא מאי"],[[0,"דתנן אין מבקעין עצים","בי\"ט לא מן הקורות הסדורות זו על גב זו בקרקע ועומדות לבנין:"],[0,"ולא מן הקורה שנשברה בי\"ט","ואע\"פ שעומדת מעכשיו להיסק הואיל ובין השמשות לאו להכי קיימא כיון דאתקצאי לבין השמשות אתקצאי לכולי יומא אלמא אית לן מוקצה ביום טוב הלכך מוקי רב נחמן למתני' דאיירי ביום טוב ובית הלל כר' יהודה ובעומדת לגדל ביצים ומשום מוקצה:"],[1,"מאן סתם לן למתני' ר'","הוא סדר המשנה וכשראה דברי חכם וישרו בעיניו שנאן סתם ולא הזכיר שם אומרו עליהן כדי שלא יהו שנויה מפי יחיד ונראין כאילו נשנו מפי המרובים ויעשו כמותן:"],[2,"ולא אתי לזלזולי ביה","אי מקילין בה חדא קולא לא אתי לאקולי בה טפי:"],[5,"דהתירא עדיף ליה","טוב לו להשמיענו כח דברי המתיר שהוא סומך על שמועתו ואינו ירא להתיר אבל כח האוסרין אינה ראיה שהכל יכולין להחמיר ואפילו בדבר המותר:"],[7,"ומשום הכנה","דאסרי לה ב\"ה כדמפרש ואזיל:"],[8,"דכל ביצה דמתילדא האידנא מאתמול גמרה לה","ואף על גב דבידי שמים הוא אסור דבעינן כל סעודות שבת וסעודות יום טוב שיהו מזומנות ומוכנות מבעוד יום של חול:"],[9,"ורבה","דאסר בהכנה שאינה בידים ממש:"],[9,"לטעמיה דאמר רבה","בפסחים (דף מז:) ויליף מהכא דמוקצה דאורייתא:"],[9,"והכינו","והזמינו כגון מכאן אני אוכל למחר דאי משום הכנה בידים ולומר שיאפו ויבשלו מבעוד יום בהדיא כתיב את אשר תאפו אפו אלא הזמנה בפה קאמר וכתיב ביום הששי וסתם ששי חול הוא ואחשבה רחמנא לסעודת שבת שיזמיננה מבעוד יום ובחול:"],[9,"ואין יום טוב מכין לשבת","ויום טוב נמי קרוי שבת ובעיא סעודתו הזמנה והזמנתה בחול אבל סעודת חול לא חשיבא ולא שייכא בה הזמנה הלכך באחד בשבת בעלמא לית לן למיסר ביצה שנולדה ביה משום דאתכן בידי שמים דסעודת חול לא אצרכה רחמנא זמון מבעוד יום דלא שייך בה מוקצה:"],[10,"יום טוב בעלמא","שאינו אחר שבת:"],[10,"שבת דעלמא","שאינו אחר יום טוב:"],[10,"תשתרי","לגמוע ביצה חיה שנולדה בו:"],[11,"ומי גזרינן","ומי אחמור רבנן בביצה למגזר היתרא משום איסורא:"],[11,"[והתניא וכו']","וא\"ת הויא לה גזרה לגזרה דהנך דמתילדין ביומיהם נמי אינן אסורות אלא משום גזרה דיום טוב אחר השבת תריץ הא מצי לאוקומי ביום טוב אחר השבת דהשתא איכא למיגזר אטו דמתילדין ביומיהם ואשמועינן הך מתני' דאפי' בי\"ט אחר השבת מותרות הואיל ואינם נולדות ומשום הנך דמתילדן ליכא למגזר דמילתא דלא שכיחא הוא בשם רבינו והא דאמרינן בכולי הש\"ס שאין גוזרין גזרה לגזרה מהאי קרא נפקא ושמרתם את משמרתי עשו משמרת כלומר גזרה למשמרתי לתורתי ולא משמרת למשמרת שלא יעשו גזרה לגזרה:"],[11,"ואין י\"ט מכין לחברו","לא גרסינן במלתיה דרבה דהא קרא קא דריש ושני ימים רצופים בתורה לא אשכחן דמספיקא עבדינן להו:"],[13,"רב יוסף אמר","טעמא דביצה בתרנגולת העומדת לאכילה וכדאוקימנא ובית הלל דאסרי משום פירות הנושרין מן האילן בשבת וקא סלקא דעתך השתא גזרה היא משום פירות הנושרין דלא נכלינהו דהא נמי לפירות הנושרין מן האילן דמיא שאף זו פרי הנושר:"]],[[0,"","גבי שבת דסתם לן תנא כרבי שמעון. ותימה והא הוי סתם ואח\"כ מחלוקת דהא פליג ר' יהודה במתניתין ואמר אם לא נתנבלה בערב שבת אסור ואין הלכה כסתם דכי האי גונא חשיב סתם ואח\"כ מחלוקת בפרק יש נוחלין (ב\"ב דף קכב: ושם) גבי מלתיה דרבי יוחנן בן ברוקה דפריך סתם ואחר כך מחלוקת היא וי\"ל דהתם סמיך אועוד מאי אלא דפריך בתר הכי וכן פירש שם בקונטרס אבל לעולם מהני הסתם להיות רבים והוי רבים רבי שמעון והוי יחיד רבי יהודה והלכתא כרבים כת\"ק דהיינו רבי שמעון וא\"ת גבי שבת נמי סתם לן כרבי יהודה כי האי דתנן (שבת דף מד.) מטלטלין נר חדש אבל לא ישן ור' שמעון מתיר והואיל ואוסר מוקצה מחמת מיאוס כל שכן מחמת איסור דהכי אמרינן התם וי\"ל דהאי סתמא עדיפא הואיל ונשנית משנה בסתם לבסוף פרק מי שהחשיך (שבת דף קנו: ושם):"],[0,"","מוקים לב\"ה כר\"ש. וקשה דמאי אולמיה דהאי סתמא מהאי סתמא וי\"ל דבעדיות לא תני לה מקולי ב\"ש וחומרי ב\"ה:"],[0,"","אין מבקעין עצים לא מן הקורות וכו'. לא מייתי מרישא דאין מבקעין קורות דהא מיירי בסואר של קורות דהוי מוקצה מחמת חסרון כיס ובהא כ\"ע מודו אפי' ר' שמעון אלא מייתי מסיפא דלא מן הקורה שנשתברה וא\"ת והא ר' שמעון אינו מתיר אלא ביושב ומצפה (לקמן ביצה ל:) וי\"ל דה\"נ הואיל ונשתברה בשבת מסתמא היתה רעועה מאתמול והוי כיושב ומצפה מתי תשבר קורתו ותהיה ראויה להסקה:"],[5,"","וכ\"ת כח דהתירא עדיף. פי' הקונט' לכך כח דהתירא עדיף כשאדם מתיר סומך על שמועתו וצריך להביא ראיה לדבריו אבל איסורא אדם יכול להחמיר עליו בלא טעם:"],[5,"","ונפלוג בתרוייהו. תימה ובכל מקום דקאמר כח דהיתרא עדיף לפרוך הכי וי\"ל דהכי פריך ונפלוג בתרוייהו שלא יאריך משום כך ויאמר היא וביצתה אבל בעלמא לא שייך:"],[9,"","והיה ביום הששי וגו'. פרש\"י וע\"כ בא לאשמועינן דאפילו הכנה בידי שמים ביצה אסורה דאי משום הכנה בידי אדם כלומר שיאפו ויבשלו מבעוד יום הא בהדיא כתיב את אשר תאפו אפו אלא הזמנה בפה קאמר ואין י\"ט מכין לשבת כו' ואין שבת מכין לי\"ט מכ\"ש דכיון דאין י\"ט מכין לשבת כ\"ש דאין שבת מכין לי\"ט והקשה רש\"י אם כן ביצה שנולדה באחד בשבת או לאחר י\"ט תתסר מכ\"ש דשבת וי\"ט לא מכינין אהדדי כ\"ש דלא מכינין אחול ותירץ דלגבי סעודת חול לא צריך הכנה דאין סעודת חול חשובה אך תימה הואיל והכנה דאורייתא היאך אופין ומבשלין מי\"ט לשבת וכ\"ת ע\"י ערובי תבשילין וכי אתי תקנתא דרבנן וליעקר הכנה דאורייתא ונראה ליישב דרבה גופיה אזיל לטעמיה דאית ליה הואיל ואי מקלעי אורחין חזי ליה השתא נמי חזי ליה ואפילו לדידן ניחא דכל דבר אפוי ומבושל לא שייך ביה הכנה שאינו מחוסר רק תקון בעלמא דמעיקרא הוה חזי ליה רק גבי ביצה שהוא דבר חדש שלא היתה בעולם ולא היתה ראויה כלל מעיקרא (ולאפות ולבשל תקוני מלתא בעלמא) תימה דכאן משמע שהמן לא היה יורד בי\"ט כדפי' רש\"י הששי הראוי להכנה וזהו בחול והא אמר ויברך ויקדש ברכו במן וקדשו במן שבשבת לא היה יורד מן אבל בי\"ט היה יורד וי\"ל דמדרשים חלוקין כדאיתא במדרש (מכילתא ע' בשלח) שבת לא יהיה (שמות ט״ז:כ״ו) לרבות יום הכפורים לא יהיה בו לרבות י\"ט שלא היה יורד בהן מן ועי\"ל דאפי' היה יורד בי\"ט מ\"מ בי\"ט שחל להיות בע\"ש לא היה יורד מדכתיב קרא בו ביום הששי ולא כתיב ששי משמע הששי המיוחד שהוא ראוי להכנה ולא בששי שהוא יו\"ט:"],[11,"","נגזר משום הנך דמתילדן ביומיהן. ואין זה גזרה לגזרה דמותר לאוכלן בי\"ט משמע אפילו ביום טוב דלאחר השבת:"],[12,"","מלתא דלא שכיחא היא. וקשה דלמא אם לא שחטה היתה נולדת היום ואם כן מאתמול גמרה לה ותאסר בלא גזרה מספק וי\"ל דמאחר דלא נולדה ע\"י כך לא חשיב גמר ובירושלמי פליג בהא:"]]],[["גזרה שמא יעלה ויתלוש היא גופה גזרה ואנן ניקום ונגזור גזרה לגזרה כולה חדא גזרה היא","רבי יצחק אמר גזרה משום משקין שזבו","אמר ליה אביי משקין שזבו טעמא מאי גזרה שמא יסחוט היא גופה גזרה ואנן ניקום ונגזור גזרה לגזרה כולה חדא גזרה היא","כולהו כרב נחמן לא אמרי כי קושיין כרבה נמי לא אמרי הכנה לית להו","אלא רב יוסף מאי טעמא לא אמר כרבי יצחק אמר לך ביצה אוכלא ופירות אוכלא לאפוקי משקין דלאו אוכלא","ורבי יצחק מאי טעמא לא אמר כרב יוסף אמר לך ביצה בלועה ומשקין בלועין לאפוקי פירות דמגלו וקיימו","ואף רבי יוחנן סבר גזרה משום משקין שזבו דרבי יוחנן רמי דרבי יהודה אדרבי יהודה ומשני","תנן אין סוחטין את הפירות להוציא מהן משקין ואם יצאו מעצמן אסורין רבי יהודה אומר אם לאוכלין היוצא מהן מותר ואם למשקין היוצא מהן אסור","אלמא כל אוכלין לרבי יהודה אוכלא דאפרת הוא","ורמינהו ועוד אמר רבי יהודה מתנה אדם על כלכלה של פירות ביום טוב ראשון","ואוכלה בשני וכן ביצה שנולדה בראשון תאכל בשני","בשני אין בראשון לא ומשני רבי יוחנן מוחלפת השיטה","ומדקא מרמי להו אהדדי שמע מינה חד טעמא הוא"],[[0,"ויתלוש","דהוה איסורא דאורייתא דהיינו קוצר שהוא אב מלאכה:"],[0,"חדא גזרה היא","לא שתהא זו גזרה דלא ליתי לידי פירות הנושרין אלא כשנמנו וגזרו על פירות הנושרין אף ביצה היתה במשמע ואע\"ג דלית בה משום תלישה מיהו מכלל גזרת חכמים היתה שאף היא פרי הנושר:"],[1,"משום משקין שזבו","דק\"ל אסורין לבו ביום כדתנן ואם יצאו מעצמן אסורים (שבת דף קמג:) וביצה נמי דמיא להו שזבה ויצאת ממקום שהיתה בלועה:"],[2,"שמא יסחוט","וסחיטת פירות תולדה דדש היא שמפרקן מתוך זג שלהן כמפרק תבואה מקש שלה:"],[2,"חדא גזרה היא","כדפרישית כשגזרו על משקין שזבו אף ביצה היתה במשמע:"],[3,"כולהו","רבה דאוקי מתני' משום הכנה ורב יוסף ורבי יצחק דאוקמוה משום גזרה:"],[3,"כרב נחמן לא אמרי","משום מוקצה:"],[3,"כי קושיין","כדפרכינן לעיל ליפלגו בתרווייהו:"],[4,"ומשקין לאו אוכלא","הלכך כשגזרו על משקין שזבו לא היתה ביצה במשמע שהרי אינה משקה אבל בכלל פירות הנושרין היתה:"],[5,"בלועה","בתוך התרנגולת וזבה לחוץ:"],[5,"ומשקין בלועין","בחרצן וזבין לחוץ:"],[5,"לאפוקי פירות דמגלו וקיימו","הלכך נשירת הביצה לאו בכלל נשירת הפירות:"],[7,"ואם יצאו מעצמן אסורין","בו ביום גזרה שמא יסחוט:"],[7,"אם לאוכלין","הן מכונסין הפירות הללו היוצא מהן מותר בו ביום דכיון דלא ניחא ליה בהני משקין ליכא למגזר שמא יסחוט:"],[8,"אלמא","מדקאמר אם לאוכלין היוצא מהן מותר כל לאוכלין אמר בדבר היוצא מהן אוכלא דאפרת הוא ואינו בכלל גזרת משקין שזבו:"],[9,"ועוד אמר ר' יהודה","לעיל מיניה תנן במסכת ערובין ראש השנה שהיה ירא שמא תתעבר ויהיו שני ימים טובים מערב אדם שני ערובין כו' דקסבר שתי קדושות הן אחד חול ואחד יום טוב ולא ידעינן הי חול והי יום טוב:"],[9,"מתנה אדם על הכלכלה","להא מלתא הוי שתי קדושות היתה לו כלכלה של פירות טבל ושכח ולא עישר מערב יום טוב ותנן אין מגביהין תרומות ומעשרות ביו\"ט מעשר ביו\"ט בתנאי ואומר אם היום חול ולמחר קדש יהיו אלו תרומה ומעשרות על אלו ואם היום קדש אין בדברי כלום ונותן בהן סימן ולמחרת חוזר ואומר כן אם היום חול ואתמול קדש יהיו אלו תרומה על השאר ואם היום קדש ואתמול חול הרי נעשה תרומה מאתמול וממה נפשך נתקנו:"],[10,"ואוכלה בשני","אבל לא בראשון דשמא קדש הוא ואין בדבריו כלום:"],[10,"וכן לגבי ביצה","הוו שתי קדושות האחד חול והאחד יו\"ט והנולדה בראשון מותרת בשני:"],[11,"בשני אין בראשון לא","אלמא כל מידי דזב ממקומו ביו\"ט ואפילו אוכלא אסור:"],[11,"ומשני רבי יוחנן מוחלפת השיטה","שיטת המשנה דאין סוחטין ואיפוך דרבי יהודה לרבנן:"],[12,"ומדקא מרמי","רבי יוחנן משקין שזבו וביצה אהדדי:"],[12,"שמע מינה חד טעמא הוא","ומאן דאסר בהא אסר בהא ודשרי בהא שרי בהא:"]],[[0,"","גזרה שמא יעלה ויתלוש. ותימה ל\"ל האי טעמא דלקמן (ביצה דף כד:) גבי נכרי שהביא דורון אם יש במינו במחובר אסור פי' רש\"י דכיון דאתקצאי לבין השמשות אתקצאי לכולא יומא וכן משמע דטעמא משום מוקצה מדמייתי לה גבי ספק מוכן והשתא תרי טעמי למה לי וי\"ל דטעמא דהכא אתיא אליבא דר' שמעון דלית ליה מוקצה ולקמן אתיא אליבא דרבי יהודה ותימה דהא פירש רש\"י גופיה לקמן נכרי שהביא דורון כו' אסור הואיל ולא לקטינהו מאתמול אקצינהו והוי כמוקצה דגרוגרות וצמוקים דאפי' ר' שמעון מודה א\"כ אתיא נמי כר' שמעון ע\"כ י\"ל דמיירי הכא כגון בחצר דהוי מוכן לעורבים ומוכן לעורבים הוי מוכן לאדם לכך צריך האי טעמא וא\"ת הא אמרי' (שבת דף קכב.) מעמיד אדם בשבת בהמתו על המחובר אבל לא על המוקצה פירוש עשבים שנתלשו היום ואמאי הא הוי מוכן לבהמה דאי בעי אכלה מנפשה וי\"ל דמיירי בתרי עברי דנהרא עוד יש לומר דלא שייך מוכן לעורבים רק בפירות האילן שרגילין להשיר מעצמן והוא מצפה לכך אבל תימה אם כן כיון דאמר האי טעמא למה לי טעמא דלקמן ויש לומר . דלקמן מיירי בדבר דבעי מרא וחצינא כגון לפת וצנון דלא שייך שמא יעלה ויתלוש דאדכורי מדכר הואיל ואין יכול בקל לתולשו וראיה לדבר הא דתנן במסכת שבת (דף קכב. ושם) נכרי שהדליק הנר בשביל ישראל אסור להשתמש לאורו אבל בשביל הנכרי מותר ואמאי לא חיישינן שמא ידליקנו ישראל עצמו אלא אדכורי מדכר ומטעם זה אכל רבינו אליעזר ממי\"ץ מליח שצלאו נכרי מעצמו בשבת דלמאי ניחוש הרי לא צלאו בשבילו וכי תימא שמא יצלה הוא עצמו הואיל ואיכא טרחא בדבר אדכורי מדכר ואי משום מוקצה חזי לכוס ולא נהירא דאמרינן במסכת שבת (ג\"ז שם) בהדיא אם הביא נכרי מים אסור שמא ירבה בשבילו ואין לחלק ולומר דדוקא גבי מים שייך שמא ירבה בשבילו אבל כאן הנכרי צלאו כבר ולא שייך האי טעמא דהא איכא בתוספתא (דשבת סי\"ב) בהדיא במכירו אסור מפני שמרגילו לשבת הבאה ועוד י\"ל דדוקא בפירות וענבים שייך שמא יעלה ויתלוש ושמא יסחוט לפי שאדם מתאוה להם ובעודו בכפו יבלענו אך תימה מאי שמא יעלה ויתלוש הא אפי' לכתחילה מותר לתלוש דהא אוכל נפש מותר וגם קשה לקמן (ביצה דף כג: ושם) תנן אין צדין דגים מן הביברין ביו\"ט ואמאי הא אוכל נפש הוא ואין לומר דכל דבר שיכול לעשותו מערב יו\"ט אסור לעשותו ביו\"ט עצמו כי לא אתעביד ליה מערב יו\"ט דהא אמרי' (לקמן ביצה כח:) הוא ולא מכשיריו פירוש אוכל נפש ולא מכשיריו כגון לתקן שפוד רבי יהודה אומר לכם לכל צרכיכם והוא לבדו איצטריך לאסור מכשירין שאפשר לתקנן מערב יום טוב אלמא דוקא במכשירין יש חילוק בין אפשר לעשותן מערב יו\"ט בין אי אפשר אבל באוכל נפש כ\"ע מודו דאפילו אפשר לעשותן מערב יו\"ט מותר לעשותן ביו\"ט וי\"א דלכך אין צדין שמא יצוד דגים טמאים שאינם צורך ולא נהירא דאם כן הוי מלאכה שאינה צריכה לגופה דמותרת על כן פירש רבינו נתנאל מקינו\"ן דבירושלמי יש אך אשר יאכל לכל נפש וסמיך ליה ושמרתם את המצות אותם מלאכות שמשימור ואילך הם מותרות דהיינו מלישה ואילך אבל שאר מלאכות דמקודם לכן אסורין ועוד דבירושלמי יש מיעוט אחר אך שלא לקצור [וע' תוספות שבת צה. ד\"ה והרודה]:"],[11,"","רבי יוחנן אמר מוחלפת השיטה. פירש רש\"י מוחלפת ההיא דאין סוחטין ויפה פירש דעל כרחך צריך לפרש הכי דאין לפרש איפוך ההיא דכלכלה דאם כן כ\"ש דקשה מדרבי יהודה לדר\"י שיאסור ביו\"ט שני דהא רבנן דפליגי עליה אמרי קדושה אחת היא וא\"כ אי אמרינן איפוך אסור אפילו ביו\"ט שני ותימה דהא ר' יוחנן גופה פסיק בפרק חבית (שבת דף קמג: ושם) דהלכה כרבי יהודה (דקאמר רבי יוחנן הלכה כרבי יהודה) בשאר פירות אבל זיתים וענבים לא אלמא דלא סבירא ליה דמוחלפת השיטה וי\"ל דרבי יוחנן קאמר לפי דברי אותם האמוראים דלא סברי מוחלפת השיטה לדבריכם הכי הוא והכי נראה לי כמדומה ובשיטת מאיבר\"א תירץ דמוחלפת השיטה היא אותה דכלכלה ורבי יהודה לדבריהם דרבנן קאמר להו לדידי אפילו ביום הראשון מותרין דאוכלא דאפרת הוא ולדידכו דאסריתו נולד בההיא דאין סוחטין אפילו ביום טוב השני אסור ואם תאמר אם כן דלדבריהם קאמר להו אמאי קא מחליף השיטה לימא לדבריהם קאמר להו ולא מוחלפת השיטה כרבינא ויש לומר דזה נראה לו דוחק לומר לדבריהם קאמר להו כדלא מוקמינן מוחלפת כו' דהואיל ועדיין לא דברו חכמים כלל מתחילה קודם רבי יהודה לא שייך למימר לדבריהם ורבינא אינו חושש לזה:"]]],[["רבינא אמר לעולם לא תיפוך ורבי יהודה לדבריהם דרבנן קאמר להו","לדידי אפילו בראשון נמי שריא דאוכלא דאפרת הוא אלא לדידכו אודו לי מיהת דבשני שריא דשתי קדושות הן ואמרי ליה רבנן לא קדושה אחת היא","רבינא בריה דרב עולא אמר הכא בתרנגולת העומדת לגדל ביצים ורבי יהודה לטעמיה דאית ליה מוקצה","מיתיבי אחד ביצה שנולדה בשבת ואחד ביצה שנולדה ביום טוב אין מטלטלין אותה לא לכסות בה את הכלי ולא לסמוך בה כרעי המטה","אבל כופה עליה את הכלי בשביל שלא תשבר וספיקא אסורה ואם נתערבה באלף כולן אסורות","בשלמא לרבה דאמר משום הכנה הוי ספיקא דאורייתא וכל ספיקא דאורייתא לחומרא","אלא לרב יוסף ולרבי יצחק דאמרי משום גזרה ספיקא דרבנן היא וכל ספיקא דרבנן לקולא","(א\"ל) סיפא אתאן לספק טרפה","אי הכי אימא סיפא נתערבה באלף כולן אסורות אי אמרת בשלמא ספק יו\"ט ספק חול הוי דבר שיש לו מתירין וכל דבר שיש לו מתירין אפילו באלף לא בטיל","אלא אי אמרת ספק טרפה דבר שאין לו מתירין היא ותבטל ברובא","וכי תימא ביצה חשובה ולא בטלה הניחא למאן דאמר כל שדרכו לימנות שנינו","אלא למאן דאמר את שדרכו לימנות שנינו מאי איכא למימר","דתנן מי שהיו לו חבילי תלתן של כלאי הכרם ידלקו נתערבו באחרות ואחרות באחרות כולן ידלקו דברי רבי מאיר וחכמים אומרים יעלו באחת ומאתים","שהיה רבי מאיר אומר את שדרכו למנות מקדש וחכמים אומרים אינו מקדש אלא ששה דברים בלבד רבי עקיבא אומר שבעה ואלו הן אגוזי פרך ורמוני באדן וחביות סתומות וחלפי תרדין וקלחי כרוב ודלעת יונית רבי עקיבא מוסיף אף ככרות של בעל הבית","הראוי לערלה ערלה הראוי לכלאי הכרם כלאי הכרם ואתמר עלה רבי יוחנן אמר את שדרכו למנות שנינו ורבי שמעון בן לקיש אמר כל שדרכו למנות שנינו","הניחא לרבי שמעון בן לקיש אלא לרבי יוחנן מאי איכא למימר","אמר רב פפא האי תנא תנא דליטרא קציעות הוא דאמר כל דבר שבמנין אפילו בדרבנן לא בטיל וכל שכן בדאורייתא","דתנן ליטרא קציעות שדרסה על פי עגול ואינו יודע באיזה עגול דרסה על פי חבית ואינו יודע באיזו חבית דרסה על פי כורת ואינו יודע באיזו כורת דרסה רבי מאיר אומר רבי אליעזר"],[[0,"רבינא אמר","הא דקאמר ר' יוחנן מוחלפת השיטה לא תיפוך:"],[1,"אוכלא דאפרת הוא","וכיון דמשום סחיטה ליכא משום משקין שזבו נמי ליכא בעומדת לאכילה:"],[1,"לדידכו","דאסריתו לה אף בשני נהי נמי דאית לכו בביצה גזירת משקין שזבו ואפילו בתרנגולת העומדת לאכילה:"],[1,"אודו לי מיהת דבשני שריא","דחד מינייהו חול הוא:"],[1,"קדושה אחת היא","ולא דמו לשאר ימים טובים דהנך לאו משום ספקא אתקון דאף בזמן ב\"ד היו עושין אותם שני ימים אם באו עדים מן המנחה ולמעלה כדאמרינן בר\"ה (דף ל:):"],[2,"רבינא ברי' דרב עולא אמר","רבי יהודה אדר' יהודה מעיקרא לא תקשי דהא דקאמר בשני אין בראשון לא בעומדת לביצים קאמר ומשום מוקצה ולא משום משקין שזבו:"],[3,"מיתיבי","אהנך אמוראי קמאי דאפלוג בטעמא דבית הלל דמתני':"],[3,"לכסות בה את הכלי","פי צלוחית:"],[3,"לסמוך בה","זוקפה כנגד חודה וסומך בה:"],[4,"אבל כופה עליה כו'","ואע\"ג דהיא אינה ניטלת מטלטלין את הכלי לצורכה ולאפוקי מדר' יצחק דאמר (שבת דף מג.) אין כלי ניטל אלא לדבר הניטל בשבת ואיהו מוקי לה בצריך למקומו של כלי:"],[4,"וספקא","של זו אסורה קא סלקא דעתך ספק נולדה ביו\"ט ספק בחול אסורה ביו\"ט:"],[6,"ספק דרבנן היא","דאפי' ודאי משום גזירה הוא דאתסר וכי הויא לה ספיקא הוי ספק במידי דאסור מדרבנן:"],[7,"לספק טריפה","ספק נולדה מתרנגולת טרפה ולאו ביו\"ט קאי ואיידי דאיירי באיסור ביצה איירי נמי בהא:"],[8,"שיש לו מתירין","שיכול לאכלו אחר יו\"ט בהיתר גמור:"],[8,"אפילו באלף לא בטיל","ואע\"ג דמדאורייתא חד בתרי בטיל דכתיב (שמות כ״ג:ב׳) אחרי רבים להטות אחמור רבנן הואיל ויש לו מתירין לאחר זמן לא יאכלנו באיסור על ידי ביטול:"],[10,"הניחא למ\"ד","לקמן:"],[10,"כל שדרכו למנות שנינו","במשנת ערלה כדלקמן דלא בטיל משמע כל דבר שיש בני אדם המקפידין עליו מפני חשיבותו למוכרו במנין ביצה נמי הרבה מוכרין אותה במנין:"],[11,"אלא למאן דאמר את שדרכו","דמשמע את המיוחד לכך שאין אדם מוכרו באומד:"],[11,"מאי איכא למימר","הרי ביצה הרבה נמכרת באומד בלא מנין:"],[12,"תלתן","מין קטנית למתק קדירה פילוג\"ר בלע\"ז:"],[12,"ידלקו","כדין כלאי הכרם שנאמר (דברים כ״ב:ט׳) פן תוקדש תוקד אש דאסירי בהנאה:"],[12,"יעלו באחת ומאתים","אם נתערב אחד מהן במאתים של היתר יעלה אחד מהן וידלק והשאר מותרין וזה שיעור ביטול כלאים וערלה באחד ומאתים:"],[13,"שהיה ר' מאיר אומר","כלומר להכי אמר ר' מאיר כולן ידלקו ולית להו ביטול שהיה ר' מאיר אומר הואיל ודרכן לימנות אין בטלין ומקדשין לאסור כל המתערבין בהן:"],[13,"וחכמים אומרים","כל פירות שבעולם בטלים חוץ מששה דברים הללו המנויין כאן שהן חשובין מאד:"],[13,"פרך ובאדן","מקומות הן:"],[13,"קולחי","קלחי כרובין גדולים עם עלין שלהן וכרוב של א\"י היה גדול כאילן כדאמרינן בכתובות (דף קיא:):"],[14,"הראוי לערלה ערלה","אותן שהן מין אילן וערלה נוהגת בהן מקדשין את ערוביהן משום ערלה:"],[14,"והראוי לכלאי הכרם","כגון חלפי תרדין וקולחי כרוב וככרות שאינן מין אילן מקדשין ערוביהן באיסור כלאי הכרם:"],[14,"את שדרכו לימנות שנינו","במילתיה דר' מאיר:"],[15,"הניחא לר' שמעון בן לקיש","איכא לאוקמא לברייתא דלעיל דקתני ביצה לא בטלה כר' מאיר:"],[16,"האי תנא","דלעיל:"],[16,"תנא","דאיירי גבי ליטרא קציעות הוא דאמר כל דבר שיש בו מנין אפילו במידי דרבנן כגון ליטרא קציעות דאיירי בתרומת פירות דרבנן לא בטיל כדמפרש לקמיה:"],[16,"וכ\"ש","ביצה טרפה:"],[17,"ליטרא קציעות","תאנים שנתייבשו בשדה וקצען במקצוע והוא שם כלי העשוי לכך וחותכין בו עוקצי התאנים ואחר כך דורסים אותם בכלי עגול והן נדבקין יחד ונעשין כגבינה והוא נקרא עגולי דבילה וכשבאין למוכרן מפרידן במגריפה ומוכרן במשקל ליטרא:"],[17,"שדרסה ע\"פ כלי","ששמו עגול שבו עושין העגולין:"],[17,"ואינו יודע באיזה עגול","אבל יודע שעל פיו הוא ולא בתוכו:"],[17,"רבי מאיר אומר","כן נחלקו ר' אליעזר ור' יהושע בדבר זה ר' אליעזר אומר אף על פי שאין לטרות תחתונות בספק דמוע מצטרפות התחתונות אל הפומין של כל העגולין הללו:"]],[[1,"","לדידי אפי' בראשון נמי שריא ותימה ר' יהודה דאמר כבית שמאי וכי שביק ב\"ה ועביד כב\"ש וי\"ל דר' יהודה היה אומר לא נחלקו ב\"ש וב\"ה בדבר זה מעולם:"],[4,"","אבל כופה עליה כלי. פירש רש\"י דמהך ברייתא פריך התם לר' יצחק דאמר דאין כלי ניטל אלא לדבר הניטל והוא תירץ בצריך למקומו ומכאן פוסקין דהא דקי\"ל דדבר שמלאכתו לאיסור אסור אינו אלא דוקא שאינו לצורך גופו או לצורך מקומו אבל לצורך גופו או לצורך מקומו שרי ואם התחיל לטלטלו בשביל שצריך לגופו או למקומו מותר להוליכו אפילו בחדרו אם ירצה דהא חזינא הכא דהואיל וצריך למקומו או לגוף הכלי כופהו על הביצה:"],[12,"","ואחרות באחרות וכו'. תימה דאם כן אוסר ספק ספיקא ובהתערובות (זבחים דף עד. ושם) דקאמר מי איכא דאסר ספק ספיקא באסורי הנאה אמאי לא פשיט ליה מהכא דאסרינן אע\"ג דאיכא ספק ספיקא בשלמא ההיא דלעיל דאמר וספיקא אסורה נתערבה באלף כולן אסורות נוכל לפרש כדפירש ר\"ת נתערב' באלף אאיסור עצמו קאי א\"נ הא דלעיל ברייתא היא ומאי אולמא דהך ברייתא דהכא מהך ברייתא דהתם אבל (מברייתא קשיא למשנה) ע\"כ לא גריס ר\"ת ואחרות באחרות ורבינו יצחק ב\"ר ברוך אומר דגרס ליה שפיר וה\"פ שנתערב גם האיסור דסד\"א שמותר הואיל ואיכא כעין תרי רובי קא משמע לן ועוד תירץ הר\"ר יצחק דגרס ליה שפיר ואעפ\"כ לא מצי למיפשט מהכא דקים לן כל דבר שיש לו חשיבות אינו בטל אלא בתרי רובי לכך אינו בטל הכא אבל התם מוכיח ליה מתרי רובי דקאמר אם נתערב רובא בתוך רובא והתניא וכו' אבל הכא אין כאן תרי רובי שהתערובת הראשון היה שוה ובפרק הערל (יבמות דף פא. ושם בד\"ה נתערבו) פירשתי:"]]],[["אומר רואין את העליונות כאילו הן פרודות והתחתונות מעלות את העליונות","רבי יהושע אומר אם יש שם מאה פומין יעלו ואם לאו הפומין אסורין והשולים מותרין","רבי יהודה אומר רבי אליעזר אומר אם יש שם מאה פומין יעלו ואם לאו הפומין אסורין והשולים מותרין רבי יהושע אומר אפילו יש שם שלש מאות פומין לא יעלו","דרסה בעגול ואינו יודע באיזה עגול דרסה דברי הכל יעלו דברי הכל היינו פלוגתייהו","אמר רב פפא הכי קאמר דרסה בעגול ואינו יודע באיזה מקום עגול דרסה אי לצפונה אי לדרומה דברי הכל יעלו","רב אשי אמר לעולם ספק יום טוב ספק חול הוי דבר שיש לו מתירין וכל דבר שיש לו מתירין אפילו בדרבנן לא בטיל","תניא אחרים אומרים משום רבי אליעזר ביצה תאכל היא ואמה במאי עסקינן אילימא בתרנגולת העומדת לאכילה פשיטה דהיא ואמה שריא אלא בתרנגולת העומדת לגדל ביצים היא ואמה אסורה א\"ר זירא תאכל אגב אמה","היכי דמי אמר אביי כגון שלקחה סתם נשחטה הובררה דלאכילה עומדת לא נשחטה הובררה דלגדל ביצים עומדת","רב מרי אמר גוזמא קתני דתניא אחרים אומרים משום רבי אליעזר ביצה תאכל היא ואמה ואפרוח וקליפתו","מאי קליפתו אילימא קליפה ממש קליפה בת אכילה היא אלא אפרוח בקליפתו עד כאן לא פליגי רבנן עליה דרבי אליעזר בן יעקב אלא היכא דיצא לאויר העולם אבל היכא דלא יצא לאויר העולם לא פליגי","אלא אפרוח וקליפתו גוזמא הכא נמי תאכל היא ואמה גוזמא","אתמר שבת ויום טוב רב אמר נולדה בזה אסורה בזה ורבי יוחנן אמר נולדה בזה מותרת בזה נימא קסבר רב קדושה אחת היא","והאמר רב הלכה כארבעה זקנים ואליבא דרבי אליעזר דאמר שתי קדושות הן","אלא הכא בהכנה דרבה קמיפלגי רב אית ליה הכנה דרבה ורבי יוחנן לית ליה הכנה דרבה","כתנאי נולדה בשבת תאכל ביום טוב ביום טוב תאכל בשבת רבי יהודה אומר משום רבי אליעזר עדיין היא מחלוקת שבית שמאי אומרים תאכל ובית הלל אומרים לא תאכל","אושפיזכניה דרב אדא בר אהבה הוו ליה הנך ביצים מיו\"ט לשבת אתא לקמיה אמר ליה מאי לאטווינהו האידנא וניכלינהו למחר","א\"ל מאי דעתיך רב ורבי יוחנן הלכה כרבי יוחנן אפילו רבי יוחנן לא קא שרי אלא לגומעה למחר אבל ביומיה לא","והתניא אחת ביצה שנולדה בשבת ואחת ביצה שנולדה ביום טוב אין מטלטלין אותה לא לכסות בה את הכלי ולא לסמוך בה כרעי המטה","אושפיזכניה דרב פפא ואמרי לה ההוא גברא דאתא לקמיה דרב פפא הוו ליה הנך ביצים משבת ליום טוב אתא לקמיה אמר ליה מהו למכלינהו למחר אמר ליה זיל האידנא ותא למחר דרב לא מוקי אמורא עלויה מיומא טבא לחבריה משום שכרות","כי אתא למחר אמר ליה"],[[0,"רואין אותן כאילו הן פרודות","אם אין כאן מאה פומין של היתר שיהא בהן כדי להעלות פי האיסור באחד ומאה רואין כאילו ליטרות של כל הפומין פרודות מעל הפומין ומעורבות בשל שולים ונמצאו כולם בספק הדמוע ומצטרפות התחתונות להעלות את ליטרא שעל הפה דהואיל ותרומת פירות דרבנן מקילים בהעלאתם:"],[1,"ור' יהושע אומר אם יש שם מאה פומין","של היתר לבד פומין של אסור מעלין אותן באחד ומאה ואם לאו הפומין אסורין ואין השולים מועילין לבטל הפומין הואיל ואינן בספק הדמוע:"],[2,"רבי יהודה אומר","לא כן נחלקו ר' אליעזר ור' יהושע אלא כן נחלקו ר' אליעזר אומר כו':"],[2,"ר' יהושע אומר אפילו יש שם שלש מאות פומין","וכולן בכלל הספק אין מעלין את היחיד הואיל ופומי הכלי דבר שיש בו מנין הוא לא בטלי ואפילו בדרבנן אבל דרסה בעגול כו':"],[4,"הכי קאמר דרסה בתוך העגול","דעכשיו אינן נכרות שהרי מדובקות ואינו יודע היכן היא אם בצפונו של עגול או בדרומו הואיל והשתא לאו בת מנין היא ולא מנכרא דברי הכל יעלו ותנא דלעיל ר' יהודה ואליבא דרבי יהושע היא:"],[5,"רב אשי אמר לעולם","הא דקתני וספקה אסור ספק יום טוב ספק חול קאמר ודקשיא לך לרב יוסף ולרבי יצחק ספק דרבנן הוא ולקולא הכא אזלינן לחומרא הואיל ויש לו מתירין למחר:"],[5,"אפילו בדרבנן","כגון ביצה דגזרת פירות הנושרין היא לא בטלה בתערובתה וכי היכי דבבטולה מחמרינן מהאי טעמא בספקה נמי מחמרינן מהאי טעמא:"],[6,"ביצה תאכל","אם נולדה ביום טוב:"],[6,"פשיטא דהיא ואמה שריא","כלומר אם בא לומר כבית שמאי לשמעינן ביצה אמה למה לי פשיטא דשריא:"],[6,"היא ואמה אסורה","דשמעינן לר' אליעזר דאית ליה מוקצה דתנן בפרק המביא (לקמן ביצה דף לד.) ר' אליעזר אומר עומד אדם על המוקצה כו' אלמא הכנה בעי:"],[6,"אגב אמה","אם אוכלין את אמה היום תאכל אף היא:"],[7,"שלקחה סתם","תרנגולת זו קנאה סתם:"],[8,"גוזמא קתני","כאדם שרוצה להחזיק דבריו מדבר יתר ובעומדת לאכילה קאמר ונחלק על בית הלל האוסרים ואמה לא איצטריכא ליה אלא גזים ואמר מילתא יתירא הכל יאכל גם את האב גם את האם:"],[9,"דר' אליעזר בן יעקב","אוסר אפרוחים שלא נפתחו עיניהם ופליגי רבנן עליה ולקמן מייתי לה בגמרא:"],[10,"גוזמא","אע\"פ דלא אפשר גזים ואמר מילתא דטופיינא גוזמא דבר שנוי שאינו מתקבל:"],[11,"שבת ויום טוב","הסמוכין והוא הדין ליום טוב ושבת:"],[11,"קדושה אחת היא","הרי הן כיום אחד ארוך:"],[12,"ארבעה זקנים אליבא דר' אליעזר","בערובין בפ' בכל מערבין (עירובין דף לח:):"],[12,"דאמר שתי קדושות הן","ומערב ליום א' למזרח ולשני למערב:"],[13,"הכנה דרבה","דאמר הכנה בידי שמים מתסרא מיום טוב לשבת דסעודת שבת בעיא הזמנה מיום חול מגזרת הכתוב:"],[14,"עדיין היא מחלוקת","ב\"ש וב\"ה בזה כשם שנחלקו לבו ביום:"],[15,"אושפיזכניה","בעל הבית:"],[15,"מיו\"ט לשבת","היום נולדו והיה רוצה לאכלן למחר בשבת:"],[15,"לאטווינהו","לצלותן האידנא מי אסירי בטלטול בו ביום או לא:"],[16,"מאי דעתיך","דפשיטא לך דלמחר מיהא שרו משום דקיימא לן רב ור' יוחנן הלכה כר' יוחנן מיהו בטלטול האידנא אסירי דאפילו ר' יוחנן לא שרי לצלותה היום אלא לגומעה למחר אם היה יו\"ט קודם לשבת אבל ביומיה לא ואפילו בטלטול:"],[17,"והתניא","סייעתא:"],[18,"דרב לא מוקי אמורא עלויה","לא היה מעמיד מתורגמן לפניו לדרוש דרשה לרבים:"],[18,"מיומא טבא לחבריה","כלומר משעשה היום יום טוב דהיינו לאחר סעודה עד מחר:"],[18,"משום שכרות","דרב אורויי היה מורי בדרשה שלו כדאמרינן בכריתות ושכור אסור להורות דכתיב יין ושכר אל תשת (ויקרא י׳:ט׳) וכתיב להורות את בני ישראל (שם):"]],[[11,"","נימא קסבר רב קדושה אחת הן. תימה לימא דקסבר שתי קדושות הן אלא הטעם הוי מגו דאתקצאי לבין השמשות דשמא יום שבת הוא אתקצאי לכולי יומא דיום שני וי\"ל דלא אמרינן מגו משום יום שהוא לשעבר דדוקא להבא אמרינן הכי כגון בין השמשות דתחילת יום טוב או בין השמשות דשבת שמא שבת הוא ותימה דהא בסוכה (דף י.) אמרינן נויי סוכה אסורין עד מוצאי יום טוב האחרון של חג שהוא יום תשיעי שהוא ספק יום שמיני ועל כרחיך טעמא משום דאתקצאי בין השמשות דשמא יום שמיני הוא והיינו לשעבר וי\"ל דמוקצה מחמת מצוה שאני כדמפרש טעמא התם דילמא מתרמיא ליה סעודה ואכיל בגוה והתם אמרינן אפילו לשעבר אבל הכא מוקצה דמחמת אסור לא אמרינן הכי:"],[13,"","אלא בהכנה דרבה קמפלגי. ותימה דהא אמרינן כל היכא דמתילדא האידנא מאתמול גמרה לה ואם כן כשחל יום טוב לאחר השבת והביצה נולדה בשבת היא נגמרת ביום שהוא חול ואם כן מאי הכנה איכא וי\"ל דמכל מקום כשנולדה בשבת הרי זו הכנה דגם בשעת לידה שייך הכנה ועוד יש לומר דכיון דאם נולדה ביו\"ט הרי זו אסורה אם נאמר כשנולדה בשבת הרי היא מותרת בשביל אותה לידה דשבת אם כן הוי שבת מכין ליום טוב:"],[14,"","רבי יהודה אומר משום ר' אליעזר עדיין היא מחלוקת. ואע\"ג דפירשתי לעיל דר' יהודה סבירא ליה דלא נחלקו ב\"ש וב\"ה בדבר זה מ\"מ לא קשיא מהכא דהא דידיה והא דרביה:"]]],[["איכו השתא אשתלאי ואמרי לך רב ורבי יוחנן הלכה כרבי יוחנן הא אמר רבא הלכתא כותיה דרב בהני תלת בין לקולא בין לחומרא","אמר רבי יוחנן עצים שנשרו מן הדקל בשבת אסור להסיקן ביום טוב ואל תשיבני ביצה מאי טעמא ביצה משום דביומא נמי חזיא לגומעה ולא קא שרי לה עד למחר מידע ידיע דבת יומא אסורה עצים דלא חזו ליומייהו אי שרי להו למחר אתי למימר ביומייהו נמי שרו ואתמול משום שבת הוא דלא חזו להסקה","אמר רב מתנה עצים שנשרו מן הדקל לתוך התנור ביום טוב מרבה עליהם עצים מוכנים ומסיקן והא קא מהפך באיסורא כיון דרובא דהיתרא נינהו כי קא מהפך בהיתרא קא מהפך","והא קא מבטל איסורא לכתחלה ותנן אין מבטלין איסור לכתחלה הני מילי בדאורייתא אבל בדרבנן מבטלין","ולרב אשי דאמר כל דבר שיש לו מתירין אפילו בדרבנן לא בטיל מאי איכא למימר הני מילי היכא דאיתיה לאיסורא בעיניה הכא מקלא קלי איסורא","אתמר שני ימים טובים של גליות רב אמר נולדה בזה מותרת בזה ורב אסי אמר נולדה בזה אסורה בזה","לימא קא סבר רב אסי קדושה אחת היא והא רב אסי מבדיל מיומא טבא לחבריה","רב אסי ספוקי מספקא ליה ועביד הכא לחומרא והכא לחומרא","אמר ר' זירא כותיה דרב אסי מסתברא דהאידנא ידעינן בקביעא דירחא וקא עבדינן תרי יומי","אמר אביי כותיה דרב מסתברא דתנן בראשונה היו משיאין משואות משקלקלו הכותים התקינו שיהו שלוחין יוצאין","ואילו בטלו כותים עבדינן חד יומא והיכא דמטו שלוחין עבדינן חד יומא","והשתא דידעינן בקביעא דירחא מאי טעמא עבדינן תרי יומי משום דשלחו מתם הזהרו במנהג אבותיכם בידיכם זמנין דגזרו המלכות גזרה ואתי לאקלקולי","אתמר שני ימים טובים של ראש השנה רב ושמואל דאמרי תרוייהו נולדה בזה אסורה בזה דתנן בראשונה היו מקבלין עדות החדש כל היום (כולו) פעם אחת נשתהו העדים לבא"],[[0,"איכו השתא","אם הוריתי לך אתמול בשכרותי:"],[0,"אשתלאי","שכחתי ושגגתי והייתי מורה בו היתר משום דקיימא לן בשאר דוכתי רב ור' יוחנן הלכה כר' יוחנן עכשיו יפה דחיתיך עד היום ונזכרתי:"],[0,"הא אמר רבא","לקמן (ביצה דף ה.):"],[0,"הלכתא כותיה דרב בהני תלת","שאמר לענין ביצה זו משבת ויום טוב ולקמיה בשני ימים טובים של גליות נחלק להקל והשלישי בשני ימים טובים של ראש השנה נחלק להחמיר:"],[1,"מן הדקל","שנשבר בשבת:"],[1,"אסור להסיקן ביום טוב","הסמוך לו:"],[1,"ואל תשיבני ביצה","שאמרתי בה נולדה בזה מותרת בזה דהכא שייך למיסר טפי:"],[1,"ומאי טעמא ביצה כיון דביומא","אי לאו דאסירא משום דנולדה בשבת הוה חזיא לגומעה חיה שיש בני אדם גומעין כן:"],[1,"ולא שרי ליה (מר) עד למחר מידע ידיע","כי שרית ליה למחר ואתמול לא שרית דבת יומא אסירא אבל עצים דשבת כיון דביומייהו בלאו איסור מוקצה נמי לא חזו שאין מבערין אש בשבת:"],[1,"אי שרי להו (מר) למחר אתי למימר","אם נפלו בו ביום נמי שרו ואתמול שלא בערנום משום דשבת לא חזי להסקה:"],[2,"והא קא מהפך באיסורא","כשמוליכן בתנור מזוית לזוית:"],[2,"בהיתרא מהפך","שהאיסור בטל ברוב:"],[3,"והא קמבטל איסור בידים","ותנן אין מבטלין איסור לכתחלה דאע\"ג דאיסורא בטיל ברובא הני מילי היכא דאיערב ממילא אבל לאערובי ולבטולי בידים אסור דהכי תנן במס' תרומות (פ\"ה מ\"ט) סאה תרומה שנפלה לתוך תשעים ותשעה וחזרה ונפלה סאה של חולין אם שוגג מותר ואם מזיד הפילה לאותה סאה אחרונה כדי להשלים מאה חולין להעלות את התרומה אסור:"],[3,"","בדאורייתא- כגון תרומה:"],[3,"","אבל בדרבנן- כגון מוקצה דהכא:"],[5,"","של גליות- שאין עושין אותו אלא בני גליות הרחוקים מבית דין ואין השלוחין יכולין להגיע אצלם מראש חדש עד יו\"ט להודיעם באיזה יום נקבע החודש אם ביום שלשים אם ביום שלשים ואחד ועושין ב' ימים יו\"ט מספק ומדאורייתא ביום הראשון שבתון וביום השביעי שבתון ותו לא:"],[5,"","מותרת בזה- דחד מינייהו חול הוא וממה נפשך שריא:"],[5,"","אסורה בזה. כדמפרש ואזיל:"],[6,"","לימא קסבר רב אסי קדושה אחת היא. חכמים קבעום על בני גולה לעשותם לדורות מחמת ספק זה והטילום עליהם כחומר יום ארוך:"],[6,"","והא רב אסי מבדיל- ומברך המבדיל בין קדש לחול דקסבר קים לן בקביעא דירחא ויו\"ט שני חול גמור הוא משום מנהג אבותינו שלא ידעו בקביעת החדש כמונו ועשאום מספק מאליהן אנחנו עושין אותם:"],[7,"","ספוקי מספקא ליה- אם חק חכמים הוא שהוטל על הגליות לדורות ואפילו ירבו בהם חכמים יודעי העתים יהיו עושין אותן שנים א\"כ הרי הוא מדברי סופרים כיום ארוך או אם הן עשאום מאליהן מספק וחד מנייהו חול ולמאן דקים ליה בקביעא דירחא בעי אבדולי:"],[8,"","כותיה דרב אסי מסתברא- דאסיר:"],[8,"","קים לן בקביעא דירחא. על ידי חשבון שמחשבין תולדתו אנו למדים אם נראה ביום שלשים אם לאו:"],[8,"ועבדינן תרי יומי","אלמא חק קבוע הוא מתקנת חכמים על ישראל הרחוקים לעשותן ואפילו בלא ספק הלכך כחד יומא אריכא שוינהו:"],[9,"כותיה דרב מסתברא","שאינו חק אלא מדאגת הספק החמירום עליהם הגליות:"],[9,"","בראשונה- קודם שקלקלו הכותים והשיאו הם משואות ביום שלא קבעו בו החודש כדי להטעות את ישראל:"],[9,"","משיאין משואות- כמו להעלותם משאת העשן מן העיר (שופטים כ) (סימן) תבערה ובראש השנה מפרש להו ובהן היו יודעין כל בני הגליות הקרובים והרחוקים את קביעת החודש ולא היו עושין אלא יו\"ט אחד בכל מקום:"],[9,"שיהו שלוחים יוצאים","ועד מקום שיכול להגיע בתוך חמשה עשר ימים הם מודיעים ועושין יום אחד והשאר עושין שני ימים:"],[10,"ואילו בטלו הכותים","הדרינן ועבדינן משואות בראש ההרים וידעו הכל:"],[10,"ועבדי חד יומא","בכל דוכתא והאידנא נמי היכא דמטו שלוחין קודם יו\"ט עבדי חד יומא שמע מינה לא קבעום עליהם בתקנה לדורות:"],[11,"דגזרי המלכות גזרה","שלא יתעסקו בתורה וישתכח סוד העיבור מכם ותעבדו נמי חד יומא ואתי לקלקולי ולעשות חסר מלא ומלא חסר ותאכלו חמץ בפסח:"],[12,"אסורה בזה","שהם ודאי חוק קבוע להיות כיום ארוך מדרבנן שמתחילה לא מחמת ספק התחילו לעשותן:"],[12,"כל היום","יום שלשים של אלול ומבערב היו אסורין במלאכה שמא יתקדש החודש למחר ונמצא שהלילה הזה יו\"ט שכן כל היום מצפין לעדות רואי הלבנה אולי יבואו וכל שעה שבאין עד שתחשך היו מקבלין עדותן ומקדשין החודש בו ביום:"]],[[3,"","ותנן אין מבטלין איסור לכתחילה ואע\"ג דמדאורייתא חד בתרי . בטיל היינו היכא דמיערב ממילא אבל למערבינהו בידים לבטולי אסור דהכי תנן במס' תרומות (פ\"ה מ\"ט) סאה של תרומה שנפלה לתוך תשעים ותשעה של חולין וחזרה ונפלה לתוכן סאה של חולין ורבה עליהן בשוגג מותר במזיד אסור דאין מבטלין איסור לכתחילה ומשני הני מילי בדאורייתא אבל בדרבנן מבטלין ומש\"ה הפילה אסור דאין מבטלין איסור לכתחילה אבל הכא לא אמרינן הכי דשפיר . מבטלין לכתחילה ואם תאמר לעיל (ביצה ג:) גבי עגול דהוי תרומה דרבנן יוסיף עליו ויבטל וי\"ל דהא דאמר בדרבנן מבטלין היינו בדבר שעיקרו מדרבנן כגון מוקצה דעיקרו אינו אלא מדרבנן אבל בדבר שעיקרו מדאורייתא כגון תרומה דאיכא שום דבר דאורייתא כגון דגן תירוש ויצהר אפילו במקום שאינו אלא מדרבנן כגון בשאר פירות אין מבטלין וכן משמע פ' גיד הנשה (חולין צח.) גבי ההיא פלגא דזיתא דתרבא דנפל בדקולא סבר מר בר רב אשי לשערינהו בתלתין פלגי . דזיתא א\"ל אבוה אל תזלזל בשיעורי כו' ואין מבטלין ואמאי לא הוסיף עליהן עד [ששים] כדי לבטל אותם אלא שמע מינה כיון דעיקר איסורו דאורייתא כגון היכא דאיכא כזית הכי נמי דליכא כזית וליכא אלא איסור דרבנן אין מבטלין:"]]],[["ונתקלקלו הלוים בשיר התקינו שלא יהו מקבלים את העדים אלא עד המנחה","ואם באו עדים מן המנחה ולמעלה נוהגין אותו היום קדש ולמחר קדש","אמר רבה מתקנת רבן יוחנן בן זכאי ואילך ביצה מותרת דתנן משחרב בית המקדש התקין רבן יוחנן בן זכאי שיהו מקבלין עדות החדש כל היום","א\"ל אביי והא רב ושמואל דאמרי תרוייהו ביצה אסורה א\"ל אמינא לך אנא רבן יוחנן בן זכאי ואת אמרת לי רב ושמואל","ולרב ושמואל קשיא מתניתין לא קשיא הא לן והא להו","ורב יוסף אמר אף מתקנת רבן יוחנן בן זכאי ואילך ביצה אסורה מ\"ט הוי דבר שבמנין וכל דבר שבמנין צריך מנין אחר להתירו","אמר רב יוסף מנא אמינא לה דכתיב (דברים ה, ל) לך אמור להם שובו לכם לאהליכם ואומר (שמות יט, יג) במשוך היובל המה יעלו בהר","(ותניא) כרם רבעי היה עולה לירושלים מהלך יום אחד לכל צד וזו היא תחומה (עלת) מן (הצפון) ועקרבת מן (הדרום) לוד מן המערב וירדן מן המזרח","ואמר עולא ואיתימא רבה בר בר חנה א\"ר יוחנן מה טעם כדי לעטר שוקי ירושלים בפירות","ותניא כרם רבעי היה לו לר' אליעזר במזרח לוד בצד כפר טבי"],[[0,"ונתקלקלו הלוים בשיר","תמיד של בין הערבים שאמרו בו שירה של חול שהיו סבורים שלא יבאו עוד והיום חול וכשבאו נמצא שהוא קדש ובשל שחר אין טעות דבתמיד של שחר אפילו הוקדש החדש קודם הקרבתו שיר של חול היו אומרים לפי שברוב השנים אין העדים ממהרים לבא כל כך:"],[0,"עד המנחה","עד הקרבת תמיד של בין הערבים אבל לאחר מכאן אותו היום הרי הוא מעובר ומונין מיום המחרת ליום הכפורים וסוכות ואם באו עדים מן המנחה ולמעלה אע\"פ שאין מונין למועדות מהיום לא מזלזלינן ביה בהאי שלשים אלא גומרין אותו באיסורו כאשר הוזהרו עד המנחה ממלאכה כן נוהגין וגומרין אותו בקדושתו אלמא תחילת עשייה שני ימים לראש השנה אפילו בבית דין הוה ולא מספק שהרי ודאי שיום טוב למחר ואעפ\"כ תקנו לעשותו שמע מינה חק חכמים ומצותן היה לעשותן בבאו עדים אחר המנחה והרחוקים יש עליהם לעשותן בכל שנה שמא יבאו עדים אחר המנחה והרי קדושתו אחת ואין כאן לומר ממה נפשך חד מינייהו חול דשמא אין כאן חול אלא שניהם קדש:"],[2,"אמר רבה","גר':"],[2,"מתקנת רבן יוחנן בן זכאי","שהחזיר הדבר ליושנו לקבל עדותן כל היום ולקדש היום נמצא שאין בית דין עושין שני ימים והרחוקים העושים שני ימים אינו אלא מספק שאין יודעין אם נתקדש ביום שלשים אם בשלשים ואחד והרי הן כשאר י\"ט של גליות וביצה שנולדה בזה מותרת בזה ממה נפשך דחד מינייהו חול:"],[4,"","ולרב ושמואל קשיא מתניתין. דקתני דחזר הדבר ליושנו:"],[4,"הא לן והא להו","לבני א\"י שעושין יום אחד מותרת אבל לדידן בני גולה אסורה שהרי עדיין אנו עושין שני ימים ועודנו כבתחילה מפני אותה תקנה ראשונה לא מפני ספק הלכך הואיל ולא פסקו מאצלנו משהתחלנו אין להקל ולומר אין מנהגנו זה מפני תקנה ראשונה אלא מפני הספק וביצה מותרת הא לא אמרינן דכיון דלא פסקה אותה תקנה מאצלנו שנה אחת לעשות יום אחד עדיין באיסורנו הראשונה עמדנו להיותם כיום ארוך:"],[5,"הוי דבר שבמנין","ביצה זו נאסרת בקבוץ חכמים שנמנו וגמרו לעשותן שני ימים קדושה אחת אם לא באו עדים לפני המנחה וכל העושין שני ימים מחמת כן עשו שמא לא באו עדים לבית דין קודם המנחה:"],[5,"צריך מנין אחר","שימנו לך ויתירוהו ולקמן פרכינן ביצה מי אתסרא במנין והלא לא נמנו אלא על קבלת עדות ובההוא חזר בו רבן יוחנן והתירו:"],[6,"מנא אמינא לה","דכל דבר הנאסר במנין צריך מנין אחר להתירו ואפילו אירע דבר שאתה יכול להורות בו היתר ולומר אין תקנת מנין הראשון עומדת כי הכא אפילו הכי אסור עד שיתירוהו בפירוש בקבוץ חכמים:"],[6,"לך אמור להם","לקמן מפרש לה היכי יליף:"],[6,"ואומר במשוך היובל","לקמן מפרש:"],[7,"ותניא","נמי דצריך מנין אחר להתירו:"],[7,"כרם רבעי","שאמרה תורה קדש הלולים (ויקרא י״ט:כ״ד) וגמרינן קדש קדש ממעשר שני דכתיב ביה קדש וכל מעשר הארץ מזרע הארץ מפרי העץ וגו' (שם כז) שצריך להעלות הפירות לירושלים או לפדותן ולהעלות הדמים לירושלים ותקנו חכמים במהלך יום אחד לכל צד שלא יפדוהו אלא הפירות עצמן יעלם ויאכלם שם כדמפרש לקמן כדי לעטר שוקי ירושלים בפירות:"],[9,"במזרח לוד","היינו בין לוד לירושלים בתוך מהלך יום דהא אמרינן לוד בתוך מהלך יום מן המערב נמצא מזרחה בין לוד לירושלים בכיצד מברכין (ברכות דף לה.) יש פלוגתא חד תני נטע רבעי וחד תני כרם רבעי:"]],[[0,"","ונתקלקלו הלוים בשיר. בשיר של בין הערבים מיירי שאמרו שיר של חול שלא היו סבורים שיבאו עדים אותו יום ונהגו אותו יום חול וכשבאו לאחר המנחה נמצא שהוא קדש אבל אינו אומר בשיר של שחרית שאמרו של חול בתמיד של שחרית שהרי אפילו באו קודם הקרבת תמיד של שחרית היו אומרים שיר של חול כדאמרינן בר\"ה (דף ל: ושם) לפי שרוב השנים לא היו ממהרין כל כך לבא והקשה ר' פרץ והאיכא קלקול גבי מוספין ואמאי לא חשו אלא על עבודת התמיד דכשבאו עדים מן המנחה ולמעלה כבר הקריבו התמיד וא\"כ אינן יכולין להקריב המוספין דכתיב והקטיר עליה חלבי השלמים ודרשינן (יומא דף לג.) עליה השלם כל הקרבנות כולן שאין קרבן קרב לאחריה ותירץ דאפילו לא באו עד לאחר הקרבת התמיד מכל מקום המוספין קרבין דהיכא דלא אפשר שאני מידי דהוי אמחוסר כפורים בע\"פ שמביא כפרתו לאחר הקרבת התמיד של בין הערבים ואוכל פסחו בערב והכי אמרינן בפ' תמיד נשחט (פסחים נט. ושם) ועוד י\"ל דאתי עשה דרבים ודחי עשה דהשלמה משום דאלים טפי דהכי אמרינן בתמיד נשחט (ג\"ז שם) דאתי עשה דפסח דענוש כרת ודחי עשה דהשלמה דאינו ענוש כרת ויש מפרשי' דמעיקרא אייתו התמיד ומתנו אם לא יבאו עדים יהא תמיד ואם יבאו יהא מן המוספין ואח\"כ יביאו את התמיד ושאר קרבנות ולא נהירא דאיכא בהדיא התם דאמרו שיר של חול עם תמיד של בין הערבים:"],[4,"","הא לן והא להו. פי' בקונטרס בני א\"י שמקדשין החדש על פי הראייה ואין עושין אלא יום אחד ופעמים עושין שנים כשבאו עדים מן המנחה ולמעלה ואשתני בשביל תקנת רבן יוחנן בן זכאי ואין עושין אלא יום אחד אף כשבאו עדים מן המנחה ולמעלה ואפילו כשהיו עושין שני ימים כגון שלא באו עדים הרי הוא מחמת ספק והרי הן שתי קדושות לפי שאין זה מחמת המנהג לפיכך היתה מותרת להן אבל לבני חוצה לארץ אסור שהרי עדיין הם עושין שני ימים כבתחילה ואם כן לא אשתני להן מפני התקנה הואיל והתחילו לעשות שני ימים ולא פסקו בשום פעם לעשות יום אחד עדיין הם עומדים באיסורן להיותן כיום ארוך דלא נימא דמחמת ספק הן עושין דאין יודעין אם באו עדים אם לאו אלא מחמת המנהג הן עושין כיון דלא נשתנה להן המנהג וא\"ת לר' יוסי דאמר בעירובין (דף לט. ושם) גבי שני ימים של ר\"ה נולדה בראשון אסורה בשני והא ר' יוסי בא\"י הוה לאחר חורבן וא\"כ שתי קדושות הן ואמאי ביצה אסורה ואין לומר דהיינו קודם חורבן דהוו קדושה אחת דא\"כ מאי נפקא מינה מאי דהוה הוה וכי תימא דהיינו לאחר חורבן והא דביצה אסורה היינו לבני בבל דלדידהו קדושה אחת הן זה אינו דר' יוסי מא\"י ונקט מילתא בשביל בבל וי\"ל דלעולם ר' יוסי מקודם חורבן קאמר ואין להקשות מאי דהוה הוה הואיל ואשמועינן פסק דגם עתה שייך לאחר חורבן לבני בבל:"],[5,"","כל דבר שבמנין צריך מנין אחר להתירו. יש שהיו רוצין לומר מכאן דאותן חרמות שעושין לזמן עד פסח או עד זמן אחר דכי יגיע הזמן צריך מנין להתיר את החרם אע\"פ שעבר הזמן דהא הרי הכא דהקב\"ה אסר להם תשמיש בשביל מתן תורה וממילא ידעינן דלאחר שלשה ימים דנתנה תורה דמותרין ואעפ\"כ התיר להם ולא היא דהכא אין כאן שום זמן דקרא דהיו נכונים לשלשת ימים וגו' (שמות י״ט:ט״ו) הזמינו עצמכם לדבר שיהיה לסוף שלשת ימים דאם כתיב היו נכונים שלשת ימים בלא למ\"ד של לשלשת ימים הייתי מוכיח שפיר דכי היכי דצריך להתיר תשמיש צריך נמי להתיר החרם ומדלא כתיב הכי שמע מינה גבי תשמיש צריך להתיר משום דכתיב אל תגשו אל אשה וגו' דמשמע עולמית כי היכי דאסר להם קודם מתן תורה שלשת ימים אבל חרמות שמשימין לזמן מכי עבר הזמן ממילא עבר ואין צריך היתר: [ועי' תוספות סנהדרין נט: ד\"ה לכל דבר]:"]]],[["ובקש להפקירו לעניים אמרו לו תלמידיו רבי כבר נמנו עליך חבריך והתירוהו מאן חבריך רבן יוחנן בן זכאי","טעמא דנמנו הא לא נמנו לא","מאי ואומר ה\"ק מכדי כתיב (שמות יט, טו) היו נכונים לשלשת ימים אל תגשו אל אשה (דברים ה, ל) לך אמור להם שובו לכם לאהליכם למה לי שמע מינה כל דבר שבמנין צריך מנין אחר להתירו","וכי תימא למצות עונה הוא דאתא ת\"ש (שמות יט, יג) במשוך היובל המה יעלו בהר","מכדי כתיב (שמות לד, ג) גם הצאן והבקר אל ירעו אל מול ההר ההוא במשוך היובל למה לי שמע מינה דבר שבמנין צריך מנין אחר להתירו","וכי תימא הני מילי בדאורייתא אבל בדרבנן לא ת\"ש כרם רבעי והא כרם רבעי דרבנן וקאמרי ליה כבר נמנו עליך חבריך והתירוהו","וכי תימא ביצה נמי אמנו עלה רבן יוחנן בן זכאי ושריוה כי אמנו אעדות אביצה לא אמנו","א\"ל אביי אטו ביצה במנין מי הואי ביצה בעדות תליא מלתא אתסר עדות אתסר ביצה אשתרי עדות אשתרי ביצה","רב אדא ורב שלמן תרוייהו מבי כלוחית אמרי אף מתקנת רבן יוחנן בן זכאי ואילך ביצה אסורה מ\"ט מהרה יבנה בית המקדש ויאמרו אשתקד מי לא אכלנו ביצה ביום טוב שני השתא נמי ניכול ולא ידעי דאשתקד שתי קדושות הן והשתא קדושה אחת היא","אי הכי עדות נמי לא נקבל מ\"ט מהרה יבנה בית המקדש ויאמרו אשתקד מי לא קבלנו עדות החדש כל היום כולו השתא נמי נקבל","הכי השתא התם עדות מסורה לב\"ד ביצה לכל מסורה","רבא אמר אף מתקנת רבן יוחנן בן זכאי ואילך ביצה אסורה מי לא מודה רבן יוחנן בן זכאי שאם באו עדים מן המנחה ולמעלה שנוהגין אותו היום קדש ולמחר קדש","ואמר רבא הלכתא כותיה דרב בהני תלת בין לקולא בין לחומרא"],[[0,"להפקירו לעניים","שילקטוהו הם ויעלוהו לירושלים ויאכלוהו שם שהיה עליו טורח להעלות שם הפירות:"],[0,"כבר נמנו עליך חבריך והתירוהו","לפדותו ולהעלות דמיו ואע\"ג דלאחר חורבן הוה קסברי קדושה ראשונה קדשה לשעתה וקדשה לעתיד לבא וצריך להעלות הפירות או הדמים:"],[1,"טעמא דנמנו הא לא נמנו לא","ואע\"ג דממילא ליתא לתקנתא קמייתא דהא כדי לעטר שוקי ירושלים הוא דהוה וכיון דחרבה מה לנו לעטרה לצורך הנכרים ואפילו הכי צריך מנין:"],[2,"מאי ואומר","כלומר כיצד אנו למדין מן המקרא הראשון ולמה נאמרו שנים:"],[2,"ה\"ק","כך למד מן הראשון מכדי כתיב היו נכונים לשלשת ימים אל תגשו אל אשה וממילא אישתרו בתשמיש לאחר שלשה ימים שקבלו את התורה למה ליה למהדר ולמיתן להו רשות לשוב לאהליהם דהיינו תשמיש:"],[2,"ש\"מ","הואיל וקודשא בריך הוא אסר בעי למשרייה הוא גופיה בהדיא וה\"ה לכל דבר שבמנין:"],[3,"וכי תימא","כלומר וקרא דבמשוך היובל דיליף תנא מיניה להכי הדר ביה ויליף מהתם דהכי קאמר לך וכי תימא דהאי שובו לכם לאו למשרי תשמיש דהא ממילא משתרי אלא לצוותן לשוב במצות המלך על כרחן שלא לגרוע עונת נשותיהן:"],[3,"ת\"ש","מהכא במשוך היובל שימשוך בהסתלק שכינה מן ההר ויאריך התוקע את קולו כמנהג התוקע באחרונה לשון אחר במשוך היובל שימשוך התוקע מלתקוע והכי מפרש לה במכילתא במשוך היובל בפסוק היובל:"],[4,"מכדי כתיב","בלוחות האחרונות ואיש לא יעלה עמך וגו' (שמות לד) מסיפיה דקרא יליף אל מול ההר ההוא כל זמן שהוא בהויית קדושתו שהשכינה עליו אסור אבל נסתלק שכינה מותר שמעינן ממילא למה ליה לאדכורי שריותא בהדיא בלוחות הראשונות ולמימר נסתלקה שכינה המה יעלו והלא לא נסתלקה שכינה ממנו מיום מתן תורה עד אחד בחדש שהוקם המשכן ועד בעשרים באייר שנעלה הענן והיה לו ללמוד היתר כשמסתלק מאל מול ההר ההוא ובמסכת תענית (דף כא:) נמי מההוא קרא ילפינן דתניא רבי יוסי אומר לא מקומו של אדם מכבדו אלא הוא מכבד מקומו שכל זמן שהשכינה היתה בהר אמרה תורה גם הצאן והבקר אל ירעו וגו' נסתלקה שכינה אמרה תורה במשוך היובל המה יעלו בהר הלכך למה ליה לכתוב בהדיא המה יעלו ולא אישתרי ממילא מדוקיא דההר ההוא ש\"מ צריך מנין אחר להתירו כו':"],[5,"הני מילי בדאורייתא","באיסור שיצא מפי הגבורה הוצרכנו לשמוע היתר מפיו אבל במנין דרבנן לא בעינן שריותא בהדיא אלא מכללא:"],[5,"ת\"ש כרם רבעי","דהא דהוצרך להעלות פירות עצמן במהלך יום דרבנן הוא וקא בעי מנין ואע\"ג דאיכא למשרייה מכלל:"],[6,"וכ\"ת ביצה נמי וכו'","השתא הדר רב יוסף לאסוקי מלתא דאמר אף מתקנת רבן יוחנן בן זכאי ואילך ביצה אסורה:"],[7,"ביצה במנין מי הואי","כלום הוזכרה במנין הראשון לאוסרה:"],[8,"מהרה יבנה בית המקדש","ותחזור תקנה ראשונה שלא לקבל עדות אלא עד המנחה:"],[10,"מסורה לב\"ד","אין נזקקין להם אלא ב\"ד והם יודעין טעמו של דבר ולא יטעו:"],[10,"לכל מסורה","ליד הכל היא באה ואין הכל באין לישאל וסומכין על מנהגן:"],[11,"מי לא מודה כו'","אע\"ג דתקן לקבל עדות החדש כל היום להיות מונין למועדות מן הראשון ואפילו באו עדים לאחר המנחה אבל מלעשות י\"ט שני לא נעקרה תקנה ראשונה ממקומה:"]],[[0,"","ובקש ר' אליעזר להפקירו לעניים. וא\"ת אי קסבר קדושה ראשונה קדשה לשעתה ולא קדשה לעתיד לבא א\"כ מה הרויחו עניים בזה הא היו צריכין לפדותו קודם אכילה שהרי לא היה חומה לירושלים ולא היו יכולין לאכלו בשום מקום רק לפדותו קודם אכילה וי\"ל לפרש\"י ניחא דפי' קדושה ראשונה אליבא דרבי אליעזר קדשה לעתיד לבא א\"כ יכולין העניים להביא פירות לירושלים ולאכלן שם בלא פדייה אי נמי אפילו ס\"ל לא קדשה לעתיד לבא מ\"מ היו מרויחין העניים דהא הקדש שוה מנה שחללו על שוה פרוטה מחולל ואפילו לכתחילה בזמן הזה כדאי' בערכין (דף כט.):"],[4,"","מכדי כתיב גם הצאן והבקר אל ירעו וגו'. פירוש מכדי כתיב אל מול ההר ההוא דמשמע כל זמן שהוא בהוייתו בקדושה ששכינה שרויה עליו דוקא אסור אבל נסתלקה שכינה מותר וא\"כ במשוך היובל למה לי וא\"ת והא אל מול ההר ההוא בלוחות אחרונות כתיב ובמשוך היובל נאמר קודם לכן בלוחות הראשונות ואי לא במשוך היובל לא שמעינן שריותא בלוחות הראשונות ופירש בקונטרס שלא נסתלקה שכינה ממנו מיום מתן תורה עד יום שהוקם המשכן ועד בעשרים באייר בשנה השנית שנעלה הענן וא\"כ שריותא דבמשוך היובל לא הוי עד שנה שניה ואז נאמר כבר אל מול ההר ההוא דמשמע מינה שריותא כדפי' כך שיטת הקונטרס ודוחק הוא דהא במשוך היובל משמע שגם בו ביום דמתן תורה הותרו לעלות כשימשוך היובל שלא היו קולות רק בלוחות הראשונות בסיון וא\"כ ליכא למימר שריותא דבמשוך היובל לא היה עד השנה שניה ועוד כיון דמההוא משתמע היתר בהדיא כדפרי' א\"כ אין צריך מנין אחר להתירו מידי דהוה אחרמות לאחר הזמן כדפרישית לעיל לכן נראה לי ה\"פ ת\"ש במשוך היובל וכו' למה לי והלא בלאו הכי יש להתיר מסברא דהא לא אסר להם לעלות אלא משום שכינה וא\"כ ממילא משתריין כשנסתלקה השכינה והא דקאמר מכדי כו' זהו שלא תאמר דבמשוך היובל אתי למשרי כשיפסקו הקולות אע\"פ שלא נסתלקה שכינה עדיין והאי התירא לא הוה שמעינן ממילא מסברא והשתא לא תפשוט מידי הא לא אפשר לומר דמכדי כתיב גם הצאן והבקר אל ירעו בלוחות האחרונות אע\"פ שלא היה שם קולות ומסתמא ה\"ה נמי בדברות הראשונות שנאסרו כל זמן ששכינה בהר אפילו כשיפסקו הקולות כמו באחרונות א\"כ במשוך היובל לא בא להתיר (אלא) כשיפסקו הקולות (. שנסתלקה) שכינה והאי התירא שמעינן ממילא מסברא אלא שמע מינה שצריך מנין אחר להתירו:"],[11,"","מי לא מודה רבן יוחנן בן זכאי כו' דהיום קדש ולמחר קדש. וא\"ת והא הוא עצמו תקן לקבל עדות החדש כל היום ופי' הקונטרס הני מילי לענין שמונין המועדות מיום הראשון ואפילו באו לאחר המנחה אבל מלעשות יום שני קדש לא נעקרה תקנה ראשונה ממקומה וקשה דמנין ליה הך סברא דתקינו לענין מועדות לחוד הא לענין יום טוב הוי יום שני נמי קדוש וא\"כ תהא הביצה אסורה ואימא כיון שהתקין שיהו מקבלין כל היום א\"כ כשהיו עושין שני ימים הם מספק ושתי קדושות נינהו וביצה מותרת לכך נראה כפירוש ר\"ח דגרס מי לא מודה שאם לא באו כו' ומ\"מ קשה דכיון שלא באו א\"כ היו שני ימים מספק וא\"כ שתי קדושות נינהו וביצה מותרת וי\"ל דה\"פ שאם לא באו עדים עד סמוך לחשכה ומיד החשיך ולא היה שהות ביום כדי לקבל עדותם ומ\"מ היו יכולין לעשות מעט מלאכה ולא היו עושין אלמא דקדושה אחת נינהו והא דאמר התקינו שיהו מקבלין עדותן כל היום היינו היכא דבאו עדים ביום או קודם המנחה או לאחר מיד והשתא דאתית להכי אין למחוק גרסת הספרים אם באו עדים וכו' כדפי' ומ\"מ יש ליישב פרש\"י ודקשיא לך מנא ליה הך סברא ה\"פ מי לא מודה רבן יוחנן בן זכאי וכו' כגון קודם חורבן דהוי קדושה אחת ואם כן גם לאחר חורבן נמי כשהיו עושין שני ימים כמו קודם חורבן הם קדושה אחת:"]]],[["אמר רבא מת ביום טוב ראשון יתעסקו בו עממים מת ביו\"ט שני יתעסקו בו ישראל ואפילו בשני ימים טובים של ר\"ה מה שאין כן בביצה","נהרדעי אמרי אף בביצה דמה דעתיך דלמא מעברי ליה לאלול הא אמר רב חיננא בר כהנא אמר רב מימות עזרא ואילך לא מצינו אלול מעובר","אמר מר זוטרא לא אמרן אלא דאשתהי אבל לא אשתהי משהינן ליה","רב אשי אמר אע\"ג דלא אשתהי נמי לא משהינן ליה מ\"ט יום טוב שני לגבי מת כחול שויוה רבנן אפילו למיגז ליה גלימא ולמיגז ליה אסא","אמר רבינא והאידנא דאיכא חברי חיישינן","רבינא הוה יתיב קמיה דרב (אסי) בשני ימים טובים של ראש השנה חזייה דהוה עציב אמר ליה אמאי עציב מר א\"ל דלא אותיבי עירובי תבשילין","אמר ליה ולותיב מר האידנא מי לא אמר רבא מניח אדם עירובי תבשילין מיו\"ט לחבירו ומתנה","אמר ליה אימר דאמר רבא בשני ימים טובים של גליות בשני ימים טובים של ראש השנה מי אמר","והא אמרי נהרדעי אף ביצה מותרת אמר ליה רב מרדכי בפירוש אמר לי מר דלא סבר להא דנהרדעי","אתמר אפרוח שנולד ביום טוב רב אמר אסור ושמואל ואיתימא ר' יוחנן אמר מותר רב אמר אסור מוקצה הוא ושמואל ואיתימא ר' יוחנן אמר מותר הואיל ומתיר עצמו בשחיטה","אמרי ליה רב כהנא ורב אסי לרב וכי מה בין זה לעגל שנולד ביום טוב אמר להו הואיל ומוכן אגב אמו בשחיטה","ומה בין זה לעגל שנולד מן הטרפה שתיק רב","אמר רבה ואיתימא רב יוסף מ\"ט שתיק רב לימא להו הואיל ומוכן אגב אמו לכלבים","אמר ליה אביי"],[[0,"אמר רבא מת בי\"ט ראשון כו'","מת המוטל לקבור אם י\"ט ראשון הוא וכו':"],[0,"משא\"כ בביצה","לענין ביצה לא הקלו בי\"ט שני דראש השנה להשוות לשל גליות דאלו ר\"ה נולדה בזה אסורה בזה:"],[1,"אף בביצה","נולדה בזה מותרת בזה:"],[1,"דמאי דעתיך","לאסרה בשני לרחוקי' מב\"ד:"],[1,"דילמא מעברי ליה לאלול","כתקנה הראשונה למנות מיום שני ולעשות שני ימים כגון שלא באו עד יום שלשים ואחד:"],[1,"מימות עזרא ואילך וכו'","ואע\"פ שתקנו לא אירע שבאו עדים מן המנחה ולמעלה חוץ מאותה הפעם ועדיין לא נתקנה האי דנקט מימות עזרא משום דבימיו עברוהו דכתיב בעזרא (נחמיה ח) וביום השני ובראש השנה משתעי:"],[2,"לא אמרן","דיתעסקו בו ישראל:"],[2,"אלא דאשתהי","ומתירא שלא יסריח:"],[3,"אסא","הדס היו מניחין על מטת מת לכבודו:"],[4,"דאיכא חברי","אומה רשעה שהיו בימי פרסיים וכופין את ישראל לעשות מלאכתן ובי\"ט היו נדחין מהן ע\"י שאומרים להם י\"ט הוא ואם יראו אותם מקברין מתיהם יכופו אותם למלאכה והאי גלימא דאמרינן לעיל אינו צורך המת שהרי יש לו תכריכין אחרים כל צרכו שאם צריך לו מאי אפילו דקאמר הא אמרינן בי\"ט שני יתעסקו בו ישראל ועסק זה חציבת קברו וחתוך תכריכין הלכך על כרחך בגלימא שאינו צריך לו מיירי דומיא דאסא דשרי למגזייה וקמ\"ל דאע\"ג דטרחא דלא צריך הוא אלא משום כבודו עושין לו יותר מדאי מותר לעשות לו כיון דלגבי מת כחול שויוה רבנן:"],[5,"חזייה","רבינא לרב אשי דהוה עציב:"],[5,"","ה\"ג אמאי עציב מר:"],[5,"א\"ל דלא אותיבי ערובי תבשילין","לא הושבתי כלומר לא הכנתי לי ערובי תבשילין לאפות ולבשל מי\"ט לשבת דתנן לקמן (ביצה דף טו:) עושה אדם תבשיל מערב י\"ט לשם ערוב:"],[6,"האידנא","בי\"ט ראשון והוא חמישי בשבת ועל תנאי הוא אומר אם היום הוא חול ולמחר קדש יהא ערוב ואם היום קדש ולמחר חול איני צריך לכך:"],[7,"מי אמר","והרי הם כיום ארוך ושניהם קדש:"],[8,"א\"ל רב מרדכי","לרבינא מנהרדעי לא תותביה למר בפירוש שמיע ליה מיניה דלא סבר לנהרדעי רב מרדכי תלמידו של רב אשי היה כדאמרינן בסוטה (דף מו:) גבי לויה לרבו עד פרסה רב מרדכי אלויה לרב אשי כו':"],[9,"הואיל ומתיר עצמו","בלידתו להיות נשחט מה שלא היה לפני לידתו אף מוקצה התיר את עצמו בלידתו דמגו דאתקן להא אתקן להא:"],[10,"לעגל שנולד בי\"ט","דתניא לקמן שמותר בו ביום לדברי הכל:"],[10,"מוכן אגב אמו","בעודו בתוך מעיה אם נשחטה האם היה נאכל:"],[11,"הטרפה","בנה אסור אם נמצא בתוכה דעובר ירך אמו הוא הואיל ובשחיטת אמו אתה בא לאכלו וכי נולד ביו\"ט מן הטרפה ליכא למימר הואיל ומוכן אגב אמו ואפ\"ה בשחיטת עצמו מותר לשחטו ולאכלו דלא אשכחן מאן דאסיר:"],[12,"לכלבים","דבין השמשות היתה אמו עומדת לכך אבל אפרוח שבקליפה אינו עומד לאכילת כלבים ואף לא היה ראוי הלכך נולד הוא:"]],[[1,"","מימות עזרא ואילך לא מצינו אלול מעובר. וא\"ת והאמרינן בערובין (דף לט. ושם) דרבי יוסי אוסר הביצה שנולדה [בראשון ביום] השני וא\"כ היכי פליגי נהרדעי אר' יוסי שהוא תנא י\"ל דלרבי יוסי אסור אי אתרמי ונהרדעי אמרי דלא אתרמי:"],[3,"","יום טוב שני לגבי מת כחול שויוה רבנן אפילו למיגז ליה גלימא ואפילו למיגז ליה אסא. ותימה דבמועד קטן (דף ת: ושם) אמרינן אין חופרין כוכין במועד והכא משמע דאין זו מלאכה וי\"ל כפי' ר\"ח דפירש שהיו רגילין לחפור הרבה ביחד כדי שיהיו מזומנות כשיבאו מתים ועל זה קאמר דאין חופרין במועד לצורך אחר המועד:"],[4,"","והאידנא דאיכא חברי חיישינן. פרש\"י שכופין לישראל לעשות מלאכה וכשהוא י\"ט מניחין אותם ואם היו רואין שיקברו מתיהם יכופו אותם לעשות מלאכה והשתא בזמן הזה שאין חברי מותר ואין לומר שצריך מנין אחר להתירו דכיון דזה הטעם משום חששא ועברה החששא עבר הטעם וה\"נ אמרינן גבי מים מגולין דאסורין שמא נחש שתה מהן ועכשיו שאין נחשים מצויין בינינו אנו שותין מהן אפילו לכתחילה אע\"פ שהוא דבר שבמנין ומ\"מ ר\"ת היה אוסר ומעשה היה במלאו\"ן שמת אדם אחד בי\"ט שני ורצו להתעסק בו לקברו וגער בהן ר\"ת ושלח להם בני בשכר אינן בני תורה ואתם בני תורה כדאיתא בשבת (דף קלט: ושם) שלא לקבור מת בי\"ט שני משום דלאו בני תורה נינהו ואתי לזלזולי ביה אבל הר\"י אמר דאין זה דמיון דהא לענין הרבה דברים אשכחנא דאינן בני תורה כדאי' ביבמות (דף מו. ושם) חזנהו דקא אכלי תורמוס דשלקי נכרים ואסר להם ופרכינן והא נאכל כמו שהוא חי וכל שהוא נאכל כמו שהוא חי אין בו משום בשולי נכרים ומשני שלא היו בני תורה ואנו אין אנו חוששין בדבר זה דקיימא לן דכל שהוא נאכל כמו שהוא חי אין בו משום בשולי נכרים והר\"ר יחיאל אומר דלא דמי דשאני הכא דבצנעה הוא אוכל בביתו ולא אוושא מלתא אבל לקבור מתים בפרהסיא אוושא מלתא ואין נכון להתיר ועוד אמר רבינו תם דבזמן הזה נמי יש יהודים שהן משועבדים למלכות לעשות מלאכה כגון לקבל המס ולהתעסק בצרכיהם הלכך אם יראו שיתעסקו לעשות מלאכה במת יכופו אותם לעשות מלאכה למלכות:"],[9,"","אפרוח שנולד בי\"ט וכו'. נראה לומר דאתרמי שנפתחו עיניו היום דאי לא נפתחו עיניו קי\"ל דאפילו בחול אסור:"],[9,"","הואיל ומתיר עצמו בשחיטה. פירש רש\"י מתיר עצמו בלידתו להיות נשחט אבל קודם לידתו היה אסור וכיון דאתקן לשחיטה אתקן נמי לענין מוקצה ותימה למה להו לשמואל ור' יוחנן הך טעמא תיפוק ליה משום דלית להו מוקצה כדאמרינן פרק מי שהחשיך (שבת דף קנו:) דשמואל וזעירי ור' יוחנן כר' שמעון סבירא להו וי\"ל דהכא קאמר טעמא אפילו לרבי יהודה דאית ליה מוקצה שרי מהאי טעמא ולכך צריך האי טעמא אי נמי איצטריך אפילו לרבי שמעון דלית ליה מוקצה דמודה בהאי מוקצה דהכא דהוי כגרוגרות וצמוקין והכי מוכח בשבת (דף מה:):"],[11,"","וכי מה בין זה לעגל שנולד מן הטרפה. דהתם לא מצי למימר הואיל ומוכן אגב אמו דהא אמו טרפה והוא מותר ותימה והא מוכן הוא דאמרינן בחולין (דף עה.) דבן פקועה ניתר בארבעה סימנין בשחיטת אמו או בדידיה ואם כן יכול להושיט ידו במעי אמו וישחטנו ויהיה מוכן כהאי גוונא וי\"ל דקאמר גמרא אליבא דרבי אושעיא דקמבעיא ליה התם בחולין (דף עד.) אם ניתר בן פקועה בארבעה סימנין אי נמי י\"ל הואיל ולכתחילה אין לו לשחטו כי האי גוונא שאינו יכול לראות מידי דהוה אשוחט בלילה (שם דף יג:) דאסור לכתחילה לא מיקרי מוכן ועוד יש לומר דהתם מיירי דאירע שכלו לו חדשיו והכא מיירי בלא כלו לו חדשיו עד היום וא\"כ לא הוי מוכן היום הואיל ובין השמשות לא הוה חזי:"]]],[["השתא מוכן לאדם לא הוי מוכן לכלבים דתנן מחתכין את הדלועין לפני הבהמה ואת הנבלה לפני הכלבים רבי יהודה אומר אם לא היתה נבלה מערב שבת אסורה לפי שאינה מן המוכן מוכן לכלבים הוי מוכן לאדם","אמר ליה אין מוכן לאדם לא הוי מוכן לכלבים דמאי דחזי ליה לאיניש לא שדי ליה לכלבים מוכן לכלבים הוי מוכן לאדם דדעתיה דאיניש אכל מידי דחזי ליה","תניא כותיה דרב תניא כותיה דשמואל ואיתימא ר' יוחנן","תניא כותיה דרב עגל שנולד ביו\"ט מותר אפרוח שנולד ביום טוב אסור ומה הפרש בין זה לזה זה מוכן אגב אמו בשחיטה וזה אינו מוכן אגב אמו","תניא כותיה דשמואל ואיתימא רבי יוחנן עגל שנולד ביום טוב מותר ואפרוח שנולד ביו\"ט מותר מאי טעמא זה מוכן אגב אמו וזה מתיר עצמו בשחיטה","תנו רבנן אפרוח שנולד ביום טוב אסור רבי אליעזר בן יעקב אומר אף בחול אסור לפי שלא נתפתחו עיניו","כמאן אזלא הא דתניא (ויקרא יא, מב) לכל השרץ השורץ על הארץ לרבות אפרוחים שלא נתפתחו עיניהם כמאן כר' אליעזר בן יעקב","אמר רב הונא אמר רב ביצה עם יציאתה נגמרה מאי עם יציאתה נגמרה אילימא עם יציאתה נגמרה ומותרת לאכלה בחלב הא במעי אמה אסורה לאכלה בחלב והתניא השוחט את התרנגולת ומצא בא ביצים גמורות מותרות לאכלן בחלב","אלא עם יציאתה נגמרה ומותרת לאוכלה ביום טוב הא במעי אמה אסורה לאכלה ביום טוב והא תניא השוחט את התרנגולת ומצא בה ביצים גמורות מותרות לאכלן ביום טוב","וכי תימא קמ\"ל בברייתא מאי דלא אשמעינן במתניתין הא נמי תנינא ביצה שנולדה ביו\"ט ב\"ש אומרים תאכל וב\"ה אומרים לא תאכל ועד כאן לא פליגי ב\"ש וב\"ה אלא בנולדה אבל במעי אמן דברי הכל שריין","וכי תימא בית הלל אפילו במעי אמן נמי אסרי והא דקתני נולדה להודיעך כחן דב\"ש דאפילו נולדה נמי שרו אלא הא דתניא השוחט את התרנגולת ומצא בה ביצים גמורות מותרות לאכלן ביום טוב מני לא ב\"ש ולא ב\"ה","אלא עם יציאתה נגמרה ומגדלת אפרוחים במעי אמה אינה מגדלת אפרוחים למאי נפקא מינה למקח וממכר כי ההוא דאמר להו ביעי"],[[0,"מוכן לאדם לא הוי מוכן לכלבים","למאן דאית ליה מוקצה דהא נתנבלה בשבת לר' יהודה אתמול בין השמשות היתה עומדת לאדם וקא חשיב ליה מוקצה בהא לגבי כלבים:"],[1,"אכל מידי דחזי ליה","ועובר שבמעי טרפה ראוי לו לכשיולד הלכך מאתמול דעתיה עלויה אם יולד יאכלנו:"],[5,"לפי שלא נתפתחו עיניו","ואתרבי לאסורא מכל השרץ השורץ על הארץ כדלקמן:"],[7,"עם יציאתה נגמרה","כשיצאה נגמרה ברייתה אבל מקמי הכי לא חשיבא ביצה גמורה ולקמיה מפרש ואזיל למאי הלכתא:"],[7,"לאכלה בחלב","דהשתא הוה ביצה ולא בשר אבל הנמצאת במעי אמה אינה ביצה ואסורה לאכלה בחלב:"],[7,"ביצים גמורות","ואפילו בלא קליפה לבנה אלא שהחלמון לבדו גמור ואע\"פ שמעורה עדיין בגידין שריא כדלקמן מדפליג ר' יעקב עליה ואמר אם היו מעורות בגידין אסורות:"],[8,"בי\"ט","וה\"ק יצתה ודאי מבעוד יום מותר כי ודאי הוא דנגמרה בחול אבל לא יצתה לא נגמרה בחול ואסורה משום הכנה דרבה:"],[9,"וכי תימא","אין הלכה כברייתא זו דאשמועינן בה מאי דלא אשמעינן במתני' ובשום משנה לא סתם לן רבי הכי ואם רבי לא שנה רבי חייא מנין לו:"],[10,"אלא הא דתניא כו'","הך ברייתא דלעיל מאן קתני לה:"],[10,"לא בית שמאי ולא ב\"ה","לא ב\"ש דמאי אריא במעי אמה אפילו נולדה בי\"ט שריא ולא ב\"ה דאפילו במעי אמן אסירי:"],[11,"ומגדלת אפרוחים","ולענין דין מקח וממכר אתמר דאם נולדה נגמר בשולה וראויה לגדל ממנה אפרוחים אבל נמצאת במעי אמה אינה מגדלת אפרוחים ואם תבעוהו למכור ביצים לגדל אפרוחים אם מכר אלו הוי מקח טעות ובטל מקח:"]],[[0,"","השתא מוכן לאדם לא הוי מוכן לבהמה דתנן מחתכין וכו' ר' יהודה כו' לפי שאינו מוכן. ותימה היכי הוי מוכן לאדם אדרבה לא הוי מוכן לאדם דבין השמשות לא מצי שחיט לה דשמא הוא שבת והיכי מוכח מהכא דמוכן לאדם לא הוי מוכן לכלבים על כן נראה להרר\"י דגרס אם לא היתה נבלה מעיו\"ט ולא נראה דהא בהדיא אמרינן לעיל (דף ב.) דגבי שבת מתניא דקאמר גבי שבת דסתם לן תנא כר\"ש וכו' ומייתי הך משנה וי\"ל דשפיר מיירי בשבת ומייתי מן היתור דאי לא אשמועינן כי אם גבי שבת לתני רבי יהודה אומר אם לא היתה נבלה מערב שבת אסורה ותו לא והייתי יודע דאסורה משום מוקצה ואמאי היה צריך למיתני לפי שאינו מן המוכן אם אינו ענין לשבת דהא שמעינן ליה תנהו ענין ליו\"ט ואפילו הכי אסור ואע\"ג דהוה מוכן לאדם בין השמשות משום דמוכן לאדם לא הוי מוכן לכלבים ותימה הא דתנן בשבת (דף מב: ושם) אין נותנין כלי תחת הנר בשבת לקבל בו שמן ואם נתנו מבעוד יום מותר ואין נאותין הימנו לפי שאינו מן המוכן והתם מאי דרשינן מן היתור ולא שייך לרבות י\"ט וי\"ל דהתם נמי מרבי' מן היתור אע\"פ שכבה הנר כבר אסור אחרי כן לפי שאינו מן המוכן והר\"ר יעקב מקורביי\"ל תירץ דשפיר מיירי דוקא לענין שבת ואעפ\"כ מוכח שפיר דמוכן לאדם לא הוי מוכן לכלבים דאי ס\"ד מוכן לאדם הוי מוכן לכלבים א\"כ בע\"ש מבעוד יום אם היה מוכן לאדם היה כמו כן מוכן לכלבים לפי דבריו דמוכן לאדם הוי מוכן לכלבים א\"כ כשהחשיך וקדש היום אע\"ג דנסתלקה הכנה דאדם שאינה ראויה לאדם עכשיו מ\"מ היתה מוכנת לכלבים מבעוד יום וכיון שהיתה מוכנת להם ההכנה לא נסתלקה בקדוש היום:"],[1,"","מוכן לכלבים הוי מוכן לאדם דדעתיה דאיניש אכל מידי דחזי ליה. וקשה דא\"כ אפרוח נמי יהא מותר שמוכן לכלבים וי\"ל דבעינן מוכן ועומד וזה אינו עומד לכלבים:"],[3,"","עגל שנולד בי\"ט מותר. ותימה מ\"מ הוי אסור משום נולד כמו ביצה וי\"ל דהא דאמר דשייך למיסר נולד היינו דוקא בדבר מאכל דומיא דפירות הנושרין ומשקין שזבו אבל בעלי חיים לא:"],[7,"","ביצים גמורות מותרות לאכלן בחלב. וקשה דהא אמרינן בעדיות (פ\"ה מ\"א) ביצת נבלה כל. שכמוה נמכרת בשוק ב\"ש מתירין וב\"ה אוסרין והכא היכי מותר לאכלן בחלב וי\"ל דטעמא משום דבשר עוף בחלב מדרבנן ואפילו ב\"ה מודו וקשה דאמרינין בעירובין (דף סב: ושם) אפילו ביעתא בכותחא לא לשרי איניש במקום רביה מאי קמ\"ל פשיטא והאיכא בסמוך ר' יעקב דאסר וי\"ל דכ\"ע מודו דביצים. גמורות מותרות לאכלן בחלב וטעמא דב\"ה דאסרי ביצת נבלה היינו משום דגזרינן אטו ביצת טרפה כדאמרינן בעדיות ומודים בביצת טרפה שהיא אסורה מפני שהיא גדילה באיסור: [וע\"ע תוס' עירובין סב: ד\"ה אפילו ובכתובות ס: ד\"ה אפילו ובב\"ק מז. ד\"ה מ\"ט ובחולין נח. ד\"ה ושוין]:"],[9,"","וכי תימא קא משמע לן בברייתא מאי דלא אשמעינן במשנה. פירש רש\"י וגילה לנו רבי הואיל ולא סתם לן במשנה הכי דהברייתא משובשת דרבי לא שנאה ר' חייא מנין ליה ותימה אם כן מאי פריך הא נולדה אסורה לא בית שמאי ולא ב\"ה ואמאי דחיק נפשיה לאוקומה אליבא דתנאי הואיל ומשובשת היא על כן צריך לפרש הכי וכי תימא קא משמע לן בברייתא מאי דלא אשמעינן במתניתין כלומר מאי ששייר במתני' קתני הברייתא דאי לא תנא אלא מתניתין הייתי אומר שמתירין בית שמאי דוקא כשנולדה אבל במעי אמה היו מודים דאסור ופריך תנינא דאדרבה נולדה חמורה יותר מבמעי אמה ואתיא נמי כבית הלל וכו' דבמעי אמה דברי הכל שריא:"],[10,"","מני לא כב\"ש ולא כב\"ה. ואינו יכול לפרש דקתני בברייתא מה ששייר במתניתין דהא ס\"ד עכשיו שנולדה חמורה מבמעי אמה:"]]],[["דפחיא למאן יהבו ליה ביעי דשחוטה אתא לקמיה דרבי אמי אמר להו מקח טעות הוא והדר","פשיטא מהו דתימא האי לאכילה קא בעי להו והאי דקאמר דפחיא משום דצריבן למאי נפקא מינה למיתבה ליה ביני ביני קמ\"ל","ההוא דאמר להו ביעי דדכרא למאן ביעי דדכרא למאן יהבו ליה ביעי דספנא מארעא אתא לקמיה דרבי אמי אמר להו מקח טעות הוא והדר","פשיטא מהו דתימא האי לאכילה קא בעי להו והאי דקאמר דדכרא משום דשמינן טפי למאי נפקא מינה למיתבא ליה ביני ביני קמ\"ל","ואי בעית אימא מאי עם יציאתה נגמרה עם יציאת רובה נגמרה וכדרבי יוחנן דא\"ר יוחנן ביצה שיצאה רובה מערב יום טוב וחזרה מותרת לאכלה ביום טוב","ואיכא דאמר מאי עם יציאתה נגמרה עם יציאת כולה נגמרה עם יציאת כולה אין אבל רובה לא ולאפוקי מדר' יוחנן","גופא השוחט את התרנגולת ומצא בה ביצים גמורות מותרות לאכלן בחלב ר' יעקב אומר אם היו מעורות בגידין אסורות","מאן תנא להא דת\"ר האוכל מנבלת עוף טהור מן השלל של ביצים מן העצמות ומן הגידין ומן הבשר שנתלש מן החי טהור","מן האשכול של ביצים מן הקורקבן ובני מעיין או שהמחה את החלב וגמעו טמא","מאן תנא מן השלל של ביצים טהור אמר רב יוסף דלא כרבי יעקב דאי כר' יעקב האמר אם היו מעורות בגידין אסורות","אמר ליה אביי ממאי דלמא עד כאן לא קאמר רבי יעקב התם אלא לענין אסורא אבל לענין טומאה לא","וכי תימא לענין טומאה נמי נגזור אפושי טומאה הוא ואפושי טומאה מדרבנן לא מפשינן","ואיכא דאמרי מאן תנא מן האשכול של ביצים טמא אמר רב יוסף ר' יעקב היא דאמר אם היו מעורות בגידין אסורות א\"ל אביי ממאי דאשכול מהנך דתליא באשכול דלמא אשכול גופיה","וכי תימא אשכול גופיה מאי למימרא מידי דהוה אקורקבן ובני מעיין דאע\"ג דבשר נינהו כיון דאיכא אינשי דלא אכלי איצטריך לאשמועינן הכא נמי כיון דאיכא אינשי דלא אכלי איצטריך לאשמועינן","ת\"ר כל שתשמישו ביום נולד ביום כל שתשמישו בלילה נולד בלילה כל שתשמישו בין ביום ובין בלילה נולד בין ביום ובין בלילה כל שתשמישו ביום נולד ביום זו תרנגולת כל שתשמישו בלילה נולד בלילה זו עטלף כל שתשמישו בין ביום ובין בלילה אדם וכל דדמי ליה","אמר מר כל שתשמישו ביום נולד ביום זו תרנגולת למאי נפקא מינה לכדרב מרי בריה דרב כהנא דאמר רב מרי בריה דרב כהנא בדק בקנה של תרנגולין מערב יום טוב ולא מצא בה ביצה ולמחר השכים ומצא בה ביצה מותרת","והלא בדק אימר לא בדק יפה יפה ואפילו בדק יפה אימר יצתה רובה וחזרה הואי וכדר' יוחנן","איני והא אמר ר' יוסי בן שאול אמר רב בדק בקנה של תרנגולת מערב יו\"ט ולא מצא בה ביצה ולמחר השכים ומצא בה ביצה אסורה התם בדספנא מארעא","אי הכי דרב מרי נמי אימא מארעא ספנא בדאיכא זכר בהדה בדאיכא זכר נמי אימא מארעא ספנא אמר רבינא גמירי כל היכא דאיכא זכר לא ספנא מארעא","ועד כמה אמר רב גמדא משמיה דרב כל היכא"],[[0,"דפחיא","כמו דפעיא הנולדים מן התרנגולת חיה שפועה בלידתה:"],[1,"פשיטא","דמקח טעות הוא דהא בהדיא אמר ליה דפחיא:"],[1,"דצריבן","לשון מבושלות כל צרכן כמו צרבת (ויקרא יג) כויה שבשול:"],[1,"ונפקא מינה","בין מאן דבעי להו לאכילה בין מאן דבעי להו לאפרוחים:"],[1,"למיתבא ליה דביני ביני","להחזיר לו דמי מעלה שבין ביעי דפחיא לביעי דשחוטה ואי בעי להו לאכילה אין המקח בטל דהא בני אכילה נינהו אלא שאלו יפים מהם ויחזיר לו דמי מעליותן:"],[1,"קא משמע לן","רבי אמי דסתם מאן דבעי ביעא דפחיא לאפרוחים בעי להו ואין אלו שוין לו כלום:"],[2,"דדכרא","שילדתן תרנגולת מתרנגול ולא נתחממה מן הקרקע לקולטן בלא זכר:"],[2,"דספנא מארעא","מתחממת בקרקע ויולדת ביצים ואותן ביצים אין מגדלות אפרוחים:"],[2,"ספנא","קולטת ביצים כשמתעפרת בקרקע ובסמוך לקמן אמר כל היכא דאיכא זכר לא ספנא מארעא כלומר אינה קולטת ביצים מן הקרקע אלא מן הזכר ואינו אלא לשון שפוני טמוני חול (דברים ל״ג:י״ט):"],[4,"עם יציאת רובה נגמרה","ולענין י\"ט אתמר דאם יצתה רובה מערב י\"ט וחזרה בתוך מעיה וילדתה בלילה מותרת דהויא ליה כאילו נולדה מאתמול:"],[4,"כדרבי יוחנן","דאמר לקמן הכי:"],[5,"ואי בעית אימא","רב לאפוקי מדר' יוחנן אתא ועם יציאתה דקאמר עם יציאת כולה ולמעוטי יציאת רובה:"],[6,"מעורות","מחוברות:"],[7,"נבלת עוף טהור","מטמאה האוכלה לטמא בגדים שהוא לבוש בשעת בליעתה ואין לה טומאת מגע ומשא ובמסכת נדה (דף נא.) ילפינן לה והאוכל אחד מן הדברים הללו ממנה:"],[7,"מן השלל של ביצים","כשהן כבושין ושלולין וקבועין בשדרה כלומר האוכל אותם ביצים בעודן מעורין בגידין:"],[7,"מן הגידין","וקסבר אין בגידין בנותן טעם:"],[7,"שלל","בשט\"א כמו שלל של כובסין (שבת דף מח:):"],[7,"בשר שנתלש מן החי","לאו נבלה היא:"],[8,"מן האשכול","מבשר השדרה שהביצים אדוקים שם:"],[8,"שהמחה את החלב","התיך את השומן וגמעו טמא ובהעור והרוטב (חולין דף קכ.) פרכינן והא אכילה כתיבה ביה ואמר רבי שמעון בן לקיש הנפש לרבות את השותה והכא כתיב ונפש אשר תאכל נבלה ובנבלת עוף טהור מתוקם בת\"כ:"],[9,"מאן תנא מן השלל של ביצים טהור","אלמא לאו בשר הוא דלא כר' יעקב:"],[10,"אלא לענין אסורא","דאע\"ג דלאו בשר נינהו אסר לה מדרבנן הואיל וקרובים להיות בשר ואיכא למגזר משום בשר בחלב אבל לענין טומאה לא דלאו בשר נינהו דלטמו:"],[11,"וכי תימא לענין טומאה נגזור","דלטמו מדרבנן כי היכא דגזרינן לענין אסורא:"],[11,"אפושי טומאה הוא","דאיכא הפסד טהרות:"],[11,"ואפושי טומאה מדרבנן לא מפשינן","ואע\"פ שגזרו בטומאות במקומות הרבה ליכא למימר הכא נמי נגזר דלא ניחא לן דלפשו בטומאות:"],[12,"ואיכא דאמרי","דאשכול דסיפא הוה משמע ליה לרב יוסף ביצים המעורות בגידין ושלל הוה משמע ליה שאינן מעורות כל כך כמו אותן הגמורות קרובות לבא בהן קליפה הלבנה שאינם דבקות יפה אלא מעט:"],[13,"מאשכול גופיה","בשר הדבוק בשדרה והביצים אדוקין בו:"],[14,"נולד ביום","נקבותיו יולדות ביום:"],[14,"עטלף","קלב\"א שור\"ץ בלע\"ז:"],[15,"מערב יום טוב","בין השמשות דשוב לא ילדה אלא בלילה:"],[15,"השכים","קודם עלות השחר והאי דנקט בדק רבותא קמ\"ל דאע\"ג דבדק ולא מצא דליכא למתלייה בנולדה בחול אפילו הכי מותרת דסמכינן אברייתא דקתני כל שתשמישו ביום נולד ביום והא ודאי לא ילדתו בלילה:"],[16,"אימר יצתה רובה וחזרה הואי","ואע\"ג דמילתא דלא שכיחא היא מגו דפשיטא לן דאינה יולדת בלילה תלינן בה:"],[17,"בדספנא מארעא","והיא יולדת אף בלילה:"],[17,"ספנא","קולטת ביצים כשמתעפרת בקרקע ובסמוך לקמן אמר כל היכא דאיכא זכר לא ספנא מארעא כלומר אינה קולטת ביצים מן הקרקע אלא מן הזכר ואינו אלא לשון שפוני טמוני חול (דברים לג):"],[18,"אי הכי","דיש יולדת בלילה:"],[18,"דרב מרי","היכי שריא אימא מארעא ספנא וילדה בליל יום טוב:"]],[[6,"","ומצא בה ביצים גמורות וכו' ר' יעקב אומר אם היו מעורות בגידין אסורות. תימה כיון דגמורות כיצד היו מעורות ופירש הקונטרס דגמורות קאי אחלמון אבל לא נתקשה עדיין השפופרת מבחוץ רק הקרום על כן קאי רבי יעקב וקאמר אם היו מעורות ולפי הספרים דלא גרסי גמורות ניחא והכי גרסינן ומצא בה ביצים מותרות לאכלן בחלב רבי יעקב אומר כו':"]]],[["דשמעה קליה ביממא","עבד רב מרי עובדא עד שתין בתי","ואי איכא נהרא לא עברא ואי איכא מברא עברא ואי איכא מיצרא לא עברא הוה עובדא ועברא אמיצרא","במאי אוקימתא בדספנא מארעא מאי איריא בדק כי לא בדק נמי","כי לא בדק אימא מאתמול הואי אי הכי כי בדק נמי אימא יצתה רובה וחזרה היא וכדר' יוחנן דרבי יוחנן לא שכיח","ואמר רבי יוסי בן שאול אמר רב האי תומא שחיקא סכנתא לגלויא:","בית שמאי אומרים שאור בכזית:","מאי טעמייהו דב\"ש א\"כ לכתוב רחמנא חמץ ולא בעי שאור ואנא אמינא ומה חמץ שאין חמוצו קשה בכזית שאור שחמוצו קשה לא כל שכן שאור דכתב רחמנא למה לי לומר לך שיעורו של זה לא כשיעורו של זה","ובית הלל צריכי דאי כתב רחמנא שאור הוה אמינא משום דחמוצו קשה אבל חמץ דאין חמוצו קשה אימא לא צריכא","ואי כתב רחמנא חמץ משום דראוי לאכילה אבל שאור שאין ראוי לאכילה אימא לא צריכא","ובית שמאי לית להו דרבי זירא דאמר רבי זירא פתח הכתוב בשאור וסיים בחמץ לומר לך זהו שאור זהו חמץ","לענין אכילה כולי עלמא לא פליגי כי פליגי לענין ביעור בית שמאי סברי לא ילפינן ביעור מאכילה ובית הלל סברי ילפינן ביעור מאכילה","אתמר נמי א\"ר יוסי בר חנינא מחלוקת לענין ביעור אבל לענין אכילה דברי הכל זה וזה בכזית","תניא נמי הכי (שמות יג, ז) ולא יראה לך (שאור) ולא יראה לך (חמץ) זהו מחלוקת שבין בית שמאי וב\"ה שב\"ש אומרים שאור בכזית וחמץ בככותבת וב\"ה אומרים זה וזה בכזית:","השוחט חיה ועוף ביו\"ט וכו':","השוחט דיעבד אין לכתחלה לא אימא סיפא וב\"ה אומרים לא ישחוט מכלל דת\"ק סבר ישחוט","הא לא קשיא לא ישחוט ויכסה קאמר","אימא סיפא ומודים שאם שחט שיחפור בדקר ויכסה מכלל דרישא לאו דיעבד הוא","אמר רבה הכי קאמר השוחט שבא לימלך כיצד אומר לו ב\"ש אומרים אומר לו שחוט חפור וכסה ובית הלל אומרים לא ישחוט אא\"כ היה לו עפר מוכן מבעוד יום","רב יוסף אמר ה\"ק השוחט שבא להמלך כיצד אומר לו ב\"ש אומרים אומר לו לך חפור שחוט וכסה וב\"ה אומרים לא ישחוט אא\"כ היה לו עפר מוכן מבעוד יום","א\"ל אביי לרב יוסף לימא מר ורבה בדרבי זירא אמר רב קא מפלגיתו דא\"ר זירא אמר רב השוחט צריך שיתן עפר למטה ועפר למעלה שנאמר (ויקרא יז, יג) ושפך את דמו וכסהו בעפר עפר לא נאמר אלא בעפר מלמד שהשוחט צריך שיתן עפר למטה ועפר למעלה","דמר אית ליה דרבי זירא ורבה לית ליה דרבי זירא","א\"ל בין לדידי בין לרבה אית לן דרבי זירא והכא בהא קא מפלגינן רבה סבר אי איכא עפר למטה אין אי לא לא חיישינן דלמא ממליך ולא שחיט ולדידי (אדרבה) הא עדיפא דאי לא שרית ליה אתי לאמנועי משמחת יום טוב:","ומודים שאם שחט שיחפור בדקר ויכסה: אמר רבי זריקא אמר רב יהודה והוא שיש לו דקר נעוץ מבעוד יום והא קא עביד כתישה אמר רב חייא בר אשי אמר רב"],[[0,"דשמעה קליה ביממא","שהקול אינו נשמע ביום כבלילה:"],[1,"עובדא","דבדק מעי\"ט ולא מצא והשכים ומצא ולא היה תרנגול זכר עד ששים בתים וסמך רב מרי על התרנגול והתיר את הביצה:"],[2,"מברא","גשר:"],[2,"מיצרא","חבל קשור בראשי שתי יתדות אחת תקועה בשפת הנהר מזה ואחת תקועה בשפת הנהר מזה ועץ קצר מוטל לרוחב הנהר ועוברין בו בדוחק על ידי שאוחזין בחבל ועוברין:"],[3,"במאי אוקימתא","לדרבי יוסי ב\"ר שאול:"],[4,"אימא מאתמול הואי","דכיון דרובא ביממא ילדן אי לא בדק תלינן ביממא:"],[4,"דרבי יוחנן לא שכיחא","הלכך בדאיכא זכר כיון דקים לן דאינה יולדת בלילה תלינן כרבי יוחנן אבל בדספנא מארעא לילד בלילה שכיח טפי מיצתה רובה:"],[5,"תומא שחיקא","שומין שחוקין:"],[5,"לגלויא","הנחש שותה ממנו אם מוצאו מגולה ומטיל בו ארס:"],[7,"אם כן","דחד שיעורא לתרוייהו:"],[7,"שיעורו של זה כו'","להכי לא יליף שאור מחמץ משום דחמץ בככותבת דלא תימא דיו לבא מן הדין להיות כנדון ושאור נמי בככותבת להכי כתביה בהדיא לשעורי בשיעורא זוטא ושיעורא רבא ולהכי נקט כותבת דבהכי הוי יתובי דעתא כדמפרש טעמא ביומא (דף עט.) אי נמי שיעורין הלכה למשה מסיני:"],[10,"לית להו דרבי זירא","בתמיה והא קרא בהדיא כתיב:"],[10,"פתח הכתוב בשאור","שאור לא ימצא בבתיכם (שמות יב):"],[10,"וסיים בחמץ","כי כל אוכל [מחמצת] והוה ליה למכתב כי כל אוכל שאור כו' דהא אתיא עונשו עם אזהרתו:"],[10,"זהו שאור וכו'","כזה כן זה:"],[11,"לענין אכילה כולי עלמא לא פליגי","דאפילו ב\"ש מודו דחמץ חייב בכזית כשאור באכילתו וכדר' זירא אבל לביעור לב\"ש לא השוו מדאיצטריך קרא למכתבינהו לתרוייהו לא יראה לך חמץ ולא יראה לך שאור לא ילפינן למימר כי היכי דבאכילה השוה הכתוב אכילת חמץ לביעור שאור אף לביעורו השוה לו דמדאיצטריך למכתבינהו יש חלוק בשיעורן:"],[13,"תניא נמי הכי","דבביעור הוא דפליגי ולא באכילה:"],[15,"השוחט דיעבד","דאי שחט משמע אבל לכתחילה לא שרי ליה בית שמאי לשחוט אא\"כ יש לו עפר מוכן תיחוח:"],[15,"מכלל דת\"ק סבר ישחוט","בתמיה והא השוחט קאמר:"],[16,"הא לא קשיא","לא ישחוט דב\"ה אכסוי לחודיה קא מהדרי והכי קאמר לא יגמור מעשה השחיטה דהיינו הכסוי:"],[16,"לא ישחוט ויכסה","אע\"פ ששחט לא יגמור:"],[18,"השוחט שבא לימלך","אע\"ג דהשוחט דעלמא דיעבד על כרחך הכא לכתחלה השוחט שבא לשחוט (בהמה) ובא לימלך לנו מה יעשה אם ישחוט אם לאו הואיל ואין לו עפר תיחוח ב\"ש אומרים כו':"],[19,"רב יוסף אמר כו'","ולקמיה מפרש במאי קמפלגי רבה ורב יוסף אליבא דב\"ש:"],[20,"בעפר","משמע שהוא נבלל וטמון בעפר קודם הכסוי:"],[20,"וכסהו עפר","הוי משמע דלא קפיד אלא אכסוי:"],[22,"אית לן דר' זירא","ובעינן עפר למטה והכי קאמר רבה אם יכולין לומר לו שחוט מיד שיש לו כבר עפר למטה שרינן ליה אבל אם אנו צריכין לומר לו חפור תחלה לא נתיר לו:"],[22,"דלמא","לאחר חפירה ממליך ולא שחיט נמצא שחופר בחנם:"],[22,"הא עדיפא","דלא תגזור הכי:"],[23,"והא קא עביד כתישה","לרב יהודה פריך דאמר והוא שיש לו דקר נעוץ אלמא דטעמא דמתניתין לאו משום דאתי עשה דוכסהו בעפר ודחי את לא תעשה כל מלאכה אלא משום דכבר חפור ועומד הוא והא קא עביד כתישה שעדיין רגבים מדובקים הם ואינן ראוין לכסוי אלא אם כן כותשן וכותש תולדה דטוחן הוא ומלאכה היא:"]],[[0,"","דשמעה קליה ביממא. ובלילה משמיעין קולם למרחוק יותר מביום ולא נקט בלילה משום דתשמישו ביום:"],[4,"","כי לא בדק אימר מאתמול הואי. וא\"ת והא ביצה דבר שיש לו מתירין א\"כ ספקא לחומרא וי\"ל דשאני הכא משום דגם כי ספנא מארעא שכיח דיולדת ביום יותר מבלילה:"],[7,"","לומר לך שיעורו של זה לא כשיעורו של זה. פירש רש\"י דאי לא כתב שאור הייתי אומר דיו לבא מן הדין להיות כנדון ודוקא בככותבת וא\"ת מנלן דשיעור חמץ בככותבת אימא כביצה או כשיעור אחר ופ\"ה דהלכתא גמירי לה דהוי ככותבת ולא נהירא דא\"כ קרא למה לי ע\"כ נראה פירוש (אחר) הואיל וידענא דשיעורו של זה לא כשיעורו של זה נוקים ליה שיעורו כדאשכחנא בעלמא גבי יום כפור (יומא דף עט. ושם) דהוי בככותבת:"],[10,"","דאמר רבי זירא פתח הכתוב בשאור וסיים בחמץ וכו' ובית הלל סברי ילפינן ביעור מאכילה. ואם תאמר למה ליה צריכותא דלעיל הא ידענא שפיר [דחמץ] בכזית מהכא וי\"ל שלא תטעה לומר הואיל וחלקן הכתוב בשני לאוין ולא יראה לך (. שאור) ולא יראה לך (. חמץ) ודאי אין שיעורן שוה דזה בככותבת וזה בכזית קמ\"ל הצריכתות וא\"ת הואיל ואית להו הצריכתות למה להו דר' זירא י\"ל לא הייתי משים כרת אלא בחמץ דכתיב ביה כרת:"]]],[["בעפר תיחוח","והא קא עביד גומא כדר' אבא דאמר ר' אבא החופר גומא בשבת ואינו צריך אלא לעפרה פטור עליה:","שאפר כירה מוכן הוא: אפר כירה מאן דכר שמיה אמר רבה הכי קאמר ואפר כירה מוכן הוא","אמר רב יהודה אמר רב לא שנו אלא שהוסק מערב יו\"ט אבל הוסק ביום טוב אסור ואם ראוי לצלות בו ביצה מותר","תניא נמי הכי כשאמרו אפר כירה מוכן הוא לא אמרו אלא שהוסק מערב יו\"ט אבל הוסק ביום טוב אסור ואם ראוי לצלות בו ביצה מותר","הכניס עפר לגנתו ולחורבתו מותר לכסות בו ואמר רב יהודה מכניס אדם מלא קופתו עפר ועושה בה כל צרכו","דרש מר זוטרא משמיה דמר זוטרא רבה והוא שייחד לו קרן זוית","מיתיבי כוי אין שוחטין אותו ביו\"ט ואם שחטו אין מכסין את דמו ואי איתא לכסייה כדרב יהודה","ולטעמיך לכסייה באפר כירה או בדקר נעוץ אלא דלית ליה הכא נמי דלית ליה","אי הכי מאי איריא ספק אפילו ודאי נמי לא","לא מבעיא קאמר לא מבעיא ודאי דלא לשחוט אבל ספק אימא משום שמחת יו\"ט לשחוט ולא לכסייה קמ\"ל"],[[1,"והא קא עביד גומא","וחייב משום בנין:"],[1,"פטור עליה","כדמפרש טעמא בפ\"ק דחגיגה דכיון דאינו צריך אלא לעפרה ולא לגומא אינו בונה ולא חורש אלא מקלקל וכל המקלקלים פטורים:"],[2,"מאן דכר שמיה","דקאמר שאפר כו' דמשמע דיהיב טעמא למילתיה דלעיל:"],[3,"שהוסק מערב י\"ט","מאתמול דעתיה עלויה לכל מילי:"],[3,"אבל הוסק ביו\"ט","דליכא למימר דעתיה עלויה מאתמול אסור:"],[3,"ואם ראוי לצלות בו ביצה","שיש עדיין רמץ חם:"],[3,"מותר","דמאתמול בעודם עצים היו מוכנים להסק ולבשל ולצלות ועודנו בתשמישו זה ואיידי דחזי להפוכי ביה מידי לצליית ביצה שקיל ליה נמי ומנח ליה על הדם:"],[5,"הכניס עפר","הרבה במקום אחד לצורך גנתו או לצורך חורבתו לשוטחן בהן מותר לכסות בו דכל זמן שהוא צבור דעתיה עלויה לכל צרכיו:"],[5,"מכניס אדם מלא קופתו עפר","בסתם ונותנו במקום אחד ועושה בה כל צרכיו ולא אמרינן בטלה לה לגבי קרקע הבית איידי דזוטרא:"],[6,"והוא שיחד לה כו'","ולא שטחה דמוכחא מילתא דלצרכיו קא בעי לה ובעפר תיחוח קאמר שאינו מחוסר לא חפירה ולא כתישה אלא הכנה:"],[7,"כוי","ספק חיה ספק בהמה:"],[7,"אין שוחטין אותו ביו\"ט","משום דשמא חיה הוא וצריך כסוי והוא אינו יכול לכסותו ביו\"ט כדקתני:"],[7,"ואם שחטו אין מכסין את דמו","דשמא בהמה הוא ואין בו מצות כסוי ואין מטלטלין העפר לכך:"],[7,"ואם איתא","דיש עפר שמוכן לכל צרכי אדם אפי' הוא בהמה לכסייה:"],[7,"כדרב יהודה","אם הכניס קופת עפר:"],[8,"ה\"ג ולטעמיך לכסייה בדקר נעוץ או באפר כירה","דהא בהדיא תנא במתני' דמוכן הוא:"],[9,"אפילו ודאי נמי","דהא כב\"ה קי\"ל דאסרי ואפילו דיעבד בלא דקר נעוץ:"],[10,"לא מבעיא קאמר","הא דנקט כוי אין שוחטין כל שכן חיה גמורה הטעונה כסוי והוא אינו יכול ולרבותא אשמעינן כוי ולא מיבעיא ודאי:"]],[[0,"","בעפר תיחוח והא קא עביד גומא. תימה דמשמע דשייך גומא אף בעפר תיחוח ובשבת פרק כירה (שבת דף לט. שם) אמרי' אין טומנין ביצה בחול (רב) אמר גזרה שמא יטמין ברמץ (ור' זירא) אמר גזרה שמא יזיז עפר ממקומו מאי בינייהו איכא בינייהו עפר תיחוח פירוש למ\"ד שמא יטמין ברמץ איכא למגזר אבל למ\"ד שמא יזיז אין כאן משום שמא יזיז וי\"ל דהתם מיירי שכל המקום סביב עפר תיחוח וכשמגביה הביצה אז נופל הקרקע ואין ניכר כאן שיש גומא אבל הכא מיירי שהוא קשה סביב והעפר תיחוח באמצע וא\"כ כשמגביה (הביצה) נכרת הגומא:"],[1,"","ואינו צריך אלא לעפרה פטור. משום דהוי מלאכה שאינה צריכה לגופה ופטור עליה ותימה דא\"כ פטור אבל אסור לכתחלה וי\"ל דמשום שמחת י\"ט מותר אפילו לכתחלה וא\"ת אם כן למה לי דקר נעוץ וי\"ל דמ\"מ בעינן שיהא מוכן מערב יום טוב:"],[2,"","הכי קאמר ואפר כירה מוכן הוא. ותימה דאמרי' בפרק כסוי הדם (חולין דף פח: ושם) ב\"ש אומרים אין מכסין באפר דאפר לא מקרי עפר והיכי קאמר הכא דאפר מוכן הוא לעשות כסוי לכ\"ע דהא קתני ליה גבי ושוין במתני' וי\"ל דמלתא דהכא באפי נפשה קאמר רבה כלומר ואפר הכירה מוכן הוא לענין טלטול שאר דברים כגון לכסות בו צואה וכיוצא בו אבל לא קאי אכסוי דלעיל כלל א\"נ י\"ל דהתם מיירי באפר אוכלין דאינו מגדל צמחין הלכך הואיל ואינו מגדל צמחין אין מכסין בו אבל הכא מיירי באפר עצים דמגדל צמחין ואע\"פ דלא מקרי עפר מכסין בו דקאמר דבר המגדל צמחין אע\"ג דלא אקרי עפר ואי אקרי עפר בשום מקום אע\"ג דלא מגדל צמחין מכסין בו דתניא היה הולך במדבר ואין לו עפר לכסות שוחק דינר זהב ומכסה בו היה הולך בספינה ואין לו עפר לכסות שורף טליתו ומכסה בו ופריך אשכחן אפר דמקרי עפר שנאמר ולקחו לטמא מעפר שרפת החטאת ולכך שורף טליתו ומכסה בו אלא דינר זהב מנא ליה ומשני דכתיב ועפרות זהב לו (איוב כ״ח:ו׳) ועל כרחך עפרות זהב ושריפת טלית לא מגדלי צמחים ולכך הוצרך הפסוק לומר דמקרו עפר דכל דבר המגדל צמחים מרבינן התם מקרא דוכסהו (ויקרא יז) אע\"ג דלא אקרו עפר כגון נסורת של חרשים דקה ונעורת של פשתן דקה ושחיקת כלי מתכות וא\"כ אפר הכירה וחול הדק ונעורת של פשתן וסיד ומגופה שכתשן מותר לכסות:"],[3,"","אמר רב יהודה לא שנו אלא שהוסק מערב י\"ט וכו'. נראה דהכי הלכתא דהא מייתי ליה סייעתא מברייתא ועוד דליכא מאן דפליג דאפי' ר\"ש מודה דהאי דהוסק בי\"ט דהוי נולד גמור דמעיקרא עצים והשתא אפר והויא כמיא בעיבא מבלע בליעי (עירובין דף מה:) דמודה ר\"ש וא\"ת ואנו היאך אנו מסלקין אפר הכירה בי\"ט לאפות הפשטיד\"ה אע\"ג שאין ראוי לצלות בו ביצה ואומר הר\"ר יצחק דמוקצה אינו אסור לטלטל בי\"ט בשביל אוכל נפש ושמחת י\"ט וראיה מדלקמן פרק אין צדין (ביצה דף כח:) ובירושלמי מפרש דהכא מיירי בשלא שחט אבל שחט שרי אע\"ג שהוסק בי\"ט שלא לעקור מצות כסוי:"],[5,"","ואמר רב יהודה מכניס אדם מלא קופתו עפר וכו'. וא\"ת מה בא להוסיף על הברייתא דקתני אפי' הכניס לגנתו או לחורבתו וכ\"ש מלא קופתו וי\"ל דלפי' רש\"י ניחא דכשהכניס עפר לגנתו מיירי שהכניס הרבה ביחד וכל זמן שהוא צבור דעתו עליו לכל צרכו ואינו בטל אגב קרקע אבל הכא מיירי שלא הכניס הרבה רק מלא קופתו מעט (מפני) עפר וס\"ד דיבטל אגב קרקע א\"נ י\"ל דהתם לא מיירי רק לכסות בו אבל שאר צרכיו לא והכא אשמועינן דהואיל ומלא קופתו עפר עביד בו כל צרכו:"],[7,"","ואי איתא לכסייה כדרב יהודה. משמע דקאי אסיפא וכן פי' רש\"י בסמוך בהדיא דקאי אסיפא ועל כרחך צ\"ל דקאי אסיפא דאי קאי ארישא מאי פריך לכסייה בדקר נעוץ הא ב\"ה סבירא להו דלכתחילה לא ישחוט וכו' וכי פריך הש\"ס ולעביד כב\"ש אבל תימה מדפריך בסמוך והא סיפא וכו' מכלל דעד השתא איירי ברישא וי\"ל דלעולם קאי ארישא ולא גרסינן בדקר נעוץ אלא גרס לכסייה באפר כירה עוד י\"ל דלמה שפירש ר\"ת לקמן (ביצה דף ט: ד\"ה אנ (ר ר\"י) ניחא דפירש שמוחלפת השיטה דבית הלל אומרים יחפור בדקר ויכסה וב\"ש אומרים לא ישחוט והשתא פריך אליבא דבית הלל:"],[9,"","אי הכי מאי איריא ספק אפי' ודאי נמי. תימה מאי אי אמרת בשלמא שייך הכא אפי' כי ליתא דרב יהודה שייך להקשות הכא לכסייה בדקר נעוץ וכו' וצריך לשנויי דלית ליה וי\"ל דהכי פי' אי אמרת בשלמא דלית ליה דרב יהודה לא קשיא ליה אברייתא דאיכא למימר דלית ליה דקר נעוץ ואפר כירה דבני אדם לא שכיחי שיש להם דקר נעוץ ואפר כירה שהוסק מערב י\"ט ודרב יהודה אית ליה שיש לו עפר מזומן דשכיח הוא טפי ומ\"מ אין לכסות כדרב יהודה בעפר דליתא לדרב יהודה ואין הלכה כרב יהודה ואין להקשות מאי איריא ספק וכו' הואיל וליתא לדרב יהודה ודקר נעוץ לית ליה דהא ודאי איתא לדרב יהודה לענין שמכסה בו כשהוא ודאי חיה או עוף אבל מה שאמר רב יהודה ועושה בו כל צרכו לא סבירא לן כותיה ולא שרי לכסויי בו כוי אבל כיון דאיתא לדרב יהודה צריך ליה לשנויי דלית ליה כל הני ואפי' עפר מזומן אין לו ואם כן אפי' ודאי נמי:"]]],[["והא מדקתני סיפא ואם שחטו אין מכסין את דמו מכלל (דרישא) בדאית ליה עסקינן","אלא אמר רבה אפר כירה מוכן לודאי ואין מוכן לספק","לספק מאי טעמא לא דקא עביד גומא ודאי נמי קא עביד גומא אלא כדר' אבא הכא נמי כדר' אבא","אלא ספק מאי טעמא דלמא עביד כתישה ודאי נמי נגזור משום כתישה ודאי כי קא עביד כתישה אתי עשה ודחי את לא תעשה","אימר דאמרינן אתי עשה ודחי את לא תעשה כגון מילה בצרעת א\"נ סדין בציצית","דבעידנא דקא מעקר לאו קא מוקים לעשה הכא בעידנא דקא מעקר לאו לא מוקים עשה הא לא קשיא דבהדי דכתיש קא מכסי","סוף סוף יום טוב עשה ולא תעשה הוא ואין עשה דוחה את לא תעשה ועשה","אלא אמר רבא אפר כירה דעתו לודאי ואין דעתו לספק","ואזדא רבא לטעמיה דאמר רבא הכניס עפר לכסות בו צואה מותר לכסות בו דם צפור דם צפור אסור לכסות בו צואה","נהרבלאי אמרי אפילו הכניס עפר לכסות בו דם צפור מותר לכסות בו צואה","אמרי במערבא פליגי בה ר' יוסי בר חמא ור' זירא ואמרי לה רבא בריה דרב יוסף בר חמא ור' זירא חד אמר כוי הרי הוא כצואה וחד אמר כוי אינו כצואה","תסתיים דרבא הוא דאמר כוי הרי הוא כצואה דאמר רבא הכניס עפר לכסות בו צואה מותר לכסות בו דם צפור דם צפור אסור לכסות בו צואה תסתיים","רמי בריה דרב ייבא אמר כוי היינו טעמא דלא מכסינן גזירה משום התרת חלבו","אי הכי אפילו בחול נמי בחול אמרי לנקר חצרו הוא צריך","שחט באשפה מאי איכא למימר בא לימלך מאי איכא למימר","אלא בחול [אי נמי] מספקא אמרי ליה רבנן זיל טרח וכסי ביום טוב אי מספקא מי אמרי ליה רבנן זיל טרח וכסי","תני רבי זירא לא כוי בלבד אמרו אלא אפילו שחט בהמה חיה ועוף ונתערבו דמן זה בזה אסור לכסותו ביום טוב","אמר רבי יוסי בר יאסיניאה לא שנו אלא שאין יכול לכסותו בדקירה אחת אבל יכול לכסותו בדקירה אחת מותר","פשיטא מהו דתימא נגזר דקירה אחת אטו שתי דקירות קמ\"ל","אמר) רבה שחט צפור מערב יו\"ט אין מכסין אותו ביו\"ט"],[[0,"והא מדקתני סיפא כו'","כלומר בשלמא אין שוחטין דרישא איצטריך כדקאמרת דלא תימא נשחוט משום כבוד יום טוב בלא כסוי אלא סיפא דקתני אין מכסין אי דלית ליה חדא מהני לכסות מאי איצטריך לאשמועינן השתא ודאי אין מכסין ספק מבעיא אלא שמע מינה בדאית ליה דלגבי ודאי מכסין ואשמועינן דספק לא וקשיא לן אמאי אין מכסין אי כדרב יהודה אי באפר הכירה:"],[1,"מוכן לודאי ואין מוכן לספק","קא ס\"ד דהכי קאמר אע\"ג דדעתיה לכל מילי הכנסתו מועלת לודאי ואינה מועלת לספק ופרכינן וכיון דדעתיה עלויה ומשום דאקצה ליכא ספק מ\"ט לא מכסינן משום דקא עביד גומא בתמיה:"],[2,"אלא כדר' אבא","ודאי מ\"ט שרית כדר' אבא דאמר לעיל מקלקל הוא ופטור עליה:"],[3,"דלמא קא עביד כתישה","גרסינן שמא יהו שם רגבים ויכתישם:"],[3,"ודאי נמי נגזור משום כתישה","ומשני כיון דרוב פעמים אין צריך לכתוש לא גזור רבנן משום כתישה דאי נמי אתו לידי כך לאו איסורא דאורייתא איכא דאתי עשה דוכסהו בעפר ודחי לא תעשה מלאכה דקיימא לן בפרק קמא דיבמות (דף ד.) עשה דוחה את לא תעשה:"],[4,"מילה בצרעת","דכתיב (דברים כ״ד:ח׳) השמר בנגע הצרעת ותניא בקוצץ בהרתו הכתוב מדבר ותניא בגמרא דאם לא הביא כלי במסכת שבת (קלב:) ימול בשר ערלתו אפילו במקום בהרת יקוץ:"],[4,"","אי נמי ציצית בכלאים דכתיב (דברים כ״ב:י״א) לא תלבש שעטנז וסמיך ליה גדילים תעשה לך דבשעת מילה או בשעת לבישת הטלית מעקר לאו ומקיים עשה אבל עשה זה כשהוא כותש עובר בלאו והעשה אינו מקיים עד שיכסה:"],[6,"עשה ולא תעשה הוא","דכתיב (ויקרא כג) ביום הראשון שבתון דמשמע שבות:"],[7,"ואין דעתו לספק","הלכך איסור מוקצה איכא והוא הדין לדרב יהודה:"],[8,"ואזדא רבא לטעמיה","דאמר מי שדעתו לודאי לא רמי אנפשיה לאזמוני למידי דספק:"],[8,"הכניס עפר לכסות בו צואה","ביום טוב שיש לו תינוק וירא שמא יטיל רעי ביו\"ט לפניו:"],[8,"מותר לכסות דם צפור","שיש לו לשחוט ביום טוב דכיון שהזמינו לספק כל שכן לודאי:"],[8,"אסור לכסות בו צואה","אם יש לו תינוק קטן והטיל צואה ביום טוב מאי טעמא דם צפור ודאי היה לו שישחטנו ויהא צריך כסוי אבל הצואה ספק הוא אם יארע במקום המאוס לו ודעתו לודאי ולא לספק:"],[9,"נהרבלאי אמרי","בסנהדרין (דף יז:) מפרש דהוא רמי בר בריבי:"],[9,"מותר לכסות בו צואה","כיון דאזמניה אזמניה דהא נמי קרוב לודאי:"],[10,"כוי הרי הוא כצואה","המכניס עפר לכסות בו צואה מותר לכסות בו דם כוי דזה וזה ספק:"],[10,"וחד אמר אינו כצואה","והמכניס עפר לכסות צואה אסור לכסות בו דם כוי דכוי לגבי צואה כספק לגבי ודאי דצואת תינוק שכיחא וקרובה לודאי:"],[11,"תסתיים דרבא הוא דאמר","צואה כספק וכוי מותר בהזמנת צואה:"],[11,"דאמר רבא הכניס עפר לכסות בו צואה מותר לכסות בו דם צפור דם צפור אסור לכסות בו צואה","אלמא ספק הוא:"],[12,"משום התרת חלבו","דאי שרית לכסוייה אתי למימר חיה הוא:"],[13,"בחול אמרי לנקר חצרו כו'","הרואה אומר לא מפני שטעון כסוי אלא כדי לנקר חצרו מכסהו:"],[14,"לא גרסינן ולטעמיך אלא הכי גרסינן בא לימלך מאי איכא למימר","מי שיש לו כוי ובא לימלך לחכמים אם צריך לכסותו ובחול והם מורים לו שצריך כסוי:"],[14,"מאי איכא למימר","איהו גופיה אתי למימר חיה הוא דהא מצרכו ליה כסוי:"],[15,"אלא","לא גרסינן:"],[15,"בחול אי נמי ספקא הוא כו'","כלומר בחול זה שהורוהו לכסות לא מחזיק ליה בחיה ודאית דמימר אמר אי נמי מספקא להו לרבנן אי חיה אי בהמה אמרי ליה זיל טרח וכסי כו' אמרי ליה גרסינן:"],[16,"לא כוי בלבד אמרו","דאין מכסין ביום טוב דדין הוא שלא יכסוהו שמא בהמה היא וטרח טרחא דלא מצוה ואפילו באפר הכירה:"],[16,"אלא אפילו שחט כו'","דאיכא חד דטעון כסוי אפילו הכי אין מכסין משום דקא טרח נמי בשל בהמה:"],[18,"פשיטא","דהא לא טרח בשביל בהמה מידי:"],[19,"אין מכסין אותו ביו\"ט","דהיה לו לכסות מבעוד יום ומשום אמנועי משום שמחת יום טוב ליכא דמשום דלא מכסי דם לא מתסר צפור באכילה:"]],[[0,"","והא מדקתני סיפא ואם שחטו וכו'. ואם תאמר אמאי לא פריך אי לית ליה פשיטא דאין שוחטין דבמאי יכול לכסות ופירש הקונט' דאי קאי ארישא הוה אמינא דלשחוט ולא לכסייה משום שמחת י\"ט אלא אסיפא דקתני אין מכסין אי דלית ליה חדא מהני איצטריך למימר אין מכסין אותו השתא ודאי אין אנו מכסין כב\"ה דאסרי אפי' דיעבד בלא דקר נעוץ ספק מבעיא אלא שמע מינה בדאית ליה דודאי מכסין אבל ספק לא והדר קושיא לדוכתין לכסייה כדרב יהודה או באפר כירה:"],[7,"","סוף סוף יו\"ט עשה ולא תעשה אלא אמר רבא וכו'. ותימה דהכא משמע לרבא דאית ליה עשה ולא תעשה מדדחיק נפשיה לשנויי ובפרק במה מדליקין (שבת דף כד: שם) אמר רבא הוא ולא מכשיריו לבדו ולא מילה שלא בזמנה ורב אשי אמר יום טוב עשה ולא תעשה וכו' משמע דרבא לית ליה ההוא טעמא וי\"ל דגמרא דחיק נפשיה לאוקומי מילתא דרבא אליבא דהלכתא די\"ט עשה ולא תעשה אע\"ג דרבא עצמו לית ליה האי סברא:"],[16,"","תני ר' זירא לא כוי בלבד אמרו וכו'. וא\"ת וכי יש כח ביד חכמים לעקור דבר שהוא מן התורה דהא כסוי דאורייתא דכתיב וכסהו בעפר וי\"ל דאין הכי נמי דשב ואל תעשה יש כח בידם:"]]],[["גלגל עיסה מערב יום טוב מפריש ממנה חלתה ביום טוב אבוה דשמואל אמר אפילו גלגל עיסה מערב יום טוב אין מפריש ממנה חלתה ביום טוב","לימא פליגא דשמואל אדאבוה (דשמואל) דאמר שמואל חלת חוצה לארץ אוכל והולך ואח\"כ מפריש","אמר רבא מי לא מודה שמואל שאם קרא עליה שם שאסורה לזרים:","\u0001מתני׳\u0002 בית שמאי אומרים אין מוליכין את הסולם משובך לשובך אבל מטהו מחלון לחלון ובית הלל מתירין:","\u0001גמ׳\u0002 אמר רב חנן בר אמי מחלוקת ברשות הרבים דבית שמאי סברי הרואה אומר להטיח גגו הוא צריך ובית הלל סברי שובכו מוכיח עליו אבל ברשות היחיד דברי הכל מותר","איני והא אמר רב יהודה אמר רב כל מקום שאסרו חכמים מפני מראית העין אפילו בחדרי חדרים אסור תנאי היא דתניא שוטחן בחמה אבל לא כנגד העם רבי (אליעזר) ורבי שמעון אוסרין","איכא דאמרי אמר רב חנן בר אמי מחלוקת ברשות היחיד דבית שמאי אית להו דרב יהודה אמר רב ובית הלל לית להו דרב יהודה אמר רב אבל ברשות הרבים דברי הכל אסור","לימא רב דאמר כבית שמאי","תנאי היא דתניא שוטחן בחמה אבל לא כנגד העם רבי (אליעזר) ורבי שמעון אוסרין"],[[0,"גלגל עיסה מערב י\"ט מפריש ממנה חלתה בי\"ט","ואע\"ג דתנן לקמן (ביצה דף לו:) אלו הן משום שבות אין מגביהין תרומות ומעשרות בי\"ט והא נמי כתרומת דגן דמיא שהיה יכול להפרישה מערב י\"ט אפילו הכי מפריש שלא גזרו על תרומת עיסה שהרי מותר לגלגלה בי\"ט ולאפותה כדי לאכול פת חמה:"],[0,"אין מפריש הימנה","דלא התירו להפריש חלה אלא בעיסה שנתגלגל בי\"ט אבל זו היה לו להפריש מערב יו\"ט כתרומת דגן ופירות:"],[1,"חלת [חו\"ל]","חלה טורטי\"ל חלה שמרימין מן העיסה שבחוצה לארץ הואיל ואינה מן התורה כדקיימא לן בקדושין (דף לו:) כל מצוה התלויה בפירות הגדלים בארץ אינו נוהג אלא בארץ:"],[1,"אוכל והולך","כל הפת ומשייר כדי חלה ומפרישה באחרונה אלמא הפרשתה שלא לצורך היא ולא הויא הפרשה והמפריש בי\"ט אינו כמתקן דלתסר כשאר הגבהת תרומה דגזור בה רבנן מפני שנראה כמתקן:"],[2,"מי לא מודה שמואל","אע\"פ שאינו צריך להפרישה שאם קרא עליה שם שחל עליה שם חלה ואסורה לזרים אלמא שם תרומה עליה ואיתא בכלל אין מגביהין תרומות ומעשרות ביו\"ט:"],[3,"מתני' אין מוליכין את הסולם","קס\"ד סולם המיוחד לכך וניכר שהוא של שובך וטעמא דב\"ש מפרש בגמרא דאסרי ואע\"פ שהוא בא ליטול גוזלות לשמחת י\"ט:"],[3,"מחלון לחלון","באותו שובך עצמו שכן דרך שובך להיות בו מחיצות הרבה קן לכל זוג וזוג וחלון לכל קן וקן:"],[4,"גמ' הרואה","שהוא מוליכו אומר להטיח גגו הוא צריך והרי הוא עושה מלאכה ביום טוב:"],[4,"להטיח","שהיו טחין גגותיהן בטיט לפי שלא היו משופעין אלא עשויין כמין תקרת עליה ומשתמשין בהן לפיכך טחין אותן ומשפעין הטיח לצד הכתלים שיזובו מימיו:"],[4,"שובכו מוכיח עליו","שובכו של סולם מוכיח שהוא ניכר שהוא של שובך:"],[4,"מותר","שהרי אין אדם רואהו:"],[5,"והאמר רב יהודה אמר רב כו'","וקשיא דרב אדרב חנן ואע\"ג דרב אמורא הוא מקשי מיניה מפני שרבן של כל בני הגולה היה בדורו חוץ משמואל:"],[5,"תנאי היא","איכא תנא דקאי כוותיה:"],[5,"שוטחן בחמה","מי שנשרו כליו בדרך במי גשמים שוטחן בחמה והן נוגבין מאליהן:"],[5,"אבל לא כנגד העם","שלא יאמרו כבסן בשבת אלמא מידי דמשום מראית העין מותר במקום צנוע:"],[7,"לימא רב דאמר כב\"ש","לרב חנן קא פריך דאוקי לה בית הלל ברה\"ר אסרי וברשות היחיד שרו א\"כ לרב חנן רב דאמר כל מקום שאסרו כו' דאמר כב\"ש בתמיה הא ודאי לא שביק ב\"ה ועביד כב\"ש ועל כרחך לבית הלל אפי' ברשות הרבים מותר משום דשובכו מוכיח עליו דאי ברה\"ר אסור וברשות היחיד שרי לא הוה אמר רב להא שמעתא:"],[8,"תנאי היא","כלומר אמר לך רב חנן ודאי רב סבר דבית הלל אפילו בר\"ה שרו ופליג עלי ואנא דאמרי כי האי תנא דאמר שוטחן בחמה דלית ליה דרב וההוא תנא מוקי בית הלל כוותיה דלא התירו אלא ברשות היחיד ורבי אליעזר ור\"ש דסבירא להו כרב מוקמי שריותא דבית הלל דמתניתין ואפי' ברה\"ר דקא סברי שובכו מוכיח עליו וב\"ש לית להו שובכו מוכיח עליו ואסרי אפי' בחדרי חדרים י\"מ דלרב קא פריך ואמר לך רב תנאי היא ולאו מלתא היא דמאי רבותייהו דרבי אלעזר ור' שמעון במקום בית הלל הא ב\"ש נמי טובא הוו ואין הלכה כמותן:"]],[[0,"","גלגל עיסה מערב י\"ט מפריש חלה בי\"ט. פרש\"י דאע\"ג דאין מגביהין תרומות ומעשרות בי\"ט והא נמי כתרומת גורן דמיא שהוא היה יכול להפריש מעי\"ט דהא מאתמול התחיל זמנה להפריש דתנן (חלה פ\"ג) מאימתי חיוב חלה משגלגל אפילו הכי מפרישין לה שלא גזרו על תרומת עיסה שהרי מותר לגלגל בי\"ט ולאפות כדי לאכול פת חמה ואז מותר להפריש ממנה חלה כיון שבי\"ט נלושה א\"כ לא היה הפרשת חלה בכלל איסור הגבהת תרומה ואפי' כשגלגלה מבעוד יום עי\"ל דלפי הירושלמי ניחא דקמיירי שלא גמר הלישה מעי\"ט ואע\"ג דסוף סוף היה יכול להפריש מבעוד יום משעת גלגול מכל מקום אחר שנגמרה הלישה בי\"ט הוה ליה כאילו נעשית כל הלישה בי\"ט שרגילות שלא להפריש חלה עד גמר הלישה ולעולם הפרשת חלה הוי בכלל הגבהת תרומה היכא דהיה לו להפריש מאתמול אבל לא מצי למימר דלהכי מחלק בין כסוי משום דגבי כסוי לא ממנע משמחת י\"ט דאין הכסוי מעכב האכילה אבל הפרשת חלה מעכב אכילה דזה אינו דהא מיירי הכא בחוצה לארץ כדאמר בסמוך וא\"כ אוכל ואחר כך מפריש דמשמע דליכא מאן דפליג בזה ובתוספתא פי' דטעמא דרבה דמיירי בחוצה לארץ ולא מחזי כמתקן כיון שבלאו הכי יוכל לאכול אבל בא\"י מודה רבה ואין נראה דמשמע בסמוך דלא שייך כלל לומר זה הטעם דקאמר מי לא מודה שמואל שאם קרא וכו' א\"כ כיון דשם חלה עליה מיחזי כמתקן ומשמע לפי הלשון דסברא זו פשוטה ולכך נראה עיקר כדפי' לעיל דאפי' בא\"י מתיר רבה ואבוה דשמואל אסר אפי' בחו\"ל ותדע דהא ודאי הירושלמי מיירי בא\"י ואפילו הכי לא קא אסר אלא היכא דלש אבל ערס שרי דהיינו גלגל ונראה דהלכה כרבה דהוא בתראה ודוקא גלגל שלא נגמרה לישתה לגמרי דאי נגמרה לגמרי אפילו רבה מודה דאין מפרישין אותה בי\"ט והכי נמי איתא בירושלמי כל הלש עיסה מעי\"ט אין מפרישין חלתה בי\"ט וקאמר לש אין ערס לא וה\"פ דוקא לש דנגמרה מערב י\"ט אין מפרישין אבל ערס לא דלא נגמרה הלישה מערב י\"ט מפריש והכא נמי מיירי בגלגל שהוא כמו ערס והיכא דשכח ולא הפריש מן הפת מעי\"ט קי\"ל דחלת חו\"ל אוכל והולך ואח\"כ מפריש וא\"כ ישייר מן הפת מכל אחד ואחד ואוכל השאר ולמחר יפריש חלה וצריך שתהא גדולה כדי שיהיה לה הכירא אחר הפרשה דכתיב (במדבר טו) ראשית דבעינן שיהיו שיריה ניכרין והיכא דאפה עריבה מלאה עיסה מערב י\"ט ושכח ולא הפריש חלה מערב י\"ט ישייר פת אחת בשביל כולם עד למחר מפני שגבלן כאחד אבל במצות בערב הפסח אם שכח ולא הפריש צריך לשייר מכל אחת ואחת מפני שגיבולן כל אחת ואחת בפני עצמה ולמחר יניח כל החתיכות בסל אחד ומצרפן לחלה ויפריש מן כולם אחת ומיהו אם ירצה לעשות דבר קל יעשה מצה אחת ויאפה אותה ויצרפם ויפריש [מאחת על] כל האחרות אגב אותה מפני שחיובה בא עכשיו:"],[3,"","אין מוליכין הסולם. תימה אפי' הכין אותם מאתמול מ\"מ אית בהו משום צידה כדאמרינן לקמן (ביצה דף כד.) הצד יוני שובך [ויוני עליה] חייב וי\"ל דמיירי בקטנים שלא פרחו:"],[5,"","והאמר רב יהודה אמר רב. אף על גב דרב היה אמורא מ\"מ פריך שפיר כיון דרב גדול היה בדורו וראש ישיבה לישראל חוץ משמואל אין סברא דרב חנן פליג עליה:"],[7,"","ורב כבית שמאי. פרש\"י ומקשה לרב חנן דמוקי דבית הלל לית להו דרב וברה\"ר דברי הכל אסור ואפילו ב\"ה אסרי וברשות היחיד שרו (ואדרבה) רב לא יאמר הכי דלא יאמר דלא כהלכתא אלא יאמר דב\"ה שרו אפילו ברה\"ר דשובכו מוכיח עליו ודלא כוותך ומשני תנאי היא כלומר רב חנן אמר לך אין הכי נמי דרב סבר דבית הלל שרו ברה\"ר ופליג עלי ואנא דאמרי כי ההוא תנא דשוטחן דלית ליה דרב וההוא תנא מוקי לה בית הלל כוותיה דלא התירו אלא ברשות היחיד וי\"מ דלרב קא פריך ואמר לך רב תנאי היא דסבירא להו כב\"ש ואנא סבירא לי כהני תנאי ולא נראה דמאי אולמייהו דרבי אליעזר ור\"ש לגבי בית הלל הא ב\"ש טובא תנאי הוו ואע\"פ כן אין הלכה כמותם:"]]],[["מתניתין דלא כי האי תנא דתניא אמר רבי שמעון בן אלעזר מודים ב\"ש וב\"ה שמוליכין את הסולם משובך לשובך לא נחלקו אלא להחזיר שב\"ש אומרים אין מחזירין וב\"ה אומרים אף מחזירין","אמר רבי יהודה במה דברים אמורים בסולם של שובך אבל בסולם של עליה דברי הכל אסור ר' דוסא אומר מטהו מחלון לחלון אחרים אומרים משום רבי דוסא אף מדדין בו","בני רבי חייא נפוק לקרייתא כי אתו אמר להו אבוהון כלום מעשה בא לידכם אמרו לו סולם בא לידינו והתרנוהו אמר להם צאו ואסרו מה שהתרתם","אינהו סבור מדקא אמר רבי יהודה בסולם של עליה לא פליגי מכלל דתנא קמא סבר פליגי ולא היא רבי יהודה טעמיה דתנא קמא קא מפרש","ממאי מדקתני מוליכין את הסולם משובך לשובך ואי סלקא דעתך בסולם של עליה פליגי האי מוליכין את הסולם משובך לשובך מוליכין את הסולם לשובך מבעי ליה אלא לאו הכי קאמר של שובך אין של עליה לא","ואידך מי קתני סולם של שובך משובך לשובך קתני ואפי' לכמה שובכין","איכא דאמרי אמרו לו הטוי סולם של עליה בא לידינו והתרנוהו אמר להם צאו ואסרו מה שהתרתם אינהו סבור מאי דקא אסר תנא קמא קא שרי רבי דוסא ולא היא מאי דקא שרי תנא קמא קא אסר רבי דוסא:","אבל מטהו מחלון לחלון וכו': אלמא גבי שמחת יו\"ט ב\"ש לחומרא וב\"ה לקולא","ורמינהי השוחט חיה ועוף ביום טוב ב\"ש אומרים יחפור בדקר ויכסה וב\"ה אומרים לא ישחוט אא\"כ היה לו עפר מוכן מבעוד יום","אמר רבי יוחנן מוחלפת השיטה ממאי דלמא עד כאן לא קאמרי ב\"ש התם אלא היכא דאיכא דקר נעוץ אבל היכא דליכא דקר נעוץ לא","ואי נמי עד כאן לא קאמרי בית הלל הכא אלא דשובכו מוכיח עליו אבל התם לא","אלא אי קשיא הא קשיא בית שמאי אומרים לא יטול אלא אם כן נענע מבעוד יום וב\"ה אומרים עומד ואומר זה וזה אני נוטל","אלמא גבי שמחת יו\"ט ב\"ש לחומרא וב\"ה לקולא ורמינהי השוחט חיה ועוף ביו\"ט אמר רבי יוחנן מוחלפת השיטה","ודלמא לא היא עד כאן לא אמרי ב\"ש אלא היכא דאיכא דקר נעוץ"],[[0,"מתניתין","דקתני בהולכת סולם פליגי לאו כי האי תנא דקתני בהולכה מודו מפני שצורך י\"ט היא:"],[1,"אבל של עליה אסור","דההוא ודאי אמרי להטיח גגו הוא צריך:"],[1,"מדדין בו","אם החלון רחוק ואין ראש הסולם מגיע שם בה בהטיה מדדין רגליו של סולם מעט מעט:"],[2,"לקרייתא","לכפרים לראות שדותיהן:"],[2,"סולם בא לידינו","הולכת סולם של עליה לשובך:"],[3,"מכלל דת\"ק סבר","בשל עליה פליגי בחזרה ומודים בהולכה:"],[3,"טעמיה דת\"ק קא מפרש","ובשל עליה ליכא למאן דשרי:"],[4,"ממאי מדקתני","במלתיה דת\"ק משובך לשובך אלמא בסולם המיוחד לשובכין קאי:"],[5,"מי קתני סולם של שובך","דנהוי משמע דבשל שובך קאי:"],[5,"משובך לשובך קתני","ולעולם בשל עליה ורבותא אשמועינן דיוליכנו מעליה לשובך ראשון וממנו לכמה שובכין:"],[6,"הטוי סולם של עליה","והוליכו לשובך מבעוד יום ועכשיו בא להטותו מחלון לחלון:"],[6,"מאי דקא אסר ת\"ק","דרבי דוסא דהוא ר' יהודה דאמר בסולם של עליה אסור להוליך קא שרי רבי דוסא מיהא להטות:"],[6,"ולא היא מאי דקא שרי ת\"ק","דהיינו של שובך להוליך קא אסר ר' דוסא ואתא למימר הולכה אסור הטיה שרי ובשל עליה לא איירי כלל:"],[9,"מוחלפת השיטה","כאן הוחלפה שיטתן וצריך להפוך דבריהם:"],[9,"וממאי דמוחלפת","ומאי קשיא ליה לר' יוחנן דלמא טעמייהו דב\"ש התם משום דאיכא דקר נעוץ וליכא צד איסור:"],[9,"אבל היכא דליכא דקר נעוץ","דאיכא צד רמז חפירה לא שרו ואפי' בעפר תיחוח שהוא כחפור ועומד והכא נמי לא שנא דהא איכא חשדא דלהטיח גגו:"],[10,"אבל התם לא","דגזרי משום כתישה דלמא זמנין דבעי כתישה:"],[11,"אלא אי קשיא","מתניתין אהדדי שהוצרך רבי יוחנן להחליף שיטתן וצריך להפוך דבריהם:"],[11,"הא קשיא","על זו החליפה:"],[11,"לא יטול","מן הגוזלות בי\"ט:"],[11,"אא\"כ נענע מבעוד יום","ולא סגי בהכנה בדבור בעלמא כדמפרש לקמן טעמא דלמא למחר כי שקיל להו חייס עלייהו וממליך:"]],[[3,"","ולא היא דר\"י טעמא דת\"ק מפרש. וא\"ת והא כל מקום דתני במה לחלוק וי\"ל דהיינו במשנה אבל לא בברייתא:"],[6,"","מאי דקא שרי ת\"ק קא אסר רבי דוסא. דאפי' בשאר סולמות לא שרי אלא הטוי ותימה רבי דוסא דאמר כמאן דלכ\"ע שרי הולכה בשאר סולמות וי\"ל דר' דוסא יאמר דלא נחלקו ב\"ש וב\"ה בדבר זה משמע דקי\"ל כר' דוסא ותימה דאמר בעירובין פרק חלון (עירובין דף עז: ושש) מטלטלין את הסולם ובכולי שמעתין משמע דאסור לטלטל סולם של עליה ור' דוסא אוסר אפי' סולם של שובך וי\"ל דשני מיני סולמות הן וכן משמע בהדיא פרק חלון (עירובין דף עז:) והתם מיירי בקטנים והכא מיירי בגדולים והר\"ר אברהם מבורגו\"ל פירש דהתם מיירי בשבת דמאי טעמא אסרי לטלטל הסולם משום דמחזי דלהטיח גגו הוא צריך ובשבת ליכא חששא שאסור להוציאו לחוץ אבל הכא מיירי ביום טוב דמותר להוציאו לחוץ וא\"כ איכא הך חששא ולפי זה אסור לטלטל הסולם שלנו בי\"ט ואפילו בביתו דשמא הלכה כרבי דוסא וצ\"ע:"],[7,"","אלמא גבי שמחת י\"ט ב\"ש לחומרא וכו'. וא\"ת אמאי לא פריך מביצה שנולדה ופי' הקונט' משום דגבי ביצה לא שייך שמחה שאין בה שמחת י\"ט כ\"כ ומה שמתירין ב\"ש היינו מטעם דלית להו הכנה ומטעם דלא דמי לפירות הנושרים ולמשקין שזבו:"],[9,"","אמר ר' יוחנן מוחלפת השיטה. פירוש ההיא דתריסין דב\"ה סברי אין מסלקין התריסין בי\"ט וכל הנך משניות דמייתי מחליף ואותה דהשוחט כדקאי קאי וקשה טובא להדא פי' דא\"כ מתוקמא לפי המסקנא כל הני שנויי דחיקי דלעיל דמייתי הואיל ולא מחליף בשום פנים אותה דהשוחט ועוד קשה מאי קאמר גבי עור משום דמחזי למזגא עליה הא מפרש טעמא לקמן (ביצה דף יא:) דהתירו סופן משום תחלתן וע\"ק דא\"כ דאותה דהשוחט נשארת במקומה א\"כ רבה ורב יוסף שקלו וטרו (לעיל ביצה דף ז:) אליבא דב\"ש וזהו דוחק גדול ועוד קשה כיון דמוחלפת ההיא דתריסין סבירא להו לב\"ה דאין מסלקין משום דיש בנין וסתירה בכלים ובריש פרק כל הכלים (שבת דף קנב: ושם) סתים לן תנא דאין בנין וסתירה בכלים לכך פר\"ת דמוחלפת השיטה היינו ההיא דהשוחט דב\"ה סברי יחפור בדקר ויכסה וכו' והשתא ניחא הכל ואומר ר\"ת תמיה אני על מה הצריכו העולם הכנה וזכור אני דבימי נערותי לא הוי מצריכין כלל אך עתה לפי מה שטעו דסבורים דמוחלפת לא קאי אהשוחט וכו' וב\"ה לחומרא לפיכך מצריכין הכנה ומיהו זה אינו דלפי פירושו נמי לכל הפחות סברי ב\"ה מאי דסברי ב\"ש מעיקרא וב\"ש בעו דקר נעוץ ואפי' בעפר תיחוח בעו הכנה מדקאמר הכא עד כאן לא קאמרי ב\"ש התם אלא דאיכא דקר נעוץ משמע אפילו בעפר תיחוח בעו ב\"ש דקר נעוץ מבעוד יום משום הכנה כדפ\"ה ותדע דאל\"כ הא דקאמר רב יהודה לעיל והוא שיש לו דקר נעוץ לאו אליבא דב\"ה הוא לפי המסקנא דאמרי ב\"ה שיחפור בדקר לכתחלה וישחוט ואע\"ג דמייתי מלתיה דרב יהודה גבי ומודים מכל מקום קאי אכולה מתניתין כדפרישית וסברא היא דלא פליגי ב\"ש וב\"ה אלא בהא דבכה\"ג דשרו ב\"ש בדיעבד שרו ב\"ה לכתחילה ולעולם בעו דקר נעוץ משום הכנה ועוד ראיה מדקאמר רב יהודה גופיה לעיל (ביצה דף ח.). ממלא קופתו ועושה בה כל צרכו משמע דבעינן הכנה לפי האמת ואע\"פ שיש לפרש דבשאר צרכים מיירי כגון לכסות בו צואה אבל לכסוי דם לא בעינן הכנה לא משמע הכי לעיל לפי המסקנא וגם עתה דאמר מוחלפת השיטה אין להחליף פירוש דברי האמוראין וא\"כ יפה נהגו העולם שלא לכסות רק בעפר מוכן שהוא תיחוח כגון מצבור של אפר או שראוי לצלות בו ביצה ולא מעפר תיחוח שע\"ג קרקע שהוא בטל אגב קרקע ולא מאפר הכירה שהוסקה בי\"ט אם אינו ראוי לצלות בו ביצה ותימה א\"כ דמוחלפת קאי אההיא דהשוחט ובית שמאי לחומרא היכי מונה לה במסכת עדיות גבי הנך דב\"ש לקולא ובית הלל לחומרא וי\"ל דמונה לה לפי הטעות דנשנית קודם דמוחלפת השיטה:"]]],[["אבל היכא דליכא דקר נעוץ לא אי נמי עד כאן לא קאמרי בית הלל הכא אלא כיון דמוקצה הוא בעומד ואומר זה וזה אני נוטל סגי אבל התם לא","אלא אי קשיא הא קשיא בית שמאי אומרים אין נוטלין את העלי לקצב עליו בשר ובית הלל מתירין אלמא גבי שמחת יום טוב בית שמאי לחומרא ובית הלל לקולא ורמינהי השוחט חיה ועוף בית שמאי וכולי אמר רבי יוחנן מוחלפת השיטה","ממאי דלמא לא היא עד כאן לא קאמרי בית שמאי התם אלא היכא דאיכא דקר נעוץ אבל היכא דליכא דקר נעוץ לא אי נמי עד כאן לא קאמרי בית הלל הכא אלא דאיכא תורת כלי עליו אבל התם לא","אלא אי קשיא הא קשיא בית שמאי אומרים אין נותנין את העור לפני הדורסן ולא יגביהנו אלא אם כן יש עליו כזית בשר ובית הלל מתירין","אלמא גבי שמחת יום טוב בית שמאי לחומרא ובית הלל לקולא ורמינהי השוחט חיה ועוף ביום טוב וכולי אמר רבי יוחנן מוחלפת השיטה","ממאי דלמא לא היא עד כאן לא קאמרי בית שמאי התם אלא היכא דאיכא דקר נעוץ אבל היכא דליכא דקר נעוץ לא אי נמי עד כאן לא קאמרי בית הלל הכא אלא דחזי למזגא עלויה אבל התם לא","אלא אי קשיא הא קשיא בית שמאי אומרים אין מסלקין את התריסין ביום טוב ובית הלל מתירין אף להחזיר אלמא גבי שמחת יום טוב בית שמאי לחומרא ובית הלל לקולא ורמינהי השוחט חיה ועוף ביום טוב וכולי","בשלמא בית שמאי אבית שמאי לא קשיא התם דאיכא דקר נעוץ הכא ליכא דקר נעוץ אלא בית הלל אבית הלל קשיא","אמר רבי יוחנן מוחלפת השיטה (אי נמי) עד כאן לא קאמרי בית הלל הכא אלא משום דאין בנין בכלים ואין סתירה בכלים אבל התם לא:","\u0001מתני׳\u0002 בית שמאי אומרים לא יטול אלא אם כן נענע מבעוד יום ובית הלל אומרים עומד ואומר זה וזה אני נוטל:","\u0001גמ׳\u0002 אמר רב חנן בר אמי מחלוקת בבריכה ראשונה דבית שמאי סברי גזרינן דלמא אתי לאמלוכי","ובית הלל סברי לא גזרינן אבל בבריכה שניה דברי הכל בעומד ואומר זה וזה אני נוטל סגיא","ובית הלל למה ליה למימר זה וזה אני נוטל לימא מכאן אני נוטל למחר","וכי תימא בית הלל לית להו ברירה והתנן המת בבית ולו פתחים הרבה כולן טמאים","נפתח אחד מהן הוא טמא וכולן טהורין חשב להוציאו באחד מהן או בחלון שיש בו ארבעה על ארבעה מצלת על כל הפתחים כולן","בית שמאי אומרים והוא שחשב להוציאו עד שלא ימות המת ובית הלל אומרים אף משימות המת","הא אתמר עלה אמר רבה לטהר את הפתחים מכאן ולהבא וכן אמר רבי אושעיא לטהר את הפתחים מכאן ולהבא מכאן ולהבא אין למפרע לא","רבא אמר לעולם למפרע והכא היינו טעמא דלמא מטלטל ושביק מטלטל ושביק וקא מטלטל מידי דלא חזי ליה","והא אמרת בעומד ואומר זה וזה אני נוטל סגיא הני מילי מערב יום טוב"],[[0,"אבל היכא דליכא דקר נעוץ לא","והא נמי להא דמיא דלמא ממליך ואשתכח דטלטלה בכדי דכיון דממליך בטלה לה הזמנה למפרע:"],[0,"אלא כיון דמוקצה הוא","כיון דאינו אסור אלא משום מוקצה בהזמנה בעלמא סגי:"],[1,"את העלי","דף עב וכבד וכותשין בו חטים לטרגיס וטיסני והוי מלאכתו לאיסור וקא סברי ב\"ש אסור לטלטלו ואפי' לצורך גופו שצריך לגוף הכלי למלאכה המותרת היום:"],[2,"תורת כלי עליו","ואף על פי שמלאכתו לאיסור מותר לטלטלו לצורך גופו:"],[3,"אין נותנין את העור","שהופשט ביום טוב:"],[3,"לפני הדורסן","לא ישטחנו במקום דריסת הרגלים שזהו צורך עבוד שמתעבד ע\"י הדריסה:"],[3,"ובית הלל מתירין","קס\"ד משום שמחת יום טוב דאי לא שרית ליה לא שחיט:"],[5,"למזגא עליה","כן היתה ישיבתם שוטחין בגדים על גבי הקרקע ונסמכין ויושבין על ברכיהן כפופין כדאמרינן בפסחים (דף קח.) הוה זגינן אברכי דהדדי ונמצאת שטיחתו צורך י\"ט:"],[6,"תריסין","דלתות החלונות של חנויות שסוגרין בהן החלונות בלילה ומסלקין אותם ביום ונותנין אותן לפניהם ושוטחין עליהן תבלין למכור לרבים ובי\"ט מותר ליקח מחנוני המכיר אותו ובלבד שלא יזכיר סכום מקח:"],[6,"אף להחזיר","ולסגור בהן וחזרה ודאי שלא לצורך היא ואפילו דאמרינן אין בנין בכלים טרחא דלאו צורך מיהא הוה וקא שרינן ליה משום תחלתן כדלקמן אלמא משום שמחת י\"ט מקילינן וקשיא ב\"ה דכסוי:"],[7,"הכא ליכא דקר נעוץ","כלומר ליכא טעמא להתירא דקא סברי יש בנין בכלים:"],[9,"מתני' עומד ואומר","מבעוד יום:"],[10,"גמ' בבריכה ראשונה","דרך מגדלי יונים להניח בריכה ראשונה של כל שנה להיות צוות לאמה:"],[10,"גזרינן","כי שקיל להו למחר אתי לאמלוכי וחייס עלייהו והוי ליה טלטול שלא לצורך ומשנענע ומשמש בהן מבעוד יום לשחיטה ולא חס עלייהו תו לא חיישינן דחייס:"],[11,"בריכה","קובי\"ד בלע\"ז שהיונים יולדים בריכה בכל חדש וחדש והן שני גוזלות זכר ונקבה ומפסיקין בתקופת טבת וחוזרים ויולדים בניסן:"],[13,"לית להו ברירה","וכי שקיל למחר דלמא לא הני אזמין והוא לא הזמין את כולם אלא כדי צרכו:"],[13,"ולו פתחים הרבה","כולם פתוחים או כולם סגורים:"],[13,"כולם טמאים","כל כלים המונחים בחלל הפתחים תחת עובי התקרה של פתח טמאים ואע\"פ שאינו תחת הגג המאהיל על המת שגזרו חכמים טומאה על מקום שהוא דרך יציאת הטומאה שסופו לצאת דרך שם וכאן אין אנו יודעים באיזה יוציאנו הלכך כולם טמאים:"],[14,"נפתח אחד מהם","לאחר מיתת המת:"],[14,"הוא טמא","בין כלים דמעיקרא בין כלים דלבסוף המובאין לו מבחוץ:"],[14,"וכולן טהורים","לדברי הכל מוקמינן להו דמודו הכל מכאן ולהבא בכלים המובאים לתוכן אחרי כן מבחוץ דודאי בההוא דנפתח מפיק ליה:"],[14,"ארבעה על ארבעה","בכך שערוהו שראוי להוצאת מתים:"],[14,"מצלת על כל הפתחים","מלטמא כאילו נפתח:"],[15,"אף משימות המת","וקס\"ד דבברירה פליגי ובכלים שהיו בהם בין מיתה למחשבה ב\"ש סברי לא אמרי' הוברר דמעיקרא דעתיה להכי הואי ולא ירדה הטומאה לשאר הפתחים ובית הלל סברי הוברר ולמאי דס\"ד השתא סבירא לן דבנפתח אחד מהם נמי הוו פליגי בכלים דמעיקרא וטהורין דקא תני לעיל לדברי הכל בכלים דמכאן ולהבא:"],[16,"הא אתמר עלה כו'","ואפי' בית הלל לית להו הוברר ואין מטהרין אלא כלים דלבסוף דלאחר מחשבה אבל הראשונים טמאים וב\"ש מטמאין אף האחרונים דקא סברי משירדה תורת טומאה לפתחים לפני מחשבה במיתת המת שוב אינו עולה מהם אלא על ידי מעשה כגון נפתח ובנפתח אחד מהם לא פליגי מידי:"],[17,"רבא אמר לעולם למפרע","נמי מטהרין בית הלל דאית להו ברירה והכא במתניתין היינו טעמא דצריך לברר ולומר אלו אני נוטל דלמא למחר מטלטל ובודק השמנים ושביק הא ושקיל אידך נמצא מטלטל מה שלא הזמין שהרי לא היה דעתו אלא בכדי צרכו הלכך אומר זה וזה אני נוטל ולמחר על כרחיה הני מילי דשקיל:"],[18,"והא אמרת בעומד","מרחוק ואין מנענע סגיא אלמא לא בדק מאתמול הכחושים והשמנים ואכתי איכא למיחש:"],[18,"ה\"מ מערב י\"ט","כלומר היכא דידע מערב י\"ט דהני הוא דאזמינן דתו בין שהן כחושין בין שהן שמנים לא שקיל אחריני שהרי יודע שמוקצין הם שלא זמנן:"]],[[16,"","ב\"ש אומרים והוא שחשב עליו וכו' וב\"ה אומרים אף משימות המת. וקא סלקא דעתך דמיירי בכלים דלמפרע וה\"ה דפליגי כשנפתח אחד מהם ובכלים דלמפרע והא דקאמר לעיל נפתח אחד מהם הוא טמא והן טהורין ולא פליגי ב\"ש מיירי בכלים הבאים אחר כן שם ותימה אדפליגי בחשב ליפלגו בנפתח ובכלים דלמפרע וי\"ל דנקט חשב משום רבותא דב\"ה דאפי' במחשבה דעלמא פליגי דמועיל להציל כל הפתחים אחרים אבל תימה לב\"ה דאית להו ברירה היכי משכחת כשמת בבית ולו פתחים הרבה דכולן טמאים הא איכא למימר לבסוף כשמוציאין בההוא פתח הוברר הדבר מתחלה דסופו לצאת דרך שם וי\"ל כגון שעשאו פתח חדש והוציאו המת דלא שייך ברירה א\"נ מיירי דנשאר המת במקומו:"]]],[["אבל ביום טוב אסור דזימנין דמשתכחי שמנים כחושים וכחושים שמנים וקמטלטל מידי דלא חזי ליה אי נמי זימנין דמשתכחי כלהו כחושים ושביק להו ואתי לאמנועי משמחת יום טוב:","\u0001מתני׳\u0002 זמן שחורים ומצא לבנים לבנים ומצא שחורים שנים ומצא שלשה אסורים שלשה ומצא שנים מותרים","בתוך הקן ומצא לפני הקן אסורין ואם אין שם אלא הם הרי אלו מותרים:","\u0001גמ׳\u0002 פשיטא אמר רבה הכא במאי עסקינן כגון שזמן שחורים ולבנים והשכים ומצא שחורים במקום לבנים ולבנים במקום שחורים מהו דתימא הני אינהו נינהו ואתהפוכי אתהפוך קמ\"ל הנך אזדו לעלמא והני אחריני נינהו","לימא מסייע ליה לר' חנינא דאמר ר' חנינא רוב וקרוב הלך אחר הרוב","כדאמר אביי בדף הכא נמי בדף:","שנים ומצא שלשה אסורין: מה נפשך אי אחריני נינהו הא אחריני נינהו ואי לא אחריני נינהו הא איכא חד דמערב בהו:","שלשה ומצא שנים מותרין: מ\"ט הני אינהו נינהו וחד מנייהו אזל לעלמא","לימא מתניתין רבי היא ולא רבנן דתניא הניח מנה ומצא מאתים חולין ומעשר שני מעורבין זה בזה דברי רבי וחכמים אומרים הכל חולין","הניח מאתים ומצא מנה מנה מונח ומנה מוטל דברי רבי וחכמים אומרים הכל חולין","אפילו תימא רבנן הא אתמר עלה רבי יוחנן ור\"א דאמרי תרוייהו שאני גוזלות הואיל ועשויין לדדות","ולמה לי לשנויי עלה שאני גוזלות הואיל ועשויין לדדות והא אתמר עלה דההיא דרבי יוחנן ור' אלעזר חד אמר בשני כיסין מחלוקת אבל בכיס אחד דברי הכל חולין וחד אמר בכיס אחד מחלוקת אבל בשני כיסין דברי הכל מנה מונח ומנה מוטל","בשלמא למ\"ד בשני כיסין מחלוקת היינו דאיצטריך לשנויי הכא שאני גוזלות הואיל ועשויין לדדות אלא למ\"ד בכיס אחד מחלוקת אבל בשני כיסין דברי הכל מנה מונח ומנה מוטל השתא למה לי לשנויי עלה הא אמרת בשני כיסין לא פליגי","אמר רב אשי הכא בגוזלות מקושרים וכיסים מקושרים עסקינן גוזלות מנתחי אהדדי כיסין לא מנתחי אהדדי","ורבי אמר לך כיסין נמי זמנין"],[[0,"אבל ביום טוב","כשבא לבררן ביום טוב כלומר שלא ברר דבריו מבעוד יום וסומך על בדיקת מחר שיבדוק את כולן:"],[0,"דזימנין דמשתכחי שמנים כחושין וכחושין שמנים","אותם הנראים שמנים למראה עיניו נמצאים כחושין במשמושן והכחושים נמצאים שמנים:"],[0,"מידי דלא חזי ליה","כל אותן שטלטל יותר על צרכו מוקצים היו:"],[0,"","אי נמי גרסינן אי נמי זימנין דמשתכחי כלהו כחושין וקא ממנע משמחת י\"ט וכל זה על ידי שלא ברר אתמול דבריו לפיכך סמך על שקר לומר אי אפשר שלא יהו שנים או שלשה טובים ולמחר נמצאו כולם רעים אבל כשאתה מזקיקו לברר שוב אינו סומך אלא על אלו בין היו שמנים או כחושין ולדעת כן זמנן ובא ונוטלן ולא ממנע:"],[1,"מתני' זמן שחורים","ולא היה שם עוד ולמחר מצא הכל לבנים ודאי המזומנים הלכו להם ואלו אחרים דאתו להו מעלמא לשובך וכן שנים ומצא שלשה ואינו מכיר את המוכנים כולם אסורים:"],[1,"שלשה ומצא שנים מותרים","האחד הלך והשנים נשארו ולא אמרינן הואיל והאחד הלך כן הלכו כולם ואלו אחרים הם:"],[2,"זמן בתוך הקן ומצא לפני הקן","ובתוך הקן לא מצא כלום הרי אלו אסורים ובגמרא מפרש לה:"],[3,"גמ' כגון שזמן שחורים ולבנים","בשני קנין וכל הקנין מובדלין במחיצות ועליות כדרך כל שובכין עשויין עליות הרבה וכל עליה יש בה מחיצות הרבה:"],[3,"השכים ומצא כו'","והכי קאמר זמן שחורים בקן זה ומצא בו לבנים ולבנים זמן בשני ומצא בו שחורים:"],[4,"דרבי חנינא","בבבא בתרא בלא יחפור:"],[4,"רוב וקרוב","אם בא מעשה לפנינו ויש לתלותו בדבר הקרוב לו להתיר או לאסור ויש לתלותו אחר הרוב לענין אחר חלוף הקרוב הלך אחר הרוב ומתני' נמי הכי אמר דהא איכא למתלינהו להנך שחורים באותם שהיו אתמול בקן שבצדו וכן הלבנים ולומר נהפכו ולא תלינן אלא אמרינן מעלמא אתו ומרובא פירשו:"],[5,"כדאמר אביי","לקמן:"],[5,"בדף","שיש דף לפני השובך בולט ויוצא ממנו ושם באים ויושבין יונים דמעלמא תדיר שיראים ליכנס לקן מפני שאותן שבקן מגרשים את כל הבא אליהן וכשיוצאין משובך אלו נכנסין הלכך חיישינן שמא מן הדף באו לקנין הלכך אסורים דהוו להו כלהו קרובים שבדף ושבקן הלכך זיל בתר רובא:"],[6,"מה נפשך כו'","פירושא דמתניתין היא כלומר להכי אסורים דמה נפשך להתירם:"],[8,"[לימא מתניתין רבי היא","הא מתניתין סתמא היא והלכה כסתם משנה ואנן קי\"ל (כתובות דף כא.) הלכה כרבי מחבירו ולא מחביריו]:"],[8,"הניח מנה","ממעות מעשר שני בתיבה:"],[8,"חולין ומעשר שני מעורבין זה בזה","האחד חולין ואינו יודע איזהו ונוטל היפה שבהן ואומר אם (היא זו) של מעשר הרי יפה ואם חולין היא תהא חברתה מחוללת עליה:"],[8,"הכל חולין","הואיל ולא מצא כמו שהניח תולין להקל ולומר נטל את הראשון והניחו במקום אחר והניח שוב את אלו ושכח שאין אדם מניח מעות חולין ומעות מעשר ביחד:"],[9,"מנה מוטל","ונשאר הך מנה ממעשר:"],[9,"הכל חולין","הואיל ולא העלהו לירושלים לא הפרידן זה מזה ושניהם נטלן והניחם במקום אחר וזה חולין הוא שהניח הלום אחרי כן ושכח:"],[10,"שאני גוזלות","להכי איכא למימר האחד הלך וחבריו נשארו:"],[10,"הואיל ועשויין","רגילים הן להיות מדדין אחד אחד ויוצאין ונכנסין אבל מנה לא הלך מאליו אא\"כ נטלו וכשנטל נטל שניהם:"],[11,"ולמה לי לשנויי עלה","רבי יוחנן ורבי אלעזר מה דוחקין לתלות טעם משנתנו במדדים הא לדידהו מתוקמת שפיר כרבנן בלאו האי טעמא דהא אינהו אפליגו בההיא דמעשר חד אמר מחלוקת במונחין שני המנין בכיס אחד בההוא הוא דקאמרי רבנן דכשנטל כל הכיס נטל אבל בשני כיסים מודו דהאחד נטל והניח השני וחד אמר מחלוקת בב' כיסין בההוא הוא דקאמר רבי מנה מונח ומנה מוטל:"],[11,"האי מאי","לא גרסינן:"],[12,"בשלמא למ\"ד כו'","המקשה סיומי מסיים למילתיה ומפרש קושייתו בשלמא מאן דמוקי פלוגתייהו בב' כיסין דהיינו כדומיא דמתני' דהוו שני גוזלות צריך לשנויי דתקום מתניתין כרבנן מהאי טעמא הואיל ועשויין לדדות אלא למ\"ד בשני כיסין מודו רבנן השתא למה לי לשנויי משום דעשויין לדדות הא בשני כיסים נמי הכי קאמרינן:"],[12,"השתא ומה כו'","לא גרסינן אלא ה\"ג אלא למ\"ד בכיס אחד מחלוקת אבל בשני כיסים דברי הכל מנה מונח ומנה מוטל השתא למה לי לשנויי עלה האמר בשני כיסים לא פליגי וחד מהני רבנן או רבי יוחנן או רבי אלעזר אוקמה הכי ולעיל אמאי שנו תרוייהו הואיל ועשויין לדדות:"],[13,"אמר רב אשי הכא בגוזלות כו'","מ\"ד בכיס אחד מחלוקת בשני כיסין כעין כיס אחד קאמר דהיינו שני כיסין מקושרין ודקאמר אבל בשני כיסין דברי הכל מנה מונח ומנה מוטל בשאין מקושרין ומתניתין אפי' בגוזלות מקושרין משמע דהנותרין מותרין ולא אמרי' אותן שזמן נטלו כולם ואלו אחרים הלכך אי לא דשאני גוזלות הואיל ועשויין לדדות לא הוה מתוקמא כרבנן דהא בכיסים מקושרין אמרי רבנן הכל חולין והשתא אגב האי שנויא מתוקמא שפיר כרבנן דגוזלות דמדדין מנתחי אהדדי ואיכא למתלי לקולא דחד מנייהו הוא דאזל ליה אבל כיסים לא מנתחי ואדם בא ונטלן וכיון דמקושרים הם שניהם נטל:"]],[[6,"","איכא חד דמערב בהו. וא\"ת ולבטיל ברובא וי\"ל דבעלי חיים לא בטלי דחשיבי אי נמי ה\"ל דבר שיש לו מתירין לאחר יו\"ט וכל דבר שיש לו מתירין אפי' באלף לא בטיל:"],[7,"","חד מנייהו אזל לעלמא. וא\"ת וכי תלינן לקולא בדבר שיש לו מתירין ויש לומר דהואיל ונשארו שנים במקומם ודאי בכה\"ג תלינן לקולא:"],[8,"","חולין ומעשר שני מעורבין זה בזה. פ\"ה בורר מנה היפה שבשניהם ויאמר אם זה של מעשר מוטב ואם האחר של מעשר הרי זה מחולל על זה ותימה דמפרש בפרק הזהב (ב\"מ דף מה.) דאין מחללין כסף על כסף ולא מעות על מעות לכך נראה דמחלל בתחלה המנה של מעשר על פרוטות של נחשת ואח\"כ מחללו על מנה היפה שבשניהם:"],[11,"","הכל חולין. שאני אומר הוא לקח מעות של מעשר שני והני אחריני נינהו ותימה דהא לא אמרי' שאני אומר להקל אלא כשהוא מדרבנן כדאיתא בפסחים (דף י.) דקאמר שאני תרומה דרבנן לפיכך אני תולה להקל לומר שאני אומר וכו' וי\"ל דכיון שאין אדם מניח חולין אצל מעשר תלינן שפיר לקולא ואמרי' ודאי לקח אלו משם ושכח ואחר כך הניח אלו שם:"]]],[["דמתעכל קטרייהו:","בתוך הקן ומצא לפני הקן אסורין: לימא מסייע ליה לר' חנינא דאמר ר' חנינא רוב וקרוב הלך אחר הרוב","אמר אביי בדף רבא אמר בשני קנין זו למעלה מזו עסקינן ולא מבעיא זמן בתחתונה ולא זמן בעליונה ומצא בתחתונה ולא מצא בעליונה דאסירן דאמרינן הנך אזלו לעלמא והנך אשתרבובי אשתרבוב ונחות","אלא אפילו זמן בעליונה ולא זמן בתחתונה ובא ומצא בעליונה ולא מצא בתחתונה הנך נמי אסירי דאמרינן הנך אזלו לעלמא והנך סרוכי סריך וסליקו:","ואם אין שם אלא הן הרי אלו מותרין: היכי דמי אילימא במפורחין איכא למימר הנך אזלו לעלמא והני אחריני נינהו","אלא במדדין אי דאיכא קן בתוך חמשים אמה אדדויי אדדו ואי דליכא קן בתוך חמשים אמה פשיטא דמותרין דאמר מר עוקבא בר חמא כל המדדה אין מדדה יותר מחמשים אמה","לעולם דאיכא קן בתוך חמשים אמה וכגון דקיימא בקרן זוית מהו דתימא אדדויי אדדו קמ\"ל כל היכא דמדדה והדר חזי לקניה מדדה ואי לא לא מדדה:","\u0001מתני׳\u0002 בית שמאי אומרים אין נוטלים את העלי לקצב עליו בשר ובית הלל מתירין בית שמאי אומרים אין נותנין את העור לפני הדורסן ולא יגביהנו אלא אם כן יש עמו כזית בשר ובית הלל מתירין:","\u0001גמ׳\u0002 תנא ושוין שאם קצב עליו בשר שאסור לטלטלו","אמר אביי מחלוקת בעלי אבל בתברא גרמי דברי הכל מותר פשיטא עלי תנן","מהו דתימא הוא הדין דאפילו תברא גרמי נמי והאי דקתני עלי להודיעך כחן דבית הלל דאפילו דבר שמלאכתו לאיסור נמי שרו קמ\"ל","איכא דאמרי אמר אביי לא נצרכא אלא אפילו תברא גרמי חדתי מהו דתימא ממלך ולא תבר עלה קמ\"ל","ובית שמאי לא חיישי לאמלוכי והתניא בית שמאי אומרים אין מוליכין טבח וסכין אצל בהמה ולא בהמה אצל טבח וסכין ובית הלל אומרים מוליכין זה אצל זה","בית שמאי אומרים אין מוליכין תבלין ומדוך אצל מדוכה ולא מדוכה אצל תבלין ומדוך ובית הלל אומרים מוליכין זה אצל זה","הכי השתא בשלמא בהמה אתי לאמלוכי דאמר נשבק האי בהמה כחושה ומייתינא בהמה אחריתי דשמינה מינה קדרה נמי אתי לאימלוכי דאמר נשבק האי קדרה דבעיא תבלין ומייתינא אחריתי דלא בעיא תבלין הכא מאי איכא למימר ממלך ולא תבר כיון דשחטה לתבירא קיימא:","בית שמאי אומרים אין נותנין את העור: תנא ושוין שמולחין עליו בשר לצלי אמר אביי לא שנו אלא לצלי אבל לקדרה לא","פשיטא לצלי תנן הא קמ\"ל דאפילו לצלי כעין קדרה אסור","תנו רבנן אין מולחין את החלבים ואין מהפכין בהן משום ר' יהושע אמרו שוטחן ברוח על גבי יתדות","אמר רב מתנה הלכה כר' יהושע איכא דאמרי אמר רב מתנה אין הלכה כר' יהושע בשלמא למאן דאמר הלכה כר' יהושע אצטריך סד\"א יחיד ורבים הלכה כרבים קמ\"ל הלכה כיחיד","אלא למאן דאמר אין הלכה פשיטא יחיד ורבים הלכה כרבים מהו דתימא מסתבר טעמיה דר' יהושע דאי לא שרית ליה ממנע ולא שחיט קא משמע לן","ומאי שנא מעור לפני הדורסן"],[[0,"דמתעכל קטרייהו","ניתר הקשר שלהם ומתפרק מאליו והבא ונטל שמא לא מקושרין מצאם וחטף האחד והלך לו:"],[1,"לפני הקן","דרך כל שובכין להיות מעט מן דף העליה בולט חוץ למחיצה של כל קן וקן ושם היונים יוצאים לאויר ונוחים שם כרצונם וחוזרים לקן:"],[1,"הלך אחר הרוב","כי הכא דלא אמרי' אלו אותן שזמן בתוך הקן שהוא קרוב ללפני הקן אלא אמרי' מעלמא אתו:"],[2,"בדף","דכלהו קרוב נינהו הלכך הלך אחר הרוב דאיכא תרתי:"],[2,"רבא אמר","הא לא אצטריך לאשמועינן אלא בשני קנין זו למעלה מזו ובשניהם גוזלות וזמן את שבזו ולא זמן את שבזו ולמחר בא ולא מצא בתוך הקן שזמן אלא לפניו ובאותו שלא זמן לא מצא לא לפניו ולא לתוכו הלכך אסירי ולא משום חששא דיוני דעלמא אלא מאחר שלא מצאן במקומן ועוד שבקן האחר המוקצה לא מצא כלום יש לחוש שמא אלו שמצא לפני הקן המוכן לא מתוכו יצאו אלא מתוך המוקצה:"],[2,"","ולא מיבעיא קאמר לא גרסי' אלא ה\"ג ולא מיבעיא זמן בתחתונה ולא זמן בעליונה כו'. כלומר ותנא דאצטריך לאשמועינן אסורים לאו כשזמן את של תחתונה ולמחר מצא בתחתונה לפניה ולא בתוכה ולא מצא בעליונה כלום אצטריך למימר דאסירי דחיישינן דלמא הני דאזמין אזדו להו והנך שמצא לפניה משל עליונה באו ואשתרבובי אשתרבוב למטה ונחיתו הא לא אצטריך דאפי' זמן בעליונה בתוכה ולא זמן את של תחתונה ולמחר מצא בעליונה לפניה ולא בתוכה ולא מצא בתחתונה כלל אסירי ולא תימא לאו אורחייהו למסרך ומיסק בעודן קטנים אלא אמרינן סרוכי סרוך מן התחתונה המוקצה וסליקו לפני העליונה:"],[4,"ואם אין שם אלא הן","אם אין סביבותיהם אתמול אלא הן:"],[4,"הרי אלו מותרים","דודאי אלו הן שהזמין בתוך הקן ובאו לפניה:"],[4,"מפורחים","גדולים ופורחים למרחוק:"],[5,"אדדויי אדדו","מאותו קן ואתו להכא כדמפרש ואזיל דעד חמשים אמה מדדה:"],[6,"בקרן זוית","שזוית הבית בולט להלאה מן השובך וקן זה שזמן בו עומד לצדדין דאי הוה אתי להכא לא הוה חזי לקניה שהזוית של בית עומדת לפניו: [ציור]"],[7,"מתני' עלי","מלאכתו לאיסור לכתוש במכתשת משום הכי אסרי ליה בית שמאי:"],[8,"גמ' שאסור לטלטלו","דאתעביד ליה צורך י\"ט:"],[9,"בתברא גרמי","המיוחדת לקצב עליה בשר:"],[10,"מהו דתימא","הוא הדין דאפילו תברא גרמי אסרי ב\"ש דלמא בתר דטלטלה ממליך ולא תבר ואשתכח דטרח בכדי:"],[11,"איכא דאמרי אמר אביי כו'","כי אותביניה פשיטא עלי תנן שני אביי גופיה הכי לא נצרכא הא דאמרינן אבל תברא גרמי דברי הכל מותר אלא לתברא גרמי חדתי שלא קצב עליה מעולם דאיכא למיחש דחייס עלה וממלך:"],[12,"לא חיישי לאמלוכי","בתמיה ופריך לאביי:"],[12,"אין מוליכין טבח וסכין וכו'","אם היו רחוקים זה מזה דלמא [בתר] דטריח ממליך:"],[13,"מדוך","בוכנא שדוכין בו תבלין במדוכה:"],[14,"נשבק האי קדרה","מין תבשיל זה שיהא צריך תבלין כגון בשר ובצלים:"],[14,"ואעבד קדרה דלא בעיא תבלין","כגון כרוב ולפת:"],[14,"","מאי איכא למימר גרסי' קמ\"ל לא גרסינן:"],[15,"שמולחין עליו","ואע\"פ שהמלח מועיל לעבוד:"],[15,"לצלי","דאין מולחין אותו יפה:"],[16,"הא קא משמע לן דאפי' לצלי כעין קדרה אסור","האי אבל לקדרה דקאמר אביי צלי כעין קדרה קאמר כגון אדם המולח צלי יפה יפה קרוב למליחת בשר שלצורך קדרה דלא תימא כל צלי שרי:"],[17,"אין מולחין את החלבים","ביום טוב כדי שלא יסריחו ואפי' נשחטה הבהמה בי\"ט:"],[20,"ומאי שנא מעור לפני הדורסן","דשרו בית הלל משום דאי לא שרית ליה ממנע ולא שחיט:"]],[[5,"","פשיטא דמותרין דאמר מר עוקבא כל המדדה וכו'. וקשה וכי מייתי ראיה ממר עוקבא שהוא אמורא וי\"ל דע\"כ אנו צריכין לומר כדמר עוקבא דאם לא כן לא מתוקמא מתניתין דלא יחפור (ב\"ב דף כג:):"],[7,"","אין נוטלין העלי. ותימה הא צריך לגופה וכל כלי שצריך. לגופו או למקומו אפילו מלאכתו לאסור נוטלין אותו ביום טוב וי\"ל דבפרק כל הכלים (שבת דף קכג. ושם) מוקמינן ליה במוקצה שיש בו חסרון כיס דכ\"ע מודו דאסור כגון סיכי זירי ומזורי דקפיד עלייהו וב\"ה שמתירין היינו דוקא משום שמחת י\"ט כדמפרש בגמרא:"],[15,"","ושוין שמולחין עליו בשר לצלי. לאו משום דצריך מליחה לצלי כדמפ' בחולין (דן קיא.) אלא משום שנהגו למלחו כדי ליתן טעם [ועי' תוספות חולין יד. ד\"ה ונסבין]:"]]],[["התם לא מוכחא מלתא משום דחזי למזגא עליה הכא אתי למימר מאי טעמא שרו לי רבנן כי היכי דלא לסרח מה לי למשטחינהו מה לי לממלחינהו","אמר רב יהודה אמר שמואל מולח אדם כמה חתיכות בשר בבת אחת אף על פי שאינו צריך אלא לחתיכה אחת רב אדא בר אהבה מערים ומלח גרמא גרמא:","\u0001מתני׳\u0002 בית שמאי אומרים אין מסלקין את התריסין ביום טוב ובית הלל מתירין אף להחזיר:","\u0001גמ׳\u0002 מאי תריסין אמר עולא תריסי חנויות","אמר עולא שלשה דברים התירו סופן משום תחלתן ואלו הן עור לפני הדורסן ותריסי חנויות","וחזרת רטיה במקדש","ורחבא אמר רבי יהודה אף הפותח חביתו ומתחיל בעיסתו על גב הרגל","ואליבא דרבי יהודה דאמר יגמור","עור לפני הדורסן תנינא מהו דתימא טעמייהו דבית הלל משום דחזי למזגא עלייהו ואפילו מערב יום טוב נמי קמ\"ל התירו סופן משום תחלתן דיום טוב אין דערב יום טוב לא","תריסי חנויות נמי תנינא [ובית הלל מתירין אף להחזיר] מהו דתימא טעמייהו דבית הלל משום דאין בנין בכלים ואין סתירה בכלים ואפילו דבתים נמי קמ\"ל התירו סופן משום תחלתן דחנויות אין דבתים לא","חזרת רטיה במקדש נמי תנינא מחזירין רטיה במקדש אבל לא במדינה מהו דתימא טעמא מאי משום דאין שבות במקדש אפילו כהן דלאו בר עבודה הוא קמ\"ל התירו סופן משום תחלתן דבר עבודה אין דלאו בר עבודה לא","פותח את חביתו נמי תנינא הפותח את חביתו ומתחיל בעיסתו על גב הרגל רבי יהודה אומר יגמור וחכמים אומרים לא יגמור","מהו דתימא טומאת עם הארץ ברגל כטהרה שויוה רבנן ואף על גב דלא התחיל נמי קמ\"ל התירו סופן משום תחלתן התחיל אין לא התחיל לא","ועולא מאי טעמא לא אמר הא בפלוגתא לא קא מיירי הנך נמי פלוגתא נינהו בית שמאי במקום בית הלל אינה משנה","מתניתין דלא כי האי תנא דתניא אמר רבי שמעון בן אלעזר מודים בית שמאי ובית הלל שמסלקין את התריסין ביום טוב לא נחלקו אלא להחזיר שבית שמאי אומרים אין מחזירין ובית הלל אומרים אף מחזירין במה דברים אמורים בשיש להן ציר אבל אין להן ציר דברי הכל מותר","והתניא במה דברים אמורים בשאין להן ציר אבל יש להן ציר דברי הכל אסור אמר אביי בשיש להן ציר מן הצד דברי הכל אסור אין להן ציר כל עיקר דברי הכל מותר כי פליגי בשיש להן ציר באמצע"],[[0,"התם לא מוכחא מילתא","שתהא שטיחתו לצורך עבוד דמימר אמר האי דשרו ליה רבנן לתתו לפני הדריסה מפני צורך יום טוב התירו שאף שטיחתו צורך י\"ט דחזי למזגא עליה אבל הכא גבי חלבים כי שרית לשוטחן מוכחא מלתא שלתקון החלבים התרתו ואתי נמי לממלחינהו ומליחה מאבות מלאכות היא בדבר שיש בו עבוד דתנן (שבת דף עג.) והמולחו והמעבדו:"],[1,"בבת אחת","דחד טרחא לכלהו:"],[1,"מערים","לאחר שמלח זו לאכלה היום אומר חברתה ערבה עלי לאכלה היום וחוזר ומולחה:"],[3,"תריסין","דלתות פתחיהן:"],[3,"חנויות","כמו תיבות הן ועומדות בשוק ואינן מחוברו' לקרקע:"],[4,"","התירו סופן שאינו צורך יום טוב:"],[4,"משום תחלתן","שהוא צורך יום טוב ואי לא שרית סופן לא עביד תחלתן:"],[4,"עור לפני הדורסן","הותרה שטיחתן משום שחיטתן:"],[4,"תריסי חנויות","הותרה חזרתן משום סלוקן:"],[5,"וחזרת רטיה","בשבת פרק כלל גדול (שבת דף עה:) אמרו הממרח רטיה בשבת חייב משום ממחק:"],[5,"במקדש","לכהן שלקה בידו וצריך לעבוד עבודה וליטול רטיה מעל ידו שלא תהא חציצה בין ידו לעבודה מחזיר הרטיה לאחר עבודה דאי לא שרית ליה להחזירה לא שקיל ליה מעיקרא:"],[6,"ורחבא אמר רבי יהודה","י\"מ ספק משמיה דרבי יהודה נשיאה ספק משמיה דרב יהודה ואני אומר לא ראה רחבא את רבי יהודה נשיאה דהא מפומבדיתא הוה ולא מצינו שעלה לא\"י ועוד כי אמרי' בעלמא דדייק וגמר שמעתת' מפומיה דרביה כרחבא דפומבדיתא. הוה לן למימר דאפילו ספיקי דגברי גריס כדאמרינן בדרב יהודה בהכל שוחטין (חולין יח:) ונראה בעיני משום דרבו מובהק היה ולא היה לומד מרב אחר הוה קרי ליה רבי דלא נספקיה בדרב יהודה אחרינא:"],[6,"אף הפותח את חביתו","חבר כשהתחיל למכור יינו או ככרו לעולי רגלים ברגל וממשמשי בה יד הכל וטומאת עם הארץ ברגל טהורה כל ימות הרגל ובמה שנשאר לאחר הרגל נחלקו רבי יהודה וחכמים בפרק חומר בקדש (חגיגה דף כו.) רבי יהודה אומר יגמור וימכרנה לחברים ולכל אדם ויזהר שלא יגע עם הארץ עוד וחכמים אומרים לא יגמור ולא ימכרנה עוד משום דנטמאת ברגל במגע עם הארץ ונהי דכל ימות הרגל אשתראי שלא לביישם מיהו לאחר הרגל חלה למפרע ואשמעינן רחבא דרבי יהודה לא אמר יגמור אלא משום תחילתן דאי לא שרית ליה לא פתח ליה מעיקרא:"],[8,"תנינא","במתניתין ובית הלל מתירין ומעולא מאי נפקא לן:"],[8,"ואפילו מעי\"ט","שהופשט מבעוד יום:"],[8,"דערב יום טוב לא","דליכא למיגזר משום תחילתן דאי נמי לא שרית ליה אינו נמנע מלשחוט מעי\"ט דהא יכול לשוחטו מבעוד יום:"],[9,"תנינא","במתניתין:"],[9,"","וב\"ה מתירין אף להחזיר גרסינן:"],[9,"דאין בנין בכלים","אין איסור בנין וסתירה בכלים אלא בבתים דנחייב בבנין כל דהו והעושה כלי או גומרו בי\"ט או בשבת משום מכה בפטיש הוא דמחייב שהוא חיוב לכל גמר מלאכה או אם הוא דבר שהוא מחליקו חייב משום ממחק ואם צריך קצוע חייב משום מחתך וכן אורג או מסך או תופר אבל בנין וסתירה לא שייך בהו לאחיובי בסלוק וחזרה דהא דתנן (שבת דף קב:) הבונה כל שהוא בבתים תנן והלכך בית הלל אפילו בתיבות הבית שרו לסלק דלתותיהן ולהחזיר ואע\"ג דלאו לשמחת י\"ט קמ\"ל עולא דאע\"ג דאין בנין וסתירה בכלים קאסרי ליה ב\"ה מדרבנן אי לאו משום תחלתן דחנויות שהן צרכי רבים אין אבל תריסי כלי הבית לא:"],[10,"תנינא","בעירובין מחזירין רטיה במקדש אבל לא במדינה:"],[10,"מהו דתימא טעמא","דהתירא משום דלא גזרו על השבות שבמקדש ולקשור רטיה וכן כל דבר רפואה שאין מלאכה אלא שבות הוא שגזרו חכמים בכל רפואות גזירה משום שחיקת סמנין:"],[11,"תנינא","בחגיגה:"],[12,"כטהרה שויה רבנן","דאסמכוה אקרא כאיש אחד חברים (שופטים כ׳:י״א) וטעמא דרבי יהודה משום דלא הדרה חיילא ואע\"ג דלא התחיל על גב הרגל למוכרה ואירע שנגע בה עם הארץ ברגל קאמר נמי רבי יהודה דאין מגעו מטמאה ואפי' לאחר הרגל קמ\"ל רחבא דמשום תחלתן הוא:"],[13,"בפלוגתא לא קא מיירי","והא פליגי רבנן עלה:"],[14,"מתניתין","דקתני בסלוק נמי פליגי לאו כי האי תנא:"],[14,"בשיש להן ציר","ידות לשני ראשין דדומות לבנין:"],[15,"והתניא","בשאין להן ציר הוא דשרי ב\"ה אבל בשיש כו':"],[15,"אמר אביי","דכולי עלמא תרוייהו הנך תנאי דברייתא דפרשי לן פלוגתא דב\"ש וב\"ה:"],[15,"דברי הכל אסור","ובשאין להן ציר כל עיקר דברי הכל ב\"ש וב\"ה:"],[15,"בשיש להן ציר באמצע","כעין פליט\"א ותוחבין אותו בחור שבאמצע דופן פתח התיבה:"]],[[1,"","מערים ומלח גרמא גרמא. וכן רגילין העולם שמערימין ואוכלין מעט מן התרנגולת ואוכלין הכבד ומיהו ה\"ר שמואל היה אומר היינו דוקא קודם אכילה אבל אחר אכילה לא:"],[6,"","אמר רחבא אמר ר' יהודה. פי' רש\"י יש מפרשים דלהכי קאמר האי לישנא משום שהיה מסופק אם שמע שמועה זאת מרבי יהודה הנשיא או מרב יהודה ולא נהירא דרחבא היה בפומבדיתא ולא מצינו שעלה לא\"י ועוד מצינו בפסחים (דף נב:) דדייק וגמר שמעתתא מפומיה דרביה כרחבא דפומבדיתא כו' ואם כן שהיה מסופק ממי שמע שמועה היה לו לומר דאפילו ספיקי דגברי גריס כדאמר בחולין (דף יח:) בשמעתין דמוגרמת לכך נראה לי דלכך אמר רבי יהודה משום שהיה רבו מובהק והא דקאמר וגמר שמעתתא מפומיה קאי אהא דקאמר סטיו לפנים מסטיו ולא קאמר. אסטונית דאותו לשון שמע מרבו ולא רצה לשנותו:"],[9,"","מהו דתימא טעמייהו דב\"ה דאין בנין וסתירה כו'. דקי\"ל אין בנין וסתירה כשהוא מהדק ומפרק כי אם בעושה כלי שהוא חייב משום מכה בפטיש או בבונה על גבי קרקע כדאמרינן בשבת (דף קב:) הבונה כל שהוא חייב קמ\"ל ותימה הא קיימא לן אין בנין וסתירה בכלים י\"ל מ\"מ אסור שמא יתקע:"]]],[["מר סבר גזרינן ציר באמצע אטו ציר מן הצד ומר סבר לא גזרינן:","\u0001מתני׳\u0002 בית שמאי אומרים אין מוציאין לא את הקטן ולא את הלולב ולא את ספר תורה לרשות הרבים ובית הלל מתירין:","\u0001גמ׳\u0002 תני תנא קמיה דרבי יצחק בר אבדימי השוחט עולת נדבה ביום טוב לוקה","אמר ליה דאמר לך מני בית שמאי היא דאמרי לא אמרינן מתוך שהותרה הוצאה לצורך הותרה נמי שלא לצורך דאי בית הלל הא אמרי מתוך שהותרה הוצאה לצורך הותרה נמי שלא לצורך הכא נמי מתוך שהותרה שחיטה לצורך הותרה נמי שלא לצורך","מתקיף לה רבה ממאי דבית שמאי ובית הלל בהא פליגי דלמא בערוב והוצאה לשבת ואין ערוב והוצאה ליום טוב קא מיפלגי","מר סבר ערוב הוצאה לשבת וערוב הוצאה ליום טוב","ומר סבר ערוב הוצאה לשבת ואין ערוב הוצאה ליום טוב כדכתיב (ירמיהו יז, כב) ולא תוציאו משא מבתיכם ביום השבת בשבת אין ביום טוב לא","מתקיף לה רב יוסף אלא מעתה ליפלגו באבנים אלא מדלא מפלגי באבנים ש\"מ","בהוצאה שלא לצורך פליגי","ואף ר' יוחנן סבר במתוך שהותרה הוצאה לצורך הותרה נמי שלא לצורך פליגי דתני תנא קמיה דר' יוחנן המבשל גיד הנשה בחלב ביום טוב ואכלו לוקה חמש","לוקה משום מבשל גיד ולוקה משום אוכל גיד ולוקה משום מבשל בשר בחלב ולוקה משום אוכל בשר בחלב ולוקה"],[[0,"מר סבר","בית שמאי:"],[0,"ומר סבר","בית הלל והנך מתניתא לא אפלוג אלא מר אשמעינן חדא ומר אשמעינן חדא ולא פליגי מתניתא קמייתא הכי קאמר במה דברים אמורים בשיש להן ציר באמצע אבל אין להם ציר כל עיקר דברי הכל מותר ותנא בתרא ה\"ק במה דברים אמורים דנחלקו בשאין להם ציר מן הצד אבל בשיש להם ציר מן הצד דברי הכל אסור:"],[1,"מתני' לא את הקטן","כל מילי דלאו צורך אכילה:"],[2,"גמ' עולת נדבה","דאילו עולת חובת היום רחמנא שריא אבל זו יש להקריבה לאחר יום טוב:"],[2,"לוקה","משום (לא תעשה כל מלאכה) (שמות כ):"],[3,"לצורך","אך אשר יאכל לכל נפש:"],[4,"בערוב הוצאה","אם נאסרה הוצאה ביו\"ט ונתקנו הלכות ערובי חצירות ליו\"ט אם לאו:"],[4,"ואין ערוב והוצאה כו'","ואע\"ג דעיקר הוצאה מויעבירו קול במחנה נפקא לן (שבת דף צו:) בא ירמיה ופירש שלא נאסרה אלא בשבת משום הכי קא שרו אבל שחיטה שהיא אב מלאכה ובכלל לא תעשה כל מלאכה היא אימא לך אפילו לב\"ה אם הותרה לצורך לא הותרה שלא לצורך והך מתניתין אפי' ב\"ה:"],[7,"מתקיף לה רב יוסף","אהך אתקפתא דרבה:"],[7,"אלא מעתה","דסבירא להו לב\"ה אין אסור הוצאה ליו\"ט:"],[7,"ליפלגו באבנים","אי אין אסור הוצאה אין אסור טלטול שלא נאסר טלטול אלא משום הוצאה ומה שלא גזרו על כל טלטולים אפילו על אוכלים וכלים משום דאין גוזרין גזרה על הצבור אא\"כ רוב צבור יכולין לעמוד בה:"],[7,"אלא מדלא אפלוג באבנים","ש\"מ דלכולי עלמא יש הוצאה ליו\"ט אלא שמן התורה הותרה לצורך וב\"ה אית להו כיון דהותרה לצורך הותרה מן התורה לגמרי אלא רבנן גזור במידי דהוי טרחא דלא צריך כגון אבנים אבל בקטן וספר תורה דצריכינן להו ביו\"ט לא גזור ובית שמאי לית להו מיגו ומידי דצורך אכילה שהתורה התירתו הותר ושאינו צורך אכילה באסורו עומד מן התורה:"],[9,"","ואף ר' יוחנן סבר במתוך גרסינן:"],[9,"פליגי","ב\"ש וב\"ה ודכולי עלמא יש אסור הוצאה ליו\"ט מויעבירו קול במחנה דישנה בשאר מלאכות וירמיה היה מזהירן על השבתות שהן חמורין והלואי ישמעו:"],[10,"לוקה משום מבשל גיד","שהבשול אב מלאכה הוא ובשול גיד דבר האסור ואינו ראוי לאכילה ועומד באסור לא תעשה כל מלאכה דלא הותר אלא לצורך:"],[10,"ולוקה משום מבשל בשר בחלב","לאו משום יו\"ט דמלקות דבשול יו\"ט הא תנא ליה אלא אפילו הוא חול לוקה משום מבשל בשר בחלב דכתיב לא תבשל גדי בחלב שלש פעמים אחד לאסור אכילה ואחד לאסור הנאה ואחד לאסור בשול:"]],[[2,"","השוחט עולת נדבה ביום טוב לוקה וכו'. וה\"ה דמצי למימר ר\"ע היא. דלית ליה מתוך אלא ניחא ליה למנקט ב\"ש דסבירא להו הכי בהדיא טפי ותימה הואיל ומוקמינן לה אליבא דב\"ש אם כן לימא השוחט עולת חובה בי\"ט לוקה דהא ב\"ש אית להו לקמן (ביצה דף יט.) על עולת ראייה דלוקה דדרשינן וחגותם חגיגה אין עולת ראייה לא וי\"ל משום דיוקא נקטיה דאי הוה נקט עולת חובה הוה אמינא עולת חובה מחייבי אבל שלמי חובה כיוצא בו פטור הואיל והם חובה וגם יש בהן צורך האדם אבל שלמי נדבה חייב הואיל והיה יכול להקריבן למחר והשתא דנקט עולת נדבה אשמעינן רבותא דדוקא עולת נדבה חייב דכולה כליל אבל שלמי נדבה פטור אע\"ג שאינו חייב בהן והיה יכול להמתין עד למחר הואיל ויש בהן צורך הדיוט וא\"ת והא אפילו ב\"ה מודו דלוקה דסבירא להו לקמן (שם) דנדרים ונדבות אין קרבים בי\"ט ואמאי מוקים לה אליבא דב\"ש וי\"ל דמהיכא אית ליה דנדרים ונדבות אין קרבים בי\"ט מלכם ולא לגבוה וא\"כ הוי לאו הבא מכלל עשה דאין לוקין עליו וא\"ת כיון דאהדריה אהדריה לאסורא קמא דהא אמרי' גבי גוזז פסולי המוקדשין דלוקה אע\"ג דלא ידעינן אסור גזיזה רק מדכתיב (דברים יב) תזבח ולא גיזה דהיינו לאו הבא מכלל עשה דאין לוקין אלא ש\"מ כיון דאהדריה אהדריה לאסורא קמא כלומר ללאו שהיה בו קודם שנפסל וגם גבי נדרים ונדבות נימא הכי דאהדריה לאסורא קמא ולוקה וי\"ל דשאני גיזה שלא הותרה בפסולי המוקדשין כלל בהדיא וא\"כ הואיל ואשתכח סמך בהו לאסורא מוקמינן ליה באיסורא קמא אבל הכא גבי יו\"ט דאוכל נפש הותר דכתיב אשר יאכל וגו' (שמות יב) וה\"ה בנדרים ונדבות מתוך שהותרה וכו' וא\"כ אשכחנא דהותרו בהדיא וכיון דאשכחנא דהותרו בהדיא לא אמרי' אהדרי' לאסור' קמא אלא למאי דאהדריה אהדריה ולמאי דלא אהדריה לא אהדריה וקאי דוקא בעשה:"],[4,"","דלמא בערוב והוצאה קמפלגי. פי' רש\"י ערובי חצרות וקשה מאי צריך עירובי חצרות גבי י\"ט הא בלאו הכי מותר לטלטל מחצר לחצר לצורך לכ\"נ להר\"ר חיים כהן דגרסינן ערוב הוצאה בלא וי\"ו והכי פירושו אם אסור הוצאה מעורב בו בין שאר מלאכות אע\"ג שהיא מלאכה גרועה ואם שייכא אסור הוצאה אם לא קמפלגי ומיהו יש לישב דגרסינן שפיר ערוב והוצאה דצריך ערוב שיוכל להוציא דברים שאינן לצורך יו\"ט כלל (ואין ערוב והוצאה ליו\"ט דשאני הוצאה דגרועה היא מכל שאר מלאכות ויש ספרים דגר' קרא דירמיה ולא תוציאו משא מבתיכם ביום השבת בשבת אין ביו\"ט לא דממעט לה בהדיא מטעם דהוצאה גרועה היא):"],[7,"","ה\"ג רש\"י אלא מעתה לפלגו באבנים ומדלא מיפלגי באבנים ש\"מ וכו' והכי פירושו אלא מעתה דב\"ה לית להו אסור הוצאה לפלגו בטלטול אבנים ולשמעינן רבותא דלית להו בהן אסור הוצאה דהא לא נאסר בשום דבר טלטול אפי' דבר שמלאכתו לאסור וגם אינו צורך י\"ט כלל אלא גזרה שמא יוציא כדאיתא בהדיא פרק כל הכלים (שבת דף קכד:) ואפי' דבר שהוא צורך יו\"ט כגון כלי הצריך לו היה ראוי לאסור גזירה שמא יוציא אלא שאין גוזרין גזירה על הצבור אא\"כ רוב הצבור יכולין לעמוד בה ומדלא קמפלגי באבנים שמע מינה בהוצאה וכו' דב\"ה סברי מתוך וא\"ת כיון דב\"ה אית להו מתוך אמאי אין מתירין אפי' טלטול אבנים וכל דבר אפילו אינו צורך יום טוב ויש לומר דודאי אין ה\"נ דמדאורייתא הואיל והותרה הותרה לגמרי אלא רבנן גזור על דבר שאינו צורך יו\"ט דכיון דעיקר הוצאה נאסרה יש לאסור בדבר שאין לצורך יום טוב כלל ע\"כ פי' רש\"י ולא רצה לגרוס כמו שיש בספרים אלא מעתה הוציא אבנים לב\"ה ה\"נ דלא מחייב מלקות דא\"כ הוה מסיק לפי' זה הוציא אבנים לב\"ה דחייב ורש\"י קים ליה דב\"ה סבירא להו הואיל והותרה הותרה לגמרי אלא רבנן הוא דגזור בדבר שאינו צורך יו\"ט כלל וקשה חדא דאמרי' בפסחים (דף מ:) האופה מיו\"ט לחול לוקה ולא אמרינן מתוך וכו' ואפילו לרבה דלא לקי היינו מטעם הואיל ואי אתרמי ליה אורחים אבל מטעם מתוך לא קאמר ועוד דמוחק גירסת הספרים לכן נראה לפר' דגרסי' כגירסת הספרים אלא מעתה הוציא אבנים לב\"ה ה\"נ דלא מחייב פי' מדאורייתא מלקות וכ\"ת ה\"נ א\"כ לפלגו באבנים אלא ודאי מדלא קמפלגי וכו' ודוקא בהוצאה שיש בה צורך יו\"ט קצת אמרינן מתוך שהותרה לצורך יו\"ט דכל אוכל נפש מותר הותרה נמי שלא לצורך אוכל נפש הואיל ואיכא צורך מקצת שיש צורך יו\"ט אבל שלא לצורך יו\"ט כלל ודאי דאסור מן התורה כגון אופה מיו\"ט לחול ומוציא אבנים דליכא לא צורך נפש ולא שמחת יו\"ט חייב מדאורייתא וכי פליגי ב\"ש וב\"ה בדברים שאינן לצורך אוכל נפש ואיכא בהן צורך יו\"ט קצת כגון קטן למולו דהמצוה נקראת צורך יום טוב ולולב לצאת בו וס\"ת לקרות בו וכן פי' רבינו חננאל אבל. ליתא פירושן דלאו דוקא קטן למולו דה\"ה שלא למולו דשרי גם טיול דהא אשכחן נמי דמשחקין בכדור שקורין פלוט\"א בלע\"ז ביו\"ט ברה\"ר אע\"ג דליכא אלא טיול וא\"ת השוחט עולה מה צורך יש לו בה יש לומר דהכא נמי איכא שמחת יו\"ט שלא יהא שלחנך מלא ושלחן רבך ריקן כדמוכח לקמן (ביצה דף כ:):"]]],[["משום הבערה","א\"ל פוק תני לברא הבערה ובשול אינה משנה ואם תמצא לומר משנה בית שמאי היא דאמרי לא אמרינן מתוך שהותרה הוצאה לצורך הותרה נמי שלא לצורך ה\"נ לא אמרינן מתוך שהותרה הבערה לצורך הותרה נמי שלא לצורך","דאי בית הלל כיון דאמרי מתוך שהותרה הוצאה לצורך הותרה נמי שלא לצורך הכא נמי מתוך שהותרה הבערה לצורך הותרה נמי שלא לצורך:","\u0001מתני׳\u0002 בש\"א אין מוליכין חלה ומתנות לכהן ביום טוב בין שהורמו מאמש בין שהורמו מהיום ובית הלל מתירין","אמרו להם בית שמאי גזרה שוה חלה ומתנות מתנה לכהן ותרומה מתנה לכהן כשם שאין מוליכין את התרומה כך אין מוליכין את המתנות","אמרו להם בית הלל לא אם אמרתם בתרומה שאינו זכאי בהרמתה תאמרו במתנות שזכאי בהרמתן:","\u0001גמ׳\u0002 קא סלקא דעתך שהורמו מהיום ושנשחטו מהיום ושהורמו מאמש ושנשחטו מאמש מני מתניתין לא רבי יוסי ולא רבי יהודה אלא אחרים דתניא אמר רבי יהודה לא נחלקו בית שמאי ובית הלל על המתנות שהורמו מערב יום טוב שמוליכין עם המתנות שהורמו מהיום ושנשחטו מהיום לא נחלקו אלא להוליכן בפני עצמן שבית שמאי אומרים אין מוליכין ובית הלל אומרים מוליכין","וכך היו בית שמאי דנין חלה ומתנות מתנה לכהן ותרומה מתנה לכהן כשם שאין מוליכין את התרומה כך אין מוליכין את המתנות אמרו להם בית הלל לא אם אמרתם בתרומה שאינו זכאי בהרמתה תאמרו במתנות שזכאי בהרמתן","אמר רבי יוסי לא נחלקו בית שמאי ובית הלל על המתנות שמוליכין לא נחלקו אלא על התרומה שבית שמאי אומרים אין מוליכין ובית הלל אומרים מוליכין וכך היו בית הלל דנין חלה ומתנות מתנה לכהן ותרומה מתנה לכהן כשם שמוליכין את המתנות כך מוליכין את התרומה אמרו להם בית שמאי לא אם אמרתם במתנות שזכאי בהרמתן תאמרו בתרומה שאין זכאי בהרמתה","אחרים אומרים לא נחלקו בית שמאי ובית הלל על התרומה שאין מוליכין לא נחלקו אלא על המתנות שבית שמאי אומרים אין מוליכין ובית הלל אומרים מוליכין לימא אחרים היא ולא רבי יהודה","אמר רבא מי קתני שהורמו מהיום ושנשחטו מהיום שהורמו קתני ולעולם שחיטתן מאמש לימא רבי יהודה היא ולא אחרים אפילו תימא אחרים ובהנך דנשחטו מאמש","אי הכי היינו רבי יהודה איכא בינייהו טפלה:","אמר רב יהודה אמר שמואל הלכה כרבי יוסי רב טובי בריה דרב נחמיה הוה ליה גרבא דחמרא דתרומה אתא לקמיה דרב יוסף אמר ליה מהו לאמטויי לכהן האידנא א\"ל הכי אמר רב יהודה אמר שמואל הלכה כרבי יוסי","אושפזיכניה דרבא בר רב חנן הוה ליה אסורייתא דחרדלא א\"ל מהו לפרוכי ומיכל מנייהו ביו\"ט לא הוה בידיה אתא לקמיה דרבא א\"ל מוללין מלילות ומפרכין קטניות ביו\"ט","איתיביה אביי המולל מלילות מערב שבת למחר מנפח מיד ליד ואוכל אבל לא בקנון ולא בתמחוי","המולל מלילות מערב יום טוב למחר מנפח על יד על יד ואוכל אפילו בקנון ואפילו בתמחוי אבל לא בטבלא ולא בנפה ולא בכברה מערב יום טוב אין ביו\"ט לא","אפילו תימא ביו\"ט ואיידי דתנא רישא מערב שבת תנא סיפא נמי מערב יום טוב","א\"כ מצינו תרומה שזכאי בהרמתה ותנן לא אם אמרתם בתרומה שאינו זכאי בהרמתה וכו'","לא קשיא"],[[0,"משום הבערה","שהיא מלאכה לעצמה קא סבר יש חלוק מלאכות ליום טוב ללקות שתים על שתי מלאכות משום יום טוב:"],[1,"הבערה ובשול","דיום טוב אינה משנה ללקות עליהן דמתוך שהותרו לצורך הותרו נמי שלא לצורך מן התורה:"],[1,"אינה משנה","לא נשנית מעולם בבית המדרש:"],[1,"ואם תמצא לומר משנה","אם יאמרו תנאים שנשנית ודאי בית שמאי שנאוה:"],[3,"מתני' אין מוליכין חלה","אע\"פ שמותר בהפרשתה לא שרו ליה הולכתה אלא תקון לתקן עיסתו התירו לו ולא יותר:"],[3,"מתנות","הזרוע והלחיים והקיבה אף הן הרמתן הותרה לו שהרי נצטוה להרימן והיאך יאכל שאר הבשר ואע\"פ שאין טובלין כשאר טבל לאסור הבשר באכילה מיהו אם לא פירש שאר הבשר מהן הרי הוא אוכלן ועובר בעשה הלכך הרמתן התירו ולא הולכתן וכולן משום גזרה דאין מגביהין אותם:"],[4,"גזרה שוה","לאו דוקא דכולה מדרבנן גזור אלא דומיא דגזרה שוה בדרבנן:"],[4,"מתנה לכהן","מעשרים וארבע מתנות כהונה הן:"],[4,"כשם שאין מוליכין","דבהא מודיתו לן שהרי מאתמול הוגבהה:"],[5,"שאינו זכאי","רשאי לא נתנו חכמים לאדם כח וזכות בהפרשתה:"],[6,"","גמ' לא ר' יוסי ולא רבי יהודה אלא אחרים גרסינן:"],[8,"שמוליכין אותן כו'","ומתניתין קתני בין שהורמו מהיום וקס\"ד דבנשחטו היום קא מיירי ואסר:"],[8,"על המתנות שמוליכין","הואיל וזכאי בהרמתן והוא הדין לחלה וחד מינייהו נקט:"],[9,"אלא על המתנות","ואפילו נשחטו מהיום משמע כי מתניתין:"],[9,"לימא אחרים היא ולא ר' יהודה","כלומר כר' יוסי ודאי לא אפשר לאוקמא כרבי יהודה מאי מי מצינן למימר דמתניתין נמי דוקא בשל אמש קאמר ומתוקם אליביה או נזקק על כרחנו לומר דלא כרבי יהודה:"],[10,"מי קתני","מתני' בין שהורמו ונשחטו מהיום ולעולם שחיטתן מאמש אבל בהנך דנשחטו ביום טוב מודו:"],[10,"לימא רבי יהודה היא ולא אחרים","כיון דמתניתין דוקא בדשל אמש קאי מדלא קתני נשחטו היום נימא דלא כאחרים דהא אחרים על המתנות קאמרי:"],[10,"בהנך דנשחטו מאמש","על המתנות דקאמרי אחרים בשל אמש קמיירי:"],[11,"טפלה","ר' יהודה מתיר לטפל ולהוליך של אמש עם של היום ואחרים סברי דאפי' לטפל נמי אסרי ב\"ש ומתני' דלא איירי בטפלה כלל איכא למימר כרבי יהודה ואיכא למימר כאחרים:"],[12,"הלכה כרבי יוסי","ואליבא דב\"ה דאפי' תרומה נמי מותר להוליך:"],[13,"אסורייתא","חבילות של חרדל בשרביטין והזרע בתוכן:"],[13,"מהו לפרוכי","השרביטין ולהוציא הזרע ביום טוב מי שרי בי\"ט כשחיטה וכבישול או דלמא כיון דאפשר מערב יו\"ט לא דתולדת דישה הוא:"],[13,"מוללין מלילות","דדש כלאחר יד הוא ואפילו בשבת לאו דאורייתא הוא אלא מדרבנן וביום טוב לא גזור:"],[14,"מלילות","של חטין שמולל בידיו כשהן רכים: גבי שבת גרסי' מיד ליד וגבי יום טוב גרסי' על יד על יד:"],[14,"מיד ליד","שלא כדרך חול:"],[14,"קנון","כלי הוא ראשו אחד רחב והשני עשוי כעין מרזב קצר ונותן הקטניות בתוך הרחב ומנענע והאוכל מתגלגל דרך המרזב והפסולת נשאר בכלי:"],[14,"תמחוי","קערה גדולה:"],[15,"על יד על יד","מעט מעט:"],[15,"אבל לא בטבלא כו'","דמחזי כמאן דעביד לצורך מחר שאין דרך לעשות בכלים הללו אלא הרבה:"],[15,"מערב יום טוב אין","המולל מערב יו\"ט קתני ולא קתני המולל ביו\"ט:"],[17,"אם כן","דמוללין מלילות ביו\"ט מצינו תרומה שזכאי בהרמתה דסתם שבלין לא מפרישין תרומה עד שיעשו דגן והמוללן ביו\"ט לאכלן מפריש מהן תרומה על כרחו:"]],[[2,"","הכא נמי כיון שהותרה הבערה לצורך וכו'. וא\"ת ומה צורך איכא במבשל גיד כיון שהוא אסור יש לומר כיון שהיה בדעתו של זה לאכלו היינו צורך יום טוב:"],[3,"","אין מוליכין חלה ומתנות לכהן כו'. פי' לאו דוקא מוליכין דה\"ה אם יבא הכהן לביתו לא יתנם לו וכן משמע בירושלמי דדמאי פרק הלוקח פירות בהדיא דקאמר התם מי שקרא שם לתרומת מעשר דמאי ולמעשר עני של ודאי לא יטלם בשבת אבל אם כהן ועני רגילים לאכול אצלו באין ואוכלין ובלבד שיודיעם פי' מאתמול וקאמר. עלה דההוא דקאמר לא יטלם היינו מתניתין לא יתנם ומייתי מהך דהכא אין מוליכין וכו' ומסיק ילפי' הוא מההיא וההיא ילפינן מהוא הוא ילפינן מההיא הוא יו\"ט היא שבת פי' ה\"ק דהיא דבשבת ילפינן מההוא דאין מוליכין דמיירי ביו\"ט והוא ילפינן מהיא דוקא מה שמתירין ב\"ה היינו דוקא כשרגילין לאכול אצלו ואותה של ירושלמי קרי היא אלמא דאם אין למדין לאכול אצלו לא יתנם אפי' אם יבא הכהן לביתו משום דלא סלקא אדעתא דבר אינש למיכל פיסתיה בביתא דחבריה ויסברו העולם שהוא תרם אותם ביום טוב ולכך הוא אוכל בביתו:"]]],[["הא רבי הא ר' יוסי בר' יהודה דתניא הכניס שבלין לעשות מהן עיסה אוכל מהן עראי ופטור","למוללן במלילות רבי מחייב ור' יוסי ברבי יהודה פוטר","ולרבי יוסי ברבי יהודה נמי משכחת לה כגון שהכניס שבלין לעשות מהן עיסה ונמלך עליהן למוללן ביום טוב דטבלא ביומיה","אלא מאי תרומה רוב תרומה","אמר אביי מחלוקת בשבלין אבל בקטניות דברי הכל אסורייתא טבלא","לימא מסייע ליה מי שהיו לו חבילי תלתן של טבל הרי זה כותש ומחשב כמה זרע יש בהם ומפריש על הזרע ואינו מפריש על העץ מאי לאו רבי יוסי בר' יהודה היא דאמר התם לא טבלא הכא טבלא","לא רבי היא אי רבי היא מאי איריא תלתן אפי' שבלין נמי","אלא מאי רבי יוסי בר' יהודה לשמעינן שאר מיני קטניות וכ\"ש תלתן","אלא תלתן אצטריכא ליה סד\"א הואיל וטעם עצו ופריו שוה לפרוש נמי אעצו קמ\"ל","איכא דאמרי אמר אביי מחלוקת בשבלין אבל בקטניות דברי הכל אסורייתא לא טבלא מיתיבי מי שהיו לו חבילי תלתן של טבל הרי זה כותש ומחשב כמה זרע יש בהן ומפריש על הזרע ואינו מפריש על העץ מאי לאו טבל טבול של תרומה","לא טבל טבול של תרומת מעשר","וכדר' אבהו א\"ר שמעון בן לקיש דאמר רבי אבהו אמר רבי שמעון בן לקיש מעשר ראשון שהקדימו בשבלין","שמו טובלו לתרומת מעשר","כותש למה לי לימא ליה כי היכי דיהבו לי הכי יהיבנא לך אמר רבא קנסא","תניא נמי הכי בן לוי שנתנו לו שבלין במעשרותיו עושה אותן גורן ענבים עושה אותן יין זיתים עושה אותן שמן ומפריש עליהם תרומת מעשר ונותנן לכהן שכשם שתרומה גדולה אינה ניטלת"],[[0,"הא רבי הא ר' יוסי ברבי יהודה","לעולם מוללין מלילות לדברי הכל ודקשיא לן אם כן מצינו תרומה שזכאי בהרמתה אין ודאי מצינו אליבא דרבי דאמר יש תרומה במלילות ומתניתין דקתני לא מצינו ר' יוסי ברבי יהודה היא דאמר אין תרומה במלילות:"],[0,"אוכל מהן עראי","כל זמן שלא דשן ומרחן בכרי לא נגמרה מלאכתן לתרומה:"],[1,"למוללן במלילות","הכניסן לאכלן מעט מעט ע\"י מלילות:"],[1,"רבי מחייב","בתרומה שלא יאכל מהן עראי עד שיפריש לפי שהכנסתן בשבלין היא גמר מלאכתן שאין סופן לבא לידי גורן אחר וזהו גרנן:"],[1,"ורבי יוסי בר' יהודה פוטר","דגנך כתיב והיינו מרוח דאין דגון אלא קבוץ בכרי: ופרכינן לרבא דאמר מוללן לר' יוסי ברבי יהודה נמי אי שרית למוללן ביו\"ט משכחת לה על כרחיך שזכאי בהרמתה במלילות שהכניסן לעשות עיסה בדישה ומרוח ונמלך עליהן למוללן להצניען כולן למלילות דעל כרחיך מודה בהו רבי יוסי דטבלן ביום שנמלך עליהן דכיון דהכניסן לשם גורן גמור ירדה להן תורת תרומות ומעשרות וכשנמלך למוללן נעשית הכנסתו גורן והמוללן ביו\"ט על כרחו קדים תרומתן:"],[3,"אלא מאי תרומה רוב תרומה גרסינן","ולא גרס אלא מאי אית לך למימר אלא לא תימא הא רבי הא רבי יוסי דבין לרבי בין לרבי יוסי מתוקמא ומאי תרומה דתנן מתניתין אינו זכאי בהרמתה ברוב תרומות קאמר שישנן על ידי דישה ומרוח והן מערב יום טוב:"],[4,"מחלוקת בשבלין","בהנהו הוא דפטר ר' יוסי דרובן לדישה ואין גרנן אלא במרוח:"],[4,"אבל קטניות","יש בני אדם הרבה שאין חובטין אותן יחד אלא כדי קדרתן לפיכך הכנסתן בחבילין זהו גרנן:"],[5,"תלתן","מין קטנית הוא ומעט נותנין בקדרה ליתן טעם:"],[5,"כותש","זהו דרך דישתן:"],[5,"ומחשב","מאומד:"],[5,"ואין מפריש על העץ","אין צריך להפריש מן הקשים ואף על פי שטעם עצו ופריו שוה לא חייבוהו חכמים במעשרות מדקתני חבילין של טבל אלמא אסורייתא טבלא:"],[7,"לשמעינן שאר מיני קטניות","דטבלו בחבילי ואף על פי שהרבה עושין מהן כרי ומרוח וכ\"ש תלתן שהוא נותנו מעט מעט בקדרה למתק ונותנו בעצו:"],[8,"אלא תלתן אצטריכא ליה גרסינן","ולעולם רבי היא וה\"ה לשבלין ולא תסייעי' מהכא:"],[9,"איכא דאמרי אמר אביי מחלוקת בשבלין","בהנהו מחייב רבי לפי שהרבה כונסין אותן למלילות וקליות שהן גרנן אבל בקטניות סתם הכנסתם למרוח ואסורייתא לא טבלא:"],[9,"מאי לאו בטבל טבול לתרומה","כלומר מאי לאו גבי ישראל קרי ליה טבל ועדיין לא נקרא עליו שם בפה ומסתמא קרוי טבל וחייב לתרומה שהיא תחלה לכל המעשרות דכתיב בה ראשית:"],[10,"לא בטבל טבול לתרומת מעשר","לעולם אין חבילין גמר מלאכה ואילו גבי ישראל הוא לא הוה מקרי טבל אלא בבן לוי קאי שקדם והלך אצל ישראל ונטל מעשר ראשון ממנו בחבילין והואיל וחל על חבילין הללו שם מעשר נעשו טבל אצלו להפריש מהם תרומת מעשר מן המעשר שעל הלוי להפריש והיא במיתה וכל תורת תרומה עליה דתרומה קרייה רחמנא:"],[11,"שהקדימו בשבלין","שהקדימו לתרומה גדולה:"],[12,"שמו טובלו","שם מעשר שנקרא עליו טובלו ואוסרו באכילת עראי ובמיתה כדין טבל עד שירים תרומת מעשר שלו ולקמיה יהיב טעמא:"],[13,"כותש למה לי","אי בבן לוי מוקמינן ליה למה מוטל עליו לעשותו דגן אי אמרת בשלמא בישראל קאי ואסורייתא טבלא שפיר תנא כותש דכתיב דגנך ודרבנן דומיא דאורייתא תקון:"],[13,"קנסא","על שהקדים וגרם להערים לעבור על דברי תורה שהמשנה סדר המעשרות עובר בלאו מלאתך ודמעך לא תאחר (שמות כג) דהכי קאמר לא תאחר תרומה להקדים לה מעשר:"],[14,"","יעשה אותו גורן גרסינן:"]],[[0,"","הא רבי יוסי. פרש\"י ומה מצינו דזכאי בהרמתה היינו אליבא דרבי דאמר יש תרומה במלילות דסבר דהכנסתן דמלילות היינו גרנן וגמר מלאכה אבל מתני' דקתני לא מצינו היינו ר' יוסי ברבי יהודה דאמר אין תרומה במלילות דאדגן קפיד רחמנא ואין זה אלא קבוץ בעלמא ובסמוך גרסינן ולרבי יוסי בר' יהודה נמי משכחת לה וכו' משמע לפי' דלר' יוסי אפי' אכילת קבע יכול לאכול בלא מעשר דאם היה מחייב באכילת קבע משכחת לה לר' יוסי בר' יהודה דזכאי בהרמתה באכילת קבע ותימה דהלשון לא משמע כן דהא קאי על אכילת עראי הכניס שבלין לעשות מהן עיסה אוכל מהן עראי ופטור ועלה מסיק למוללן במלילות רבי מחייב מעראי ור' יוסי בר' יהודה פוטר מעראי וע\"ק לרבי נמי היכי מצינו (הוא) שזכאי בהרמתה ביו\"ט הואיל דאית ליה דהכנסתן למלילות זהו גרנן וגמר מלאכתן אם כן נתחייבו מאתמול מעיו\"ט ואם כן אין יכול להפריש ביו\"ט לכן נ\"ל דהא דקאמר דכהן זכאי בהרמתה אתיא אליבא דר' יוסי ברבי יהודה דפוטר דכיון דסבר דהכנסתן לאו זהו גרנן ואם כן כי מללן ביו\"ט בא לו חיוב השתא וא\"כ זכאי בהרמתה והא דאמר דאינו זכאי בהרמתה אתי אליבא דרבי דס\"ל דהכנסתן זו היא גרנן והיה להם לתרום מאתמול וא\"כ אינו זכאי בהרמתה ובסמוך גרסי' ולרבי משכחת לה וכו':"],[9,"","איכא דאמרי מחלוקת בשבלים אבל בקטניות ד\"ה לא טבלא. והקשה הר\"ר שמשון מקוצי דבכל התלמוד לא מצינו איכא דאמרי כה\"ג שהוא להפך מן הראשון דודאי . מצינו בשאר מקומות לישנא קמא דברי הכל ואיכא דאמרי בהא נמי פליגי או איכא דאמרי בהא פליגי ובהא דלישנא קמא דברי הכל אבל כה\"ג לא דכל הפחות הוה לי' למימר דבקטניות מחלוקת אבל בשבלין כ\"ע מודו ותירץ דה\"ק לישנא קמא מחלוקת בשבלין היכא שפירש בהדיא שהכניסן לשבלין אבל בקטנית שפירש למוללן ד\"ה טבלא וה\"ה דפליגי בקטניות סתם ובשבלין סתם ולאיכא דאמרי ה\"ק מחלוקת בשבלין סתם שלא פירש למוללן אבל בקטניות סתמא כ\"ע מודו דלא טבלו וה\"ה בקטניות שהכניסן למוללן פליגי וכן בשבלין פליגי והשתא ניחא דלא הוי להיפך לגמרי דהא דקאמר לישנא קמא דפליגי מסיק הכא בדאיכא דאמרי ד\"ה [לא] טבלא וא\"ת והא לא מיירי כלל בפלוגתיה רק במפרש שהכניסן לשבלים יש לומר דמה דקתני סיפא למוללן במלילות משום דמסתמא כמו למוללן במלילות דכל שלא פיר' דהוו לעשות מהן עיסה הוי כמו למוללן במלילות בשבלים אבל תימה להאי פירושא דמקשה בסמוך מאי לאו בטבל וכו' מאי פריך לשני ליה דמיירי בדמפרש והכא מיירי בסתם ויש לומר דמשמע דמיירי בכל ענין אפילו בסתמא ועוד דבעי אליבא דכלהו תנאי:"]]],[["אלא מן הגורן ומן היקב כך תרומת מעשר אינה ניטלת אלא מן הגורן ומן היקב","מחשב הא מדידה בעי","הא מני אבא אלעזר בן גימל היא דתניא אבא אלעזר בן גימל אומר (במדבר יח, כז) ונחשב לכם תרומתכם בשתי תרומות הכתוב מדבר אחת תרומה גדולה ואחת תרומת מעשר כשם שתרומה גדולה ניטלת באומד ובמחשבה כך תרומת מעשר ניטלת באומד ובמחשבה","גופא א\"ר אבהו א\"ר שמעון בן לקיש מעשר ראשון שהקדימו בשבלין שמו טובלו לתרומת מעשר מאי טעמא אמר רבא הואיל ויצא עליו שם מעשר:","אמר ר\"ש בן לקיש מעשר ראשון שהקדימו בשבלין פטור מתרומה גדולה","שנא' (במדבר יח, כו) והרמותם ממנו תרומת ה' מעשר מן המעשר מעשר מן המעשר אמרתי לך ולא תרומה גדולה ותרומת מעשר מן המעשר","א\"ל רב פפא לאביי אי הכי אפילו הקדימו בכרי נמי אמר ליה עליך אמר קרא (במדבר יח, כט) מכל (מעשרותיכם) תרימו את כל תרומת ה'","ומה ראית האי אדגן והאי לא אדגן:","תנן התם המקלף שעורין מקלף אחת אחת ואוכל ואם קלף ונתן לתוך ידו חייב אמר רבי אלעזר וכן לשבת","איני והא רב מקלפא ליה דביתהו כסי כסי ור' חייא מקלפא ליה דביתהו כסי כסי אלא אי אתמר אסיפא אתמר המולל מלילות של חטים מנפח על יד על יד ואוכל ואם נפח ונתן לתוך חיקו חייב אמר רבי אלעזר וכן לשבת","מתקיף לה רבי אבא בר ממל ורישא למעשר אין לשבת לא ומי איכא מידי דלענין שבת לא הוי גמר מלאכה ולמעשר הוי גמר מלאכה","מתקיף לה רב ששת בריה דרב אידי ולא והא גרנן למעשר דתנן איזהו גרנן למעשר הקשואין והדלועין משיפקסו ושלא פקסו משיעמיד ערמה ותנן נמי גבי בצלים משיעמיד ערמה ואילו גבי שבת העמדת ערמה פטור","אלא מאי אית לך למימר מלאכת מחשבת אסרה תורה הכא נמי מלאכת מחשבת אסרה תורה:","כיצד מולל אביי משמיה דרב יוסף אמר חדא אחדא ורב אויא משמיה דרב יוסף אמר חדא אתרתי רבא אמר כיון דמשני אפילו חדא אכולהו נמי","כיצד מנפח אמר רב אדא בר אהבה אמר רב מנפח"],[[0,"אלא מן הגורן ומן היקב","שנגמר כולה דכתיב דגן תירוש ויצהר (במדבר יח):"],[1,"מחשב הא מדידה בעי","בשלמא אי בישראל מוקמת לה ובתרומה גדולה איכא למיתני מחשב דניטלת באומד שתרומה גדולה לא נתנה בה התורה שיעור דכתיב ראשית דגנך (דברים יח) ורבנן הוא דאמרי שיעור עין יפה ובינונית ורעה הלכך באומד סגי דאי נמי לא יהיב כשיעור חטה אחת פוטרת כל הכרי אבל גבי לוי מעשר מן המעשר כתיב (במדבר יח) וצריך למדוד:"],[2,"","אבא אלעזר בן גימל גרסי':"],[2,"ונחשב לכם תרומתכם","בלוים כתיב:"],[2,"בשתי תרומות הכתוב במדבר","דכתיב כדגן מן הגורן זו תרומה גדולה תרומתכם זו תרומת מעשר:"],[2,"מה תרומה גדולה נטלת באומד","כדפריש' דלא כתיב בה שיעור:"],[2,"ובמחשבה","נותן עיניו בצד זה ואוכל בצד אחר דכתיב ונחשב ואתרוייהו קאי והא דקא יליף לה מתרומה גדולה משום אומד נקט לה:"],[3,"הואיל ויצא עליו שם מעשר","ורחמנא אמר והרמותם ממנו מעשר מן המעשר משנקרא מעשר הזקיקם לתרומתו:"],[4,"פטור מתרומה גדולה","שהיה לו לכהן ליטול תרומה גדולה תחלה שהרי קרויה ראשית והלוי אחריו מעשר במה שמשייר וזה שנטל מעשר תחלה ונמצא שלא הורמה תרומה גדולה ממעשרו וישראל לא יתן לכהן אלא אחד מחמשים במה ששייר נמצא כהן מפסיד פטור הלוי מתרומה גדולה שבמעשר זה שנאמר והרמותם ממנו תרומת ה' ופירש ומה היא התרומה מעשר מן המעשר:"],[6,"אפילו הקדימו","לתרומה בכרי משנתמרח נפטר לוי מהאי קרא:"],[6,"עליך אמר קרא","כדי שלא תאמר כן:"],[6,"מכל (מעשרותיכם) תרימו את כל תרומת ה'","ובלוים כתיב ולהכי כתיב כל למימר דכל צד תרומה המוטלת בו יתן:"],[7,"ומה ראית","דהאי כל דמרבי שדית ליה אהקדימו בכרי ואידך אהקדימו בשבלים אימא איפכא:"],[7,"האי אדגן","הקדימו בכרי כבר נעשה דגן ומשבא לכלל דגן חלה עליו חובת כהן דכתיב ראשית דגנך הלכך מסתברא דהאי קרא דזכותא דכהן אכרי תשדייה:"],[8,"המקלף שעורים","לאוכלן קלופים חיים:"],[8,"ואוכל","ופטור מן המעשר דכי האי גוונא אכילת עראי היא ובשלא נתמרחו קאי שמקלפן מתוך שבולת שלהן:"],[8,"חייב","במעשר דהוה ליה קבע:"],[8,"וכן לשבת","אחת אחת לא הוי מפרק תולדה דדש דכלאחר יד הוא אבל משקבצן בידו הויא תולדת דישה וחייב:"],[9,"כסי כסי","מלא כוסות:"],[9,"ואוכל","בלא מעשר:"],[9,"לתוך חיקו","בשולי בגדיו שקורין פאנ\"ץ:"],[11,"והרי גרנו של מעשר","כלומר הרבה מלאכות שאמרו שהן קובעות גורן למעשר לאסרו באכילת עראי ומותרות בשבת:"],[11,"איזהו גרנן למעשר","לעיל מינה איירי בפירות וקאמר אימתי גמר מלאכתן ליקבע למעשר:"],[11,"משיפקסו","משניטל פקס שלהן והוא כמין פרח בראשו כמו שיש בתפוחים ונופל מאליו כשמתיבש:"],[11,"ושלא פקסו משיעמיד ערמה","כלומר ואם עד שלא פקסו העמיד ערמה מהן כמין כרי הוקבעו אלמא העמדת ערמה הויא גמר מלאכה למעשר ולענין שבת משהביא בצלים לביתו אין העמדת ערמה מלאכה:"],[12,"אלא מאי אית לך למימר","אע\"ג דלמעשר הויא מלאכה לשבת מלאכת מחשבת שהיא מלאכת אומנות אסרה תורה שנסמכה פרשת שבת למלאכת המשכן בויקהל והתם מלאכת מחשבת כתיב:"],[13,"כיצד מולל","ביום טוב דאמרן לעיל מוללין מלילות והא ודאי שינוי בעי מעובדא דחול:"],[13,"חדא אחדא","בין גודל לאצבע:"],[13,"חדא אתרתי","בין גודל לשתי אצבעותיו:"],[14,"כיצד מנפח","דאמרינן לעיל למחר מנפח מיד ליד בשבת:"]],[[2,"","כשם שתרומה גדולה ניטלת וכו'. ואם תאמר מה צריך למילף תרומת מעשר מתרומה גדולה דניטלת במחשבה תיפוק ליה דבהדיא כתיב בה ונחשב דקאי אתרומת מעשר וכו' ופ\"ה דלאו דוקא נקט מחשבה אלא אומד דוקא נקט ועי\"ל אי לאו דילפינן תרומת מעשר מתרומה גדולה לא הייתי אומר דתרומת מעשר ניטלת במחשבה דאי משום קרא דונחשב דכתיב גבי מעשר מוקמינן לה בתרומה גדולה דה\"ק בירושלמי כל התורה למדה ומלמדה חוץ מתרומת מעשר דמלמדה ואינה למדה דהא ממנו דכתיב גבי תרומת מעשר דמיניה נפקא מוקף דדרשינן ממנו מן הסמוך לו ומוקמינן לה בתרומה גדולה דבעינן מוקף אבל בתרומת מעשר מדאורייתא לא בעינן מוקף אלמא גבי ממנו דכתיב במעשר מוקמינן ליה בתרומה גדולה והכא נמי ונחשב נימא כדפרישית:"],[7,"","ומה ראית האי אדגן והאי לא אדגן. ותימה היכי אסיק אדעתיה דמקשה לומר אפכא דבשבלין יהא חייב ובהקדימן בכרי יהא פטור אם הוא חייב בשבלים כ\"ש בכרי שכל מה שאחרי כן יהא חייב ואומר הרר\"י דה\"ק מה ראית לחייב מכל צדדין הקדימו בכרי ופטור בשבלין אימא דבין חיוב ובין פטור בהקדימו בכרי פטור קודם ראיית פני הבית וחיוב לאחר ראיית פני הבית ומשני האי אדגן פירוש בהקדימו בכרי וא\"כ דין הוא שיהא חייב מכל צד:"],[8,"","ואם קלף ונתן לתוך ידו חייב. פרש\"י ואם קלף מתוך השבלין ותימה היכי מקלפא לרב דביתהו כסי כסי האמר לעיל דמולל מלילות מערב שבת וכו' משמע הא בשבת אסור ויש לומר דהתם מיירי לתלוש מן השבלים שהוא מפרק וזהו תולדה דדש שהוא אב מלאכה והכא מיירי בשכבר נתלשו מע\"ש מן השבלין אבל עוד הן בקליפתן החיצונה ולכך שרי ומה שפרש\"י הכא דאם קלף ונתן לתוך ידו חייב מפני שהוא קבע לא נהירא דבסמוך משמע שהטעם מפני שהוא גמר מלאכה הואיל והוא קולף הרבה ביחד דהיינו דגונו:"],[13,"","כיצד מולל. פי' ביו\"ט ובשבת אסור למלול וכיצד מנפח ר\"ל בשבת דביו\"ט שרי אף בקנון ובתמחוי:"],[14,"","כיצד מנפח וקאמר בין קשרי אצבעותיו. ותימה דלעיל אמר המולל מלילות מע\"'ש למחר מנפח מיד ליד כו' אבל לא בקנון וכו' ויש לומר דלעיל הוי פירוש בין קשרי אצבעותיו וקנון ותמחוי דנקט משום י\"ט נקט ליה:"]]],[["מקשרי אצבעותיו ולמעלה","מחכו עלה במערבא כיון דמשני אפילו בכולה ידא נמי אלא א\"ר אלעזר מנפח בידו אחת ובכל כחו:","\u0001מתני׳\u0002 בית שמאי אומרים תבלין נדוכין במדוך של עץ והמלח בפך ובעץ הפרור ובית הלל אומרים תבלין נדוכין כדרכן במדוך של אבן והמלח במדוך של עץ:","\u0001גמ׳\u0002 דכולי עלמא מיהת מלח בעיא שנוי מ\"ט רב הונא ורב חסדא חד אמר כל הקדרות כולן צריכות מלח ואין כל הקדרות צריכות תבלין","וחד אמר כל התבלין מפיגין טעמן ומלח אינה מפיגה טעמה","מאי בינייהו איכא בינייהו דידע מאי קדרה בעי לבשולי אי נמי במוריקא","אמר רב יהודה אמר שמואל כל הנדוכין נדוכין כדרכן ואפילו מלח והא אמרת מלח בעיא שנוי הוא דאמר כי האי תנא דתניא אמר רבי מאיר לא נחלקו בית שמאי ובית הלל על הנדוכין שנדוכין כדרכן ומלח עמהן","לא נחלקו אלא לדוכה בפני עצמה שבית שמאי אומרים מלח בפך ובעץ הפרור לצלי אבל לא לקדרה ובית הלל אומרים בכל דבר בכל דבר סלקא דעתך אלא אימא לכל דבר","א\"ל רב אחא ברדלא לבריה כי דייכת אצלי אצלויי ודוך רב ששת שמע קל בוכנא אמר האי לאו מגוויה דביתאי הוא","ודלמא אצלויי אצלי דשמעיה דהוה צליל קליה ודלמא תבלין הוו תבלין נבוחי מנבח קלייהו","תנו רבנן אין עושין טיסני ואין כותשין במכתשת תרתי הכי קאמר מה טעם אין עושין טיסני לפי שאין כותשין במכתשת","ולימא אין כותשין במכתשת אי תני אין כותשין במכתשת הוה אמינא ה\"מ במכתשת גדולה אבל במכתשת קטנה אימא שפיר דמי קמ\"ל","והתניא אין כותשין במכתשת גדולה אבל כותשין במכתשת קטנה אמר אביי כי תניא נמי מתניתא מכתשת גדולה תניא"],[[0,"מקשרי אצבעותיו","ולא בכפו:"],[2,"מתני' מדוך","הוא בוכנא שמכין בו כדרכו ואין צריך שנוי אבל במלח במקום שיש מלח גסה בפך של חרס ידוכנו ולא במדוכה:"],[2,"או בעץ פרור","כף גדולה שקורין פוקי\"א דמלח בעי שנוי ובגמרא מפרש טעמא:"],[2,"והמלח במדוך של עץ","שנוי בעי אבל סגי בהאי שנוי זוטא:"],[3,"גמ' כל הקדרות","כל מיני תבשיל צריכות מלח הלכך מאתמול הוה ידע דאיבעי לי' לדוכה:"],[3,"ואין כל הקדרות צריכות תבלין","ואדם אינו יודע מה יעלה בלבו לאכול מחר:"],[4,"מפיגין טעמן","ממירין טעמן אם ידוכן מאתמול ריחו לא נמר (ירמיהו מ״ח:י״א) מתרגמינן לא פג:"],[5,"דידע מאתמול מאי קדרה בעי בשולי","ללישנא קמא בעי שנוי ללישנא בתרא לא בעי שנוי:"],[5,"אי נמי","תבלין של מוריקא איכא בינייהו שיש קדרה שמתבלין אותה בכרכום ואינו מפיג טעמו אם נדוך מבעוד יום והוא לא היה יודע מה יבשל מחר ללישנא בתרא בעי שנוי ללישנא קמא לא בעי שנוי:"],[6,"עמהם","מלח ותבלין כאחד:"],[7,"לא נחלקו אלא לדוכה בפני עצמה","כדרכה כשאר תבלין:"],[7,"בפך ובעץ הפרור","על ידי שנוי ולא כדרכה ולצלי דהיינו דבר מועט:"],[7,"בכל דבר סלקא דעתך","ואפי' בדבר שאין ניטל בשבת:"],[7,"לכל דבר","ואפי' לקדרה ועל כרחך כדרכה אמרי ככל דרך שיטת הש\"ס דעל מה נחלקו דומיא דלא נחלקו קאמר לא נחלקו על התבלין ומלח כאחד שנדוכין כדרכן על מה נחלקו לדוך כדרכה על מלח בפני עצמה שב\"ש אומרים בפך בשנוי ועוד מחמיר לצלי ולא לקדרה וב\"ה אומרים לכל דבר נדוכית כדרכה ולא הוצרך לפרש שכבר פירש:"],[8,"כי דייכת","מלח:"],[8,"אצלי אצלויי ודוך","הטה המדוכה על צדה דסבר כשמואל דאמר נידוכת כדרכה במדוך של אבן ומיהו שנוי זוטא בעי לשנויי:"],[8,"קל בוכנא","במדוכת מלח:"],[8,"האי לאו מגויה דביתאי הוא","יודע אני שאין זה בתוך ביתי שאסרתי עליהם לדוך במדוך של אבן בלא שנוי:"],[9,"דהוה צליל קליה","ואילו מכה בהשמטה באלכסון לא היה קולו צלול:"],[9,"ודילמא תבלין הוו","שאינן צריכין שנוי:"],[9,"נבוחי מנבח","כשהן משברין הגרעינים נשמע קולו במדוכה כמנבחים קרוישנ\"ט:"],[10,"אין עושין טיסני","בי\"ט שטורח גדול הוא שכותש החטין עד שנחלקים א' לארבעה כדאמרי' במו\"ק (ד' יג:):"],[10,"תרתי","שני דברים יש כאן לא זה דומה לזה קתני אין עושין טיסני הא חלקא ודייסא שפיר דמי דאין טרחן מרובה והדר תני אין כותשין כלל:"],[11,"ולימא אין כותשין","ואנא ידענא דתו לא מתעביד טיסנא: סתם מכתשת היינו גדולה:"],[11,"אבל קטנה אימא שפיר דמי","אפילו טיסני:"],[11,"קא משמע לן","אין עושין טיסני כלל לפי שאין כותשין שום כתישה במכתשת והך מכתשת על כרחיך לא שנא גדולה ולא שנא קטנה מדתני רישא אין עושין טיסני כלל:"],[12,"אבל כותשין בקטנה","דהוי כלאחר יד דאינה אלא לתבלין:"],[12,"כי תניא נמי מתני'","דלעיל מכתשת גדולה תניא ולא תימא מה טעם קאמר אלא תרתי קתני וה\"ק אין עושין טיסני כלל אפי' בקטנה ואין כותשין שאר כתישות במכתשת כגון דייסא וסתם מכתשת בגדולה קא מיירי:"]],[[2,"","בית הלל אומרים תבלין נידוכין במדוך של אבן. ותימה דמשמע הכא דתבלין מותר לדוך בלא שנוי ובמסכת שבת (דף קמא. ושם) קאמר פלפלין בקתא דסכינא חדא חדא שרי תרי תרי אסיר וכי תימא דיש חילוק בין פלפלין לתבלין זה אינו דבהדיא קאמר בתוספתא עלה דהכא פלפלין הרי הוא כתבלין וי\"ל דהתם מיירי בשבת ותדע דשמעתא דהתם מיירי בשבת דאם רוצה לומר בי\"ט היה לו לפרש . כדפירש ר\"ח והכא מיירי בי\"ט וא\"כ שרי כדרכו ואפי' במדוך של אבן אבל מלח של ים צריך שינוי לדוך אותו גרעין גרעין אבל שלינייונ\"י אין צריך שנוי הואיל והוא עשוי בידי אדם:"],[5,"","איכא בינייהו דידע כו' בעי לבשולי. דללישנא קמא בעי שנוי וללישנא בתרא לא בעי שנוי אי נמי בהאי שאינו מפיג טעמו ולא ידע דללישנא בתרא צריך שנוי וללישנא קמא לא צריך שנוי ופסק ר\"י שיש לאסור בכל ענין דאזלינן לחומרא אע\"ג דבשל סופרים הלך אחר המיקל הואיל ולכל אחד ואחד יש קולא וחומרא מכל צד עבדינן לחומרא ומיהו שומין מותר לתקנם בי\"ט בלא שנוי מפני שמתקלקלין ביותר אם יעשה אותן מערב יו\"ט ועוד דאמרינן דרוח רעה שורה עליהן כשנטחנין בלילה ומיהו מהאי פיסקא לא נפיק לן מידי דהא קי\"ל כשמואל בסמוך דכל הנדוכין נדוכין כדרכן וכדתניא דמייתי בר ממלח שצרי' אצלויי דרך שנוי מעט וכן פסק רב אלפס דהואיל ואזלי וגררי אמוראי אליבא דהאי ברייתא אע\"ג דבמתני' פליגא עלה קיימא לן כברייתא וכן פסק רב יהודאי גאון בהלכות פסוקות וכן יש מנהג הלכה למעשה דהך מלתא תליא באשלי רברבי ומ\"מ אסור לטחון פלפלין ברחים שלהם משום דמחזי כעובדא דחול כשטוחנין ברחים שקורין מוליני\"ט בלע\"ז כדאיתא בפ\"ב (דף כג.) אבל במדוך של אבן מותר לדוכן בלא שנוי ואף לפירוש התוספות דאזלינן לחומרא מכל מקום שמא דפלפלין מותרין היכא דלא ידע מאי קדרה בעי לבשולי לפי שהן מפיגין טעמן ופלפלין נמי מפיג טעמן מדלא קאמר איכא בינייהו פלפלין אבל לפי מה שפירש בשם הגדולים דקי\"ל דכל הנדוכין נדוכין כדרכן יש להתיר אפי' כי ידע מאי קדרה בעי לבשולי ואפילו לא מפיג טעמו והמחמיר לדוכן מעי\"ט הרבה ביחד יתברך באלהים ובשם המיוחד:"],[7,"","בכל דבר ס\"ד. פי' ואפילו בדבר שאין ניטל בשבת כגון סיכי זיירי ומזורי דמודי בהו ר' שמעון אלא אימא לכל דבר ואפילו לקדרה ואם תאמר ואכתי מאי מייתי דילמא לעולם בעי שנוי וי\"ל כדפ\"ה דשיטת התלמוד כך היא דדומיא דלא נחלקו קאמר דנחלקו וכי היכי דלא נחלקו על התבלין ומלח עמהן שנדוכין כדרכן ביחד בלא שנוי דומיא דהכי נחלקו בית שמאי וב\"ה על מלח בפני עצמה לדוכה כדרכה בלא שנוי:"],[10,"","תרתי. כלומר למה לי למימר תרתי דסתרי אהדדי אין עושין טיסני הא חלקא ודייסא שפיר דמי דאין טרחא מרובה והדר תני אין כותשין כלל כדפ\"ה:"],[12,"","כי תניא נמי במתניתא במכתשת גדולה תניא. פירוש והשתא נימא דתרתי קאמר והכי קאמר אין עושין טיסני כלל אפי' במכתשת קטנה ואין כותשין שאר דברים בגדולה אבל בקטנה כותשין הכל חוץ מטיסני משום דהאי דליכא רק לתבלין הוי כתישה כלאחר יד:"]]],[["רבא אמר לא קשיא הא לן והא להו","רב פפי אקלע לבי מר שמואל אייתי ליה דייסא ולא אכל ודלמא במכתשת קטנה עבדוה דחזייה דהוה דייק טפי","ודלמא מאתמול עבדוה דחזייה דהוה קליף צהריה ואי בעית אימא שאני בי מר שמואל דאיכא פריצותא דעבדי:","\u0001מתני׳\u0002 הבורר קטניות ביום טוב בית שמאי אומרים בורר אוכל ואוכל ובית הלל אומרים בורר כדרכו בחיקו בקנון ובתמחוי אבל לא בטבלא ולא בנפה ולא בכברה רבן גמליאל אומר אף מדיח ושולה:","\u0001גמ׳\u0002 תניא אמר רבן גמליאל במה דברים אמורים כשהאוכל מרובה על הפסולת אבל פסולת מרובה על האוכל דברי הכל נוטל את האוכל ומניח את הפסולת","פסולת מרובה על האוכל מי איכא מאן דשרי לא צריכא דנפיש בטרחא וזוטר בשיעורא:","רבן גמליאל אומר אף מדיח ושולה: תניא אמר רבי אלעזר בר' צדוק כך היה מנהגן של בית ר\"ג שהיו מביאין דלי מלא עדשים ומציפין עליו מים ונמצא אוכל למטה ופסולת למעלה","והתניא איפכא לא קשיא הא בעפרא הא בגילי:","\u0001מתני׳\u0002 בית שמאי אומרים אין משלחין ביום טוב אלא מנות ובית הלל אומרים משלחין בהמה חיה ועוף בין חיין בין שחוטין משלחין יינות שמנים וסלתות וקטניות אבל לא תבואה ורבי שמעון מתיר בתבואה:","\u0001גמ׳\u0002 תני רב יחיאל ובלבד שלא יעשנו בשורה תנא אין שורה פחותה משלשה בני אדם בעי רב אשי תלתא גברי ותלתא מיני מאי תיקו:","רבי שמעון מתיר בתבואה: תניא רבי שמעון מתיר בתבואה כגון חטין לעשות מהן לודיות שעורים ליתן לפני בהמתו עדשים לעשות מהן רסיסין:","\u0001מתני׳\u0002 משלחין כלים בין תפורין בין שאינן תפורין ואף על פי שיש בהן כלאים והן לצורך המועד אבל לא סנדל המסומר ולא מנעל שאינו תפור רבי יהודה אומר אף לא מנעל לבן מפני שצריך אומן זה הכלל כל שנאותין בו ביום טוב משלחין אותו:","\u0001גמ׳\u0002 בשלמא תפורין חזו למלבוש שאין תפורין נמי חזו לכסויי אלא כלאים למאי חזו","וכי תימא חזו למימך תותיה והתניא (ויקרא יט, יט) לֹא יַעֲלֶה עָלֶיךָ אבל אתה יכול להציעו תחתיך אבל אמרו חכמים אסור לעשות כן שמא תכרך לו נימא על בשרו","וכ\"ת דמפסיק מידי ביני ביני והאמר ר' שמעון בן פזי א\"ר יהושע בן לוי אמר ר' יוסי בן שאול אמר רבי משום קהלא קדישא דבירושלים אפילו עשר מצעות זו על גבי זו וכלאים תחתיהן אסור לישן עליהם (משום שנאמר לא יעלה עליך)","אלא בוילון והאמר עולא מפני מה אמרו וילון טמא מפני שהשמש מתחמם כנגדו"],[[0,"רבא אמר","לעולם מה טעם קאמר ובקטנה נמי קאי וקאמר אין כותשין כלל ודרמינן עלה אבל כותשין כו':"],[0,"הא לן","דלית לן עבדי דמזלזלי:"],[0,"הא להו","דאית להו עבדי דמזלזלי ועושין בגדולה ואומרים בקטנה עשינו:"],[2,"קליף צהריה","צוהר מראיתו היה קלוף ולבן:"],[3,"מתני' מדיח","במים:"],[3,"ושולה","מפרש בגמרא שולה הפסולת שצף למעלה כמו משישלה בחביות (ע\"ז דף נו.) דהיינו נמי שנוטל חרצנים הצפים ע\"פ החביות:"],[4,"בד\"א","דשרו ב\"ה ליטול פסולת ממש ולהשליך:"],[5,"מי איכא מאן דשרי","ואפי' לטלטלו והא בטילי ליה מיעוטא לגבי רובא והוה ליה ככוליה פסולת ולא חזי:"],[5,"דנפיש בטרחא","שישנו דק והכי קאמר בד\"א בזמן שטורח האוכל מרובה על של פסולת הוא דקא אמרי ב\"ה נוטל פסולת דמעוטי בטרחא עדיף אבל אם טורח הפסולת מרובה על של האוכל דברי הכל כו':"],[6,"ומציפין עליו מים","ונותנים בו מים עד שצפים על האוכל:"],[7,"איפכא","אוכל למעלה ופסולת למטה:"],[7,"עפרא","למטה מן האוכל:"],[7,"גילי","קש למעלה מן האוכל:"],[8,"אין משלחין","דורון איש לרעהו:"],[8,"אלא מנות","דבר המוכן ואינו עשוי להניחו למחר כגון חתיכות בשר חתוכות לפני האורחים וכן דגים:"],[8,"אבל לא את התבואה","שאינה ראויה היום שאין טוחנים ביום טוב שהיה לו לטחון מאתמול ולא תפיג טעמה:"],[8,"ורבי שמעון מתיר בתבואה","שמא יבשלם בקדרה ויכתשם במכתשת קטנה:"],[9,"שלא יעשנו בשורה","לא ישלח הדורון ע\"י אנשים הרבה דאוושא מלתא ונראים כמוליכים למכור בשוק:"],[9,"תלתא גברי","שלוחים עם תלתא מיני:"],[9,"מאי","מי אזלינן בתר כל מין ומין ושרי כי היכא דיכול לשלוח איש אחד עם כל מין זה בלא זה השתא נמי שרי או דלמא השתא מיהא אוושא מלתא:"],[10,"לודיות","מאכל חטין:"],[10,"רסיסין","מאכל העשוי מן העדשים:"],[11,"משלחין כלים","בגדים:"],[11,"והן לצורך המועד","ובגמרא מפרש למאי חזו:"],[11,"אבל לא סנדל","של עץ מצופה עור ומסמרות קבועין בו שגזרו חכמים עליו שלא לנעלו בשבת וביום טוב משום מעשה שהיה שנהרגו הרוגים בשבת על ידו במסכת שבת (דף ס.):"],[11,"ולא מנעל שאינו תפור","דלא חזי למידי:"],[11,"אף לא מנעל לבן","שלא היה דרכו לנעלו:"],[11,"שצריך אומן","להשחירו:"],[11,"שנאותין","מתקשטין:"],[13,"למימך","לכפול:"],[13,"שמא תכרך לו נימא","ויש נימים גדולין וגסים כגון של דלופקרין שקורין קו\"ט ומחממת במקומה ועובר משום לא תלבש שעטנז א\"נ נימא בעלמא כיון דעיקר הבגד מהנהו ומחממו מלמטה הויא לה הא לבישה דאית בה הנאה:"],[14,"דמפסיק מידי","שנותן בגד אחר ביניהם:"],[14,"אסור לישן עליהם","מדרבנן:"],[15,"בוילון","שראוי לפרסו כנגד הפתח:"],[15,"מפני מה אמרו וילון טמא","מקבל טומא' ולא עשאוהו כא' ממחיצו' הבית שאינן מקבלות טומאה:"],[15,"מפני שהשמש מתחמם כנגדו","מתעטף בשוליו לפיכך יש תורת כלי עליו וכיון דמתחממים כנגדו אסור לעשותו כלאים:"]],[[0,"","רבא אמר. לעולם מה טעם קאמר ושום כתישה לא שריא ואפילו בקטנה ומיירי להו לבני א\"י שיש להם עבדים שמזלזלים בדבר כך פירש הקונטרס:"],[3,"","הבורר קטניות ביו\"ט בית שמאי אומרים בורר אוכל ואוכל. ולאו ' היינו ברירה וכו' ותימה דבמסכת שבת (דף קלח.) קאמר מה דרכו של בורר נוטל האוכל ומניח הפסולת והכא משמע שאין ברירה בכך דקרי ליה שנוי וי\"ל דהתם ה\"פ נוטל האוכל עצמו ומניח הפסולת פירוש יזרוק אותו ומכל מקום פסולת מתוך האוכל הוי ברירה אי נמי התם שהפסולת מרובה על האוכל ואז ודאי הוי אוכל מתוך הפסולת דרך ברירה אבל הכא מיירי שהאוכל מרובה על הפסולת דאז הוי פסולת מתוך האוכל דרך ברירה ובגמ' דפריך דפסולת מרובה על האוכל מי איכא מאן דשרי פי' אפי' בטלטול יהא אסור היה יכול להקשות דזהו דרך בורר אלא דעדיפא מניה פריך דאפילו טלטול יהא אסור דבטל מעוטא לגבי רובא והוי ככוליה פסולת:"],[15,"","מפני מה אמרו וילון טמא מפני שהשמש מתחמם כנגדו. וא\"ת והא בפרכת המשכן אמר בפרק גיד הנשה (חילין דף צ: ושם) דמקבל טומאה (וקאמר) ושלש מאות כהנים וכו' ואף על גב דהאי טעמא לא שייך בהו ויש לומר דשאני פרכת הואיל דמיכף כייפי עלויה דארון הוי הוא אהל ומטמא במת ומ\"מ קשה דהיאך מטמאה בולד הטומאה דאמר במסכת שקלים (דף יב:) פרכת שנטמאה בולד הטומאה ומיירי במשקה דזב וזבה דאי לאו הכי לא מטמו כלי וי\"ל כיון שנעשה אהל יש להם תורת כלי ומטמאים אף בולד הטומאה ועוד אומר הר\"ר שמואל מאייבר\"א כשהיו נושאים הפרכת ממקום למקום נותן הכלים לתוכה א\"כ יש תורת כלי עליהם ובה\"ג. גרס וילון אסור ויש לפרש אסור לעשותו מכלאים מפני שהשמש מתחמם כנגדו ול\"נ דלא אשכחנא בשום מקום לא בברייתא ולא במשנה דיהא אסור וילון מכלאים בשלמא טומאה אשכחנא כדתנן סדין שהיה טמא מדרס ועשאו וילון טהור מן המדרס אבל טמא מגע."]]],[["אלא בקשין וכי הא דאמר רב הונא בריה דרב יהושע האי נמטא גמדא דנרש שריא","אמר רב פפא ערדלין אין בהן משום כלאים אמר רבא הני צררי דפשיטי אין בהם משום כלאים דבזרני יש בהם משום כלאים רב אשי אמר אחד זה ואחד זה אין בהן משום כלאים לפי שאין דרך חמום בכך:","אבל לא סנדל המסומר: סנדל המסומר מ\"ט לא משום מעשה שהיה","אמר אביי סנדל המסומר אסור לנעלו ומותר לטלטלו אסור לנעלו משום מעשה שהיה ומותר לטלטלו מדקתני אין משלחין דאי ס\"ד אסור לטלטלו השתא לטלטולי אסור משלחין מבעיא:","ולא מנעל שאינו תפור: פשיטא לא נצרכא דאע\"ג דנקיט בסיכי:","ר' יהודה אומר אף לא מנעל לבן: תניא ר' יהודה מתיר בשחור ואוסר בלבן מפני שצריך ביצת הגיר ר' יוסי אוסר בשחור מפני שצריך לצחצחו","ולא פליגי מר כי אתריה ומר כי אתריה באתריה דמר בשרא לתחת באתריה דמר בשרא לעיל:","זה הכלל כל שנאותין בו ביום טוב: רב ששת שרא להו לרבנן לשדורי תפלין ביומא טבא אמר ליה אביי והא אנן תנן כל שנאותין בו ביום טוב משלחין אותו הכי קאמר כל שנאותין בו בחול משלחין אותו ביום טוב","אמר אביי תפלין הואיל ואתו לידן נימא בהו מילתא היה בא בדרך ותפלין בראשו ושקעה עליו חמה מניח ידו עליהם עד שמגיע לביתו היה יושב בבית המדרש ותפלין בראשו וקדש עליו היום מניח ידו עליהן עד שמגיע לביתו","מתיב רב הונא בריה דרב איקא היה בא בדרך ותפלין בראשו וקדש עליו היום מניח ידו עליהן עד שמגיע לבית הסמוך לחומה היה יושב בבית המדרש וקדש עליו היום מניח ידו עליהן עד שמגיע לבית הסמוך לבית המדרש","לא קשיא הא דמנטרא הא דלא מנטרא","אי דלא מנטרא מאי איריא בראשו אפילו מחתן בארעא נמי דהא תנן המוצא תפלין מכניסן זוג זוג","לא קשיא הא דמנטרא מחמת גנבי ומחמת כלבי הא דמנטרא מחמת כלבי ולא מנטרא מחמת גנבי","מהו דתימא רוב לסטים ישראל נינהו ולא מזלזלי בהו קמ\"ל:","\u0001הדרן עלך ביצה\u0002"],[[0,"בקשין","בגדים קשין שאין מחממים מותר לישב עליהן:"],[0,"נמטא","בגד שקורין פלטר\"א בלע\"ז:"],[0,"גמדא","קשה כמו גמוד מסאני (פסחים דף קיא.) דבר שהוא כווץ נעשה קשה:"],[0,"דנרש","מקום:"],[0,"שריא","לישיבה שאינו מחמם:"],[1,"ערדילין","ראיתי בתשו' הגאונים שרגילין ללבשן תחת מנעליהן (ותולים) עליהם עור של תישים מעובדין תחת קרקעיתן וכנגד העקב של רגל יש עושין אותן של צמר וקורין אותן נמטי:"],[1,"אין בהם משום כלאים","דקשין הן:"],[1,"צררי דפשיטי אין בהן משום כלאים","בגד כלאים שצרורין בו מעות מותר לתתן בחיקו שהמעות מקשין אותו ואינו מחמם:"],[1,"דבזרני","שצרור בהם זרעים:"],[1,"יש בהם משום כלאים","ואסור לתתן בתוך חיקו:"],[3,"","אסור לנעלו ביו\"ט:"],[3,"ומותר לטלטלו","דכלי הוא:"],[3,"מעשה שהיה","במסכת שבת פרק במה אשה יוצאה (שבת דף ס.):"],[4,"בסיכי","יתדות קטנות של עץ וי\"א תופר שתי תפירות באמצעו ושתים בראשו ושתים בעקבו:"],[5,"ביצת הגיר","גיר מין קרקע המשחיר:"],[5,"ביצת","כל דבר הנלוש ונעשה עב קרוי ביצת מטונ\"ש בלע\"ז:"],[5,"לצחצחו","להחליקו כדמפרש לקמיה שבמקומו היו הופכים מקום בשר מבחוץ ומקום שער מבפנים ודרך מקום בשר להיות בו מרטים וקליפות קליפות:"],[6,"באתריה דר' יהודה בשרא לתחת","לפנים הלכך א\"צ לצחצחו:"],[7,"והאנן תנן כו'","ותפילין אין נאותין בהן ביו\"ט כדאמר בערובין (דף צו.) יצאו שבתות וימים טובים שהן עצמן אות:"],[7,"כל שנאותים בו בחול","שהוא מתוקן כל צרכו:"],[7,"משלחין אותו ביום טוב","דאי ביום טוב דקתני מתני' לאו אנאותין דלקמיה קאי אלא אמשלחין דבתריה ולאתויי תפילין אתא דאי נמי מנח להו ביו\"ט ליכא אסורא ומיהו סנדל המסומר לא דלא לימא מדשרו רבנן לשלחו ש\"מ מותר לנעלו:"],[8,"היה בא בדרך","בע\"ש:"],[8,"מניח ידו עליהם","שלא יראום וחכמים התירו לו להכניסם לעיר דרך מלבוש דהיא העברה כלאחר יד ומשום בזיון:"],[8,"בבהמ\"ד","בשדה היה ואינו משתמר:"],[9,"לבית הסמוך לחומה","משנכנס לעיר יתנם בבית הראשון ולא יוליכם עד ביתו:"],[10,"הא דמנטרא","באותו בית הסמוך לבהמ\"ד אם נשמרים הם בו יתנם שם:"],[11,"מאי איריא בראשו","שכבר היה מלובש בהן מבעוד יום דקא נקיט אביי:"],[11,"אפי' מחתן בארעא נמי","אפילו לאחר שקדש היום מצאן מונחים בקרקע התירו לו חכמים להניחן בראשו ולהצניען:"],[11,"המוצא","גרס ולא גרסינן המוציא:"],[11,"המוצא תפילין","בשבת בשדה:"],[11,"מכניסן","לעיר:"],[11,"זוג זוג","נותן בראשו אחד ואחד בזרועו כדרך הנחתן בחול ומכניסן וחוזר והולך ולובש זוג אחר ומכניסן תפילין של ראש ושל זרוע קרי זוג זוג:"],[12,"ולא מנטרא מחמת גנבי","ואשמעינן אביי דהואיל ולא מנטרא מחמת גנבי מאחר שהן בראשו יוליכם עד ביתו אבל אם מצאן שם במקום שהן נשמרין מן הכלבים לא יזיזם ממקומן:"]],[[0,"","אלא בקשין. משמע הכא דבדבר קשה אין בו משום כלאים וכן משמע ביומא (דף סט. ושם) דקאמר שהכהנים היו מקפלים בגדיהם תחת ראשיהם ופריך הא קא מתהנו מכלאים וכו' וכללא דסוגיא איתא התם כדאיתא הכא ואמר רב אשי שאני בגדי כהונה דקשין הן ותימה דאמר בערכין (דף ג:) הכל חייבין בציצית כהנים לוים וישראלים ופריך פשיטא משום דכהנים הן יהיו פטורים ומשני מהו דתימא הואיל וכתיב לא תלבש שעטנז גדילים תעשה לך אימא כל שישנו בלא תלבש שעטנז ישנו בכלל גדילים תעשה לך והני כהני הואיל ואשתרו כלאים לגבייהו אימא לא לחייבו בציצית קמ\"ל דכהנים חייבין והשתא תימה מאי קאמר הואיל ואשתרו כלאים לגבייהו דשאני בגדיהם שהיו קשין לכ\"נ דדוקא להציע תחתיהם דהואיל דברכים ליכא אלא איסור דרבנן להציע בקשין לא גזור ומייתי כי ההיא וכו' נמטא גמדא דנרש שריא גמדא שמתקשה מותר להציע תחתיו כן פרש\"י אבל רכים אסורים כדאמר התם דלבדין אסורין מפני שהן שוע ול\"נ דשריא משמע אפי' ללבוש ויש לומר דאה\"נ דשריא אפילו ללבוש ואם תאמר מאי מייתי מהא גמדא דנרש וכו' והא פירש דקשין מותרין דוקא להציע תחתיו אבל ללבוש אסורין וי\"ל דגבי [בבגדי כהונה] מיירי שהוא שוע טווי ונוז ואז יש בו איסור כלאים מדאורייתא וכיון שהן אסורין מן התורה א\"כ אפילו קשין אסורין בלבישה ובהעלאה אבל גמדא אינו אלא דרבנן כדאמרינן בנדה (דף סא: ושם) דמדאורייתא בעינן שיהא שוע טווי ונוז והא דקאמר הלבדים אסורים מיירי דוקא דרבנן וכיון דרכים ליכא אסורא אלא דרבנן אפי' בלבישה בקשין לא גזור והני פורפוינטי\"ש שקורין באשכנז דמזיל\"ש שאנו לובשים דפעמים שיש בהן צמר יש לומר הואיל ואם עושין קרע קטן מוציאין אותו דרך הקריעה דחד מסרך סריך לחבירו שרי אבל אם היו משימין בהן חתיכות קטנות של בגד צמר ודאי שיהא אסור:"],[7,"","הכי קאמר כל שנאותין בחול וכו'. ואתי לאתויי תפלין דמשלחין אותן דהא אפילו אם מניח אותן ליכא אסורא אבל לא תני לאתויי סנדל המסומר דודאי יהא אסור לשלחו דאי שרית לשלחו אתי לנעלו דאיכא איסורא בדבר זה אבל תפלין (נהי דשבת ויום טוב לאו זמן תפילין הן) מכל מקום ליכא איסורא להניחן:"],[8,"","היה בא בדרך ותפילין בראשו ושקעה עליו חמה וכו' או יושב בבית המדרש וכו'. פרש\"י דתרוייהו מיירי בערב שבת דשבת לאו זמן תפילין וכי בא בדרך ושקעה עליו חמה התירו לו להביאם לעיר הואיל ומביאם כלאחר יד ולפ\"ז קשה דא\"כ אמאי נקט גבי בא בדרך ושקעה ולגבי יושב בבית המדרש וקדש היום כיון דטעמא דתרוייהו שוין אמאי שני בלישניה לכ\"נ ובא בדרך ושקעה מיירי בחול והואיל ושקעה חמה יש לו לסלקן וקמ\"ל דלילה לאו זמן תפילין הוא ואם תאמר אי מיירי בחול אמאי אינו מביא אותם בידו וי\"ל דלמא משתלפי ליה מידיה וההיא דיושב בבית המדרש נקט וקדש היום דבע\"ש מיירי וקמ\"ל דשבת לאו זמן תפילין הוא:"]]],[["מתני׳ \u0001יום\u0002 טוב שחל להיות ערב שבת לא יבשל בתחלה מיום טוב לשבת אבל מבשל הוא ליום טוב ואם הותיר הותיר לשבת ועושה תבשיל מערב יום טוב וסומך עליו לשבת","בית שמאי אומרים שני תבשילין ובית הלל אומרים תבשיל אחד ושוין בדג וביצה שעליו שהן שני תבשילין","אכלו או שאבד לא יבשל עליו בתחלה ואם שייר ממנו כל שהוא סומך עליו לשבת:","\u0001גמ׳\u0002 מנא הני מילי אמר שמואל דאמר קרא (שמות כ, ז) זכור את יום השבת לקדשו זכרהו מאחר שבא להשכיחו","מאי טעמא אמר רבא כדי שיברור מנה יפה לשבת ומנה יפה ליום טוב","רב אשי אמר כדי שיאמרו אין אופין מיום טוב לשבת קל וחומר מיום טוב לחול","תנן עושה תבשיל מערב יום טוב וסומך עליו לשבת בשלמא לרב אשי דאמר כדי שיאמרו אין אופין מיום טוב לשבת היינו דמערב יום טוב אין ביום טוב לא אלא לרבא מאי איריא מערב יום טוב אפילו ביום טוב נמי","אין הכי נמי אלא גזרה שמא יפשע","ותנא מייתי לה מהכא (שמות טז, כג) את אשר תאפו אפו ואת אשר תבשלו בשלו מכאן אמר רבי אלעזר אין אופין אלא על האפוי ואין מבשלין אלא על המבושל מכאן סמכו חכמים לערובי תבשילין מן התורה","תנו רבנן מעשה ברבי אליעזר שהיה יושב ודורש כל היום כולו בהלכות יום טוב יצתה כת ראשונה אמר הללו בעלי פטסין כת שניה אמר הללו בעלי חביות כת שלישית אמר הללו בעלי כדין","כת רביעית אמר הללו בעלי לגינין כת חמישית אמר הללו בעלי כוסות התחילו כת ששית לצאת אמר הללו בעלי מארה","נתן עיניו בתלמידים התחילו פניהם משתנין אמר להם בני לא לכם אני אומר אלא להללו שיצאו שמניחים חיי עולם ועוסקים בחיי שעה","בשעת פטירתן אמר להם (נחמיה ח, י) לכו אכלו משמנים ושתו ממתקים ושלחו מנות לאין נכון לו כי קדוש היום לאדונינו ואל תעצבו כי חדות ה' היא מעוזכם","אמר מר שמניחין חיי עולם ועוסקין בחיי שעה והא שמחת יום טוב מצוה היא רבי אליעזר לטעמיה דאמר שמחת יום טוב רשות","דתניא רבי אליעזר אומר אין לו לאדם ביום טוב אלא או אוכל ושותה או יושב ושונה רבי יהושע אומר חלקהו חציו לה' וחציו לכם","אמר רבי יוחנן ושניהם מקרא אחד דרשו כתוב אחד אומר (דברים טז, ח) עצרת לה' אלהיך וכתוב אחד אומר (במדבר כט, לה) עצרת תהיה לכם הא כיצד רבי אליעזר סבר או כולו לה' או כולו לכם ורבי יהושע סבר חלקהו חציו לה' וחציו לכם","מאי לאין נכון לו אמר רב חסדא למי שלא הניח עירובי תבשילין איכא דאמרי מי שלא היה לו להניח עירובי תבשילין אבל מי שהיה לו להניח עירובי תבשילין ולא הניח פושע הוא","מאי כי חדות ה' היא מעוזכם אמר רבי יוחנן משום רבי אליעזר בר' שמעון אמר להם הקדוש ברוך הוא לישראל בני לוו עלי וקדשו קדושת היום והאמינו בי ואני פורע","ואמר רבי יוחנן משום רבי אליעזר בר' שמעון הרוצה שיתקיימו נכסיו יטע בהן אדר שנאמר (תהלים צג, ד) אדיר במרום ה'","אי נמי אדרא כשמיה כדאמרי אינשי מאי אדרא דקיימא לדרי דרי תניא נמי הכי שדה שיש בה אדר אינה נגזלת ואינה נחמסת ופירותיה משתמרין","תני רב תחליפא אחוה דרבנאי חוזאה"],[[0,"מתני' יום טוב לא יבשל בתחלה","להיות תחלת בשולו ועיקרו לשם שבת אלא לשם יו\"ט יהא תחלת בשולו והמשויר יהא לשבת כדקתני ואזיל אבל מבשל הוא ליו\"ט ובלא הערמה כדקתני לקמן:"],[0,"עושה תבשיל","לשם ערוב:"],[1,"וביצה שעליו","שהיו טחין ביצה על הדג כשצולין אותו:"],[2,"אכלו או שאבד","קודם שבשל כל צרכי שבת:"],[2,"סומך עליו","לבשל בשבילו:"],[3,"גמ' מנא הני מילי","לאו דוקא מקראי יליף דערובי תבשילין דרבנן והכי קא מבעיא ליה אהיכא אסמכוה רבנן:"],[3,"זכור","אין זכירה אלא בדבר המשתכח:"],[3,"זכרהו מאחר שבא להשכיחו","כשבא יו\"ט בערב שבת קרוב שבת להשתכח מחמת יו\"ט שמרבה בסעודת היום ואינו מניח לשבת כדי כבודו והזהירך הכתוב לזכרו וכשמערב ערובי תבשילין נמצא שזוכרו שהרי אינו עושה אלא מחמת שבת:"],[4,"מ\"ט","למה תקנו ערוב קרא ודאי לאו בערוב משתעי ולאו ערוב משתמע מניה ואסמכתא בעלמא הוא וכי אתא קרא לקדוש היום אתא כדתניא בפסחים (דף קו.) זכרהו על היין ערוב מדרבנן ומה ראו לתקן:"],[4,"אמר רבא כדי שיברור כו'","מתוך שמערב זוכר את השבת ואינו מכלה את הכל ליו\"ט ובורר מנה לזה ומנה לזה:"],[5,"רב אשי אמר","לא לכבוד שבת תקנוהו אלא לכבוד יום טוב:"],[5,"כדי שיאמרו אין אופין מיום טוב לשבת","אלא א\"כ התחיל מבעוד יום דאינו אלא כגומר והולך אבל אתחולי לא:"],[5,"ק\"ו דמיום טוב לחול","לגמרי לא:"],[6,"בשלמא לרב אשי","דאמר לכבוד יו\"ט תקנוהו כדי שיאמרו אסור להתחיל בשולי שבת ביו\"ט היינו דמערב יו\"ט הוצרך לעשותו:"],[6,"אלא לרבא","דאמר כדי שיברור:"],[6,"אפי' ביו\"ט","יעשהו לפני סעודת יו\"ט יש כאן זכירת שבת לברור מנותיו:"],[7,"שמא יפשע","ישכח ולא יערב משום דטריד:"],[8,"ותנא מייתי לה מהכא","כן דרך שיטת התלמוד כשמתחילין האמוראין להוציא טעם מן המקרא ויש תנא של ברייתא למד אותו ממקום אחר נקט הכי כלומר האמוראין למדוהו מכאן והתנא למד מכאן:"],[8,"את אשר תאפו אפו","הוה ליה למכתב היום אפו ובשלו אלא רמז הוא שיש לך יום ששי שאין אופין לצורך מחר:"],[8,"אלא על האפוי","בחמישי בשבת:"],[8,"אופין","פת:"],[8,"מבשלין","תבשיל:"],[9,"שהיה יושב ודורש","ביום טוב:"],[9,"יצתה כת ראשונה","לסעוד סעודת יום טוב והניחוהו דורש:"],[9,"בעלי פטסין","חביות גדולות הכינו להם באנומלין ומסך משתאות לפיכך מהרו לצאת כלומר בעלי נפש הן ואינן יגיעין לשמוע תורה:"],[10,"הללו בעלי מארה","שהיה בית המדרש מתרוקן מאד וגנאי הדבר וקשה בעיניו:"],[10,"","עד מתי הם יושבים ל\"ג:"],[11,"התחילו פניהם משתנין","כסבורין שכועס על כת ששית מפני שאחרו לצאת וכ\"ש עלינו:"],[11,"חיי שעה","סעודה:"],[12,"אכלו משמנים","מקרא הוא בספר עזרא עד כי חדות ה' היא מעוזכם:"],[16,"שלא היה לו להניח","כגון שאבדה לו אבדה מערב יו\"ט ומחזר כל היום אחריה:"],[17,"חדות ה'","שמחה שאתם עושים בשביל הקב\"ה הרי היא מעוזכם היא תעזור אתכם לשלם הקפותיכם ומלוותיכם שתלוו בשבילה:"],[18,"שיתקיימו לו נכסיו","שלא יהא אדם חומסן וגוזל שדות ממנו:"],[18,"יטע בהן אדר","אילן חשוב הוא יש לו שם למרחוק ואומרים פלוני יש לו אדר בשדהו ומתוך כך היא נקראת על שמו ואם הולך למדינת הים ובא אחר והחזיק בה יש לו עדים הרבה שהיתה שלו ואילו מכרה היה הקול יוצא להיות נקראת על שמו של שני:"],[18,"שנאמר אדיר במרום","כלומר שאדר לשון קיום וחוזק ולכך נקרא אדר:"],[19,"כשמיה","כשמו שמפרשין בני אדם את שמו:"],[19,"נחמסת","חמסן יהיב דמי אלא שלוקח בכח ויש קול לדבר והיום או מחר מזמינו לבית דין:"],[19,"ופירותיה משתמרין","לא ידענא מאי היא י\"מ שנוטעין אותו על הגבולים ויש לו ענפים הרבה והוא לשדה לגדר ולי נראה שהוא מין עשב חשוב וזרעו מתערב עם הפירות ובשדה לבן קאמר ומשתמרת התבואה מן הכנימה והתולעים שריח אותו זרע מבריחן והורגן כדאמר בחומטין שמשמר התבואה במסכת שבת (דף לא.):"]],[[14,"","או אוכל ושותה או יושב ושונה. ואע\"ג דלעיל קאמר לתלמידיו אכלו משמנים ושתו ממתקים משום דסיים הדרשה הוא דהא בשאר ימים נמי היו אוכלים אחר הדרשה ומ\"מ אמר להו אכלו משמנים ושתו ממתקים משום שמחת יום טוב:"],[17,"","לוו עלי ואני פורע. והא דאמר (פסחים דף ק.) עשה שבתך חול ואל תצטרך לבריות ה\"מ כשאין. לו [א] לפרוע:"]]],[["כל מזונותיו של אדם קצובים לו מראש השנה ועד יום הכפורים חוץ מהוצאת שבתות והוצאת י\"ט והוצאת בניו לתלמוד תורה שאם פחת פוחתין לו ואם הוסיף מוסיפין לו","א\"ר אבהו מאי קראה (תהלים פא, ד) תקעו בחדש שופר (בכסא) ליום חגנו איזהו חג שהחדש מתכסה בו הוי אומר זה ראש השנה וכתיב (תהלים פא, ה) כי חק לישראל הוא משפט לאלהי יעקב","מאי משמע דהאי חק לישנא דמזוני הוא דכתיב (בראשית מז, כב) ואכלו את חקם אשר נתן להם פרעה מר זוטרא אמר מהכא (משלי ל, ח) הטריפני לחם חקי","תניא אמרו עליו על שמאי הזקן כל ימיו היה אוכל לכבוד שבת מצא בהמה נאה אומר זו לשבת מצא אחרת נאה הימנה מניח את השניה ואוכל את הראשונה","אבל הלל הזקן מדה אחרת היתה לו שכל מעשיו לשם שמים שנאמר (תהלים סח, כ) ברוך ה' יום יום תניא נמי הכי בית שמאי אומרים מחד שביך לשבתיך ובית הלל אומרים ברוך ה' יום יום","א\"ר חמא ברבי חנינא הנותן מתנה לחברו אין צריך להודיעו שנאמר (שמות לד, כט) ומשה לא ידע כי קרן עור פניו","מיתיבי (שמות לא, יג) לדעת כי אני ה' מקדשכם אמר לו הקב\"ה למשה משה מתנה טובה יש לי בבית גנזי ושבת שמה ואני מבקש ליתנה לישראל לך והודיע אותם מכאן אמר רבן שמעון בן גמליאל הנותן פת לתינוק צריך להודיע לאמו","לא קשיא הא במתנה דעבידא לאגלויי הא במתנה דלא עבידא לאגלויי שבת נמי מתנה דעבידא לאגלויי מתן שכרה לא עבידא לאגלויי:","אמר מר מכאן אמר רשב\"ג הנותן פת לתינוק צריך להודיע לאמו מאי עביד ליה שייף ליה משחא ומלי ליה כוחלא והאידנא דחיישינן לכשפים מאי אמר רב פפא שייף ליה מאותו המין","א\"ר יוחנן משום ר' שמעון בן יוחי כל מצות שנתן להם הקב\"ה לישראל נתן להם בפרהסיא חוץ משבת שנתן להם בצנעא שנאמר (שמות לא, יז) ביני ובין בני ישראל אות היא לעולם","אי הכי לא לענשו נכרים עלה שבת אודועי אודעינהו מתן שכרה לא אודעינהו ואי בעית אימא מתן שכרה נמי אודעינהו נשמה יתירה לא אודעינהו","דאמר ר' שמעון בן לקיש נשמה יתירה נותן הקב\"ה באדם ערב שבת ולמוצאי שבת נוטלין אותה הימנו שנאמר (שמות לא, יז) שבת וינפש כיון ששבת ווי אבדה נפש:","עושה אדם תבשיל מערב יום טוב: אמר אביי לא שנו אלא תבשיל אבל פת לא","מאי שנא פת דלא אילימא מידי דמלפת בעינן ופת לא מלפתא והא דייסא נמי דלא מלפתא דאמר ר' זירא הני בבלאי טפשאי דאכלי נהמא בנהמא ואמר רב נחומי בר זכריה משמיה דאביי מערבין בדייסא אלא מידי דלא שכיח בעינן ופת שכיחא ודייסא לא שכיחא","איכא דאמרי אמר אביי לא שנו אלא תבשיל אבל פת לא מאי טעמא אילימא דמידי דלא שכיח בעינן ופת שכיחא והא דייסא לא שכיחא ואמר רב נחומי בר זכריה משמיה דאביי אין מערבין בדייסא אלא מידי דמלפת בעינן ופת לא מלפתא ודייסא נמי לא מלפתא דאמר ר' זירא הני בבלאי טפשאי דאכלי נהמא בנהמא","תני ר' חייא עדשים שבשולי קדרה סומך עליהן משום ערובי תבשילין וה\"מ דאית בהו כזית אמר רב יצחק בריה דרב יהודה שמנונית שעל גבי הסכין גוררו וסומך עליו משום ערובי תבשילין והני מילי דאית בהו כזית","אמר רב אסי אמר רב דגים קטנים מלוחים אין בהם משום בשולי נכרים אמר רב יוסף ואם צלאן נכרי סומך עליהם משום ערובי תבשילין ואי עבדינהו נכרי כסא דהרסנא אסור","פשיטא מהו דתימא"],[[0,"כל מזונותיו של אדם","כל מה שעתיד להשתכר בשנה שיהא נזון משם קצוב לו כך וכך ישתכר בשנה זו ויש לו ליזהר מלעשות יציאה מרובה שלא יוסיפו לו שכר למזונות אלא מה שפסקו לו:"],[0,"חוץ מהוצאת שבתות","אותה לא פסקו לו מה ישתכר לצרכה ומהיכן תבואהו אלא לפי מה שרגיל ממציאים לו לשעה או לאחר שעה:"],[0,"פוחתין לו","כלומר ממציאין לו שכר מועט:"],[1,"מאי קראה","שקוצבין מזונות בראש השנה:"],[1,"בכסה ליום חגנו","אבחדש קאי תקעו בחדוש הלבנה שופר כשהוא מתכסה ביום חגנו:"],[1,"שהחדש מתכסה בו","שהלבנה מתכסה בו שאינה נראית לכל אדם אלא שחרית ליושבי מזרח וערבית ליושבי מערב כדאמר בר\"ה (דף כ:) עשרים וארבע שעות מתכסה סיהרא:"],[1,"הוי אומר זה ר\"ה","דאלו שאר יו\"ט כבר נתמלאה הלבנה במקצת ונראית בכל מקום:"],[3,"ואוכל את הראשונה","נמצא אוכלה לזו כדי שתהא היפה נאכלת בשבת דהויא לה אכילתה של הראשונה לכבוד שבת:"],[4,"לשם שמים","בוטח שתזדמן לו נאה לשבת:"],[4,"מחד שביך לשבתיך","מאחד בשבת שלך תן לבך לשבת הבאה:"],[4,"יום יום","יעמס לנו את צרכינו ועזרתנו:"],[5,"אינו צריך להודיעו","לומר שלא יהא זה יושב ותוהה מהיכן בא אליו דבר זה:"],[5,"ומשה לא ידע","אלמא נתן לו הקב\"ה הוא קרון עור פנים ולא הודיעו:"],[6,"לדעת כי אני ה' וגו'","רישיה דקרא אך את שבתותי תשמרו ומאי לדעת רוצה אני שתודיעם מה מתנה חשובה אני מבקש ליתן להם:"],[6,"צריך להודיע את אמו","לעשות לו אות וסימן שאם יאכלנו קודם שיבא לאמו תראה את האות ותשאלנו מי עשה לך כך והוא יאמר פלוני וגם נתן לי פת ומתוך כך ידעו אביו ואמו שהוא אוהבם ותרבה אהבה ורעות בישראל:"],[7,"דעבידא לגלויי","כגון קרון פנים דמשה שהודיעוהו הרואין לא צריך הנותן להודיעו:"],[8,"ומלי ליה כוחלא","נותן כחול סביבות עיניו:"],[10,"לא (נענשו) נכרי עלה","ואנן אשכחן שחזר הקב\"ה להענישן על התורה ועל המצות דכתיב וזרח משעיר למו הופיע מהר פארן (דברים לג) וכתיב אלוה מתימן יבא (חבקוק ג):"],[10,"נשמה יתירה","רוחב לב למנוחה ולשמחה ולהיות פתוח לרוחה ויאכל וישתה ואין נפשו קצה עליו:"],[11,"וינפש","דרשינן ליה אוי על הנפש שהלכה לה:"],[12,"לא שנו","דהוי ערוב:"],[13,"דמלפת","לפתן בעינן דמוכחא מלתא שעשוי לשבת:"],[13,"ופת לא מלפתא","הלכך לא מוכחא מלתא היא שהרי בכל יום יש לחם:"],[15,"שבשולי קדרה","שנשארו בלא מתכוין:"],[15,"סומך עליהם","מערב יום טוב לשם ערוב ולא אמרינן לא חשיבי ובטלי:"],[15,"גוררו","מערב יום טוב:"],[16,"אין בהם משום בשולי נכרים","שגזרו חכמים בבשולי נכרים משום חתנות ועל שנאכל כמו שהוא חי לא גזרו על בשולו דכיון שנאכל כמו שהוא חי אינו בשול דלא אהני מידי ואלו נאכלין על ידי מלחן חיים:"],[16,"סומך ישראל עליהן","דהא שרו באכילה:"],[16,"כסא דהרסנא","מטוגן בשומן קרבי דגים ובקמח:"],[16,"אסירי","דקמח אין נאכל כמו שהוא חי לפיכך יש בו משום בשולי נכרים:"]],[[0,"","כל מזונותיו של אדם קצובים כו' והוצאת בניו לתלמוד תורה. פר\"י הכל נפקי מקראי דלעיל מזונותיו דשבת כדאמר לוו עלי ואני פורע תורה דכתיב חדות וחדות היא תורה דכתיב פקודי ה' ישרים משמחי לב (תהלים יט):"],[1,"","איזהו חג שהחדש מתכסה בו וכו'. פרש\"י שהלבנה אינה נראית וקשה לפי' זה דהוה ליה למימר שהלבנה מתכסה לכך . פר\"ת [שר\"ח] מזדמן בו כלומר שרגיל לבא בו וכסא לשון זמן כמו ליום הכסא יבא ביתו (משלי ז׳:כ׳) ורבינו משולם פירש מתכסה שלא היה שעיר של ר\"ח קרב בו והקשה רבינו תם דבתוספתא. קאמר דקחשיב (. ל\"ו) שעירים בשנה וקא חשיב י\"ב שעירים דראשי חדשים ולא מצינו י\"ב אם לא היה שעיר דר\"ח דר\"ה והשיב לו רבינו משולם דלא עלה על לבו לומר כן אלא היתה דעתו דלא מפרש קרא בהדיא של ראש חדש דראש השנה דכתיב בפינחס מלבד עולת החדש וחטאת לא הזכיר וי\"מ מתכסה שאין מזכירין אותו במוסף דראש השנה ור\"ת היה אומר אדרבה הואיל והיה קרב מזכירין אותו במוסף דראש השנה ותקן ר\"ת לומר במוסף מלבד עולת החדש וגו' וכן תקן לומר שני שעירים כהלכתן וגו' שעיר אחד של ראש חדש ושעיר אחד של ר\"ה:"]]],[["הרסנא עיקר קמ\"ל קמחא עיקר","אמר ר' אבא ערובי תבשילין צריכין כזית איבעיא להו כזית אחד לכלן או דלמא כזית לכל אחד ואחד ת\"ש דאמר רבי אבא אמר רב ערובי תבשילין צריכין כזית בין לאחד בין למאה:","תנן אכלו או שאבד לא יבשל עליו בתחלה שייר ממנו כל שהוא סומך עליו לשבת מאי כל שהוא לאו אע\"ג דליכא כזית לא דאית ביה כזית:","ת\"ש תבשיל זה צלי ואפילו כבוש שלוק ומבושל וקולייס האספנין שנתן עליו חמין מערב יו\"ט תחלתו וסופו אין לו שיעור מאי לאו אין לו שיעור כלל לא אין לו שיעור למעלה אבל יש לו שיעור למטה","אמר רב הונא אמר רב ערובי תבשילין צריכין דעת פשיטא דעת מניח בעינן דעת מי שהניחו לו בעינן או לא בעינן","תא שמע דאבוה דשמואל מערב אכולה נהרדעא רבי אמי ורבי אסי מערבו אכולהו טבריא: מכריז רבי יעקב בר אידי מי שלא הניח ערובי תבשילין יבא ויסמוך על שלי ועד כמה אמר רב נחומי בר זכריה משמיה דאביי עד תחום שבת:","ההוא סמיא דהוה מסדר מתניתא קמיה דמר שמואל חזייה דהוה עציב אמר ליה אמאי עציבת אמר ליה דלא אותיבי ערובי תבשילין אמר ליה סמוך אדידי לשנה חזייה דהוה עציב אמר ליה אמאי עציבת אמר ליה דלא אותיבי ערובי תבשילין אמר ליה פושע את לכולי עלמא שרי לדידך אסור","ת\"ר יום טוב שחל להיות בערב שבת אין מערבין לא ערובי תחומין ולא ערובי חצרות","רבי אומר מערבין ערובי חצרות אבל לא ערובי תחומין מפני שאתה אוסרו בדבר האסור לו ואי אתה אוסרו בדבר המותר לו","אתמר רב אמר הלכה כתנא קמא ושמואל אמר הלכה כרבי:","איבעיא להו הלכה כרבי לקולא או לחומרא פשיטא דלקולא קאמר משום דשלח רבי אלעזר לגולה לא כשאתם שונין בבבל רבי מתיר וחכמים אוסרין אלא רבי אוסר וחכמים מתירין מאי","תא שמע דרב תחליפא בר אבדימי עבד עובדא כותיה דשמואל ואמר רב תחלת הוראה דהאי צורבא מרבנן לקלקולא אי אמרת בשלמא לקולא קאמר היינו קלקולא אלא אי אמרת לחומרא מאי קלקולא איכא","כיון דמקלקלי בה רבים"],[[0,"הרסנא עיקר","שומן הדגים:"],[1,"בין לאחד בין למאה","די להם בכזית:"],[2,"לא דאית ביה כזית","ולגבי ככר שלם קרי ליה כל שהוא:"],[3,"תבשיל זה","של ערוב:"],[3,"כבוש","בחומץ ובחרדל ומיני ירקות:"],[3,"שלוק","מבושל הרבה מאד:"],[3,"מבושל","כהלכתו:"],[3,"קולייס האספנין","דג מליח הוא ורך ונאכל כמו שהוא חי אלא שנותנין עליו חמין וזה בשולו כדתנן במסכת שבת (דף לט.) שהדחתו זו היא גמר מלאכתו:"],[3,"שנתנו עליו חמין","גרסינן שעשו לו מערב יו\"ט בשול הראוי לו:"],[3,"תחלתו","כשעשה התבשיל אין לו שיעור כמה יהא בו:"],[3,"סופו","אכלו או שאבד ושייר ממנו קצת:"],[3,"מאי לאו אין לו שיעור כלל","לא לרב ולא למעט:"],[3,"לא אין לו שיעור למעלה","לומר שלא יוסיף בו על כך וכך:"],[3,"למטה","לא יפחות מכזית:"],[4,"צריכים דעת","שידעו שלשם כך נעשו ורב הונא לא פירש דעת מי ומפרשינן לה אנן ואמרינן הא ודאי פשיטא לן דכי אמר רב הונא צריכים דעת דעתו דמניח מיהא בעי דאיהו עדיף שעושהו לשם כך מיהו מבעיא לן דעת מי שהניחו לצרכו כגון דעשהו זה לצורך חברו כלום צריך שימלך בו תחלה לעשותו על פיו:"],[5,"עד תחום שבת","ולעומדים חוץ לתחום לא היה דעתו של מניח עליהם ולא עלו על לבו לזוכרן:"],[6,"מסדר מתניתא","שהיה יודע משניות בגרסא ומחזר עליהן לפני מר שמואל שהיו סדורות בפיו כעיקרן:"],[6,"סמוך אדידי","דמערבנא אכולה נהרדעא שהיא עירו:"],[6,"לשנה","לשנה אחרת וראש השנה היה שאין יכול להניח ולהתנות:"],[6,"לדידך אסור","שאין דעתי על המזידין והפושעים שאינם חרדים לדברי חכמים:"],[7,"לא ערובי חצרות","לטלטל מחר דנראה כמתקן דבר:"],[8,"שאתה אוסרו בדבר האסור לו","כח יש בידך לאסור עליו מלעשות צורך מחר דבר שהוא אסור בו ביום והיינו תחומין שאף ביו\"ט אסור לצאת מן התחום:"],[8,"ואי אתה אוסרו","אין כח בידך לאסור לו מלתקן למחר דבר שהוא מותר בו ביום ואסור טלטול חצרות ליתיה ביום טוב:"],[10,"משום דשלח רבי אלעזר כו'","לפיכך הוצרכו לשאול לקולא קאמר שמואל או לחומרא משום דשלח ר' אלעזר לחומרא ואנו שונין דרבי לקולא לפיכך שואלים אנו שמואל שקבע הלכה כרבי היכי מתני לפלוגתייהו:"],[11,"ואמר רב תחלת הוראה וכו'","דרב פליג עליה ואמר הלכה כת\"ק:"],[12,"כיון דמקלקלי בה רבים","ששוכחין ומטלטלין בלא ערוב:"]],[[0,"","[לעיל] דגים קטנים מלוחים אין בהם משום בשולי נכרים. דהא נאכלים כמו שהן חיין הואיל ומלוחים אבל אם לא היו מלוחים יש בהם משום בשולי נכרים ותימה דאמר במס' ע\"ז פרק אין מעמידין (עבודה זרה דף לח.) כל שאינו עולה על שלחן מלכים ללפת בו את הפת אין בו איסור משום בשולי נכרים וקאמר עלה כגון דגים קטנים וי\"ל דהתם בקטנים טפי מיירי והכא מיירי בדגים שאין קטנים כל כך שפעמים שהן עולין על שלחן מלכים ללפת בו את הפת:"],[0,"","קמ\"ל קמחא עיקר. מכאן אנו סומכין ליקח מן הנכרים פת הנלוש מן הביצים שקורין קנטויי\"ש ואובליזא\"ש דמאי נחוש אי משום פת עצמו התירו חכמים אי משום ביצים ששלקו בה הא אמרינן קמחא עיקר ואין לחלק ולומר דשאני הכא לחומרא כלומר דקמחא שהוא מן שלקות שבלילתו רכה אסור אבל בעלמא שהוא עב והוי מעשה תנור אף שהיתר עיקר לא אזלינן לקולא אי אפשר לומר כן דהא קאמר הכא מהו דתימא הרסנא עיקר כלומר היה לנו להתיר אלמא היכא דהיתר עיקר אזלינן בתריה אפי' לקולא אי לאו דאסיק דקמחא עיקר ואין לחוש שמא הביצים מעופות טמאים דהא אינן מצויין בינינו ושמא יש דם בביצים רובם אין בהם דם ומה שבודקים הביצים בשעה שמשימין אותם ברוטב אם יש בהן דם זהו חומרא בעלמא דהא אם לא נבדקו מותרין וגם אין לחוש משום ביצי נבלות או מטרפות משום דאזלינן בתר הרוב וא\"ת והא יש לחוש שמא נלושו בביצים טרופות דאמר בחולין (דף סד. ושם) דאין לוקחין ביצים טרופות מן הנכרי וי\"ל ה\"מ בעינייהו משום דאית בהו ריעותא דמוכחא מלתא ממה שהן טרופות דמנבלות וטרפות אתו וזבנהו ישראל לנכרי אבל הכא שנלושו דליכא שום ריעותא לא חיישינן לשום דבר ויש לומר שנלושו מביצים שלמות ומיהו פשטי\"ץ של דגים שאפאו נכרי אין להתיר דיש בהם משום בשולי נכרים הואיל ונבלע שומן הדגים בתוך העיסה והדגים אסורין משום בישולי נכרים א\"כ אף העיסה שמבחוץ אסורה ונעשה כולו בשולי נכרים אע\"פ שהעיסה אין בה משום ב\"נ דהא התירו את הפת וגם מה שנבלע בה אינו בעין מ\"מ קודם שנבלע בעיסה היה בעין והיה נאסר ונמצא שהעיסה נלושה מן האיסור דרבנן ויש שמסירין השומן ואוכלים אותן בכה\"ג ואותן ניליי\"ש מדלא מברכין עלייהו ברכת המוציא יש בהן משום ב\"נ ומיהו אומר הר\"ר יחיאל דאין בהם משום ב\"נ כיון דדרך אפיית פת עביד להו ועוד דאי קבע סעודתיה עלייהו מברך ברכת המוציא אלמא פת נינהו:"],[1,"","אמר רבי אבא ערובי תבשילין צריך שיהא בהן כזית. וג' דינים יש בהלכות ערוב ערובי תחומין צריך שתי סעודות לכל אחד ואחד והכי מסיק בהדיא בעירובין (דף פ:) ערובי חצרות צריכין כגרוגרת לכל אחד ואחד והכי מסיק בהדיא בעירובין (דף פב:) עד שיהא ב' סעודות ואם יש שם מזון ב' סעודות אינו צריך יותר ואפילו מאה יכולין לסמוך עליו ערובי תבשילין בין לאחד בין למאה אינו צריך אלא כזית לכל מין ומין:"],[8,"","רבי אומר מערבין ערובי חצרות אבל לא ערובי תחומין. תימה הא רבי ס\"ל בפרק בכל מערבין (עירובין דף לח: ושם) דשבת ויו\"ט קדושה אחת היא וא\"כ היכי מערבינן ערובי חצרות מי\"ט לשבת ויש לומר דאדרבה היינו טעמא הכא דרבי דהא דאית ליה קדושה אחת הן היינו בדבר האסור לעשות ביו\"ט כגון תחומין אסור לעשותם ביו\"ט בשביל שבת דהא קדושה אחת הן אבל בשביל שקדושה אחת היא לא אסרינן דבר המותר לעשות ביו\"ט עצמו כגון לטלטל בחצרו לעשות ערוב בשביל שבת:"]]],[["היינו קלקולא אמר רבא אמר רב חסדא אמר רב הונא הלכה כרבי ולאסור","תנו רבנן יום טוב שחל להיות בשבת בית שמאי אומרים מתפלל שמנה [ואומר] של שבת בפני עצמה ושל יו\"ט בפני עצמה וב\"ה אומרים מתפלל שבע מתחיל בשל שבת ומסיים בשל שבת ואומר קדושת היום באמצע רבי אומר אף חותם בה מקדש השבת ישראל והזמנים","תני תנא קמיה דרבינא מקדש ישראל והשבת והזמנים אמר ליה אטו שבת ישראל מקדשי ליה והא שבת מקדשא וקיימא אלא אימא מקדש השבת ישראל והזמנים אמר רב יוסף הלכה כרבי וכדתריץ רבינא:","ת\"ר שבת שחל להיות בר\"ח או בחולו של מועד ערבית ושחרית ומנחה מתפלל שבע ואומר מעין המאורע בעבודה ואם לא אמר מחזירין אותו רבי אליעזר אומר בהודאה ובמוספין מתחיל בשל שבת ומסיים בשל שבת ואומר קדושת היום באמצע","רשב\"ג ורבי ישמעאל בנו של רבי יוחנן בן ברוקא אומרים כל מקום שהוזקק לשבע מתחיל בשל שבת ומסיים בשל שבת ואומר קדושת היום באמצע אמר רב הונא אין הלכה כאותו הזוג","אמר רב חייא בר אשי אמר רב מניח אדם עירובי תחומין מיום טוב לחברו ומתנה","אמר רבא מניח אדם עירובי תבשילין מיום טוב לחבירו ומתנה","מאן דאמר עירובי תחומין כל שכן עירובי תבשילין ומאן דאמר עירובי תבשילין אבל עירובי תחומין לא מאי טעמא דלמקני שביתה בשבתא לא","תנו רבנן אין אופין מיום טוב לחברו באמת אמרו ממלאה אשה כל הקדרה בשר אע\"פ שאינה צריכה אלא לחתיכה אחת ממלא נחתום חבית של מים אע\"פ שאינו צריך אלא לקיתון אחד אבל לאפות אינו אופה אלא מה שצריך לו","ר' שמעון בן אלעזר אומר ממלאה אשה כל התנור פת מפני שהפת נאפת יפה בזמן שהתנור מלא אמר רבא הלכה כרבי שמעון בן אלעזר","איבעיא להו מי שלא הניח עירובי תבשילין הוא נאסר וקמחו נאסר או דלמא הוא נאסר ואין קמחו נאסר","למאי נפקא מינה לאקנויי קמחו לאחרים אי אמרת הוא נאסר וקמחו נאסר צריך לאקנויי קמחו לאחרים ואי אמרת הוא נאסר ואין קמחו נאסר לא צריך לאקנויי קמחו לאחרים מאי","תא שמע מי שלא הניח עירובי תבשילין הרי זה לא יאפה ולא יבשל ולא יטמין לא לו ולא לאחרים ולא אחרים אופין ומבשלין לו כיצד הוא עושה מקנה קמחו לאחרים ואופין לו ומבשלין לו ש\"מ הוא נאסר וקמחו נאסר ש\"מ","איבעיא להו עבר ואפה מאי ת\"ש מי שלא הניח עירובי תבשילין כיצד הוא עושה מקנה קמחו לאחרים ואחרים אופין לו ומבשלין לו"],[[0,"היינו קלקולא","אם היה מותר לערב אתמול והוא אסר:"],[1,"מתחיל בשל שבת","ברכה אחת לשניהם ומתחיל להזכיר שבת תחילה ותתן לנו את יום המנוחה הזה ואת יום חג פלוני הזה:"],[1,"ומסיים","הברכה בשל שבת מקדש השבת ותו לא:"],[1,"ואומר קדושת היום באמצע","ותתן לנו ה' אלהינו את יום המנוחה הזה ואת יום חג פלוני הזה:"],[2,"תני תנא קמיה דרבינא","במילתיה דרבי מקדש ישראל והשבת והזמנים:"],[2,"אטו שבת ישראל מקדשי ליה","שקדמת קדושת ישראל לשל שבת בשלמא זמנים צריך להקדים קדושת ישראל לקדושתן שעל ידי קדושת ישראל נתקדשו הם ואילו לא נתקדשו ישראל לא היו קובעים חדשים וקוראין מועדים בבית דין:"],[2,"אלא שבת מקדשא וקיימא","מששת ימי בראשית ואינה תלויה בקביעות דראש חדש:"],[3,"מתפלל שבע","כשאר שבתות כי היכי דבחול אין לו למועד ברכה קבועה בשלש תפלות הללו אף בשבת אין צריך לקבוע לו ברכה לבית שמאי ולא לכללו לבית הלל:"],[3,"מעין המאורע","ראש חדש או מועד:"],[3,"בעבודה","כגון יעלה ויבא בברכת עבודה:"],[3,"בהודאה","כמו שאומר על הנסים בחנוכה ופורים:"],[4,"כל מקום שזקוק לשבע","ואפי' ערבית ושחרית ומנחה:"],[4,"","אין הלכה כאותו הזוג גרסינן אלא כתנא קמא דאמר ערבית שחרית ומנחה מתפלל שבע ואומר מעין המאורע בעבודה מיהו לאו הלכתא כוותיה בהא דקאמר ובמוספין מתחיל כו' אלא בהא הלכתא כרבי דאמר אף חותם בה מקדש השבת ישראל והזמנים או ראשי חדשים בראש חדש:"],[6,"מיום טוב לחבירו","אם נזכר ביו\"ט ראשון וחלו שני ימים טובים חמישי וערב שבת ומתנה אם היום חול ומחר קדש עירובי עירוב ואם חלוף איני צריך לערב לתבשילין ובתחומין יאמר אם היום קדש אין בדברי כלום ולמחר יאמר כמו כן בשל תחומין ובאותה הפת עצמה דממה נפשך הוי עירוב אבל בשל תבשילין אין צריך לשנות ולחזור את תנאו למחר:"],[7,"דלמקני שביתה בשבתא","לאו דוקא שבתא נקט אלא יו\"ט קרי שבתא לא התירו לו לקנות שביתה ביום טוב ואפי' מספק ואם התירו בעירובי תבשילין התם משום כבוד שבת התירו:"],[8,"אין אופין","פת:"],[8,"ממלאה אשה כו'","דבחד טרחא סגי וכן בנחתום לגבי מלוי:"],[8,"אבל לאפות","כל ככר וככר צריכה אפיה ורדיה לעצמה:"],[9,"בזמן שהתנור מלא","שתנורים קטנים היו ומדביקין פת בדפנות ומתוך שהוא מלא מתמעט חללו ואין מקום לחמימותו להתפשט והפת נאפת יפה:"],[10,"הוא נאסר","לאפות:"],[10,"וקמחו נאסר","שלא יהו אחרים אופין קמחו בעודו שלו:"],[11,"לאקנויי קמחו","אם צריך לתת במתנה את קמחו שיהו אחרים מותרים לאפותו ולתת לו:"],[11,"","בשלמא לא גרס:"],[12,"ולא יטמין","כדרך שמטמינין תבשיל שבת:"],[13,"עבר ואפה מאי","מהו שיאכל בשבת:"]],[[4,"","אין הלכה כאותו הזוג. וא\"ת אמאי לא קאמר הלכה כתנא קמא וי\"ל דאי הוה אמר הלכה כתנא קמא הוה משמע אכל דבריו אף ממה שאמר מסיים בשל שבת והא ליתא דהא קי\"ל דהלכתא כרבי דאמר חותם ברוך מקדש השבת ישראל והזמנים:"],[7,"","מאי טעמא למקני שביתה בשבתא לא. וא\"ת למה לי האי טעמא האיכא טעמא דהכנה כדאמרי' בפ' בכל מערבין (עירובין דף לח: ושם) מיו\"ט לשבת מאי טעמא לא משום הכנה וי\"ל דאי לאו ההיא טעמא דמקני שביתה בשבתא משום טעמא דקאמר משום הכנה לא אסרינן הואיל ויש שם ספק דשמא חול הוא לגמרי מכל מקום קשה דהתם בעירובין למה לי טעמא דהכנה תיפוק ליה משום דמקני שביתה בשבתא לא ויש לומר דהתם מיירי בעירובי חצרות ולא שייך למקני שביתה ומכל מקום קשה מההוא דגטין. פרק הזורק (דף ע':) גבי שכיב מרע דקאמר איהי תזיל ותחוד ותפתח והתם מיירי בשבת דשרי לעשות קנין והכא אסר למקני שביתה אפי' ביו\"ט וי\"ל דשכיב מרע שאני דהתירו עליו שלא תטרף דעתו ותדע דיש חלוק בין שכיב מרע לאיש אחר דהא התירו לו לגרש בשבת ואין אנו מקדשין ואין מגרשין ואע\"ג דלא קאמר לקמן אין מגרשין . מכל מקום למה יש לחלק בין קדושין לגרושין ועוד דבתוספתא אמרינן בהדיא אין מקדשין ואין מגרשין ולי נראה מדקאמר התם אי אתה מודה משמע דלא פליג שום אדם עליה והא פליג רבי עליה לעיל דאמר מערבין עירובי חצרות לכך נראה לפרש דטעמא דהכא יש לומר משום הכנה וה\"ק אסור למקני שביתה בשבתא משום דהיינו הכנה ואין מכינין מיום טוב לשבת וא\"ת לרבי יוחנן דאמר לעיל (ביצה דף ד.) נולדה בזה מותרת בזה וקאמר טעמא לעיל משום דלית ליה הכנה וכי פליג רבי יוחנן אכל הני תנאי ואמוראי דהכא ויש לומר דהתם מיירי בהכנה שנעשה בידים כגון עירובי תחומין ואפי' רבי יוחנן מודה אבל מה שמתיר ר' יוחנן היינו גבי ביצה דהוי הכנה בידי שמים שנעשית מאליה:"],[11,"","אי אמרת הוא נאסר וקמחו נאסר צריך לאקנויי קמחו לאחרים ואי אמרת אין קמחו נאסר אין צריך לאקנויי קמחו. ותימה הואיל וקמחו נאסר מה מועיל הקנייה לאחרים מי יכול לסלק האיסור שבו כדי שיאכל הוא עצמו אחר (כך) שנאסר ועוד קשה כיון שהוא נאסר מאיזה טעם יהא מותר שאחרים אופין (לשבת) בשבילו וכי אחרים יכולים לעשות בשבילו מה שהוא עצמו אינו יכול לעשות בשביל עצמו לכן נראה לי כגי'. דה\"ג אי אמרת הוא נאסר ואין קמחו נאסר מצי לאקנויי קמחו לאחרים ואז מועיל הקנין ואי אמרת הוא נאסר וקמחו נאסר לא מצי לאקנויי קמחו לאחרים דהא לא מועיל הקנין ובסמוך גרס ש\"מ הוא נאסר ואין קמחו נאסר:"]]],[["ואי איתא ליתני עבר ואפה מותר אמר רב אדא בר מתנה תנא תקנתא דהיתרא קתני תקנתא דאסורא לא קתני","ת\"ש מי שהניח עירובי תבשילין הרי זה אופה ומבשל ומטמין ואם רצה לאכול את עירובו הרשות בידו אכלו עד שלא אפה עד שלא הטמין הרי זה לא יאפה ולא יבשל ולא יטמין לא לו ולא לאחרים ולא אחרים אופין ומבשלין לו","אבל מבשל הוא ליו\"ט ואם הותיר הותיר לשבת ובלבד שלא יערים ואם הערים אסור","אמר רב אשי הערמה קא אמרת שאני הערמה דאחמירו בה רבנן טפי ממזיד","רב נחמן בר יצחק אמר הא מני חנניה היא ואליבא דבית שמאי דתניא חנניה אומר בית שמאי אומרים אין אופין אלא אם כן ערב בפת ואין מבשלין אא\"כ ערב בתבשיל ואין טומנין אלא אם כן היו חמין טמונין מערב יום טוב","ובית הלל אומרים מערב בתבשיל אחד ועושה בו כל צרכו","(תנן) המעשר פירותיו בשבת בשוגג יאכל במזיד לא יאכל לא צריכא דאית ליה פירי אחריני","ת\"ש המטביל כליו בשבת בשוגג ישתמש בהן במזיד לא ישתמש בהן","לא צריכא דאית ליה מאני אחריני א\"נ אפשר בשאלה","ת\"ש המבשל בשבת בשוגג יאכל במזיד לא יאכל אסורא דשבת שאני:","בית שמאי אומרים שני תבשילין: מתניתין דלא כי האי תנא דתניא אמר רבי שמעון בן אלעזר מודים בית שמאי ובית הלל על שני תבשילין שצריך על מה נחלקו על דג וביצה שעליו שב\"ש אומרים שני תבשילין ובית הלל אומרים תבשיל אחד ושוין שאם פרפר ביצה ונתן לתוך הדג או שרסק קפלוטות ונתן לתוך הדג שהן שני תבשילין","אמר רבא הלכתא כתנא דידן ואליבא ד\"ה:","אכלו או שאבד הרי זה לא יבשל עליו וכו': אמר אביי נקטינן התחיל בעיסתו ונאכל עירובו גומר:","\u0001מתני׳\u0002 חל להיות אחר השבת בית שמאי אומרים מטבילין את הכל מלפני השבת וב\"ה אומרים כלים מלפני השבת ואדם בשבת","ושוין שמשיקין את המים בכלי אבן לטהרן אבל לא מטבילין ומטבילין מגב לגב ומחבורה לחבורה:","\u0001גמ׳\u0002 דכולי עלמא מיהת כלי בשבת לא מאי טעמא אמר רבה גזרה"],[[0,"ואי איתא","דעבר ואפה מותר מכדי תנא אתקנתא קא מהדר נתני נמי הך תקנתא בהדי הך דמקנה קמחו:"],[0,"תקנתא דהיתרא","העשויה בהיתר:"],[2,"שלא יערים","לאחר שבשל לצורך. לומר עוד אני צריך להזמין אורחים ויבשל תבשילין אחרים ויותירם לשבת אבל בקדרה אחת אם ירבה לשבת הא אמר דאפי' לחול שרי כדלעיל ממלאה אשה קדרה בשר ואע\"פ שאינה צריכה אלא לחתיכה אחת:"],[2,"ואם הערים אסור","לאכול דאחמור רבנן בהא מילתא שלא לעקור תורת עירוב ולא דמי להערמה דרב אדא בר אהבה דמלח גרמא גרמא דאין עבוד באוכלין ואי משום טרחא הא עדיפא דלמא חס שלא יסריח הבשר וממנע ולא שחיט וקס\"ד דהוא הדין לעבר ואפה:"],[3,"שאני הערמה כו'","לעולם עבר ואפה מותר והערמה אינה ראיה לכאן דשאני הערמה ממזיד דאיכא למימר אחמור בה רבנן בהערמה טפי ממזיד דאלו מזיד רשע הוא לעבור על דברי חכמים ואין אחרים למדים הימנו והוא עצמו משים אל לבו ושב הלכך לא מעקרא תורת עירוב אבל מערים סבור לעשות בהיתר הלכך לא ישיב אל לבו לחזור בו ואחרים למדין הימנו ומעקרא תורת עירוב הלכך קנסוהו רבנן:"],[4,"הא מני","דקתני אם הערים אסור:"],[4,"חנניה היא","דשמעינן ליה דמחמיר בעירובי תבשילין ואליבא דבית שמאי:"],[6,"במזיד לא יאכל","שעבר על השבות דאין מגביהין תרומות ומעשרות ביו\"ט אלמא אחמור רבנן במילתייהו ואפי' גבי עונג שבת:"],[6,"דאית ליה פירי אחריני","לשבת:"],[7,"המטביל כליו","במקוה שיש לו בחצרו ועבר אדרבנן דאמרי במתניתין מטבילין כלים מלפני השבת דנראה כמתקן:"],[7,"ישתמש בהן","בו ביום:"],[8,"אפשר בשאלה","לשאול כלים מחברו ולהשתמש:"],[9,"אסורא דשבת","בשול שבת מאבות מלאכות הוא ואיסור סקילה הוא הלכך קנסוה רבנן למזיד אבל עבר ואפה ביום טוב לשבת אסורא דרבנן הוא דעבד:"],[10,"על מה נחלקו על דג וביצה שעליו שבית שמאי אומרים שני תבשילין","צריך וזה כתבשיל אחד שמחובר בו ובטיל לגביה וב\"ה אומרים דיו בתבשיל אחד כזה:"],[10,"ושוין שאם פרפר ביצה","מבושלת ונתן לתוכו דלחודיה קאי שהן שני תבשילין:"],[10,"שרסק","מינצ\"ר בלעז:"],[10,"קפלוטות","כרתי פורי\"ש בלעז:"],[11,"כתנא דידן","דמתניתין דקתני בית הלל שרו בתבשיל אחד:"],[12,"אם התחיל בעיסתו","לתקנה ולאפותה ע\"י עירובו:"],[13,"מתני' מטבילין את הכל","כל הצריך טבילה בין אדם בין כלים:"],[13,"מלפני השבת","דקי\"ל בר\"ה (דף טז:) חייב אדם לטהר את עצמו ברגל דכתיב ובנבלתם לא תגעו (ויקרא י״א:ח׳) ומוקים לה ברגל הלכך יטביל מערב שבת דאסור להטביל בשבת וביו\"ט:"],[13,"ובית הלל אומרים כו'","והא דנקט שבת רבותא אשמועינן לב\"ה דאפי' בשבת שרו באדם ובגמרא מפרש מאי טעמא דכלים אסורים:"],[14,"ושוין שמשיקין את המים","מי שיש לו מים יפין לשתות ונטמאו ממלא מהן כלי אבן ונותנם במקוה מים מלוחים עד שמשיק מים למים ונמצאו אלו זרועים ומחוברים למי המקוה ובטלי אגבייהו וטהרו ואין עוד טהרה במקוה לכל אוכל ומשקה אלא למים ולא בתורת טבילה אלא בתורת זריעה כדאמרינן בפסחים בפרק כל שעה (פסחים דף לד:):"],[14,"אבל לא מטבילין","בגמרא מפרש שאין נותנין אותן בכלי עץ טמא הצריך טבילה להשיקן בו כדי להעלות טבילה לכלי אגב השקת המים:"],[14,"ומטבילין מגב לגב","ביום טוב:"],[14,"ומחבורה לחבורה","בגמרא מפרש לה:"]],[[2,"","ובלבד שלא יערים. פרש\"י בשתי קדרות שיאמר אני צריך להזמין אורחים או יבאו לי אורחים אבל בקדרה אחת מותר להערים ולהרבות דהא חזינן לעיל דאפי' מיום טוב לחברו שרי בכך. ואם תאמר מאי שנא מההיא דרב אדא דמערים ומלח גרמא גרמא וי\"ל דשאני התם דהוי עבוד אוכלין בעלמא ומשום שמחת יום טוב התירו דאי לאו הכי חייש שמא יסריח הבשר וממנע ולא שחיט אבל הכא מיירי בבשול דחמור וגם היה יכול לעשות תקנה על ידי עירובי תבשילין מבעוד יום:"],[10,"","על מה נחלקו על דג וביצה שעליו שב\"ש אומרים שני תבשילין. ודג וביצה שעליו אינו חשוב אלא תבשיל אחד וב\"ה אומרים תבשיל אחד כלומר תבשיל אחד כי האי גוונא כגון דג וביצה שעליו חשוב שני תבשילין וקשה דלישנא לא משמע הכי לכך נראה לי דגרס אפכא. ב\"ש אומרים תבשיל אחד פירוש דג וביצה שעליו אינו חשוב אלא תבשיל אחד וצריך עוד תבשיל אחר ובית הלל אומרים שני תבשילין פירוש דג וביצה שעליו חשוב שני תבשילין:"],[11,"","אמר רבא הלכתא כתנא דידן ואליבא דב\"ה. פירש רש\"י ואליבא דבית הלל דקאמר תבשיל אחד ואר\"ת דלאפיה צריך לערב: גם בפת ואינו יכול לאפות על ערוב תבשיל אחד דהא קיימא לן כרבי אליעזר דאמר אין אופין אלא על האפוי ואין מבשלין אלא על המבושל מדקא מייתי סתמא דגמ' כוותיה לעיל בריש פרקין דקאמר ותנא מייתי לה מהכא והא דקאמרי ב\"ה לעיל מניח אדם ערוב תבשיל אחד ועושה בו כל צרכו קאי אמאי דקאמר בית שמאי אין טומנין את החמין אלא אם כן היו לו חמין טמונין מבעוד יום וכו' וסברי דאפי' בשלשה תבשילין צריך שיהא לכל אחד ואחד כנגדו ועל זה קא מיירי ב\"ה ואמרי דעל תבשיל אחד עושה בו כל צרכו כלומר כל מיני תבשילין כגון חמין וכיוצא בו והא דקאמר אביי לא שנו אלא תבשיל אחד אבל פת לא היינו דווקא היכא דאינו רוצה לאפות אבל אם היה רוצה לאפות היה צריך פת ולא נהירא להר\"ר יצחק חדא דמכל הני משמע דלא צריך אלא תבשיל אחד לכל דבר בין לאפות בין לבשל ומה שמביא הש\"ס לעיל דר' אליעזר לאו משום דהלכתא כותיה אלא אסמכתא בעלמא מייתי על עירובי תבשילין אלא אדרבה קיימא לן כרבי יהושע לגבי דרבי אליעזר משום דרבי אליעזר שמותי הוא ורבי יהושע פליג עליה בירושלמי ואמר אופין ומבשלין על המבושל ומ\"מ אור\"י לא מלאני לבי לעבור על דברי דודי וצריך שני תבשילין פת ותבשיל וכן עמא דבר:"]]],[["שמא יטלנו בידו ויעבירנו ארבע אמות ברשות הרבים א\"ל אביי יש לו בור בחצירו מאי איכא למימר א\"ל גזירה בור בחצרו אטו בור ברשות הרבים","התינח שבת ביו\"ט מאי איכא למימר גזרו יו\"ט אטו שבת","ומי גזרינן והא תנן ושוין שמשיקין את המים בכלי אבן לטהרן אבל לא מטבילין ואי איתא נגזור השקה אטו הטבלה","ותסברא אי אית ליה מים יפים הני למה לי למעבד להו השקה אלא דלית ליה וכיון דלית ליה מזהר זהיר בהו","איתיביה מדלין בדלי טמא והוא טהור ואי איתא נגזור דלמא אתי לאטבוליה בעיניה שאני התם מתוך שלא הותרה לו אלא ע\"י דליו זכור הוא","איתיביה כלי שנטמא מעיו\"ט אין מטבילין אותו ביו\"ט ביו\"ט מטבילין אותו ביום טוב ואם איתא נגזור דיום טוב אטו דערב יום טוב טומאה ביום טוב מלתא דלא שכיחא היא ומלתא דלא שכיחא לא גזרו בה רבנן","איתיביה כלי שנטמא באב הטומאה אין מטבילין אותו ביום טוב בולד הטומאה מטבילין אותו ביום טוב ואם איתא נגזור הא אטו הא","ולד הטומאה היכי משכחת לה גבי כהנים כהנים זריזין הם","ת\"ש דאמר רב חייא בר אשי אמר רב נדה שאין לה בגדים מערמת וטובלת בבגדיה ואם איתא נגזור דלמא אתי לאטבולי בעינייהו","שאני התם מתוך שלא הותרה לה אלא על ידי מלבוש זכורה היא","רב יוסף אמר גזרה משום סחיטה","אמר ליה אביי תינח כלים דבני סחיטה נינהו כלים דלאו בני סחיטה נינהו מאי איכא למימר א\"ל גזרה הני אטו הני איתיביה כל הני תיובתא ושני ליה כדשנינן","רב ביבי אמר גזרה שמא ישהא תניא כוותיה דרב ביבי כלי שנטמא מערב יום טוב אין מטבילין אותו ביום טוב גזרה שמא ישהא","רבא אמר מפני שנראה כמתקן כלי אי הכי אדם נמי אדם נראה כמיקר","הא תינח מים יפים מים רעים מאי איכא למימר אמר רב נחמן בר יצחק פעמים שאדם בא"],[[0,"גמרא ויעבירנו ארבע אמות ברשות הרבים","ממקומו עד המקוה:"],[2,"ומי גזרינן","ומי אחמור רבנן כולי האי בהך תקנתא דטבילת כלים למגזר התירא אטו אסורא וגזרה לגזירה:"],[3,"ותסברא","דהא קושיא הוא:"],[3,"מזהר זהיר בהו","שלא יטמאו וכיון דזהיר בהו הויא להו טומאתן מלתא דלא שכיחא ולא גזרו בה רבנן:"],[4,"מדלין","מים:"],[4,"בדלי טמא והוא טהור","מאליו והא לא דמי למטביל כלי ע\"ג מימיו דמתני' דאסור דהתם כל עצמו לא בא אלא לטהר בין מים בין כלי הלכך מוכחא מילתא דטבילה וטעמא דטבילה אסורה משום דנראה כמתקן כלי והאי מחזי אבל הכא אין הכל יודעים שהדלי טמא והרואה אומר לשאוב מים הללו היה צריך:"],[4,"נגזור דלמא אתי לאטבוליה בעיניה","בלא שאיבת מים:"],[4,"מתוך שלא הותרה לו","טבילה זו אלא ע\"י דליו בשאיבתו שאין כן דרך שאר טבילות:"],[4,"זכור הוא","שהטבילה אסורה בי\"ט:"],[5,"כלי שנטמא מערב י\"ט","ובאב הטומאה כדלקמן:"],[5,"אין מטבילין אותו בי\"ט","הואיל והיה לו להטבילן מבעוד יום:"],[5,"בי\"ט מטבילין אותו בי\"ט","וישתמש בו היום חולין שאין צריכין הערב שמש:"],[5,"דלא שכיחא","שהרי הכל מטהרין ברגל וכל שכן שזהירין מלהטמא:"],[6,"כלי שנטמא באב הטומאה","מערב י\"ט כדלעיל:"],[6,"אין מטבילין אותו בי\"ט","דכיון דטמא מן התורה הוה ליה כמתקן:"],[6,"בולד הטומאה","אין כאן תקון דמדאורייתא טהור מעליא הוא שאין כלי טמא אלא באב הטומאה כדתניא בהכל שוחטין (דף כה.) אוכל ומשקה מטמאין מאויר כלי חרס ואין כל הכלים מטמאין מאויר כלי חרס משום דהוה ליה ולד הטומאה שמה שבתוכו אין מיטמא מחמת השרץ אלא מחמת אויר כלי יש מפרשים כלי שנטמא באב הטומאה אפילו נטמא בי\"ט אין מטבילין אותו בי\"ט וטעמא משום דבעי הערב שמש דטומאה דאורייתא צריכה הערב שמש הלכך הואיל ואינו ראוי היום לתשמיש לא יטבילנו וקשי' לי הרי ראוי להשתמש בו חולין שאין הערב שמש אלא לתרומה וקדשים כדתנן טבל ועלה אוכל במעשר העריב שמשו אוכל בקדשים (נגעים פרק יד מ\"ג):"],[7,"ולד הטומאה היכי משכחת לה","מי הוא הצריך להטבילו אינו אלא כהן דהא ולד הטומאה ראשון וכלי שנטמא בו שני ומותר לחולין שאין שני עושה שלישי בחולין וא\"צ להטבילו אלא לתרומה:"],[7,"זריזין הן","ולא אתו למשרי דאב הטומאה אי נמי זריזין מלבא טומאה לכליהן והויא מלתא דלא שכיחא:"],[8,"שאין לה בגדים","טהורים להחליף וללבוש אחר טבילתה והיום י\"ט ואינה יכולה להטביל את אלו שעליה:"],[8,"מערמת וטובלת","כשהיא לבושה וסלקא לה טבילה אף לכלים ולא מוכחא מלתא שהיא מתקנת דלטבילת עצמה נכנסה ואדם מותר לטבול כב\"ה דנראה כמיקר כדלקמן:"],[10,"רב יוסף אמר","טעמא דמתני' דטבילת כלים בשבת וי\"ט אסירא משום סחיטת בגדים שאף הן בכלל כלים:"],[12,"שמא ישהא","אי שרית ליה לאטבולינהו ביו\"ט משהי להו עד י\"ט שהוא פנוי ואתי בהו בתוך כך לידי תקלה להשתמש בהן תרומה:"],[13,"רבא אמר","טעמא דמתני' מפני שנראה כמתקן כלי ודמיא לתקנת מלאכה וגזור עלה מדרבנן:"],[14,"תינח מים יפין","שדרך לרחוץ בהן:"]],[[0,"","שמא יעבירנו ארבע אמות ברשות הרבים. תימה אמאי לא קאמר שמא יוציאנו מרשות היחיד לרשות הרבים וי\"ל שיש היכרא בפתח ובגפופי החצר:"],[1,"","גזרה י\"ט אטו שבת. ולא הוי גזרה לגזרה די\"ט ושבת אחת היא:"],[2,"","נגזור השקה אטו הטבלה. וקשה לפרוך נגזור משום שמא יעבירנו ארבע אמות ברשות הרבים להשיקן וי\"ל דגבי הטבלת כלי צריך למגזר שמא יעבירנו לפי שלהוט להטבילו אבל בהשקת מים אין להוט כל כך להשיקן דאפשר במים אחרים וכן בסמוך בולד הטומאה לא פריך נגזור שמא יעבירנו לפי שאינו להוט כל כך להטבילו כיון דליכא אלא טומאה דרבנן:"],[4,"","מדלין בדלי טמא והוא טהור. מאליו תימה דבמתניתין אמר אין מטבילין כלי על גבי מימיו לטהרו וי\"ל דהתם מיירי שהוא מלא מים ויש בו הוכחה דלאטבולי קבעי ואסור להטביל כלי דמחזי כמתקן אבל הכא אין הכל יודעין שהדלי טמא וא\"כ הרואה יהא סבור דלשאוב הוא צריך:"],[6,"","כלי שנטמא באב הטומאה אין מטבילין אותו בולד הטומאה מטבילין אותו וכו'. פירש רש\"י דמיירי שנטמא מערב י\"ט דאי בי\"ט אפילו באב הטומאה מטבילין אותו והא דאמרינן לעיל מערב י\"ט אין מטבילין אותו בי\"ט מיירי שנטמא באב הטומאה וטעמא דאב הטומאה אין מטבילין אותו משום דטומאה דאורייתא היא דנראה כמתקן אבל בטומאה שנטמא במשקין אינו טמא כי אם מדרבנן ולא מחזי כמתקן ועוד פירש פירוש אחר דמיירי שנטמא בי\"ט עצמו ובאב הטומאה ומ\"מ אין מטבילין אותו בי\"ט הואיל וצריך הערב שמש ואין מטבילין לצורך חול אבל בולד הטומאה אינו צריך הערב שמש ומטבילין אותו בי\"ט והא דאמרינן נטמא ביום טוב מטבילין אותו בי\"ט מיירי שנטמא בולד הטומאה ולא נהירא ליה לרש\"י דאכתי מ\"מ הרי ראוי להשתמש בו חולין שאינו צריך הערב שמש אלא תרומה והר\"י פי' דניחא לפי המסקנא דאיירי בתרומה דשם צריך הערב שמש ואינו נראה להר\"ר יצחק דאטו פסיקא ליה דכהנים לית להו חולין ומיהו קשה היאך הוא מותר להטביל כלי שנטמא בולד הטומאה דאם רוצה להשתמש בחולין ובמעשר א\"צ טבילה ואי משום תרומה הא בעי הערב שמש וא\"כ לצורך חול הוא מטביל ויש לומר דלפירוש אחר שפירש רש\"י ניחא דבטבילה דרבנן כמו זו לא בעיא הערב שמש. כדתנן במסכת פרה (פי\"א משנה ה) כל הטעון ביאת מים מדברי חכמים לאחר ביאתו מותר בכולן:"],[7,"","היכי משכחת לה בכהנים. וא\"ת בישראל נמי משכחת לה דכל הפוסל תרומה מטמא משקין להיות תחלה וי\"ל דמיירי בכלי שאינו ראוי להשתמש בתוכו מים כגון כלי מנוקב:"],[8,"","מערמת וטובלת בבגדיה. תימה היינו שרייה ושרייה אסורה מפני שהוא מכבס ומלבן דאמרי' שרייתו זו היא כבוסו וי\"ל דהואיל דהוי דרך טינוף שרי ותדע דהאיך אנו מנגבים ידינו במפה בשבת הא הוי שרייה ואסור מפני שהוא מכבס ומלבן אלא כיון דהוי דרך טינוף שרי הכא נמי נימא הכי:"],[12,"","גזרה שמא ישהא. פי' עד י\"ט שהוא פנוי ויבא לידי תקלה להשתמש בהן תרומה אבל אדם אין משהא עצמו מלטבול ועוד לא שייך למיחש לידי תקלה כל כך:"]]],[["בשרב ורוחץ אפילו במי משרה","תינח בימות החמה בימות הגשמים מאי איכא למימר אמר רב נחמן בר יצחק פעמים שאדם בא מן השדה מלוכלך בטיט ובצואה ורוחץ אפילו בימות הגשמים","תינח בשבת ביוה\"כ מאי איכא למימר","אמר רבא מי איכא מידי דבשבת שרי וביוה\"כ אסור אלא הואיל ובשבת שרי ביוה\"כ נמי שרי","ומי אית ליה לרבא הואיל והתנן החושש בשיניו לא יגמע בהן את החומץ אבל מטבל הוא כדרכו ואם נתרפא נתרפא ורמינן עלה לא יגמע ופולט אבל מגמע ובולע","ואמר אביי כי תנן נמי מתני' מגמע ופולט תנן ורבא אמר אפי' תימא מגמע ובולע ולא קשיא כאן קודם טבול כאן לאחר טבול","ואם איתא נימא הואיל וקודם טבול שרי לאחר טבול נמי שרי הדר ביה רבא מההיא","וממאי דמההיא הדר ביה דלמא מהא הדר ביה לא סלקא דעתך דתניא כל חייבי טבילות טובלין כדרכן בין בתשעה באב בין ביוה\"כ:","ושוין שמשיקין את המים בכלי אבן וכו': מאי אבל לא מטבילין אמר שמואל אין מטבילין את הכלי על גב מימיו לטהרו ביום טוב","מני מתניתין לא רבי ולא רבנן דתניא אין מטבילין את הכלי על גב מימיו לטהרו ואין משיקין את המים בכלי אבן לטהרן דברי רבי וחכמים אומרים מטבילין כלי על גב מימיו לטהרו ומשיקין את המים בכלי אבן לטהרן","מני אי רבי קשיא השקה אי רבנן קשיא הטבלה","איבעית אימא רבי איבעית אימא רבנן אי בעית אימא רבי רישא דברייתא ביום טוב וסיפא בשבת וכולה מתניתין ביו\"ט"],[[0,"בשרב","חום:"],[0,"מי המשרה","ששורין הפשתן בהן:"],[2,"ביום הכפורים","שאסור ברחיצה משום ענוי ומותר בטבילת מצוה כדלקמן:"],[2,"מאי איכא למימר","הא ודאי מוכחא מלתא דלטבילה מתכוין ולא כמיקר:"],[3,"מי איכא מידי","דמלאכה דבשבת שרי וליכא איסור דרבנן משום דדמיא למלאכה:"],[3,"וביום הכפורים אסור","משום מלאכה כי הא דבעית למסרי עליה משום דנראה כמתקן:"],[3,"כיון דבשבת","דחמירא במלאכה שרי משום טעמא דמיקר:"],[3,"ביום הכפורים נמי שרי","ואע\"ג דלא נראה כמיקר שלא תחמיר לענין מלאכה ביום הכפורים משבת:"],[4,"ומי אית ליה הואיל","באיסורי שבת כה\"ג משום דשרי בהא לא תשרי בהא:"],[4,"לא יגמע בהן את החומץ","לרפואה דכל רפואה בשבת גזור בה רבנן משום שחיקת סממנין שהיא אב מלאכה טוחן:"],[4,"אבל מטבל הוא","בו מאכלו כדרכו:"],[4,"לא יגמע ופולט","דמוכחא מלתא דלרפואה עביד:"],[5,"","ואמר אביי גרסינן:"],[5,"ורבא אמר","גרסינן:"],[5,"קודם טבול","קודם אכילה מגמע ובולע דלא מוכחא מלתא דלרפואה דסברי חומץ אהני ליה למיכל:"],[5,"לאחר טבול","לאחר אכילה וטבל מאכלו בחומץ דמוכחא מלתא דלאו חומץ בעי למטעם אלא משום רפואה ואמאי הרי קודם אכילת שבת היה מותר ובחצי שבת אתה אוסרו ובחצי שבת אתה מתירו:"],[6,"נימא הואיל","וקודם אכילה שרי דנראה כחפץ בבליעת חומץ לאחר אכילה נמי שרי שאין חלוק בשיעור של שבת:"],[6,"הדר ביה רבא מההיא","דחומץ ושנייה כאביי ואת זו דטבילה דאית ליה הואיל אמר לאחר חזרה:"],[7,"דלמא מהא","דטבילה דיוה\"כ הדר ביה ושל חומץ אמר באחרונה:"],[7,"לא ס\"ד","למיסר טבילה ביוה\"כ:"],[7,"בין בתשעה באב בין ביום הכפורים","ואע\"פ שאסורין ברחיצה:"],[8,"אין מטבילין כלי","הצריך טבילה על גב השקת מימיו לטהרו:"],[9,"","הכי גרסינן דתניא אין מטבילין את הכלי על גב מימיו לטהרו ואין משיקין את המים בכלי אבן לטהרן דברי רבי וחכמים אומרים מטבילין כלי על גב מימיו לטהרו ומשיקין את המים בכלי אבן לטהרן מני אי רבי קשיא השקה אי רבנן קשיא הטבלה אי בעית אימא רבי אי בעית אימא רבנן אי בעית אימא רבי מתניתא רישא בי\"ט וסיפא בשבת וכולה מתני' בי\"ט ואי בעית אימא רבנן וכולה מתני' בשבת - וה\"פ אי רבי קשי' השקה דרבי אסר ומתני' תנן משיקין אי רבנן קשיא הטבלה דאינהו שרו להטביל ומתניתין קתני אין מטבילין ומשני רישא דמתניתא רישא דמלתא דרבי דאיירי בהטבלה לאוסרה הא השקה שריא איירי בי\"ט וסיפא דמלתיה דאסר אף השקה איירי בשבת וכן רבנן נמי רישא איירי בי\"ט וסיפא איירי בשבת והכי קאמר מטבילין כלי על גב מימיו לטהרו ביו\"ט וכל שכן דמשיקין ומשיקין את המים בכלי אבן בשבת השקה אין הטבלה לא ובתוספתא דביצה ודשבת בהדיא תני בה הכי אין מטבילין את הכלי על גב מימיו לטהרו בי\"ט ואין משיקין את המים בכלי אבן לטהרן בשבת דברי רבי וחכמים אומרים כו' והשתא דברייתא מתוקמא הכי אי בעית אימא מתני' רבנן היא וכולה מתני' בשבת הלכך הטבלה אסירא והשקה שריא כרבנן דאמרי משיקין את המים בכלי אבן לטהרן בשבת השקה הוא דשריא הא הטבלת כלים אסירא:"]],[[6,"","הדר ביה רבא מההיא. פי' מההיא שנויא דקא משני כאן קודם כו' לא ס\"ד דאמר כל חייבי טבילות כו' ותימה מנא ליה דרבא הדר ביה מההיא שנויא לעולם אימא לך דהדר משנויא דהואיל דמאי מזקיקו לההוא טעמא דהואיל דקמשני מתני' משום דנראה כמתקן ואימא דהדר ביה מההיא שנויא והדר ביה נמי מההיא שנויא דהואיל והא דכלים אסורים מההיא טעמא דשנויי אמוראי דלעיל משום שמא יעבירנו או ישהא או יסחוט וי\"ל דסמי חדא מקמי תרתי ההיא שנויא דהכא כאן קודם טבילה מקמי תרתי שנויי דמשני משום מתקן כלי והואיל ולא נהירא חדא דהא בהא תליא דהא מה דמשני רבא הואיל ושבת כו' היה כולו להעמיד שנויא משום דנראה כמתקן ועוד דהיה לו לפרש האי מקמי תרתי לכך נראה לי דקים ליה לגמרא דלא היה יכול לעקור מפני שנראה כמתקן כיון דמתרץ ליה עלה דמתני' אבל היה סבור לעקור שנויא דהואיל ומהא נמי מייתי ראיה דאין יכול לעקור [וע\"ע תוס' שבת קיא. ד\"ה לא]:"],[7,"","כל חייבי טבילות טובלין כדרכן בין בתשעה באב בין ביום הכפורים. היינו דוקא להני שטובלין טבילת מצוה בזמנה אבל השתא שכל טבילות שנשותינו טובלות היינו טבילה שלא בזמנה דהן סופרות ז' נקיים מספק שהן זבות אינן טובלות בט' באב וביוה\"כ ומיהו יש לחלק כדאמר ביומא (דף פח.) נדות ויולדות טבילתן בלילה זבין וזבות טבילתן ביום בעל קרי טובל והולך עד המנחה כדי שיתפלל תפלת המנחה בטהרה אבל לאחר המנחה לא יטבול ומפרש התם טעמא דאי משום תפלת נעילה היה יכול להמתין עד הלילה ויטבול ויתפלל תפלת נעילה בלילה ואמאי אינו טובל ביום כדי שתהא הטבילה בזמנה אלמא ש\"מ דקסבר ההוא תנא דטבילה בזמנה לאו מצוה היא ואפילו הכי שריא ביוה\"כ ומיהו בתשעה באב אין טובלין כר' חנינא בן אנטיגנוס דאמר כדאי בית אלהינו לאבד טבילה אחת בשנה וקאמר עלה בירושלמי הורה ר' לוי כר' חנינא בן אנטיגנוס ולית הלכתא כהך משנה דקאמר כל חייבי טבילות וכו' ועוד אומר ר\"י דבזמן הזה אין טובלין לא ביוה\"כ ולא בט' באב דדוקא הם שהיו עוסקין בטהרות היה צריך לטבול מיד כדי שלא יטמאו הטהרות אבל השתא דהטבילה אינה באה אלא לטהרה לבעלה יכולה היא לרחוץ ולחוף ערב יוה\"כ כדי שתסרוק שערה וחופפת מעט למוצאי יום הכפורים משום דצריך חפיפה סמוך לטבילה וכן בט' באב דהא אפי' תטבול ביום הכפורים ובט' באב אסורה. לבעלה:"],[8,"","ושוין שמשיקין המים בכלי אבן לטהרן. אבל לא בכלי עץ לפי שהוא מקבל טומאה מן המשקין ונמצא שהוא מטביל כלי וא\"ת אמאי אין מטבילין אותו הא איכא תרתי לטיבותא חדא דנטמא בי\"ט ועוד דלא נטמא כי אם בולד הטומאה וכולי עלמא מודים דמטבילין לכל הפירושים דלעיל ולמאן דמוקי מתניתין בשבת וכרבנן ניחא אבל למאן דמוקי לה בי\"ט וכו' קשיא וי\"ל דמ\"מ אין לגרום הטומאה לכלי בידים כדי שיטבילנו דדוקא כשנטמא כבר בולד הטומאה הוא דמטבילין אותו אבל אסור לטמאותו על מנת להטבילו בי\"ט:"],[9,"","אין מטבילין את הכלי על גבי מימיו לטהרו ואין משיקין וכו'. הכי גריס רש\"י הטבלה קודם השקה בין בדברי רבי בין בדברי חכמים ובספרים היה כתוב אפכא השקה קודם הטבלה והכל אחד אלא שגרסת הספרים גרס רישא בשבת וסיפא בי\"ט ולגירסת רש\"י רישא בי\"ט וסיפא בשבת ועל פי התוספתא הגיה רש\"י הגירסא ולפי מה שכתוב בספרים השקה קודם הטבלה לא תוכל לפרש רישא בי\"ט וסיפא בשבת אלא אם כן תפרש שאמתניתין קאי דקתני משיקין אבל לא מטבילין ושבוש הוא כדפירש רש\"י:"]]],[["ואיבעית אימא רבנן וכולה מתניתין בשבת:","תנו רבנן כלי שנטמא מערב יום טוב אין מטבילין אותו בין השמשות","רבי שמעון שזורי אומר אף בחול אין מטבילין אותו מפני שצריך הערב שמש","ותנא קמא לא בעי הערב שמש אמר רבא אשכחתינהו לרבנן דבי רב דיתבי וקא אמרי במחשבתו נכרת מתוך מעשיו קמפלגי והיכי דמי כגון דנקיט מנא בידיה ורהיט ואזיל בין השמשות לאטבוליה","מר סבר האי דקא רהיט ואזיל מידע ידע דבעי הערב שמש","ומר סבר מחמת מלאכתו הוא דקרהיט","ואמינא להו אנא במחשבתו נכרת מתוך מעשיו דכולי עלמא לא פליגי כי פליגי כגון דאיטמי בפחות מכעדשה ואתא לקמיה דרבנן לשיולי בפחות מכעדשה איטמי אי לא מר סבר מדהא לא גמיר הערב שמש נמי לא גמיר ומר סבר הא הוא דלא גמיר הא הערב שמש גמיר:","ומטבילין מגב לגב: תנו רבנן כיצד מגב לגב הרוצה לעשות גתו על גב כדו","וכדו על גב גתו עושה","כיצד מחבורה לחבורה היה אוכל בחבורה זו ורוצה לאכול בחבורה אחרת הרשות בידו:","\u0001מתני׳\u0002 ב\"ש אומרים מביאין שלמים ואין סומכין עליהן אבל לא עולות ובית הלל אומרים מביאין שלמים ועולות וסומכין עליהן:","\u0001גמ׳\u0002 אמר עולא מחלוקת בשלמי חגיגה לסמוך ועולת ראייה ליקרב דבית שמאי סברי (ויקרא כג, מא) וחגותם אותו חג לה' חגיגה אין עולת ראייה לא וב\"ה סברי לה' כל דלה'","אבל נדרים ונדבות דברי הכל אין קריבין ביו\"ט וכן אמר רב אדא בר אהבה נדרים ונדבות אין קריבין ביו\"ט","מתיבי אמר רבי שמעון בן אלעזר לא נחלקו בית שמאי ובית הלל על עולה שאינה של יו\"ט שאינה קרבה ביום טוב ועל שלמים שהן של יום טוב שקריבין ביו\"ט","על מה נחלקו על עולה שהיא של יום טוב ועל שלמים שאינן של יו\"ט שבית שמאי אומרים לא יביא ובית הלל אומרים יביא","תריץ ואימא הכי אמר ר' שמעון בן אלעזר לא נחלקו בית שמאי ובית הלל על עולה ושלמים שאינן של יו\"ט שאין קריבין ביום טוב ועל שלמים שהן של יום טוב שקריבין ביו\"ט על מה נחלקו על עולה שהיא של יו\"ט שבית שמאי אומרים לא יביא ובית הלל אומרים יביא","רב יוסף אמר תנאי שקלת מעלמא תנאי היא דתני' שלמים הבאים מחמת יו\"ט ביום טוב בית שמאי אומרים סומך עליהן מערב יו\"ט ושוחטן ביו\"ט ובית הלל אומרים סומך עליהן ביום טוב ושוחטן ביום טוב"],[[0,"ואי בעית אימא","רבי קתני לה וכולה מתני' בי\"ט כדאמרינן אין מטבילין את הכלי על גב מימיו לטהרו בי\"ט הטבלה הוא דלא הא השקה בכלי אבן שפיר דמי ובספרים שלנו נחלפה רישא לסיפא וסיפא לרישא דכתיב בהו ברישא אין משיקין והדר אין מטבילין ועל כן רוב התלמידים שגו בפירושה של סוגיא זו ואין אדם יכול לישבה על כנה וגורסין מפני דוחק ומתני' רישא בי\"ט וסיפא בשבת ומפרשינן רישא דקתני משיקים בי\"ט קאמר ותנא השקה והוא הדין להטבלה וסיפא דקתני אבל לא מטבילין איירי בשבת ותנא הטבלה והוא הדין להשקה ואין ראוי לפרש כן לדרדקי דבי רב דא\"כ ליתני קילתא ושמעינן חמירתא לשמעינן הטבלה דמותרת בי\"ט ואנא אמינא דכל שכן השקה אבל השתא דאשמעינן משיקין איכא למימר דוקא קתני אבל הטבלה לא וכן לענין שבת דאשמעינן אבל לא מטבילין אי הוא הדין להשקה סבירא ליה הוה ליה לאשמועינן אין משיקין ושמעינן כל שכן דאין מטבילין אבל השתא דאשמעינן אין מטבילין איכא למימר הא השקה שרי וסייג לדברי ספר התוספתא דכך מצינו בו במסכת שבת ובמסכת ביצה:"],[1,"אין מטבילין אותו בין השמשות","מפני שהוא ספק לילה ונמצא מטביל בי\"ט:"],[2,"אף בחול","אם אנו רואין אדם המטביל כלי בין השמשות אנו צריכין להחזירו ולמחות בידו מפני שצריך הערב שמש וזה המטביל כלי בלילה ודאי דעתו להשתמש בו מיד ולא להמתין הערב שמש דלמחר:"],[3,"ותנא קמא לא בעי כו'","בתמיה:"],[3,"אשכחתינהו לרבנן דבי רב","לתלמידים שבבית המדרש:"],[3,"מעשיו","דקא רהיט במרוצה:"],[4,"מידע ידע דבעי הערב שמש","והיינו דרהיט כסבור להספיק קודם יציאת היום וכשיראה שלא יספיק הואיל ובא למקוה גומר טבילתו וממתין מלהשתמש בו עד שיעריב שמשו למחר הלכך בין השמשות די\"ט אסור משום דמטביל בי\"ט שלא לצורך אבל בחול לא מחינן ביה דמחשבתו ניכרת שלהערב שמשו הוא מתכוין מתוך מעשיו של מרוצתו:"],[6,"דכולי עלמא לא פליגי","דודאי ניכרת באיניש דעלמא והאי גברא דאפליג ביה רבי שמעון שזורי ואמר דלא אמרינן ביה מחשבתו ניכרת מתוך מעשיו:"],[6,"כגון דאיטמי ליה","מנא אחרינא בפחות מכעדשה מן השרץ ואתא לשיולי וכו':"],[6,"הא הוא דלא גמיר","דלא כתיב בהדיא בכעדשה אבל הערב שמש דבהדיא כתיב מגמר גמיר ובכהן עסקינן דמשתמש בו תרומה:"],[7,"הרוצה לעשות גתו על גב כדו","מי שהיו כליו טמאין והטבילן לדעת דריכת זיתיו ונמלך לעשות גתו:"],[8,"עושה","גתו על גב טבילה זו שהטביל לשם כדו וא\"צ לחזור ולהטביל לשם גת וההיא טבילה שניה הבא להחמיר על עצמו ולהטביל קתני מתניתין שהוא מטביל בי\"ט שאין כאן תקון כלי ואינה טבילה שהרי אינה צריכה:"],[9,"בחבורה זו","על פסחו והיה טמא או כליו טמאין וטבל לדעת כן:"],[9,"הרשות בידו","וא\"צ לחזור ולטבול וקאמרה מתני' דאם בא להחמיר ולהטביל כליו לשם חבורה האחרת מטביל ביום טוב:"],[10,"מתני' מביאין שלמים","ביו\"ט לפי שיש בהן אכילת אדם:"],[10,"ואין סומכין עליהן","שהסמיכה אסורה משום שבות שבכל כחו היה סומך והוי ליה משתמש בבעלי חיים ותנן אין רוכבין על גבי בהמה (לקמן ביצה דף לו:):"],[10,"אבל לא עולות","אין מביאין עולות חוץ מתמידין ומוספין שהן קרבן צבור וזמנן קבוע אבל עולת יחיד לא יביא לפי שאין בה אכילת הדיוט וכתיב (שמות י״ב:ט״ז) יעשה לכם ולא לגבוה:"],[11,"גמ' מחלוקת בשלמי חגיגה לסמוך ועולת ראייה ליקרב","מתני' דמודו תרוייהו בשלמים להביא ולא אפלוג בהו אלא בסמיכתן בשלמי חגיגה מודו ב\"ש בהבאתן מפני שהן חובת היום כדאמרינן בחגיגה (דף ט.) מוחגותם אותו חג ועולה שנחלקו אף בהבאתן בעולת ראייה נחלקו וההיא הוא דקא שרו ב\"ה מפני שהיא של יום טוב דנפקא לן מולא יראו פני ריקם (שמות כ״ג:ט״ו):"],[12,"אבל נדרים ונדבות","הואיל ואין זמנן היום כלל דברי הכל אין קרבין ואפי' שלמים וכ\"ש עולות דיכול להביאן לאחר זמן ואף על גב דחגיגה וראייה יש להן תשלומין כל שבעה שרו בה שמא יאנס ולא יקריבנה בשאר הימים ותנן עבר הרגל ולא חג אינו חייב באחריותו והכי מפרש בברייתא לקמן דמשום האי טעמא שרו לה:"],[13,"שאינה של יום טוב","כגון נדר ונדבה:"],[13,"שאינה קרבה","דאית בה תרתי לאסורא אין בה אכילת אדם ואפשר לאחר זמן:"],[13,"ועל שלמים שהן של י\"ט","כגון חגיגה ושלמי שמחה:"],[13,"שקרבין","דאיכא תרתי להתירא אכילת אדם והן זמנן ברגל ואם יעבור הרגל בטל קרבנו:"],[14,"ועל שלמים שאינן וכו'","אלמא שלמים דנדרים ונדבות לבית הלל קרבין וקשיא לעולא:"],[16,"תנאי שקלת מעלמא","וכי לא משכחת תנא דאמר כעולא דתימא עולא כי ההוא סבירא ליה דאיצטריכא לך לשבושה להך מתני' ולתרוצה:"],[16,"תנאי היא","אשכחן תנא אחרינא דקאי כעולא:"],[16,"מחמת יום טוב","חגיגה ושמחה:"]],[[11,"","אמר עולא מחלוקת כו'. וא\"ת לב\"ש למה להו למימר טעמא משום וחגותם הא קאמרינן לקמן משום לכם ולא לגבוה וי\"ל משום דלא תטעה לומר לה' כל דלה' ומ\"מ קשיא לב\"ה למה להו למימר כל דלה' תיפוק ליה משום דאית להו לב\"ה מתוך וכו' והוי שפיר צורך קצת משום שלא יאמרו שלחן שלך מלא ושל רבך ריקן כדפרישית לעיל פ\"ק (ביצה ד' יב. סד\"ה ה\"ג) וי\"ל משום שלא תטעה לומר וחגותם חג חגיגה אין עולה לא:"]]],[["אבל נדרים ונדבות דברי הכל אין קריבין ביום טוב","והני תנאי כי הני תנאי דתניא אין מביאין תודה בחג המצות מפני חמץ שבה ולא בעצרת מפני שהוא יו\"ט אבל מביא אדם תודתו בחג הסוכות","ר' שמעון אומר הרי הוא אומר (דברים טז, טז) בחג המצות ובחג השבועות ובחג הסכות כל שבא בחג המצות בא בחג השבועות ובחג הסוכות וכל שלא בא בחג המצות אינו בא בחג השבועות ובחג הסוכות ר\"א בר\"ש אומר מביא אדם תודתו בחג הסוכות ויוצא בה ידי חובתו משום שמחה ואין יוצא בה משום חגיגה","אמר מר אין מביאין תודה בחג המצות מפני חמץ שבה פשיטא אמר רב אדא בריה דרב יצחק ואמרי לה רב שמואל בר אבא הכא בארבעה עשר עסקינן וקסבר אין מביאין קדשים לבית הפסול","ולא בעצרת מפני שהוא יו\"ט קסבר נדרים ונדבות אין קריבין ביום טוב","אבל מביא אדם תודתו בחג הסוכות אימת אילימא ביום טוב עצמו והא אמרת ולא בעצרת מפני שהוא יום טוב אלא בחולו של מועד","ר\"ש אומר הרי הוא אומר בחג המצות ובחג השבועות ובחג הסוכות כל שבא בחג המצות בא בחג השבועות ובחג הסוכות וכל שלא בא בחג המצות אינו בא בחג השבועות ובחג הסוכות מתקיף לה ר' זירא השתא סלותי מסלתינן נדרים ונדבות מבעיא","אמר אביי בהקרבה כולי עלמא לא פליגי דשרי כי פליגי למיקם עליה בבל תאחר","ת\"ק סבר שלש רגלים אמר רחמנא אפילו שלא כסדרן","ור' שמעון סבר כסדרן אין שלא כסדרן לא","רבי אלעזר בר' שמעון אומר מביא אדם תודתו בחג הסוכות אימת אילימא בחולו של מועד היינו ת\"ק אלא ביו\"ט וקסבר נדרים ונדבות קריבין ביו\"ט","ומאי שנא חג הסוכות דנקט רבי אלעזר בר' שמעון לטעמיה דתניא רבי שמעון אומר לא יאמר חג הסוכות שבו הכתוב מדבר למה נאמר לומר שזה אחרון","רבי אלעזר ברבי שמעון אומר לומר שזה גורם:","ויוצא בה משום שמחה ואינו יוצא בה משום חגיגה: פשיטא דבר שבחובה הוא וכל דבר שבחובה אינו בא אלא מן החולין","לא צריכא דאף על גב דפריש","כדבעא מניה רבי שמעון בן לקיש מר' יוחנן האומר הרי עלי תודה ואצא בה ידי חגיגה הריני נזיר"],[[0,"אבל נדרים ונדבות כו'","ועולא דקאמר כי האי תנא:"],[1,"והני תנאי","דלקמן פליגי כי הני תנאי דלעיל בנדרים ונדבות:"],[1,"מפני חמץ שבה","על חלות לחם חמץ וגו' (ויקרא ז׳:י״ג):"],[1,"ולא בעצרת מפני שהוא יום טוב","ותודה נדרים ונדבות היא:"],[1,"בחג הסוכות","בחולו של מועד:"],[2,"רבי שמעון אומר כו'","לקמיה מפרש לה:"],[2,"מביא אדם תודתו בחג הסוכות","לקמיה מפרש אפילו ביום טוב קאמר ויוצא בה משום שלמי שמחה ואף על פי שמחויב בתודה זו ועומד דתניא במסכת חגיגה (דף ח.) ושמחת בחגך לרבות כל מיני שמחות של בשר לשמחה מדלא כתיב והבאת שלמים ואכלת שם ושמחת ומיהו פשיטא לן דכל זמן שבית המקדש קיים אין שמחה אלא בבשר שנאמר (דברים כ״ז:ז׳) וזבחת שלמים ואכלת שם ושמחת והאי קרא בהר גרזים כתיב ולא בשלמי שמחת י\"ט כתיב דשמחת י\"ט אם יש לו בכורות ומעשר בהמה אין צריך להביא שלמים:"],[2,"ואין יוצא בה משום חגיגה","דדבר שבחובה הוא וכל דבר שבחובה אינו בא אלא מן החולין ותודה זו כבר מחויב הוא בה ואין זו מן החולין שיהא פוטר בה חגיגתו:"],[3,"אמר מר","השתא מהדר אמילתיה לפרושי מאי דאמר לעיל בהקרבת נדרים ונדבות פליגי:"],[3,"לבית הפסול","שממעט זמן אכילתן שאינו יכול לאכול חמץ אלא עד ארבע שעות ומתוך כך חמץ שבה בא לידי נותר:"],[6,"ר\"ש אומר כו'","קס\"ד למיסר נדרים ונדבות בחולו של מועד אתא:"],[6,"השתא","לרבי שמעון דאסר הני:"],[6,"סלותי מסלתינן","לוקטין עצים בשדה מן המחובר בחולו של מועד דתניא במועד קטן (דף יב:) קוצצין עצים מן המחובר במועד לצורך המועד:"],[7,"אמר אביי בהקרבה כ\"ע ל\"פ דשרי","בחולו של מועד:"],[7,"כי פליגי למיקם עליה בבל תאחר","וכולה הך מתני' לענין בל תאחר איירי תנא קמא סבר כל המאחר נדרו שלש רגלים אפילו שלא כסדרן עובר בבל תאחר וטעמא יליף בר\"ה (דף ד:) מהאי קרא שלש פעמים בשנה וגו' למה לי למיכתב בחג המצות ובחג השבועות ובחג הסוכות כיון דכתיב שלש פעמים פשיטא דהני נינהו דהא מינייהו קסליק דלעיל מיניה כתיב שמור את חדש האביב שבעה שבועות תספור לך חג הסוכות תעשה לך ש\"מ לבל תאחר לומר אלה קבעתי לך לתשלום מתנותיך ונדריך והיינו דקא אתא לאשמועינן עצה טובה כל מי שיש עליו תודה יביאנה בחג הסוכות ואפילו הוא רגל ראשון אחר נדרו שאם לא יביאנה עכשיו יצטרך לבא בשבילה לירושלים שהרי בעלותו ברגל בפסח לא יביאנה מפני חמץ שבה ולא בעצרת מפני שהוא יום טוב נמצא שאיחרה ג' רגלים שלא כסדרן ואתא ר\"ש למימר הרי הוא אומר כו' כסדרן אין שלא כסדרן לא הלכך הנודרה לפני סוכות יש לו שהות עד לשנה הבאה וה\"ק כל שבא בחג המצות כגון שנדר קודם הפסח והיה עליו להביאה בחג המצות בא בחג השבועות שלאחריו או בחג הסוכות ואין לו עוד שהות וכל שאינו בא בחג המצות שלא היתה עליו להביאה בפסח כגון שנדר אחר הפסח אינו בא כלומר אינו צריך להביאה לא בחג השבועות שלאחריו ולא בחג הסוכות שיש לו שהות עד הסוכות של שנה הבאה שעברו שלש רגלים כסדרן:"],[10,"אלא ביום טוב וקסבר כו'","והיינו תנאי:"],[11,"לא יאמר חג הסוכות","כשהחזיר הכתוב להזכירן לשלש רגלים לבל תאחר לא היה צריך לכתוב ובחג הסוכות כיון שכתוב שלש פעמים בשנה וכתב בחג המצות ובחג השבועות דממילא ידענא דבו היה הכתוב מדבר שבפרשת סוכות הוא עסוק ובו נכתב כתוב זה:"],[11,"שזה אחרון","דבעינן כסדרן:"],[12,"שזה גורם","את בל תאחר שאפילו נדר לפני החג כיון שעבר עליו חג הסוכות עובר:"],[13,"דבר שבחובה הוא","דכתיב וחגותם:"],[13,"מן החולין","ולא ממעות מעשר שני ולא מנדרים ונדבות שהוא מחויב ועומד בהן:"],[14,"דאף על גב דפריש","דכשנדר התודה פירש על מנת שיוצא בה ידי חגיגתו:"]],[[2,"","רבי שמעון אומר הרי הוא אומר בחג המצות וגו' כל שבא בחג המצות בא בחג השבועות ובחג הסוכות. כך משמע מתוך פירוש הקונטרס דלקמן דגריס הכי וא\"כ לפירוש זה מעיקרא דס\"ד שבא לומר דנדרים ונדבות אין קרבין בחול המועד ה\"פ כל שאינו בא בחג המצות כגון תודה וכיוצא בה דאליבא דתנא קמא תודה אינה קרבה בחג המצות ואפי' בחול המועד וזהו דוחק דהיכי משמע ממלתיה דנדרים ונדבות חוץ מתודה אינן באין בחג המצות וכי תימא כל שאינו בא בחג המצות ר\"ל ביום טוב אם כן לא הוי דומיא דחג הסוכות ועוד דאם כן אמאי כתב בחג השבועות לומר שאינן באין בחג השבועות והא אף בחול המועד דסוכות אינן באין ועוד כי גם לפי המסקנא לא אתי שפיר דקאמר דלענין בל תאחר קאמר וה\"ק כל שראוי לבא בחג המצות שנתחייב בו קודם חג המצות בא בחג השבועות ובחג הסוכות שלא יאחר מלהביאו או בעצרת או בסוכות ועתה איך יביאנו והלא אין בו חול המועד וכי תימא דנדרים ונדבות קרבין בי\"ט הא משמע דבהני תנאי ליכא מאן דסבר קרבין בי\"ט רק רבי אלעזר בר' שמעון ודוחק הוא לפרש בא בחג השבועות שכשיבא לרגל יביאנו או קודם לכן ולאו בי\"ט קאמר על כן נראה דגרס הכי כל הבא בחג המצות ובחג השבועות בא בחג הסוכות וכו' והשתא מעיקרא סלקא דעתך כל שאינו בא בחג המצות כגון תודה וכן שאר נדרים ונדבות שאינן באין בחג השבועות כדקאמר תנא קמא בהדיא אינן באין בחג הסוכות ואפילו בחול המועד ולפי המסקנא ה\"ק כל שבא בחג המצות ובחג השבועות כלומר שראוי לבא בזמן שניהם כלומר שעברו שני רגלים כסדרן בא בחג הסוכות פירוש צריך שיביאנו בחול המועד של סוכות וכל שאינו בא וכו' כלומר שאינו ראוי לבא בשניהם רק בעצרת ולא בחג המצות אינו חייב להביאו בחג הסוכות זה ורישא דוקא פירוש בא בחג הסוכות כלומר חובה להביאו משום בל תאחר וסיפא לאו דוקא פי' סיפא דאינו בא ר\"ל אם לא ירצה שהרי הוא יכול להמתין עד סוכות של שנה הבאה אבל לעולם אם ירצה יקריב בחול המועד וקל להבין:"]]],[["ואגלח ממעות מעשר שני מהו א\"ל נדור ואינו יוצא נזיר ואינו מגלח:","ההוא גברא דאמר להו הבו ליה ארבע מאה זוזי לפלוני ולנסיב ברתי אמר רב פפא ארבע מאה שקיל וברתיה אי בעי נסיב אי בעי לא נסיב","טעמא דאמר הבו ליה ולנסיב אבל אי אמר לנסיב והבו ליה אי נסיב שקיל ואי לא נסיב לא שקיל:","יתיב מרימר וקאמר להא שמעתא משמיה דנפשיה א\"ל רבינא למרימר אתון הכי מתניתו לה אנן כדבעא מיניה ריש לקיש מר' יוחנן מתנינן לה:","תני תנא קמיה דר' יצחק בר אבא (ויקרא ט, טז) ויקרב את העולה ויעשה כמשפט כמשפט עולת נדבה למד על עולת חובה שטעונה סמיכה","א\"ל דאמר לך מני בית שמאי היא דלא גמרי שלמי חובה משלמי נדבה דאי בית הלל כיון דגמרי שלמי חובה משלמי נדבה עולת חובה נמי לא תבעי קרא דגמרי מעולת נדבה","וממאי דבית הלל שלמי חובה משלמי נדבה גמרי דלמא מעולת חובה גמרי ועולת חובה גופא בעיא קרא","מאי שנא משלמי נדבה דלא גמרי שכן מצויין מעולת חובה נמי לא גמרי שכן כליל","(אלא) אתיא מבינייא","וסברי בית שמאי שלמי חובה לא בעו סמיכה והתניא אמר רבי יוסי לא נחלקו בית שמאי ובית הלל על הסמיכה עצמה שצריך על מה נחלקו על תכף לסמיכה שחיטה שבית שמאי אומרים אינו צריך ובית הלל אומרים צריך","הוא דאמר כי האי תנא דתניא אמר רבי יוסי בר' יהודה לא נחלקו בית שמאי ובית הלל על תכף לסמיכה שחיטה שצריך על מה נחלקו על הסמיכה עצמה שבית שמאי אומרים אינו צריך ובית הלל אומרים צריך:","ת\"ר מעשה בהלל הזקן שהביא עולתו לעזרה לסמוך עליה ביו\"ט חברו עליו תלמידי שמאי הזקן אמרו לו מה טיבה של בהמה זו אמר להם נקבה היא ולזבחי שלמים הבאתיה כשכש להם בזנבה והלכו להם","ואותו היום גברה ידם של בית שמאי על בית הלל ובקשו לקבוע הלכה כמותן והיה שם זקן אחד מתלמידי שמאי הזקן ובבא בן בוטא שמו שהיה יודע שהלכה כבית הלל ושלח"],[[0,"ואגלח ממעות מעשר שני","קרבנות שגזר עליו הכתוב ביום תגלחתו אקנה ממעות מעשר שני:"],[0,"נדור","על התודה ואינו יוצא בה ידי חגיגה:"],[0,"נזיר ואינו מגלח","ממעות מעשר אלא מן החולין דכיון דאמר הרי עלי נתחייב דאמירה לגבוה כמסירה להדיוט וכי הדר אמר על מנת לאו מילתא היא:"],[1,"ההוא גברא","מצוה מחמת מיתה היה:"],[3,"להא שמעתא","דהאומר הרי עלי תודה ואצא בה ידי חגיגה:"],[3,"משמיה דנפשיה","ולא אמר לה בלשון בעיא אלא מאליו אמרה האומר הרי עלי תודה ואצא בה ידי חגיגה הריני נזיר ואגלח ממעות מעשר שני נדור ואינו יוצא נזיר ואינו מגלח:"],[3,"אתון הכי מתניתו לה","מאליה ולא משמיה דר' יוחנן:"],[3,"אנן כדבעא מיניה ריש לקיש מר' יוחנן מתנינן לה","דאהדר ליה ר' יוחנן הכי:"],[4,"ויקרב את העולה","עולת יום שמיני של מלואים שהטיל הכתוב על אהרן חובה ליום קח לך עגל בן בקר לחטאת ואיל לעולה תמימים (ויקרא ט׳:ב׳):"],[4,"ויעשה כמשפט","מה משפט האמור בעולת חובה על כרחיך כמשפט המפורש בעולת נדבה בויקרא קאמר שכל משפטי עולה ושלמים שם נאמרו ובשל נדבה דבר הכתוב דכתיב אדם כי יקריב מכם משמע לכשירצה יקריב וכתיב התם וסמך ידו ואתא האי כמשפט דכתיב בעולת חובה ללמד עליה שתטען סמיכה כשאר משפטי נדבה:"],[5,"אמר ליה","ר' יצחק לתנא:"],[5,"דאמר לך מני","הא דאיצטריך קרא להכי ולא גמר לה בבנין אב דמה מצינו בנדבה שהיא עולה וטעונה סמיכה אף חובה שהיא עולה כמותה תטעון סמיכה:"],[5,"ב\"ש היא","דאמר במתניתין מביאין שלמים של י\"ט שהן חובה ואין סומכין עליהן וטעמא מאי משום דסמיכה בויקרא כתיב בשלמי נדבה ואם זבח שלמים קרבנו וסמך ידו וגו' וקא סברי לא גמרינן חובה מנדבה דפרכינן מה לנדבה שכן מצויה בכל שעה שירצה יתנדב ויביא תאמר בחובה שאינה אלא לכשיתחייב הלכך לא דחיא סמיכה דידהו יום טוב הלכך עולת חובה נמי אי לאו דפרט בה קרא כמשפט לא הוה בעיא סמיכה דחובה מנדבה לא גמרי':"],[6,"וממאי דבית הלל כו'","דלמא לעולם חובה מנדבה לא גמרינן אלא בית הלל חובה מחובה גמרי שלמי חובה מעולת חובה הלכך עולת חובה בעיא האי קרא דכמשפט להיות מפורש בה ואי לא לא הוה ידעינן סמיכה לא בעולה ולא בשלמים דחובה והך מתניתא דברי הכל היא:"],[8,"אתיא מבינייא","לעולם מתני' דתני תנא דברי הכל היא ואפי' לב\"ה בעיא קרא ומאחר דקי\"ל סמיכה בעולת חובה מהאי קרא אתו להו שלמי חובה מתרוייהו משלמי נדבה ומעולת חובה במה מצינו בשלמי נדבה שטעונין סמיכה אף שלמי חובה שהן שלמים כמותן יטענו סמיכה וכי פרכת מה לשלמי נדבה שהן מצויין עולת חובה תוכיח שאינה מצויה וטעונה סמיכה אף אני אביא שלמי חובה שאע\"פ שאינן מצויין יטענו סמיכה וכי פרכת מה לעולת חובה שכן כליל תאמר בשלמי חובה שאינם כליל שלמי נדבה יוכיחו וחזר הדין לא ראי זה כראי זה לא ראי עולת חובה כראי שלמי נדבה לתלות טעם הסמיכה בראיה שכן מצוין דהך ראיה בעולת חובה ליתא ולא ראי שלמי נדבה כראי עולת חובה לתלות טעם הסמיכה בראיה שכן כליל דהא ליתא בשלמי נדבה וכתיב בהו סמיכה הצד השווה שבהן על כרחך תתלה טעם סמיכתן בטעם הצד השוה שבשניהם בעולת חובה ובשלמי נדבה הצד השוה שבשניהם שקרבן יחיד הן וטעונין נסכים [וסמיכה] אף אני אביא כל הטעון נסכים והוא קרבן יחיד שיטעון סמיכה ואתו להו שלמי חובה מהאי טעמא:"],[9,"לא נחלקו על הסמיכה","בשלמי חובה שצריך אלא כך היו בית שמאי אומרים סומך עליהן מערב יום טוב ושוחטן ביום טוב ולא אמרינן תכף לסמיכה שחיטה:"],[10,"הוא דאמר כי האי תנא כו' על תכף לסמיכה שחיטה שצריך","בדבר הטעון סמיכה כדכתיב וסמך ושחט:"],[10,"על הסמיכה עצמה","אם טעונין שלמי חובה סמיכה:"],[11,"נקבה היא","שאין עולה נקבה:"],[11,"ולזבחי שלמים הבאתיה","מרוב ענותנותו של הלל היה משנה מפני השלום:"],[11,"כשכש להם בזנבה","כדי להטעותן שיהיו סבורים שהיא נקבה:"]],[[0,"","נזיר ואינו מגלח. ודוקא דקאמר הכי אבל אם אמר אפכא על מנת שאצא משום חגיגה הרי עלי תודה לא וכן בנזיר וכן משמע בסמוך דקאמר דטעמא דאמר הבו ליה ולנסיב כו' וכן פי' בקונט' שפירש טעמא משום דכיון דאמר הרי עלי נתחייב דאמירה לגבוה כמסירתו להדיוט וכי אמר ע\"מ לאו מילתא היא:"],[4,"","ויקרב את העולה וכו'. פירש רש\"י דקאי אעולה של אהרן שנאמר בפ' שמיני ולא נהירא דהא קאי אעולת צבור דהכתיב שעיר העם ומיד אח\"כ כתיב ויקרב את העולה ועולה של אהרן מפורשת בפסוק אחר בפרשה לכך נראה דאין הכי נמי דקאי אעולה של צבור:"],[4,"","למד על עולת חובה שטעונה סמיכה. ותימה דאמר התם דאין טעונין סמיכה בקרבנות צבור אלא בשתי קרבנות וזו אינה מן המנין אלא (. פר) של ע\"ז ופר של העלם דבר ולפי' רש\"י דפירש דהכא מיירי בקרבן של אהרן שהוא קרבן יחיד ניחא וי\"ל דהא דקאמר דאין צריכין סמיכה אלא בב' קרבנות היינו דוקא בקרבנות שהן לדורות אבל הכא מיירי בקרבן המלואים שהיה לפי שעה ומ\"מ קשה דהיכי ילפינן דורות משעה דקא למד על עולת חובה שטעונה סמיכה ועוד היכי ילפינן יחיד מצבור דהא פי' דקרא דויעשה כמשפט מיירי בקרבן צבור ולפי' רש\"י ניחא ועוד י\"ל שנויא השוה לשניהם הואיל וגלה לנו קרא דויקרב את העולה וגו' דילפינן שעה מדורות וקרבן צבור מקרבן יחיד דכתיב אדם כי יקריב לדורות וה\"ה דלילפי דורות משעה ויחיד מצבור ועוד אמר הר\"מ דיש לישב פי' רש\"י ולעולם פשטיה דקרא דויקרב העולה מיירי בקרבן צבור ואי קשיא הא אינה טעונה סמיכה כדקאמר ב' סמיכות בצבור י\"ל דאין ה\"נ אלא אם אינו ענין לקרבנות צבור דהא קי\"ל דאין טעונין סמיכה אלא בשתי קרבנות צבור וזו אינה מן המנין תנהו ענין לקרבנות אהרן שהוא קרבן יחיד:"],[5,"","דלא גמרי שלמי חובה כו'. השתא אית ליה לרבי יצחק בר אבא דטעמא דב\"ש דאמרי אין סומכין היינו משום דאין טעונין סמיכה ולא כרבי יוסי דקאמר בסמוך דפליגי בתכף כו' ורש\"י פי' במתני' טעמא משום שבות שמשתמש בבעלי חיים ויפה פי' דבפ' אין דורשין (חגיגה דף טז:) משמע דבהכי פליגי לרבי יוחנן:"],[6,"","דלמא מעולת חובה גמרי. ואם תאמר והא הוי דבר הבא מן ההיקש דעולת חובה לא ידעינן אלא מנדבה דכמשפט ודבר הלמד בהיקש אינו חוזר ומלמד בבנין אב וי\"ל דבעיא היא בזבחים (דף נ.) אם חוזר ומלמד בבנין אב ואם לאו והכא קאמר אם תמצי לומר חוזרין ומלמדין בבנין אב דבר הלמד בהיקש מעולת חובה גמירי לה דחובה מחובה ילפינן:"]]],[["והביא כל צאן קדר שבירושלים והעמידן בעזרה ואמר כל מי שרוצה לסמוך יבא ויסמוך ואותו היום גברה ידן של בית הלל וקבעו הלכה כמותן ולא היה שם אדם שערער בדבר כלום:","שוב מעשה בתלמיד אחד מתלמידי ב\"ה שהביא עולתו לעזרה לסמוך עליה מצאו תלמיד אחד מתלמידי ב\"ש אמר לו מה זו סמיכה אמר לו מה זו שתיקה שתקו בנזיפה והלך לו","אמר אביי הלכך האי צורבא מרבנן דאמר ליה חבריה מלתא לא להדר ליה מלתא טפי ממאי דאמר ליה חבריה דאיהו אמר ליה מה זו סמיכה וקא מהדר ליה מה זו שתיקה:","תניא אמרו להם בית הלל לבית שמאי ומה במקום שאסור להדיוט מותר לגבוה מקום שמותר להדיוט אינו דין שמותר לגבוה אמרו להם בית שמאי נדרים ונדבות יוכיחו שמותר להדיוט ואסור לגבוה","אמרו להם בית הלל מה לנדרים ונדבות שאין קבוע להם זמן תאמר בעולת ראייה שקבוע לה ' זמן אמרו להם בית שמאי אף זו אין קבוע לה זמן דתנן מי שלא חג ביום טוב ראשון של חג חוגג והולך כל הרגל כולו ויום טוב האחרון של חג","אמרו להם בית הלל אף זו קבוע לה זמן דתנן עבר הרגל ולא חג אינו חייב באחריותו","אמרו להם בית שמאי והלא כבר נאמר לכם ולא לגבוה אמרו להם בית הלל והלא כבר נאמר לה' כל דלה' אם כן מה תלמוד לומר לכם לכם ולא לכותים לכם ולא לכלבים:","אבא שאול אומרה בלשון אחרת ומה במקום שכירתך סתומה כירת רבך פתוחה במקום שכירתך פתוחה אינו דין שכירת רבך פתוחה וכן בדין שלא יהא שולחנך מלא ושולחן רבך ריקן","במאי קא מפלגי מר סבר נדרים ונדבות קרבין ביום טוב ומר סבר אין קרבין ביום טוב","אמר רב הונא לדברי האומר נדרים ונדבות אין קרבין ביום טוב לא תימא מדאורייתא מחזא חזו ורבנן הוא דגזרי בהו גזירה שמא ישהה","אלא אפילו מדאורייתא נמי לא חזו דהא שתי הלחם דחובת היום נינהו וליכא למגזר שמא ישהה ואינו דוחה לא את השבת ולא את יו\"ט:","איבעיא להו לדברי האומר נדרים ונדבות אין קרבין בי\"ט עבר ושחט מאי רבא אמר זורק את הדם על מנת להתיר בשר באכילה רבה בר רב הונא אמר זורק את הדם על מנת להקטיר אימורין לערב","מאי בינייהו איכא בינייהו נטמא בשר או שאבד לרבא לא זריק לרבה בר רב הונא זריק","מיתיבי כבשי עצרת ששחטן שלא לשמן או ששחטן בין לפני זמנן בין לאחר זמנן הדם יזרק והבשר יאכל ואם היתה שבת לא יזרוק ואם זרק"],[[0,"צאן קדר","מעולים היו:"],[1,"שוב מעשה כו'","לאחר המעשה הזה היה מעשה בתלמיד אחד כו':"],[1,"מה זו סמיכה","שאתה רוצה לסמוך ולעבור על דברי ב\"ש והלא אנו חלוקין עליכם:"],[1,"אמר לו מה זו שתיקה","שהיה לך לשתוק ואינך שותק:"],[1,"שתקו בנזיפה","בגערה:"],[3,"מקום שאסור להדיוט","שבת שאסור לעשות להדיוט כלום מותר לגבוה תמידין ומוספין:"],[3,"מקום שמותר להדיוט","י\"ט דכתיב (שמות יב) הוא לבדו יעשה לכם כל צד צרכי אכילה:"],[3,"אינו דין שמותר לגבוה","כל צרכי אכילת מזבח ואפילו עולת ראייה:"],[3,"נדרים ונדבות יוכיחו","שיו\"ט מקום המותר להדיוט הוא ואתם מודים לנו שאסורים להקריב והן צרכי גבוה:"],[5,"אף זו קבוע לה זמן כו'","ויש לחוש שמא יפשע או יאנס בשאר ימי המועד ולא יביא:"],[6,"והלא כבר נאמר לה'","וחגותם אותו חג לה':"],[7,"אומרה בלשון אחרת","להאי קל וחומר דבית הלל דלעיל:"],[7,"כירה","יש לה בית קבול לקבל שתי קדרות ושייך למימר בה סתומה ופתוחה:"],[8,"במאי קמפלגי","אבא שאול ותנא קמא אבא שאול דלא אמר אמרו להם בית שמאי נדרים ונדבות יוכיחו סבירא ליה נדרים ונדבות קרבין לבית הלל:"],[9,"לא תימא מדאורייתא מחזא חזו","דלה' משמע כל דלה' אפילו נדרים ונדבות:"],[9,"שמא ישהה","עד המועד שיהא לו בשר מצוי ברגל ושמא כשיבא המועד יארע לו אונס ונמצא מאחר נדרו:"],[10,"מדאורייתא נמי","סבירא ליה דאסור דכי כתיב לה' דומיא דוחגותם קאמר עולות הדומות לחגיגה זמן קבוע ברגל כמותה:"],[10,"דהא שתי הלחם","דעצרת דחובת היום הן ואינן ראויין לבא קודם לכן דלגזר בהו שמא ישהה הואיל ויכול לאפותן מערב י\"ט אמור רבנן במסכת מנחות (דף צה:) דאין דוחין לא שבת כו' באפייתן דלאו דומיא דחגיגה הוא שזמן שחיטתה קבוע ברגל ואינו יכול להקדים ולאחר:"],[11,"עבר ושחט מאי","מהו שיזרוק את הדם:"],[11,"על מנת להתיר בשר באכילה","כלומר אם הבשר קיים שתהא זריקתו צורך יו\"ט שיאכל הבשר היום זורק ואם לאו אינו זורק:"],[11,"על מנת להקטיר אימורין לערב","אפילו אין כאן אלא לצורך הכשר קרבן להכשיר קרבן שאין יכול לזרוק בלילה והקטרת האימורין כשרה כל הלילה וימתין עד שתחשך ויקטירה:"],[12,"לרבא לא זריק","אף על גב דלאו מלאכה היא גזור בה משום שבות:"],[13,"כבשי עצרת","הבאים עם שתי הלחם כדכתיב בפרשת שור או כשב בעצרת ועשיתם שעיר עזים אחד לחטאת ושני כבשים וגו' (ויקרא כג):"],[13,"שלא לשמן","שצריך לשחטן לשם שלמי צבור ושחטן לשם עולה:"],[13,"לפני זמנן","קודם עצרת והם הופרשו לשם כבשי עצרת:"],[13,"הדם יזרק והבשר יאכל","דקיימא לן כל הזבחים שנזבחו שלא לשמן כשרים ליקרב ונאכלין אלא שלא עלו לבעלים לשם חובה:"],[13,"ואם היתה שבת לא יזרוק","שהרי אסור לבשל ולצלות היום ולא יאכל מן הבשר:"],[13,"ואם זרק","ולא נמלך:"]],[[0,"","והביא כל צאן קדר בעזרה. ותימה הא אין מביאין חולין בעזרה ויש לומר דלאו דוקא בעזרה אלא בהר הבית:"],[3,"","נדרים ונדבות יוכיחו. פ\"ה שמותר להדיוט במקום שמותרים להדיוט לעשות כל צרכו כגון ביום טוב אסורין ליקרב לגבוה אפילו שלמים וכל שכן עולות במאי קא מפלגי מר סבר נדרים ונדבות אין קרבין פרש\"י ת\"ק דאמר נדרים ונדבות יוכיחו ומר סבר אבא שאול נדרים ונדבות קרבין בי\"ט מדלא קאמר נדרים ונדבות יוכיחו והר\"ר שמואל היה מפרש פירוש אחר נדרים ונדבות יוכיחו במקום שיש חלק להדיוט כגון שלמים ואסורי' לגבוה כגון עולות במאי קמפלגי ת\"ק סבר נדרים ונדבות קרבין ביום טוב מדקאמר במקום שמותר להדיוט כגון שלמים דהוו נדרים ונדבות אלמא דס\"ל לת\"ק דנדרים ונדבות קרבין ביו\"ט ואסורין לגבוה כגון עולה אבל אבא שאול דאמר ומה במקום שכירתך סתומה כו' משמע אפילו דשלמים אלמא דס\"ל דנדרים ונדבות אין קרבין בי\"ט וקשה להאי פי' דבפ' אלו עוברין (פסחים דף מז. ושם) אמר בהדיא וסבר לה כאבא שאול דאמר לכם ולא לנכרים משמע אבל נדרים ונדבות קרבין בי\"ט מדלא מוקי ליה לומר לכם ולא לגבוה אלמא דסבירא ליה לאבא שאול דנדרים ונדבות קרבין בי\"ט לכ\"נ כפי' ראשון:"],[6,"","לכם ולא לנכרים. ב\"ה נמי דרשי לכם ולא לגבוה למעוטי נדרים ונדבות כדפי' בפ\"ק (דף יב. בד\"ה השוחט) אלא נקט כותים וכלבים דפסיקא ליה:"],[7,"","שכירתך פתוחה. פ\"ה לשון כירה ממש ונראה דר\"ל כמו ויכרה להם כירה גדולה (מלכים ב ו׳:כ״ג):"],[12,"","מאי בינייהו כגון שנטמא. וא\"ת נימא דאיכא בינייהו כגון שנטמאו אימורים או שנאבדו דלרבא זריק הואיל ואיכא בשר ולרבה בר רב הונא לא זריק כיון שנטמאו האימורין ותי' הר\"ר שמשון מקוצ\"י דרבה בר רב הונא מודה להא דרבא דזורק את הדם על מנת להתיר באכילה דהוי צורך אוכל נפש ושמחת יום טוב אבל הוא מוסיף עליה דקאמר אפילו נטמא בשר זורק את הדם ע\"מ להקטיר אימורין לערב אבל קשה היאך יהא הבשר מותר באכילה הא אמר. התם אימורין כל כמה דלא מקטרי בשר לא מתאכיל דהא דהקטרת אימורין לא מעכבא ה\"מ היכא דליתנהו שנטמאו או נאבדו אבל היכא דאיתנהו מעכבי ויש מתרצים דהכא מיירי שנטמאו או נאבדו ולא נהירא דאם כן לימא דאיכא בינייהו דהכל קיים דלרבא לא זרק ולרבה זריק ועוד דבסמוך משמע אע\"ג דאיתנהו דקאמר כבשי עצרת וכו' הדם יזרק והבשר יאכל ואם היתה שבת לא יזרוק ואם זרק הורצה ע\"מ להקטיר וכו' אלמא דמיירי דאיתנהו ואעפ\"כ בי\"ט הדם יזרק והבשר יאכל וי\"ל דהכא הואיל ואין יכול להקטיר האימורין מבעוד יום הוי כאילו נאבדו או נטמאו:"]]],[["הורצה על מנת להקטיר אימורין לערב אם זרק דיעבד אין לכתחלה לא בשלמא לרבא ניחא אלא לרבה בר רב הונא קשיא קשיא ואיבעית אימא שאני שבות שבת משבות י\"ט:","בעא מניה רב אויא סבא מרב הונא בהמה חציה של נכרי וחציה של ישראל מהו לשחטה בי\"ט אמר ליה מותר אמר ליה וכי מה בין זה לנדרים ונדבות אמר ליה עורבא פרח","כי נפק אמר ליה רבה בריה לאו היינו רב אויא סבא דמשתבח ליה מר בגויה דגברא רבה הוא אמר ליה ומה אעביד ליה אני היום (שיר השירים ב, ה) סמכוני באשישות רפדוני בתפוחים ובעא מינאי מלתא דבעיא טעמא","וטעמא מאי בהמה חציה של נכרי וחציה של ישראל מותר לשחטה בי\"ט דאי אפשר לכזית בשר בלא שחיטה אבל נדרים ונדבות אסור לשחטן בי\"ט דכהנים כי קא זכו משלחן גבוה קא זכו:","אמר רב חסדא בהמה חציה של נכרי וחציה של ישראל מותר לשחטה ביום טוב דאי אפשר לכזית בשר בלא שחיטה עיסה חציה של נכרי וחציה של ישראל אסור לאפותה בי\"ט דהא אפשר ליה למפלגה בלישה","מתיב רב חנא בר חנילאי עיסת כלבים בזמן שהרועין אוכלין ממנה חייבת בחלה ומערבין בה ומשתתפין בה ומברכין עליה ומזמנין עליה ונאפת בי\"ט ואדם יוצא בה ידי חובתו בפסח","ואמאי והא אפשר ליה למפלגה בלישה שאני עיסת כלבים הואיל ואפשר לפייסן בנבלה","ומי אית ליה לרב חסדא הואיל והא אתמר האופה מי\"ט לחול רב חסדא אמר לוקה רבה אמר אינו לוקה","רב חסדא אמר לוקה לא אמרינן הואיל ומקלעי ליה אורחים חזי ליה השתא נמי חזי ליה רבה אמר אינו לוקה אמרי' הואיל","אלא לא תימא הואיל ואפשר אלא כגון דאית ליה נבלה דודאי אפשר לפייסן בנבלה:","בעו מניה מרב הונא הני בני באגא דרמו עלייהו קמחא דבני חילא מהו לאפותה בי\"ט אמר (ליה) חזינא אי יהבי ליה רפתא לינוקא ולא קפדי כל חדא וחדא חזיא לינוקא ושרי ואי לאו אסור","והתניא מעשה בשמעון התימני שלא בא אמש לבית המדרש בשחרית מצאו [ר'] יהודה בן בבא אמר לו מפני מה לא באת אמש לבית המדרש אמר לו בלשת באה לעירנו ובקשה לחטוף את כל העיר ושחטנו להם עגל והאכלנום ופטרנום לשלום","אמר לו תמה אני אם לא יצא שכרכם בהפסדכם שהרי אמרה תורה לכם ולא לעובדי כוכבים ואמאי הא חזי למיכל מיניה","אמר רב יוסף עגל טרפה הואי והא חזי לכלבים","תנאי היא דתניא (שמות יב, טז) אך אשר יאכל לכל נפש הוא לבדו יעשה לכם ממשמע שנאמר לכל נפש שומע אני אפילו נפש בהמה במשמע כענין שנאמר (ויקרא כד, יח) ומכה נפש בהמה ישלמנה תלמוד לומר לכם"],[[0,"הורצה על מנת להקטיר כו'","כלומר ויקטיר אימורין לערב ולא יקטירם היום:"],[0,"לכתחלה לא","הואיל ולא יאכל בשר היום:"],[0,"שאני שבות שבת","החמירו חכמים בדבריהם בשבת מביום טוב:"],[1,"מה בין זה לנדר ונדבה","שחצין לו וחצין לגבוה ואסור לשוחטן מפני חלק גבוה:"],[1,"עורבא פרח","עורב הפורח למעלה השיאו לדבר אחר:"],[2,"כי נפק","רב אויא:"],[2,"אמר ליה רבה בריה","דרב הונא לאבוה:"],[2,"לאו היינו כו'","ולמה דחיתו והלך לו בכלימה:"],[2,"אני היום סמכוני באשישות","יו\"ט הוא ודרשתי לרבים וחליתי מטורח הדרשה וקורא אני עלי סמכוני באשישות הביאו לי סעודה ואסעוד:"],[2,"דבעיא טעמא","וצריך אני להרהר ולעיין בה:"],[3,"וטעמא מאי","סוגיא דגמרא הוא:"],[3,"כהנים משלחן גבוה קא זכו","בחזה ושוק וה\"ה לבעלים בשאר הבשר כעבד הנוטל פרס מבית רבו נמצאת כל השחיטה לשם גבוה:"],[5,"חייבת בחלה","דלחם קרינא ביה:"],[5,"ומערבין בה","ערובי חצרות להוציא מבתים לחצר שהבתים רשות לכל יחיד ויחיד והחצר רשות כולן וצריכים ערוב להוציא כל אחד מביתו לחצר:"],[5,"ומשתתפים בה","שתוף קרי במבוי שחצירות הרבה פתוחין לו וכל חצרות שבש\"ס לפני הבתים ויוצאים דרך חצר לרשות הרבים או למבוי:"],[5,"ומברכין עליה","המוציא:"],[5,"ומזמנים עליה","שלשה שאכלו כאחת:"],[5,"ונאפת בי\"ט","משום חלק הרועים:"],[5,"ואדם יוצא בה ידי חובתו בפסח","לילה הראשון של פסח שהוא מצוה לאכול מצה דכתיב בערב תאכלו מצות (שמות י״ב:י״ח) ושאר הימים אם רצה לאכול שאר דברים בלא לחם הרשות בידו:"],[6,"לפייסן בנבלה","ונמצאת כולה נאכלת לאדם:"],[7,"ומי אית ליה הואיל","סוף סוף מפרנס הכלבים ממנה שהרי אין לו נבלה ומשום אסמכתא דהואיל ואילו היה לו נבלה קא שרית ליה:"],[7,"מיו\"ט לחול","לאחר שסעד אפה דהא ודאי לחול הוא:"],[10,"בני באגא","ישראל הדרים בכפרים:"],[10,"דרמו עלייהו קמחא דבני חילא","המלך הטיל עליהם לאפות ולבשל לבני חילו אנשי מלחמתו:"],[10,"כל חדא וחדא כו'","ופליג רב הונא אדרב חסדא דאמר חציה של נכרי וחציה של ישראל אסור לאפותה:"],[11,"התימני","מתמנת היה כדכתיב (שופטים טו) שמשון חתן התימני מתמנת:"],[11,"אמש","כלומר בין הערבים של יו\"ט:"],[11,"בלשת","חיל גדול של גדודי נכרים שמחפשים ובולשין לשלול שלל:"],[12,"יצא שכרכם","שנשתכרתם בממון יצא ואבד בשביל הפסד עונש שתענשו על חילול יו\"ט: ולא לכלבים לא גרסינן:"],[12,"והא חזי למיכל מניה","ולא יקפידו שהרי משלהן היה: היינו דקאמר ליה כו' לא גרס והכי גרס והא חזי לכלבים:"],[14,"תנאי היא","דאיכא תנא דאסר לכלבים:"],[14,"לכל נפש","אך אשר יאכל לכל נפש:"]],[[3,"","אבל נדרים ונדבות כי קא זכו משלחן גבוה קא זכו. כהנים בחזה ושוק והישראל בבשר משלחן גבוה כעבד שנוטל פרס מרבו כן פרש\"י ואפי' לרבי יוסי הגלילי דקאמר קדשים קלים ממון בעלים הן בב\"ק (דף יב:) ואפי' לאחר זריקה קאמר דממון בעלים הם רק במתנות כהונה מ\"מ אותו ממון זכה משלחן גבוה דהא עיקר הקרבן בשביל גבוה והלכך נהי דהוי ממונו לקדש בו את האשה מ\"מ כל העבודות לצורך גבוה הם עושים:"],[4,"","עיסה חציה של נכרי וחציה של ישראל. ואם תאמר והאמר לעיל רבי שמעון בן אלעזר אומר ממלאה אשה תנור פת ואע\"פ שאינה צריכה אלא לפת אחת מפני שהפת נאפית יפה בזמן שהתנור מלא ושרי לאפות בי\"ט אפי' לכתחילה וכי תימא דאתיא לת\"ק והא הלכתא כר' שמעון דמתיר ויש לומר דשאני התם דכל הפת של ישראל שהרשות בידו לאכול כל אחד ואחד או זה או זה ועוד דלמא מקלעי ליה אורחים אבל הכא דחציה של נכרי אסור לאפותה בי\"ט:"],[8,"","הואיל ומקלעי אורחים וכו'. ותימה הא אמר בשבת פרק המצניע (שבת דף צה. ושם) הרודה חלות דבש ביום טוב סופג ארבעים ואמאי לוקה לרבה דאמר הכא הואיל וכו' התם נמי נימא הואיל דמקלעי אורחים וכו' ואין לומר דשאני התם דאפשר לעשותו מעי\"ט דלענין אוכל נפש אין לחלק בין אפשר ללא אפשר כדפרישית בריש מכילתין (דף ג.) גבי רב יוסף דאמר משום פירות הנושרין ויש לומר דמיירי שהדביש הדבש ואינו ראוי לאכילה אלא לכתישה דגמלי א\"נ שתלש חלות דבש סמוך לחשכה ולא היה שהות אפי' באו אורחים לאכלן:"],[10,"","חזינן אי יהבינן לינוקא ולא קפדי כל חדא וחדא וכו'. פרש\"י ופליגא אההיא דלעיל דרב חסדא דקאמר עיסה חציה של נכרי וכו' דאפשר למפלגה בלישה ואומר ר\"י דלא פליגי דשאני עיסה דחציה של נכרי וחציה של ישראל דישראל מצי למפלגה ולאפות חלקו אבל הכא מיירי שהיה הקמח לבני חילא אלא שטורח אפייה הוה רמי אבני באגא הלכך לא היו יכולין ליקח כלל מן הקמח קודם האפייה לאפותו לצורך התינוק אבל אח\"כ שאפו בשביל החיל אז לא קפדי וכן בעגל דבסמוך לא שייך אפשר למפלגיה שנתנו משלהם ומש\"ה אם היו לוקחין ממנו היו מקפידין אם לא ע\"י טורח הבשול כדרך מבשלים שאוכלין מעט מן הבשול להכי פריך אדרב הונא מהכא:"]]],[["לכם ולא לכלבים דברי רבי יוסי הגלילי ר\"ע אומר אפילו נפש בהמה במשמע אם כן מה תלמוד לומר לכם לכם ולא לעובדי כוכבים","ומה ראית לרבות את הכלבים ולהוציא את העובדי כוכבים מרבה אני את הכלבים שמזונותן עליך ומוציא אני את העובדי כוכבים שאין מזונותן עליך:","אמר ליה אביי לרב יוסף ולרבי יוסי הגלילי דאמר לכם ולא לכלבים הני סופלי לחיותא היכי שדינן להו ביום טוב","אמר ליה הואיל וחזו להסקה תינח ביבישתא ברטיבתא מאי איכא למימר אמר ליה חזו להיסק גדול","תינח בי\"ט בשבת מאי איכא למימר מטלטלינן להו אגב ריפתא כדשמואל דאמר שמואל עושה אדם כל צרכו בפת","ופליגא דרבי יהושע בן לוי דאמר רבי יהושע בן לוי מזמנין את הנכרי בשבת ואין מזמנין את הנכרי ביום טוב גזרה שמא ירבה בשבילו","רב אחא בר יעקב אמר אפילו בשבת נמי לא משום שיורי כוסות אי הכי דידן נמי דידן חזו לתרנגולין דידהו נמי חזו לתרנגולין דידהו איסורי הנאה נינהו","ולטלטלינהו אגב כסא מי לא אמר רבא מטלטלין כנונא אגב קטמיה אע\"ג דאיכא עליה שברי עצים","התם לאו איסורי הנאה נינהו הכא איסורי הנאה נינהו:","אמר ליה רב אחא מדפתי לרבינא ולהוי כגרף של רעי אמר ליה וכי עושין גרף של רעי לכתחלה:","אדבריה רבא למר שמואל ודרש מזמנין את הנכרי בשבת ואין מזמנין את הנכרי בי\"ט גזרה שמא ירבה בשבילו: מרימר ומר זוטרא כי הוה מקלע להו נכרי בי\"ט אמרו ליה אי ניחא לך במאי דטריחא לן מוטב ואי לא טרחא יתירא אדעתא דידך לא טרחינן:","\u0001מתני׳\u0002 ב\"ש אומרים לא יחם אדם חמין לרגליו אלא אם כן ראויין לשתיה וב\"ה מתירין עושה אדם מדורה ומתחמם כנגדה:","\u0001גמ׳\u0002 איבעיא להו האי מדורה מאן קתני לה דברי הכל היא ושני להו לבית שמאי בין הנאת כל גופו להנאת אבר אחד או דלמא ב\"ה קתני לה אבל ב\"ש לא שני להו","ת\"ש ב\"ש אומרים לא יעשה אדם מדורה ויתחמם כנגדה וב\"ה מתירין:","\u0001מתני׳\u0002 שלשה דברים רבן גמליאל מחמיר כדברי ב\"ש אין טומנין את החמין לכתחלה ביום טוב ואין זוקפין את המנורה ביום טוב ואין אופין פתין גריצין אלא רקיקין אמר רבן גמליאל מימיהן של בית אבא לא היו אופין פתין גריצין אלא רקיקין אמרו לו מה נעשה לבית אביך שהיו מחמירין על עצמן ומקילין לכל ישראל להיות אופין פתין גריצין וחררין:","\u0001גמ׳\u0002 היכי דמי אי דאנח עירובי תבשילין מאי טעמא דב\"ש ואי דלא אנח עירובי תבשילין מאי טעמא דב\"ה אמר רב הונא לעולם אימא לך שלא הניח עירובי תבשילין וכדי חייו שרו ליה רבנן","ורב הונא לטעמיה דאמר רב הונא מי שלא הניח עירובי תבשילין אופין לו פת אחת ומבשלין לו קדרה אחת"],[[2,"הני סופלי","גרעיני תמרין:"],[2,"היכי שדינן להו","כיון דלאדם לא חזו ומאכל לבהמה לא משתרי אסירי בטלטול:"],[4,"עושה אדם כל צרכו בפת","ומטלטל ע\"י הפת ולא חיישינן לבזיון דאוכלין:"],[5,"ופליגא דרבי יהושע בן לוי","הא דרב הונא דלעיל דאמר אי כי יהבינן רפתא לינוקא כו':"],[6,"שיורי כוסות","של יין ששרה בהן פתו ומטלטלן השמש להצניע הכוס:"],[6,"דידן נמי","הא לא חזו דמאיסי:"],[7,"כנונא","כלי שמשימים בו הגחלים:"],[7,"אגב קטמיה","שהיינו צריכין לאפרו והוכן מע\"ש לכסות רוק או צואה:"],[7,"ואע\"ג דאיכא עליה שברי עצים","דלא חזו מטלטל להו עם כנונא:"],[8,"הכא איסורי הנאה נינהו","ומוקצי טפי:"],[9,"ולהוי כגרף של רעי","שמותר לטלטלו ולפנותו לאשפה מחמת מאוס כדאמרינן בפרק בתרא (דף לו:):"],[9,"וכי עושין גרף של רעי לכתחילה","נהי דכי איתיה קמן מסלקינן ליה אבל לאתויי קמן או למיזל אנן לגביה כי היכי דנמאס עלן ונסלקיה מי שרי:"],[11,"מתני' לא יחם אדם חמין","לרחוץ רגליו אוכל נפש התיר הכתוב ולא להבעיר אור בשביל רחיצה:"],[11,"מדורה","היסק גדול:"],[12,"גמ' הנאת כל גופו","דמיא לאוכל נפש:"],[14,"מתני' ג' דברים כו'","מפ' טעמא בגמרא:"],[14,"אין זוקפין","משמע אם נפלה מנורה של מתכת אין זוקפין ומשיבין אותה:"],[14,"פתין גריצין","ככרות עבים משום טרחא:"],[14,"חררין","שאופים על הגחלים:"]],[[0,"","לכם ולא לכלבים דברי ר' יוסי הגלילי. אומר הר\"ר שמואל מאייבר\"א בשם אחיו הר\"ר משה דהלכה כר' יוסי הגלילי ואף ע\"ג דקיימא לן דהלכה כרבי עקיבא מחברו דהא אשכחנא סתמא דמשנה כותיה במס' חלה (פ\"א מ\"ח) בההיא דמייתי לעיל עיסת כלבים בזמן שהרועים אוכלין ממנה נאפית ביום טוב ודוקא בזמן שהרועים אוכלין ממנה הא לאו הכי לא והכי איתא (בספרי) בהדיא אבל אין הרועים אוכלין ממנה אין אופין אותה בי\"ט:"],[2,"","הני סופלי לחיותא היכי שדינן. ואם תאמר מאי מספקא ליה דאמאי היה לו לאסור אי משום טרחא מהא לא משני מידי דמה בכך משום דחזיא להסקה והאיכא טרחא יתירא ואי בעי לאסרו משום מוקצה דאית להו דמאכל לבהמה מוקצה הוא לא היא דאם כן תיקשי היאך אנו נותנין תבן לבהמה ועוד תנן מטלטלין שער של אפונים הואיל שהוא ראוי למאכל בהמה ועוד דאמר בשר תפוח מטלטלים אותו מפני שהוא ראוי למאכל כלבים ויש לומר דהני גרעיני תמרה אינן ראויין לבהמה אלא על ידי תקון גדול לחתכן ומדרבנן הויא מלאכה ומ\"מ ראויין כמו שהם על ידי הדחק והואיל ואינן ראויין להיות עיקר מאכל בהמה אלא על ידי תקון גדול היכי שדינן להו למאן דדריש לכם ולא לכלבים משום דהויא מלאכה ומשני דמותרין לטלטל ליתנם לחיות מפני דחזו להסקה:"],[4,"","עושה אדם כל צרכו בפת. ותימה דאמר בשבת (דף קמב:) דלא אמרו היתר ככר או תינוק אלא למת בלבד ויש לומר בדבר שיכול לעשות מבעוד יום אמר התם דלא אמר היתר אלא למת בלבד אבל הני סופלי לא היה יכול לעשותם מערב יו\"ט:"],[7,"","כנונא אגב קטמיה אף על גב דאיכא עליה שברי עצים. וא\"ת מאי מייתי מהכא דלמא שאני הכא שיש בו דבר המטלטל כגון קטמא שראוי לכסות בו צואה או רוק אבל בלא קטמא לא שרי משום דהוי בסיס לדבר האסור וא\"כ הכא בכוס שיש בו דבר שאסור לטלטלו לא ויש לומר דה\"נ מדמה שבכל אחד יש בו חדא לטיבותא וחדא לריעותא והכא הכוס שרי לטלטל ומה שיש בתוכו אסור וגבי כנונא יש בתוכו דבר המותר והכנונא עצמו אסור לטלטל דמלאכתו לאיסור וה\"פ כי היכי דמטלטל כנונא אגב קטמא הכי הוה לן לטלטל השיורין עם הכוס ואין נראה דלפום רהיטא משמע דהא דקאמר מטלטלין כנונא אגב קטמיה לאו מכח הקטמא אלא היינו לצורך גופו ולצורך מקומו ולא דמי לכוס ואם כן אף כי הוי מלאכתו לאיסור שרי לטלטל אלא נראה דטיבותא דכוס הוי משום דשיורי כוסות גריעי טפי וראויין להתבטל אגב הכוס כמו שברי עצים אגב קטמא ור\"ת פי' דלא מקרי בסיס לדבר מועט שאינו נקבע כגון שברי עצים ושיורי כוסות ודאמרינן דבעינן קטמא היינו משום שמטלטל שברי עצים תוך הכנונא והיה לו לנערם אבל אי איכא קטמא לא היה יכול לנערם שלא יפול הקטמא וכ\"ש שיורי כוסות אף על גב דליכא היתר עמהן מ\"מ שרו לטלטל אגב כסא לפי שאי אפשר לנערם:"],[11,"","לא יחם אדם חמין אא\"כ ראויין לשתיה. וא\"ת מאיזה טעם שרו ב\"ש ואפילו ראויין לשתיה הא לית להו מתוך וי\"ל דמיירי כגון ששותה ומרבה לרחוץ רגליו והכי איתא בהדיא בירושלמי דלב\"ש צריך לשתות מהן וב\"ה מתירין ודוקא לרגליו אבל לכל גופו מודה דאסור דדבר השוה לכל נפש בעינן וזה אינו ראוי אלא לבני אדם מעונגין אבל ידיו ורגליו שוה לכל נפש:"]]],[["ומדליקין לו את הנר משום רבי יצחק אמרו אף צולין לו דג קטן תניא נמי הכי מי שלא הניח עירובי תבשילין אופין לו פת אחת וטומנין לו קדרה אחת ומדליקין לו את הנר ומחמין לו קיתון אחד ויש אומרים אף צולין לו דג קטן","רבא אמר לעולם שהניח ושאני הטמנה דמוכחא מלתא דאדעתא דשבתא קעביד","איתיביה אביי חנניה אומר בית שמאי אומרים אין אופין אלא אם כן ערב בפת ואין מבשלין אלא א\"כ ערב בתבשיל ואין טומנין אלא אם כן היו לו חמין טמונין מערב יו\"ט הא היו לו חמין טמונין מיהא עביד ואע\"ג דמוכחא מלתא דאדעתא דשבת קעביד","אלא אמר אביי כגון שערב לזה ולא ערב לזה וחנניה היא ואליבא דב\"ש:","ואין זוקפין את המנורה: מאי קא עביד אמר רב חיננא בר ביסנא הכא במנורה של חליות עסקינן דמחזי כבונה דב\"ש סברי יש בנין בכלים וב\"ה סברי אין בנין בכלים ואין סתירה בכלים","עולא איקלע לבי רב יהודה קם שמעיה זקף לה לשרגא איתיביה רב יהודה לעולא הנותן שמן בנר חייב משום מבעיר והמסתפק ממנו חייב משום מכבה א\"ל לאו אדעתאי:","אמר רב קנבא שרי:","בעא מיניה אבא בר מרתא מאביי מהו לכבות את הנר מפני דבר אחר אמר לו אפשר בבית אחר","אין לו בית אחר מאי אפשר לעשות לו מחיצה אין לו לעשות מחיצה מאי אפשר לכפות עליו את הכלי אין לו כלי מאי אמר ליה אסור","איתיביה אין מכבין את הבקעת כדי לחוס עליה ואם בשביל שלא יתעשן הבית או הקדרה מותר אמר ליה ההיא רבי יהודה היא כי קאמינא אנא לרבנן","בעא מיניה אביי מרבה מהו לכבות את הדלקה ביו\"ט היכא דאיכא סכנת נפשות לא קא מבעיא לי דאפילו בשבת שרי כי קמבעיא לי משום אבוד ממון מאי א\"ל אסור","איתיביה אין מכבין את הבקעת כדי לחוס עליה ואם בשביל שלא יתעשן הבית או הקדרה מותר ההיא רבי יהודה היא כי קאמינא אנא לרבנן","בעא מיניה רב אשי מאמימר מהו לכחול את העין ביו\"ט היכא דאיכא סכנה כגון רירא דיצא דמא דמעתא וקדחתא ותחלת אוכלא לא מבעיא לי דאפי' בשבת שרי כי קמבעיא לי סוף אוכלא ופצוחי עינא מאי א\"ל אסור","איתיביה אין מכבין את הבקעת ושני ליה כדשנין","אמימר שרי למכחל עינא מנכרי בשבתא איכא דאמרי אמימר גופיה כחל עינא מנכרי בשבתא אמר ליה רב אשי לאמימר מאי דעתיך דאמר עולא בריה דרב עילאי כל צרכי חולה עושין ע\"י נכרי בשבת ואמר רב המנונא כל דבר שאין בו סכנה אומר לנכרי ועושה","הני מילי היכא דלא מסייע בהדיה אבל מר קא מסייע בהדיה דקא עמיץ ופתח אמר ליה איכא רב זביד דקאי כותך ושניי ליה מסייע אין בו ממש","אמימר שרא למכחל עינא ביו\"ט שני של ראש השנה אמר ליה רב אשי לאמימר והאמר רבא מת ביום טוב ראשון יתעסקו בו עממין ביום טוב שני יתעסקו בו ישראל ואפילו בשני ימים טובים של ראש השנה"],[[3,"גמ' שערב לזה ולא ערב לזה","אפה ובשל מבעוד יום לשם ערוב ולא טמן חמין:"],[4,"במנורה של חליות","וכשנפלה נפרדו חליותיה:"],[4,"יש תורת בנין בכלים","ובונה חייב בכל שהוא:"],[4,"אין תורת בנין בכלים","ואינו חייב אלא אם כן עשה בו מלאכה כגון ממחק או מחתך או אורג או תופר שהן אבות מלאכות לעצמם אבל חזרת חליות שאין בה אלא משום בנין אין בונה אלא בבתים ואהלים:"],[5,"קם שמעיה","דעולא:"],[5,"זקף לשרגא","שהיה רוצה שיסתלק השמן לאחוריו ולא ימשך אחר הפתילה ותכבה:"],[5,"שרגא","נר של חרס קרויזו\"ל בלע\"ז:"],[5,"הנותן שמן בנר","בשבת:"],[5,"המסתפק","הנוטל ממנו ואוכל:"],[5,"חייב משום מכבה","וכבוי בי\"ט לא אשתרי:"],[5,"לאו אדעתאי","עשה השמש מה שעשה:"],[6,"קנבא","למחוט ראש הפתילה שנעשה פחם שקורין מוקיי\"ר בלעז:"],[7,"מפני דבר אחר","לשמש מטתו:"],[8,"לעשות מחיצה","בסדין:"],[9,"בקעת","אישטיל\"א:"],[9,"כדי לחוס עליה","שאין כבוי זה צורך י\"ט ואני שמעתי דהוי ליה סותר ע\"מ לבנות במקומו:"],[9,"מותר","אלמא לצורך יום טוב שיהנה היום שרי:"],[9,"ר' יהודה","דאמר לקמן מכשירי אוכל נפש שרו ודריש יעשה לכם לכל צרכיכם והאי נמי צרכיכם הוא וכן תשמיש ואנא דאסרנא כרבנן דדרשי הוא לבדו:"],[11,"איתיביה כו'","ואין לך עשון בית גדול מן הדלקה וצורך י\"ט הוא לכבותה שלא יצטרך לישב בשרב ובגשמים:"],[12,"למכחל עינא","לשום בו כחול לרפואה:"],[12,"רירא","שעושה ריר ביב\"א והוא שקורין קציד\"ה בלע\"ז שהוא עושה ריר שמגליד תמיד:"],[12,"דיצא","פי' שנוקב כמו מחט כמו דץ ביה מידי (חולין דף צג:):"],[12,"דמא","שנקנ\"ר:"],[12,"דמעתא","מדמעת תמיד:"],[12,"קדחתא","לשון קדחה באפי (דברים ל״ב:כ״ב) שורפת והוא שקורין איתקלפיישו\"ן:"],[12,"תחלת אוכלא","תחלת החולי של כל אלו:"],[12,"דאפילו בשבת שרי","כדאמרינן במסכת ע\"ז (דף כח:) שורייני דעינא באובנתא דלבא תלו:"],[12,"סוף אוכלא ופצוחי עינא","שקרוב להתרפאות הוא ואינו כוחל אלא להגיה מאורו:"],[13,"איתיביה בקעת","שמותר להנאת הגוף שלא יתעשן:"],[13,"כדשנין","רבי יהודה היא דאמר לכל צרכיכם:"],[15,"עמיץ ופתח","סוגר ופותח ריסי עיניו להכניס הכחול:"],[15,"איכא רב זביד","שהיה מקשה לי כמותך:"],[15,"ושניי ליה","ופרקתי לו:"],[15,"מסייע אין בו ממש","מי שאינו עושה מלאכה ממש אלא מסייע מעט כי האי ובלאו הוא מתעבדא אין בו ממש והכי אמר במסכת שבת בהמצניע (שבת דף צג.) גבי זה יכול וזה אינו יכול יכול חייב ושאינו יכול פטור ואע\"ג דקמסייע בהדיה מסייע אין בו ממש:"]],[[0,"","ומדליקין לו נר. מכאן משמע שצריך להזכיר בברכת עירובי ' תבשילין יהא שרי לבשולי ולאפויי ולאדלוקי וכו' ואם בשביל הדלקה לא התנה משמע הכא דיהא אסור להדליק לו רק נר א' מדחזינן דהוצרך להזכיר אדלוקי הנר משמע דאסור למי שלא הניח להדליק לו רק נר אחד:"],[4,"","ובית הלל סברי אין בנין וסתירה בכלים. וא\"ת והא בשבת (דף מו.) במנורה של חליות כ\"ע לא פליגי דאסור וי\"ל דהתם מיירי בשבת והכא מיירי בי\"ט ולא החמירו חכמים הואיל ואין בנין בכלים אי נמי י\"ל דהתם מיירי שכולה של חליות ומפרקין אותה אברים אברים אבל הכא מיירי שאין חסר כאן רק להקימה קצת ואינה בעלת אברים דכולה מחוברת היא:"],[5,"","והמסתפק ממנו חייב משום מכבה. אינו ר\"ל מפני שממהר כבוי דלא הוי אלא גרם כבוי וגרם כבוי ביום טוב שרי אע\"פ שממהר כבויה ובשבת נמי אינו חייב אלא היינו טעמא הואיל דבאותה שעה שהוא מסתפק ממנה מכבה קצת ומכסה אורו דלא יכול לאנהורי כולי האי כי איכא שמן מועט בנר ולכך נראה ככבוי ומכאן יש להתיר קנדיל\"א של שעוה גדולה לחתוך למטה ממנה כיון דבשעה שחותך אותה אינו מכחיש מאור שלה כלל אע\"ג שהוא גורם לגרום כבויה שרי ודוקא לחתוך אותה באור אבל בסכין אסור אליבא דכולי עלמא דאמר לקמן במתני' (ביצה דף לב.) חותכה באור בפי שתי נרות:"],[6,"","קנבא שרי. פי' רש\"י מוקייר בלעז למחוט ראש הפתילה ועושה פחם ולא נהירא דלקמן פרק המביא (ביצה דף לב:) קרי ליה מוחטין את הנר מאי מוחטין עדויי חושכא ולא קאמר הכא כי ההיא לישנא דהתם לכ\"נ דתרי חטויי יש אחד בשעה שדולק והיינו ההוא דלקמן ויש אחד לאחר שכבה שמתקנין אותה כדי שידליק מהר ומסיר הפחם שבראש הפתילה ובכך נוחה כשידליק אותה והיינו ההוא דהכא דשרי:"],[9,"","אין מכבין את הבקעת וכו'. מכאן יש למחות את הנשים שרגילות להסיר הפתילה מתוך השמן כשהיא דולקת ומשימין אותה על הקרקע וכן שלא לכסות את האור ומה שנהגו העולם להדליק הנר מי\"ט לחברו ואין מדקדקין אם הוא לילה ולעיל פירשתי דהוי הכנה ואין י\"ט מכין לחבירו י\"ל דאע\"ג שאינו לילה מ\"מ הוא סמוך לחשיכה ואף באותו יום צורך הוא אותה הדלקה:"],[9,"","ההיא רבי יהודה היא. דאית ליה לכל צרכיכם ואנן עבדינן כרבנן ואם תאמר והא אנן פסקינן לקמן הלכה כר' יהודה וי\"ל דמסיק עליה ואין מורין כן אי נמי י\"ל דהא דשרינן מדרשה דלכם היינו דוקא בדבר שהוא אוכל נפש אבל בדבר שאינו אלא לתשמיש בעלמא וכן שלא תתעשן הקדרה אסור:"]]],[["מה שאין כן בביצה","אמר ליה אנא כנהרדעי סבירא לי דאמרי אף בביצה ומאי דעתיך דלמא מעברי ליה לאלול האמר רב חיננא בר כהנא מימות עזרא ואילך לא מצינו אלול מעובר:","ואין אופין פתין גריצין אלא רקיקין: תנו רבנן ב\"ש אומרים אין אופין פת עבה בפסח וב\"ה מתירין וכמה פת עבה אמר רב הונא טפח שכן מצינו בלחם הפנים טפח","מתקיף לה רב יוסף אם אמרו בזריזין יאמרו בשאינן זריזין אם אמרו בפת עמלה יאמרו בפת שאינה עמלה","אם אמרו בעצים יבשים יאמרו בעצים לחים אם אמרו בתנור חם יאמרו בתנור צונן אם אמרו בתנור של מתכת יאמרו בתנור של חרס","אמר רב ירמיה בר אבא שאלית את רבי ביחוד ומנו רב מאי פת עבה פת מרובה","איכא דאמרי אמר רב ירמיה בר אבא אמר רב שאלית את רבי ביחוד ומנו רבינו הקדוש מאי פת עבה פת מרובה ואמאי קרו ליה פת עבה משום דנפישא בלישה אי נמי באתריה דהאי תנא פת מרובה פת עבה קרו ליה","מכדי משום דקטרח טרחא דלא צריך הוא מאי אריא פסח אפי' בשאר ימים טובים נמי אין הכי נמי ותנא ביו\"ט דפסח קאי תניא נמי הכי ב\"ש אומרים אין אופין פת מרובה ביום טוב וב\"ה מתירין:","\u0001מתני׳\u0002 אף הוא אמר שלשה דברים להקל מכבדין בית המטות ומניחין את המוגמר ביו\"ט ועושין גדי מקולס בלילי פסחים וחכמים אוסרין:","\u0001גמ׳\u0002 אמר רב אסי מחלוקת לגמר אבל להריח דברי הכל מותר","מיתיבי אין מכבדין בית המטות ביום טוב ושל בית רבן גמליאל מכבדין אמר רבי אליעזר בר צדוק פעמים הרבה נכנסתי אחר אבא לבית רבן גמליאל ולא היו מכבדין בית המטות ביום טוב אלא מכבדין אותן מערב יום טוב ופורסין עליהם סדינין למחר כשאורחים נכנסין מסלקין את הסדינין ונמצא הבית מתכבד מאליו אמרו לו אם כן אף בשבת מותר לעשות כן","ואין מניחין את המוגמר ביו\"ט ושל בית רבן גמליאל מניחין אמר רבי אליעזר בר צדוק פעמים הרבה נכנסתי אחר אבא לבית רבן גמליאל ולא היו מניחין את המוגמר ביום טוב אלא מביאין ערדסקאות של ברזל ומעשנין אותן מערב יום טוב ופוקקין נקביהן מערב יום טוב למחר כשאורחים נכנסין פותחין את נקביהן ונמצא הבית מתגמר מאליו","אמרו לו א\"כ אף בשבת מותר לעשות כן","אלא אי אתמר הכי אתמר אמר רב אסי מחלוקת להריח אבל לגמר אסור","איבעיא להו מהו לעשן רב ירמיה בר אבא אמר רב אסור ושמואל אמר מותר רב הונא אמר אסור מפני שמכבה אמר ליה רב נחמן ונימא מר מפני שמבעיר א\"ל תחלתו מכבה וסופו מבעיר","א\"ר יהודה על גבי גחלת אסור"],[[0,"מה שאין כן בביצה","דקדושה אחת הן ולא הקלו בי\"ט שני של ראש השנה אלא לענין מת בלבד:"],[2,"בפסח","קא סלקא דעתך שאינו יכול לשמרה מהחמיץ:"],[2,"וכמה פת עבה","שהתירו בית הלל:"],[2,"שכן מצינו בלחם הפנים","שהוא מצה כדאמרינן בכל המנחות באות מצה (מנחות דף נז.) ועביו טפח כשמו לחם הפנים יש לו פנים ואין פנים פחותין מטפח:"],[3,"בזריזין","של בית גרמו שהיו אומנים וזריזים בדבר:"],[3,"פת עמלה","בריי\"א בלע\"ז שהיה טעון ג' מאות שיפה שפשוף בידו וחמש מאות בעיטה באגרוף שף אחת בועט שתים שף שתים בועט שלש במנחות (דף עו.):"],[4,"עצים יבשים","מט\"ו באב היו פוסקין מלכרות עצים למערכה במסכת תענית (דף לא.) ומעצי לשכת העצים היו אופין ומבשלים כל צרכי מקדש:"],[4,"בתנור חם","שמסיקין אותו בכל יום הן למנחות הן לצלי:"],[4,"מתכת","במס' זבחים (דף צה:) אמרי' תנור של מקדש של מתכת היה משום שתי הלחם ולחם הפנים שאפייתן וקדושתן בתנור הוה ליה כלי שרת וכלי שרת דחרס לא עבדינן:"],[5,"ביחוד","ביני לבינו:"],[6,"ואיכא דאמרי","רב גופיה אמר שאלית את רבי ביחוד:"],[6,"ומנו","רבו דרב רבינו הקדוש לשון אחר ביחוד בברור כדתנן בשקלים (פ\"ו מ\"ב) וידעו ביחוד ששם ארון נגנז:"],[6,"פת מרובה","ולאו משום חמוץ הוא אלא משום דטרח טרחא יתירא למחר וליום אחר:"],[7,"תניא נמי הכי","דבשאר יום טוב נמי נחלקו:"],[7,"וב\"ה מתירין","כדאמרינן שהפת נאפה יפה כשהתנור מלא:"],[8,"מתני' מכבדין בית המטות","בית המסיבה שאוכלין שם שהיו מסובין ואוכלין על גבי המטות:"],[8,"מוגמר","לבונה על גבי גחלים:"],[8,"מקולס","כרעיו ובני מעיו תלויין חוצה לו בצדו כשצולהו והיו עושין זכר למקדש שכתוב בו על כרעיו ועל קרבו ומקולס לשון גבור מזויין שכלי זיינו תלוין לו בצדו כדמתרגמינן וכובע נחשת וקולסא דנחשא (שמואל א י״ז:ה׳):"],[8,"וחכמים אוסרין","בשלשתן בכבוד משום אשוויי גומות ובמוגמר משום דלאו צורך כל נפש הוא ומהאי טעמא אסרינן ליה בכתובות בפרק ראשון (דף ז.) אשר יאכל לכל נפש דבר השוה לכל נפש וזה אינו אלא למפונקים או למי שריחו רע ובגדי מקולס מפני שדומה לקדשים ויאמרו מותר להקדיש ולאכול קדשים בחוץ:"],[9,"גמ' מחלוקת לגמר","כשאסרו חכמים לא אסרו אלא כשמניחו כדי לגמר בו כלים שנותן המחתה עם הלבונה והגחלים תחת הבגדים להכניס בהן ריח דלאו להנאת הגוף הוא אלא להכשיר כלים אבל מניח לבונה על גבי גחלים להריח ריח מותר שהנאת הגוף הוא ולאוכל נפש דמי והשתא למאי דקאמר רב אסי לא הוי טעמא דרבנן משום דבר השוה לכל נפש כדפרישית לעיל אלא משום דלקשוט כלים הוא מכוין ולקמן הדר ביה מחמת קושיא:"],[10,"כשאורחים נכנסין","שהן קרויין לסעודת הנשיא לכבוד יום טוב:"],[11,"ערדסקיאות","אנצינצייר\"ש והם נבובים ומנוקבים:"],[11,"ופוקקין נקביהן","לשמור העשן והריח שלא יצא:"],[12,"אם כן","לא היו חביריו חלוקין עליו דאף בשבת מותר לעשות כן אלא ודאי ביום טוב היו מניחים לפיכך נחלקו עליו מכל מקום גמרינן מינה דלאו לגמר הוה אלא להריח ולכבוד האורחין ואפלוג רבנן עליה למיסר להניחו ביום טוב אליבא דתנא קמא ולר\"א בר צדוק אפי' רבן גמליאל לא התיר ואת אמרת דברי הכל מותר:"],[13,"מחלוקת להריח","התם הוא דשרי רבן גמליאל להניח ביום טוב כדי להריח כתנא קמא דרבי אליעזר בר צדוק ורבנן אסרי דבעינן דבר השוה לכל נפש:"],[14,"מהו לעשן","פירות בעשן בשמים לקלוט טעם הבושם:"],[14,"אסור","דתפנוק יתירא הוא ואין שוה לכל נפש אלא לאיסטניס ובהאי עשן איכא אב מלאכה כדמפרש רב הונא טעמיה דרב מפני שהוא מכבה הגחלים כשנותן אבקת הבשמים עליהן:"],[14,"ושמואל אמר מותר","דאוכל נפש הוא וראוי אף לעניים אלא שאינו מצוי להם ודמי לנזדמן לו צבי בי\"ט כדאמרינן בכתובות (שם):"],[14,"מפני שמכבה","כדפרישית אינו שוה לכל נפש לפיכך אסור לעשות אב מלאכה בשבילה:"],[14,"ונימא מר מפני שמבעיר","הבשמים שגם זה אב מלאכה:"],[14,"אמר ליה תחילתו מכבה וסופו מבעיר","ותרוייהו הוו ביה ואנא קמא קמא נקטי:"],[15,"על גבי גחלת אסור","דאיכא מכבה ומבעיר:"]],[[6,"","דנפישא בלישה. פירש רש\"י וב\"ה מתירין משום דאמר ר\"ש בן אלעזר. ממלאה אשה תנור פת וכו' ולא נהירא חדא דאם כן ה\"ל לאתויי הא דר' שמעון בן אלעזר כיון דפלוגתייהו בהכי ועוד דלא דמי כלל לפתין גריצין ולמאי אייתינהו הכא לכן נראה לי דפת מרובה. דקאמר היינו פתים גדולים ביותר ועושה לצורך חול הואיל ואין בו טורח כל כך והכי משמע בירושלמי מתוך שאתה מיגעו ממנע ואין עושה אלא כדי צרכו דפת קטן יש בו טורח יותר בעריסת כל אחד ואחד ובין גריצין ובין רקיקין היינו כדי צרכו בלבד וגם הן שוין בעביין אלא דגריצין היינו גדולות ורקיקין קטנות והא דקאמר בסמוך משום דקא טרח טרחא דלא צריך הכי קאמר מתוך שעושה ככרות גדולות אתי למעבד יותר מצורך י\"ט: [ועי' תוספות פסחים לז. ד\"ה וב\"ה]:"]]],[["על גבי חרס מותר","ורבה אמר על גבי חרס נמי אסור משום דקא מוליד ריחא רבה ורב יוסף דאמרי תרוייהו סחופי כסא אשיראי ביומא טבא אסור מ\"ט משום דקמוליד ריחא","ומ\"ש ממוללו ומריח בו וקוטמו ומריח בו התם ריחא מיהא איתא ואוסופי הוא דקא מוסיף ריחא הכא אולודי הוא דקמוליד ריחא רבא אמר על גבי גחלת נמי מותר מידי דהוה אבשרא אגומרי","דרש רב גביהא מבי כתיל אפתחא דבי ריש גלותא קטורא שרי א\"ל אמימר מאי קטורא אי קטורא בידי מעשה אומן הוא ואי לעשן אסור דהא קא מכבה אמר ליה רב אשי לעולם לעשן מידי דהוה אבשרא אגומרי","איכא דאמרי א\"ל אמימר מאי קטורא אי קטורא בידי מעשה אומן הוא אי לעשן אסור דקא מוליד ריחא אמר רב אשי אנא אמריתה נהליה ומשמיה דגברא רבה אמריתה נהליה לעולם לעשן ומידי דהוה אבשרא אגומרי:","ועושין גדי מקולס: תניא רבי יוסי אומר תודוס איש רומי הנהיג את בני רומי לאכול גדי מקולס בלילי פסחים שלחו ליה אלמלא תודוס אתה גוזרנו עליך נדוי שאתה מאכיל את בני ישראל קדשים בחוץ","קדשים סלקא דעתך אלא אימא כעין קדשים:","\u0001מתני׳\u0002 שלשה דברים רבי אלעזר בן עזריה מתיר וחכמים אוסרים פרתו יוצאה ברצועה שבין קרניה","ומקרדין את הבהמה ביו\"ט ושוחקין את הפלפלין ברחים שלהן","רבי יהודה אומר אין מקרדין את הבהמה ביום טוב מפני שעושה חבורה אבל מקרצפין וחכמים אומרים אין מקרדין אף לא מקרצפין:","\u0001גמ׳\u0002 למימרא דר' אלעזר בן עזריה חדא פרה הויא ליה והאמר רב ואמרי לה אמר רב יהודה אמר רב תליסר אלפי עגלי הוה מעשר רבי אלעזר בן עזריה מעדריה כל שתא ושתא תנא לא שלו היתה אלא של שכנתו היתה ומתוך שלא מיחה בה נקראת על שמו:","ומקרדין את הבהמה ביו\"ט: תנו רבנן איזהו קרוד ואיזהו קרצוף קרוד קטנים ועושין חבורה קרצוף גדולים ואין עושין חבורה","וג' מחלוקות בדבר רבי יהודה סבר דבר שאינו מתכוין אסור מיהו קרוד קטנים ועושין חבורה קרצוף גדולים ואין עושין חבורה ולא גזרינן קרצוף אטו קרוד","ורבנן סברי נמי כר' יהודה דבר שאינו מתכוין אסור וגזרינן קרצוף אטו קרוד ור' אלעזר בן עזריה סבר לה כר' שמעון דאמר דבר שאינו מתכוין מותר ובין קרוד ובין קרצוף שרי","אמר רבא אמר רב נחמן אמר שמואל ואמרי לה אמר רב נחמן לחודיה הלכה כר' שמעון שהרי רבי אלעזר בן עזריה מודה לו אמר ליה רבא לרב נחמן ולימא מר הלכה כר' יהודה שהרי חכמים מודים לו א\"ל אנא כר' שמעון ס\"ל ועוד שהרי רבי אלעזר בן עזריה מודה לו:"],[[0,"על גבי חרס","שהסיקו:"],[0,"מותר","דכבוי ליכא והבערה נמי ע\"י שינוי היא כלאחר יד וליכא איסורא דאורייתא:"],[1,"דקמוליד ריחא","שנכנס בחרס שלא היה בו ריח ואסור מדרבנן שהמוליד דבר חדש קרוב הוא לעושה מלאכה חדשה:"],[1,"סחופי כסא אשיראי","לכפות כוס מבושם על השיראים של מלבוש להכניס בהן ריח הבושם שבכוס:"],[1,"אסור","דקא מוליד ריח בשיראים:"],[2,"מאי שנא ממוללו ומריח בו","דתניא (במשילין) גבי עצי בשמים מוללו בין אצבעותיו כדי להוציא ריחו או קוטמו שיהא מקום הקטימה לח ונותן ריח ובתלושין קמיירי:"],[2,"רבא אמר על גבי גחלת נמי מותר","כשמואל דאוכל נפש הוא עשון פירות זה ושוה לכל נפש ואי משום כבוי והבערה ואולודי ריחא מידי דהוה אבשרא אגומרי דאיכא כל הני ושרי:"],[3,"קטורא שרי","כן דרש להם ולא פירש דבריו:"],[3,"אי קטורא בידי","שעושין לבתי שוקים ולבתי ידים של חלוקי הנשים שמקמטין אותן על עץ חלק או על אגודה של קשים וקורין אופרונציי\"ר מעשה אומן הוא ואסיר וקטורא לשון קשר:"],[3,"ואי קטורא","לשון קטור הכבשן דהיינו לעשן:"],[4,"אסור משום דמוליד ריח","והיכי דריש דשר:"],[4,"בשרא אגומרי","מוליד נמי ריח בפחמין:"],[5,"אלמלא תודוס אתה","חכם גדול ונכבד:"],[6,"קדשים סלקא דעתך","מאי קרוב להאכיל קדשים איכא היאך יכולין להיות קדשים ואין אדם מקדישן:"],[6,"אימא כעין קדשים","והכי שלחו ליה שאתה מאכיל את ישראל כעין קדשים והרואה אומר הוקדשו לפסח:"],[7,"מתני' פרתו יוצאה","בשבת:"],[7,"ברצועה שבין קרניה","לנוי ואמור רבנן משאוי הוא ואינו תכשיט לה:"],[8,"ומקרדין","אישטריליי\"ר במגרדת של ברזל ששיניה דקות ואע\"ג דעביד חבורה:"],[8,"ברחים שלהן","כעין אותם שלנו:"],[9,"מקרצפים","במגררת של עץ ששיניה גסות ואין עושה חבורה:"],[12,"גמ' במאי קא מיפלגי","כולה לישנא לא גרסינן וה\"ג ושלש מחלוקות בדבר ר' יהודה סבר דבר שאין מתכוין אסור מיהו קרוד קטנים ועושין חבורה קרצוף גדולי' ואין עושין חבורה ולא גזרינן קרצוף אטו קרוד ורבנן סברי לה כרבי יהודה דאמר דבר שאינו מתכוין אסור וגזרינן קרצוף אטו קרוד ור' אלעזר בן עזריה סבר דבר שאין מתכוין מותר ופירש ר' יהודה סבר חבורה אע\"פ שאין מתכוין לה אסור מיהו הך חששא בקרוד איתא הלכך אין מקרדין אבל בקרצוף ליכא למיחש משום חבורה:"],[13,"ורבנן סברי נמי כר' יהודה דבר שאין מתכוין אסור","ואין מקרדין ומחמירי מיניה דגזרי קרצוף אטו קרוד:"],[13,"ור' אלעזר סבר","הואיל ואין מתכוין לחבורה אף על גב דזמנין דמתרמי שרי הלכך אפי' קרוד שרי:"],[14,"הלכה כר' שמעון","דאמר (שבת כב. מו:) גורר אדם מטה כסא וספסל דדבר שאינו מתכוין מותר:"]],[[0,"","על גבי חרס מותר. פי' רש\"י משום שאין כאן כבוי ואי משום הבערה הוי הבערה כלאחר יד ושרי לעשותה ביום טוב והר\"ר יצחק פירש דשפיר הוי הבערה כדרכה ומ\"מ שריא דקסבר דהבערה שלא לצורך שרי לעשותה ביום טוב וכן משמע בירושלמי [דמשילין] מהו לאדלוקי נר של בטלה ביום טוב ר' יוסי אסר ורבנן שרו והטעם מאן דאסר סבר דהבערה לחלק יצתה והוי מלאכה ואסור לעשותה בי\"ט ומאן דשרי סבר דללאו יצתה והבערה שלא לצורך מותר לעשותה בי\"ט ולא הוי אב מלאכה ומיהו התם קאמר לא תאסור ולא תשרי ומכאן יש ליזהר מלעשות הבערה שלא לצורך כדקאמרינן בירושלמי לא תאסור ולא תשרי ומכל מקום על גבי גחלת אסור לפי שיש כבוי עם הבערה דלכולי עלמא האי לא שרי הואיל דאין זה דבר השוה לכל נפש ואפי' למאן דשרי הבערה שלא לצורך כלל בירושלמי היינו לפי שישנו פעמים לצורך אוכל נפש אבל כבוי דלעולם אינו לצורך תקון אוכל נפש ודאי אסור לכולי עלמא בי\"ט ורבא דשרי אף על גבי גחלת היינו משום דחשיב ליה דבר השוה לכל נפש דאם היו עשירים צריכין הן לכך:"],[10,"","תליסר אלפי עגלי הוה מעשר רבי אלעזר בן עזריה וכו'. ותימה והא ר' אלעזר בן עזריה היה אחר חורבן הבית טובא דהא רבן גמליאל היה נשיא קודם ר' אלעזר בן עזריה ורבן גמליאל היה לאחר חורבן הבית דהא רבן יוחנן בן זכאי היה עושה תקנות מיד לאחר חורבן הבית משום דרבן גמליאל לא הגיעו ימיו להיות נשיא כדאמר משחרב בית המקדש התקין רבן יוחנן בן זכאי ואח\"כ רבן גמליאל ואחר כך ר' אלעזר ור' אלעזר לא היה כי אם בן שמנה עשרה שנה כשהיה נשיא ונשיאותו לאחר חורבן ואמרינן בבכורות (דף נג.) דלאחר חורבן נתבטל כל מעשר בהמה ויש לומר דלא נתבטל לאלתר כי אם לאחר זמן אי נמי אפטרופוס של רבי אלעזר בן עזריה שהיה בימי הבית היה מעשר אי נמי לאו דוקא מעשר אלא שהיה נותן למלך בכל שנה העשירית:"],[12,"","ושלש מחלוקות בדבר מר סבר גזרינן קרצוף וכו'. פירש ר\"י דהלכה כר' שמעון שמתיר ודוקא במגררת של עץ דאין עושה חבורה אבל במגררת שלנו שהן של ברזל כ\"ע מודו דאסור דפסיק רישיה ולא ימות הוא שתולש שערות:"]]],[["\u0001מתני׳\u0002 הרחים של פלפלין טמאה משום שלשה כלים משום כלי קבול ומשום כלי מתכת ומשום כלי כברה:","\u0001גמ׳\u0002 תנא תחתונה משום כלי קבול אמצעית משום כלי כברה עליונה משום כלי מתכת:","\u0001מתני׳\u0002 עגלה של קטן טמאה מדרס ונטלת בשבת ואינה נגררת אלא על גבי כלים","ר' יהודה אומר כל הכלים אין נגררין חוץ מן העגלה מפני שהיא כובשת:","\u0001גמ׳\u0002 עגלה של קטן טמאה מדרס דהא סמיך עלויה ונטלת בשבת משום דאיכא תורת כלי עלה","ואינה נגררת אלא על גבי כלים על גבי כלים אין על גבי קרקע לא מאי טעמא דקא עביד חריץ מני ר' יהודה היא דאמר דבר שאין מתכוין אסור","דאי ר' שמעון האמר דבר שאין מתכוין מותר (דתנן) רבי שמעון אומר גורר אדם מטה כסא וספסל ובלבד שלא יתכוין לעשות חריץ","אימא סיפא ר' יהודה אומר אין הכל נגררין בשבת חוץ מן העגלה מפני שהיא כובשת מפני שכובשת אין אבל חריץ לא עבדא","תרי תנאי ואליבא דרבי יהודה:","\u0001הדרן עלך יום טוב:\u0002","מתני׳ \u0001אין\u0002 צדין דגים מן הביברים ביו\"ט ואין נותנין לפניהם מזונות","אבל צדין חיה ועוף מן הביברין ונותנין לפניהם מזונות","רשב\"ג אומר לא כל הביברין שוין זה הכלל כל"],[[0,"מתני' טמאה משום שלשה כלים","מקבלת טומאה על שם שלשה כלים נפקא מינה דאי נמי אזל חד שמא מינה טמאה משום אידך ובגמרא מפרש לה:"],[1,"גמ' תחתונה","שמקבלת אבק הפלפלין כשנופל דרך נקבי המכבר:"],[1,"משום כלי קבול","שכלי עץ שיש לו בית קבול הוא:"],[1,"אמצעית","שהיא מקפת את המכבר משום כלי עץ לא מטמאה דאין קבולה קבול אלא חכמים גזרו טומאה על הכברה משום ארוג ואפי' אין המכבר של מתכת מטמאה משום כלי כברה ושלנו שהיא של מתכת ודאי טמאה משום פשוטי כלי מתכות:"],[1,"ועליונה","שמכתשין ושוחקין בה הפלפלין טמאה משום כלי מתכות דמשום כלי עץ ליכא לטמויה דפשוטיהן טהורין אלא משום צפוי התחתון שהוא עיקר והעץ בטל אצלו:"],[2,"מתני' עגלה של קטן","שעושין לו לשחוק ויושב עליה ומטלטלין אותו עליה:"],[2,"טמאה מדרס","אם התינוק זב נעשית העגלה אב הטומאה דמיוחדת לישיבה היא דהא סומך קטן עליה נמצאת שהיא מיוחדת לו לישיבה ואין אומרים לו עמוד ונעשה מלאכתנו דאילו לא מיחדא להכי לא הות אב הטומאה כדתניא יכול כפה סאה וישב עליה כו' (שבת דף נט.):"],[2,"ונטלת בשבת","דתורת כלי עליה:"],[2,"ואינה נגררת","בשבת:"],[2,"אלא על גבי כלים","על גבי בגדים מפני שעושה חריץ בקרקע וחופר חייב משום חורש:"],[3,"מפני שכובשת","חריץ הנראה בהלוכה לא על ידי חפירה הוא אלא כובשת ודורסת הקרקע ונדוש תחתיה ונעשה מקומה נמוך אבל אינו זז עפר ממקומה:"],[6,"","גמ' לעשות חריץ גרסינן:"],[7,"כובשת אין","כובשת הוי אבל חריץ לא עבדא:"],[8,"תרי תנאי ואליבא דרבי יהודה","חד סבר העגלה נמי כשאר כלים דעושה חריץ בגרירתה שפעמים שאין האופן מתגלגל והוא נגרר וחופר ואידך סבר לא שכיח הכי ואינה אלא כובשת תחת גלגולה:"],[10,"אין צדין דגים","אף על גב דשחיטה ואפייה ובשול מאבות מלאכות הן והותרו לצורך יום טוב טעמא משום דאי אפשר מערב יום טוב דשחיטה חייש למכמר בשרא פן יתחמם ויסריח אבל צידה אפשר לצודו מבעוד יום ויניחנו במצודתו במים ולא ימות ולמחר יטלהו:"],[10,"ביברים","של דגים הן בריכות של מים שקורין ויביי\"ר ביברין של חיה קרפיפות מוקפין גדר סביב וכונסין לתוכן חיות הבר ויולדות ומגדלות שם:"],[10,"ואין נותנין","לפני הדגים מזונות ואפי' למאן דאמר נפש בהמה במשמע הני מילי דמזונותן עליך אבל דגים אפשר להם בלא מזונות שהם אוכלים שרשי עשבים וקרקע וגדול אוכל את הקטן:"],[11,"אבל צדין חיה ועוף","המכונסים מאתמול קא סלקא דעתך השתא כיון דמוקפים גדר הוו להו כנצודין ועומדין אבל דגים נשמטין לחורים ולסדקים והויא צידה ביום טוב:"],[11,"ונותנין לפניהם מזונות","בימי החורף צריכין מזונות ואף בימי הקיץ במקום דריסת בני אדם שאין עשבים עולים בו:"]],[[0,"","מתני' משום שלשה כלים. פי' ואם נטמא זה לא נטמא זה אפי' בשעת מלאכה שהן כולן יחד הואיל וכל אחד ראוי למלאכה בלבדו ולא דמי למספרים של פרקים ואזמל של רהיטני דהתם הם מחוברים יותר בשעת מלאכה:"],[1,"","משום כלי כברה. פירש רש\"י אע\"ג שהיא של עץ ואין לה בית קיבול שאין נשאר בה כלל מכל מקום גזרו עליה משום ארוג ולא נראה דלא שייך ארוג במעשה של עץ כי אם [בצמר ופשתים ונראה לפרש] בכברה של סלתות דקאמר בירושלמי כברות של סלתות טמאה משום שיש עליה תורת כלי שמקבלת הסובין שאינן יכולין לצאת דרך נקבים והא דקאמר משום כלי כברה ולא קאמר משום בית קיבול ה\"ק משום תורת קבול כלי כברה דחשיב קבול שלה כדפי':"],[2,"","עגלה של קטן. פירש הקונטרס שהקטן יושב בתוכה ולא נהירא דמאי קא משמע לן פשיטא הא אין לך כלי מיוחד גדול מזה לכך נראה לי דהיינו כלי שעושין לקטנים להתלמד להלוך והיא עומדת על שלשה אופנים ואוחז בה בידיו והיא מתגלגלת לפניו תמיד:"],[10,"","אין צדין דגים מן הביברין וכו'. פירש רש\"י דאע\"ג דאוכל נפש מותר היינו דוקא כגון בשול ואפייה ושחיטה דאי אפשר מערב יום טוב דיותר טוב פת חמה וגם בשול בי\"ט ושחיטה שמא יסריח אבל צידה אפשר לצודו מערב י\"ט ויניחנו במים במצודתו ולא ימות ולא נהירא כדמפרש בריש מכילתין (דף ג. ושם) גבי גזרה שמא יתלוש דאין לחלק באוכל נפש בין אפשר לעשותו מערב יום טוב לאי אפשר אלא דוקא במכשירין יש חלוק לכך נ\"ל כפר\"ח מקינו\"ן שפירש לעיל [ביצה דף ג. סד\"ה גזרה] משום דדמי לקצירה:"],[10,"","ואין נותנין לפניהם מזונות. פירש רש\"י דאין מזונותן עליו דהם אוכלים עשב הנמצא במים וגם פעמים אוכלים עפר וגדולים אוכלים הקטנים ואפילו למאן דשרי מאך אשר יאכל לכל נפש (שמות י״ב:ט״ז) דמשמע אפילו בהמה מכל מקום דגים לא הואיל ואין מזונותן עליך ותימה דבגמרא פריך ורמינהי ביברין של חיה ועוף אין צדין וכו' ומשני כאן בביבר קטן כאן בביבר גדול והשתא תינח מצידה לצידה תרצת שפיר אלא מזונות מאי תרצת דבמתני' אמרי' ונותנין לפניהם מזונות והתם אמרי' אין נותנין לפניהם מזונות לכך נראה לי דהא תליא בהא אי צידה מותרת מותר נמי ליתן לפניהם מזונות והכי פירושו אין צדין דגים מן הביברין וכו' ואין נותנין לפניהם מזונות גזרה שמא יצודם דהא צידה שלהן אין מותרת ביום טוב והשתא כשמתרץ בגמרא מצידה ממזונות נמי ניחא דהא בהא תליא ומכל מקום קשיא דמשמע הכא דהיכא דצידה שלהן אסורה אפילו לזרוק להם מזונות אסור ובפרק מי שהחשיך (שבת דף קנה: ושם) קאמר גבי דברים שאסור ליקח מהן למשדא קמייהו שפיר דמי ויש לומר דהתם מיירי בשבת דחמיר דאוכל נפש אסור ולא שייך למגזר שמא יקח מהן אבל הכא מיירי ביום טוב דאוכל נפש מותר גזרינן דלמא כשיתן להם מזונות שמא יצוד מהם:"]]],[["המחוסר צידה אסור ושאינו מחוסר צידה מותר:","\u0001גמ׳\u0002 ורמינהו ביברין של חיה ושל עופות אין צדין מהם ביום טוב ואין נותנין לפניהם מזונות קשיא חיה אחיה קשיא עופות אעופות","בשלמא חיה אחיה לא קשיא הא ר' יהודה הא רבנן","דתנן ר' יהודה אומר הצד צפור למגדל וצבי לבית חייב לבית הוא דמחייב אבל לביברין לא וחכמים אומרים צפור למגדל וצבי לגנה ולחצר ולביברין","אלא עופות אעופות קשיא וכי תימא הא נמי לא קשיא הא בביבר מקורה הא בביבר שאינו מקורה","והא בית דכביבר מקורה דמי ובין לרבי יהודה ובין לרבנן צפור למגדל אין לבית לא","אמר רבה בר רב הונא הכא בצפור דרור עסקינן שאינה מקבלת מרות דתנא דבי ר' ישמעאל למה נקרא שמה צפור דרור שדרה בבית כבשדה","השתא דאתית להכי חיה אחיה נמי לא קשיא הא בביבר קטן הא בביבר גדול","היכי דמי ביבר קטן היכי דמי ביבר גדול אמר רב אשי כל היכא דרהיט אבתרה ומטי לה בחד שחיא ביבר קטן ואידך ביבר גדול אי נמי כל היכא דאיכא עוקצי עוקצי ביבר גדול ואידך ביבר קטן אי נמי כל היכא דנפלי טולא דכתלי אהדדי ביבר קטן ואידך ביבר גדול:","רשב\"ג אומר לא כל הביברין שוין וכו': אמר רב יוסף אמר רב יהודה אמר שמואל הלכה כרבי שמעון בן גמליאל אמר ליה אביי הלכה מכלל דפליגי","אמר ליה ומאי נפקא לך מינה אמר ליה גמרא גמור זמורתא תהא:","זה הכלל כל המחוסר צידה וכו': היכי דמי מחוסר צידה אמר רב יוסף אמר רב יהודה אמר שמואל כל שאומר הבא מצודה ונצודנו","אמר ליה אביי והא אווזין ותרנגולין שאומרים הבא מצודה ונצודנו ותניא הצד אווזין ותרנגולין ויוני הרדיסאות פטור","אמר רבה בר רב הונא אמר שמואל הללו באין לכלובן לערב והללו אין באין לכלובן לערב","והרי יוני שובך ויוני עלייה דבאין לכלובן לערב ותניא הצד יוני שובך ויוני עלייה וצפרים שקננו בטפיחין בבירות חייב","אלא אמר רבה בר רב הונא אמר שמואל הללו באין לכלובן לערב ומזונותן עליך והללו באין לכלובן לערב ואין מזונותן עליך","רב מרי אמר הני עבידי לרבויי והני לא עבידי לרבויי כולהו נמי עבידי לרבויי לכלובן קאמרינן דעבידי לרבויי:","\u0001מתני׳\u0002 מצודות חיה ועוף ודגים שעשאן מערב יום טוב לא יטול מהן ביום טוב אלא אם כן יודע שנצודו מערב יום טוב ומעשה בנכרי אחד שהביא דגים לרבן גמליאל ואמר מותרין הן אלא שאין רצוני לקבל הימנו:","\u0001גמ׳\u0002 מעשה לסתור חסורי מחסרא והכי קתני ספק מוכן אסור ורבן גמליאל מתיר ומעשה נמי בנכרי אחד שהביא דגים לרבן גמליאל ואמר מותרין הן אלא שאין רצוני לקבל הימנו","אמר רב יהודה אמר שמואל אין הלכה כר\"ג ואיכא דמתני לה אהא דתניא ספק מוכן ר\"ג מתיר ורבי יהושע אוסר אמר רב יהודה אמר שמואל הלכה כר' יהושע ואיכא דמתני לה אהא דתניא"],[[0,"המחוסר צידה","שצריך לצודו:"],[3,"גמ' הצד צפור","מן החוץ עד שהכניסו למגדל עץ שקורין מישטיי\"ר או הצד צבי מן החוץ עד שהכניסו לבית בשבת:"],[3,"חייב","דכיון דהכניס צפור למגדל ונעל לפניו הרי הוא אחוז ועומד ונגמרה צידתו וכן צבי לבית ונעל בפניו אבל צפור שהכניס לבית ונעל בפניו פטור שיוצא לו דרך חלונות ואין כאן צידה או צבי שהכניסו מן החוץ לביבר ונעל לפניו אין זו צידה:"],[3,"וחכמים אומרים צפור למגדל","היא צידתו כאשר אמרת אבל צבי אין צריך עד שיכניסנו לבית דאף לגינה ולחצר ולביבר הוי צידה ומתניתין דקתני צדין מן הביברין ביום טוב רבנן היא דאמרי משנכנס לביבר הוא נצוד ועומד וברייתא ר' יהודה:"],[4,"אלא עופות קשיא","דהא כולהו מודו דאין צידתן אפילו לבית:"],[4,"מקורה","שיש לו גג:"],[6,"הכא","דקתני גבי שבת צפור למגדל ולא לבית:"],[6,"בצפור דרור","שדרה בבית כבשדה שיודעת להשמט בזויות הבית לכל צד ולכך נקראת דרור על שם דירה שדרה בכל מקום:"],[7,"השתא דאתית להכי","דעופות אעופות לא קשו אהדדי ולא דחיקא לאוקומי מתני' בפלוגתא דתנאי חיה אחיה נמי לא תוקמא כתנאי אלא תרוייהו כרבנן ומתניתין בביבר קטן וכן ההיא דשבת וברייתא דקתני אין צדין בביבר גדול ויש לה להשמט ורשב\"ג אף בביבר קטן פליג אם צ\"ל הבא מצודה אי נמי לאו לאפלוגי אתא אלא לפרושי כדלקמן:"],[8,"בחד שחיא","בפעם אחת שהוא שוחה עליו לתפשו אין לו להשמט ממנו:"],[8,"עוקצי עוקצי","זויות:"],[8,"דנפלי טולא דכתלי אהדדי","מרוב קטנו וקצרו:"],[9,"הלכה מכלל דפליגי","רבנן עליה למימר כל הביברין שוין בתמיה והא אוקימנא בביבר קטן משום דנצוד ועומד:"],[10,"מאי נפקא לך מינה","אי אמינא הלכה כ\"ש דאי לא פליגי הלכתא היא:"],[10,"אמר ליה גמרא גמור זמורתא תהא","משל שוטים הוא כמו זבון וזבין תגרא אקרי (ב\"מ דף מ:) כך גמרא גמור אומר לתלמיד שוטה למוד הן אמת הן שבוש ויהא לך לזמר ושיר:"],[11,"הבא מצודה","כלומר שצריך לבקש תחבולות לתפשו והיינו שיעורא דביבר גדול דלעיל ואידך ביבר קטן ורב אשי שערינהו לעיל בחדא שיעורא ורב יוסף בהאי שיעורא:"],[12,"הרדיסאות","על שם מקומם וי\"א ע\"ש הורדוס והן הגדלים בבתים:"],[13,"לכלובן","סל שמקננין בו כמו ככלוב מלא עוף (ירמיהו ה׳:כ״ז) אווזין ותרנגולין באין לערב לכלוב ונוח לתפשן שם הלכך הרי הן כנצודין ועומדים ומותר לצודן אפילו חוץ לכלובן:"],[14,"יוני שובך ויוני עלייה","יוני הבר הן ושטין ואוכלין בחוץ:"],[14,"בטפיחין בבירות","גרס כמין פכין נותנין בחומות הבירות והמגדלים לקנן שם עופות הבר:"],[15,"ומזונותן עליך","הלכך כבהמה הן וחשיבי מזומן:"],[16,"הני עבידי לרבויי","יוני שובך עשויין להשמט ולברוח מפני בני אדם:"],[16,"לכלובן קאמרינן דעבידי לרבויי","פורחין עד קינן וצריך לעלות אחריהן וגם שם נשמטין ממנו ויורדין:"],[17,"מתני' מותרין הן","בגמ' פריך מעשה לסתור:"],[17,"אלא שאין רצוני לקבל הימנו","שאני שונאו:"],[18,"גמ' מעשה לסתור","בתמיה וכי דרך המדברים לומר דבר ומביאין מעשה אחריו להכחיש דבור הראשון:"],[18,"ספק מוכן","כלומר וזו שאמרנו לא יטול מהן מספק דהיינו ספק מוכן וספק מוקצה ואסור לאו דברי הכל היא אלא פלוגתא דרבן גמליאל ור' יהושע היא לקמן בשמעתין מייתינן לה בברייתא:"],[19,"דמתני לה","להא דשמואל דאסר ספק מוכן:"],[19,"אהא","מאן דמתני אמתניתין אמר אין הלכה כר\"ג דלא שייך למימר הלכה כר' יהושע משום דלא תני ליה לדר' יהושע במתניתין:"]],[[8,"","כל היכא דנפלי טולא מן הכתלים. ושיעור היה להם גובה בכתלים של ביברין:"],[11,"","כל שאומר הבא מצודה ונצודנו כו'. וא\"ת והרי אמרינן לעיל שיעור אחר ופ\"ה דאידי ואידי חד שיעורא הוא ודוחק הוא דאם כן אמאי מפרש אותו פעם אחרת והלא פירש לעיל היכי דמי ביבר גדול וכו' לכך נ\"ל דלעיל מיירי בבהמה וחיה והכא מיירי בעופות ואע\"ג דלעיל קאמר הא בביבר מקורה מכל מקום לא פירש שיעור הביבר בכמה לא הוי מחוסר צידה והשתא ניחא דפריך עלה מאווזין ותרנגולין:"],[12,"","ותניא הצד אווזין ותרנגולין ויוני הרדיסאות. וא\"ת והא קיימא לן כל פטורי דשבת פטור אבל אסור מדרבנן ומתניתין נמי מודה דפטור אבל אסור מדרבנן וי\"ל לפי מה שפירשתי במתניתין ניחא דגזרינן מזונות גזירה שמא יבא לצוד מהן דאם כן ע\"כ צריך לומר דאסור מן התורה דאם אינו אסור אלא מדרבנן לא הוה גזרינן ליתן מזונות משום שמא יצודם דהוי גזירה לגזירה אי נמי סמיך אההי\"א דתנן פ' האורג במסכת שבת (דף קו: ושם) דאמר התם ר\"ג מחוסר צידה הצד לתוכו פטור דהא מחוסר צידה [וא\"כ] הצד מתוכו חייב והכי פריך הואיל ואוקמת מחוסר צידה דרוצה לומר כל שאומר הבא מצודה ונצודנו א\"כ היכי קאמרת הכא הצד אווזין ותרנגולין פטור הא שפיר חשיב מחוסר צידה כיון שצריך לומר הבא מצודה ונצודנו ובמחוסר צידה הצד מתוכו חייב והכא הוי הצד מתוכו:"]]],[["שוחטין מן הנגרין ביו\"ט אבל לא מן הרשתות ומן המכמורות רבי שמעון בן אלעזר אומר בא ומצאן מקולקלין מערב יום טוב בידוע שמערב יום טוב נצודו ומותרין בא ומצאן מקולקלין ביום טוב בידוע שביום טוב נצודו ואסורין","הא גופה קשיא אמרת בא ומצאן מקולקלין מערב יום טוב בידוע שמערב יום טוב נצודו טעמא דבא ומצאן מקולקלין הא ספיקא אסורין אימא סיפא בא ומצאן מקולקלין ביום טוב בידוע שביום טוב נצודו טעמא דבא ומצאן מקולקלין הא ספיקא מערב יום טוב נצודו ומותרין","הכי קאמר בא ומצאן מקולקלין מערב יום טוב בידוע שמערב יום טוב נצודו ומותרין הא ספיקא נעשה כמי שנצודו ביום טוב ואסורין","אמר רב יהודה אמר שמואל הלכה כרבי שמעון בן אלעזר:","ואמר מותרין הם: מותרין למאי רב אמר מותרין לקבל ולוי אמר מותרין באכילה","אמר רב לעולם אל ימנע אדם עצמו מבית המדרש אפילו שעה אחת דאנא ולוי הוינן קמיה דרבי כי אמרה להא שמעתא באורתא אמר מותרין באכילה בצפרא אמר מותרין לקבל אנא דהואי בי מדרשא הדרי בי לוי דלא הוה בי מדרשא לא הדר ביה","מיתיבי נכרי שהביא דורון לישראל אפילו דגים המפולמין ופירות בני יומן מותרין בשלמא למ\"ד מותרין לקבל שפיר אלא למאן דאמר מותרין באכילה פירות בני יומן מי שרו באכילה","ולטעמיך פירות בני יומן מי שרו בטלטול אלא בכוורי דאדימי ופירי דכבישי בירקא עסקינן ואמאי קרי להו בני יומן שהן כעין בני יומן","אמר רב פפא הלכתא נכרי שהביא דורון לישראל ביום טוב אם יש מאותו המין במחובר אסור ולערב נמי אסורין בכדי שיעשו","ואם אין מאותו המין במחובר תוך התחום מותר"],[[0,"שוחטין מן הנגרין","שוחטין חיות מן ביברים לפי שנצודים ועומדים ועל שם שעושין שם ניגרי מים וחריצין לשתות החיות שם קרי להו נגרים:"],[0,"אבל לא מן הרשתות","מצא חיה במצודתו ספק נצוד היום ספק נצוד מאתמול:"],[0,"בא מעי\"ט","למקום שהיו פרוסים והן באורך מיל או חצי מיל וכשחיה נופלת בראשו אחד מתוך שמתפרקת ומתנתקת לצאת המצודות מתקלקלות כולן וראשו השני נתק ממקום שנתקע וסימן הוא לו שיש חיה בראש האחר:"],[0,"נתקלקלו ביום טוב","ע\"כ הכי משמע שודאי נתקלקלו בי\"ט וכגון שבדקן משחשכה ולא היו מקולקלין ועכשיו מקולקלין ולהכי פריך הא גופה קשיא:"],[2,"ה\"ג טעמא דבא ומצאן הא ספק אסור הכי קאמר כו'","וכולה חדא מילתא היא בא ומצאן שנתקלקלו מערב יום טוב בידוע שמערב יום טוב נצודו ואם יש לחוש ולומר שנתקלקלו ביום טוב כגון שלא בא ומצאן מאתמול מקולקלין הרי הן כאילו ידוע שביום טוב נצודו:"],[3,"הלכה כר' שמעון","דאמר ספק מוכן אסור והיכא דבא ומצאן מקולקלין מאתמול יש לסמוך דנצודו מבעוד יום:"],[4,"לקבל","בטלטול דכולי האי לא אחמור מספק מוכן דלתסרו בטלטול אבל באכילה לא שרינהו רבן גמליאל:"],[4,"ולוי אמר מותרין באכילה","קאמר רבן גמליאל ולאו דסבירא לרב ולוי כותיה אלא מלתיה הוא דמפרשי:"],[6,"מפולמים","לחים אמ\"י בלע\"ז:"],[6,"מותרין","והא על כרחך רבן גמליאל הוא דמיקל:"],[6,"שפיר","ואע\"ג דלאו ספק הוא אלא ודאי מוקצה איכא למימר דמתיר בטלטולו ולקמן פריך עלה פירות בני יומן בטלטול מי שרי נהי דמיקל רבן גמליאל בספק מוכן בודאי שאינו מוכן מי מיקל:"],[7,"אלא בכוורי דאדימי","אדומים שלא נס ליחן ואדמומית שתחת לחייהן שבודקין אותן שם:"],[7,"ופירי דכבישי בירקי","כשלקטום טמנום מיד בירק שלא יברח לחלוחן כבישי טמונין כמו רישא בכבשא (חולין דף צג:) והני ודאי מוכן נינהו דניכרין שמעי\"ט הן ואשמועינן דאע\"ג דדמו לבני יומן לא חיישינן למראית העין ורבותי פירשו כוורי דאדימי מנותחין הן כמו אדמויי אדמוה (ע\"ז דף לח:) וקשיא לי א\"כ מאי למימרא:"],[8,"אם יש מאותו המין במחובר אסורין","משום מוקצה ואפילו לרבי שמעון יש מוקצה בגרוגרות וצמוקים ומחובר כגרוגרות וצמוקים דמי מדלא לקטן מאתמול אקצינהו מדעתיה ולא תחלוק במחובר בין שלו בין של נכרי:"],[8,"ולערב אסורין בכדי שיעשו","כדי שלא יהנה ממלאכת יו\"ט והא דקאמר ולערב אסורים בכדי שיעשו הא לאחר כן מותרים אפילו לערב ראשון נמי אע\"ג דליל יו\"ט שני הוא ממתין בכדי שיעשו ומותרין ממה נפשך אם הלילה חול הוא הרי המתין בכדי שיעשו ואם קדש הוא נמצא שנלקטו בחול כן דעתי נוטה ויש לי ראיות הרבה מההוא בר טביא דעירובין (דף לט:) ומביצה שנולדה בזה שמותרת בזה (לעיל ביצה דף ד:) אלמא האחד חול הוא וממה נפשך מותר ולא זכיתי לשאול את פי רבי' יעקב בדבר זה כי היו נוהגים בו היתר במקומינו והיה לי דבר פשוט ולאחר פטירתו של רבי שמעתי את רבי' יצחק הלוי שהוא אוסר עד ליל מוצאי יו\"ט שני וכל אנשי עירו כמותו וגם הלכות גדולות אוסרים כן ודנתי לפניו ולא הועיל לי הדבר וכל טעמו אינו אלא מדנקט בכדי שיעשו בלילה הראויה לעשיה קאמר ואני אומר צריך להמתין בכדי שיעשו משום שמא היום היה קדש והלילה חול ותדע מדלא קאמר לערב של שני אסורים בכדי שיעשו לערב הראשון קאמר ובתשובת רבי' גרשום מאור הגולה מצאתי כמותי גם עתה בא אלי מכתב מגרמיי\"ש שבא לשם אדם גדול זקן ויושב בישיבה מן רומא ושמו ר' קלונימוס ובקי בכל הש\"ס והורה כן ונחלק עליהן:"]],[[7,"","אלא בכוורי דאדימי וכו'. דודאי נצודו מערב י\"ט וקרי ליה בני יומן כך פרש\"י ולא נהירא דפשיטא דמותרין לטלטל ואתיא כדברי הכל ומשמע דלא אתיא אלא כרבן גמליאל דמתיר ספק מוכן לכן נראה לי דאין ודאי שהוא מערב י\"ט אלא ספק והשתא אתיא כרבן גמליאל דמתיר ספק מוכן:"],[8,"","ולערב אסורין בכדי שיעשו. פרש\"י כדי שיעור לקיטתן שלא יהנה ממלאכת י\"ט ולערב ראשון קאמר דממה נפשך הן מותרין אם היה חול הרי היום נלקטו ואם היה היום קדש הרי הלילה הזה חול ובשני ימים טובים של גליות מיירי והביא ראיה מביצה דלעיל (ביצה דף ד: ושם) שנולדה בזה מותרת בזה ומההוא טביא דאתציד ביום ראשון ואכלו אותו ביום שני בעירובין (דף לט: ושס) כן פרש\"י ורבינו יצחק הלוי והגאונים אוסרין עד מוצאי ליל יום טוב שני ומפרש בכדי שיעשו לילה הראויה לעשיה ומיהו בתשובת רבינו גרשום מאור הגולה מצאתי כמותי וגם רבינו קלונימוס איש רומי בקי בכל הש\"ס שלח לי כתב מעיר גרמיז\"א כמותי והקשה הר\"י לפרש\"י דפירש דלכך בעינן כדי שיעשו כדי שלא יהנה ממלאכת יום טוב א\"כ המבשל בשבת בשוגג. אמאי יאכל הא נהנה ממלאכת שבת אלא ודאי אין זה הטעם אלא הטעם שמא יאמר לנכרי לך ולקט ומזה הטעם אסורים עד מוצאי י\"ט האחרון בכדי שיעשו דאי אמרת דמותרין במוצאי יום טוב ראשון חיישינן שמא יאמר לנכרי בי\"ט ראשון לך והביא כדי לאכול מהן בשני ואם כן ע\"כ לילה הראויה לעשיה קאמר ומה שהביא רש\"י ראיה מביצה וכו' יש לדחות אותה דהתם נולדה מאליה מן השמים וגם ראיה שהביא מההוא טביא דעירובין (דף לט: ושם) יש לומר דמיירי שהיו המצודות פרוסות מעי\"ט ומאליו נצודו וכללא הכי הוא דדבר הבא מאליו או דבר מוקצה הבא בידים שהביא נכרי בשביל עצמו או בשביל נכרי אחר ונתנן לישראל בי\"ט ראשון מותר בשני אבל אם הביאו בשביל ישראל מן המחובר אסור עד מוצאי יום טוב שני בכדי שיעשו ואם לאו שאין במינו במחובר חוץ לתחום אסורין תוך התחום מותרין ור\"י פירש שאין במינו במחובר הבא מחוץ לתחום לא בעינן כדי שיעשו דלא החמירו אלא בדבר שנעשה בו מלאכה דה\"נ הקילו שמותר לישראל אחר אפילו בו ביום וקשה לרבי' יהודה דאמרינן בפרק שואל (שבת דף קנא: ושם) הביאו חלילים למת מחוץ לתחום לא יספוד בהן עד מוצאי יום טוב ומשמע התם בכדי שיעשו ויש לומר דשאני התם דאוושא טפי מילתא דהכל יודעין שהובאו בשבילו ואיכא למגזר טפי ויש חלוק בין מת לדברים אחרים כדאמר התם עשה קבר לאביו בי\"ט לא יקבור בו עולמית אע\"ג דדברים אחרים מותרים בכדי שיעשו אחר שבת או אחר יו\"ט ואומר הר\"ר שמואל מאייבר\"א דספק חוץ לתחום מותר והביא ראיה מעירובין (דף מה:) גבי מיא בעיבא מיבלע בליעי וכו' וקאמר דהוי ספק אם באו חוץ לתחום וסיפא דברייתא לקולא ורבי יהודה היה אוסר במחובר ובצידה אפי' לא הביאו בשביל ישראל רק בשבילו או בשביל נכרי אחר ולא משמע כן גבי מרחצת בשבת דשרי (שבת דף קבב.) הואיל ואיכא נכרים בעיר ואין סברא לחלק בין דבר אכילה לדבר אחר ואומר הרר\"י די\"ט שחל להיות בה' בשבת ובע\"ש או בא' בשבת ובב' בשבת הבא ביום ראשון שרי ליום שלישי ולא בעינן הראויה לעשיה דשני ימים קודם לא שייך שמא יאמר לנכרי ויש להחמיר בדבר (ובכדי שיעשו דאמר לפי' התוס' כדי שיתלשו ויובאו ממקום שצד אותם גם יש לספק אם הביא קופה מלאה פירות אם צריך להמתין כדי שילקטו באדם אחד או בכמה בני אדם):"]]],[["חוץ לתחום אסור והבא בשביל ישראל זה מותר לישראל אחר","אמר רבה בר רב הונא אמר רב הסוכר אמת המים מערב יום טוב ולמחר השכים ומצא בה דגים מותרין","אמר רב חסדא מדברי רבינו נלמוד חיה שקננה בפרדס אינה צריכה זמון אמר רב נחמן נפל חברין ברברבתא איכא דאמרי אמר רבה בר רב הונא מדברי רבינו נלמוד חיה שקננה בפרדס אינה צריכה זמון אמר רב נחמן נפל בר חברין ברברבתא","התם לא קא עביד מעשה הכא קא עביד מעשה","ולא בעיא זמון והתניא חיה שקננה בפרדס צריכה לזמן וצפור דרור צריך לקשור בכנפיה כדי שלא תתחלף באמה וזו עדות שהעידו מפי שמעיה ואבטליון תיובתא","ומי בעיא זמון והתניא אמר ר\"ש בן אלעזר מודים בית שמאי ובית הלל על שהזמינן בתוך הקן ומצא לפני הקן שאסורין במה דברים אמורים ביוני שובך ויוני עליה וצפרים שקננו בטפיחין ובבירה אבל אווזים ותרנגולים ויוני הרדסיאות וחיה שקננה בפרדס מותרין ואין צריכין זמון וצפור דרור צריכה לקשר בכנפיה כדי שלא תתחלף באמה","והמקושרים והמנוענעין בבורות ובבתים ובשיחין ובמערות מותרין ובאילנות אסורין שמא יעלה ויתלוש והמקושרין והמנוענעין בכל מקום אסורין משום גזל","אמר רב נחמן לא קשיא הא בה הא באמה אמה בזמון סגי לה צידה מעליותא בעיא","אלא אמר ר\"נ בר יצחק אידי ואידי בדידה הא בגנה הסמוכה לעיר הא בגנה שאינה סמוכה:","\u0001מתני׳\u0002 בהמה מסוכנת לא ישחוט אלא אם כן יש שהות ביום לאכול ממנה כזית צלי ר\"ע אומר אפילו כזית חי מבית טביחתה","שחטה בשדה לא יביאנה במוט ובמוטה אבל מביא בידו אברים אברים:","\u0001גמ׳\u0002 אמר רמי בר אבא הפשט ונתוח בעולה והוא הדין לקצבים מכאן למדה תורה דרך ארץ שלא יאכל אדם בשר קודם הפשט ונתוח","(לאפוקי) מאי קמ\"ל אילימא לאפוקי מדרב הונא דאמר רב הונא בהמה בחייה בחזקת איסור עומדת עד שיודע לך במה נשחטה","נשחטה בחזקת היתר עומדת עד שיודע לך במה נטרפה","והאנן תנן מתניתין כדרב הונא דתנן ר\"ע אומר אפילו כזית חי מבית טביחתה מאי לאו מבית טביחתה ממש","לא ממקום שטובחת אכילתה","והא תני רבי חייא מקום טביחתה ממש אלא רמי בר אבא"],[[0,"חוץ לתחום אסורין","לא שמעתי טעם מקובל בדבר דאי משום מוקצה אמאי מותר לישראל אחר ואי משום שנעשה בו איסור בשבילו א\"כ לישראל אחר נמי אסור דנכרי שהדליק את הנר בשבת תנן (שבת דף קכב.) אם בשביל ישראל אסור ולא חלקו בינו לחברו וי\"ל דגבי איסור תחומין דרבנן לא אחמור כולי האי ודיין אם אסרוהו על זה (טעם אחר נראה לי מחוץ לתחום אסורין גזירה שמא ישלח בשבילו והבא בשביל זה מותר לאחר דליכא למגזר בה שאינו מכירו):"],[1,"הסוכר אמת המים","סותמה שלא יכנסו בה דגים מבחוץ משתחשך ואת אלה הכין והזמין על ידי מעשה זה:"],[2,"מדברי רבינו","רב דשלשתן רב הונא ורב חסדא ורב נחמן דקרי ליה לרב חסדא חברין תלמידים של רב הוו:"],[2,"בפרדס","מקום המשתמר ואין הולד יוצא שאינו יכול לברוח וקל לצודו ואינו צריך זמון דהא הכא מפני שהיא סתומה ואין יכולין לצאת קרי להו מוכנים ולקמיה פריך דזמון גדול הוא זה שעושה מעשה לשם הזמנה:"],[2,"נפל חברין","רב חסדא:"],[2,"ברברבתא","נכנס ראשו למחלוקות גדולות שירבו עליו בזאת ולקמיה מסיים קושיא אלא מפסקא מלתא באיכא דאמרי דמחלפי רב חסדא ברבה בר רב הונא:"],[2,"נפל בר חברין","רב הונא חבריה הוה מתלמידיו של רב ורבה בריה קרי בר חברין:"],[4,"וצפור דרור","שזימנה מבעוד יום צריך לקשור בכנפיה להיות סימן לה:"],[5,"ומצא לפני הקן שאסורין","כדמתרצינן לה בפ\"ק (דף י:) שהיו שני קנין וזימן את זו ולא זימן את זו ולמחר בא ומצא במזומנת ולא במקומן אלא בדף הבולט לפני הקן ובחברתה לא מצא כלום שאסורין דחיישינן שמא מקן שאינה מזומנת באו לכאן:"],[5,"במה דברים אמורים","דבעינן זמון:"],[5,"צפור דרור","קטנה היא והאם והבת שוות:"],[6,"והמקושרים","בכנפיהם סימן הוא להם:"],[6,"והמנוענעים","מאתמול לשם זמון והוא מכירן:"],[6,"בבתים ובבורות","ובכל מקום שאינו מחובר:"],[6,"מותרים","בי\"ט:"],[6,"והמקושרים והמנוענעים","הנמצאים בכל מקום אף בחול אסורין למוצאן משום גזל שהראשון שקשרן או נענען קנאן בהגבהתם שהפקר נקנה בהגבהה:"],[7,"בה","בולד אינו צריך זמון שאינה יכולה לברוח ודעתיה עליה אבל אמה שהיא גדולה צריכה זימון:"],[8,"בדידה","בולד:"],[8,"בסמוכה לעיר","ידע בה ודעתיה עלויה:"],[9,"מתני' בהמה מסוכנת","שהוא ירא שתמות ואינו צריך לה שכבר סעד סעודתו אלא מחמת הפסדו הוא שוחט:"],[9,"לא ישחוט אא\"כ","יודע שיש שהות ביום לאכול כזית צלי הימנה:"],[9,"מבית טביחתה","שהוא מזומן ומופשט מעורו ועומד:"],[10,"לא יביאנה במוט ובמוטה","בשני בני אדם משום דאוושא מלתא היא ומזלזל בי\"ט:"],[11,"גמ' הפשט ונתוח","פי' הכתוב בעולה שהיא אכילת גבוה וה\"ה יש ללמוד לקצבים באכילת הדיוט:"],[12,"מאי קמ\"ל","דרך ארץ או איסור ולמימר דאסור לאכול ממנה עד שינתחה שמא ימצא לה סימן טרפה בסתר והחזיק לנו הבהמות בספק טרפות אף קודם שראה בהן טרפות:"],[12,"לאפוקי מדרב הונא דאמר בהמה בחייה בחזקת איסור","אבר מן החי עומדת ונפקא מינה שאם אירע ספק בשחיטתה נעמידנה על חזקתה ואסורה עד שיודע לך ברור שנשחטה כראוי ומשנשחטה כראוי הרי היא בחזקת היתר דסתם בהמות אינן טרפות ואם נמצא בה נקב בריאה או בבני מעים ויש לתלותו לאחר שחיטה ולהכשיר ובקודם שחיטה ולאסור העמידנה על חזקתה שהיתה בה קודם שנמצא בה ספק זה ומותרת עד שיודע לך אמת שהיא טרפה:"],[14,"מבית טביחתה ממש","קודם הפשט:"],[15,"שטובחת אכילתה","מבני מעיה שהמאכל מתחתך ומתעכל שם:"]],[[0,"","הבא בשביל ישראל זה מותר לישראל אחר. תימה מה טעם זה אי הוי מוקצה אפילו לישראל אחר אסור ואי אסור לישראל ראשון בשביל שנעשה בהן איסור בשבילו אם כן לישראל אחר נמי אסורין כדאמרי' (שבת דף קכב.) נכרי שהדליק הנר אם בשביל ישראל אסור וליכא חלוק בין אותו ישראל לישראל אחר ותירץ רש\"י דשמא גבי איסור תחומין דליכא אסורא אלא מדרבנן לא אחמור כולי האי ודי אי אסרינן על זה שהובאו בשבילו:"],[6,"","המקושרין אסורים בכ\"מ מפני גזל. פרש\"י שהראשון קנה אותן בהגבהה ולא נהירא דלא שייך כאן הגבהה אלא כדאמרי' דהבטה קונה בהפקר הואיל ומתעסק הוא בהן קצת:"],[8,"","כאן בשדה הסמוכה וכו'. תימה אמאי לא משני לעיל כן וי\"ל אמורא היה לו לפרש דבריו והואיל ולא פירש מיירי בין בסמוכה וכו':"],[12,"","בחזקת איסור עומדת. פרש\"י בחזקת איסור אבר מן החי ולא נהירא דאם כן למה לי עד שיודע במה נשחטה כיון דחזינא שמתה א\"כ לא שייך בה איסור אבר מן החי דאיסור אבר מן החי לא שייך אלא מחיים לכן נ\"ל דחזקת איסור ר\"ל בחזקת שלא נשחטה עד שיודע לך וכו' ומשום איסור שאינה זבוחה דרחמנא אמר תזבח ואכלת שחוט ואכול ובזה ניחא אפילו למ\"ד בהמה בחייה לאו לאברים עומדת:"]]],[["אורח ארעא קמ\"ל","כדתניא לא יאכל אדם שום ובצל מראשו אלא מעליו ואם אכל ה\"ז רעבתן כיוצא בו לא ישתה אדם כוסו בבת אחת ואם שתה ה\"ז גרגרן תנו רבנן השותה כוסו בבת אחת ה\"ז גרגרן שנים דרך ארץ שלשה מגסי הרוח","ואמר רמי בר אבא חצובא מקטע רגליהון דרשיעיא","נטיעה מקטע רגליהון דקצביא ודבועלי נדות","תורמוסא מקטע רגליהון דשנאיהון של ישראל שנאמר (שופטים י, ו) ויוסיפו בני ישראל לעשות הרע בעיני ה' ויעבדו את הבעלים ואת העשתרות ואת אלהי ארם ואת אלהי צידון ואת אלהי מואב ואת אלהי בני עמון ואת אלהי פלשתים ויעזבו את ה' ולא עבדוהו","ממשמע שנאמר ויעזבו את ה' איני יודע שלא עבדוהו ומה ת\"ל ולא עבדוהו א\"ר אלעזר אמר הקב\"ה אפילו כתורמוס הזה ששולקין אותו שבע פעמים ואוכלין אותו בקנוח סעודה לא עשאוני בני","תנא משמיה דר\"מ מפני מה נתנה תורה לישראל מפני שהן עזין תנא דבי ר' ישמעאל (דברים לג, ב) מימינו אש דת למו אמר הקב\"ה ראויין הללו שתנתן להם דת אש איכא דאמרי דתיהם של אלו אש שאלמלא (לא) נתנה תורה לישראל אין כל אומה ולשון יכולין לעמוד בפניהם","והיינו דאמר ר\"ש בן לקיש ג' עזין הן ישראל באומות כלב בחיות תרנגול בעופות וי\"א אף עז בבהמה דקה וי\"א אף צלף באילנות:","שחטה בשדה לא יביאנה במוט: ת\"ר אין הסומא יוצא במקלו ולא הרועה בתרמילו ואין יוצאין בכסא אחד האיש ואחד האשה","איני והא שלח ר' יעקב בר אידי זקן אחד היה בשכונתינו והיה יוצא בגלודקי שלו ובאו ושאלו את ר' יהושע בן לוי ואמר אם רבים צריכין לו מותר","וסמכו רבותינו על דברי אחי שקיא דאמר אנא אפיקתיה לרב הונא מהיני לשילי ומשילי להיני ואמר ר\"נ בר יצחק אנא אפיקתיה למר שמואל משמשא לטולא ומטולא לשמשא התם כדאמר טעמא אם היו רבים צריכין לו מותר","א\"ל רב נחמן לחמא בר אדא שליח ציון כי סלקת להתם אקיף וזיל אסולמא דצור וזיל לגבי דר' יעקב בר אידי ובעי מיניה כסא מה אתון ביה","אדאזל להתם נח נפשיה דר' יעקב בר אידי כי סליק אשכחיה לרבי זריקא א\"ל כסא מה אתון ביה א\"ל הכי אמר ר' אמי ובלבד שלא יכתף מאי ובלבד שלא יכתף אמר רב יוסף בריה דרבא באלונקי","איני והא רב נחמן שרא לה לילתא למיפק אאלונקי שאני ילתא דבעיתא","אמימר ומר זוטרא מכתפי להו בשבתא דרגלא משום ביעתותא ואמרי לה משום דוחקא דצבורא:","\u0001מתני׳\u0002 בכור שנפל לבור רבי יהודה אומר ירד מומחה ויראה"],[[0,"אורח ארעא","ולא משום איסור טרפה:"],[1,"כדתניא","מצינו אף תנאים שמלמדים הלכות דרך ארץ שלא יראה אדם עצמו על הבריות כרעבתן אף זה הממהר לאכול קודם הפשט נראה כרעבתן:"],[1,"בצל","ציבול\"ה:"],[1,"מעליו","מצד העלין:"],[2,"חצובא מקטע רגליהון דרשיעיא","עשב ששרשיו נוקבין ויורדין בעומק ואין מתפשט לצדדין כלל ונוטעין אותו בין גבולי שדות ובו תיחם יהושע לישראל את הארץ מקטע רגלי הרשעים ליום הדין שגוזלין וחומסים ומשיגין גבול ואין למדין ממנו:"],[3,"נטיעה מקטע רגליהן דקצביא","נטיעת ערלה שאמרה תורה להמתין שלש שנים מלאכול פירות מקטע רגלי הקצבים הממהרין לאכול קודם הפשט ונתוח ופעמים שנמצאת טרפה וכן דבועלי נדות שממהרין ואינם יכולין להמתין עד שתטבול:"],[4,"תורמוס","מין קטנית עגול כמין עדשה ורחב כמעה קטנה והוא מר מאוד עד ששולקין אותו שבע פעמים ונעשה מתוק וטוב עד שיאכל למטעמים בקנוח סעודה:"],[4,"מקטע רגליהון דשונאי ישראל","דכתיבי שבעה ע\"ז בהאי קרא ולבסוף ויעזבו את ה' התורמוס הזה לאחר שהטריח את בעליו שבע פעמים הוא חוזר למוטב והן הטריחו את בוראן להביא עליהן פורעניות ולהכעיסו בשבעת אלה ולא חזרו בהן:"],[5,"מאי ולא עבדוהו","לשון קבלה הוא שהוא קובל עליהם הקדיחוני והקניטוני שבע פעמים כבשול התורמוס ואחרי כל זאת לא נחשבתי בעיניהם:"],[6,"שהן עזים","ונתנה להם תורה שיעסקו בה והיא מתשת כחם ומכנעת לבם:"],[6,"מימינו אש דת למו","מימינו נתן להם התורה מפני שאש דת למו והרבה מקראות חסרים כזה:"],[6,"דתיהן של אלו","מנהגם של אלו אש שהם עזים כאש:"],[7,"עזים","קשים להנצח אנדרי\"ש בלע\"ז:"],[7,"צלף באילנות","לא ידעתי מהו עזות שלו:"],[8,"אין הסומא יוצא במקלו","דהוי דרך חול ואיכא זלותא די\"ט:"],[8,"ואין יוצאין בכסא","שטוענין אותם בני אדם והם יושבים בקתדרא:"],[9,"בגלודקי","פליידסטו\"ל:"],[9,"צריכין לו","לבית המדרש לדרשה:"],[9,"מותר","להוציאו בו מביתו לבית המדרש:"],[10,"אפיקתיה","בכסא:"],[10,"מהיני לשילי","מקומות סמוכין ואין תחום שבת ביניהם:"],[11,"לחמא בר אדא","כך שמו:"],[11,"שליח ציון","רגיל היה לעלות לירושלים:"],[11,"אקיף","הרבה בשבילי את הדרך להקיף ההר ולך דרך סולם מעלות הר של צור ששם יושב רבי יעקב בר אידי:"],[11,"מה אתון ביה","מה אתם אומרים בו:"],[12,"כי סליק","כלומר כי מטא לא\"י ולאחר שעבר את צור:"],[12,"אלונקי","שנביאיל\"ש בלע\"ז שנותן זרועו על כתף חבירו וחבירו על כתפו וזה בכסאו יושב על זרועותם דמתחזי דרך חול ופרהסיא ולהוליך למקום רחוק טפי משנושאים בין ידיהן בכסאו:"],[13,"ילתא","שם אשתו של ר\"נ:"],[13,"דבעיתא","ליפול:"],[14,"בשבתא דרגלא","שדורשין:"],[14,"מכתפי להו","בבית המדרש עד מקומם:"],[14,"משום בעתותא דצבורא","שהיו נבעתים מן הצבור העומדים על רגליהם מפניהם והיו יראים ליפול:"],[14,"משום דוחקא","שעומדים על רגליהן וטורח צבור הוא הלכך מכתפי להו עבדיהם ותלמידיהם ומוליכין אותן מהר למקומן:"],[15,"מתני' בכור שנפל לבור","בכור בזמן הזה אין נשחט בלא מום מפני שקדשים הוא דמאליו הוא קדוש והשוחטו כשהוא תם הוי שוחט קדשים בחוץ וענוש כרת:"],[15,"שנפל לבור","וירא פן ימות שם:"],[15,"מומחה","בקי במומין להבחין בין מום קבוע למום עובר:"]],[[0,"","אורח ארעא קמ\"ל. פי' רש\"י ולאו משום איסור טרפה תימה דבסמוך משמע שיש איסור בדבר דקאמר נטיעה מקטע רגליהון דקצביא וי\"ל דודאי ליכא איסור דמשנשחטה היא עומדת בחזקת היתר מיהו אם נמצאת טריפה לאחר שאכל הוא נענש כשוגג ולא כאונס שלא היה לו למהר כל כך:"],[7,"","וצלף באילנות. פרש\"י ולא ידענא מאי עזותיה ופי' בתוספתא משום דעושה ג' פירות עלין אביונות וקפריסין ועוד שטוען פירות בכל יום מה שאין כן בשאר אילנות ועוד פי' ר\"י דעזותו הוי ממה ששורין ביין מן הקפריסין שהיא עזה כדאמר בפטום הקטרת יין קפריסין למה הוא בא ששורין בו הצפורן כדי שתהא עזה ולא כפרש\"י שפירש בכריתות (דף ו.) שהוא יין הבא ממקום קפרס:"],[13,"","שאני ילתא דבעיתא. וא\"ת והא לא התירו אלא כי יש בה צורך רבים כדאמרינן לעיל וי\"ל דלמא נמי הלכה לצורך רבים שבת ראש הגולה היתה והיו רבים צריכים ממנה:"],[15,"","בכור שנפל לבור ר\"י אומר וכו'. נ\"ל דמיירי בבכור שהיה בו מום קבוע מאתמול אך שלא הראה לחכם מבעוד יום דאי נפל ביה מומא בי\"ט ודאי לא הוה שרי רבי יהודה דהוי מוקצה מחמת איסור דלא הוה דעתיה עליה מאתמול ור' יהודה אית ליה מוקצה וה\"ק בכור שנפל בו מום אך שלא הראהו לחכם מבעוד יום ונפל לבור בי\"ט ירד המומחה וכו' דרואין מומין בי\"ט ס\"ל לרבי יהודה ר\"ש אומר אין זה מן המוכן"]]],[["אם יש בו מום יעלה וישחוט ואם לאו לא ישחוט ר' שמעון אומר כל שאין מומו ניכר מבעוד יום אין זה מן המוכן:","\u0001גמ׳\u0002 במאי קא מפלגי אי נימא ברואין מומין קמפלגי דר' יהודה סבר רואין מומין בי\"ט ור' שמעון סבר אין רואין מומין בי\"ט ולפלגו ברואין מומין דעלמא","בכור שנפל לבור אצטריכא ליה סד\"א משום צער בעלי חיים לערים ולסקיה כר' יהושע קמ\"ל","אי הכי לא ישחוט לא יעלה וישחוט מבעי ליה לא צריכא דעבר ואסקיה סד\"א לשחטיה קמ\"ל","לשחטיה הא תם הוא לא צריכא דנפל ביה מומא והא מוקצה הוא","אלא דנפל ביה מום עובר מערב יום טוב והשתא הוה ליה מום קבוע מהו דתימא דדעתיה עלויה ונשחטיה קמ\"ל:","ת\"ר בכור תם שנפל לבור ר' יהודה הנשיא אומר ירד מומחה ויראה אם יש בו מום יעלה וישחוט ואם לאו לא ישחוט אמר לו ר' שמעון בן מנסיא הרי אמרו אין רואין מומין ביום טוב כיצד נולד בו מום מערב \"ט אין מבקרין אותו בי\"ט נולד בו מום"],[[0,"אם יש בו מום","על כרחך ר' יהודה מוקצה אית ליה ובמום הנופל בו ביום טוב לא שרי דלאו דעתיה עלויה מאתמול וה\"ק בכור בעל מום שלא הראהו לחכם מבעוד יום להתירו ונפל לבור בי\"ט ירד מומחה ויראה מום שהיה בו אתמול אם מום קבוע הוא יעלה וישחוט משום דמוקצה ליכא דמאתמול דעתיה עלויה:"],[0,"אין זה מן המוכן","לאו משום מוקצה אסר ליה דהא לית ליה מוקצה אלא לפי שמתירו בי\"ט נראה כמתקנו דהוה ליה כדן דין דגזור ביה משום שבות וה\"ק אין התרתו היתר ואינו מוכן להכשר:"],[1,"גמ' אי נימא ברואין כו'","דהא ודאי משום מוקצה לא הוי טעמייהו דאפכא שמעינן להו אלא משום ראיית מום דר\"ש סבר אין רואין כיון דהוה ליה כיושב ודן דין:"],[1,"לפלגו בעלמא","בלא נפל לבור:"],[2,"לערים","לומר ודאי ימצא בו מום:"],[2,"ולסקיה כרבי יהושע","דאמר בפרק משילין (לקמן ביצה דף לז.) אותו ואת בנו שנפלו לבור מעלה את הראשון ע\"מ לשחוט ואינו שוחט וחוזר ומעלה את השני רצה זה שוחט רצה זה שוחט:"],[3,"אי הכי","דנפילת בור דנקט לאשמועינן דלא יעלהו נקט ליה ואם לאו לא יעלהו מבעי ליה דהא עיקר משום העלאה נקט לה ושחיטה פשיטא לן:"],[3,"לא צריכא דעבר ואסקיה","ומשמעותא דלא לסקיה מרישא ש\"מ דקתני ירד המומחה ויראה ולא קתני יעלהו ויראה והדר אשמועינן אחריתי דאי עבר ואסקיה ולא מצא בו מום לא ישחוט:"],[4,"דנפל ביה מומא","השתא וה\"ק אם יש בו מום הקבוע מעי\"ט יעלה וישחוט ואם לאו דלא היה מעי\"ט אלא היום אפילו עבר והעלהו לא ישחוט:"],[4,"והא מוקצה הוא","אי מאתמול לא הוה ביה מום כלל פשיטא דלא ישחוט דהא אשמעינן רבי יהודה בכמה דוכתי דאית ליה מוקצה:"],[5,"קמ\"ל","דאי לא הוה קבוע מערב י\"ט לא ישחוט משום דמוקצה מחמת איסור הוה אי נמי משום דעבר ואסקיה:"],[6,"","בכור תם שנפל לבור גרסינן בברייתא דלית להו מוקצה להנך תנאי בבכור דכל שעתא דעתיה עלויה שמא יפול בו מום:"],[6,"","ר' יהודה הנשיא הוא רבי ולאו היינו רבי יהודה דמתניתין דסתם ר' יהודה הוא ר' יהודה בר אלעאי:"],[6,"ירד מומחה","ולא לערים ולסקיה:"],[6,"אם יש בו מום","אפילו נפל בו היום:"],[6,"יעלה וישחוט","דלית ליה מוקצה בבכור:"],[6,"ואם לאו","ועבר ואסקיה לא ישחוט אפילו נפל בו מום לאחר העלאה וקנסא הוא משום דעבר ואסקיה [א\"נ] לא ישחוט לא יעלה בהערמת שחיטה קאמר דלא ישחוט לא אצטריך דהא תם הוא ומתניתין דלא שנינן הכי משום דמתניתין לא מצינן לאוקומה בתם משום דרבי יהודה מוקצה אית ליה ולא מצי למימר אם יש בו מום שנפל בו בי\"ט יעלה וישחוט וכיון דע\"כ בבעל מום תוקמה לא אצטריך לשנויי סיפא בשנויא דחיקא ולמימר דלא ישחוט לא יעלה קאמר דהא מצי לשנויא שפיר כדשנינן דאשמעינן ואם לאו דלא היה קבוע מבעוד יום דאפילו עבר ואסקיה לא ישחוט ואע\"ג דאתעביד ליה מום קבוע השתא: לשון אחר לא גרס בברייתא בכור תם אלא כי מתני' גרסינן בברייתא בכור שנפל לבור ומתוקמא הכי בכור שנפל לבור ר' יהודה הנשיא אומר ירד מומחה ויראה דלא נערים ונסקיה מעיקרא:"],[6,"אם יש בו מום","אם ימצא בו מום הידוע שהיום לא נעשה יעלהו וישחוט ואם לאו אלא נפל בו מום היום אפילו העלהו לא ישחוט ולרבי יהודה נשיאה ליכא למפרך כדפרכינן לעיל פשיטא דלא ישחוט דהא מוקצה הוא דאלו לדידיה אצטריך דהשתא הוא דאשמעינן דאית ליה מוקצה:"],[6,"א\"ל ר' שמעון בן מנסיא הרי אמרו","רבותינו דורות שלפנינו אין רואין מומין דר\"ש בן יוחי מדורות שלפניהם היה ורבי תלמידו היה כדאמר במסכת עירובין (דף צא.) ובמסכת שבת (דף קמז:) א\"ר כשהיינו לומדים תורה אצל ר' שמעון בתקוע היינו מעלין לו שמן כו' וקאמר ליה ר' שמעון בן מנסיא לרבי הרי נחלקו בה דורות שלפנינו ונזיל לחומרא:"],[6,"נולד בו מום מעי\"ט","רבי שמעון בן מנסיא מפרש מלתיה דר' שמעון בן יוחי וה\"ק הרי אמר ר\"ש בן יוחי אין רואין מומין כיצד נולד בו מום מערב י\"ט אין מבקרין אותו לכתחלה אבל אם עבר ובקרו שוחטו שהרי אינו מתקן כל כך שקרוב היה בין השמשות להיות מתוקן שלא היה מחוסר אלא ראיית חכם:"]],[[0,"","ע\"כ לא בעי למימר דאין זה מן המוכן שהוא מוקצה דהא ר\"ש לית ליה מוקצה אלא ה\"פ כל שאין מומו ניכר שלא ראהו חכם מעי\"ט ולא היה נודע אם היה קבוע אין זה מן המוכן כלומר אין היתרו היתר דאין מוכן להכשיר דאין רואין מומין בי\"ט וטעמא משום דנראה כמתקן או כדן את הדין שהוא אסור משום שבות ע\"כ פירש רש\"י וקשה דאין זה מן המוכן משמע דאפילו בקרו חכם כיון שלא נודע שהוא מום קבוע מאתמול אוסר ר\"ש ולפ\"ה משמע דוקא דאינו מוכן להכשיר לכתחלה הא דיעבד שפיר דמי וע\"ק דבשבת מוכח בהדיא בפרק כירה (שבת דף מו: ושם) דמטעם מוקצה קאמר דפריך מהכא דר\"ש אית ליה מוקצה והא לית ליה מוקצה לר\"ש לכן נ\"ל דמטעם מוקצה קאמר דאין זה מן המוכן ואפילו עבר ובקרו מ\"מ אסור משום מוקצה ופליגי ברואין מומין וגם פליגי במוקצה מיתורא דקתני אין זה מן המוכן והא דפריך הכא בגמ' לפלגו ברואין מומין בעלמא ר\"ל דלא נפל לבור ולעולם כלישנא דמתניתין דמוקצה וכן הא דקאמר בגמרא מהו דתימא כיון דדעתיה עלויה נשחטיה קמ\"ל ר\"ל דאסור משום מוקצה ואפילו אם בקרו בדיעבד אף לר' יהודה כיון שלא היה בו מום קבוע מאתמול ור\"ש אסר אפילו אם היה בו מום משום מוקצה כדפירש' דלא כאדא בר אוכמי וא\"ת מ\"ש דבכל דוכתא מחמיר רבי יהודה טפי במוקצה מרבי שמעון וי\"ל דטעמא רבה אית ליה הואיל דס\"ל דרואין מומין ביום טוב וידוע שמום קבוע היה מאתמול א\"כ אין כאן מוקצה דהא מאתמול דעתיה עלויה אבל לר\"ש אית ליה דאין רואין מומין הלכך לאו דעתיה עלויה מאתמול על כן אסור אפילו אם בקרו בדיעבד:"],[6,"","תנו רבנן בכור תם שנפל לבור ה\"ג. דר' יהודה הנשיא לית ליה מוקצה דקאמר אם יש בו מום קבוע ואפילו אם נפל בי\"ט יעלה וישחוט ולית להו להני תנאי מוקצה בבכור דלעולם דעתו עליו שמא יפול בו מום ואם לאו שאין בו מום מאליו לא ישחוט וא\"ת פשיטא והא תם הוא וי\"ל לא יעלה בהערמת שחיטה כדפירש' לעיל ועל ר' יהודה דמתני' לא בעי לשנויי הכא דלא בעי לשנויי שנויא דחיקא ולא יעלה בהערמת שחיטה קאמר הואיל דאית ליה שנויא אחרינא דר' יהודה אית ליה מוקצה בבכור וצריך לאוקומי בבעל מום ע\"כ דהא אית ליה מוקצה אבל לרבי יהודה הנשיא דלית ליה מוקצה בבכור דהא בתם שנפל לבור מיירי לא מצי לשנויי הכי שנפל בו מום קבוע בי\"ט כדמשני לרבי יהודה במתניתין עוד פרש\"י פי' אחר דלא גרס תם בברייתא אלא ה\"ג בכור שנפל לבור וכו' אם יש בו מום קבוע שידוע בו מום מערב י\"ט ישחוט ואם לאו אלא נפל בו מום היום לא ישחוט אפילו אם העלהו משום דהוי מוקצה ולרבי יהודה נשיאה אית ליה מוקצה ולא פריך הש\"ס כדפריך הש\"ס לעיל לרבי יהודה דמתני' פשיטא דמוקצה הוא דודאי לרבי יהודה דמתני' פריך שפיר דמאי אצטריך לאשמועינן אי משום מוקצה בהרבה מקומות שמעינן דרבי יהודה דמתני' אית ליה מוקצה אבל ארבי יהודה הנשיא אצטריך לאשמועינן (דרבי יהודה) דאית ליה מוקצה ותימה דבשלהי מכלתין (דף מ.) מספקא ליה לרבי יהודה הנשיא אי אית ליה מוקצה ואמאי לא פשיט ליה מהכא וי\"ל דלא פסיק להוכיח מהכא דאיכא לפרושי תרי לישני כדפי' דלחד אית ליה מוקצה ולחד לית ליה מוקצה ומספקא ליה אי כהאי לישנא אי כהאי לישנא לכך לא היה לו להוכיח מהכא: [וע\"ע תוספות שבת מה: ד\"ה לדבריו]:"]]],[["בי\"ט ר' שמעון אומר אין זה מן המוכן ושוין שאם נולד הוא ומומו עמו שזה מן המוכן","דרש רבה בר רב הונא נולד הוא ומומו עמו מבקרין אותו בי\"ט לכתחלה א\"ל רב נחמן אבא תני אם עבר ובקרו מבוקר ואת אמרת מבקרין אותו לכתחלה","אמר אביי כותיה דרבה בר רב הונא מסתברא מדקתני תלתא בבי נולד בו מום מערב יום טוב אין מבקרין אותו ביום טוב לכתחלה הוא דלא הא דיעבד שפיר דמי","נולד בו מום ביום טוב ר' שמעון אומר אין זה מן המוכן דאפילו דיעבד נמי לא והדר תני ושוין שאם נולד ומומו עמו שזה מן המוכן דאפילו לכתחלה נמי","והא כי אתא רב אושעיא אתא ואייתי מתניתא בידיה בין שנולד בו מום מערב י\"ט ובין שנולד בו מום בי\"ט חכמים אומרים אין זה מן המוכן","ואלא קשיא הך ההיא אדא בר אוכמי היא דמשבש ותני","אמר רב נחמן בר יצחק מתני' נמי דייקא דקתני ר' שמעון אומר כל שאין מומו ניכר מערב י\"ט אין זה מן המוכן מאי אין מומו ניכר אילימא שאין מומו ניכר כלל פשיטא צריכא למימר","אלא דלא אתחזי לחכם מערב י\"ט אם מום קבוע אם מום עובר קתני מיהת אין זה מן המוכן שמע מינה","בעי מיניה הלל מרבא יש מוקצה לחצי שבת או אין מוקצה לחצי שבת היכי דמי אי דאחזי בין השמשות אחזי אי דלא אחזי לא אחזי","לא צריכא דאחזי והדר אדחי והדר אחזי מאי א\"ל יש מוקצה","איתיביה ושוין שאם נולד ומומו עמו שזה מן המוכן ואמאי נימא האי בכור מעיקרא הוה חזי אגב אמיה אתיליד ליה אדחי ליה אחזייה לחכם אשתרי ליה","אמר אביי ואיתימא רב ספרא כגון דיתבי דייני התם","איכא דאמרי אמר ליה אין מוקצה לחצי שבת לימא מסייע ליה ושוין שאם נולד ומומו עמו שזה מן המוכן והא בכור מעיקרא הוה חזי אגב אמיה אתיליד ליה אדחי ליה אחזייה לחכם אשתרי ליה","אמר אביי ואיתימא רב ספרא כגון דיתבי דייני התם","ת\"ש היה אוכל בענבים והותיר והעלן לגג לעשות מהן צמוקין בתאנים והותיר והעלן לגג לעשות מהן גרוגרות לא יאכל מהן עד שיזמין מבעוד יום וכן אתה מוצא באפרסקין ובחבושין ובשאר כל מיני פירות","היכי דמי אי דחזו למה ליה הזמנה אי דלא חזו כי אזמין להו מאי הוי","וכי תימא דלא ידע אי חזו אי לא חזו והאמר רב כהנא מוקצה שיבש ואין הבעלים מכירין בו מותר","אלא לאו דחזו ואדחו והדר אחזו ואי אמרת אין מוקצה למה להו הזמנה אלא מאי יש מוקצה כי אזמין להו מאי הוי","לא צריכא דאחזו ולא אחזו דאיכא אינשי דאכלי ואיכא אינשי דלא אכלי אזמין גלי דעתיה לא אזמין לא גלי דעתיה","אמר רבי זירא ת\"ש מפולין ועדשים דהא פולין ועדשים מעיקרא חזו לכוס שדינהו בקדרה אדחו להו"],[[0,"בי\"ט","ואם נולד בו מום בי\"ט היה ר\"ש בן יוחי אומר אין זה מן המוכן ואפילו עבר ובקרו לא ישחוט שהוא כמתקנו לגמרי:"],[0,"ושוין כו'","אבל בזו היו מודים חולקים שלפנינו ר' יהודה ור\"ש שאם נולד היום ומומו עמו שזה מן המוכן שאין בזה משום תקון ומשום דין שלא היתה בו חזקת איסור מעולם וכדמוקי לה לקמן כגון דיתבי דייני התם:"],[1,"אבא תני","על אביו קאמר:"],[1,"מבוקר","ושוחטו לכתחלה:"],[2,"כותיה דרבה מסתברא","דלכתחלה שרי:"],[2,"מדקתני לה בתלתא בבי","בברייתא דלעיל בדרבי שמעון בן מנסיא:"],[2,"אין מבקרין","לכתחלה משמע:"],[3,"אין זה מן המוכן","משמע אפילו דיעבד אינה הכנה ועוד מדפלגינהו לתרי בבי:"],[3,"שזה מן המוכן אפילו לכתחלה","קאמר דמוכן לבקרו דאי בדיעבד קאמר ומאי מוכן מוכן לשוחטו קאמר אמאי פלגינהו לתלתא בבי לתנייה להך סיפא בהדי רישא ולערבינהו ולתנינהו הכי נולד בו מום מערב יום טוב או שנולד הוא ומומו עמו אין מבקרין אותו ביום טוב דלהוי משמע לכתחלה הוא דלא הא דיעבד שפיר דמי:"],[4,"","ואייתי מתניתא בידיה גרסינן:"],[4,"חכמים אומרים אין זה מן המוכן","אפילו דיעבד והא ר' שמעון היא דשמעינן ליה אין רואין מומין וכיון דבהנך תרתי ערב ותני להו איכא למימר דנולד הוא ומומו עמו דשרי דיעבד קאמר כרב נחמן וקשיא לאביי דסייעיה לרבה בר רב הונא מהך:"],[5,"ואלא קשיא ההיא","דלעיל דמסייעא ליה לרבה ואהי מינייהו סמכינן:"],[5,"ההיא","דלעיל:"],[5,"אדא בר אוכמי הוא","חכם אחד שהיו מכירין בו שהיה גורס משניות ומשכח ומשבשן:"],[6,"דיקא","כי הך דאייתי רב אושעיא:"],[6,"אי נימא שאין מומו מאתמול כלל","שלא היה בו שום מום:"],[6,"צריכא למימר","בתמיה וכי צריך היה רבי שמעון לומר לר' יהודה בן מחלוקתו כן והלא רבי יהודה אית ליה מוקצה ונהי דרואין מומין סבירא ליה האי מיהא אסור דמוקצה הוא:"],[7,"אין זה מן המוכן","אפילו דיעבד ומהשתא על כרחיך ושוין שאם נולד הוא ומומו עמו שזה מן המוכן. בדיעבד קאמר:"],[8,"יש מוקצה לחצי שבת","משום חצי שבת אם הוקצה בחציו מי הוי מוקצה לכולי שבת אם לא:"],[8,"היכי דמי","מכדי סתם מוקצה היינו גרוגרות וצמוקין שמעלה אותן על מנת ליבשן ומקצה אותן לכך ומשמתחילין ליבש אין ראוין לאכילה עד שייבשו לגמרי והא חצי שבת דקא אמרת היכי מספקא לך:"],[8,"אי דאחזו","שנגמרה מלאכתן בין השמשות אחזו ואין כאן אפילו חצי שבת בהקצאה כלל:"],[8,"ואי דלא אחזו","בין השמשות ודאי אסורין דאין כאן הכנה מבעוד יום ומאן דאית ליה מוקצה הכנה מבעוד יום בעי כדכתיב ביום הששי והכינו את אשר יביאו (שמות טז):"],[9,"לא צריכא דאחזו","בין השמשות:"],[10,"נימא האי בכור מעיקרא","בין השמשות הוה חזי לשחוט את אמו והוא נאכל בין תם בין בעל מום לפי שאין בכור קדוש אלא בלידתו דכתיב אשר יולד בבקרך וגו' (דברים ט״ו:י״ט):"],[12,"אדחיה ליה","שהיה בחזקת בכור תם ואסור עד שיראה מומו:"],[13,"דיתבי דייני התם","כשנולד וכפוטרו את הרחם ראו את מומו דלא הוקצה כלל:"],[14,"היה אוכל בענבים והותיר","רבותא נקט דלא תימא כיון דאוכל והולך לא ליבעי הזמנה וכן מפרש בפרק שלישי דשבת בכירה שהסיקוה (דף מה.):"],[14,"ענבים","יבשין קרוין צמוקים ותאנין שנתיבשו קרוין גרוגרות:"],[14,"אפרסקין","פרשקי\"ש בלע\"ז:"],[14,"חבושין","קרוני\"ץ:"],[15,"אי דאחזו","בין השמשות:"],[15,"למה לי הזמנה","הא ודאי כיון דחזא בהו דיבשו דעתיה עלוייהו שהרי לא הוקצו אלא ליבשן:"],[15,"ואי דלא אחזו כי אזמין להו מאי הוי","הא לא חזי לאכילה ולא מהניא להו הזמנה דהוה ליה כמזמין עצים ואבנים לאכילה שאין בריה אוכלתן:"],[16,"וכי תימא דלא ידע אי חזו אי לא חזו","וכי תימא הך הזמנה דקתני כגון דטורח הוא לו לעלות אליהן ולראות אם יבשו אם לאו ואינו יודע אם ראוין אם לא ראוין ומכין בהזמנה ואומר הריני אוכל מהן למחר אם ראוין הן ואשמעינן אי לאו דאזמינהו מאתמול כיון דלא הוה ידע שהן ראוין לא הוה אמרינן דעתיה עלוייהו ואסורים לאכול אפילו מצאן ראוין:"],[16,"והאמר רב כהנא מוקצה","של גרוגרות וצמוקין:"],[16,"שיבש","מבעוד יום:"],[16,"ואין הבעלים מכירין בו","אין הבעלים יודעים שיבש שלא בדקוהו מבעוד יום ולמחר מצאוהו שיבש היה מאתמול:"],[16,"מותר","דכי אסקיה מעיקרא לא אקצייה אלא ליבש והרי יבש והוכן מבעוד יום כך פירש רב אחאי בשאלתות שלו:"],[17,"ואדחו","בשבת שנפלה עליהן גשמים ותפחו והדר אחזו ששזפתן השמש וקא מיבעיא לן הך שעתא דאתקצו מי אסרה להו כולי יומא או לא:"],[17,"אלא לאו דאחזו ואדחו והדר אחזו","ע\"כ לא מתוקמא הך הזמנה אי לאו להכי דאזמין להו דאם ידחו למחר ויתקנו לבו ביום יאכל מהן:"],[17,"ה\"ג אלא מאי יש מוקצה כי אזמין להו מאי הוי","הזמנה דקודם הקצאה מאי מהניא בלאו הזמנה נמי מוכנין ועומדין הן והאיסור בא אחרי כן:"],[18,"ה\"ג אלא דאחזו ולא אחזו","בהכי עסקינן שיבשו ולא כל צרכן:"],[18,"דאיכא אינשי דאכלי ואיכא דלא אכלי","ואצטריך ליה לגלויי דעתיה אי אכיל אי לא אכיל:"],[19,"תא שמע","דאין מוקצה לחצי שבת:"],[19,"מפולין ועדשים","שאנו מבשלין ביום טוב:"],[19,"דמעיקרא","בין השמשות:"],[19,"חזו לכוס","חיין כל דבר הנאכל חי קרי אכילתו כוסס:"],[19,"אדחו להו","כל זמן שרותחין:"]],[]],[["גמר בשולייהו חזו להו","אמר ליה אביי ולטעמיך תקשי לך קדרות דעלמא דהא סתם קדרות דעלמא בין השמשות רותחות הן ולאורתא אכלינן מינייהו","אלא גמרו בידי אדם לא קא מבעיא לן כי קא מבעיא לן גמרו בידי שמים","ר' יהודה נשיאה הוה ליה ההוא בוכרא שדריה לקמיה דר' אמי סבר דלא למחזייה א\"ל רבי זריקא ואיתימא רבי ירמיה ר' יהודה ור' שמעון הלכה כר' יהודה הדר שדריה לקמיה דרבי יצחק נפחא סבר דלא למחזייה א\"ל ר' ירמיה ואיתימא ר' זריקא ר' יהודה ור' שמעון הלכה כר' יהודה","א\"ל רבי אבא מאי טעמא לא שבקתינהו לרבנן למעבד עובדא כר' שמעון א\"ל ואת מה בידך א\"ל הכי אמר ר' זירא הלכה כר' שמעון","אמר מאן דהוא אזכי ואסק להתם ואגמרה לשמעתא מפומיה דמרה כי סליק להתם אשכחיה לר' זירא א\"ל אמר מר הלכה כרבי שמעון א\"ל לא אנא מסתברא אמרי","מדקתני במתניתין ר' שמעון אומר כל שאין מומו ניכר מבעוד יום אין זה מן המוכן וקתני לה בברייתא בלשון חכמים ש\"מ מסתברא כוותיה","מאי הוי עלה אמר רב יוסף ת\"ש דתליא באשלי רברבי דאמר רבי שמעון בן פזי א\"ר יהושע בן לוי א\"ר יוסי בן שאול אמר רבי משום קהלא קדישא דבירושלים ר' שמעון וחבריו אמרו הלכה כרבי מאיר","אמרו והא אינהו קשישי מניה טובא אלא בשיטת ר' מאיר אמרוה","דתנן השוחט את הבכור ואחר כך הראה את מומו ר' יהודה מתיר ורבי מאיר אומר הואיל ונשחט שלא על פי מומחה אסור אלמא קסבר ר' מאיר ראיית בכור לאו כראיית טרפה ראיית בכור מחיים ראיית טרפה לאחר שחיטה","ומינה ראיית טרפה אפילו בי\"ט ראיית בכור מערב י\"ט","א\"ל אביי אטו התם ברואין מומין פליגי בקנסא פליגי דאמר רבה בר בר חנה אמר רבי יוחנן בדוקין שבעין כולי עלמא לא פליגי דאסור משום דמשתנין","כי פליגי במומין שבגוף רבי מאיר סבר גזרינן מומין שבגוף אטו מומין שבעין ור' יהודה סבר לא גזרינן","אמר רב נחמן בר יצחק מתניתין נמי דיקא דקתני ר' מאיר אומר הואיל ונשחט שלא על פי מומחה אסור שמע מינה קנסא הוא דקא קניס שמע מינה","אמי ורדינאה חזי בוכרא דבי נשיאה הוה ביומא טבא לא הוה חזי אתו ואמרו ליה לרבי אמי אמר להו שפיר קא עביד דלא חזי איני והא רבי אמי גופיה חזי רבי אמי כי חזי מאתמול הוה חזי"],[[0,"גמר להו בשולייהו","אשתרו ולא אמרינן שעה אחת היו מוקצות וידחו:"],[1,"ולטעמיך","דמשוית להו לרתיחתן תורת מוקצה וילפת מינה דאין מוקצה לחצי שבת:"],[1,"תקשי לך","מהשתא דלא תוכל לתרץ היאך אנו אוכלים שום קדרות בלילי שבתות דעל כרחך המוקצה לבין השמשות מוקצה לכולי יומא והרי בין השמשות כל הקדרות מסולקות מרותחות מן הכירה ואכלינן מנייהו לאורתא:"],[2,"אלא מידי דגמרו בידי אדם לא קא מבעיא לן","דכיון דבידו לתקנו בו ביום לא מקצה ליה מדעתיה מפני דחייתו הלכך פולין ועדשים אינם ראייה לכאן ומהאי טעמא נמי שרינן קדרות של בין השמשות:"],[2,"כי קא מבעיא לן גמרו בידי שמים","ע\"י חמה דכיון שאין בידו לתקנו מסח דעתיה מניה:"],[3,"הוה ליה ההוא בוכרא","והיו לו בביתו כהנים סמוכין על שלחנו ואוכלין בכורות:"],[3,"רבי יהודה ור' שמעון הלכה כרבי יהודה","הכי כיילינן להו בעירובין (דף מו:):"],[3,"אמר ליה ר' זריקא","לר' אבא:"],[4,"ואת מה בידך","דשבקת לרבי יהודה ובעית למעבד כר' שמעון ממי שמעת דהלכה כר' שמעון בזו:"],[5,"אמר מאן דהוא","אחד מן התלמידים מי שהוא ולא נודע שמו:"],[5,"אזכי ואסק","יהי רצון שאזכה לעלות לארץ ישראל למקום שרבי זירא שם דהוא מרה דשמעתא דאמרי משמיה הלכה כר' שמעון ואגמרה לשמעתא מפומיה:"],[5,"אנא מסתברא אמרי","כן אמרת דמסתברא כרבי שמעון אבל לא שמעתי שהוקבעה הלכה למעשה כמותו:"],[6,"בלשון חכמים","דקתני לעיל אתא ואייתי מתניתא בידיה בין שנולד בו מום מעי\"ט בין שנולד בו מום בי\"ט חכמים אומרים כו' ור' שמעון הוא דקאמר הכי וקרי ליה חכמים:"],[7,"באשלי רברבי","בחבלים גדולים וגסים שקשין לינתק כלומר חכמים גדולים אמרוה ואין נוחין לבטל דבריהם:"],[7,"ר' שמעון בן מנסיא וחביריו","אותן שאמר עליהן הרי אמרו אין רואין מומין בי\"ט:"],[7,"אמרו הלכה כר' מאיר","בבכורות השתא משמע שמעידין קהלא קדישא על ר' שמעון בן מנסיא שאומר עוד דבר זה ומפרש רב יוסף אמרו בתמיה וכי אפשר שקהלא קדישא אומרים דבר זה על ר' שמעון בן מנסיא וחביריו אמרו הלכה כר' מאיר ועבדינן כותייהו:"],[8,"והא אינהו קדימי וקשישי מיניה טובא","קהלא קדישא דאמרה רבי להא שמעתא משמייהו קשישי מר' שמעון בן מנסיא טובא דהא ר' שמעון בן מנסיא בימי רבי ובניו היה כדתנן באבות [פ\"ו] אמר ר' שמעון בן מנסיא אלו שבע מדות שמנו חכמים בתלמידים כלן נתקיימו ברבי ובבניו ולעיל נמי אפלוג בהדיה והיכי אמרו ההוא קהלא קדישא הלכה משמיה דר' שמעון בן מנסיא דקתני ר' שמעון וחביריו אמרו הלכה כר' מאיר:"],[8,"אלא","הכי אמור קהלא קדישא ר' שמעון בן מנסיא וחבריו שאמרו אין רואין מומין בשיטת ר' מאיר אמרוה וכן אפשר שהזקנים נתנו דעתם על דברי הבחורים ואמרו דברי פלוני נוטין אחר דברי ר' פלוני שהיה לפניו:"],[9,"השוחט את הבכור","קודם שהתירו חכם ואח\"כ הראה את מומו לחכם:"],[9,"אלמא קסבר ר' מאיר ראיית בכור","אינה קלה כראיית טרפה דאחשבוה רבנן וכל עצמה של התרת בכור תלויה בה שאף שחיטתו אסורה קודם שיראנו ואינו דומה לראיית טרפה שהתירו לבדקה אחר שחיטה:"],[10,"ומינה","וממנה למדו ר' שמעון בן מנסיא וחביריו ואמרו כיון דחשיבא כולי האי הוה ליה כמתקן וכדן דין ואסור לראותו בי\"ט ואע\"פ שהטרפה נבדקת בי\"ט והיינו תליא באשלי רברבי שאמרו קהלא קדישא דהא דר' שמעון כר\"מ אזלא וקמו להו ר' שמעון בן יוחי ור' מאיר בחדא שיטתא וה\"ל ר' יהודה יחיד ואין דבריו של אחד במקום שנים:"],[11,"אמר ליה אביי","לרב יוסף:"],[11,"אטו","ההיא דר\"מ דבכור ברואין מומין לאחר שחיטה פליגי ומשום טעמא דחשיבותא אמרה ר\"מ למלתיה והא קנסא קניס כדמפרש ואזיל ואלו אדם אחר שחטו וכסבור שהוא ניתר מפי מומחה אפילו ר\"מ מודה דרואין:"],[11,"בדוקין","טייל\"א כמו הנוטה כדוק שמים (ישעיהו מ׳:כ״ב) אם מום זה דוק שבעין:"],[11,"כולי עלמא","אפילו ר' יהודה מודה דאסור מפני שמשתנה לאחר המיתה ויש דוק שנראה לאחר שחיטה מום קבוע שאלו ראהו לפני שחיטה היה נראה עובר:"],[12,"במומין שבגוף","כגון נקצצה אזנו נשברה ידו דלא נשתנה בשביל השחיטה:"],[13,"מתני'","דבכורות נמי דיקא דמשום גזרה קאסר ליה וקנסא קניס כדי שלא ירגיל עוד מדלא קתני ר\"מ אוסר דנהוי משמע דאסורו תלוי בגופו שאין ראייתו לאחר שחיטה כלום אלא הואיל ועבר ושחטו שמע מינה זהו טעמו של דבר מפני שהקיל לשחטו ותלה ר\"מ הדבר ברשעו של כהן זה שהקיל בו:"],[14,"אמי ורדינאה","נאה היה ועל שם ורדים היה נקרא ולי נראה מאותו מקום ששמו ורדינה כדאמרינן בעירובין (דף מט.) שנקרא מאנשי ורדינה ואנשים זקנים וצרי עין בממונן היו:"],[14,"מאתמול הוה חזי","אם קבוע אם עובר:"]],[[2,"","אלא גמרו בידי אדם לא מבעיא לן וכו'. וא\"ת אמאי אין מוכיח מההיא דכופין את הסל לפני האפרוחין כדי שיעלו וירדו וקאמר [שבת מג.] מותר לטלטלם פי' אחר שירדו מותר לטלטל הסל אע\"פ שהיה אסור כשעלו האפרוחים עליו בחצי היום אלמא אין מוקצה לחצי שבת וי\"ל דשאני התם דהוי כמו גמרו בידי אדם שבידו להפריחם מעליו דהא שרינן קדרות אע\"ג דבין השמשות רותחות הן ועוד יש לומר דהתם מיירי לענין טלטול דפשיטא ליה דאין מוקצה לחצי שבת והכא קא בעי לענין אכילה:"],[13,"","אלא ר' מאיר קנסא קא קניס. ופסיק רבינו יצחק דהלכה כרבי יהודה דקבעי התם בבכורות (דף כח: ושם) סתמא דש\"ס אליבא דר' יהודה ואע\"ג דר' מאיר ור' יהודה הלכה כרבי מאיר בגזרותיו היינו ודאי בגזרותיו אבל לא בקנסותיו:"]]],[["ובי\"ט שיולי קא משייל היכי הוה עובדא כי הא דההוא גברא דאייתי בוכרא לקמיה דרבא אפניא דמעלי יומא טבא הוה יתיב רבא וקא חייף רישיה דלי עיניה וחזייה למומיה א\"ל זיל האידנא ותא למחר","כי אתא למחר אמר היכי הוה עובדא א\"ל הוה שדיין שערי בהך גיסא דהוצא והוה איהו באידך גיסא בהדי דבעי למיכל עייל רישיה ופרטיה הוצא לשפותיה א\"ל דלמא את גרמת ליה א\"ל לא","ומנא תימרא דגרמא אסור דתניא (ויקרא כב, כא) מום לא יהיה בו אין לי אלא שלא יהיה בו מום מניין שלא יגרום לו על ידי דבר אחר שלא יביא בצק או דבלה ויניח לו על גבי האזן כדי שיבא הכלב ויטלנו ת\"ל (ויקרא כב, כא) כל מום אמר מום ואמר כל מום:","\u0001מתני׳\u0002 בהמה שמתה לא יזיזנה ממקומה ומעשה ושאלו את רבי טרפון עליה ועל החלה שנטמאת ונכנס לבית המדרש ושאל ואמרו לו לא יזיזם ממקומם:","\u0001גמ׳\u0002 לימא תנן סתמא דלא כר' שמעון (דתנן) ר' שמעון אומר מחתכין את הדלועין לפני הבהמה ואת הנבלה לפני הכלבים ר' יהודה אומר אם לא היתה נבלה מערב שבת אסורה","אפילו תימא ר' שמעון מודה ר' שמעון בבעלי חיים שמתו שאסורין","הניחא למר בר אמימר משמיה דרבא דאמר מודה היה רבי שמעון בבעלי חיים שמתו שאסורין שפיר אלא למר בריה דרב יוסף משמיה דרבא דאמר חלוק היה רבי שמעון אפילו בבעלי חיים שמתו שמותרים מאי איכא למימר","תרגומה זעירי בבהמת קדשים דיקא נמי דקתני עליה ועל החלה שנטמאת מה חלה דקדישא אף בהמה דקדישא","אלא טעמא דקדישא הא דחולין שריא הניחא למר בריה דרב יוסף משמיה דרבא דאמר חלוק היה ר' שמעון אף בבעלי חיים שמתו שמותרין שפיר אלא למר בר אמימר משמיה דרבא דאמר מודה היה רבי שמעון בבעלי חיים שמתו שאסורין מאי איכא למימר","הכא במאי עסקינן במסוכנת ודברי הכל:","\u0001מתני׳\u0002 אין נמנין על הבהמה לכתחלה ביו\"ט אבל נמנין עליה מערב יום טוב ושוחטין ומחלקין ביניהם:","\u0001גמ׳\u0002 מאי אין נמנין אמר רב יהודה אמר שמואל אין פוסקין דמים לכתחלה על הבהמה ביו\"ט היכי עביד אמר רב מביא שתי בהמות ומעמידן זו אצל זו ואומר זו כזו","תניא נמי הכי לא יאמר אדם לחברו הריני עמך בסלע הריני עמך בשתים אבל אומר לו הריני עמך למחצה ולשליש ולרביע:"],[[0,"וביו\"ט שיולי קא משייל","פעמים שהיה טרוד בעיו\"ט ומשראה המומין אומר לו לך עכשיו ובא למחר והיה שואלו על המום איך בא לו מפני שנחשדו כהנים על הבכורות להטיל בהם מום כדתנן (בכורות דף לה.) כל המומין הראויים לבא בידי אדם רועי ישראל נאמנים רועי כהנים אין נאמנים וצריך להביא עדים שמאליו בא לו:"],[0,"ההוא גברא","כהן היה:"],[0,"דלי עיניה","נשא עיניו:"],[1,"הוה שדיין שערי בהך גיסא דהוצא","שעורין היו מושלכים מעבר לגדר והבכור היה לעבר השני:"],[1,"הוצא","גדר של קוצים:"],[1,"ופרטיה לשפותיה","קרע שפתיו והיא שנויה במומי הבכור שפתו שנפגמה שלעולם הוא ניכר:"],[1,"את גרמת ליה","מדעת נתת השעורים שם שנחשדתם על הבכורות מפני טורח הגדול והיציאה שהוטל עליו שישראל אינו מטפל בו אלא שלשה חדשים ונותנו לכהן:"],[2,"לא יהיה","קרי ביה לא יהיה:"],[2,"ה\"ג מום לא יהיה בו אין לי אלא כו'","אי כתב מום ולא כתב כל לא היה לי לאסור גרמא אלא נתינת מום ממש אבל עכשיו אמר מום לאסור נתינת מום ממש ואמר כל מום לאסור גרמא:"],[3,"מתני' חלה שנטמא'","אינה ראויה לכהן היום דהא באכילה אסורה לעולם ובהסקה או לתתה לכלבו בי\"ט אסור דאין מבערין קדשים טמאים מן העולם ביו\"ט ואפילו ע\"י אכילת בהמה דקי\"ל שאין שורפין קדשים בי\"ט ולא תימא דוקא שריפה משום דהבערה שלא לצורך היא דהא אין מדליקין בשמן שרפה ביו\"ט הבערה לצורך היא דהדלקת נר ביו\"ט לצורך אכילה היא ומותרת אפילו הכי בשמן שרפה לא והוא שמן תרומה שנטמאת דגזרת הכתוב היא שאין קדשים טמאים מתבערים ביו\"ט דרחמנא אחשבה להבערתן דכתיב באש ישרף (ויקרא ז׳:י״ז) הלכך מלאכה היא:"],[4,"גמ' ואת הנבלה לפני הכלבים","וכשנתנבלה בשבת קאמר מדפליג רבי יהודה עלה ואמר אם לא היתה נבלה מע\"ש אסורה לפי שאינה מן המוכן:"],[5,"בבעלי חיים","בהמה בריאה בין השמשות:"],[5,"שמתו","בי\"ט:"],[5,"שאסורים","וכי שריא במסוכנת בין השמשות דדעתיה עלויה להאכילה לכלבים:"],[7,"בבהמת קדשים","שאסורה בהנאה וטעונה קבורה ואינה נפדית דבעיא העמדה והערכה אי נמי אין פודין קדשים להאכיל לכלבים ואפילו למאן דאמר פודין בי\"ט לא פרקי לה הלכך לא חזיא:"],[8,"אלא טעמא דקדשים","כיון דדיקא מתני' למתנייה דומיא דחלה על כרחך שמעינן מינה דדוקא בקדשים נקט ופרכינן אלא טעמא דקדשים בתמיה:"],[8,"הא דחולין שריא","לכלבים ולא מתסרא משום מוקצה:"],[8,"הניחא למר בריה דרב יוסף כו'","איכא למימר מתני' דדיקא לאשמועינן דחולין שריא ר' שמעון היא דלית ליה מוקצה:"],[8,"אלא למר בריה דאמימר","מני לא ר' יהודה ולא ר' שמעון:"],[9,"הכא במאי עסקינן במסוכנת","לעולם ר' שמעון היא ומתני' במסוכנת דשרי ר' שמעון בה ואמר מחתכין את הדלועין כו' הלכך טעמא דקדשים לא יזיזנה הא דחולין שריא:"],[10,"מתני' אין נמנין","בגמ' מפרש מאי היא:"],[10,"אבל","שוחט הוא הטבח בלא פסוק דמים ומחלקין אותה ביניהם ולמחר יפסוק להם דמיה:"],[11,"גמ' אין פוסקין דמים","דמקח וממכר בשבת וביו\"ט אסור בספר עזרא (נחמיה י״ג:ט״ז):"],[11,"היכי עביד","דקתני שוחט הוא ומחלקין ביניהן היכי עביד שידעו למחר כמה היתה שוה לפסוק דמיה:"],[11,"מביא","להם ביו\"ט שתי בהמות שוות ויאמר ראו שזו כזו ולמחר שמין את הנותרת:"],[12,"הריני עמך","נמנה על בהמה זו בסלע והיינו כשמואל דאמר אין פוסקים לה דמים ביו\"ט:"]],[[3,"","ועל החלה שנטמאת לא יזיזנה ממקומה. פרש\"י דלמאי חזי אי לאכילה הא טמאה היא אי להסקה תחת תבשילו אין שורפין קדשים בי\"ט וכ\"ת יריצנה לפני כלבו כדאמרינן בפסחים (דף לב. ושם) גבי תרומת חמץ ומריצה לפני כלבו וי\"ל דנתינה לכלבו אע\"ג דאין כאן שום טורח זהו ביעורו וכשם שאין שורפין כך אין מבערים דרחמנא אחשבה להבערתו אע\"ג דהוי לצורך כדאמר אין מדליקין בשמן שרפה ביו\"ט ואע\"פ שהוא צורך יו\"ט להדליק לצורך אכילה וקשה דהא דאין שורפין קדשים ביו\"ט היינו טעמא משום טורח מלאכה לעשות אש ולעסוק בשריפתו אבל הכא כשנותן החלה לפני כלבו אין כאן שום טורח מלאכה לכן נ\"ל דלכך אין נותנה לפני כלבו משום דמצותה בשרפה כדאמר בשבת (דף כה.) כשם שמצוה לשרוף הקדשים שנטמאו כך מצוה לשרוף את התרומה שנטמאת אבל גבי תרומת חמץ דקאמר מריצה לפני כלבו לא מיירי כשנטמאה אלא משום ביעור חמץ ולכך אינה צריכה שריפה וכן משמע בתמורה (דף לג:) דחשיב לה לתרומה טמאה בהדי הנשרפין וקאמר הנשרפין לא יקברו ומ\"מ קשה דהיכי מדמה תרומה לקדשים למימר שאין שורפין תרומה ביו\"ט אימא שאני שריפת קדשים דלית בהו צורך הדיוט כלל לכך אין שורפין אבל תרומה דצורך הדיוט להסיק תחת תבשילו אימא ישרפנו בי\"ט תחת תבשילו דהא איכא צורך אוכל נפש ותירץ רבינו יצחק דתחת תבשילו הואיל ואית ביה נמי צורך גבוה בטל ליה צורך הדיוט אצל צורך גבוה והוי כאילו כולו של גבוה וראיה מדלעיל (ביצה דף יט.) דאמרינן נדרים ונדבות אין קרבין ביו\"ט ואפילו שלמים ואמאי והא שלמים צורך הדיוט אית בהו אלא ודאי בטיל ליה חלקו אצל חלק גבוה והוי כאילו כולם לגבוה הכא נמי גבי תרומה נימא הכי וקשה לפי זה דא\"כ צליית פסחים היכי דחיא י\"ט הא אית ביה צורך גבוה כי אם צלי אש ואמאי לא בטיל ליה אצל מצות גבוה את מה שיש להדיוט אלא ודאי י\"ל דאין קושיא מטעם זה דמצות גבוה לא בטלה חלק דהדיוט וגבי שלמים שאני דעיקר הקרבה בשביל גבוה וכהנים ובעלים משל גבוה קא זכו ומה שאין שורפין את התרומות היינו גזרה תרומה אטו קדשים:"],[7,"","[בבהמת קדשים. ורבי טרפון שהיה מסופק דס\"ד דשרי משום בזיון קדשים]:"]]],[["\u0001מתני׳\u0002 ר' יהודה אומר שוקל אדם בשר כנגד הכלי או כנגד הקופיץ וחכ\"א אין משגיחין בכף מאזנים כל עיקר:","\u0001גמ׳\u0002 מאי כל עיקר אמר רב יהודה אמר שמואל אפי' לשמרו מן העכברים אמר רב אידי בר אבין והוא דתליא בתריטא","ואמר רב יהודה אמר שמואל טבח אומן אסור לשקול בשר ביד ואמר רב יהודה אמר שמואל טבח אומן אסור לשקול בשר במים","ואמר רב חייא בר אשי אסור לעשות בית יד בבשר אמר רבינא ובידא שרי","אמר רב הונא מותר לעשות סימן בבשר כי הא דרבה בר רב הונא מחתך לה אתלת קרנתא","ר' חייא ור\"ש ברבי שוקלין מנה כנגד מנה ביום טוב כמאן לא כרבי יהודה ולא כרבנן אי כר' יהודה האמר שוקל אדם בשר כנגד הכלי או כנגד הקופיץ כנגד הכלי אין כנגד מידי אחרינא לא אי כרבנן הא אמרי אין משגיחין בכף מאזנים כל עיקר","אינהו דעבוד כר' יהושע דתניא ר' יהושע אומר שוקלין מנה כנגד מנה ביום טוב אמר רב יוסף הלכה כר' יהושע הואיל ותנן בבכורות כותיה","דתנן פסולי המוקדשין הנאתן להקדש ושוקלין מנה כנגד מנה בבכור","א\"ל אביי ודלמא לא היא עד כאן לא קאמר ר' יהושע הכא אלא דליכא בזיון קדשים אבל התם דאיכא בזיון קדשים לא","אי נמי עד כאן לא קאמרי רבנן התם אלא משום דלא מחזי כעובדין דחול אבל הכא דמחזי כעובדין דחול לא","למימרא דקפדי אהדדי והא הנהו שב בניתא דאתו לבי רבי ואשתכח חמש מנייהו בי ר' חייא ולא קפיד ר\"ש ברבי","אמר רב פפא שדי גברא בינייהו אי ר' חייא ור' ישמעאל בר' יוסי אי ר\"ש ברבי ובר קפרא:","\u0001מתני׳\u0002 אין משחיזין את הסכין ביום טוב אבל משיאה על גבי חברתה:","\u0001גמ׳\u0002 אמר רב הונא לא שנו אלא במשחזת של אבן אבל במשחזת של עץ מותר אמר רב יהודה אמר שמואל הא דאמרת של אבן אסור לא אמרן אלא לחדדה אבל להעביר שמנוניתה מותר מכלל דבשל עץ אפילו לחדדה נמי מותר","איכא דמתני לה אסיפא בשל עץ מותר אמר רב יהודה אמר שמואל הא דאמרת בשל עץ מותר לא אמרן אלא להעביר שמנוניתה אבל לחדדה אסור מכלל דבשל אבן אפילו להעביר שמנוניתה אסור","איכא דמתני לה אמתניתין אין משחיזין את הסכין ביו\"ט אמר רב יהודה אמר שמואל לא שנו אלא לחדדה אבל להעביר שמנוניתה מותר מכלל דע\"ג חברתה אפילו לחדדה נמי מותר","ואיכא דמתני לה אסיפא אבל משיאה על גבי חברתה אמר רב יהודה אמר שמואל לא שנו אלא להעביר שמנוניתה אבל לחדדה אסור מכלל דבמשחזת אפילו להעביר שמנוניתה אסור","מאן תנא דבמשחזת אסור אמר רב חסדא דלא כר' יהודה דתניא אין בין יו\"ט לשבת אלא אוכל נפש בלבד ר' יהודה מתיר אף מכשירי אוכל נפש","א\"ל רבא לרב חסדא דרשינן משמך הלכה כרבי יהודה אמר ליה יהא רעוא דכל כי הני מילי מעלייתא תדרשון משמאי","אמר רב נחמיה בריה דרב יוסף הוה קאימנא קמיה דרבא והוה קא"],[[0,"מתני' ר' יהודה אומר שוקל אדם בשר","טבח המוכר בשר במשקל אע\"פ שאסור לשקול בליטרא דהיינו מעשה חול מותר הוא לשקול כנגד הכלי וכנגד הקופיץ סכין גדול שקוצבין בו בשר דאיכא שנוי ולא הוי מעשה דחול:"],[0,"אין משגיחין","אין מעיינין:"],[1,"גמ' מאי כל עיקר","מאי אתא לרבויי האי כל עיקר נימא וחכמים אוסרין:"],[1,"אפי' לשמרו מן העכברים","אין נותנין אותו במאזנים התלויין ביתד גבוה:"],[1,"והוא דתליא בתריטא","בטבעת שתולין אותן בה כששוקלין דמחזי כנותנו לשם משקל:"],[2,"טבח אומן","שיודע לכוין משקל כנגד משקל בידיו:"],[2,"אסור לשקול בשר ביד","לאחוז הליטרא בידו אחת והבשר בידו אחרת ולכוין דבחול נמי כיון דאומן הוא בכך אורחיה הכי:"],[2,"במים","שיש לו שנתות וסימנים בכלי ונותנין בו מים והסימנים מודיעין אותו כמה המים עולין למעלה בשביל ליטרא בשר שכבר שיערו לכך:"],[3,"בית יד","נקב לאחוז בו:"],[3,"ובידא שרי","לנקוב באצבעו שרי דלאו דרך חול הוא אבל בסכין דרך חול הוא כשמוכר בשר עושה בו בית יד ונותנו ללוקח להוליכו לביתו ובי\"ט צריך לשנות לעשות היכר שאין מקח וממכר מותר בו:"],[4,"סימן בבשר","שלא יחליפהו הנושאו:"],[4,"אתלת קרנתא","כשהיה משלח הבשר לביתו היה רגיל לעשות כל חתיכה בעלת שלש קרנות (כזה △) וכבר היו מכירין אנשי ביתו שזה היה סימן שלו:"],[5,"ר' חייא ורבי שמעון ברבי","כשהיו חולקין בשר ביניהם היו שוקלין אותה מנה כנגד מנה ביו\"ט:"],[5,"כנגד כלי אין","דבחול לאו הכי אורחיה אבל מנה כנגד מנה כך דרך כל החולקין:"],[6,"הואיל ותנן בבכורות כותיה","דאסור לשקול ולמכור בכור בעל מום ששחטו כהן בליטרא שלא לעשות מעשה חול בקדשים דבזיון הוא וקתני דמנה כנגד מנה ויודע כמה משקל ראשונה ושוקל כנגדה מותר אלמא לאו עובדא דחול חשיב ליה:"],[7,"דתנן פסולי המוקדשין הנאתן להקדש ושוקלין מנה כנגד מנה בבכור","סיפא דמתני' נקט ורישא הכי איתא כל פסולי המוקדשין נמכרים באטליז ונשקלים בליטרא חוץ מן הבכור והמעשר שהנייתן לבעלים אבל פסולי המוקדשין הנייתן להקדש ושוקלין מנה כנגד מנה בבכור וכן פירושה כל קדשים בעלי מומים שנפדו במומן אף על פי שעדיין מקצת קדושה עליהן שאסרן הכתוב בגיזה ועבודה כדאמרינן בבכורות (דף טו.) תזבח ולא גיזה וכו' אפילו הכי נוהגין מעשה חולין בהן בזו שנשחטין באטליז ונמכרין באטליז בליטרא חוץ מן הבכור והמעשר שהניית מכירתן ביוקר אינה להקדש אלא לבעלים לפי שאין להם פדיון במומם להיות דמיהן נכנסין לקדושתן דבבכור נאמר לא תפדה ובמעשר נאמר לא יגאל (ויקרא כז) אלא נאכלין לבעלים במומן הלכך אין נוהגין בהן מעשה חולין במכירת בשרם כשנפל בהן מום ושחטום הבעלים בעלים דבכור כהן ובעלים דמעשר ישראל אבל שאר פסולי המוקדשים הניית מכירתן ביוקר להקדש היא ואע\"פ שכבר נפדו קודם שחיטה דהא קודם פדייה אין נשחטין דבעי העמדה והערכה אפילו הכי הניית מכירתן ביוקר להקדש שלפי מה שיודע שהנאתו יפה הוא מוסיף פדיונו מתחלתו לפיכך מבזין אותו למוכרו באטליז שהכל פונים שם ליקח בשר:"],[7,"ושוקלין מנה כנגד מנה","כשמוכרו בתוך הבית אלמא כי האי גונא לאו משקל הוי:"],[8,"לא היא","לא סבירא להו לרבנן דבכורות כר' יהושע בי\"ט ולא ר' יהושע ס\"ל בבכור דשרי:"],[9,"ע\"כ לא קאמרי רבנן התם אלא דלא עביד מעשה דחול","דהתם מכירה היא ואין דרך לשקול בשר הנמכר במנה כנגד מנה:"],[9,"אבל הכא","גבי רבי חייא ור\"ש ברבי קא עבדי עובדין דחול דהא חלוקה היא וכן דרך כל החולקין ולא סבירא להו לרבנן דבכורות כר' יהושע:"],[10,"ומי קפדי אהדדי","ר' חייא ור\"ש ברבי לחלוק בשר במשקל והלא מוותרין זה לזה ונוטלין זה משל זה משום חבה:"],[10,"דהנהו שב בניתא","שבעה דגים שבאו לרבי ונמצא שנטל רבי חייא חמש והוליכן לביתו:"],[10,"ולא קפיד רבי שמעון ברבי","לומר משל אבי הוא נזון יותר ממני:"],[11,"אי ר' חייא ור' ישמעאל בר' יוסי","היו אותן שחלקו שהן היו רגילין ליקח זה עם זה אי ר\"ש ברבי ובר קפרא:"],[12,"מתני' אין משחיזין","אגוייזי\"ר בלע\"ז:"],[12,"אבל משיאה על גבי חברתה","דמשני כדרך חול:"],[13,"גמ' משחזת של אבן","דמתקנת ליה שפיר דמחזי כמתקן בחול:"],[13,"מכלל דבשל עץ כו'","גמרא קא דייק מדאוקי רב יהודה איסורא בשל אבן בלחדדה מכלל דבשל עץ אף לחדדה שרי דמאי דאסר רב הונא בשל אבן שרי דכוותה בשל עץ:"],[14,"איכא דמתני לה","להא דרב יהודה:"],[14,"אסיפא","דמלתיה דרב הונא:"],[15,"איכא דמתני לה","להא דרב יהודה אמתני' ולאו אמלתיה דרב הונא:"],[15,"לחדדה","הוי תקון להעביר שמנונית אינו אלא כהדחה בעלמא:"],[17,"מתיר אף מכשירי אוכל נפש","וטעמא משום דדריש יעשה לכם לכל צרכיכם:"],[18,"דרשינן משמך","נדרוש משמך:"]],[]],[["מעבר לסכינא אפומא דדקולא ואמרי ליה לחדדה קא עביד מר או להעביר שמנוניתה ואמר לי להעביר שמנוניתה וחזיתי לדעתיה דלחדדה קא עביד וקסבר הלכה ואין מורין כן","ואמר אביי הוה קאימנא קמיה דמר והוה קא מעבר סכינא אשפתא דרחיא ואמרי ליה לחדדה קא בעי מר או להעביר שמנוניתה ואמר לי להעביר שמנוניתה וחזיתי לדעתיה דלחדדה קא עביד וקסבר הלכה ואין מורין כן","איבעיא להו מהו להראות סכין לחכם ביום טוב רב מרי בריה דרב ביזנא שרי ורבנן אסרי ורב יוסף אמר תלמיד חכם רואה לעצמו ומשאילה לאחרים","ואמר רב יוסף סכין שעמדה מותר לחדדה ביום טוב והני מילי הוא דפסקא אגב דוחקא","דרש רב חסדא ואיתימא רב יוסף אחד סכין שנפגמה ואחד שפוד שנרצם ואחד גריפת תנור וכירים ביום טוב באנו למחלוקת ר' יהודה ורבנן דתניא אין בין יו\"ט לשבת אלא אוכל נפש בלבד ר' יהודה מתיר אף מכשירי אוכל נפש","מ\"ט דת\"ק אמר קרא (שמות יב, טז) הוא לבדו יעשה לכם הוא ולא מכשיריו ור' יהודה אמר קרא לכם לכם לכל צרכיכם","ות\"ק הא כתיב לכם אמר לך ההוא לכם ולא לנכרים","ואידך נמי הא כתיב הוא אמר לך כתיב הוא וכתיב לכם ולא קשיא כאן במכשירין שאפשר לעשותן מערב יו\"ט כאן במכשירין שאי אפשר לעשותן מערב יו\"ט","אמר רב יהודה אמר שמואל שפוד שנרצף אסור לתקנו ביו\"ט פשיטא לא צריכא דאע\"ג דמפשיט בידיה","אמר רב יהודה אמר שמואל שפוד שצלו בו בשר אסור לטלטלו ביו\"ט רב אדא בר אהבה אמר רב מלכיו שומטו ומניחו בקרן זוית","אמר רב חייא בר אשי אמר רב הונא והוא שיש עליו כזית בשר רבינא אמר אף על פי שאין עליו בשר מותר לטלטלו מידי דהוה אקוץ ברשות הרבים","אמר רב חיננא בריה דרב איקא שפוד שפחות וגומות רב מלכיו","בלורית אפר מקלה וגבינה רב מלכיא","רב פפא אמר מתניתין ומתניתא רב מלכיא שמעתתא רב מלכיו וסימניך מתניתין מלכתא מאי בינייהו איכא בינייהו שפחות:","\u0001מתני׳\u0002 לא יאמר אדם לטבח שקול לי בדינר בשר אבל שוחט ומחלק ביניהם:","\u0001גמ׳\u0002 היכי עביד כי הא"],[[0,"מעבר לסכינא אפומא דדקולא","משפשף סכין על פי הסל:"],[0,"הלכה","כרבי יהודה ומותר כל איש לעשות אבל אין מורין לרבים כן שלא יזלזלו אף בשאפשר לעשותו מבעוד יום דכל הני דשרינן כגון שנתקלקלו ביו\"ט או שהיה אתמול טרוד כדאמרינן לקמן דלא התיר ר' יהודה אלא במכשירין שאי אפשר לעשותן מערב יו\"ט:"],[2,"מהו להראות","הטבח סכין לחכם בי\"ט לבדוק שהטילו חכמים על הטבחים להראות סכין לחכם קודם שישחוט שום בהמה ומהו לעשות כן בי\"ט מי מחזי כעובדא דחול דאוושא מלתא שדעתו למכור באטליז או לא מחזי:"],[2,"רואה לעצמו","בביתו סכין שלו דלא אוושא מלתא:"],[3,"שעמדה","מחריפות שלה שאינה חותכת יפה אבל לא נפגמה:"],[3,"מותר לחדדה ביו\"ט","ואע\"ג דמאתמול ומשלשום התחילה לקלקל ולילך דלא הוה ליה לאסוקי אדעתיה מאתמול דסבר לא צריכנא אבל נפגמה מאתמול לא הוי שרי דמוכחא קלקול שלה והוה ליה למעבד מאתמול:"],[3,"והני מילי דפסקא אגב דוחקא","אבל אם אינה חותכת כלל אסור לחדדה דטרחא יתירא הוא:"],[4,"אחד סכין שנפגמה ואחד שפוד שנרצם","בי\"ט אשפויינטי\"ר בלע\"ז שנשבר ראשו:"],[4,"ואחד גריפת תנור","שנפל לתוכו מן הטיח שלו ולא היה יודע מבעוד יום:"],[4,"באנו למחלוקת ר' יהודה ורבנן","נכנסנו בדבר זה למחלוקתן שממחלוקתן אנו יכולים ללמוד שאף אלו ממכשירי אוכל הן:"],[8,"שפוד שנרצף","נמעך שדרסו עליו ונעקם אבל לא נשבר:"],[8,"אסור לתקנו ביו\"ט","שהרי יכול להשתמש בו כמו שהוא וטרחא דלא צריך הוא:"],[8,"ואע\"ג דמפשיט בידיה","שמתפשט בידים ואינו צריך להכות עליו בפטיש:"],[9,"שפוד שצלו בו","בשר ביו\"ט:"],[9,"אסור לטלטלו","מיד לאחר שנצלה הצלי לפי שנמאס ומוקצה וכבר נעשה צורך יו\"ט:"],[9,"שומטו ומניחו בקרן זוית","שומטו מלפניו מהר בגרירא וטלטול מן הצד עד שיעבירו מלפניו לקרן זוית אבל לא טלטול גמור:"],[10,"שרי לטלטולי","בטלטול גמור ולסלקו שלא יזוקו בו אנשי ביתו:"],[10,"מידי דהוה אקוץ ברה\"ר","דאמר בפרק כירה שהסיקוה (שבת דף מב.) דמותר להוליכה פחות פחות מד' אמות עד שמסלקנה לצדי רה\"ר כדי שלא תזיק:"],[11,"שפוד שפחות וגומות רב מלכיו","אלו שלש הלכות רב מלכיו אמרן ולא רב מלכיא מפני ששמותיהן דומין זה לזה ויש שמחליפין שמועה של זה בשל זה נתנו בהם סימן לסדר השמועות שפוד הא דאמרן שפחות משנה היא בכתובות ר\"א אומר אפי' הכניסה לו מאה שפחות כופה לעשות בצמר שהבטלה מביאה לידי זמה ואמר רב מלכיו הלכה כר\"א גומות שמעתא היא ולא נאמרה על המשנה ולענין שתי שערות דאם נמצאו לה גומות של מקום שער אע\"פ שאין שם שער גדולה היא וחולצת דאין גומא אא\"כ היה בה שער אלא שנשרו:"],[12,"בלורית","במס' ע\"ז ועל ברייתא נאמרה הא דרב מלכיא לפרושא לברייתא דת\"ר כותי המסתפר מישראל כיון שהגיע לבלוריתו שומט את ידו מפני שהכותי כשהוא מסתפר מניחה לשם ע\"ז ואמר עלה וכמה אמר רב מלכיא שלש אצבעות לכל רוח ורוח לכל סביבותיה לא יגע שאם יגלח וילך עד הבלורית נמצא מניח לו בלוריתו ותיקנה לו לשם ע\"ז:"],[12,"אפר מקלה","שמעתא היא במסכת מכות אמר רב מלכיא לא יתן אדם אפר מקלה על גבי מכתו מפני שנראה ככתובת קעקע:"],[12,"גבינה","אפירושא דמתניתין אתמר במס' ע\"ז מפני מה אסרו גבינות במשנתנו ואמר רב מלכיא מפני שמחליקין פניה בשומן חזיר:"],[13,"מתניתין ומתניתא רב מלכיא","אסימנא דאתנח ברב מלכיא פליג רב פפא:"],[13,"שפחות","דמתניתין היא ומשוית ליה ברב מלכיו לאו דידיה היא דכל מתניתין ומתניתא דאית בהו רב מלכיא אמר פירושן אבל שמעתתא דאמרת ברב מלכיו כגון שפוד וגומות דידיה נינהו:"],[14,"מתני' שקול לי בדינר בשר","שאסור להזכיר שם דמים:"],[14,"אבל שוחט","הוא בלא פסוק דמים והן חולקין ביניהן:"],[15,"גמ' היכי עביד","כשאינו רוצה ליקח כל הבהמה ולא מחצה ולא שליש ולא רביע אלא בדינר או בשנים מה יאמר לו:"]],[[4,"","גריפת תנור וכירים. פר\"י אשוויי גומות ולא נהירא דאם כן לא הוי דומיא דהני אחריני דחשיבי משום דהוי תקון כלי לכן נ\"ל דמיירי בתנור חדש ועדיין יש בו אבנים ועפר שלא פינו וכשיסיר אותם אבנים ועפר הויין כמו גמר מלאכתן וחייב משום מכה בפטיש דכל גמר מלאכה חייב משום מכה בפטיש ומכל מקום קשה דבלא טעמא דמשום מכה בפטיש תיפוק ליה דהוי אסור משום מוקצה דאפר ואבנים שבתוכו מוקצות הן ומכאן אומר ריצב\"א דטלטול מוקצה התירו משום אוכל נפש ומכאן יש להביא ראיה למה דאמר בפ\"ק (דף יב:.):"],[10,"","רבינא אמר וכו' מידי דהוה אקוץ ברשות הרבים. דשרי לטלטל אצדדים אע\"ג דהוי מלאכה וקשה דמשמע הכא דרבינא אית ליה מוקצה מדקאמר מידי דהוה אקוץ ברה\"ר דאי לאו הכי הוה אסור מטעם מוקצה ובפרק מי שהחשיך (שבת דף קנז.) משמע דאית ליה כר' שמעון דלית ליה מוקצה דפליגי התם רב אחא ורבינא חד אמר לקולא וחד אמר לחומרא ובכל מקום רב אחא לחומרא ורבינא לקולא וי\"ל דהכא קאמר רבינא אליבא דרב יהודה אמר שמואל דאסר שפוד לטלטלו אבל איהו ס\"ל דשרי אבל קשה מדשמואל אדשמואל דהתם פרק מי שהחשיך אמר כר' שמעון דלית ליה מוקצה גבי כרכי דזוזי והכא משמע דאית ליה מוקצה וי\"ל דשאני שפוד דלאחר מלאכתו אין כאן תורת כלי עליו ולהכי אוסר שמואל דיש עליו תורת מוקצה ולעולם ס\"ל כרבי שמעון: [גם אקושיא דרבינא יש לתרץ כך. ת\"י]:"],[13,"","איכא בינייהו שפחות. גבי משנה אתמר בכתובות (דף סא:) וא\"ת א\"כ נימא אפר מקלה דהיינו שמעתא במכות (דף כא:) דלרב פפא רב מלכיו אמרה ולרב חיננא רב מלכיא אמרה וי\"ל דה\"פ שפחות ושכנגדה פירוש האמצעית דהיינו אפר מקלה אי נמי ה\"פ מתניתין ומתניתא דוקא רב מלכיא ולא רב מלכיו אבל שמעתתא יש מהם רב מלכיו ולעולם רב מלכיא אמרה אותה שמעתא דאפר מקלה ולכך אינו נותן סימן רק למתניתא:"]]],[["דבסורא אמרי תרטא ופלגו תרטא בנרש אמרי חלקא ופלגו חלקא בפומבדיתא אמרי אוזיא ופלגו אוזיא בנהר פקוד ובמתא מחסיא אמרי רבעא ופלגו רבעא:","\u0001מתני׳\u0002 אומר אדם לחברו מלא לי כלי זה אבל לא במדה ר' יהודה אומר אם היה כלי של מדה לא ימלאנו מעשה באבא שאול בן בטנית שהיה ממלא מדותיו מערב יו\"ט ונותנן ללקוחות ביו\"ט","אבא שאול אומר אף במועד עושה כן מפני ברורי המדות וחכמים אומרים אף בחול עושה כן מפני מצוי המדות:","\u0001גמ׳\u0002 מאי אבל לא במדה אמר רב יהודה אמר שמואל אבל לא בכלי המיוחד למדה אבל כלי העומד למדה ימלאנו ואתא ר' יהודה למימר אפילו כלי העומד למדה לא ימלאנו","אלמא גבי שמחת יום טוב ר' יהודה לחומרא ורבנן לקולא והא אפכא שמעינן להו דתנן רבי יהודה אומר שוקל אדם בשר כנגד הכלי וכנגד הקופיץ וחכמים אומרים אין משגיחין בכף מאזנים כל עיקר אלמא ר' יהודה לקולא ורבנן לחומרא קשיא דר' יהודה אדר' יהודה קשיא דרבנן אדרבנן","דר' יהודה אדר' יהודה לא קשיא התם בשאינו עומד למדה הכא בעומד למדה","דרבנן אדרבנן נמי לא קשיא התם קא עביד כדעבדין בחול הכא לא קא עביד כדעבדין בחול","רבא אמר מאי אבל לא במדה שלא יזכור לו שם מדה אבל כלי המיוחד למדה ימלאנו ואתא ר' יהודה למימר כלי המיוחד למדה לא ימלאנו","אלמא גבי שמחת יום טוב רבי יהודה לחומרא ורבנן לקולא והא אפכא שמעינן להו דתנן רבי יהודה אומר שוקל אדם בשר כנגד הכלי וכנגד הקופיץ וחכמים אומרים אין משגיחין בכף מאזנים כל עיקר אלמא ר' יהודה לקולא ורבנן לחומרא קשיא דר' יהודה אדר' יהודה קשיא דרבנן אדרבנן","דר' יהודה אדר' יהודה ל\"ק התם בשאינו מיוחד למדה הכא מיוחד למדה דרבנן אדרבנן נמי לא קשיא התם קא עביד כדעבדין בחול הכא לא קעביד כדעבדין בחול דעבדי אינשי דמקרבי חמרא במנא דכילא ושתו:","מעשה באבא שאול בן בטנית: תנא אף במועד עושה כן מפני בטול בית המדרש","תנו רבנן הוא כנס שלש מאות גרבי יין מברורי המדות וחבריו כנסו שלש מאות גרבי שמן ממצוי המדות והביאום לפני הגזברים לירושלים","אמרו להם אי אתם זקוקים לכך אמרו להם אף אנו אין רצוננו בכך","אמרו להם הואיל והחמרתם על עצמכם עשו מהם צרכי רבים דתניא גזל ואינו יודע למי גזל יעשה בהם צרכי רבים מאי נינהו אמר רב חסדא בורות שיחין ומערות","אדבריה רב חסדא לרבנא עוקבא ודרש לא ימדוד אדם שעורים ויתן לפני בהמתו ביו\"ט אבל קודר הוא קב או קבים ונותן לפני בהמתו ואינו חושש והנחתום מודד תבלין ונותן לתוך קדרתו כדי שלא יקדיח תבשילו","אמר רב ירמיה בר אבא אמר רב מודדת אשה קמח ביו\"ט ונותנת לתוך עיסתה כדי שתטול חלה בעין יפה ושמואל אמר אסור והא תנא דבי שמואל מותר","אמר אביי השתא דאמר שמואל אסור ותנא דבי שמואל מותר"],[[0,"בסורא אמרי","דרכן לומר לטבח תן לי תרטא או פלג תרטא ובנרש אמרי חלקא או פלג חלקא ובפומבדיתא אמרי אוזיא. כל הטבחין היו מנתחין בהמותיהם בשוה כך וכך נתחים מן הבהמה ולאותן הנתחים קרו להו בסורא תרטא ובנרש חלקא ובפומבדיתא אוזיא ובנהר פקוד רבעא:"],[1,"מתני' אבל לא במדה","בגמ' מפרש לה ומאי פלוגתייהו:"],[1,"שהיה ממלא מדותיו כו'","שאין מודדין ביו\"ט:"],[2,"אף בחולו של מועד עושה כן","בגמ' מפרש טעמא ולא גרסינן במתני' מפני ברורי המדות ואית דגרס ליה והן העלאת הרתיחות ובגמרא מפרש:"],[2,"מפני מצוי המדות","כשהיה מוכר שמן היה לו מדות הרבה ומביאין הלקוחות כליהן ומודד לאיש ואיש במדה לעצמו ומתמצות והולכות לתוך כליהן כל הלילה:"],[3,"גמ' המיוחד למדה","שמודד ומוכר בו:"],[3,"העומד למדה","שכשישבר זה בא זה תחתיו אבל עדיין לא מדד בו:"],[3,"ואתא רבי יהודה למימר","כיון דהוא עצמו מדה ולכך עשוי וכדי מדה מחזיק לא ימלאנו דמחזי שפיר כמודד ומוכר כעובדין דחול:"],[4,"כלי וקופיץ","אין עומדין לכך:"],[6,"כדעבדין בחול","במאזנים פעמים שאין הליטרא לפניו וכיון שיודע משקל כליו שוקל בו:"],[6,"לא קא עביד כעובדין דחול","דעדיין לא יצא טבעו של כלי זה למדה:"],[7,"שם מדה","רבעא או לוג אלא כך יאמר לו סתם כלי זה מלא לי:"],[9,"הכא לא קא עביד כדעבדין בחול","שדרך לקוחות לומר תן לי לוג ואין דרכן לומר כלי זה מלא לי בדרך מקח אלא בדרך הלואה או מתנה ואע\"ג דמיוחד למדה:"],[9,"עבידי אינשי דמקרבי חמרא","לחבריהם:"],[9,"במנא דכילא","של מדה:"],[10,"תנא אף במועד עושה כן מפני בטול בית המדרש","שהיה חכם גדול ובאים רבים לשאול הימנו ובמועד רבים עוסקים בתורה שאין טרודים במלאכה והיה ממלאן בלילה שאין זמן בית המדרש כדי שיהא פנוי ביום ולמאן דגרס במתני' מפני ברורי המדות מפרש הכי מפני בטול בית המדרש של באי מועד לא יהיה פנוי לשהות ולברר מדותיו שלא ירתיחו לפיכך ממלאן בלילה:"],[11,"הוא כנס כו'","משנתן יין בחבית כך וכך לוגין במדה ומכר ממנה עד שמכר חשבונו נמצא כל הנותר בחבית על ידי ברורין שהרתיח היין כשמוציאו ומעלה אופיא אישקומ\"א בלע\"ז ואין המדה מלאה והן נקראין ברורין לפי שמבררין אותן מן היין כששותה אי נמי על דקלישי וזיגי ושמן יש בו מצוי מפני שמודבק בשולי המדה ובדפנותיה וביין שכיחי ברורין ולא בשמן:"],[11,"וחבריו כנסו כו'","כדפרישית בברורין:"],[11,"לפני הגזברים","של הקדש לעשות בהן צרכי הקדש אם ירצו והם לא הקדישוה כסבורין אין יכולין להקדיש שאינו שלהם אי נמי יכולין הוה ליה גזל בעולה:"],[12,"אמרו להם חכמים אין אתם זקוקין לכך","הואיל ומתחלה לא נתכונתם לגזול שהלקוחות מוחלין על ידי טרדן ומרוצתם שאינם יכולין לשהות עוד וידעי וקא מחלי:"],[12,"אף אנו אין רצוננו לכך","לזה ליהנות משל אחרים:"],[13,"אמרו להם","חכמים א\"כ אין לכם לעשות הקדש אלא לעשות בהן צרכי רבים שהרי משל רבים היה ויהנו הבעלים מהן:"],[13,"ואין יודע למי גזל","שגזל אנשים הרבה:"],[13,"שיחין ומערות","שמתכנסין בהן מים ושותין מהן ובב\"ק (דף נ:) מפרש מאי בור ומאי שיח ומאי מערה:"],[14,"אדבריה","הנהיגו ומטייל עמו במבואות העיר:"],[14,"לא ימדוד אדם קב שעורין","אפילו ליתן לבהמתו שנראה כמודד למכור:"],[14,"אבל קודר הוא","בקב עצמו נוקב בכרי וממלאו שלא כדרך מדה לתת בידו לתוכו:"],[14,"קודר","לשון נוקב:"],[14,"נחתום","מבשל קדרות נמי קרוי נחתום:"],[14,"יקדיח","ישרוף אאורשי\"ר בלע\"ז:"],[15,"בעין יפה","שיעור חלה אחד מכ\"ד לכהן וכשאינה יודעת מדת עיסתה היא מקמצת ואומרת אין כאן כל כך אבל כשיודעת מדת עיסתה יודעת מה תפריש ועינה יפה בה:"],[15,"תנא דבי שמואל","בתוספתא שסידר שמואל מתנאים שלפניו כמו שסדרו רבי חייא ורבי אושעיא וכמו שסידר רבי את המשנה:"],[16,"השתא דאמר שמואל אסור","והוא שנה במשנתו מותר שמואל בשמעתיה דאמר אסור הלכה למעשה אתא לאשמועינן שהבא לשאול הלכה לעשות מעשה מורין לו אסור ואי חזינן איניש דעביד לא מחינן בידיה דהלכה דמותר ואין מורין כן:"]],[]],[["שמואל הלכה למעשה אתא לאשמועינן","תנו רבנן אין שונין קמח ביום טוב משום רבי פפייס ור' יהודה בן בתירא אמרו שונין ושוין שאם נפל לתוכן צרור או קיסם ששונין","תני תנא קמיה דרבינא אין שונין קמח ביום טוב אבל נפל צרור או קיסם בורר בידו אמר ליה כ\"ש דאסור דהוה ליה כבורר","דרש רבא בר רב הונא זוטי אפתחא דנהרדעא שונין קמח ביום טוב אמר להו רב נחמן פוקו ואמרו ליה לאבא שקילא טיבותך ושדי אחזרי פוק חזי כמה מהולתא הדרן בנהרדעא","דביתהו דרב יוסף נהלא קמחא אגבא דמהולתא אמר לה חזי דאנא רפתא מעליתא בעינא דביתהו דרב אשי נהלא קמחא אגבא דפתורא אמר רב אשי הא דידן ברתיה דרמי בר חמא ורמי בר חמא מרא דעובדא הוה ואי לאו דחזיא מבי נשא לא הוה עבדא:","\u0001מתני׳\u0002 הולך אדם אצל חנוני הרגיל אצלו ואומר לו תן לי ביצים ואגוזים במנין שכן דרך בעל הבית להיות מונה בתוך ביתו:","\u0001גמ׳\u0002 ת\"ר הולך אדם אצל רועה הרגיל אצלו ואומר לו תן לי גדי אחד או טלה אחד אצל טבח הרגיל אצלו ואומר לו תן לי כף אחת או ירך אחת אצל פטם הרגיל אצלו ואומר לו תן לי תור אחד או גוזל אחד אצל נחתום הרגיל אצלו ואומר לו תן לי ככר אחד או גלוסקא אחת","ואצל חנוני הרגיל אצלו ואומר לו תן לי עשרים ביצים או חמשים אגוזים עשרה אפרסקין וחמשה רמונים ואתרוג אחד ובלבד שלא יזכיר לו סכום מדה ר' שמעון בן אלעזר אומר ובלבד שלא יזכיר לו סכום מקח:","\u0001הדרן עלך אין צדין\u0002","מתני׳ \u0001המביא\u0002 כדי יין ממקום למקום לא יביאם בסל ובקופה אבל מביא הוא על כתפו או לפניו וכן המוליך את התבן לא יפשיל את הקופה לאחוריו אבל מביאה הוא בידו ומתחילין"],[[1,"אין שונין קמח","שרקדו מאתמול ובא לשנותו בנפה ליפותו אין שונין דאפשר לו מאתמול:"],[1,"שונין","דליכא טרחא ודבר הנראה הוא שזו היא פעם שניה ואין זה כמרקד לברור:"],[2,"תני תנא קמיה דרבינא אין שונין","ואפילו נפל לתוכן צרור או קיסם אלא בודק הקסמין והצרורות ובוררן בידיו:"],[2,"כל שכן דאסור","דמחזי כבורר ובורר אב מלאכה היא כהרקדה והשונה אינו מרקד שהרי נראה שהכל יוצא ואין כאן סובין:"],[3,"לאבא","לחברי:"],[3,"שקילא טיבותיך","אין אנו מחזיקין לך טובה בכך נטולה היא טובתך ומוטלת על הקוצים טיבותיך גרי\"ר בלע\"ז:"],[3,"מהולתא","נפות:"],[3,"הדרן בנהרדעא","שכולן יודעות שמותר:"],[4,"אגבא דמהולתא","באחורי הנפה כדי לשנות:"],[4,"רפתא מעליתא","אי את צריכה לשנות דשונין קמח ביום טוב:"],[4,"אגבא דפתורא","אחורי השלחן שיש לו תוך שקורין טורנרוייר\"א והיא היתה שונה הקמח על אחוריו משום שנוי:"],[4,"הא דידן","זו אשתי ברתיה דרמי בר חמא היא:"],[4,"מרא דעובדא","מדקדק במעשיו:"],[6,"רועה","זה המגדל בהמות ופעמים שמוכר מהן:"],[6,"הרגיל אצלו","שמתוך שרגיל אצלו מאמינו ונותנו לו בלא פסוק דמים:"],[6,"פטם","המפטם עופות לשון משמין:"],[7,"סכום מדה","קב או קבים:"],[7,"סכום מקח","דמים:"],[9,"מתני' המביא ממקום למקום","בתוך התחום או ע\"י ערוב:"],[9,"לא יביאם בסל ובקופה","לתת שלש וארבע בתוך קופה וישאם משום דנראה כמעשה דחול לשאת משאות:"],[9,"אבל מביא על כתפו","אחת או שתים דמוכח דלצורך י\"ט:"],[9,"או לפניו","בידו:"],[9,"וכן המוליך את התבן","להסק או לבהמה לא יפשיל קופה לאחריו דגנאי יו\"ט שנראה כמתכוין למלאכה רבה או להוליך למקום רחוק כדרך חול:"]],[[0,"","שמואל הלכה למעשה אתא לאשמועינן. פי' דאם יבא שום אדם לשאול לנו כיצד יעשה אומרי' לו הוראה לאסור אבל אם אנו רואין שום אדם שנוהג היתר בדבר אין אנו צריכין למחות בו ולפי זה לא פליג שמואל ארב דתרוייהו מודו לאסור למעשה מיהו בה\"ג פירש ושמואל הלכה למעשה אתא לאשמועינן ופליג אברייתא ופליג ארב ויש שפוסקין כשמואל ואע\"ג דהלכה כרב באסורי מ\"מ מדאמר סתמא דהש\"ס שמואל הלכה למעשה אתא לאשמועינן משמע דהלכה כותיה ויש פוסקין כרב משום דהלכה כרב באסורי וכ\"ש הכא דהא תנא [דבי] שמואל כותיה דרב ואומר הר\"ר שמואל מאייבר\"א דאפי' למ\"ד דהלכה כרב מ\"מ אסור לנו בזמן הזה למדוד משום ליטול חלה בעין יפה דדוקא בימיהן שהיו מפרישין חלה אחת מכ\"ד ונותנין לכהן שייך לומר דמותר משום עין יפה אבל אנו שאין מפרישין כי אם מעט אפילו מעיסה מרובה ואותו מעט נמי אינו נאכל אלא נשרף אין למדוד דלא שייכא סברא דקאמר הכא כדי שתטול חלה בעין יפה אלא יש לנו לשער מאומד שתהיה בריוח כשיעור משום הברכה וכן בפסח נמי יש ליזהר מלמדוד ביום טוב למצות וצריך לעשות פחות מכשיעור ולא ימדוד במדה שעשה למדוד בחול בצמצום אלא יפחות או יוסיף אם המדה קטנה:"],[4,"","אגבא דפתורא. פ\"ה אחורי השלחן כמו אגבא דמהולתא ואפשר לפרש ע\"ג השלחן ממש וחשיב שנוי לפי שדרך לרקד בעריבה ומ\"מ אין להתיר תחלת הרקדה על ידי שנוי דהא אשונין דברייתא קאי ורשב\"ם פירש דע\"י שנוי אין לחלק ויש לסמוך עליו לענין להתיר לשפחה נכרית תחלת הרקדה ע\"י שנוי אבל אנו לעצמנו אין לסמוך:"],[5,"","אצל חנוני הרגיל אצלו. בין הוא נכרי בין ישראל דאין לחלק רק היכא דאיכא חששא דמחובר או נולד:"],[7,"","שלא יזכיר לו סכום מדה. פי' רש\"י קב או קבים וסכום מקח שלא יאמר לו תן לי אגוזים בדינר אחד או בשנים וקשה דפשיטא דאסור ועוד אמאי קאמר סכום מדה ה\"ל למימר ובלבד שלא יזכיר מדה ותו לא לכן נ\"ל כר\"ח דגריס סכום מנין וקאי אלעיל וה\"פ אמרת דילך אדם אצל חנוני הרגיל אצלו ויאמר לו תן לי ה' אגוזים או י' אפרסקין ובלבד שלא יזכיר סכום מנין שלא יאמר לו תן לי י' אגוזים וכבר נתת לי ל' ואם כן אני חייב לך מ' בין הכל אבל רבי שמעון אומר ובלבד שלא יזכיר סכום מקח שלא יאמר לו תן לי אגוזים בששה פשיטין וכבר נתת לי כך ואם כן אני חייב לך מכל י\"ב פשיטין אבל סכום מנין שרי וכן איתא בתוספתא ובה\"ג מכאן יש ליזהר שלא להזכיר אפילו סכום מנין לפי שדומה למקח וממכר:"],[9,"","מתני' המביא כדי יין וכו' לא יביאם בסל. ותימה דאמרינן בשבת פ' מפנין (שבת דף קכו: ושם) מפנין ד' קופות או ה' וכ\"ש שיהא מותר בי\"ט וי\"ל דהתם מיירי שאינו יכול להוציא לחוץ ואין רואין אותו וע\"כ מותר והכא מיירי ביו\"ט שיכול להוציאו לחוץ ורואין אותו וע\"כ יהא אסור שהרואה אותו אומר לצורך חול מביא אותם ולהכי אסור ומ\"מ קשה דאמר אבל הוא מביא על כתפו אלמא משמע דמרבה בהלוכא עדיף וקאמר התם במסכת שבת למעוטי בהלוכא עדיף ויותר טוב להביאן בסל או בקופה בפעם אחת מלהביאן כל אחת בפני עצמה וי\"ל דלמה דפי' ניחא דהתם מיירי בשבת דלא הוי כעובדי דחול שאין מטלטל כי אם מזוית לזוית באותו בית ולכך קאמר למעוטי בהלוכא עדיף טפי משום טרחא יתירא אבל הכא מיירי ביו\"ט משום טרחא יתירא לא קפדינא אלא משום דמחזי דעביד כעובדי דחול וא\"כ עדיף טפי לאפושי בהלוכא ויעשה דרך שנוי כי היכי דלא לתחזי דעביד כעובדי דחול ופעמים נמי דאסור לאפושי בהלוכא אע\"ג דממעט במשאוי כיון שאין משנה מדרך חול:"]]],[["בערמת התבן אבל לא בעצים שבמוקצה:","\u0001גמ׳\u0002 תנא אם אי אפשר לשנות מותר","אתקין רבא במחוזא דדרו בדוחקא לדרו ברגלא דדרו ברגלא לדרו באגרא דדרו באגרא לדרו באכפא דדרו באכפא נפרוס סודרא עלויה ואם לא אפשר שרי דאמר מר אם א\"א לשנות מותר","אמר ליה רב חנן בר רבא לרב אשי אמור רבנן כמה דאפשר לשנויי משנינן ביומא טבא והא הני נשי דקא מליין חצבייהו מיא ביומא טבא ולא קא משניין ולא אמרינן להו ולא מידי","אמר ליה משום דלא אפשר היכא ליעבד דמליא בחצבא רבה תמלי בחצבא זוטא קא מפשא בהלוכא","דמליא בחצבא זוטא תמלי בחצבא רבה קא מפשי במשוי תכסייה בנכתמא זמנין דנפיל ואתי לאתויי תקטריה זמנין דמפסיק ואתי למקטריה תפרוס סודרא עלויה זמנין דמטמיש במיא ואתי לידי סחיטה הלכך לא אפשר","א\"ל רבא בר רב חנין לאביי תנן אין מטפחין ואין מספקין ואין מרקדין והאידנא דקא חזינן דעבדן הכי ולא אמרינן להו ולא מידי","אמר ליה ולטעמך הא דאמר (רבא) לא ליתיב איניש אפומא דלחיא דלמא מגנדר ליה חפץ ואתי לאתויי (ד' אמות ברה\"ר) והא הני נשי דשקלן חצבייהו ואזלן ויתבן אפומא דמבואה ולא אמרינן להו ולא מידי","אלא הנח להם לישראל מוטב שיהיו שוגגין ואל יהיו מזידין הכא נמי הנח להם לישראל מוטב שיהיו שוגגין ואל יהיו מזידין","והני מילי בדרבנן אבל בדאורייתא לא ולא היא לא שנא בדאורייתא ולא שנא בדרבנן לא אמרינן להו ולא מידי דהא תוספת יום הכפורים דאורייתא הוא ואכלי ושתו עד שחשכה ולא אמרינן להו ולא מידי:","ומתחילין בערמת התבן: אמר רב כהנא זאת אומרת מתחילין באוצר תחלה מני ר' שמעון היא דלית ליה מוקצה","אימא סיפא אבל לא בעצים שבמוקצה אתאן לר' יהודה דאית ליה מוקצה הכא בארזי ואשוחי עסקינן דמוקצה מחמת חסרון כיס ואפילו רבי שמעון מודה","איכא דמתני לה אסיפא אבל לא בעצים שבמוקצה אמר רב כהנא זאת אומרת אין מתחילין באוצר תחלה מני רבי יהודה היא דאית ליה מוקצה אימא רישא מתחילין בערמת התבן אתאן לר\"ש דלית ליה מוקצה התם בתבנא סריא","תבנא סריא הא חזי לטינא דאית ביה קוצים:"],[[0,"ומתחילין בערמת התבן","להסק ואע\"פ שלא זמנה מבע\"י ולא היה רגיל להסיק ממנה והשתא משמע דלית ליה מוקצה:"],[0,"אבל לא בעצים שבמוקצה","רחבה שאחורי הבתים קרויה מוקצה על שם שהיא מוקצה לאחור ואין נכנסים ויוצאין בה תדיר ושם נותנין עצים וכל דבר שאין דעתו ליטול עד זמן מרובה ובגמרא פריך סיפא לרישא דהשתא משמע דאית ליה מוקצה:"],[1,"גמ' ואם אי אפשר לשנות","כגון שזמן אורחים הרבה וצריך להביא הרבה ביחד מותר:"],[2,"דדרו בדוחקא","משאוי שאדם יחיד נושא על כתפו בחול בטורח אם בא לשאת אותו בי\"ט לצורך י\"ט כגון חבית או שק מלא פירות ישאנו בי\"ט ברגלא עתר שקורין פורק\"א כדרכי נושאי מלח למכור מפני שצריך לשנות וכשהוא משנה ישנה להקל משאו ולא להרבות טורח בי\"ט ועתר זה נוח הוא לשאת בו משא כבד וכשנושא בו חבית הנשאת בכתף משנה להקל הוא:"],[2,"דדרו ברגלא","משוי חבית גדולה שרגילין לשאת אותה ברגלא:"],[2,"לדרו באגרא","ישאוה בי\"ט בשני בני אדם במוט על כתפיהם דהיינו נמי שנוי להקל:"],[2,"דדרו באגרא","במוט על כתפיהם לדרו בי\"ט לאותו משוי באכפא במוט בידיהם משום שנוי ואע\"פ שאינו להקל מ\"מ שנוי הוא ואינו מרבה טורח בשנויו:"],[2,"נפרוס סודרא","קל הוא ואינו מכביד ושנוי הוא בעלמא ולהצנע:"],[2,"ואם אי אפשר לשנות","שאין לו סודר לכסותו:"],[3,"מליין מיא","שואבות מים מן הנהר:"],[5,"תכסייה בנכתמא","כסוי של עץ העשוי לכדין:"],[5,"זמנין דמפסיק","שצריך לקושרו שלא יפול בדרך וזמנין דמפסיק בהליכתו ואתי למקשריה וקשר העשוי להתקין אב מלאכה הוא:"],[5,"דמטמיש במיא","שנשרה במים:"],[6,"אין מטפחין","משום שיר או משום אבל:"],[6,"מטפחין","ידיו זו לזו:"],[6,"מספקין","כף על ירך:"],[6,"מרקדין","ברגל וכולם נאסרו משום שבות גזרה שמא יתקן כלי שיר בפרק משילין (לקמן ביצה דף לו:):"],[7,"אפומא דלחיא","לחי המתיר במבוי בשבת:"],[7,"דלמא מגנדר ליה חפץ","ברה\"ר חוץ ללחי:"],[7,"ואתי לאתויי","מתוך שאינו במבוי מקורה להכיר שזה רה\"ר וזה רה\"י ומביאו: וקא מגנדר חצבייהו ומייתי להו לא גרסי':"],[7,"ולא אמרינן להו ולא מידי","ואע\"ג דעברן אדרבנן דאמור לא ליתיב ואינהו יתבן:"],[8,"הנח להם","בדבר שהרגילו בו ולא יחזרו בהם:"],[8,"מוטב שיעשו שוגגין ואל יעשו מזידין","לעבור כשידעו ולא יניחו בכך:"],[9,"והני מילי","דהנח להם לישראל:"],[9,"בדרבנן","היכא דארגילו למעבר אדרבנן כי הנך דמטפחין והנך דיתבן אפומא דלחיא:"],[9,"תוספת יום הכפורים","שצריך להתחיל ולהתענות מבעוד יום דאורייתא היא דנפקא לן (יומא דף פא:) מועניתם את נפשותיכם בתשעה:"],[9,"ואכלי ושתו עד שחשכה","גרס ולא גרס משחשכה:"],[10,"באוצר","בדבר האצור שהיה מוקצה לאוצרו לזמן ארוך כהאי גוונא דסתמא אוצרין אותו לבהמה:"],[11,"ארזי ואשוחי","אין אדם מסיק אותן דעומדין לבנין:"],[11,"אשוחי","ארז נקבה:"],[11,"דמוקצה מחמת חסרון כיס נינהו","שדמיה יקרין:"],[12,"דמתני לה","לדרב כהנא:"],[12,"תבנא סריא","נרקב ומסריח שאין ראוי למאכל בהמה וסתמיה לעצים ולא לאכילה והיינו לאוצר:"],[13,"לטינא","לטיט ללבון לבנים:"],[13,"דאית ביה קוצים","ואין יכול לגבלו בידיו וברגליו:"]],[[2,"","דדרו ברגלא. פי' בעתר שקורים פורק\"א ועשוי כמין רגל לדרו באגרא בין שנים במוט על כתפיהם דהיינו שנוי והוי להקל כפ\"ה וקשה דבסוף פ' האומנין (ב\"מ דף פג.) משמע דמשאו כבד נושאין בקל ברגלא מבאגרא אלא נראה דאפילו מכביד יותר מכל מקום לא חיישינן כיון דמשנה מדרך חול וכן נמי פירש הקונטרס גבי דדרו באגרא לדרו באכפא . ואפילו נמי אין להקל מכל מקום שנוי הוא:"],[4,"","דמליא בחצבא רבה תמלי בחצבא זוטא הא קא מפשא בהלוכא. וא\"ת מאי פריך והא מפשא בהלוכא והא אמרינן לעיל דאפושי בהלוכא שפיר דמי כשיעשה דרך שנוי ויש לומר דהא מפיש בהלוכא ושנוי נמי ליכא דבחול נמי עבדינן הכי:"],[5,"","זמנין דמטמיש בהו מיא ואתי לידי סחיטה. וא\"ת והא אמר נפרוס סודרא עלויה ולא חיישינן לידי סחיטה וי\"ל דלעיל מיירי בחבית שסתום כולו ופיו צר ולכך לא חיישינן לסחיטה ועי\"ל דהכא מיירי בסחיטת מים דאסורה משום לבון וא\"כ כי נפל בגוויה מיא אתי לידי סחיטה אבל התם מיירי ביין דסחיטה שלו אסורה משום דש וא\"כ כי נפיל . לארעא הולך לאבוד ולא חיישינן לסחיטה:"],[6,"","תנן אין מטפחין ואין מרקדין. פרש\"י שמא יתקן כלי שיר ומיהו לדידן שרי דדוקא בימיהן שהיו בקיאין לעשות כלי שיר שייך למגזר אבל לדידן אין אנו בקיאין לעשות כלי שיר ולא שייך למגזר:"],[6,"","אין מטפחין. פ\"ה משום שיר או משום אבל ולא נהירא דתפוק ליה דאסור משום צער ואפי' בחול המועד כדאיתא בפ' ואלו מגלחין (מו\"ק דף כח:) ולקמיה (דף לו.) מפרש שמא יתקן כלי שיר:"],[9,"","דהא תוספת יוה\"כ דאורייתא היא ואכלי ושתו עד חשכה כו'. משמע דיש שיעור לתוספת יוה\"כ מדהצריך להפסיק מבעוד יום דהא ודאי לא היו אוכלים ממש עד חשכה דעבדי איסורא מדאורייתא ואעפ\"כ קאמר מוטב שיהיו ישראל שוגגין ואל יהיו מזידין ובפי' התוספת לא הוברר השעור ולכך יש ליזהר ולהפסיק מבע\"י:"],[13,"","התם בתבנא סריא דאית ביה קוצים. וגם אינו ראוי למאכל בהמה וקאי להסקה ואפילו רבי יהודה מודה וא\"ת מאי שנא מעצים שבמוקצה דקא אסר רבי יהודה אע\"ג דחזיין להסקה וי\"ל דלא דמי דדוקא גבי אוצר של תבן לא הקצה דעתו למה שראוי עתה דלא הקצה דעתו כי אם ממאכל בהמה ועתה הוא ראוי להסקה ומזה לא הקצה דעתו אבל אוצר של עצים הקצה דעתו ממה שראוי עתה:"]]],[["\u0001מתני׳\u0002 אין נוטלין עצים מן הסוכה אלא מן הסמוך לה:","\u0001גמ׳\u0002 מאי שנא מן הסוכה דלא דקא סתר אהלא מן הסמוך לה נמי קא סתר אהלא","אמר רב יהודה אמר שמואל מאי סמוך סמוך לדפנות רב מנשיא אמר אפילו תימא בשאין סמוך לדפנות כי תניא ההיא באסורייתא","תניא ר' חייא בר יוסף קמיה דר' יוחנן אין נוטלין עצים מן הסוכה אלא מן הסמוך לה ור' שמעון מתיר ושוין בסוכת החג בחג שאסורה ואם התנה עליה הכל לפי תנאו","ורבי שמעון מתיר והא קא סתר אהלא אמר רב נחמן בר יצחק הכא בסוכה נופלת עסקינן ור' שמעון לטעמיה דלית ליה מוקצה דתניא מותר השמן שבנר ושבקערה אסור ורבי שמעון מתיר","מי דמי התם אדם יושב ומצפה אימתי תכבה נרו הכא אדם יושב ומצפה אימתי תפול סוכתו","אמר רב נחמן (בר יצחק) הכא בסוכה רעועה עסקינן דמאתמול דעתיה עלויה:","ושוין בסוכת החג בחג שהיא אסורה ואם התנה עליה הכל לפי תנאו: ומי מהני בה תנאי","והאמר רב ששת משום ר' עקיבא מנין לעצי סוכה שאסורין כל שבעה שנאמר (ויקרא כג, לד) חג הסוכות שבעת ימים לה' ותניא ר' יהודה בן בתירא אומר מנין שכשם שחל שם שמים על החגיגה כך חל שם שמים על הסוכה ת\"ל חג הסוכות שבעת ימים לה' מה חג לה' אף סוכה לה'","אמר רב מנשיא בריה דרבא סיפא אתאן לסוכה דעלמא אבל סוכה דמצוה לא מהני בה תנאה","וסוכה דמצוה לא והתניא סככה כהלכתה ועטרה בקרמים ובסדינין המצויירין ותלה בה אגוזים שקדים אפרסקים ורמונים ופרכילי ענבים יינות שמנים וסלתות ועטרות שבלים אסור להסתפק מהן עד מוצאי יום טוב האחרון של חג ואם התנה עליהם הכל לפי תנאו","אביי ורבא דאמרי תרוייהו באומר איני בודל מהם כל בין השמשות דלא חלה קדושה עלייהו אבל עצי סוכה דחלה קדושה עלייהו אתקצאי לשבעה","ומאי שנא מהא דאתמר הפריש שבעה אתרוגים לשבעת הימים אמר רב כל אחת ואחת יוצא בה ואוכלה לאלתר ורב אסי אמר כל אחת יוצא בה ואוכלה למחר","התם דמפסקו לילות מימים כל חד וחד יומא מצוה באפי נפשיה הוא הכא דלא מפסקו לילות מימים כולהו יומי כחדא יומא אריכתא דמי:"],[[0,"מתני' אין נוטלין עצים מן הסוכה","כגון בפסח או בעצרת ויושב בסוכה בגנה או בפרדס אין נוטלין עצים מן הסוכה אלא מן הסמוך לה השתא משמע אם הוא עב שנתנו קנים הרבה מותר ליטול מהם ובגמרא פריך הא סתר אהלא דכיון דבטליה לגבי סכך כל פורתא דשקיל מניה סתירה הוא:"],[2,"גמ' סמוך לדפנות","קנים הנזקפים סביבות לדפנות כיון שלא נארגו עם הדופן לא בטלי לגבי דופן ואינו דומה לסמוך לסכך שהסכך אינו ארוג לפיכך הכל שוה העליון כתחתון סכך הוא:"],[2,"אפילו תימא בשאין סמוך לדפנות","אלא סמוך לסכך:"],[2,"וכי תניא","מתניתין באסורייתא חבילות של קנים שנתנן על הסכך מדלא התיר אגדן לא בטלינהו לגבי סכך אלא להצניעם שם:"],[2,"בברייתא","נמי גרסינן אלא מן הסמוך לה:"],[3,"ורבי שמעון מתיר","אפילו מן הסכך ולקמן פריך ליה והא סתר אהלא:"],[3,"שהיא אסורה","אפילו בחוש\"מ כדיליף לקמן:"],[3,"ואם התנה עליה","לפני י\"ט:"],[4,"נופלת","שנפלה בי\"ט דליכא סתירת אהל וטעמא דת\"ק משום מוקצה דהא בין השמשות היתה קיימת ומוקצה היא מחמת איסור סתירה אבל הסמוך לה לאו מוקצה הוא דלית ביה משום סתירה:"],[4,"מותר השמן שבנר ושבקערה","נר קרוייזיי\"ל מותר השמן שנותן בנר או בקערה שמן הניתן להדלקת הנר של שבת וכבה המותר יש בה משום מוקצה ואסור:"],[5,"אדם יושב ומצפה אימתי תכבה נרו","שיודע שסופה לכבות הלכך בין השמשות דעתיה על המותר:"],[5,"הכא אדם יושב ומצפה כו'","בתמיה וכי נביא הוא ויודע שעתידה ליפול למחר:"],[6,"בסוכה רעועה","דמסיק אדעתיה דנפלה ולמחר נפלה הלכך לרבי שמעון מוקצה ליכא דאמרינן דעתיה מאתמול עלויה ולת\"ק לא אמרינן דעתיה עלויה בשום מידי דלא חזי בין השמשות:"],[8,"לה'","משמע כל שבעה לה' הוא הקדש:"],[8,"על החגיגה","שלמי חגיגה ליאסר משהוקדשו:"],[8,"חג","חגיגה:"],[9,"סיפא","דקתני ואם התנה עליה אסוכה דעלמא קאי וארישא דברייתא קא מהדר דאיפלגו בה ת\"ק ורבי שמעון דקתני אין נוטלין עצים מן הסוכה ואוקימנא בשנפלה ומשום מוקצה וקאמר אם התנה עליה מבעוד יום שאם תפול מחר יסיקנה הכל לפי תנאו:"],[10,"ועטרה","יפה בסדינין ובקרמין המצויירין קרמין בגדי צבעונין שקורין אובריי\"ץ סדינים לבנים של פשתן:"],[10,"יינות שמנים וסלתות","בכוסות של זכוכית לנוי:"],[10,"הכל לפי תנאו","מדקתני אסור להסתפק מהן ש\"מ בטלי להו לגבי סוכה והוי להו כסוכה וקאמר דתנאי מהני:"],[11,"אביי ורבא דאמרי תרוייהו","דלא דמו לסוכה לענין תנאה ואע\"ג דבטלי לגבה דכי מהני תנאה באומר מבעוד יום איני בודל מהם מהיות כוחי וזכותי בהם ליטלן כל שהות אורך של בין השמשות של ערב י\"ט הלכך בשעת ביאת היום שהיתה קדושה צריכה לחול עליהם לא חלה לפיכך לא הוקצה אבל עצי סוכה שאינו יכול להתנות עליהם תנאי זה שהרי על כרחו יבדל מהם בין השמשות משום דסתר אהלא ובין השמשות ספק י\"ט הוא חלה קדושה עליה ועל ידי קדושה זו הוקצה לשבעה:"],[12,"ומאי שנא מהא כו'","דלא אמר באתרוג דמשום בין השמשות קמא ליתקצי כל שבעה אלא לחד יומא מכי אתני עליה לחד יומא:"],[12,"דאתמר הפריש כו' יוצא בה","ביומה:"],[12,"ואוכלה לאלתר","קסבר למצותה אתקצאי והרי נעשית מצותה:"],[12,"ורב אסי אמר יוצא בה ואוכלה למחר","דכיון דאתקצאי לבין השמשות אתקצאי לכולי יומא והא עצי סוכה נמי כיון דאתני עלייהו ליהנות מהן בחולו של מועד כהפרישה ליום ראשון דמי ומשום דבין השמשות קמא קדיש קא אמרת דאתקצאי לשבעה:"],[13,"דמפסקי לילות מימים","שאין מצותו בלילה:"]],[[9,"","אמר רב מנשיא בריה דרבא סיפא אתאן לסוכה דעלמא כו'. מצי נמי למפרך דלמאי דס\"ל דהוי מוקצה מחמת איסור לא אשכחנא דמהני ביה תנאה אלא דאינו חושש למפרך משום דאינו נשאר במסקנא אלא נקט האמת:"],[10,"","עד מוצאי י\"ט האחרון. עד שיתחיל יום החול וא\"ת התינח י\"ט שמיני מוקצה הוא משום דהוי ספק שביעי וגם ביום תשיעי שם מוקצה עליו הואיל ואתקצאי לבין השמשות אתקצאי נמי לכולי יומא ושפיר אמרינן מוקצה מחמת יום שעבר במוקצה מחמת מצוה כגון הכא בעצי סוכה אבל נהגו העולם כשחל תשיעי של חג בע\"ש שאין מסתפקין מהן בשבת שהוא עשירי ומאי טעמא אי משום סתירת אהל לא שייך בפירות ואי משום דאתקצאי בין השמשות דתשיעי תרי מגו כה\"ג לא אמרינן דבתשיעי נמי לא נאסר אלא מטעם מגו וי\"ל דהיינו טעמא משום הכנה דהואיל ובע\"ש היה אסור שהוא תשיעי והוא י\"ט אם היה נאכל בשבת היה מכין י\"ט לשבת והוי כעין נולד כיון שבא עתה ראויות שלו ולא בא בי\"ט ומזה הטעם יש נזהרין כשחל שמחת תורה אחר השבת מלאכול האתרוג באותו יום דהואיל ובשבת היה אסור שהוא שמיני ועוד כי היה ראוי לברך בו אם אתי אליהו ואמר דעברו לאלול א\"כ אם היה אוכל אותו בשמחת התורה כדאמרן הוי שבת מכין לי\"ט:"],[11,"","אבל עצי סוכה דחל קדושה עלייהו אתקצאי לשבעה. וקשה דמשמע הכא דמה שעצי סוכה אסורין היינו מטעם מוקצה וכן משמע בשבת (דף מה. ושם) הואיל והוקצה למצותו הוקצה לאיסורו ולעיל קאמר מה חג לה' אף סוכה לה' אלמא דאסורין מדאורייתא ותירץ ר\"ת דמה שאמר מה חג לשם אף סוכה לשם היינו לפי שיעור סוכה כגון ב' דפנות ושלישית אפי' טפח אבל אי עביד דפנות שלמות יותר משיעור סוכה לא נפיק מקרא ועל היותר קאמר שאסור מטעם מוקצה ור\"י פירש דודאי כל זמן שהסוכה בעמידה שייך בה מה חג לה' אף סוכה לה' אבל כשנפלה לא שייך בה מה חג וכו' ואם כן היה יכול לתרוצי הכא מה שעצי סוכה אסורין מקרא דלעיל מה חג היינו כשהיו בעמידה אבל כשנפלו מותרין אלא נקט האמת דכשנפלו נמי אסורין מטעם מוקצה:"],[12,"","כל אחת ואחת יוצא בה ואוכלה לאלתר. לאו דוקא לאלתר דהא אתרוג של יום ראשון אסור כל היום עד למחר ולא פליג רב ורב אסי אלא בשאר ימים:"]]],[["\u0001מתני׳\u0002 מביאין עצים מן השדה מן המכונס ומן הקרפף אפי' מן המפוזר איזהו קרפף כל שסמוך לעיר דברי ר' יהודה ר' יוסי אומר כל שנכנסין לו בפותחת ואפילו בתוך תחום שבת:","\u0001גמ׳\u0002 אמר רב יהודה אמר שמואל אין מביאין עצים אלא מן המכונסין שבקרפף והא אנן תנן מן הקרפף ואפילו מן המפוזרים מתניתין יחידאה היא","דתניא א\"ר שמעון בן אלעזר לא נחלקו בית שמאי ובית הלל על המפוזרים שבשדות שאין מביאין ועל המכונסין שבקרפף שמביאין על מה נחלקו על המפוזרין שבקרפף ועל המכונסין שבשדות שבית שמאי אומרים לא יביא ובית הלל אומרים יביא","אמר רבא עלי קנים ועלי גפנים אף על גב דמכנפי להו ומותבי כיון דאי מדלי זיקא מבדר להו כמפוזרים דמו ואסורין ואי אתנח מנא מאתמול עלייהו שפיר דמי:","איזהו קרפף וכו': אבעיא להו היכי קאמר כל שסמוך לעיר והוא דאית ליה פותחת ואתא ר' יוסי למימר כיון דאית ליה פותחת אפילו בתוך תחום שבת נמי","או דלמא הכי קאמר כל שסמוך לעיר בין דאית ליה פותחת בין דלית ליה פותחת ואתא ר' יוסי למימר אפי' בתוך תחום שבת ודוקא דאית ליה פותחת אבל לית ליה פותחת אפילו סמוך לעיר נמי לא","ת\"ש מדקתני ר' יוסי אומר כל שנכנסין לו בפותחת ואפילו בתוך תחום שבת ש\"מ רבי יוסי תרתי לקולא קאמר ש\"מ אמר רב סלא אמר רבי ירמיה הלכה כרבי יוסי להקל:","\u0001מתני׳\u0002 אין מבקעין עצים לא מן הקורות ולא מן הקורה שנשברה ביו\"ט ואין מבקעין לא בקרדום ולא במגרה ולא במגל אלא בקופיץ: \u0001גמ׳\u0002"],[[0,"מתני' מביאין עצים","התלושים מן השדה שבתוך התחום ביו\"ט:"],[0,"מן המכונס","אם כנסו מערב י\"ט דגלי דעתיה דעלייהו סמיך ואינו מוקצה אבל המפוזרין מוקצין:"],[0,"ומן הקרפף","שהוא משתמר ומוקף סביב אפילו מפוזרים שבו לא הקצה מדעתו:"],[0,"סמוך לעיר","ממש:"],[0,"אפילו בתוך תחום שבת","בסופו:"],[1,"גמ' יחידאה היא","רבי שמעון בן אלעזר קאמר לה דאמר בית הלל הכי שרו ופליגי רבנן עליה:"],[3,"כמפוזרין דמו","ואפילו לא פזרתן הרוח דמסתמא לא סמכה דעתיה סבר מבדר להו זיקא:"],[3,"ואי אתנח מנא עלייהו","להכבידן שפיר דמי דסמכה דעתיה:"],[4,"","רבי יוסי לקולא או לחומרא קאמר לא גרסינן דהא מלתיה דרבי יהודה נמי מבעיא לן היכי אתמר וה\"ג אבעיא להו היכי קאמר כל הסמוך לעיר והוא דאית ליה פותחת ואתא ר' יוסי למימר כיון דאית ליה פותחת אפי' בתוך תחום שבת נמי או דלמא ה\"ק כל שסמוך לעיר בין דאית ליה פותחת בין דלית ליה פותחת ואתא רבי יוסי למימר אפי' בתוך תחום שבת ודוקא דאית ליה פותחת אבל דלית ליה פותחת אפילו סמוך לעיר נמי לא תא שמע מדקתני רבי יוסי אומר כל שנכנסין לו בפותחת ואפילו בתוך תחום שבת ש\"מ רבי יוסי תרתי לקולא קאמר והכי פי' היכי קאמר מתני' כל שסמוך לעיר והוא דאית ליה פותחת מפתח שמשתמר והאי דלא תנא ליה בהדיא משום דקא סבר סתמן יש להן פותחת ואסתם קרפיפות אמרה למלתיה ואתא רבי יוסי למימר כיון דאית ליה פותחת לא בעינן סמוך וממילא דאי לית ליה פותחת בעינן סמוך ואשתרי בהכי מדתלא שריותא בשאין סמוך בפותחת מכלל דסמוך בלא פותחת נמי שרי ומיקל בתרתי דרבי יהודה בעי תרוייהו ורבי יוסי סבר בחדא סגי באיזו שתהא שם:"],[5,"או דלמא","כל שסמוך לעיר דקאמר ת\"ק בהכי תלא טעמיה כיון דהוי סמוך בין דאית ליה פותחת בין דלית ליה ואתא רבי יוסי למימר הטעם תלוי בפותחת בין סמוך בין רחוק והכי קאמר כל שנכנסים לו בפותחת הוא דמותר ואפילו הוא בתוך תחום שבת דלא מתלי טעמא בסמיכה כלל:"],[6,"תרתי לקולא קאמר","כלומר מדרבי יוסי נשמע לרבי יהודה דלאו תרוייהו בעי ורבי יוסי בתרתי אקיל דמכשיר בסמוך בלא פותחת ובפותחת בלא סמוך דשמעינן לרבי יהודה דקאמר כל שסמוך לעיר בין דאית ליה פותחת בין דלית ליה פותחת וא\"ל רבי יוסי כל שיש לו פותחת אפי' הוא בתוך התחום ואי סמוך לא בעי פותחת דאי רבי יוסי בפותחת תלא טעמא דאפילו הוא סמוך בעי פותחת לא הוה ליה לסיומי ואפילו בתוך תחום שבת אלא הכי הוה ליה למימר רבי יוסי אומר כל שנכנסין לה בפותחת דכיון דהוה תני כל הוה משמע דצריך פותחת סמוך או רחוק למה לי דסיים ואפילו בתוך תחום שבת אלא לאשמועינן דלא בעי פותחת אלא למשרי שאין סמוך ורבי יהודה דלא בעי תרתי נמי מרישא דרבי יוסי שמע מינה מדנקט כל שנכנסין לה בפותחת כיון דכולהו פותחת אית להו הכי אבעי' ליה למתני רבי יוסי אומר אפילו בתוך תחום שבת:"],[7,"מתני' אין מבקעין עצים לא מן הקורות כו'","לפי סוגיא של גמרא היא מתפרשת:"],[7,"לא בקרדום","סתם קרדום עשוי כמין כלי אומנות שעושין בו אוכפות וסרגות שקורין איישי\"ש ויש שעשוי כעין כלי האומן שקורין בירגוא\"ה שראשו הקצר דומה לקרדומות שלנו וראשו השני דומה לכלי אומני אוכפות וסרגות הסוסים:"],[7,"ולא במגרה","שיג\"ה כעין סכין מלאה פגימות וממהר לקוץ בו עצים וכלי אומן הוא:"],[7,"מגל","דולוייר\"א או שרפ\"א וכולן כלי אומן הן ונראה כעושה בו מלאכה לפיכך אסור:"],[7,"אלא בקופיץ","סתם קופיץ הוא סכין של קצבים דומה לקרדומות שלנו שאינן כלי אומן ויש שעושין בו שני ראשין והשני דומה קצת לקרדום האוכפות כדשמעינן מיניה בגמרא ומיהו סתמיה לאו למלאכת אומן הוא:"]],[[1,"","מן הקרפף ואפילו מן המפוזר. תימה הא הוי מעמר דהוא אב מלאכה וי\"ל דלא שייך עמור אלא במקום שגדילים שם כדמוכח בפרק כלל גדול (שבת דף עג:):"],[4,"","איבעיא להו היכי קאמר כל שסמוך לעיר והוא דאית ליה פותחת וכו'. אבל לא גרס ר' יוסי לקולא או לחומרא דא\"כ משמע דמספקא ליה דרבי יוסי שמא הוא מחמיר יותר מת\"ק ולא היא דהא במלתיה דרבי יהודה נמי מספקא ליה היכי אתמר אלא ה\"ג היכי קאמר וכו' והכי פי' כל שסמוך לעיר וגם אית ליה פותחת ובעי רבי יהודה תרתי לחומרא דאע\"ג דסמוך בעי פותחת והא דלא פי' בדבריו פותחת משום דקסבר סתם קרפיפות יש להן פותחת ואתא רבי יוסי למימר הואיל ואית להו פותחת ואפילו רחוק מן העיר נמי וא\"כ שמעינן מדתלי טעמא דאינו סמוך שרי בפותחת מכלל דסמוך שרי אפילו בלא פותחת ותרתי לקולא קאמר רבי יוסי בסמוך בלא פותחת או באינו סמוך בפותחת או דלמא ר' יהודה סבר כל שסמוך בין אית ליה פותחת בין לית ליה פותחת שרי דקס\"ד השתא דסתם קרפיפות לית להו פותחת ואתא ר' יוסי למימר דבעי פותחת אפילו בסמוך כ\"ש ברחוק אבל סמוכה בלא פותחת אינה מועלת כלום ע\"כ פרש\"י והקשה השר מקוצי נהי דר' יהודה תלי טעמא בסמוכה דוקא אבל פותחת אינה מועלת כלום מ\"מ לרבי יוסי אמאי לא דייק כדפי' לעיל ללישנא קמא דמדתלי רבי יוסי טעמיה דשרי בפותחת באינו סמוך מכלל דבסמוך מועיל בלא פותחת דהשתא ללישנא קמא דרבי יהודה דבעי תרתי קאמר דלרבי יוסי סגי בחדא כ\"ש להאי לישנא דקאמר השתא דלרבי יהודה סגי בחדא בסמוך בלא פותחת ותירץ דע\"כ לא מצינן למימר דרבי יוסי תרתי לקולא אית ליה בהאי לישנא כדאמר ללישנא קמא דהואיל ולהאי לישנא צ\"ל דרבי יהודה לא קפיד אפותחת ולא ס\"ל דסתם קרפיפות אית להן פותחת אלא כל שסמוך בין אית ליה פותחת בין לית ליה פותחת אם כן לא היה לרבי יוסי למתני כל שנכנסים וכו' אלא הכי הוה ליה למתני רבי יוסי אומר אם יש לו פותחת אפילו אם היה בסוף התחום שרי הא אם סמוך שרי בלא פותחת ומדנקט כל משמע דיש קרפיפות דאין להן פותחת רבי יוסי ודאי תלי טעמיה בפותחת דוקא בין סמוך בין רחוק אבל ללישנא קמא ניחא דמצינא לפרושי דרבי יוסי תרתי לקולא אמר וניחא לשון כל שנכנסין דמאי אמרת הוה ליה למתני אם יש לו פותחת אדרבה אי הוה קאמר הכי הוה משמע דרבי יהודה לא קמיירי בפותחת וליתא דעל כרחך רבי יהודה בפותחת איירי אבל ללישנא דכל שנכנסין לו בפותחת משמע דמיירי בפותחת שאם תמצי לומר דלא מיירי רבי יהודה בפותחת אם כן רבי יוסי אי אמר תרתי לקולא קשיא ליה דמאי כל דמשמע דאיירי רבי יהודה בפותחת אדרבה רבי יהודה לא מיירי בפותחת אלא הוה ליה למתני אם יש לו פותחת והכי משמע לקמן מתוך פירוש רש\"י תא שמע מדקתני רבי יוסי וכו' דהכי משמע מדנקט רבי יוסי לישנא דכל הנכנסין ובסיפא דמלתיה אצטריך לסיים ואפילו בתוך תחום שבת ש\"מ דרבי יוסי תרתי לקולא קאמר דאי רבי יוסי בפותחת תלי טעמיה דוקא ואפילו הוא סמוך בעי פותחת לא הוה ליה לסיומי ואפילו בתוך התחום אלא הכי הוה ליה למימר רבי יוסי אומר כל שנכנסין בה בפותחת דמאי אמרת דאצטריך לסיומי רבי יוסי אומר בתוך תחום שבת לטעמיה להתיר בפותחת אפילו רחוק מלישנא דכל הנכנסין נפקא וכו' דהכי קאמר כל הנכנסין בפותחת שרי אפילו ברחוק אמאי מסיים בדבריו אפילו בתוך תחום שבת אלא ש\"מ דלא בעי לרחוק אלא דוקא למשרי שאינו רחוק"]]],[["והאמרת רישא אין מבקעין כלל אמר רב יהודה אמר שמואל חסורי מחסרא והכי קתני אין מבקעין מן הסואר של קורות ולא מן הקורה שנשברה ביו\"ט אבל מבקעין מן הקורה שנשברה מערב יו\"ט","וכשהן מבקעין אין מבקעין לא בקרדום ולא במגל ולא במגרה אלא בקופיץ תניא נמי הכי אין מבקעין עצים לא מן הסואר של קורות ולא מן הקורה שנשברה ביו\"ט לפי שאינו מן המוכן:","ולא בקרדום: אמר רב חיננא בר שלמיא משמיה דרב לא שנו אלא בנקבות שלו אבל בזכרות שלו מותר","פשיטא בקופיץ תנן מהו דתימא ה\"מ קופיץ לחודיה אבל קרדום וקופיץ אימא מגו דהאי גיסא אסור האי גיסא נמי אסור קמ\"ל","[ואיכא דמתני לה אסיפא אלא בקופיץ אמר רב חיננא בר שלמיא משמיה דרב לא שנו אלא בזכרות שלו אבל בנקבות שלו אסור פשיטא ולא בקרדום תנן מהו דתימא ה\"מ קרדום אבל קופיץ וקרדום אימא מגו דהאי גיסא שרי האי גיסא נמי שרי קמ\"ל:]","\u0001מתני׳\u0002 בית שהוא מלא פירות ונפחת נוטל ממקום הפחת ר' מאיר אומר אף פוחת לכתחלה ונוטל:","\u0001גמ׳\u0002 אמאי והא קא סתר אהלא אמר רב נחומי בר אדא אמר שמואל באוירא דליבני איני והאמר רב נחמן הני ליבני דאייתור מבנינא שרי לטלטולינהו בשבתא הואיל וחזי למזגא עלייהו שרגינהו ודאי אקצינהו","אמר רבי זירא ביו\"ט אמרו אבל לא בשבת תניא נמי הכי רבי מאיר אומר אף פוחת לכתחלה ונוטל ביו\"ט אמרו אבל לא בשבת","אמר שמואל חותמות שבקרקע מתיר אבל לא מפקיע ולא חותך שבכלים מתיר ומפקיע וחותך אחד שבת ואחד יו\"ט","מיתיבי חותמות שבקרקע בשבת מתיר אבל לא מפקיע ולא חותך ביום טוב מתיר ומפקיע וחותך","הא מני ר' מאיר היא דאמר אף פוחת לכתחלה ונוטל ופליגי רבנן עליה ואנא דאמרי כרבנן ומי פליגי רבנן עליה בחותמות שבקרקע והתניא מודים חכמים לרבי מאיר בחותמות שבקרקע שבשבת מתיר אבל לא מפקיע ולא חותך ביום טוב מתיר ומפקיע וחותך"],[[0,"גמ' והאמרת רישא אין מבקעין כלל","סברה דטעמא דמתני' לאו משום מוקצה תנא ברישא אין מבקעין עצים אלא משום מלאכה וטרחא והכי קאמר אין מבקעין עצים לא מן הקורות הנשברים מערב י\"ט ועומדין להסק ולא מן הקורה כו' וזו ואין צריך לומר זו קתני והיינו דמותבי' והאמרת רישא אין מבקעין כלל והדר תני דבקופיץ שרי:"],[0,"חסורי מחסרא כו'","וטעמא דרישא משום מוקצה:"],[0,"סואר של קורות","המושכבות לארץ של בנין:"],[0,"ולא מן הקורה שנשברה ביו\"ט","ואע\"ג דהשתא להסקה קיימא בין השמשות לאו להכי קיימא:"],[1,"תניא נמי הכי","כשמואל דטעמא דמתניתין משום מוקצה:"],[2,"לא שנו אלא בנקבות שלו","בראש הרחב שקוצצין בו העץ לרחבו דדמי למלאכת אומן:"],[2,"אבל בזכרות שלו","בראש הקצר שמבקעין בו עצים מותר:"],[3,"פשיטא אלא בקופיץ תנן","וקופיץ כולה זכרות היא:"],[4,"ואיכא דמתני לה","להא דרב חיננא אסיפא דמתניתין ובאתריה דהא דמתני לה להא דרב חיננא אסיפא היו עושין לקופיץ זכרות ונקבות כמו שעשוי כלי אומן שקורין בידגוא\"ה:"],[4,"פשיטא ולא בקרדום תנן","משום דכולו נקבות וממילא שמעינן דכי שרו קופיץ משום זכרות הוא דשריוה:"],[4,"מהו דתימא","ה\"מ דאסר קרדום לחודיה דכוליה נקבות ואינו עשוי לבקע אלא לכלי אומן אבל מי שיש לו שני ראשין אחד זכרות כקופיץ ואחד נקבות כקרדום אימא דמוכחא מלתא דלבקע הוא וכי היכי דהאי גיסא שרי האי גיסא נמי שרי קמ\"ל:"],[5,"מתני' ונפחת","מאליו:"],[5,"נוטל ממקום הפחת","ולא אמרי' מוקצין מחמת איסור הן דאין יכול לפחתו ביו\"ט ואסח דעתו מינייהו דכיון דלא הוה פחיתתו איסורא דאורייתא כדמוקמינן לה באוירא דלבני לאו מוקצה נינהו כדאמר גבי טבל בשלהי פרקין (דף לד:) שהוא מוכן אצל שבת שאם עבר ותקנו מתוקן:"],[5,"אף פוחת לכתחלה","כדמפרש טעמא בגמרא:"],[6,"גמ' באוירא דליבני","סדור של אבנים בלא טיט:"],[6,"דאייתור מבנינא","שנשתיירו לו לאחר שגמר בנינו:"],[6,"שרי לטלטלינהו","דמעתה לאו לבנין קיימי אלא למזגא עלייהו ותורת כלי עליהן:"],[6,"שרגינהו","סדרן זו על זו גלי דעתיה שמקצן לבנין ואסור לטלטלינהו ומתני' נמי נתסר מדרבנן שהרי מטלטלן:"],[7,"א\"ר זירא ביו\"ט","התיר ר\"מ כיון דמדרבנן הוא דאסור ומשום שמחת יו\"ט שרי שהרי מותר בו אוכל נפש אבל לא לשבת משום טלטול כרב נחמן:"],[8,"חותמות","פרמדורי\"ש:"],[8,"חותמות שבקרקע","כגון דלתות פתחי בורות ומערה הסגורים בקשרי חבלים:"],[8,"מתיר","את הקשר דהא לאו קשר של קיימא הוא שהרי להתיר תמיד הוא עשוי:"],[8,"אבל לא מפקיע","החבל לסתור עבותו וגדילתו:"],[8,"ולא חותך","דהא סתירה היא ויש סתירה בבנין של קרקע:"],[8,"ושל כלים","כגון תיבה הנעולה ע\"ו קשר חבל מתיר ומפקיע וחותך דאין סתירה בכלים:"],[9,"מיתיבי חותמות שבקרקע כו' ביו\"ט מתיר ומפקיע וחותך","אלמא חותמות הקשורים אין בהן משום סתירה מדאורייתא ובשבת מדרבנן הוא דאסור:"]],[[0,"","וה\"ק כל הנכנסין וכו' היכא אמרינן דבעי פותחת היינו למשרי רחוק אבל סמוך שרי בלא פותחת ש\"מ דר' יוסי תרתי אמר לקולא ומדרבי יוסי נשמע לרבי יהודה דבעי תרתי לחומרא דמדנקט בדבריו כל הנכנסין א\"כ שמעי' לרבי יהודה דבעי תרתי דאל\"כ לישנא דכל קשה ומאי אמרת האי כל דקאמר לטפויי כל הקרפיפות דבעינן שיש להן פותחת הא ר' יוסי תרתי לקולא אמר א\"כ הו\"ל למיתני אם. כך פירש רבינו שמשון מקוצי:"],[0,"","והאמרת רישא אין מבקעין כלל. קסבר הש\"ס דטעמא דמתני' משום דאע\"פ דהוו מוכנים להסקה אין מבקעין מטעם מלאכה וטרחא יתירא והיינו זו ואין צריך לומר זו דאפי' עומדים להסק מערב יו\"ט אסורין כל שכן קורה שנשברה ביו\"ט עצמו והיינו הא דמותבי' והאמרת אין מבקעין וכו' כן פירש רש\"י:"],[4,"","אבל קרדום וקופיץ מדהאי גיסא שרי האי גיסא נמי שרי. ופירשו התוספות דאין אנו בקיאין בקרדום היאך הן נעשין ולכך יש לנו לאסור לבקע עצים רק ביד:"],[5,"","ונפחת נוטל ממקום הפחת. פרש\"י נפחת מאליו וא\"ת אמאי נוטל ממקום הפחת הא הוה מוקצה בין השמשות דאסור לפחתו ביו\"ט מדרבנן ומגו דאתקצאי בין השמשות אתקצאי לכולי יומא ופירש בקונט' דכיון דאינו אסור אלא מדרבנן לפחות כדמוקים ליה בגמרא באוירא דלבני השתא דנפחת שרי למיכל מינייהו דבמוקצה דרבנן לא אמרינן מגו דאתקצאי לבין השמשות וכו' והכי אמר גבי טבל בשלהי פרקין שהוא מוכן אצל שבת הואיל ואם עבר ותקנו מתוקן דלא הוי מוקצה אלא מדרבנן ולא אמר מגו דאתקצאי וכו' ולא נהירא דאמר גבי שבת (דף נ ג.) גבי סל לפני האפרוחים מגו דאתקצאי אע\"ג דאין שם מוקצה אלא מדרבנן וכן גבי גלגל מוכני שיש עליה מעות ואומר הר\"ר משה דלא אמרו אלא כשהמוקצה אינו מסתלק מן העולם כגון מעות שע\"ג הכר שאף על פי שנטלם עדיין הן בעולם אבל בטבל מיד שתקנו הטבל מסתלק המוקצה מכל וכל וא\"ת והא אמרינן בחולין (דף יד. ושם) השוחט בשבת אסור באכילה ליומא ונסבין חבריא למימר ר' יהודה היא דמגו דאתקצאי לבין השמשות שהיתה חיה אסורה ואע\"ג דעכשיו כשנשחטה נסתלק המוקצה מן העולם וי\"ל כיון דבין השמשות היתה מוקצה מחמת חסרון מלאכה דאורייתא אמרינן מגו אע\"פ שהמוקצה נסתלק מן העולם ומ\"מ קשה דהכא הפחת הוי בעולם דומיא דמוכני שיש עליה מעות דהוי המוקצה בעולם אף על פי שאין כאן שהוא במקום אחר ה\"נ גבי הפחת הכי איתא לכנ\"ל דאתיא האי סתמא כרבי שמעון דלית ליה מוקצה וא\"ת מאי קאמר לעיל בריש מכיליתין (ביצה דף ב:) גבי יום טוב סתם לן תנא כרבי יהודה והא הכא סתם לן תנא כרבי שמעון ויש לומר דאין זה סתמא דסתמא הוי אם היה יכול לומר דברי רבי שמעון ולא קאמר אם כן הוה סתם לן תנא כוותיה אבל הכא לא היה יכול לומר דברי רבי שמעון דהא רישא קאמר נוטל ממקום הפחת דמשמע דוקא בדיעבד אבל לכתחלה לא יפחות ולא מצי למימר דברי רבי שמעון דהא סבירא ליה אף פוחת לכתחילה אבל לעיל ניחא דקאמר גבי יו\"ט סתם לן תנא כרבי יהודה דלא מיירי אלא במוקצה וא\"כ היה יכול למימר דברי רבי יהודה ומדלא קאמר א\"כ סתם לן תנא כוותיה:"],[7,"","אמר ר' זירא ביו\"ט אמרו. פי' דהתירו מוקצה משום אוכל נפש אבל לא בשבת מכאן יש ראייה לריצב\"א שפירש לעיל דטלטול מוקצה התירו ביו\"ט משום אוכל נפש:"]]],[["הוא דאמר כי האי תנא דתניא חותמות שבקרקע מתיר אבל לא מפקיע ולא חותך אחד שבת ואחד יו\"ט ושבכלי בשבת מתיר אבל לא מפקיע ולא חותך ביום טוב מתיר ומפקיע וחותך","תרצת לך רישא אלא סיפא קשיא","הא מני ר' נחמיה היא דאמר כל הכלים אין ניטלין אלא דרך תשמישן","אי רבי נחמיה מאי איריא שבת אפילו יום טוב נמי וכי תימא שניא ליה לר' נחמיה בין שבות שבת לשבות יום טוב ומי שניא ליה","והתני חדא מסיקין בכלים ואין מסיקין בשברי כלים ותניא אידך מסיקין בין בכלים בין בשברי כלים ותניא אידך אין מסיקין לא בכלים ולא בשברי כלים","ומשני לא קשיא הא ר' יהודה הא ר\"ש הא ר' נחמיה","תרי תנאי ואליבא דר' נחמיה:","\u0001מתני׳\u0002 אין פוחתין את הנר מפני שהוא עושה כלי ואין עושין פחמין ביום טוב ואין חותכין את הפתילה ר' יהודה אומר חותכה באור:","\u0001גמ׳\u0002 מאן תנא דפחיתת נר מנא הוא אמר רב יוסף ר' מאיר היא דתניא כלי חרס מאימתי מקבל טומאה משנגמרה מלאכתו דברי ר' מאיר ר' יהושע אומר משיצרפו בכבשן","א\"ל אביי ממאי דלמא עד כאן לא קאמר ר' מאיר התם אלא דחזי לקבולי ביה מידי אבל הכא למאי חזי לקבולי ביה פשיטי","איכא דאמרי אמר רב יוסף ר' אליעזר בר' צדוק היא דתנן אלפסין חרניות טהורות באהל המת וטמאות במשא הזב","ר' אליעזר בר' צדוק אומר אף טהורות במשא הזב לפי שלא נגמרה מלאכתן","א\"ל אביי דלמא עד כאן לא קאמר רבי אליעזר ברבי צדוק התם אלא דחזי לקבולי ביה מידי אבל הכא למאי חזי לקבולי ביה פשיטי","תנו רבנן אין פוחתין את הנר ואין עושין אלפסין חרניות ביום טוב רבן שמעון בן גמליאל מתיר באלפסין חרניות מאי חרניות אמר רב יהודה ערניות מאי ערניות אמר אביי צעי חקלייתא","ואין עושין פחמין פשיטא למאי חזי תני רבי חייא לא נצרכה אלא למוסרן לאוליירין לבו ביום","ובו ביום מי שרי כדאמר רבא להזיע וקודם גזרה הכא נמי להזיע וקודם גזרה:","ואין חותכין את הפתילה לשנים מ\"ש בסכין דלא"],[[0,"הוא דאמר כי האי תנא","שמואל דאמר לעיל דאפי' ביו\"ט אינו מפקיע דאמר כי האי תנא דאמר נמי בחותמות שבקרקע דאפילו ביו\"ט אין מפקיע:"],[1,"תרצת לך רישא","דמלתא דשמואל בחותמות שבקרקע דמסייע ליה האי תנא:"],[1,"סיפא קשיא","דאמר שמואל ושל כלים אפילו בשבת מתיר ומפקיע וחותך והאי תנא תני ושל כלים בשבת מתיר אבל לא מפקיע ולא חותך:"],[2,"הא מני רבי נחמיה היא","כלומר לעולם מותר להפקיע ולחתוך דאין בהם משום סתירה ולהאי תנא גופיה אם יכול להפקיע ולנתק בידו שרי והא דקאסר משום טלטול סכין קאסר ורבי נחמיה היא דאמר בערובין (דף לה.) אפילו תרווד ואפילו טלית אין ניטלין אלא לצורך תשמיש שהן מיוחדין לו וסכין לאוכלין הוא דמיוחד ולא לחותמות ובהא לא סבירא ליה לשמואל כוותיה:"],[3,"אי הכי","דרבי נחמיה היא:"],[3,"שבות שבת","דטלטול שבות הוא ולא החמיר בטלטול יום טוב כבשל שבת:"],[4,"מסיקין בכלים","דבני טלטול נמי נינהו ומטלטלן נמי להסיקן:"],[4,"אין מסיקין בשברי כלים","שנשברו בי\"ט דהשתא לא חזי לטלטול ואי משום דחזו להסקה אתמול לא להכי קיימי:"],[4,"מסיקין בין בכלים כו'","דלית להו מוקצה:"],[4,"אין מסיקין לא בכלים","דאין ניטלין אלא לצורך תשמישן וכ\"ש בשברי כלים דנולד הוא והא רבי נחמיה היא ומציעתא ר\"ש וקמייתא רבי יהודה וש\"מ ביו\"ט א\"ר נחמיה דהא הסקה ביו\"ט קאי:"],[6,"תרי תנאי","חד אמר שני ליה שבות שבת משבות י\"ט וחד אמר לא שני ליה:"],[7,"מתני' אין פוחתין את הנר","ליטול אחד מן הביצים של יוצר ולתחוב אגרופו לתוכו לחקוק נר קרוייזי\"ל בלעז מפני שעושה כלי:"],[7,"ואין עושין פחמין","דאינהו נמי כלי נינהו לצורפי זהב ופתילה נמי כלי היא להדלקה שצריכה עשייה ותקון:"],[7,"חותכן באור","בגמרא מפרש מאי שנא אור מסכין:"],[8,"גמ' דפחיתת נר מנא הוא","קודם שצרפו בכבשן:"],[8,"משנגמרה מלאכתן","חקיקתם:"],[8,"משיצרפו","משיחזקם ע\"י צירוף האור בכבשן מצרף בלשון חכמים מחזק ומקשה כלי חרס וכלי מתכות בדבר המחזקן בין (ביד) [במים] בין באור:"],[9,"וממאי","דס\"ל לר\"מ בנר כשאר כלי חרס בשלמא שאר כלי חרס גדולים הם ואם אינן ראויין למים וליין ולדבר לח מפני שממחן חזו מיהו לדבר יבש כגון פירות אבל נר קטן הוא וכי לא חזי למלתיה למאי חזי ומשני חזי לקבולי ביה פשיטי:"],[10,"איכא דאמרי אמר רב יוסף","מתני' דקתני פחיתת הנר מנא הוא ר\"א ברבי צדוק היא דאמר לפני חקיקה לאו מנא הוא אבל חקיקה משוי ליה מנא:"],[10,"אלפסין חרניות","מפרש לקמן קערות של בני עיירות שאינן בני כרכים גדולים ואין מקפידין על כלים נאים ומשנפשטה הקערה של חרס אוכלין בה בשר ואין ממתינין עד שתתחקק ותצרף בכבשן:"],[10,"טהורות באהל המת","דלגבי אהל המת בעינן תוך לכלי חרס דכתיב וכל כלי פתוח (במדבר י״ט:ט״ו) משמע דיש לו פתח וכן לכל טומאת מגע:"],[10,"וטמאות במשא הזב","שהזב מטמא כלי חרס בהסט דנפקא לן בתורת כהנים מוכל כלי חרס אשר יגע בו הזב וגו' (ויקרא ט״ו:י״א) ודרשינן התם זה הסטו וכיון דמטמי ליה הסט מאבראי לא בעי תוך וקסבר ת\"ק כלי נינהו הואיל ומשתמשין בהן כמות שהן הלכך מקבלין טומאה בדבר הראוי לטמאן:"],[11,"ר\"א אומר","אין להם שום טומאה דלאו כלי נינהו:"],[11,"לפי שלא נגמרה מלאכתן","חקיקתן הא נחקקו מטמאות מדאפלוג באלפסין אלמא לר\"א חקיקה משויא להו מנא:"],[12,"דחזי לקבולי מידי","משנחקקו ומיהו קודם חקיקה לא דסופן ליחקק:"],[14,"לאוליירין","מחמי חמין ומרחצאות ואע\"ג דלצורך י\"ט הן עושין:"],[15,"מי שרי","להחם והלא גזרו על הרחיצה במסכת שבת (דף לח: ודף מ.) ואפילו הוחמו מבעוד יום וכל שכן להחם חמין לא הותר מעולם:"],[15,"להזיע","מכניס הפחמים לתוכו ובני אדם נכנסין ומזיעין וקודם שגזרו על הזיעה נשנת משנה זו:"]],[[7,"","אין פוחתין את הנר. פירש רש\"י ליטול אחד מן הגולמים של יוצר ולתחוב אגרופו בתוכו ולחקוק נר שעושה כלי ותימה א\"כ פשיטא דאסור דאפילו אין עושה כלי גמור מ\"מ אסור להתחיל את הכלי וע\"ק מאי קא אמר עלה בגמרא מאימתי מקבלין טומאה משעה שנגמרה מלאכתן הואיל והוי כלי והא כיון דהוי קודם אפייתו בתנור אם כן הוי כלי אדמה וכלי אדמה אין מקבלין טומאה לכן נראה לפרש דאין פוחתין את הנר שכך רגילין לשום באוירו קודם אפייתו קש או דבר אחר כדי לשמור האויר בשעת אפייה שלא יפלו המחיצות יחד ויסתום האויר ולאחר אפייתו קצת מסלקין אותו דבר שבתוכו ועל זה קאמר אין פוחתין את הנר כלומר שאין מסירין מה שבתוכו דהוי כמו גמר כלי ונגמרה מלאכתו ולפי שרגילין לאחר שסלקו מה שבתוכו שמחזירין אותו לתנור כדי לצרפו היטב קאמר בגמרא מאן תנא דפחיתת נר מנא הוא וקאמר ר\"מ היא דקאמר דמקבלין טומאה כשסלק מה שמשימין בתוכו אע\"פ שלא החזירו אותו עדיין לתנור אלמא דפחיתת נר היינו גמר כלי ורבי יהושע קאמר משיצרפו בכבשן דאינו כלי עד שיחזיר אותו לתנור כדי לצורפו אם כן לדידיה פחיתה הוה שריא:"],[10,"","אלפסין חרניות טהורות באהל המת. פי' רש\"י קערות של עיירות ואינן מקפידין על כלים נאים ומיד כשנפשט הכלי של חרס אוכלין בה ואין ממתינין עד שתתחקק ותצרף באש והן טהורין באהל המת שאין להם תוך ובעינן כלי פתוח וטמאות במשא הזב דהזב מטמא כלי חרס בהסט כדנפקא לן מכלי חרס אשר יגע בו איזהו מגעו שהוא ככולו הוי אומר זה הסטו דלא בעינן תוך ותימה דהואיל דאין להם תוך היכי מטמא בהסט הא אמרינן כל שאינו בא לכלל מגע אינו בא לכלל הסט לכך פי' ר\"ת ערניות יש להן תוך אלא שמכוסות למעלה ועומדות ליפתח ואותם של כפרים אין מקפידין ואוכלין כך עליהן וטהורות באהל המת דהא כלי צמיד פתיל טהור באהל המת ומיהו טמאים בהסט הואיל ועומדין ליפתח כדאמרינן. גבי צמיד פתיל שמא תסיטם אשתו וקאמר נמי כלי צמיד פתיל נצול באהל המת ואינו נצול במעת לעת שבנדה:"]]],[["דקמתקן מנא באור נמי קא מתקן מנא תני ר' חייא חותכה באור בפי שתי נרות אמר רב נתן בר אבא אמר רב מוחטין את הפתילה ביום טוב מאי מוחטין אמר רב חנינא בר שלמיא (משמיה דרב) לעדויי חושכא","תני בר קפרא ו' דברים נאמרו בפתילה ג' להחמיר וג' להקל להחמיר אין גודלין אותה לכתחלה ביו\"ט ואין מהבהבין אותה באור ואין חותכין אותה לשנים להקל ממעכה ביד ושורה בשמן וחותכה באור בפי שתי נרות","ואמר רב נתן בר אבא אמר רב עתירי בבל יורדי גיהנם הם כי הא דשבתאי בר מרינוס אקלע לבבל בעא מנייהו עסקא ולא יהבו ליה מזוני מיזן נמי לא זינוהו","אמר הני מערב רב קא אתו דכתיב (דברים יג, יח) ונתן לך רחמים ורחמך כל המרחם על הבריות בידוע שהוא מזרעו של אברהם אבינו וכל מי שאינו מרחם על הבריות בידוע שאינו מזרעו של אברהם אבינו","ואמר רב נתן בר אבא אמר רב כל המצפה על שלחן אחרים עולם חשך בעדו שנאמר (איוב טו, כג) נודד הוא ללחם איה ידע כי נכון בידו יום חשך רב חסדא אמר אף חייו אינן חיים","ת\"ר ג' חייהן אינם חיים ואלו הן המצפה לשלחן חבירו ומי שאשתו מושלת עליו ומי שיסורין מושלין בגופו ויש אומרים אף מי שאין לו אלא חלוק אחד ות\"ק אפשר דמעיין במניה:","\u0001מתני׳\u0002 אין שוברין את החרס ואין חותכין הנייר לצלות בו מליח","ואין גורפין תנור וכירים אבל מכבשין","ואין מקיפין שתי חביות לשפות עליהן את הקדרה ואין סומכין את הקדרה בבקעת וכן בדלת ואין מנהיגין את הבהמה במקל ביום טוב ורבי אלעזר בר' שמעון מתיר:","\u0001גמ׳\u0002 מ\"ט משם דקא מתקן מנא","ואין גורפין תנור וכירים תני רב חייא בר יוסף קמיה דרב נחמן ואם אי אפשר לאפות אלא אם כן גורפו מותר דביתהו דר' חייא נפל לה אריחא בתנורא ביומא טבא אמר לה ר' חייא חזי דאנא רפתא מעלייתא בעינא א\"ל רבא לשמעיה טוי לי בר אווזא ואזדהר מחרוכא","א\"ל רבינא לרב אשי אמר לן רב אחא מהוצל דמר שרקין ליה תנורא ביומא טבא אמר ליה אנן ארקתא דפרת סמכינן והנ\"מ הוא דצייריה מאתמול אמר רבינא וקטמא שרי:","ואין מקיפין שתי חביות: אמר רב נחמן אבנים של בית הכסא מותר לצדדן ביום טוב איתיביה רבה לרב נחמן אין מקיפין שתי חביות לשפות עליהן את הקדרה אמר ליה שאני התם משום דקא עביד אהלא","א\"ל רבה זוטא לרב אשי אלא מעתה בנה אצטבא ביו\"ט דלא עביד אהלא הכי נמי דשרי א\"ל התם בנין קבע אסרה תורה בנין עראי לא אסרה תורה וגזרו רבנן על בנין עראי משום בנין קבע והכא משום כבודו לא גזרו ביה רבנן","אמר רב יהודה האי מדורתא מלמעלה למטה שרי מלמטה למעלה אסור"],[[0,"דקמתקן מנא","אחת היתה ועושה אותה שתים:"],[0,"בפי שתי נרות","נותן שני ראשיה בתוך שתי נרות אם צריך להדליקן כאחת ומדליק באמצע דלא מוכח דלתקוני מנא מכוין אלא להדלקה בעלמא:"],[0,"לעדויי חושכא","כשהיא נעשית בראשה פחם מעבירה:"],[0,"לעדויי","להסיר:"],[0,"חושכא","פחם המחשיך אורה:"],[1,"נאמרו בפתילה","ביו\"ט:"],[1,"ממעכה ביד","תקון כלאחר יד הוא:"],[2,"יורדי גיהנם הן","שאינן מרחמים לעשות צדקה:"],[2,"עסקא","סחורה להשתכר למחצית שכר:"],[2,"מזוני","שאל מהם מזונות מיזן נמי לא זינוהו:"],[3,"ונתן לך רחמים","שתרחם על הבריות:"],[3,"כאשר נשבע לאבותיך","מי שיש לו רחמים מזרעו של אבות:"],[4,"בעדו","כנגדו כמו שכת בעדו (איוב א׳:י׳) כלומר חשך פרוס לפניו הכל עליו כחשך:"],[4,"נכון בידו","מזומן אצלו:"],[5,"מי שאין לו אלא חלוק אחד","אין יכול לכבסו וכנים מצערין אותו:"],[5,"דמעיין במניה","מפלה את כליו מן הכנים:"],[6,"מתני' אין שוברין את החרס","כשצולין דגים על האסכלא שקורין גראדיל\"א בלע\"ז חותכין קנים או קש שבלים או שוברין חרסים או חותכין נייר ושורין במים וסודרין הנייר על גב האסכלא מפני שהמתכת מתחמם ושורף את הדג:"],[6,"מליח","דג:"],[7,"ואין גורפין תנור וכירים","אם נפל לתוכו מן הטפל והטיח אין גורפין אותו דמתקן מנא הוא ואתיא כרבנן דאמרי מכשירי אוכל נפש אסירי:"],[7,"מכבשין","משכיבין את האפר והעפר שיהא חלק משפילו ומשווהו שלא יגע בפת שמדובקים בדפנותיו וישרפו מכבשין פרימבר\"א:"],[8,"מקיפין","מקרבין זו אצל זו כמו (אין) מקיפין בריאה (חולין דף נ.) וכמו לתרום שלא מן המוקף (גיטין דף ל:). היינו סמוך וכמו מקפת וקורא לה שם (נדה דף עא:):"],[8,"לשפות עליהם קדרה","והאור בין שתי החביות:"],[8,"לשפות","להושיב כל הושבת קדרה על האור קרי שפיתה כשאין לו כלי ברזל שקורין טרפיי\"ד או שאין לו כירה של חרס חלולה ואסר לה משום דדמי לבנין ומדרבנן משום דמתחזי כאהלא:"],[8,"ואין סומכין קדרה בבקעת","קסבר לא נתנו עצים אלא להסקה לפיכך מוקצין הן אצל כל תשמיש:"],[8,"וכן בדלת","השתא משמע וכן אין סומכין קדרה בדלת ובגמרא פריך עלה:"],[8,"ואין מנהיגין את הבהמה במקל","ברשות הרבים השתא קס\"ד משום דאין משתמשין בעצים שלא נעשו כלי מערב יום טוב דלא נתנו אלא להסקה:"],[10,"גמ' ואם אי אפשר לו כו' מותר","כר\"י:"],[10,"אריחא","חצי לבינה ונתק מכותל התנור:"],[10,"רפתא מעלייתא בעינא","כלומר גרפי התנור:"],[10,"טוי לי אוזא","צלה לי אווז בתנור שתנוריהם היו קטנים ופיהן למעלה ותולה הצלי לתוכו וסותם פיו והוא נצלה:"],[10,"ואזדהר מחרוכא","שלא יתחרך כלומר גרוף את התנור שלא יהא בו בשוליו דבר גבוה כמו אריח או אבן שהוסק בתנור שנוגע בצלי ושורפו:"],[11,"דמר","רב אשי:"],[11,"שרקין ליה תנורא","עבדי אדוני טחין סביבות כסוי פי התנור בטיט שלא יצא חומו כשהצלי בתוכו שהרוח קשה לצלי ותימה לן מלתא משום דגבול טיט תולדה דלישה הוא:"],[11,"ארקתא דפרת סמכינן","על שפתו של פרת אנו נסמכים בדבר שאין אנו צריכים לגבל טיט ששפת פרת טיט מגובל הוא:"],[11,"והוא דצייריה מאתמול","עשה בו סימן ונתקו לצד אחר:"],[11,"וקטמא שרי","לגבלו ולטוח בו דלאו בר גבול הוא:"],[12,"אבנים של בית הכסא","אבנים גדולות שמצדדין אותן להיות כמין מושב חלול ויושבין עליהם בשדות במקום המיוחד לבית הכסא:"],[12,"דקא עביד אהלא","שיש לו גג אבל הכא ליכא גג:"],[13,"אצטבא","כסא של בנין לבנים וטיט:"],[13,"בנין עראי","שאינו להתקיים:"],[13,"והכא","גבי בית הכסא משום כבוד הבריות לא גזור:"],[14,"האי מדורתא","היסק גדול שעושין לפני שרים כדרך בנין עושין לו כתלים מד' רוחות וסודרין עצים למעלה ודומה לאהל:"],[14,"מלמטה למעלה","לסדר העצים של כתלים תחלה לעשות עליהם הגג אסורין שדרך בנין הוא:"],[14,"מלמעלה למטה","להתחיל תחלה מן הגג ואח\"כ יסדרו תחתיו עצי הכתלים שרי:"]],[[11,"","וקטמא שרי. פרש\"י לגבלו ולטוח בו דלאו בר גבול הוא ותימה דאמרינן בשבת (דף יח.) דאפילו בנתינת מים על העפר בעלמא הוא חייב משום מגבל דקאמר התם אחד נותן את האפר ואחד נותן את המים האחרון חייב וי\"ל דהכא ר\"ל קטמא שרי כלומר וקטמא שרי לסתום הסדקים של תנור שלא יוציא האור כמו שהוא יבש בלא נתינת מים עליו ועוד יש לומר דה\"פ וקטמא שרי כגון שגבלו מערב יום טוב ושרי בלא [גיבול]:"],[14,"","מלמטה למעלה אסור. משום דהוי דרך בנין וכן הוי טעמא דכולן וא\"ת היכי מסדרין שלחן שאין לו רגלים על גבי ספסלים שלו דמתחלה משימין הספסלים ואח\"כ משימין עליהם את השלחן י\"ל דהואיל ואין להם מחיצות שרי וכל הני מיירי דאית להו מחיצות לצדדים המגיעות לארץ ותימה דאמר בשבת (דף לו: ושם) מחזירין קדרה על גבי כירה והתם (דף לח:) קאמר מאן דאית ליה מחזירין דאפילו בשבת מחזירין וי\"ל דכל הנך אינן אסורין אלא היכא שמתקן האהל והמחיצות אבל אם עשה האהל בלא מחיצות שרי והתם גבי כירה המחיצות היו עשויות מתחלה וכן פר\"ח גבי ביעתא כגון שיש ביצים מכאן וביצים מכאן וא' על גביהן והאור תחת אוירן ולא כפי' רש\"י שפי' ביצים שמסדרין על גבי אסכלא דכיון דליכא מחיצות לא הוי כעין בנין אלא נרא' כדפריש וגם פוריא לא מיירי"]]],[["וכן ביעתא וכן קדרה וכן פוריא וכן חביתא","ואין סומכין את הקדרה בבקעת וכן בדלת בדלת ס\"ד אלא אימא וכן הדלת: תנו רבנן אין סומכין את הקדרה בבקעת וכן הדלת לפי שלא נתנו עצים אלא להסקה ורבי שמעון מתיר","ואין מנהיגין את הבהמה במקל ביו\"ט ור' אלעזר בר' שמעון מתיר לימא ר' אלעזר בר' שמעון כאבוה סבירא ליה דלית ליה מוקצה לא בהא אפילו ר' שמעון מודה משום דמחזי כמאן דאזיל לחנגא:","חזרא רב נחמן אסר ורב ששת שרי ברטיבא כולי עלמא לא פליגי דאסור כי פליגי ביבשתא מאן דאסר אמר לך לא נתנו עצים אלא להסקה ומאן דשרי אמר לך מה לי לצלות בו מה לי לצלות בגחלתו","איכא דאמרי ביבשתא כולי עלמא לא פליגי דשרי כי פליגי ברטיבתא מאן דאסר דלא חזי להסקה ומאן דשרי אמר לך הא חזי להיסק גדול והלכתא יבשתא שרי רטיבתא אסור","דרש רבא אשה לא תכנס לדיר העצים ליטול מהן אוד ואוד שנשבר אסור להסיקו ביו\"ט לפי שמסיקין בכלים ואין מסיקין בשברי כלים","למימרא דרבא כר' יהודה סבירא ליה דאית ליה מוקצה והא אמר ליה רבא לשמעיה טוי לי בר אווזא ושדי מעיה לשונרא התם כיון דמסרחי מאתמול דעתיה עלויה:","\u0001מתני׳\u0002 ר' אליעזר אומר נוטל אדם קיסם משלפניו לחצוץ בו שיניו ומגבב מן החצר ומדליק שכל מה שבחצר מוכן הוא וחכמים אומרים מגבב משלפניו ומדליק","אין מוציאין את האור לא מן העצים ולא מן האבנים ולא מן העפר ולא מן הרעפים ולא מן המים ואין מלבנין את הרעפים לצלות בהן:","\u0001גמ׳\u0002 אמר רב יהודה"],[[0,"וכן ביעתא","ביצים גסות הנתונות ע\"פ כלי חלול כעין טרפי\"ד או על האסכלא אין מושיבין את הכלי תחלה ואח\"כ יסדר עליו אלא יאחזנו בידו ויושיב הביצה עליו ואח\"כ יושיב הכלי על הגחלים שלא יעשנו כסדר בנין:"],[0,"וכן קדרה","שמושיבין על ב' חביות לא יקיפנה תחלה ואח\"כ יושיב הקדרה עליהם אלא העליונה יתלה באויר ויאחזנה בידו ויסדרו החביות תחתיה סביב:"],[0,"וכן פוריא","מטות השרים שפורקין אותן ומחזירין לא יזקוף הכרעים תחלה לתת הארוכות בכרעים ואח\"כ יפרוס העור למצע ששוכבין עליו אלא פורס העור תחלה ויאחזוהו בני אדם בידיהם ואח\"כ יביאו הארוכות ויקשרו הרצועות של עור בהן ואח\"כ יזקפו הכרעים ויתנו הארוכות לתוכן:"],[0,"וכן חביתא","חביות שמסדרים באוצר ומושיבין אחת על גבי שתים:"],[1,"בדלת ס\"ד","ומי זה הסומך קדרה בדלת והלא תשבר:"],[1,"אימא וכן הדלת","אין סומכין אותו בבקעת:"],[1,"ור\"ש מתיר","דלית ליה מוקצה:"],[2,"בהא אפי' ר\"ש מודה","כלומר הך פלוגתא לאו במוקצה היא ואפי' ר\"ש מודה כת\"ק דאסור ולא משום מוקצה אלא נראה כמוליכה ממקום למקום שהוא צריך להנהיגה הרבה כגון למכור בשוק:"],[2,"חנגא","מחול ועל שם שבני אדם סובבים והולכים בשוק כעין סובבות במחולות קרי ליה חנגא:"],[3,"חזרא","ענף עץ שהוא חד כקוץ וראוי לתקעו בצלי כמין שפוד ולצלות בו:"],[3,"ר\"נ אסר","ביו\"ט משום דמוקצה נינהו לטלטל שלא עשאו לכלי מבעוד יום:"],[3,"ברטיבא","שאינו ראוי לטלטלו אפילו להסקה דכ\"ע לא פליגי דאסור:"],[3,"מה לי לצלות בו","לתחבו לתוכו:"],[3,"מה לי לצלות בגחלתו","הרי ראוי לטלטלו לעשותו גחלת וצולה בה:"],[4,"והלכתא כו'","הך הלכתא אליבא דמאן דאית ליה מוקצה אקבע אבל אנן כר\"ש ס\"ל בין במוקצה בין בדבר שאינו מתכוין וכר' יהודה במכשירי אוכל נפש וכולהו שרו בין חזרא בין סמיכת קדרות והקפת חביות ומדורתא וקדרה וכל האמוראים שאסרו את אלו למעלה תלמידי דרב הוו ורב סבר לה כרבי יהודה במוקצה ואנן קיימא לן כרבי שמעון:"],[5,"דרש רבא כו'","דכרבי יהודה ס\"ל:"],[5,"לדיר","דיר עצים:"],[5,"אוד","עץ לעשות אוד לתנור פורגי\"ן בלע\"ז וטעמא משום דלא נתנו אלא להסיק אא\"כ נעשה כלי מבעוד יום:"],[5,"ואוד שנשבר","ביו\"ט:"],[6,"ושדי מעיה לשונרא","השלך בני מעים לחתול ולר' יהודה אסור לטלטלו ולתתו לחתול דמאתמול מוכן לאדם היה ולא לכלבים דקאמר אם לא היתה נבילה מע\"ש אסורה:"],[6,"כיון דמסרחי","אם יניחם לצורך מחר והיום לא היה צריך להם מאתמול דעתיה עלוייהו להשליכם לחתול:"],[7,"מתני' נוטל אדם קיסם משלפניו","ממה שלפניו בבית:"],[7,"לחצוץ בו שיניו","ליטול בשר החוצץ בין שניו בורגיי\"ר בלע\"ז ומשלפניו לאו דוקא דלר\"א אף מן החצר נמי דקאמר כל מה שבחצר מוכן הוא ורישא לא אתא לאשמועינן אלא היתר טלטול עצים אף שלא להסקה דאפלוג רבנן בה כדלקמן בברייתא בגמרא והא דנקט משלפניו משום רבנן דפליגי דאפילו משלפניו להדליק אין לחצוץ לא:"],[7,"מגבב","קסמין דקין וקשין מן החצר ומדליק בהן:"],[7,"וחכ\"א מגבב משלפניו ומדליק","אבל מן החצר לא הואיל ודקין הן וטורח לקוששן מאתמול לאו להכי קיימי ודקאמרת נוטל קיסם לחצוץ שניו (מאתמול) אנן אית לן דאף משלפניו לא יטול אלא להדליק דלא נתנו [אלא] להסקה ובתרתי פליגי:"],[8,"ואין מוציאין את האור","משום דמוליד:"],[8,"מן המים","נותנים מים בכלי זכוכית לבנה ונותנו בחמה כשהשמש חם מאד והזכוכית מוציאה שלהבת ומביאין נעורת ומגיעים בזכוכית והיא בוערת כך שמעתי בפיוט יוצר שיסד אחד מגאוני לומברדיא\"ה:"],[8,"מן העפר","קרקע קשה כשחופרים אותה מוציאה אור כעין גרגישתא שלנו ממקום מחפורת שלה:"],[8,"רעפים","טייבלו\"ש:"],[8,"אין מלבנין","באור ובגמרא מפרש טעמא:"]],[[0,"","כגון מטה שלנו שאין לה מחיצות אלא שיש לה מחיצות אך תימה דאמר בשבת (דף קלט:) האי פרוונקא (. אפלגא) דכובא אסירא והתם המחיצות היו עשויות כבר וי\"ל דשאני התם הואיל ורחב הכובא יותר מדאי נעשה כאהל פרש\"י דרב יהודה דהכא ס\"ל כרבי יהודה דאוסר מוקצה ודבר שאין מתכוין אבל אנן ס\"ל כר\"ש ודבר שאין מתכוין מותר ודוחק הוא לומר דכל הני מילתא דלא כר\"ש אלא נראה לומר דאפילו ר\"ש מודה דהויא הכא אסור דהא דא\"ר שמעון דבר שאין מתכוין מותר היינו כגון שעושה דבר שאין מתכוין לעשותו אבל הכא מתכוין לעשות מה שהוא עושה:"],[4,"","והלכתא יבשתא שרי רטיבא אסור. פרש\"י דהלכתא אקבע אליבא דמאן דאית ליה מוקצה ולא נתנו עצים אלא להסקה אבל אנו דקי\"ל כר\"ש שרי אפי' חזרא רטיבא ודוחק הוא לומר דר\"ש פליג אמאי דפסיק הש\"ס וי\"ל דאפילו לר\"ש דנהי דאית ליה שנתנו עצים שלא להסקה היינו בדבר הראוי להסקה אבל רטיבא אין ראויין להסקה:"],[5,"","דרש רבא וכו'. פירש רש\"י דכר' יהודה ס\"ל וע\"כ לא תכנס ליטול אוד דלא נתנו עצים אלא להסקה ודוחק הוא לומר דהש\"ס קיימא דלא כהלכתא אלא ודאי דאפילו ר' שמעון מודה דאסור משום דהוי כתקוני מנא:"],[6,"","ושדי מעיה לשונרא. פירש\"י דלרבי יהודה הוה אסור לטלטלן ליתן לחתול דמאתמול מוכן לאדם הוה ולא לכלבים וא\"ר יהודה דאם לא היתה נבלה מעיו\"ט אסור ליתן לכלבים וגם אינו ראוי ליתן לאדם לפי שאין דרך בני אדם לאכול בני מעים ביו\"ט דבלאו הכי יש להם הרבה לאכול וא\"ת וכי משום שאינו אוכל מהן הוו מוקצין א\"כ היכי מטלטלין בשר חי דחזיא לכוס במסכת שבת (דף קכח.) הא אינו אוכל מהן משום שיש לו הרבה לאכול וי\"ל דמיירי שכבר הסריחו ולא הוי חזי לאדם ולר' יהודה היה אסור ומשני כיון דמסריחי כלומר כיון דודאי מסריחי דעתידין להסריח דעתו לכלבים:"],[7,"","רבי אליעזר אומר נוטל אדם קיסם משלפניו. פירש\"י לאו דוקא משלפניו דה\"ה משלאחריו נמי דקתני כל מה שבחצר מוכן הוא אלא נקט משלפניו משום רבנן דפליגי אח\"כ דשרו דוקא להדליק אבל לחצוץ בו שניו לא ותימה דהא משמע בפרק המוציא (שבת דף פא: ושם) דדוקא קתני דבעי התם אבנים של בית הכסא מהו להעלותן אחריו לגג וקא פשיט ליה דשריא ופריך מיתיבי ר\"א אומר נוטל אדם קיסם משלפניו דדוקא משלפניו אבל בכל החצר לא ואת אמרת דיכול להעלות לגג וי\"ל דאה\"נ דודאי דוקא קאמר כדמשמע התם ואף על גב דקאמר כל מה שבחצר מוכן הוא היינו דוקא גבי אכילה משום דאדם קובע לו מקום לאכילתו והיה לו להכין אבל גבי אש לא שייך דפעמים שאינו עושה מדורה ביו\"ט וכן מחלק התם בין אבנים לקיסם:"],[7,"","וחכמים אומרים מגבב משלפניו ומדליק. פרש\"י דבתרתי פליגי דאפילו להדליק דוקא משלפניו ולחצוץ שניו אפילו משלפניו לא דעצים לא נתנו אלא להסקה וקשה לפירושו דחכמים סבירא להו דלא כהלכתא דפליגי בפלוגתא דרבי שמעון ורבי יהודה לכן נ\"ל דטעמא דרבנן דלכך אסור לחצוץ שניו גזירה משום שמא יקטום וכן מסיק נמי בגמרא:"]]],[["אוכלי בהמה אין בהן משום תקון כלי","איתיביה רב כהנא לרב יהודה מטלטלין עצי בשמים להריח בהן ולהניף בהן לחולה ומוללו ומריח בו ולא יקטמנו להריח בו ואם קטמו פטור אבל אסור לחצוץ בו שיניו לא יקטמנו ואם קטמו חייב חטאת","א\"ל השתא פטור אבל אסור קא קשיא לי חייב חטאת מבעיא אלא כי תניא ההיא בקשין קשין בני מלילה נינהו","חסורי מחסרא והכי קתני מוללו ומריח בו קוטמו ומריח בו בד\"א ברכין אבל בקשין לא יקטמנו ואם קטמו פטור אבל אסור לחצוץ בו שיניו לא יקטמנו ואם קטמו חייב חטאת","תני חדא קוטמו ומריח בו ותניא אידך לא יקטמנו להריח בו אמר רבי זירא אמר רב חסדא לא קשיא הא ברכין הא בקשין","מתקיף לה רב אחא בר יעקב בקשין אמאי לא מאי שנא מהא דתנן שובר אדם את החבית לאכול ממנה גרוגרות ובלבד שלא יתכוין לעשות כלי ועוד הא רבא בר רב אדא ורבין בר רב אדא דאמרי תרוייהו כי הוינן בי רב יהודה הוה מפשח ויהיב לן אלותא אלותא אע\"ג דחזיא לקתתא דנרגי וחציני","לא קשיא הא ר\"א הא רבנן דתניא ר\"א אומר נוטל אדם קיסם משלפניו לחצוץ בו שיניו וחכ\"א לא יטול אלא מאבוס של בהמה ושוין שלא יקטמנו ואם קטמו לחצוץ בו שיניו ולפתוח בו הדלת בשוגג בשבת חייב חטאת במזיד ביו\"ט סופג את הארבעים דברי ר\"א","וחכ\"א אחד זה ואחד זה אינו אלא משום שבות ר\"א דקאמר התם חייב חטאת הכא פטור אבל אסור רבנן דקא אמרי התם פטור אבל אסור הכא מותר לכתחלה","ולית ליה לרבי אליעזר הא דתנן שובר אדם את החבית לאכול ממנה גרוגרות ובלבד שלא יתכוין לעשות כלי אמר רב אשי כי תניא ההיא במוסתקי:","ומגבב מן החצר: ת\"ר מגבב מן החצר ומדליק שכל מה שבחצר מוכן הוא ובלבד שלא יעשה צבורין צבורין ורבי שמעון מתיר במאי קא מפלגי מר סבר מחזי דקא מכניף למחר וליומא אחרינא ומ\"ס קדרתו מוכחת עליו:","אין מוציאין את האור וכו': מ\"ט משום דקא מוליד ביום טוב:","ואין מלבנין את הרעפים: מאי קא עביד אמר רבה בר בר חנה א\"ר יוחנן הכא ברעפים חדשים עסקינן מפני"],[[0,"גמ' אוכלי בהמה","כגון קש ועלי קנים אין בהם משום תקון כלי ומותר לקטום ולתקן קש של שבלין בשבת לחצוץ שניו:"],[1,"להניף","ווכטליי\"ר משום הבלא:"],[1,"ומוללו","בין אצבעותיו להוציא ריחו:"],[1,"ולא יקטמנו להריח בו","שיהא מקום הקטימה לח וריחו נודף גזירה דלא ליתי לקוטמו לחצוץ בו שניו דהתם כלי משוי ליה ואיכא איסורא דאורייתא:"],[1,"פטור","דאינו לשם כלי:"],[1,"חייב חטאת","בשבת ויש עצי בשמים שהן אוכלי בהמה ואפ\"ה חייב:"],[2,"א\"ל","רב יהודה השתא פטור אבל אסור קא קשיא לי כלומר תשובה גדולה חזרת להשיבני אם מצאת ברייתא אומרת לחצוץ בו שניו פטור אבל אסור אף היא היתה תשובה לדברי שאני אומר מותר לכתחלה וכל שכן שהבאת לי חיוב חטאת אבל אינה תשובה דכי תניא ההיא בעצי בשמים קשין שאינן ראויין למאכל בהמה:"],[3,"קוטמו ומריח בו","ואפי' לכתחלה דהא אף לחצוץ בו שניו שרי אלא אורחא דמילתא נקט שאין דרך רכין לתקנן לחצוץ:"],[5,"בקשין אמאי לא","להריח בו מי גזור רבנן כשאין מתכוין לכלי אטו מתכוין:"],[5,"והתנן שובר אדם חבית","מגופה שיש בה גרוגרות ואוכל ובלבד שלא יתכוין ליפות השבירה להיות לה לפה שתהא עוד כלי:"],[5,"הוה מפשח","איישבריי\"ר בלע\"ז כשמסעף בידו ענפים מעץ גדול כמו ויפשחני (איכה ג׳:י׳-י״א) עשה לי גדר בסעיפות בענפי עצי היער סביבות דרכי כדי שלא אצא כדרך שעושין בני היערים שקורין פליישי\"ץ:"],[5,"הוה מפשח","לן מן התלושין:"],[5,"אלותא","מקלות גדולים כמו ולא באלה ולא ברומח במסכת שבת (דף סג.):"],[5,"ואע\"ג דחזיא לקתתא דנרגי וחציני","שהיא קשה וראוי לעשות ממנו בית יד לקרדום ולפסל שקורין דולויי\"ר והוא היה שוברה להריח:"],[6,"לא יטול אלא מן האבוס של בהמה","דדבר הראוי לאכילה מוכן לכל צורך אבל עצים הואיל ודרכן לדבר האסור כגון לעשות כלים לא התירו לטלטלן אלא להסקה:"],[6,"שלא יקטמנו","אקיסם קאי:"],[7,"אחד זה ואחד זה","אחד שבת ואחד יום טוב:"],[7,"אינו אלא משום שבות","דקטימה תקון כלאחר יד הוא ולא תקון מעליא הוא אלא א\"כ מחתכו וממחקו בסכין והשתא קא מהדר לתרוצי קושיא דלעיל הא דתני לעיל בקשין לא יקטמנו להריח ר' אליעזר דאמר בקוטם לכלי חייב חטאת הכא גבי קוטם להריח פטור אבל אסור גזירה שמא יקטמנו לכלי והא דרב יהודה דמפשח להריח כרבנן דאמרי בקוטם לכלי פטור אבל אסור הכא להריח מותר לכתחילה:"],[8,"ולית ליה לרבי אליעזר כו'","והא הכא דכי מתכוין לעשות כלי איכא חיובא דאורייתא וכי לא מתכוין לא גזור רבנן לכתחילה:"],[8,"כי תניא ההיא","דמותר:"],[8,"במוסתקי","חבית שבורה שמדבקין שבריה בשרף של עץ שקורין שף שעושין הימנו זפת וקורין אותו ריישינ\"א וריחו דומה לריח לבונה ובלשון ערבי קורין אותו מוסתק\"י ומדבקין בו קערות חרס הנשברים כך אמר לי רבי שמואל המכונה חסיד מן ברבשט\"א וכיון דרעועה היא ליכא למגזר בה שלא יתכוון לעשות כלי:"]],[[2,"","פטור אבל אסור קא קשיא לי חייב חטאת מבעיא. פרש\"י תשובה גדולה חזרת להשיבני דאפי' פטור אבל אסור קא קשיא לי כ\"ש דחייב חטאת קא קשיא לי אבל לא קשיא כלל דהתם מיירי בקשין שאינן ראויין למאכל בהמה וקשה מאי מאריך בלשונו השתא פטור אבל אסור קא קשיא לי לשני ליה לאלתר התם מיירי בקשין וע\"ק דמשמע דבקשין מתסר לרב יהודה ובסמוך מתיר רב יהודה אף להריח דאמר דמפשח ויהיב אלותא וכו' ואר\"ת דגרסי' כגרסא דר\"ח דגריס א\"ל וה\"פ דרב יהודה משיב לרב כהנא פשיטא דהברייתא נשנית בטעות דהא הא דקאמר פטור אבל אסור קא קשיא לי דאדרבה מותר לגמרי ואפי' לכתחלה חייב חטאת מבעיא כ\"ש דנשנית בטעות כיון דקתני חייב חטאת וא\"ל רב כהנא לרב יהודה מצינן לשנויי לך דהברייתא מיירי בקשין שאין ראויין כלל למאכל בהמה ולכך זהו דלהריח פטור אבל אסור לחצוץ בו שניו חייב חטאת אבל לדידך קשה דבקשין נמי קא אמרת דמותר להריח כדקאמר מפשח ויהיב אלותא וכו' ומ\"מ רב יהודה לא הוה מודה ליה דרב יהודה ס\"ל דלחצוץ שניו פטור אבל אסור ולהריח מותר אפי' לכתחלה אף על גב דקשין הן להריח מותר:"],[5,"","כי הוינן בי רב יהודה הוה מפשח לן כו'. ומיירי להריח כדמסיק דסבר כרבנן דאמרו התם גבי לחצוץ שניו פטור אבל אסור ולהריח מותר אפי' לכתחלה ולא גזרו שמא יקטום וא\"ת למה נמנעו כשחל יו\"ט במ\"ש מלהריח בשמים משום שמא יקטום והא לא חיישינן כדמוכח הכא אליבא דרב יהודה דס\"ל כרבנן וגם אין שייך לפרושי טעמא משום אש גיהנם שמתחיל לשרוף ולהסריח ולכך מברכינן בכל מ\"ש דעלמא וכשחל יו\"ט במ\"ש אז אין האש מתחיל לשרוף ולהסריח ולכך לא מברכינן דהא גם ביו\"ט שובת דא\"כ גם במוצאי יו\"ט אמאי לא מברכינן אבשמים וגם אין לפרש דהא דמברכינן אבשמים במ\"ש משום נפש יתירה שאבד ומריח הבשמים ומישב דעתו עליו וכשחל במ\"ש אז אינו מפסיד נפש יתירה דביו\"ט אית ליה נשמה יתירה דא\"כ במוצאי יו\"ט אמאי לא מברכינן אבשמים ואי ליכא הני טעמי א\"כ מ\"ט דמברכינן אבשמים במ\"ש וי\"ל דלעולם טעמא דמברכי' אבשמים במ\"ש הוי משום נשמה יתירה ובי\"ט ליכא נשמה יתירה וא\"ת אמאי לא מברכין אבשמים כשחל יו\"ט להיות במ\"ש כיון דיש לו מאכלים חשובים וטובים מישב דעתו ממילא בלא ריח בשמים:"],[8,"","כי תניא ההיא במוסתקי. מזופפת ורעועה פירש רש\"י דלא חיישינן לתקון כלי דהואיל ורעועה הרבה יחוס עליה דשמא יקלקל החבית ועושה נקב לכל הפחות שיוכל וה\"ר יצחק פירש במסכת ערובין (דף לד: ושם בד\"ה ואמאי) דכיון שהם מדובקים בזפת ואין החתיכות שלמות לא הוי שום תקון כלי:"]]],[["שצריך לבדקן ואמרי לה מפני שצריך לחסמן","תנן התם דרסה או שטרפה בכותל או שרצצתה בהמה ומפרכסת ושהתה מעת לעת ושחטה כשרה א\"ר אלעזר בר ינאי משום ר' אלעזר בן אנטיגנוס צריכה בדיקה","בעא מיניה ר' ירמיה מרבי זירא מהו לשחטה ביום טוב מי מחזקינן רעותא ביום טוב או לא","אמר ליה תנינא אין מלבנין את הרעפים לצלות בהן והוינן בה מאי קא עביד ואמר רבה בר בר חנה א\"ר יוחנן הכא ברעפים חדשים עסקינן מפני שצריך לבדקן","אמר ליה אנן מפני שצריך לחסמן מתנינן לה:","תניא אחד מביא את האור ואחד מביא את העצים ואחד שופת את הקדרה ואחד מביא את המים ואחד נותן בתוכו תבלין ואחד מגיס כולן חייבין והתניא אחרון חייב וכולן פטורין לא קשיא הא דאייתי אור מעיקרא הא דאייתי אור לבסוף","בשלמא כולהו קא עבדי מעשה אלא שופת את הקדרה מאי קא עביד אמר רבי שמעון בן לקיש הכא בקדרה חדשה עסקינן ומשום לבון רעפים נגעו בה:","ת\"ר תנור וכירים חדשים הרי הן ככל הכלים הנטלין בחצר אבל אין סכין אותם שמן ואין טשין אותן במטלית ואין מפיגין אותן בצונן כדי לחסמן ואם בשביל לאפות הרי זה מותר:","תנו רבנן מולגין את הראש ואת הרגלים ומהבהבין אותן באור אבל אין טופלין אותם בחרסית ולא באדמה ולא בסיד ואין גוזזין אותן במספרים","ואין גוזזין את הירק בתספורת שלו אבל מתקנין את הקונדס ואת העכביות ומסיקין ואופין בפורני ומחמין חמין באנטיכי ואין אופין בפורני חדשה שמא תפחת:","ת\"ר אין נופחין במפוח אבל נופחין בשפופרת ואין מתקנין את השפוד ואין מחדדין אותו ת\"ר אין מפצעין את הקנה לצלות בו מליח אבל מפצעין את האגוז במטלית ואין חוששין שמא תקרע:","\u0001מתני׳\u0002 ועוד אמר רבי אליעזר עומד אדם על המוקצה"],[[0,"שצריך לבודקן","אם יוכלו לקבל לבונה הלכך ביו\"ט לא דלמא פקעי ואשתכח דטרח שלא לצורך:"],[0,"ואמרי לה שצריך לחסמן","להקשותם בהסק ראשון הם מתחזקין ומתקשים הלכך אע\"ג דלצורך יו\"ט נמי הוא דהא צולין עליהם מיהו כיון דבהסק זה נעשה כלי אסור:"],[1,"תנן התם","באלו טרפות:"],[1,"דרסה וטרפה בכותל","אדם שדרס על העוף או שזרקו וחבטו בכותל:"],[1,"או שרצצתה בהמה ומפרכס'","ואינה יכולה לעמוד:"],[1,"ושהתה מעת לעת","יום א' שלם ושחטה כשרה:"],[1,"ה\"ג א\"ר אלעזר בר' ינאי משום ר\"א בן אנטיגנוס צריכה בדיקה","כי שהתה מעת לעת נמי צריכה בדיקה לאחר שחיטה שמא נשתברו רוב צלעותיה או נשברה השדרה ונפסק החוט שלה או אחד משאר מיני טרפות ושהייה דמעת לעת אצטריך דאי לא שהתה אע\"פ שבדקה ולא מצא סימן טרפות טרפה שזו היא אחת משמנה עשרה טרפות ונקרא רסוקי אברים שאבריה מתפרקין כולן ואע\"פ שאין רושם ניכר בה וזהו סימנה אם שהתה מעת לעת בידוע שלא נתרסקו אבריה דקים להו לרבנן מסיני דרסוק אברים אינה חיה מעת לעת אבל שאר מיני טרפה חיה כל שנים עשר חדש:"],[2,"מהו לשחטה ביו\"ט","מי חיישינן הואיל וצריכה בדיקה ואיתיליד בה רעותא:"],[2,"מי מחזקינן רעותא","בגוה משום חשש איסור מלאכה ביו\"ט דלמא משתכח טרפה ונמצא שוחטה שלא לצורך בשלמא שאר בהמות אע\"ג דמחמרינן אנפשין ובדקינן מיהו סמכינן ארובא ורוב בהמות אינן טרפות הכא מאי:"],[2,"ביו\"ט","כלומר משום חומר מלאכה ביו\"ט:"],[3,"מפני שצריך לבדקן","וחיישינן דלמא פקעי אלמא מחזקינן רעותא משום חומר יו\"ט שלא ללבנן:"],[4,"מפני שצריך לחסמן","ולא משום חשש פקיעה אלא דודאי משוי ליה מנע בהסק זה:"],[5,"שופת את הקדרה","מושיבה רקנית על האור:"],[5,"מגיס","מנער בכף שקורין קומיבר\"א:"],[5,"כולן חייבין","מביא את האור משום מבעיר את הגחלת דכשהוא מוליכה היא מתלבנה מרוח הליכתו ומביא את העצים לאור משום מבעיר שופת קדרה לקמיה מפרש מאי עביד נותן מים ותבלין ומגיס משום מבשל שאף הוא אב מלאכה:"],[5,"דאייתי אור מעיקר'","כולהו עבדי מעשה כדפרישי':"],[5,"דאייתי אור לבסוף","איהו הוא דעבד והנך לא עבדי מידי:"],[6,"בקדירה חדשה עסקינן","שנותנין אותה רקנית על האור לחסמה:"],[6,"ומשום לבון רעפים נגעו בה","משום הך גזירה גופה שאסרו ללבן רעפים נגעו גם בזו:"],[7,"חדשים","וכ\"ש ישנים:"],[7,"הרי הן ככל הכלים הנטלין","בשבת בחצר דחזו למיתב בגוייהו מידי:"],[7,"אין סכין אותן שמן","להחליקן ולצחצחן:"],[7,"טשין","שפין:"],[7,"ואין מפיגין אותן","לאחר הסקן אין מפיגין הסקן בצונן לחסמן שמתקשין ע\"י הצונן וכולהו משום דמתקן מנא:"],[7,"ואם","להפיגה בשביל לאפות שהוסקו הרבה וחושש שלא תשרף הפת מותר:"],[8,"מולגין","ברותחין:"],[8,"אין טופלין אותן","בסיד להסיר שערן דהוי דרך העבדנין:"],[8,"ואין גוזזין אותן במספרים","דמחזי כצריך לשער:"],[9,"ואין גוזזין הירק","התלוש שיש בו ראשי עלין נרקבין וכמושין אין גוזזין אותן בתספורת שלו שגוזזין בה מן המחובר דמאן דחזי סבר שלקטן היום:"],[9,"קונדס ועכביות","מיני ירקות הן שיש טורח בתקונן:"],[9,"פורני","הן תנורים שלנו הגדולים ופיהם בצדם ולא חיישינן לטרחא אם יש לו אוכלין הרבה דלא סגי ליה בתנור:"],[9,"שמא תפחת","ע\"י שחדשה היא ונמצא טורח שלא לצורך:"],[10,"אין נופחין במפוח","דמחזי כאומן עושה מלאכה:"],[10,"ואין מתקנין את השפוד","ודלא כר' יהודה אי נמי בנרצם מערב י\"ט ודברי הכל:"],[10,"אין מפצעין את הקנה","לתת קרומיותיו תחת המליח על האסכלא שעושה כלי דכל מידי דעביד להשתמש בו הוי תקון כלי:"],[10,"ואין חוששין שמא תקרע","ואפי' נקרעת לא אכפת לן דאין זה קורע על מנת לתפור:"],[11,"מתני' ועוד אמר ר' אליעזר","משום דתנא אחת לקולא גבי מוקצה והדר אמר אחריתי קאמר ועוד וקשיא לי בגוה והא אפסקוה רבנן במילי טובא באין מוציאין את האור והנך דבהדיה והיינו מלתא אחריתי דלאו מלתיה ואמאי לא אותביניה בעירובין (דף כג.) גבי ועוד דר' יהודה בן בבא דאותביה מר\"א דסוכה ושנינן לא אפסקוה אלא במלתיה ואלו אותבינה מהא לא הוה ליה לשנויי הכי ואומר אני שגרסת המשנה שלא כסדר:"],[11,"עומד אדם על המוקצה","הצריך הזמנה והזמנה מועלת לו כגון אחזי ולא אחזי דאמר באין צדין (לעיל ביצה דף כו:):"]],[[6,"","הכא בקדרה חדשה עסקינן. ומשום לבון רעפים נגעו בה ויש נזהרים שלא לבשל בתחלה בקדרה חדשה ולא היא דהכא בקדרה רקנית דאז שייך בה לבון רעפים ששופתה קודם שמביא המים אבל כשמבשלין בה מאכל לא שייך בה לבון רעפים:"],[7,"","ואין מפיגין אותן בצונן כדי לחסמן ואם בשביל לאפות הרי זה מותר. ותימה דאמר לעיל אסור לחסמן אע\"פ שהוא עושה נמי כדי לצלות עליהם וי\"ל דשאני בין רעפים לתנור דתנור (שאני) כיון דהוא עושה ע\"י משקין שאני דאינו ודאי חוסמן:"],[8,"","מולגין הראש והרגלים. אבל כל גופו של גדי אסור הואיל ויכול בהפשט הקלה לעשות טפי:"],[9,"","ואין אופין בפורני חדשה שמא תפחת. וא\"ת והא אמרינן לעיל ואם בשביל לאפות מותר וי\"ל דהכא שאני בפורני שהוא גדול ויש לחוש יותר שמא תפחת:"],[10,"","אין נופחין במפוח כו'. פירש ר\"י מדלא מפליג בין מפוח של אומנין ובין מפוח של בעל הבית כי היכי דמפליג בשל אומן בין מפוח לשפופרת משמע דכל המפוחין אסורים אפילו של בעל הבית נמי ויש ליזהר שלא לנפח בו כלל מיהו העולם נהגו בו היתר ע\"י להפכו מלמעלה למטה ואומר מ\"ו הר\"ר פרץ נ\"ע דיש לדחות מה שפיר' מדלא מפליג וכו' דשמא הא עדיפא ליה דכולי בשל אומן קא מיירי:"],[11,"","ועוד אמר ר' אליעזר עומד אדם כו'. פרש\"י דמשום דקאמר ר\"א חדא לעיל גבי נוטל אדם קיסם קאמר הכא ועוד אחריתי לקולא והקשה רש\"י הא אפסקו במילי טובא באין מוציאין האור והיינו במלתא אחריתי דלא. אמרו בה רבי אליעזר ורבנן וא\"כ לא שייך ביה למימר ועוד דהכי מוכח בעירובין (דף כג. ושם) דכל היכא דאפסקוה בדבר דלא איירו בה לא שייך למימר ועוד ע\"כ נראה לפירוש רש\"י דהגרסא מהמשנה משובשת היא בספרים והא דאמר ר' אליעזר עומד אדם כו' יש להיות קודם ההיא דאין מוציאין וכו' וקשה דא\"כ גם סדר הגמ' אינו כמשפט ור\"ת אומר דהיכא דהוו תרוייהו לקולא שפיר קאמר ועוד אע\"ג דאפסקו במילי אחריני והא דאמרינן בעירובין דלא שייך למימר ועוד היינו היכא דהוו חדא לחומרא וחדא לקולא והא דאפסקוה זהו לפי שרוצה לשנות מילי דאור גבי הדדי:"]]],[["ערב שבת בשביעית ואומר מכאן אני אוכל למחר וחכמים אומרים עד שירשום ויאמר מכאן ועד כאן:","\u0001גמ׳\u0002 תנן התם תינוקות שטמנו תאנים מערב שבת ושכחו ולא עשרו למוצאי שבת לא יאכלו אלא אם כן עשרו ותנן נמי המעביר תאנים בחצרו לקצות בניו ובני ביתו אוכלין מהן עראי ופטורים","בעא מניה רבא מרב נחמן שבת מהו שתקבע מוקצה למעשר בדבר שלא נגמרה מלאכתו מי אמרינן כיון דכתיב (ישעיהו נח, יג) וקראת לשבת עונג קבעה ואפילו בדבר שלא נגמרה מלאכתו או דלמא בדבר שנגמרה מלאכתו קבעה בדבר שלא נגמרה מלאכתו לא קבעה","א\"ל שבת קובעת בין בדבר שנגמרה מלאכתו בין בדבר שלא נגמרה מלאכתו א\"ל ואימא שבת דומיא דחצר מה חצר אינה קובעת אלא בדבר שנגמרה מלאכתו אף שבת לא תקבע אלא בדבר שנגמרה מלאכתו א\"ל לימוד ערוך הוא בידינו שהשבת קובעת בין בדבר שנגמרה מלאכתו בין בדבר שלא נגמרה מלאכתו","אמר מר זוטרא בריה דרב נחמן אף אנן נמי תנינא ועוד אמר רבי אליעזר עומד אדם על המוקצה ערב שבת בשביעית וכו' טעמא דשביעית דלאו בר עשורי הוא הא בשאר שני שבוע הכי נמי דאסור מ\"ט לאו משום דשבת קבעה","לא שאני התם כיון דאמר מכאן אני אוכל למחר קבע ליה עלויה אי הכי מאי אריא שבת אפילו בחול נמי הא קמ\"ל דטבל מוכן הוא אצל שבת שאם עבר ותקנו מתוקן"],[[0,"ערב שבת בשביעית","שאין מעשר נוהג בה ואין מחוסר אלא הזמנה וה\"ה במעושר ובשאר שני שבוע אלא אורחא דמלתא נקט דסתם מוקצה לאו מעושר הוא דגרוגרות וצמוקים הן סתם מוקצה ואין רגילין לעשר קודם גמר מלאכה:"],[0,"ואומר מכאן אני נוטל למחר","וסגי בהכי דיש ברירה:"],[0,"עד שירשום","בסימן דאין ברירה:"],[1,"גמ' תינוקות שטמנו תאנים","בשדה או בגנה לאכילת שבת ושכחו ולא עשרו כו' לא יאכלו ואף על גב דקי\"ל אין הטבל מתחייב במעשר לאוכלו אכילת עראי עד שיראה פני הבית או פני החצר בב\"מ בהשוכר את הפועלים (ב\"מ דף פח.) אכילת שבת חשובה ועראי שלה הרי הוא קבע והרי הוטמנו לאכילת שבת והוקבעו והאי דנקט תינוקות רבותא היא דאשמעינן דיש להם מחשבה ע\"י מעשה המוכיח כדאמרינן בהכל שוחטין (חולין דף יג.) ותאנים דבר שנגמרה מלאכתן הוא אא\"כ חשב עליהן לקציעות או לגרוגרות ושמעינן מינה בדבר שנגמרה מלאכתו שבת קובעת למעשר בלא ראיית פני הבית ובדבר שלא נגמרה מלאכתו לא שמעינן אי קבעה אי לא קבעה:"],[1,"ותנן המעביר תאנים","השוטח תאנים בחצרו:"],[1,"לקצות","ליבשן לעשות מהן קציעות ולאחר שנעשו קציעות דורסן בעגול:"],[1,"בניו ובני ביתו אוכלין מהן עראי ופטורין","מלעשר דאין חצר קובעת בראיית פנים אלא בדבר שנגמרה מלאכתו ומבעיא ליה לרבא שבת מי הוה כחצר או עדיפא מיניה:"],[2,"מהו שתקבע מוקצה למעשר","מוקצה היינו לא נגמרה מלאכתו:"],[2,"בדבר שלא נגמרה מלאכתו","לישנא יתירא הוא והוא פי' של מוקצה ונכתב בספרים:"],[2,"כיון דכתיב וקראת לשבת עונג","כיון דאקרי אכילה דידיה עונג קבעה שאין בה עוד שם עראי אלא שם קבע:"],[3,"שבת קובעת","אם יחדה לשבת אסורה אף למוצאי שבת ואם לא יחדה לשבת בשבת אסור לכל שאכילתה לעולם קבע היא קרויה אבל למוצאי שבת מותר כדלקמן:"],[4,"על המוקצה","וסתמיה לא נגמרה מלאכתו עד עתה:"],[4,"שביעית","לאו בר עשורי היא נפקא לן במכילת' מואכלו אביוני עמך ויתרם תאכל חית השדה (שמות כ״ג:י״א) מה חיה אוכלת שלא במעושר אף אדם אוכל שלא במעושר:"],[4,"הכי נמי דאסיר","לאכול למחר משום מעשר:"],[4,"מאי טעמא","בשאר שני שבוע לא הא בשאר שני שביעית לא קבע למעשר בלא ראיית פני הבית ואפי' בבית אינו נקבע אלא בכניסתו דרך שערים כדאמרינן בהשוכר את הפועלים (ב\"מ דף פח.) וזה כשנכנס לא נקבע דהא לא נגמרה מלאכתו ואמר לעיל דאין חצר קובעת אלא בדנגמר ובית וחצר שוין כדאמרי' התם בהשוכר ואמאי נקט מתניתין שביעית למיסר שאר שנים לאו משום קביעות דשבת:"],[5,"שאני התם כו'","דאיהו אחשבה בדבורו שקראה אכילה:"],[5,"אי הכי","דטעמיה משום דבוריה הוא:"],[5,"מאי אריא שבת","מאי אריא דאשמעינן הך בשבת לשמעינן בחול ובסדר זרעים והכא ליפלגו בהכנה דגוזלות כדאפלגו ב\"ש וב\"ה בברירה:"],[5,"הא קמ\"ל דטבל מוכן הוא כו'","להכי נקט גבי שבת לאשמועינן מלתא אחריתי אגב אורחיה דאצטריך לאפלוגי בהכנה תנא נמי הא בהדיה דבשאר שני שבוע אינו אסור משהזמינן אלא משום מעשר בלבד אבל הכנה איתא שאם בא אדם אחד ועבר ותקנו מתוקן ומותר לאכול ולא אמרינן לא מהניא ליה הזמנה כל זמן שלא נתקן דהא מוקצה מחמת אסור טבל הוא ואסחיה מדעתיה קמ\"ל כיון דהגבהת תרומה ומעשר מדאורייתא בשבת שרי אין זה מוקצה מחמת איסור והכי שמעינן ליה ממתניתין מדקתני עומד אדם על המוקצה לכתחלה בשביעית ולא מצי למידק מינה איסור בשאר שני שבוע אלא הכי קאמר הא בשאר שני שבוע לא יעמוד ויאמר כן דקבע ליה בדבוריה ומחייב במעשר ולמחר אכיל ליה בטבליה דאי ס\"ל לתנא דאיסור מוקצה נמי לא פקע מיניה הכי הוה ליה למתני העומד על המוקצה ערב שבת בשביעית ואומר מכאן אני אוכל למחר הרי זה מן המוכן ודייקינן מיניה הא בשאר שני שבוע אינו מוכן אי נמי עומד אדם על המוקצה ע\"ש בשביעית ואומר מכאן אני אוכל למחר והרי זה מן המוכן ודייקינן מינה הא בשאר שני שבוע אינו מוכן אבל השתא לא שמעינן מדיוקא דנתסר משום מוקצה אלא משום מעשר:"]],[[0,"","ואומר מכאן אני נוטל. מקשה בירושלמי מחלפא שטתייהו דב\"ש לעיל. קאמר לא יטול אא\"כ נענע והכא קאמר דבאמירה בעלמא סגי דהא ר\"א שמותי הוא [א] וי\"ל דלא קשה דלא מחלפא שטתייהו דמוקצה דבעלי חיים. עדיף ומחמירין טפי אבל קשה דמחלפא שטתייהו דב\"ה דלעיל קאמר דבאומר מכאן אני נוטל למחר סגי והכא קאמר דבעי שירשום ויש לומר דשאני הכא דאקצייה בידים:"],[1,"","תינוקות שטמנו וכו'. ואע\"ג שיכולין לאכול אכילת עראי עד שיראו פני הבית או פני החצר מ\"מ אכילת שבת חשובה ועראי שלו קבע וכיון שטמנו. בשבת לאכול הוקבעו אע\"פ שעבר שבת ונקט תינוקות לרבותא אע\"פ שאין להם מחשבה גרידא מעשה יש להם:"],[1,"","בניו ובני ביתו אוכלין אכילת עראי. פי' בירושלמי דוקא בניו אבל איהו גופי' אקבעינהו דגלה בדעתו להניחם שם כך:"],[4,"","הא בשאר שני שבוע לא. דשבת אקבעינהו וכללא דשמעתין כל היכא דר\"ל שקובע קובע בלא ראיית פני הבית כמו אם הכניסן דרך (שערים) [דרך גגות וקרפיפות]:"],[5,"","אי הכי מאי אריא שבת אפי' בחול נמי. אי הכי דטעמא משום דקבעי' בדבורו אפילו בחול נמי וכ\"ת משום דאצטריך לאשמועינן הכנה ומכאן אני נוטל לפיכך נקט שבת והא מתני' קמשמע לן תרתי דדבורו קובע ואשמועינן דין הכנה דא\"כ לשמעינן בחול דבורו קובע דהוי רבותא טפי ופלוגתא דהכנה לשמעינן במקום אחר בפירות מתוקנים אם כנסן לאוצר בצריך שירשום ולומר סגי לומר מכאן אני נוטל משמע מדנקט שבת לענין טבל דשבת קובע בטבל בשאר ימי שבוע א\"נ ה\"פ לשמעינן בחול דדבורו קובע ובהכנה לפלגו פלוגתא דב\"ה וב\"ש גבי גוזלות כדאיתא לעיל ולא נהירא כדפרישית לעיל דלא שייך פלוגתייהו בבעלי חיים:"],[5,"","הא קמ\"ל דטבל מוכן הוא אצל כו'. לכך נקטינהו לענין שבת דאגב אורחיה דהכנת שבת אשמועינן חדוש אחר דהיכא דהזמינו לשבת דאינו אסור אלא משום מעשר המעורב ואם בא אדם ותקנו מתוקן ולא אמרינן הואיל ונתקצה בשביל מעשר שבתוכו נתקצה לכל היום הואיל והגבהת תרומות ומעשרות לא הוי אלא מדרבנן והכי דייק ליה מדתני עומד אדם על המוקצה וכו' משמע הא בשאר שני שבוע לא יעמוד לכתחלה הא אם עבר ותקנו מתוקן אבל אי ס\"ל לתנא דמשום איסור מוקצה לא תקנו כשעבר ותקנו הכי הל\"ל . העומד על המוקצה ע\"ש בשביעית ואומר מכאן אני נוטל למחר הרי הוא מן המוכן ודייקינן מינה הא בשאר שני שבוע אינו מן המוכן:"]]],[["והלא מותרו חוזר ושמעינן ליה לרבי אליעזר דאמר כל היכא דמותרו חוזר לא קבע","דתנן הנוטל זיתים מן המעטן טובל אחת אחת במלח ואוכל ואם טבל ונתן לפניו עשרה חייב ר\"א אומר מן המעטן טהור חייב מן המעטן טמא פטור מפני שהוא מחזיר את המותר","והוינן בה מאי שנא רישא ומאי שנא סיפא וא\"ר אבהו רישא במעטן טהור וגברא טמא דלא מצי מהדר ליה","סיפא במעטן טמא וגברא טמא דמצי מהדר ליה","מתניתין נמי במוקצה טהור וגברא טמא דלא מצי מהדר ליה והלא מוחזרין ועומדין הן","אלא אמר רב שימי בר אשי ר\"א קא אמרת רבי אליעזר לטעמיה דאמר תרומה קבעה וכ\"ש שבת דתנן פירות שתרמן עד שלא נגמרה מלאכתן ר\"א אוסר לאכול מהן עראי וחכמים מתירין","ת\"ש מסיפא וחכ\"א עד שירשום ויאמר מכאן ועד כאן טעמא דע\"ש בשביעית דלאו בר עשורי הוא הא בשאר שני שבוע דבני עשורי נינהו אסורים מ\"ט לאו משום דשבת קבעה","לא שאני התם כיון דאמר מכאן ועד כאן אני אוכל למחר קבע ליה אי הכי מאי אריא שבת אפילו בחול נמי הא קמ\"ל דטבל מוכן הוא אצל שבת שאם עבר ותקנו מתוקן","ורמינהי היה אוכל באשכול ונכנס מגנה לחצר ר\"א אומר יגמור רבי יהושע אומר לא יגמור","חשכה בלילי שבת ר\"א אומר יגמור ר' יהושע אומר לא יגמור","התם כדקתני טעמא ר' נתן אומר לא כשאמר ר\"א יגמור בחצר יגמור אלא יוצא חוץ לחצר ויגמור ולא כשאמר ר\"א יגמור בשבת יגמור אלא ממתין למוצאי שבת ויגמור","כי אתא רבין א\"ר יוחנן אחד שבת ואחד תרומה ואחד חצר ואחד מקח כולן אין קובעין אלא בדבר שנגמרה מלאכתן","שבת לאפוקי מדהלל דתניא המעמר פירות ממקום למקום לקצור וקדש עליהן היום א\"ר יהודה הלל לעצמו אוסר"],[[0,"והלא מותרו חוזר","היכי מצית למימר דקביעותא משום דבורא הוא והלא אפי' נוטל הרבה מן הטבל בחול ונותן לפניו דמחזי דקביע ליה באכילה מרובה אם דבר הראוי להחזיר המותר אחר אכילתו למקום שנטלו משם הא שמעינן ליה לרבי אליעזר דאמר לא קבע בנטילה קמייתא וכל שכן בדבורא בלא מעשה לא מקבע:"],[1,"מעטן","כלי גדול שצוברין בו את הזיתים כדי שיתחממו ויתבשל שמנן בתוכן ויהא נוח להוציאו בבית הבד:"],[1,"טובל אחת אחת במלח ואוכל","בלא מעשר ולא אמרינן טבולן במלח משוי ליה קבע הואיל ואחת אחת אוכלן מיד:"],[1,"מן המעטן טהור חייב","לעשר שאין ראוי להחזיר מותרו כדמוקי לה לקמיה בגברא טמא שנטמא במגעו וכשמחזירן מתערבין הטמאים עם הטהורים ומטמא השמן וכיון דאין ראוי להחזיר מותרן ודאי כי שקלינהו מעיקרא אדעתא למיכל לכולהו שקלינהו ושוייה אכילת קבע:"],[1,"מן המעטן טמא פטור","מפני שראוי להחזיר המותר וכי שקלינהו מעיקרא ברישא אדעתא למיכל פורתא ואהדורי מותר שקל:"],[2,"מאי שנא רישא","דאין יכול להחזיר משום דמעטן טהור והא אפשר להיות גם אם האדם טהור:"],[2,"וא\"ר אבהו","כולה בגברא טמא מתוקמא רישא דמעטן טהור לא מצי למהדר וא\"ת הרי נטמאו זיתי המעטן כשנטל מהן לא טמא אלא מקום מגעו ויכול לסלקן משם:"],[2,"","ה\"ג רישא במעטן טהור וגברא טמא דלא מצי למהדר סיפא בגברא טמא ומעטן טמא דמצי למהדר:"],[4,"ומשנינן מתניתין נמי","דקבע בדבוריה במוקצה טהור וגברא טמא עסקינן דלא מצי למהדר מותרו:"],[4,"ופרכינן והלא מוחזרין ועומדין","והלא לא נטלן אלא דבורא בעלמא הוא וכיון דכי נטלן ואפשר בחזרה מהניא ליה חזרה ולא מקבע כי לא אפשר בחזרה נמי ולא נטלן אלא דבורא בעלמא אין לך חזרה כזו דאפילו משקל נמי לא שקלינהו:"],[5,"ה\"ג אלא אמר רב שימי בר אשי כו'","אלא לעולם שבת הוא דקבעה במתני' וכי מסלקת ליה למר זוטרא מסייעתיה דלא לסייעי' לאבוה ממתני' הכי תסלקיה:"],[5,"ר\"א קא אמרת","מיניה מייתית סייעתא דשבת קבעה אף בשלא נגמרה מלאכתן:"],[5,"ר\"א לטעמיה דאמר תרומה קובעת","דבר שלא נגמרה מלאכתו שאם הגביה תרומתו נאסר לאכילת עראי עד שיפריש שאר מעשרות:"],[5,"וכ\"ש שבת","דחשיבא אכילתה אבל רבנן אימא לך כי היכי דפליגי בתרומה פליגי בשבת:"],[6,"ת\"ש מסיפא","דלא אפלוג רבנן עליה אלא לענין ברירה אבל מודו ליה דדוקא ע\"ש בשביעית הא בשאר שני שבוע אסור משום מעשר:"],[7,"דטבל מוכן הוא כו'","כדפרי' והכא לא מצי למפרך והרי מותרו חוזר כדפריך לעיל אליבא דר\"א משום דרבנן שמעינן להו דאפילו מותרו חוזר דחיילא עליה קביעותא הלכך איכא למתלי טעמייהו דרבנן במתני' נמי משום דאיהו קבעיה ולא משום שבת:"],[8,"ורמינהי","דר\"א אדרבי אליעזר:"],[8,"היה אוכל באשכול","וסתם אשכול לאו גמר מלאכה היא דסתם ענבים לדריכה קיימי:"],[8,"ונכנס מגנה","שלקטם משם ובא לו לחצר:"],[8,"ר\"א אומר יגמור","אם רצה לגמור בחצר ויגמור אכילתו דאין חצר קובעת דבר שלא נגמרה מלאכתו:"],[8,"רבי יהושע אומר לא יגמור","קסבר חצר קובעת דבר שלא נגמרה מלאכתו:"],[9,"הכי גרסינן חשכה לילי שבת רבי אליעזר אומר יגמור","אם רצה לגמור כי היכי דאמר בחצר אמר בשבת יגמור אכילתו דאין שבת קובעת דבר שלא נגמרה מלאכתו ומתניתין אוקימנא טעמא דר\"א דבשאר שני שבוע לא משום דשבת קבעה דמשום דבוריה לא מצינא למימר דהא לרבי אליעזר מותרו חוזר:"],[10,"","הכי גרסינן רבי נתן אומר לא כשאמר רבי אליעזר יגמור בחצר יגמור אלא יצא חוץ לחצר ויגמור ולא כשאמר יגמור בשבת יגמור אלא ימתין כו' - ותרוייהו אדרבי אליעזר קאי דאית ליה לרבי אליעזר שבת קבעה ומיהו למוצאי שבת יגמור דלא דמיא לתינוקות שטמנו תאנים דתנן בהו לעיל למוצאי שבת לא יאכלו דהתם לאכילת שבת יחדום הלכך קבעה עלייהו אבל זו לא יחדה לשבת יש ספרים שהיא כתובה בהם בשבוש וכן גרסינן לה במשנה דמסכת מעשרות דרבי נתן בתוספתא דמעשרות הכי איתמר:"],[11,"ואחד מקח","אם מכרן לחבירו קודם גמר מלאכה לא אמרינן אחשבינהו בהכי ואצטריכא ליה לרבי יוחנן לאשמועינן משום דאיכא למאן דאמר קבעה כדלקמן:"],[12,"שבת","איצטריך לרבי יוחנן למימר:"],[12,"לאפוקי מדהלל","דלית הלכתא כותיה אלא כרבנן דפליגי עליה:"],[12,"הלל לעצמו","הלל לבדו אוסר משמע דכל דורו חלוקין עליו:"]],[[0,"","והלא מותרו חוזר. ולרבי אליעזר אפי' נטל הרבה מן הטבל בחול לא הוי קביעות כדמוכח בסמוך בדבר הראוי להחזיר מותר וכל שכן דדבורו אינו קובע:"],[2,"","רישא במעטן טהור וגברא טמא דלא מצי למהדר. וא\"ת והרי נטמאו זיתי המעטן כשנטל מהן וי\"ל דלא טמא אלא מקום מגעו ויכול לסלקו מלמעלה שלא יגע באחרים ומ\"מ אינו ראוי להחזיר המותר לפי שמתערבים הטהורים עם הטמאים כך פ\"ה אי נמי כגון שנטלו בפשוטי כלי עץ או שנתן לו חברו:"],[4,"","והלא הן מוחזרין ועומדין. דלא נטלן אלא בדבורא בעלמא ואין לך חזרה גדולה מזו דאפי' בראוי להחזיר לא מקבע כ\"ש בלא נטל כלל:"],[5,"","אלא אמר רב שימי וכו'. ודאי לר' אליעזר קובע שבת אפילו בלא נגמרה מלאכתו כמו גבי תרומה אבל לרבנן דמתירין גבי תרומה לא ידעינן גבי שבת:"],[6,"","תא שמע מסיפא. דלא פליגי רבנן אלא דוקא בברירה:"],[7,"","[שאני התם כיון דאמר מכאן]. והכא לא שייך למפרך והלא מותרו חוזר דלרבנן לית להו הך סברא דלעולם מותרו קובע:"],[10,"","רבי אליעזר אומר יגמור בשבת אלא כו'. וא\"ת מ\"ש מתינוקות שטמנו דלמוצאי שבת לא יאכלו ויש לומר דהתם יחדום לאכילת שבת אבל הכא לא יחדום לשבת כפי' רש\"י אי נמי דהתם מיירי בתאנים דנגמרה מלאכתן אבל הכא מיירי באשכול שלא נגמרה מלאכתו:"],[11,"","אחד שבת אינו קובע וכו' אינו קובע אלא בדבר שנגמרה מלאכתו. ואם תאמר מאי נפקא מינה כיון דאינו קובע אלא בדבר שנגמרה מלאכתו וי\"ל דנפקא מינה דקובע אפי' קודם ראיית פני הבית:"],[12,"","שבת לאפוקי מדהלל. ובדין הוא דהו\"מ למנקט לאפוקי מדרבי אליעזר דאמר קובע אפי' בדבר שלא נגמרה מלאכתו ומשום הכי לא נקטיה משום דלאו רבותא הוא דבלאו הכי אין הלכה כמותו דשמותי הוא ומ\"מ קאמר בסמוך תרומה לאפוקי מדרבי אליעזר דלא אשכח תנא דאמר תרומה קובעת במעשר בדבר שלא נגמרה מלאכתו אלא רבי אליעזר:"]]],[["חצר לאפוקי מדרבי יעקב דתנן המעביר תאנים בחצרו לקצות בניו ובני ביתו אוכלין מהן עראי ופטורים מן המעשר ותני עלה רבי יעקב מחייב ור' יוסי בר' יהודה פוטר","תרומה לאפוקי מדרבי אליעזר דתנן פירות שתרמן עד שלא נגמרה מלאכתן ר\"א אוסר לאכול מהן עראי וחכמים מתירין","מקח (כדתנן) הלוקח תאנים מעם הארץ במקום שרוב בני אדם דורסין אוכל מהן עראי ומעשרן דמאי","שמע מינה תלת ש\"מ מקח אינה קובעת אלא בדבר שנגמרה מלאכתו וש\"מ רוב עמי הארץ מעשרין הן וש\"מ מעשרין דמאי מעמי הארץ אפי' בדבר שלא נגמרה מלאכתו","ולאפוקי מהא דתנן המחליף פירות עם חבירו זה לאכול וזה לאכול זה לקצות וזה לקצות זה לאכול וזה לקצות חייב רבי יהודה אומר לאכול חייב לקצות פטור:","\u0001הדרן עלך המביא\u0002","מתני׳ \u0001משילין\u0002 פירות דרך ארובה ביו\"ט אבל לא בשבת ומכסים פירות בכלים מפני הדלף וכן כדי יין וכדי שמן ונותנין כלי תחת הדלף בשבת:","\u0001גמ׳\u0002 אתמר רב יהודה ורב נתן חד תני משילין וחד תני משחילין","אמר מר זוטרא מאן דתני משילין לא משתבש ומאן דתני משחילין לא משתבש מאן דתני משילין לא משתבש דכתיב (דברים כח, מ) כי ישל זיתך ומאן דתני משחילין לא משתבש דתנן השחול והכסול שחול שנשמטה ירכו כסול שאחד מירכותיו גבוהה מחברתה","אמר רב נחמן בר יצחק מאן דתני משירין לא משתבש ומאן דתני משחירין לא משתבש ומאן דתני מנשירין לא משתבש","מאן דתני משירין לא משתבש דתנן רבי ישמעאל אומר נזיר לא יחוף ראשו באדמה מפני שמשיר את השער ומאן דתני משחירין לא משתבש דתנן השחור והזוג של ספרים אע\"פ שנחלקו טמאין","ומאן דתני מנשירין לא משתבש דתנן מי שנשרו כליו במים מהלך בהם ואינו חושש אי נמי מהא דתנן איזהו לקט הנושר בשעת קצירה:","תנן משילין פירות דרך ארובה ביו\"ט עד כמה א\"ר זירא א\"ר אסי ואמרי לה אמר רבי אסי א\"ר יוחנן כאותה ששנינו מפנין ארבע וחמש קופות של תבן ושל תבואה מפני האורחים ומפני בטול בית המדרש","ודלמא שאני התם דאיכא בטול בית המדרש אבל הכא דליכא בטול בית המדרש לא א\"נ התם היינו טעמא דארבע וחמש קופות שרי משום שבת דחמירא ולא אתי לזלזולי ביה אבל יו\"ט דקיל ואתי לזלזולי ביה כלל כלל לא","אי נמי לאידך גיסא התם היינו טעמא דליכא הפסד ממון אבל הכא דאיכא הפסד ממון אפילו טובא נמי"],[[0,"חצר","אצטריך לאשמועינן לאפוקי מהאי תנא דקתני ר' יעקב מחייב דלית הלכתא כוותיה אלא כרבי יוסי ברבי יהודה דפוטר:"],[2,"ה\"ג מקח כדתנן הלוקח תאנים כו'","אצטריך לאשמועינן דהלכתא כי הך ולא כאידך מתני' דפליגי עליה לקמיה:"],[2,"הלוקח תאנים מעם הארץ במקום שרוב בני אדם דורסין","שרוב בני המקום עושין תאניהם קציעות ודורסים אותם בעגולים הוו להו סתם תאנים דבר שלא נגמרה מלאכתו:"],[2,"אוכל מהן עראי","דאין מקח קובע בדבר שלא נגמרה מלאכתו וכולהו כשלא ראו פני הבית קא מיירו:"],[2,"ומעשרן דמאי","כשבא לעשרן מעשרן דמאי כדין כל הלוקחים מעם הארץ שאין צריך להפריש תרומה דלא חשידי עלה ולא אמרינן הני ודאי לא מעשרי דקודם גמר מלאכה לא עשרינהו עם הארץ דקסבר האי תנא יש שמעשרין קודם גמר מלאכה ומדה הנוהגת היא ותלינן ביה לקולא:"],[3,"רוב עמי הארץ מעשרין הן","מדאזלינן לקולא דקאמר מעשרן דמאי וחומרא בעלמא היא דאחמור לאפרושי מספיקא שאר מעשרות שנחשדו עליהן:"],[4,"ולאפוקי מהא דתנן","אדרבי יוחנן קאי רבי יוחנן דאמר לעיל מקח אינו קובע בדבר שלא נגמר מלאכתו אתא לאשמועינן דהלכתא כי הא דאמרי' לעיל ולאפוקי מהך:"],[4,"המחליף","היינו מקח:"],[4,"לקצות","דהיינו לא נגמר:"],[4,"חייב","דמקח קבע אפילו בשלא נגמר:"],[4,"לאכול חייב","זה שדעתו לאכול חייב דלדידיה גמר מלאכה הוא:"],[6,"מתני' משילין פירות דרך ארובה","מי שיש לו חטין ושעורין שטוחין על גגו להתיבש וראה גשמים ממשמשין ובאין התירו לו לטרוח ולהשליך דרך ארובה שבגג והן נופלין לארץ דליכא טרחא יתירא ודוקא ארובה דכל ארובה מלמעלה למטה היא בתקרת הגג אבל חלון כגון גג שמוקף מחיצה וחלון בכותל וצריך להגביהו עד החלון ולהשליכו לא טרחינן כדלקמן:"],[6,"ומכסין את הפירות","ולא אמרינן טורח שלא לצורך יום טוב הוא דשרו ליה רבנן משום הפסד ממון:"],[6,"דלף","גשמים הנוטפים מן הגג:"],[6,"וכן כדי יין","נמי מכסינן מפני הדלף:"],[6,"תחת הדלף","לקבלו בתוכו מפני טנוף הבית:"],[8,"גמ' לא משתבש","דכולהו לשון השפלה נינהו:"],[8,"כי ישל זיתך","אילן זית יפיל את פירותיו ולא יגיעו לבשול:"],[8,"הכסול והשחול","מומין בבכור משום שרוע שאחד מאבריו גדול מחבירו:"],[8,"שנשמטה ירכו","אלמא לשון השפלה הוא:"],[8,"שאחד מירכותיו גבוהה","מקום חבורה בכסלים והוא בוקא דאטמא גבוה למעלה מן הכסלים וקרוב לגג האליה יותר מחבירו:"],[10,"אדמה","גלייש\"א:"],[10,"מאן דתני","כלומר אי הוה תנא דתני הכי לא משתבש:"],[10,"השחור","תער על שם שמשחיר את השער אלמא לשון השפלה הוא:"],[10,"והזוג של מספרים","יש להן שני סכינין להכי מקרו זוג ויש להן חליות ופורקין אותן זה מזה:"],[10,"אע\"פ שנחלקו","מקבלין טומאה שראוין למלאכה כל אחד לעצמו:"],[11,"שנשרו","נפלו במים:"],[11,"מהלך בהן","והן מתנגבין והולכין ואינו חושש שיחשדוהו שכבסן:"],[12,"עד כמה","יהא בהן דלא אמרינן טרחא יתרא הוא:"],[12,"מפני האורחים","שזימן לאכול ואין מקום להסב:"],[12,"בטול בית המדרש","שאין לתלמידים מקום לישב:"],[13,"ודלמא","התם הוא דשרינן כולי האי דאיכא בטול בית המדרש והוא הדין לכבוד אורחים אבל משום הפסד ממון לא שרו רבנן כולי האי:"],[14,"אי נמי לאידך גיסא","יש לתת טעם לצד אחר שיתירו כאן יותר משם:"]],[[10,"","השחור והזוג של מספרים. פ\"ה שחור תער שאין בית יד שלו מחובר ופורקין אותו לפעמים ואף על פי שנחלקו מקבלין טומאה שראוין למלאכתן כל אחד לעצמו וקשה דבית יד למאי חזי לעצמו ונראה דשחור נמי הוי מספרים אלא שהן קטנים וזוג של מספרים הוא גדול מן השחור ושני סכינים לזה ולזה והקטנים נקראים שחור על שם שמשחירין את השער אלמא לשון השפלה הוא:"],[11,"","מי שנשרו כליו בדרך. כאן משמע שהוא לשון נשירה מלשון פירות הנושרין ולא כמו שפירש רש\"י בפרק חבית (שבת דף קמו: ושם) לשון שרייה ומיהו לכך קאמר הכא [א\"נ] כהא דתנן איזהו לקט זה הנושר בשעת קצירה דהאי איכא לדחויי ולפרושי לשון שרייה כדפירש הקונטרס:"]]],[["התם תנן אבל לא את האוצר ואמר שמואל מאי אבל לא את האוצר אבל לא יגמור את האוצר כולו דלמא אתי לאשויי גומות הכא מאי","התם הוא בשבת דאסור משום דחמיר אבל יום טוב דקיל שפיר דמי או דלמא התם דאיכא בטול בית המדרש אמרת לא הכא דליכא בטול בית המדרש לא כל שכן","והכא תנן משילין פירות דרך ארובה ביו'ט ואמר רב נחמן לא שנו אלא באותו הגג אבל מגג לגג לא ותניא נמי הכי אין מטלטלין מגג לגג אפי' כשגגותיהן שוין","התם מאי (כל שכן שבת דחמירא או דלמא) הכא הוא דאסור משום יום טוב דקיל ואתי לזלזולי ביה אבל שבת דחמירא ולא אתי לזלזולי בה שפיר דמי","או דלמא מה הכא דאיכא הפסד פירות אמרת לא התם דליכא הפסד פירות לא כל שכן","הכא (תנן) לא ישלשלם בחבל בחלונות ולא יורידם דרך סולמות התם מאי הכא ביום טוב הוא דאסור דליכא בטול בית המדרש אבל שבת דאיכא בטול בית המדרש שפיר דמי","או דלמא הכא דאיכא הפסד פירות אמרת לא התם דליכא הפסד פירות לא כל שכן תיקו:","ומכסין את הפירות: אמר עולא ואפילו אוירא דלבני ר' יצחק אמר פירות הראוין ואזדא ר' יצחק לטעמיה דאמר ר' יצחק אין כלי ניטל אלא לדבר הניטל בשבת","תנן מכסין את הפירות בכלים פירות אין אוירא דלבני לא הוא הדין דאפי' אוירא דלבני ואיידי דתנא רישא משילין פירות תנא סיפא נמי מכסין את הפירות","תנן וכן כדי יין וכן כדי שמן הכא במאי עסקינן בטיבלא","הכי נמי מסתברא דאי סלקא דעתך כדי יין וכדי שמן דהתירא הא תנא ליה רישא פירות","כדי יין וכדי שמן אצטריכא ליה סלקא דעתך אמינא להפסד מרובה חששו להפסד מועט לא חששו קמ\"ל","תנן נותנין כלי תחת הדלף בשבת בדלף הראוי","תא שמע פורסין מחצלת על גבי לבנים בשבת דאייתור מבנינא דחזי למזגא עלייהו","תא שמע פורסין מחצלת על גבי אבנים בשבת באבנים מקורזלות דחזיין לבית הכסא","תא שמע פורסין מחצלת על גבי כורת דבורים בשבת בחמה מפני החמה ובגשמים מפני הגשמים ובלבד שלא יתכוין לצוד התם נמי דאיכא דבש","אמר ליה רב עוקבא ממישן לרב אשי התינח בימות החמה דאיכא דבש בימות הגשמים מאי איכא למימר לא נצרכא אלא לאותן שתי חלות אותן שתי חלות מוקצות הן הכא במאי עסקינן שחשב עליהם","אבל לא חשב עליהם מאי אסור אדתני ובלבד שלא יתכוין לצוד לפלוג ולתני בדידה במה דברים אמורים שחשב עליהן אבל לא חשב עליהם אסור","הכי קאמר אע\"פ שחשב עליהן ובלבד שלא יתכוין לצוד","במאי אוקימתא כרבי יהודה דאית ליה מוקצה אימא סיפא ובלבד שלא יתכוין לצוד אתאן לרבי שמעון דאמר דבר שאין מתכוין מותר","ותסברא דרבי שמעון והא אביי ורבא דאמרי תרוייהו מודה רבי שמעון בפסיק רישיה ולא ימות","לעולם כולה רבי יהודה היא והכא במאי עסקינן דאית ביה כוי ולא תימא לרבי יהודה ובלבד שלא יתכוין לצוד"],[[0,"התם תנן כו'","כלומר ועוד שאלה אחרת:"],[0,"שלא יגמור את האוצר","אם לא היו שם אלא ארבע או חמש קופות שהתירו לו במקום שיש יותר כאן לא התירו לפנותן כולן ולגלות את הרצפה דלמא הוי בה גומא ומשוה לה:"],[2,"והכא תנן","כלומר ועוד יש לשאול:"],[2,"באותו הגג","שהארובה בגג שהפירות בו:"],[2,"אין מטלטלין","בפירות שבגג שבא להשילן מפני הגשמים קא מיירי ואפילו בגגותיהן של שני בתים ששוין שאין זה גבוה מזה שיהא שם טורח עלייה וירידה:"],[5,"בחלונות","כגון אם מוקף מחיצה ואין בו ארובה אבל יש חלון במחיצה לחצר או לבית לא ישלשלם בשקין דרך החלון בחבל מפני שיש טורח להעלות מן הגג לחלון ומשם לארץ:"],[5,"סולמות","כל מדרגה קרי סולם ואף הכבשים שלנו:"],[7,"ואפילו אוירא דלבני","לבנים הסדורים ומוקצים לבנין וגשמים נוטפים ומתירא שלא ימוחו מותר לטלטל כלים לצרכן ולכסותן ולא אמרינן הואיל והן עצמן אין נטלין אף הכלי לא ינטל לצרכן:"],[7,"ור' יצחק אמר","דוקא פירות הראוין לטלטול הוא דשרו רבנן לטלטל כלים לצרכן אבל מידי דלאו בר טלטול אין כלי ניטל לצרכו:"],[7,"אלא לדבר הניטל","לצורך דבר הניטל:"],[8,"ואיידי דתנא רישא","פירות הראוין דעל כרחך בדחזי לטלטול אצטריך למנקט שהרי מטלטל הן עצמן ומשילן נקט נמי לענין כסוי פירות הראוין ומיהו סיפא לאו דוקא והוא הדין ללבני:"],[9,"תנן וכן כדי יין","מכדי בהני לא איירי לעיל וכיון דתנן הכא ובא לאשמועינן דברים אחרים לבד פירות היה לו להשמיענו לבנים וכ\"ש אלו:"],[9,"הכי גרסינן הכא במאי עסקינן בדטיבלא","כלומר לא בא להשמיעך כי אם כיוצא בלבנים (וכדברך) דהנך כדי יין דקא מוסיף ותני בדטיבלא עסקינן שאסורים בטלטול דאשמועינן ברישא פירות הראוין דומיא דמשילין והדר נקט להנך לאשמועינן אף שאין ראוין:"],[11,"הפסד מועט","גשמים הנוטפין על יין הפסד מועט הוא עד שתחשך ויסלקם אבל הפירות מרקיבין:"],[12,"נותנין כלי תחת הדלף","הרי שהכלי ניטל לקבל בו מוקצה כי האי דלא חזי למידי:"],[12,"בדלף הראוי","שהן צלולין וראוין לבהמה:"],[14,"על גבי אבנים","שנגובין לבנין וכשהן מתלחלחין צריך לחזור ולנגבן שאינן מקבלות את הטיט יפה והבנין שוהה ליבש:"],[14,"מקורזלות","אגוד\"ש:"],[14,"לבית הכסא","לקנח:"],[16,"שתי חלות","של צפיחית מניחין בכוורת כשרודין אותה ומהן פרנסה לדבורים כל ימות הגשמים אותן שתי חלות מותר לכסות כל דבש הכוורת עשוי עליות עליות של חלות:"],[16,"מוקצות נינהו","לדבורים:"],[17,"דחשב עלייהו","לאדם:"],[17,"אדתני ובלבד שלא יתכוין לצוד","משמע דלא ימצא לחלק את דבריו ולאסור עד שדלג מאיסור טלטול לאיסור צידה:"],[17,"לפלוג ולתני בדידה","באיסור טלטול גופיה יכול לחלק את דבריו ולמצוא צד איסור לדבר בדלא חשב עלייהו לא יטלטל המחצלת לצרכם:"],[18,"הכי קאמר אף על פי שחשב עליהם כו'","אף בשחשב בא ללמדך שיש צד איסור במתכוין לצוד ואף על גב דעיקר להצלה מפני הגשמים מכוון:"],[19,"במאי אוקימתא כרבי יהודה","כלומר מדהוה לך לתרוצי ארישא הא מני ר' שמעון דלית ליה מוקצה ומהדרת אשנויי דחיקי למימר משום שתי החלות כרבי יהודה בעית לאוקמא משום דרבי יצחק דמותבינן ליה הנך תיובתא אית ליה מוקצה כר' יהודה:"],[19,"ובלבד שלא יתכוין לצוד","ואף על פי שהוא צדן:"],[21,"דאית ביה כוי","חלונות יש בדפנותיה ואף על פי שמכסה את פיה אינן נצודין אם לא יכסה גם את החלונות ולא תימא ובלבד שלא יתכוין אלא בלבד שלא יעשנה מצודה שלא יסתום החלונות:"],[21,"פשיטא","כיון דאית ליה לרבי יהודה דבר שאין מתכוין אסור למה ליה למיתני ובלבד שלא יעשה מצודה דהא צידה אב מלאכה היא:"]],[[9,"","בדטיבלא. וא\"ת והא אמרי' לעיל בסוף המביא (ביצה דף לד:) דטבל מוכן הוא שאם עבר ותקנו מתוקן ובפרק כירה (שבת מג.) נמי לא חשבי ליה מבטל כלי מהיכנו כיון דחזו א\"כ אכתי תקשי לן דטבל אין אוירא דלבני לא וי\"ל דעולא יאמר לך דמ\"מ חשיב ליה כדבר שאינו ניטל כיון דבשבת מיהא לא חזי כל כמה דלא תקנו דאסור לפנותו בשבת כדתנן בפרק מפנין (שבת קכו:) אבל לא את הטבל:"],[19,"","במאי אוקימתא. פרש\"י דלא אשכחנא דמוקי לה כרבי יהודה בהדיא אלא מדדחיק נפשיה כי פריך והא מוקצות נינהו ולא קאמר רבי שמעון היא אלמא משמע ליה דאתיא כרבי יהודה:"]]],[["אלא אימא ובלבד שלא יעשנה מצודה פשיטא מהו דתימא במינו נצוד אסור שלא במינו נצוד מותר קמ\"ל","רב אשי אמר מי קתני בימות החמה ובימות הגשמים בחמה מפני החמה ובגשמים מפני הגשמים קתני ביומי ניסן וביומי תשרי דאיכא חמה ואיכא גשמים ואיכא דבש:","ונותנין כלי תחת הדלף בשבת: תנא אם נתמלא הכלי שופך ושונה ואינו נמנע","בי רחיא דאביי דלוף אתא לקמיה דרבה אמר ליה זיל עייליה לפוריך להתם דלהוי כגרף של רעי ואפקיה","יתיב אביי וקא קשיא ליה וכי עושין גרף של רעי לכתחלה אדהכי נפל בי רחיא דאביי אמר תיתי לי דעברי אדמר","אמר שמואל גרף של רעי ועביט של מימי רגלים מותר להוציאן לאשפה וכשהוא מחזירו נותן בו מים ומחזירו","סבור מינה גרף של רעי אגב מנא אין בפני עצמו לא ת\"ש דההוא עכברתא דאשתכח בי אספרמקי דרב אשי אמר להו רב אשי נקטה בצוציתה ואפקוה:","\u0001מתני׳\u0002 כל שחייבין עליו משום שבות משום רשות משום מצוה בשבת חייבין עליו ביו\"ט","ואלו הן משום שבות לא עולין באילן ולא רוכבין על גבי בהמה ולא שטין על פני המים ולא מטפחין ולא מספקין ולא מרקדין","ואלו הן משום רשות לא דנין ולא מקדשין ולא חולצין ולא מיבמין","ואלו הן משום מצוה לא מקדישין ולא מעריכין ולא מחרימין ולא מגביהין תרומה ומעשר","כל אלו ביו\"ט אמרו קל וחומר בשבת אין בין יו\"ט לשבת אלא אוכל נפש בלבד:","\u0001גמ׳\u0002 לא עולין באילן גזרה שמא יתלוש","ולא רוכבין על גבי בהמה גזרה שמא יצא חוץ לתחום שמע מינה תחומין דאורייתא אלא גזרה שמא יחתוך זמורה","ולא שטין על פני המים גזרה שמא יעשה חבית של שייטין:","ולא מטפחין ולא מספקין ולא מרקדין: גזרה שמא יתקן כלי שיר:","ואלו הן משום רשות לא דנין: והא מצוה קעביד לא צריכא דאיכא דעדיף מיניה:","ולא מקדשין: והא מצוה קעביד לא צריכא"],[[0,"מהו דתימא דבר שבמינו נצוד","שדרך לצוד את בני מינו כגון חיה ועוף אסור אבל האי דאין במינו נצוד שרי קמ\"ל:"],[1,"רב אשי אמר","לעולם כדשנינן מעיקרא דאיכא דבש למאכל אדם ודקשיא לך בימות הגשמים מי איכא דבש לא קשיא דמי קתני ימות החמה וימות הגשמים:"],[2,"שופך","לחוץ:"],[2,"ושונה","יחזירנו למקומו תחת הדלף:"],[2,"ואינו נמנע","מלשנות כל היום אם צריך לכך:"],[3,"בי רחיא דאביי דלוף","הדלף היה נופל על הרחים שלו והיו עשוין בטיט ונמוחים מפני הגשמים ולא היה מספיק לכלים הצריכים לתת תחת הדלף:"],[3,"זיל עייליה לפוריך להתם","לבית שהוא שם דלהוי כגרף של רעי שיהו מאוסים הרחים לך להיות לפני מטתך ואתה מותר לטלטלן ולהוציאן לחוץ כדאמר לקמן דגרף של רעי מותר להוציאו לאשפה:"],[4,"וכי עושין גרף של רעי לכתחלה","וכי מותר לגרום שיהא הדבר מאוס לו כדי שיוציאנו:"],[4,"תיתי לי דעברי אדמר","תבואני זאת בשכרי שעברתי על דברי רבי גרף ועביט כלי חרס הן אלא של רעי קרוי גרף ושל מימי רגלים קרוי עביט:"],[5,"נותן בו מים ומחזירו","דמוקצין מחמת מאוס הן ואי לאו אגב מיא לא מצי לטלטלינהו ולהוציאו הוא דשרו ליה משום כבודו:"],[6,"סבור מינה","מדשמואל היו סבורים התלמידים דדוקא גרף נקט דאגב מנא שרי לטלטל את הרעי אבל בפני עצמו ליטול את הרעי או דבר מאוס ממש בידו ויוציאנו לא שרו ליה:"],[6,"באספרמקי","בשמים:"],[6,"בצוציתה","בזנבה:"],[7,"מתני' כל שחייב עליו","מדברי סופרים שלא לעשותו בשבת משום שבות או משום רשות שיש בו קצת מצוה אבל לא מצוה גדולה וקרוב הוא להיות דבר הרשות ויש בו איסור מדברי סופרים:"],[7,"או משום מצוה","או שיש בו מצוה ממש ואסרוהו חכמים לעשות בשבת:"],[7,"חייבין עליו","שלא לעשותו ביו\"ט:"],[8,"ואלו הן","דברים שאסורין משום שבות שהטילו עליו חכמים לשבות מהן ואין בעשייתן שום מצוה:"],[8,"לא עולין באילן כו'","כולהו מפרש בגמרא אמאי גזור בהו רבנן:"],[8,"אין מטפחין","ביד:"],[8,"ואין מספקין","על ירך:"],[8,"ואין מרקדין","ברגל וכולן לשמחה ולשיר ובגמרא מפרש גזרה שמא יתקן כנגדן כלי שיר דקא עביד מנא:"],[9,"ואלו הן משום רשות","כלומר שהיה לנו להתירן משום שהן קרובין למצוה ואסרום חכמים האי דקרו ליה רשות משום הנך דבעי למתני בסיפא דהוו מצוה גמורה ולגביהן קרי להנך מציעי רשות ולהנך קמאי קרי שבות דאיסור שבות גמור יש בהן לפי שאין בהן צד לסלק גזירות חכמים מעליהן שאין בהן לחלוחית מצוה:"],[9,"לא דנין","דין:"],[9,"ולא מקדשין","אשה ובגמרא מפרש אמאי קרי ליה רשות (ומאי טעמא גזור עלייהו):"],[10,"ולא מקדישין","הקדשות:"],[10,"מעריכין","ערכך עלי ונותן כפי שנים כמו שכתוב בפרשת ערכין (ויקרא כז):"],[10,"ולא מחרימין","הרי בהמה זו חרם וסתם חרמים לבדק הבית:"],[12,"גמ' שמא יעלה ויתלוש","דהוי אסורא מדאורייתא דהיינו קוצר שתולש מן המחובר:"],[13,"שמא יצא חוץ לתחום","מתוך שאינו מהלך ברגליו אינו רואה סימני התחומין:"],[13,"שמע מינה תחומין מדאורייתא","מדגזור רכיבה אטו תחומין דאי מדרבנן לא הוו אסרי מלתא אחריתא משום דידיה:"],[13,"שמא יחתוך זמורה","להכותה והוי קוצר מן המחובר:"],[14,"חבית של שייטין","כלי של גומא שאורגין אותו ועושין כמין חבית ארוכה ולמדין בו לשוט:"],[16,"הא מצוה קא עביד","ואמאי קרי ליה רשות:"],[17,"ולא מקדשין הא מצוה קא עביד","שנושא אשה לפרות ולרבות ואמאי קא קרי ליה רשות:"]],[[0,"","אלא אימא ובלבד שלא יעשנה מצודה. פ\"ה ובלבד שלא יכסה בו כל החלונות דלר' יהודה אסור ולר' שמעון מותר וגם מעיקרא כי בעי לאוקומי כר' שמעון משמע ליה דבכל ענין מיירי אפילו לעשות כעין מצודה לסתום כל החלונות ותימה דהא מודה ר\"ש בפסיק רישיה ולא ימות והכא ודאי הן נצודות ופירש הר\"ר משה מאייבר\"א דלר\"ש נמי מיירי שיש חור קטן בכוורת אך אינו נראה וא\"כ לא הוי פסיק רישיה ולא ימות ולר\"ש מותר ורבי יהודה דאסר אפילו דבר שאינו מתכוין בעי חור גדול שיהא נראה לדבורים לצאת מן הכוורת:"],[2,"","שופך ושונה. למה דס\"ד דאיירי לעיל בדלף שאינו ראוי לו קשה היכי מטלטל ליה הא הוה ליה ככלכלה והאבן בתוכה דאמר בסוף כירה (שבת דף מז. ושם) דלית בה . פירי וי\"ל דשרי משום דהוי כגרף של רעי וכן משמע מדמייתי ליה הכא:"],[4,"","תיתי לי דעברי אדמר. אע\"ג דאמרינן לעיל פ' יו\"ט (ביצה דף כא: ושם) דאין עושין גרף של רעי לכתחלה ס\"ל לרבה דהכא שרי משום פסידא דבי רחיא או משום דלא מקרו לכתחלה כל כך הכא כיון שהיו הגשמים כבר מזלפין בבית אין כל כך לכתחלה כמו מזמנין נכרי:"],[14,"","שמא יעשה חבית של שייטין. פ\"ה שלוקחין קנים ועושה כעין חבית ושט בהן וקשה דהא תנן ואלו טהורין בכלי חרס טבלא שאין לה לבזבזין וחבית של שייטין אלמא דחרס הוא לכן נ\"ל שהוא כלי חרס שאין לו פתח ומתוך כך אינו יכול להשתקע במים לפי שאין המים יכולין ליכנס לתוכו ולכך צף על פני המים:"],[16,"","והא מצוה קא עביד. פ\"ה וה\"ל למחשבינהו בהדי אינך דסיפא ממצוה ומשני לא צריכא דאיכא דעדיף מיניה ולכך אינו מצוה כל כך דומיא דהני דסיפא ולפי זה יכול להיות דגם בדליכא דעדיף מיניה אסור וכן פירש נמי גבי לא מקדשין הא מצוה קא עביד כו' ומשני דאית ליה אשה ובנים משמע אפילו אין לו אשה ובנים מ\"מ אסור וקשה דאמר פרק דיני ממונות (סנהדרין דף לה.) לפיכך אין דנין לא בע\"ש ולא בערב יו\"ט דהיכי לעביד לדייניה במעלי שבתא ולקטליה בשבת אין רציחה דוחה שבת ולא משני משום דאין דנין משמע התם דבסנהדרין דבסתמא ליכא עדיף מנייהו שפיר דנין ויש ליישב דניחא ליה להש\"ס למימר טעמא לאסור מן התורה ולא לאסור אלא מדרבנן ור\"ת פי' דהא מצוה קא עביד ואמאי גזרו כו' ומשני לא צריכא דאית ליה אשה ובנים אבל אם אין לו אשה ובנים מותר לקדש דמצוה קא עביד וקשה דבפ\"ק דיומא בירושלמי גבי כהן גדול מתקנין לו אשה אחרת פריך והרי קונין לו קנין בשבת ומשני אין שבות במקדש ולשני דשרי כיון דמצוה קא עביד דהא כיון שמתה אשתו מצוה לו לישא אשה אחרת ועוד קא עביד מצוה דכתיב וכפר בעדו ובעד ביתו (ויקרא ט״ז:ו׳) אלא ודאי י\"ל כפירוש הקונטרס ולא קשיא מההיא דסנהדרין דהא קאמר הכא טעמא שמא יכתוב וכיון דישבו כבר בדין מערב יו\"ט וכתבו דברי המזכין ודברי המחייבים מבעוד יום כדקאמר התם אם כן לא שייך למגזר ועוד י\"ל כפירוש ר\"ת ולא קשיא מההיא דכהן גדול דשמא חד מתרי טעמי נקט והדר מסיק התם בירושלמי דיומא אמר רבי מונא הדא אמר' הדין דכונסין ארמלין צריך לכונסן מבעוד יום שלא יהא כקונה קנין בשבת ואיתא נמי בריש כתובות בירושלמי ומפרש התם טעמא דעד שלא. קנה אינו זכאי במציאתה ולא במעשה ידיה ולא בהפרת נדריה משכנסה זכאי בכולם ונמצא כקונה קנין בשבת וההוא נמי איכא לאוקמי בשיש לו אשה ובנים ומהאי טעמא דאין מקדשין לפי שנראה כקונה קנין אסור כמו כן לתת גט בשבת:"]]],[["דאית ליה אשה ובנים:","לא חולצין ולא מיבמין: והא מצוה קא עביד לא צריכא דאיכא גדול ומצוה בגדול ליבם","וכלהו טעמא מאיגזרה שמא יכתוב:","ואלו הן משום מצוה לא מקדישין ולא מעריכין ולא מחרימין: גזרה משום מקח וממכר:","ולא מגביהין תרומות ומעשרות: פשיטא תני רב יוסף לא נצרכא אלא ליתנה לכהן בו ביום","וה\"מ פירי דטבילי מאתמול אבל פירי דטבילי האידנא כגון עיסה לאפרושי מינה חלה מפרשינן ויהבינן לכהן","והני משום רשות איכא משום שבות ליכא והני משום מצוה איכא משום שבות ליכא","א\"ר יצחק לא מבעיא קאמר לא מבעיא שבות גרידתא דאסור אלא אפי' שבות דרשות נמי אסור ולא מבעיא שבות דרשות דאסור אלא אפי' שבות דמצוה נמי אסור:","כל אלו ביו\"ט אמרו: ורמינהו משילין דרך ארובה ביו\"ט אבל לא בשבת","אמר רב יוסף לא קשיא הא ר\"א הא ר' יהושע","דתניא אותו ואת בנו שנפלו לבור ר\"א אומר מעלה את הראשון על מנת לשוחטו ושוחטו והשני עושה לו פרנסה במקומו כדי שלא ימות","ר' יהושע אומר מעלה את הראשון ע\"מ לשוחטו ואינו שוחטו וחוזר ומערים ומעלה השני רצה זה שוחט רצה זה שוחט","א\"ל אביי ממאי דילמא עד כאן לא קאמר ר\"א התם אלא דאפשר בפרנסה אבל הכא דלא אפשר בפרנסה לא","א\"נ עד כאן לא קאמר ר' יהושע התם אלא דאפשר לאערומי אבל הכא דלא אפשר לאערומי לא","אלא אמר רב פפא לא קשיא הא בית שמאי הא בית הלל","דתנן ב\"ש אומרים אין מוציאין לא את הקטן ולא את הלולב ולא את ספר תורה לרה\"ר וב\"ה מתירין","דלמא לא היא עד כאן לא קא אמרי בית שמאי התם אלא אהוצאה אבל אטלטול לא אטו טלטול לאו צורך הוצאה הוא:","\u0001מתני׳\u0002 הבהמה והכלים כרגלי הבעלים המוסר בהמתו לבנו או לרועה הרי אלו כרגלי הבעלים","כלים המיוחדין לאחד מן האחין שבבית הרי אלו כרגליו ושאין מיוחדין הרי אלו כמקום שהולכין","השואל כלי מחבירו מעיו\"ט כרגלי השואל ביו\"ט כרגלי המשאיל וכן האשה ששאלה מחברתה תבלין ומים ומלח לעיסתה הרי אלו כרגלי שתיהן ר' יהודה פוטר במים מפני שאין בהן ממש:","\u0001גמ׳\u0002 מתניתין"],[[0,"דאית ליה אשה ובנים","שני זכרים לב\"ש או זכר ונקבה לב\"ה ותו לא מיפקד כולי האי כדאמרינן ביבמות (דף סא:) ומיהא קצת מצוה איכא כדאמר בבקר זרע את זרעך ולערב אל תנח ידך (קהלת י״א:ו׳):"],[1,"מצוה בגדול","האחים ליבם ונפקא לן מוהיה הבכור (דברים כה):"],[2,"שמא יכתוב","פסק דין לדינין ושטר אירוסין לקדושין ושטר חליצה לחולצת וכתובה ליבמה:"],[3,"משום מקח וממכר","דלמקח וממכר דמו שמוציא מרשותו לרשות הקדש ומקח וממכר אסור מן המקרא דכתיב ממצוא חפצך ודבר דבר (ישעיהו נח) אי נמי מקח וממכר אתי לידי כתיבה שטרי מכירה וא\"ת הויא לה גזרה לגזרה כולה חדא גזרה היא:"],[4,"תני רב יוסף אפי' ליתנם לכהן בו ביום","דאיכא למימר לאו מוכחא מלתא היא דלתקוני טבלא מכוין דאין ידוע שיהא הוא צריך לשיריים ורואים שמוליך תרומה לכהן ומחזי דכולה מלתא משום שמחת יו\"ט דכהן שצריך לה הוא אפ\"ה אסור:"],[6,"והני משום רשות איכא משום שבות ליכא","אאמצעיתא קאי דקאמר אלו הן משום רשות וכי אין בהן משום שבות והלא אסרום כדאמרינן כל שחייבין עליו אלמא כלהו לאסורא והני בתראי משום מצוה איכא בעשייתו ומשום שבות ליכא לאסרה בשבת בתמיה והלא אסרום והיכי פלגינהו תנא דמתני' דבקמאי אדכר שבות ובאמצעי ובתראי לא אדכר שבות:"],[7,"ה\"ק לא מבעיא כו'","כלומר כולם משום שבות יש בהן והראשונים איסור יש בהן ואין בהן לחלוח מצוה והאמצעיים יש בהן שבות ואע\"פ שיש בהן קצת מצוה והאחרונים מצוה גמורה הן ואעפ\"כ גזרו עליהן שבות ולא זו אף זו קתני לא תימא קמאי הוא דאסירי דה\"ל שבות גרידתא כלומר שעבר על השבות דאין עם עבירה זו שמץ מצוה אלא אפי' מצעי דה\"ל שבות דאיכא רשות קרבות מצוה גבה נמי אסור:"],[8,"משילין פירות כו'","אלמא גזרו שבות על שבת שלא גזרו ביו\"ט:"],[9,"הא ר' אליעזר","סיפא דקתני אין בין יו\"ט לשבת דכל שבות דגזרו על שבת גזרו על יו\"ט ואפי' בהפסד ממון ר\"א היא שלא התיר להעלות אותו ואת בנו מפני הפסד ממון ורישא דקתני משילין ביו\"ט מפני הפסד ממון ר' יהושע היא:"],[10,"אותו ואת בנו","שאינן מותרין לשחוט שניהן היום:"],[13,"דאפשר לאערומי","דלא מוכחא מילתא דלהצלת ממונו מכוין דהרואה אומר הראשון שהעלה כחוש הוא והשני יפה הימנו:"],[13,"אבל הכא לא אפשר לאערומי","דהכל יודעין שלא יניחם ואינו עושה אלא להציל ומזלזלין באיסור יו\"ט:"],[15,"אין מוציאין את הקטן וכו'","דלא הותרה הוצאה שלא לצורך וגבי טלטול שלא לצורך נמי גזרינן ואפילו גבי הפסד ממון ולב\"ה דאמרי הוצאה שלא לצורך מותרת מה\"ת בטלטול נמי לא גזור רבנן:"],[16,"אטו טלטול לאו צורך הוצאה הוא","תחילת הוצאה ע\"י טלטול היא וכל מה שגזרו אינו [אלא] משום הוצאה והאי דלא גזרו על טלטול כלים ואוכלים מפני שלא יוכלו לעמוד בהן לבטל עונג שבת ושמחת יו\"ט:"],[17,"מתני' הבהמה והכלים כרגלי הבעלים","אין אדם יכול להוליכה ביו\"ט אלא במקום שבעליה יכולין לילך ואם לא ערב יש לה אלפים לכל רוח העיר ואם ערב לצפון גם היא תלך לצפון ולא לדרום:"],[18,"ושאינן מיוחדין","לאחד מהן אלא לכולן:"],[18,"הרי אלו כמקום שהולכין","למקום שכולן יכולין לילך מותר להוליך את הכלים אבל אם ערב אחד מהם לסוף אלפים לצפון והשאר לא ערבו הוא מעכב על ידם מלהוליכם לדרום אפילו פסיעה אחת מפני חלקו והן מעכבין על ידו מלהוליכם לצפון אלא אלפים שהן מותרין בהן:"],[19,"הרי הוא כרגלי השואל","שהרי קנה שביתתו אצלו בין השמשות דבין השמשות שהוא כניסת היום קונה שביתה:"],[19,"ביו\"ט","ואם שאלו ביו\"ט משחשכה:"],[19,"הרי הוא כרגלי המשאיל","לפי שקנה שביתה אצל בעליו:"],[19,"האשה ששאלה מחברתה תבלין","לקדרתה:"],[19,"ומים ומלח לעיסתה הרי אלו","הקדרה והעיסה:"],[19,"כרגלי שתיהן","אין מוליכות אותם אלא למקום ששתיהן יכולות לילך דכיון דביו\"ט שאלה קנו התבלין או המים והמלח שביתה אצל בעליהן:"],[19,"שאין בהן ממש","אין ניכרות לא בקדרה ולא בעיסה הלכך אין מעכבות הולכתן ובגמ' מוקי לה בתבשיל עבה שאין המים ניכרים בו ובמלח לא פליג דמוקמינן לה בגמ' במלח אסתרוקנית שהיא גסה וניכרת:"],[20,"גמ' מתני'","דקתני המוסר בהמתו לרועה ביו\"ט הרי אלו כרגלי הבעלים ולא כרגלי הרועה:"]],[[3,"","משום מקח וממכר. פרש\"י דלמקח וממכר דמו שמוציאן מרשותו לרשות הקדש ומקח וממכר אסור מן המקרא דכתיב ממצוא חפצך ודבר דבר אי נמי מקח וממכר אתי לידי כתיבת שטרי מכירה ואם תאמר הוי לה גזרה לגזרה כולה חדא גזרה:"],[8,"","ורמינהו משילין פירות דרך ארובה וכו'. ותימה דאמרינן במגילה (דף ז:) אין בין יו\"ט לשבת אלא אוכל נפש בלבד ואמאי לא פריך ליה ממשילין. וכו' וע\"ק אמאי לא פריך לאלתר מב\"ה דמתירין הוצאה ביו\"ט שלא לצורך ובשבת אסור וי\"ל דהתם לא פריך ממתני' משום שהיה יודע שהיה יכול לדחות דהא דקאמר התם אין בין יו\"ט לשבת כו' ה\"מ דברים שהן דאורייתא אבל מילי דרבנן איכא טובא בינייהו והכא מיירי בשבות דרבנן ולכך לא מייתי מהוצאה דאיסורא דאורייתא ומ\"מ קאמר שפיר בסמוך הא ב\"ש דהכי מדמה דכיון דב\"ש מחמירין גבי הוצאה שלא לצורך כך הם מחמירים גבי טלטול דרבנן כדמסיק במסקנא דטלטול משום הוצאה הוא דאסור:"]]],[["דלא כר' דוסא דתניא ר' דוסא אומר ואמרי לה אבא שאול אומר הלוקח בהמה מחברו מערב יו\"ט אע\"פ שלא מסרה לו אלא ביו\"ט הרי היא כרגלי הלוקח והמוסר בהמה לרועה אע\"פ שלא מסרה לו אלא ביו\"ט הרי היא כרגלי הרועה","אפי' תימא ר' דוסא ולא קשיא כאן ברועה אחד כאן בשני רועים דיקא נמי דקתני לבנו או לרועה שמע מינה","אמר רבה בר בר חנה א\"ר יוחנן הלכה כר' דוסא ומי אמר ר' יוחנן הכי והאמר ר' יוחנן הלכה כסתם משנה ותנן הבהמה והכלים כרגלי הבעלים","ולאו אוקימנא כאן ברועה אחד כאן בשני רועים","ת\"ר שנים ששאלו חלוק אחד בשותפות זה לילך בו שחרית לבית המדרש וזה ליכנס בו ערבית לבית המשתה זה ערב עליו לצפון וזה ערב עליו לדרום זה שערב עליו לצפון מהלך לצפון כרגלי מי שערב עליו לדרום","וזה שערב עליו לדרום מהלך לדרום כרגלי מי שערב עליו לצפון","ואם מצעו את התחום הרי זה לא יזיזנה ממקומה","אתמר שנים שלקחו חבית ובהמה בשותפות רב אמר חבית מותרת ובהמה אסורה ושמואל אמר חבית נמי אסורה","מאי קסבר רב אי קא סבר יש ברירה אפי' בהמה תשתרי ואי קסבר אין ברירה אפילו חבית נמי אסורה","לעולם קסבר יש ברירה ושניא בהמה דקא ינקי תחומין מהדדי אמרי ליה רב כהנא ורב אסי לרב לאיסור מוקצה לא חששו לאיסור תחומין חששו שתיק רב","מאי הוי עלה ר' הושעיא אמר יש ברירה ור' יוחנן אמר אין ברירה","וסבר ר' הושעיא יש ברירה והתנן המת בבית ולו פתחים הרבה כולן טמאים נפתח אחד מהן הוא טמא וכולן טהורים חשב להוציאו באחד מהן או בחלון שיש בו ארבעה על ארבעה מצלת על הפתחים כולן","ב\"ש אומרים והוא שחשב עליו עד שלא ימות המת וב\"ה אומרים אף משימות המת","ואתמר עלה אמר ר' הושעיא לטהר את הפתחים מכאן ולהבא מכאן ולהבא אין למפרע לא","אפוך ר' הושעיא אמר אין ברירה ור' יוחנן אמר יש ברירה","ומי אית ליה לר' יוחנן ברירה והאמר רב אסי א\"ר יוחנן האחין שחלקו לקוחות הן ומחזירין זה לזה ביובל","וכי תימא כי לית ליה לרבי יוחנן ברירה בדאורייתא אבל בדרבנן אית ליה","ובדרבנן מי אית ליה והתני איו","ר' יהודה אומר אין אדם מתנה על שני דברים כאחד אלא אם בא חכם למזרח עירובו למזרח למערב עירובו למערב ואילו לכאן ולכאן לא"],[[0,"","דלא כר' דוסא:"],[1,"כאן ברועה אחד","שאין בעיר אלא רועה אחד כל בני העיר מעמידין בהמתם ברשותו ונקנית שביתתו הלכך בין מוכר בין לוקח דעתו שלא תקנה הבהמה שביתתו אצלו אלא בשביתת הרועה ומתניתין בשני רועים דלא ידעינן להי מנייהו הויא לה דעת בעלים הלכך הרי הן כרגלי הבעלים אם אינם אצל הרועה מבעוד יום:"],[1,"דיקא נמי","דמתני' בשני רועים:"],[4,"שנים ששאלו חלוק","מבעוד יום להיות ברשות שניהם:"],[4,"זה לילך בו שחרית","של יו\"ט לבית המדרש:"],[4,"וזה לילך בו ערבית","של יו\"ט לבית המשתה:"],[4,"עליו לצפון","על מנת אותו חלוק להוליכו לצפון:"],[4,"זה שערב עליו לצפון מהלך","מוליכו לצפון:"],[4,"כרגלי מי שערב לדרום","מה שרגליו של דרומי יכולין לילך לצפון מוליכו זה לצפון ולא יותר:"],[5,"וזה שערב עליו לדרום","מוליכו זה לדרום כרגלי מי שערב עליו לצפון כמו שרגליו של צפוני מותרות לילך לדרום מוליכו זה ולא יותר מפני חלקו של צפוני כגון אם נתנו שניהם עירובן בסוף אלף אמה זה לצפון להיות לו שלשת אלפים לצפון ואלף לדרום שהרי ממקום ערובו יש לו אלפים אמה לכל רוח וזה לדרום לסוף אלף להיות לו שלשת אלפים לדרום ואלף לצפון אין יכולין להוליכו אלא אלף אמה לכל צד ששניהם מותרים בהם:"],[6,"ואם מצעו עליו את התחום","תחום שבת מצפון לדרום ארבעת אלפים שנים לצפון ושנים לדרום ואם נתנו עירובן זה לסוף אלפים לצפון וזה לסוף אלפים לדרום ונמצא תחום שלם ממוצע להפסיק בין שני עירוביהן לא יזוז ממקומו לא לצפון ולא לדרום שהצפוני אין לו לדרום אפילו פסיעה וכן הדרומי לצפון שממקום עירובו יש לו אלפים לכל רוח שהרי לכך ערב שתסתלק שביתתו ממקום לינתו ותקנה במקום עירובו:"],[7,"שנים שלקחו","מעיו\"ט לחלקן ביו\"ט:"],[7,"חבית מותרת","להוליך כל אחד חלקו למקום שערב:"],[7,"ובהמה אסורה","להוליך אלא למקום ששניהם הולכים:"],[8,"אפילו חבית אסורה","דאין ברירה וי\"ל חלק שבא לזה היה ראוי לחברו ובין השמשות קנה חלק זה שביתת חברו:"],[9,"לעולם קסבר יש ברירה","הלכך חבית מותרת ושאני בהמה שהיתה בחייה בין השמשות וכל אבריה בחייה יונקים זה מזה ומשחשכה ינק כל אבר ואבר משל חברו ואין כאן לברור:"],[9,"ינקי תחומין","חלקי הבהמה שראוין לשני תחומין:"],[9,"לאיסור מוקצה לא חששו","אנן סהדי דכל חד מינייהו אקצי דעתיה מחלקו של חברו ואם היו רוצים לאכלה כאן אינה אסורה עליהם משום מוקצה לומר כל חלק ינק מחבירו ויש כאן מוקצה ולהוליכה איש לתחומו אתה אוסר עליהם מפני יניקה זו אם יש לחוש צריך לחוש אף משום מוקצה:"],[10,"יש ברירה","וחבית ובהמה מותרין:"],[10,"אין ברירה","ושניהם אסורין:"],[11,"המת בבית כו'","מפורש בפרק קמא:"],[13,"ואתמר עלה א\"ר אושעיא","הא דאמרי ב\"ה אף משימות המת חשב מועלת לטהר כלים הבאים בפתחים ממחשבה ואילך הוא דקאמרי אבל כלים דמעיקרא לא דאין ברירה לומר הוברר דקודם שימות נמי דעתיה להאי פתחא:"],[14,"אפוך","קמייתא:"],[15,"לקוחות הן","ולא אמרינן הוברר לכל אחד חלק ירושתו וירושה אינה חוזרת ביובל אלא שמא חלק הבא לזה לא היה שלו והרי החליפו חלקיהם והוו להו לקוחות ומחזירין זה לזה ביובל:"],[16,"בדאורייתא","לעמוד כנגד דבר תורה כגון יובל לא סמכינן אברירה:"],[16,"אבל מדרבנן","לעמוד כנגד איסור תחומין דרבנן סמכינן אברירה הלכך חבית ובהמה מותרים:"],[17,"ובדרבנן מי אית ליה והתני איו","שם חכם:"],[18,"אין אדם מתנה על שני דברים כאחד","בעירובין תנן מתנה אדם על עירובו ומניח שני עירובין ששמע שעתיד חכם לבא סמוך לעירו בתוך ד' אלפים לדרוש ברבים ואינו יודע אם למזרח אם למערב אומר אם בא חכם למזרח ערובי שבמזרח יקנה לי שביתה בא למערב ערובי שבמערב יקנה בא לכאן ולכאן אם יבאו שנים למקום שארצה אלך ואברור למחר יהא ערובי דבין השמשות קונה לאותו רוח למפרע ואי אפשר כן אלא ע\"י ברירה דכי בורר למחר אומרים הוברר דבין השמשות נמי דעתיה לגבי האי ובא ר' יהודה לחלוק ולומר אינו מתנה על שני חכמים לומר למחר אברור דכי בורר למחר מי יימר דערוב של אותו רוח קנה לו בין השמשות והוברר למפרע לא אמרינן:"],[18,"אלא אם בא חכם כו'","על חכם אחד ואינו יודע לאיזה רוח יבא אפשר להתנות:"]],[[7,"","ושמואל אמר אף חבית אסורה. דלית ליה ברירה ותימה דבפרק מי שאחזו (גיטין דף עה:) דאמר דאתקין שמואל בגיטא דשכיב מרע אם ימות יהא גט ואם לא ימות לא יהא גט ולכי מיית הוי גיטא אלמא אית ליה ברירה דה\"נ דייק בריש כל הגט (גיטין דף כה: ושם) וי\"ל דהיינו דוקא תולה בדעת אחרים אבל תולה בדעת עצמו כי הכא לית ליה ברירה:"],[9,"","לאיסור מוקצה לא חששו. אנן סהדי דכל אחד מנייהו אקצי דעתיה מחלקו של חברו ואם היו רוצין לאכלה כאן אינה אסורה משום מוקצה לומר כל חלק וחלק יונק משל חברו ויש כאן מוקצה ולהוליכה איש לתחומו אתה אוסר עליהן מפני יניקה זאת אם יש לחוש צריך לחוש אף משום מוקצה כפ\"ה וקשה מאי יניקת מוקצה יש כאן והלא חלק חברו מותר לו לאכול אם נתן לו חברו דאמר לעיל משלחין ביו\"ט בהמה חיה ועוף בין חיין בין שחוטין ומפרש רבינו שמואל לאיסור מוקצה שהבהמה גדלה ומוסיפה שמנונית ביום טוב ולא אסרת להו למיחש להכי אע\"ג דסבירא ליה כרבי יהודה במוקצה לאיסור תחומין שחלק כל אחד יונק ומתגדל משל חברו חששת לאסרה בכך:"]]],[["והוינן בה מ\"ש לכאן ולכאן דלא דאין ברירה מזרח ומערב נמי אין ברירה","וא\"ר יוחנן וכבר בא חכם אלמא לית ליה לר' יוחנן ברירה","אלא לעולם לא תיפוך וכי לית ליה לרבי אושעיא ברירה בדאורייתא אבל בדרבנן אית ליה","דרש מר זוטרא הלכה כרבי אושעיא","אמר שמואל שור של פטם הרי הוא כרגלי כל אדם שור של רועה הרי הוא כרגלי אותה העיר:","השואל כלי מחבירו מערב יו\"ט: פשיטא לא צריכא שלא מסרו לו אלא ביו\"ט מהו דתימא לאו ברשותיה אוקמיה קמ\"ל","מסייע ליה לר' יוחנן דא\"ר יוחנן השואל כלי מחבירו מערב יום טוב אף על פי שלא נתנו לו אלא ביו\"ט הרי הוא כרגלי השואל:","ביו\"ט כרגלי המשאיל: פשיטא לא צריכא דרגיל ושאיל מיניה מהו דתימא ברשותיה קא מוקים ליה קמ\"ל מימר אמר דלמא משכח איניש אחרינא ואזיל ושאיל מיניה:","וכן האשה ששאלה מחברתה: כי סליק רבי אבא אמר יהא רעוא דאימא מלתא דתתקבל כי סליק אשכחיה לר' יוחנן ורבי חנינא בר פפי ור' זירא ואמרי לה ר' אבהו ור' שמעון בן פזי ור' יצחק נפחא ויתבי וקאמרי אמאי ולבטיל מים ומלח לגבי עיסה אמר להו ר' אבא"],[[0,"והוינן בה כו'","דקא ס\"ד זימנין דחכם לא בא עד לאחר בין השמשות כגון שחשכה לו בתוך התחום שבאותו מקום בית המדרש או בתוך ד' אלפים והוא מכיר אילן או גדר לסוף אלפים למקום שחשכה לו ואמר שביתתי תחתיו דיכול להלך משחשכה ד' אלפים אמות כדאמר בעירובין (דף מט:) הלכך היכא דבשעת קניית עירוב לא אתי חכם לההוא אתרא והדר אתא מי יימר דקנה ההוא עירוב למפרע דלמא חכם בין השמשות לא היה דעתו לבא לכאן אי לא סמכינן אברירה לומר הוברר דלרוח זה היה חכם עתיד לבא וזה התנה דלמקום שיבא החכם יהא ערובו קונה למפרע:"],[1,"","וא\"ר יוחנן גרסינן:"],[1,"וכבר בא חכם","הא דאמר רבי יהודה אם בא חכם למזרח וכו' דעל חכם יכול להתנות בשכבר בא קודם בין השמשות עסקינן אך זה אינו יודע לאיזה רוח בא וקאמר לאותו רוח שבא לו יהא ערובי קונה דאין קנייתו על ידי ברירה אלא קנייה ודאית ולמחר גלוי מילתא בעלמא הוא דלרוח שישמע זה שהיה בו החכם קנה ערובו ומדאצטריך ר' יוחנן לאוקמה בשכבר בא חכם ש\"מ לית ליה ברירה ואפי' בתחומין דרבנן:"],[2,"אלא לעולם לא תיפוך","ורבי אושעיא הוא דאמר יש ברירה ודקשיא לך לטהר את הפתחים מכאן ולהבא:"],[2,"בדאורייתא","כגון טומאת מת לית ליה ברירה ודרך יציאתה הלכה למשה מסיני כדאמרי' בסוכה (דף ו.) דהלכות טומאה הכי גמירי להו:"],[2,"אבל בדרבנן","כגון תחומין אית ליה:"],[4,"שור של פטם","שמפטם שוורים למכור:"],[4,"הרי הוא כרגלי כל אדם","אפי' בן עיר אחרת שבא לכאן ע\"י עירוב מוליכו למקומו כיון דאורחיה לזבוניה מאתמול אוקמיה ברשותי דמאן דאתי למחר וזבין ליה:"],[4,"שור של רועה","אדם שמגדל בהמות שלו ופעמים שמוכר מהן לשכיניו ומכיריו:"],[4,"הרי הוא כרגלי אנשי אותה העיר","אלפים אמה לכל רוח ואפילו עירב רועה זה ד' אלפים אמה לרוח אחת אינו מעכב על אחד מבני אותה העיר שלקחו הימנו ביו\"ט מלהוליכו לרוח שכנגדה אלפים דמאתמול אוקמיה ברשות בני העיר לפי שרגילין ליקח הימנו אבל כרגלי בני עיר אחרת לא דאין לרועה שם סוחר בהמות כמו פטם שיכירוהו בני עיר אחרת ליקח הימנו:"],[5,"פשיטא","דכי שאלו מבעוד יום ברשותיה קאי:"],[5,"קמ\"ל כו'","והשואל דקא תני בדבורא בעלמא ולא משך מבעוד יום וקמ\"ל כיון דאסמכיה ברשותי' אוקמיה:"],[6,"ביו\"ט הרי הוא כרגלי המשאיל פשיטא","כיון דרישא בדבורא בעלמא מוקמינן וסיפא נמי הכי איתא דאפילו דבורא לא הוה אלא ביו\"ט:"],[7,"מימר אמר","האי משאיל:"],[7,"דלמא","כיון דלא אתי ואמר לי איניש אחרינא אשכח:"],[8,"כי סליק רבי אבא","כשרצה לעלות או כשהיה בדרך אמר תפלה זו:"],[8,"יהא רעוא","כי אמטי להתם:"],[8,"אימא מילתא","דשמעתתא:"],[8,"דתתקבל","לחכמי המקום שלא אבוש:"],[8,"כי סליק","כלומר כי מטא להתם:"],[8,"אמאי","כרגלי שתיהן לבטל איסור תחומין דמים ומלח דזוטרי לגבי עיסה דנפישא:"],[8,"אמר להו רבי אבא","ומשום דחלקה של זו מועט בה יאבד שמה מלקרות על עיסה זו וכי מי שנתערב לו כו' יאכל הלה זה שהרוב שלו:"]],[[0,"","והוינן בה מ\"ש כו' מזרח ומערב נמי אין ברירה. פ\"ה דס\"ד דהחכם בא בשבת על ידי אילן או גדר ואמר שביתתי תחתיו מבעוד יום ועל ידי כך בא בשבת מחוץ לתחום וקשה דהאיך יכול לבא בשבת משני צדי העיר למזרח ולמערב כיון שיש יותר מד' אלפים בינתיים לכן נ\"ל כדפ\"ה בעירובין (דף לו: ושם) דלעולם אינו יכול לבא בשבת רק מרוח אחת ומ\"מ צריך ברירה דשמא לא יזוז ממקומו דהא קאמר ואם לאו שלא יבא חכם לא כאן ולא כאן הריני כבני עירי והא דקאמר למזרח ולמערב לאו דוקא דאם כן יהא משמע דצריך למזרח משום מערב ולמערב משום מזרח אלא רוצה לומר למזרח או למערב נמי אין ברירה דשמא לא יזוז ממקומו ועוד אמר הרר\"ף דיכול להיות דהחכם בא משני צדדי העיר בשבת ואפילו בלא אילן וגדר כגון שהוא קרוב לשש אלפים של עיר מצפונה והוא רוצה להתקרב לתוך ד' אלפים של עיר לרוח מזרחית צפונית או לרוח מערבית צפונית מפני שיש שם מקום יפה לדרוש ואין נגד העיר ממש מקום פנוי לדרוש רק בשני מקומות אלו ואין האדם מניח ערובו למזרח ממש ולמערב ממש אלא מתקרב הוא לצד החכם כל מה שיכול ומניח ערובו לאלפים אמה של רוח מזרח לצד צפון וכן לאלפים אמה של רוח מערבי לצד צפון ונמצא שהוא יכול להתקרב עד תוך אלפים של מקום שביתת החכם שהוא מהלך כל אלכסון של ד' אלפים לצד צפון ע\"י ערובו שמניח למזרח או למערב והא דקאמר למזרח ולמערב ר\"ל למזרח תחומי העיר או למזרחו של חכם וקל להבין:"],[1,"","ואמר רבי יוחנן וכבר בא חכם אלמא לית ליה לר' יוחנן ברירה. וא\"ת לישני ליה דיש חלוק בין תולה בדעת עצמו לתולה בדעת אחרים לכאן ולכאן לא משום דתולה בדעת עצמו אבל למזרח ולמערב דתולה בדעת החכם אית ליה ברירה וי\"ל דר' יוחנן סבר דאין חלוק בין תולה בדעת עצמו לתולה בדעת אחרים והא דקאמר מ\"ש היינו ר' יוחנן דקאמר הכי כדי לבא לתרץ שכבר בא חכם וכי האי גונא אשכחנא (בבבא בתרא) דקאמר וכמה אמר ר' יצחק וכו' והיינו מילתיה דר' יצחק וא\"ת מאי פריך מדתני איו לרבי יוחנן הא ע\"כ צ\"ל דלרבי יוחנן אית ליה ברירה לר' יהודה דסבר ליה דאין חלוק בין תולה בדעת עצמו לתולה בדעת אחרים דהכי אמרינן בפרק בכל מערבין (עירובין דף לו: ושם) דקאמר התם מתנה אדם על שני דברים כו' ר' יהודה אומר אם היה אחד מהם רבו ילך אחר רבו ואם היו שניהם רבותיו למקום שירצה ילך דאית ליה ברירה וקאמר עלה בגמרא ליתא למתני' מדתני איו ופריך אדרבה ליתא לדאיו מקמיה מתני' דמתנה אדם על ערובו ומשני התם משום דתניא הלוקח יין מבין הכותים פי' מסייע ליה לדתנא איו סמי חדא מקמי תרתי כו' והקשה ר\"י התם אדרבה ליתא לדאיו וההוא דהלוקח דלית להו ברירה משום דתנן בפרק מי שאחזו (גיטין דף עג.) מה היא באותן הימים הרי היא כאשת איש לכל דבריה ולכי מיית הוי גיטא [ודייקינן מינה דאית ליה לר\"י ברירה] ותנן נמי בעה\"ב שאמר מה שלקטו עניים היום יהא הפקר אלמא כולהו הני מתני' אית להו ברירה לר\"י וא\"כ סמי תרתי מקמי תלת ומשני לעולם איתא לדאיו דכולהו מתניתין איירי בתולה בדעת אחרים ומשום הכא אית להו ברירה אבל איו מיירי בתולה בדעת עצמו ואם כן לר' יוחנן דלית ליה הך חילוק על כרחך אית ליה דליתא לדאיו מקמי הך תלת מתני' ומאי פריך לר' יוחנן מדתני איו ושמא משום דבעי לתרץ לעולם לא תיפוך הקשה קושיא קלה אע\"ג דשמא לר' יוחנן לית ליה דאיו עוד תירץ הר\"ר שמשון משא\"נז דאפי' ליתא לדאיו דר' יהודה לא אמרה מ\"מ חד תנא מעלמא אמרא ולכך מיישב ר' יוחנן הברייתא שכבר בא חכם כו' ואם כן פריך שפיר:"],[8,"","ולבטיל מים ומלח לגבי עיסה. פרש\"י הואיל ועיסה נפישא ותימה הא הוי דבר שיש לו מתירין שאפי' באלף לא בטיל וי\"ל דה\"מ מין במינו אבל מין בשאינו מינו כי הכא בטל שפיר והכי מפרש בהדיא בירושלמי ועוד דלא דמי לשאר איסורים דהדבר תלוי בטעם אבל הכא איסור תחומין תלוי בשם בעלים על החפץ ובכאן שם בעל העיסה עלויה ולא שם בעלת המים והמלח ולכך יש לו להתבטל אע\"ג דיהיב טעמא ולא בטל בשאר איסורים ורבי אבא מהדר להו דאין שם בעלת המים והמלח בטל מכאן כמו שאין שם בעל הקב בטל בעשרה קבין דנפישי:"]]],[["הרי שנתערב לו קב חטין בעשרה קבין חטין של חבירו יאכל הלה וחדי אחיכו עליה אמר להו גולתיכו שקלי הדור אחיכו עליה","אמר רב אושעיא שפיר עבוד דאחיכו עליה מאי שנא חטין בשעורים דלא קאמר להו דהוה ליה מין בשאינו מינו ומין בשאינו מינו בטיל חטין בחיטין נמי נהי דלרבי יהודה לא בטיל לרבנן מבטל בטיל","אמר ליה רב ספרא משה שפיר קאמרת ולא שמיע להו הא דאמר רבי חייא קטוספאה משמיה דרב הבורר צרורות מגרנו של חברו חייב לשלם לו דמי חטים","אלמא כילא חסריה הכא נמי כילא חסריה","א\"ל אביי ולא שני ליה למר בין ממון שיש לו תובעין לממון שאין לו תובעין","א\"ל וליטעמיך הא דאמר רב חסדא נבלה בטלה בשחוטה לפי שאי אפשר לשחוטה שתעשה נבלה","שחוטה אינה בטל' בנבלה לפי שאפשר לנבלה שתעשה שחוט'","הכי נמי דכי אית לה בעלים לא בטלה וכי תימא הכי נמי והא תניא א\"ר יוחנן בן נורי חפצי הפקר קונין שביתה אע\"פ שאין להם בעלים דומין כמי שיש להם בעלים","א\"ל מי קא מדמית איסורא לממונא איסורא בטיל ממונא לא בטיל","וטעמא מאי","אביי אמר גזרה שמא תעשה עיסה בשותפות","רבא אמר תבלין לטעמ' עבידי וטעמ' לא בטיל"],[[0,"וחדי","וישמח בדבר שלא עמל בו כך זו אין שמה בטל מכאן הואיל וקנו המים שביתה אצלה דהא לא קשיא לן משום שהשאילתן לה או נתנתן במתנה יהא מותר דהא אמר ביו\"ט הרי הוא כרגל המשאיל דבתר בין השמשות אזלינן וכי קשיא להו משום מעוטא ורובא קא קשיא להו:"],[0,"גולתיכו שקלי","מלבושכם לקחתי שאתם משחקים עלי:"],[0,"גולתא","תכריך נאה שמתעטף בו תחת טליתו וכשיושב מעביר טליתו וזה נראה:"],[1,"מאי שנא חטין בשעורים דלא קאמר להו","למי שנתערב לו קב חטין בי' קבין שעורין של חבירו יאכל הלה וחדי מכלל דסבירא ליה בה דודאי יאכל וחדי דכיון דשאינו מינו הוא בטל מועט במרובה:"],[1,"חטין בחטין נמי כו'","פלוגתא דרבי יהודה ורבנן במנחות בהקומץ רבה (מנחות דף כב.):"],[2,"אמר רב ספרא","לרב אושעי':"],[2,"משה","ביקרא דמשה קא משתבע:"],[2,"שפיר קא אמרת","בתמיה כלומר אמאי קא מודית להו בחוכא ולאקשויי אמתני':"],[2,"ולא שמיע להו","להנך רבנן דמקשו אמתני' הא דאמר וכו':"],[2,"משלם לו דמי חטין","שאין דרך לבוררן והן נמכרין בתוך החטין:"],[3,"אלמא כילא חסריה","מפני שחסר מדתו מתחייב לו ואע\"ג דלא מידי שוו וכ\"ש מים ומלח דלא בטלי במעוטייהו דמידי דטעמיה הוא משום חיובא דממונא לא בטיל במיעוטה:"],[4,"אמר ליה אביי","לרב ספרא והיכא מתרצא מתניתין בהכי:"],[4,"ולא שני ליה כו'","ומתני' ממון שאין לו תובעין היום הוא דאושלתינהו ניהלה עד לאחר יו\"ט ואין לה בעיסה זו אלא איסור שביתה משום ממונא המעורב בה וכיון דמעוטא ברובא הוא וממון שאין לו תובעין הוא לא חשיב ממונא ולבטל:"],[5,"אמר ליה","רב ספרא לאביי ומשום דאין לו תובעין פקע שם ממונא מיניה ונוח ליבטל וכי טעמא דבטול ברוב בבעלים ולא בעלים קאי:"],[5,"ולטעמיך הא דאמר רב חסדא נבלה בטלה בשחוטה","אליבא דר\"י אמר' במנחות דאמר מין במינו לא בטיל מין בשאינו מינו בטיל ותני רבי חייא נבלה ושחוטה בטלות זו בזו לר\"י ואשמעינן רבי חייא דכי אמר ר\"י היכא דאפשר לו להיות כמותו אבל אי אפשר לו להיות כמותו מין בשאינו מינו הוה ובטל ופריש רב חסדא דהאי אפשר ולא אפשר דרבי חייא בתר המבטל דהוא רובא אזלינן דאם אפשר לו להיות כמועט בהלכותיו הוי מין במינו ואי לא הוי מין בשאין מינו הלכך כזית נבלה שנתערבה בהרבה זיתים של שחוטה בטלה כמי שאינה שם והנוגע בהן אין טמא דמין בשאין מינו הוא דאי אפשר לשחוטה שהוא המבטל להיות מטמא במגע ובמשא כנבלה אבל שחוטה שנתערבה בנבלה דרובה נבלה אין השחוטה בטלה להיות הנוגע בהן טמא ודאי לשרוף תרומה על מגעו לפי שאפשר לנבלה שהוא המבטל שתעשה טהורה כשחוטה דלכי מסרחה ואינה ראויה לגר שוב אין קרויה נבלה:"],[7,"הכי נמי","דאי הוו לה בעלים לא בטלה:"],[7,"וכ\"ת הכי נמי והתני'","דמשום דלאו בעלים לא פקע חשיבותא דממונא:"],[7,"דאמר רבי יוחנן חפצי הפקר","הנמצאים קונין שביתה והמוצאן מוליכן ממקום מציאתן אלפים לכל רוח ואינו מוליכן למקום שערב שם דיש להם שביתה לעצמן אלמא חשיבי בלא בעלים ושפיר תנן במתני' דאע\"ג דאין לו תובעין לא לבטול:"],[7,"ר' יוחנן בן נורי אומר כו'","ולא בהדיא תנן לה הכי אלא מדבריו שמענוה בפרק מי שהוציאוהו (עירובין דף מה:):"],[8,"א\"ל","אביי לרב ספרא אכתי מתני' לא מתרצא דאפי' יש לו תובעין איכא לאקשויי ליבטל מדמייתית על זה הבורר צרורות מי קא מדמית איסורא לאפסודי ממונא איסורא אמור רבנן לבטיל ברובא אבל ממונא לא בטיל מועט ברוב להיות קנוי ממון המועט לבעליו של מרובה ומתניתין נמי לא קאמרינן דלפקע רוב ממונא אצל חברתה להפסיד אלא איסור תחומין שיש לה בה הוא דקשיא לן דלבטל:"],[9,"וטעמא מאי","הש\"ס בעי לה דכיון דלאו תירוצא נינהו הנך שנויי טעמא דמתניתין דלא בטיל מאי הוא:"],[10,"","ה\"ג אביי אמר כו' ורבא אמר כו' ולא פליגי אלא מר שני עיסה ומר קדרה:"],[10,"אביי אמר גזרה שמא תעשה עיסה בשותפות","אי אמרת מים ומלח לא אסרי עלה אתי למימר נמי בעיסת שותפות דיוליכוה כל אחת ואחת למקומה:"],[11,"ורבא אמר כו'","ולא פליג אדאביי אלא מר שני חדא ומר שני חדא:"]],[[0,"","הרי שנתערב לו קב כו'. ואם תאמר האי פרכא אמאי המתין להקשות אותה עד כאן דהא בכל דוכתא דקאמר חד בתרי בטיל מצי למפרך הכי וי\"ל דלא מצי למפרך בעלמא הכי דאין לדמות איסור לממונא אבל הכא במתני' ממונא אע\"ג דאיכא איסור תחומים מ\"מ איסור התחומים אינו בא אלא משום דעת הבעלים דבעלמא בשאר אסורי חד בתרי בטיל אבל הכא הכי פריך דודאי מי שנתערב לו קב חטין כו' משום בטול לא פקע שם בעלים ה\"נ משום בטול לא פקע שם בעלים וקנו מים ומלח שביתה אצל בעלים ולא בטיל:"],[0,"","וחדי. וישמח לבו בדבר שלא עמל בו כך זו אין שמה בטל מכאן הואיל וקנו המים שביתה אצלם והא לא קשי' דמשום שהשאילתו לו [או נתנתה] במתנה יהא מותר דהא אמר ביו\"ט הרי הוא כרגלי המשאיל דבתר בין השמשות אזלינן וכי קשיא להו משום מעוטא ורובא קשיא להו לשון הקונ':"],[1,"","נהי דלר' יהודה לא בטיל לרבנן מבטל בטיל. מכאן נראה דהלכה כרבנן מין במינו בטיל שפיר דהא סתמה דהש\"ס קאמר הכי:"],[7,"","הכי נמי דכי אית ליה בעלים לא בטיל. פרש\"י אלא ודאי בטל וא\"ת והא רב ספרא אתא לקיי' תירוץ דרבי אבא ור' אבא קאמר דאפילו אין לו תובעין לא בטיל כמו במתניתין כ\"ש הכא שיש לו והיכי מייתי ראיה דאפילו יש לו תובעין בטל ואדרבה תקשי ליה לנפשיה וי\"ל דבשלמא רב ספרא לא קשה ליה דשאני איסורא מממונא אע\"ג דיש לו תובעין והכא מיירי באסור נבלה שנתערבה בשחוט' כו' לכך בטל אע\"ג דיש לו תובעין ורב ספרא מייתי הכי אלמא מידי דשייך ביה ביטול יש לו תובעין אין מועיל כלל לומר הואיל ויש שם בעליו עליו אינו בטל אלא מבטל שפיר אלמא לא תליא מילתא כלל בתובעין אם כן מתניתין נמי אע\"ג דאין לו תובעין כיון דלא שייך ביה בטול דממונא הוא ואסור תחומין בא על ידי הבעלים ושם בעליו עליו קנו שביתה אצלו ולא שייך בו בטול:"],[7,"","וכי תימא הכי נמי דלא שייך והתני' רבי יוחנן בן נורי אומר חפצי הפקר כו'. אלמא אע\"ג דאין לו תובעין קנו שביתה במקומן וא\"ת מאי פריך מר' יוחנן בן נורי הא פליגי רבנן עליה דרבי יוחנן ואנן ס\"ל כרבנן דאמרי לא קנו שביתה אלא כרגלי המוצאן הואיל ולית להו תובעין הכי נמי במתני' נימא הכי וי\"ל דהכי מייתי דעד כאן לא פליגי רבנן עליה דר' יוחנן בן נורי אלא היכא דאין שייכות הבעלים כלל כגון חפצי הפקר דקנו שביתה במקומן אבל היכא דיש להם שייכות הבעלים כגון במתני' אפי' רבנן מודו דאזלינן בתר בעלים אפי' היכא דליכא תובעין השתא ומדרבי יוחנן נשמע לרבנן דכי היכי דלרבי יוחנן חפצי הפקר קנו שביתה במקומן אע\"ג דאין להן תובעין לרבנן נמי היכא דהיו להם תובעין אע\"ג דהשתא לית להן קנו שביתה במקומן:"],[11,"","רבא אמר עבידי כו'. פ\"ה דאביי יהיב טעמא לעיסה ורבא שני קדרה ולא פליגי ודוחק לכן נראה דאביי שני עיסה וה\"ה קדרה שמא תעשה בשותפות ורבא שני קדרה והוא הדין עיסה דמלח יהיב טעמא בעיסה ומים חשיבי דעיקר העיסה נעשית ממים:"]]],[["ורב אשי אמר משום דהוי ליה דבר שיש לו מתירין וכל דבר שיש לו מתירין אפילו באלף לא בטיל:","רבי יהודה פוטר במים: מים אין מלח לא והא תניא ר' יהודה אומר מים ומלח בטלין בין בעיסה בין בקדרה לא קשיא הא במלח סדומית הא במלח אסתרוקנית","והתניא ר' יהודה אומר מים ומלח בטלין בעיסה ואין בטלין בקדרה מפני רוטבה לא קשיא הא בעבה הא ברכה:","\u0001מתני׳\u0002 הגחלת כרגלי הבעלים ושלהבת בכל מקום גחלת של הקדש מועלין בה ושלהבת לא נהנין ולא מועלין המוציא גחלת לרה\"ר חייב ושלהבת פטור:","\u0001גמ׳\u0002 ת\"ר חמשה דברים נאמרו בגחלת הגחלת כרגלי הבעלים ושלהבת בכל מקום גחלת של הקדש מועלין בה ושלהבת לא נהנין ולא מועלין גחלת של ע\"ז אסורה ושלהבת מותרת המוציא גחלת לרשות הרבים חייב ושלהבת פטור המודר הנאה מחבירו אסור בגחלתו ומותר בשלהבתו","מאי שנא שלהבת ע\"ז דשריא ומאי שנא דהקדש דאסירא ע\"ז דמאיסה ובדילי אינשי מינה לא גזרו בה רבנן הקדש דלא מאיס ולא בדילי אינשי מיניה גזרו ביה רבנן:","המוציא גחלת לרשות הרבים חייב ושלהבת פטור: והא תניא המוציא שלהבת כל שהוא חייב אמר רב ששת כגון שהוציאו בקיסם","ותיפוק ליה משום קיסם בדלית ליה שעורא דתנן המוציא עצים כדי לבשל ביצה קלה","אביי אמר כגון דשייפיה מנא משחא ואתלי ביה נורא ותיפוק ליה משום מנא בחספא","ותיפוק ליה משום חספא בדלית ליה שעורא דתנן חרס כדי ליתן בין פצים לחבירו דברי ר' יהודה","אלא הא דתנן המוציא שלהבת פטור היכי משכחת לה כגון דאדייה אדויי לרה\"ר:","\u0001מתני׳\u0002 בור של יחיד כרגלי היחיד ושל אנשי אותה העיר כרגלי אנשי אותה העיר ושל עולי בבל כרגלי הממלא:","\u0001גמ׳\u0002 רמי ליה רבא לרב נחמן תנן בור של יחיד כרגלי היחיד ורמינהו נהרות המושכין ומעינות הנובעין הרי הן כרגלי כל אדם אמר (רבא) הכא במאי עסקינן) במכונסין ואתמר נמי א\"ר חייא בר אבין אמר שמואל במכונסין:","ושל עולי בבל כרגלי הממלא: אתמר מילא ונתן לחבירו רב נחמן אמר כרגלי מי שנתמלאו לו רב ששת אמר כרגלי הממלא","במאי קא מיפלגי מר סבר בירא דהפקרא הוא ומר סבר בירא דשותפי הוא","איתיביה רבא לרב נחמן הריני עליך חרם המודר אסור"],[[0,"שיש לו מתירין","למחר יוליכוה או היום יאכלוה כאן:"],[1,"סדומית","דקה היא מאוד ובטלה ותדע שהסדומית דקה היא דאמרינן (חולין דף קה:) מפני מה אמרו מים אחרונים חובה מפני שמלח סדומית יש שמסמא את העינים אלמא דקה היא מאד ונדבקת ביד ואינה נכרת:"],[2,"ואין בטלין המים בקדרה מפני רוטבה","הניכר לעינים ומתניתין פוטר במים תנן לא שנא עיסה ולא שנא קדרה דמתניתין בתרתי איירי מדקתני תבלין דהיינו לקדרה:"],[2,"עבה","תבשיל עבה שאין רוטבו ניכר והוי כעיסה:"],[3,"מתני' ושלהבת","כגון הדליק נר בשלהבת חברו אינו מעכב באיסור תחומין:"],[3,"מועלין בה","הנהנה ממנה מביא אשם:"],[3,"ושלהבת לא נהנין","לכתחלה מדרבנן ואם נהנין לא מועלין אין חייבין קרבן מעילה דלית ביה ממשא:"],[3,"המוציא שלהבת פטור","מפרש בגמרא:"],[4,"גמ' גחלת של ע\"ז","שנאמר ולא ידבק בידך מאומה מן החרם (דברים י״ג:י״ח) אסור בגחלתו ומותר בשלהבתו:"],[5,"מאי שנא של ע\"ז דשרי","לגמרי דאפילו מדרבנן לא גזור בה דקתני ומותרת ובשל הקדש קתני לא נהני:"],[5,"הקדש לא מאיס ולא בדילי אינשי מינה","כולי האי כע\"ז דבדיליתא דהקדש לאו משום מאיסותא אלא משום אסורא ונהי דבעלמא אמרינן לגבי חולין בדילי אינשי מהקדש אבל לגבי ע\"ז לאו בדילותא היא:"],[6,"כל שהוא","בלא שיעור:"],[6,"הא דתני חייב כשהוציאו בקיסם","דכיון דיש לו דבר להדבק בו חשובה היא בכל שהוא ומתניתין דקתני פטור כדאוקימנא לקמן בדאדייה אדויי שהיתה דולקת ברשות היחיד סמוך לרשות הרבים ונפח בידו ונתק שלהבת והפריחה לרשות הרבים:"],[7,"ותיפוק ליה משום קיסם","אמאי תני המוציא שלהבת כל שהוא חייב בלאו שלהבת נמי חייב משום קיסם:"],[7,"בדלית בה שיעורא","להוצאת שבת:"],[7,"ביצה קלה","שהיא קלה לבשל מכל הביצים ושיערו חכמים זו ביצת תרנגולת:"],[8,"אביי אמר הא דתני חייב כגון דשייפיה למנא משחא כו'","ומשום דיש לה דבר להאחז בו היא חשובה אבל בקיסם לא סבירא ליה לאביי משום דמועט הוא וממהר לכבות אי נמי רבותא אשמעינן אביי ואפי' בחספא בעלמא נמי שאינה נאחזת כל כך חשיבא הוצאה:"],[9,"חרס","לענין הוצאת שבת:"],[9,"כדי ליתן בין פצים לחבירו","פצים כמו פצימי פתחים (סוכה דף יח.) ופצימי חלונות (ב\"ב דף יב.) הקבועים בחומה והן של עץ וסודרין אותם למטה ולמעלה ומשתי רוחות ופעמים שהן קצרים ברוחב ומושיבין שנים זה בצד זה וצריך להושיבן בשוה שלא יהא זה נמוך מזה ולא יהו עקומים וכשהאחד נוטה נותן לתחתיו חרס או אבן להשוותו או בשאין די ברוחב שניהם מבדילן זה מזה מעט ונותן חרסים דקים ביניהם:"],[10,"אלא הא דתנן","מתני' פטור היכי משכחת לה:"],[10,"ומשני דאדייה אדויי","כמו וידו אבן בי (איכה ג׳:נ״ג):"],[11,"מתני' כרגלי היחיד","אין מוליכין המים אלא כרגלי בעל הבור:"],[11,"כרגלי אותה העיר","אלפים לכל רוח חוץ לעבורי':"],[11,"ושל עולי בבל","העשויין לעוברי דרכים באמצע הדרך ועשאום בני הגולה לשתות בעלותם:"],[11,"כרגלי הממלא","מפני שהוא הפקר והפקר נקנה בהגבהה ואם בא אחד ושאל לו מימיו אינו מוליכן אלא כרגליו ולית ליה דרבי יוחנן דאמר חפצי הפקר קונים שביתה לעצמן במקומן וכ\"ת א\"כ הוה ליה למימר הרי הן כרגלי כל אדם ואמאי קתני כרגלי הממלא קסבר יש ברירה להחמיר ואמרינן הוברר דמאתמול נמי הוברר דלהאי גברא חזו וברשותיה קיימי ובעירובין (דף מה:) נמי דלא כרבי יוחנן בן נורי מתוקמא:"],[12,"גמ' נהרות המושכין","היינו סתם נהרות שיש להם משך להלאה ממקום מקור נביעתן:"],[12,"ומעינות הנובעין","ואין יוצאין מגומות נביעתן לימשך הלאה:"],[12,"הרי הן כרגלי כל אדם","אין להם שום שביתה לא במקומן ולא כרגלי הבעלים ולא כרגלי הממלא אלא כל אדם מוליכן ברגליו דכל מידי דנייד לית ליה שביתה והכי מפרשי' בעירובין בפרק מי שהוציאוהו:"],[13,"מילא ונתן לחבירו","וכגון שמילא לצורך חבירו דאי מלאו לעצמו הא תנן בהדיא כרגלי הממלא:"],[13,"כרגלי מי שנתמלאו לו","דנעשה זה שלוחו וקנה לו:"],[14,"רב ששת סבר בירא דהפקרא הוא","והמגביה מציאה לחבירו לא קנה חבירו כדאמרינן בבבא מציעא בשנים אוחזין (בבא מציעא דף י.) דהוי תופס לבעל חוב במקום שחב לאחרים אלא המגביה קנה ורב נחמן סבר בירא דשותפי הוא לא הפקירוהו בני הגולה אלא נתנוהו לכל ישראל שיהיו שותפין בו וכשאמר זה לחבירו למלאות לו מחלקו והלך בשליחותו נעשה שלוחו ואין זה מגביה מציאה:"],[15,"המודר אסור","מי שהוטל עליו הנדר אסור ליהנות מזה שנדר הנדר דה\"ק ממוני עליך הקדש:"]],[[0,"","משום דהוי דבר שיש לו מתירין וכל דבר שיש לו מתירין וכו'. ואם תאמר והא [פרישית] לעיל דלא שייך דבר שיש לו מתירין אלא במין במינו וי\"ל דאין הכי נמי דלא אמרינן ליה אלא במין במינו והכא גבי תחומין שאני דחמירי כאילו הוי מין במינו בעלמא כיון דממונא הוא ועי\"ל דכיון דהעיסה אינה נלושה אלא ע\"י המים והקדרה נתקנה בשביל התבלין אם כן כשערב זה בזה הוי כאילו מין אחד:"],[5,"","הקדש דלא בדילי אינשי גזרו רבנן. וקשה דבפ\"ק דפסחים (דף ו.) קאמר אם של הקדש הוא אין צריך לכסותו מפני שבדלים ממנו אלמא משמע דהקדש בדילי מיניה וי\"ל דאין הכי נמי דלגבי חולין בדלין ממנו אבל לגבי ע\"ז לא בדילי מיניה:"],[8,"","ותיפוק ליה משום מנא. וא\"ת ולבטיל מנא אגב שלהבת דהכי אמר בשבת פרק המצניע (שבת דף צג:) פחות מכשיעור בכלי פטור אף על הכלי דהוי הכלי בטל אגב האוכלין וי\"ל דשאני הכא דליכא חשיבותא בשלהבת לבטל הכלי לגבה דלית בה ממש:"]]],[["הרי אתה עלי חרם הנודר אסור הריני עליך ואתה עלי שניהם אסורים זה בזה ומותרין בשל עולי בבל ואסורין בשל אותה העיר","ואלו הן דברים של עולי בבל הר הבית הלשכות והעזרות ובור של אמצע הדרך ואלו הן של אותה העיר הרחוב ובית הכנסת ובית המרחץ","ואי אמרת בירא דשותפי הוא אמאי מותר והתנן השותפין שנדרו הנאה זה מזה אסורים ליכנס לחצר לרחוץ בבור","לרחוץ ה\"נ והכא במאי עסקינן למלאות מר מדידיה קא ממלא ומר מדידיה קא ממלא","וסבר רב נחמן יש ברירה והתנן האחין השותפין כשחייבין בקלבון פטורין ממעשר בהמה","וכשחייבין במעשר בהמה פטורין מן הקלבון","ואמר רב ענן לא שנו אלא שחלקו גדים כנגד טלאים וטלאים כנגד גדים","אבל חלקו גדים כנגד גדים וטלאים כנגד טלאים אומר זהו חלקו המגיעו משעה ראשונה לכך","ורב נחמן אמר אפילו חלקו גדים כנגד גדים וטלאים כנגד טלאים אין אומר זה חלקו המגיעו משעה ראשונה לכך","אלא דכולי עלמא בירא דהפקרא היא אלא הכא במגביה מציאה לחבירו קא מיפלגי מר סבר קנה ומר סבר לא קנה:","\u0001מתני׳\u0002 מי שהיו פירותיו בעיר אחרת וערבו בני אותה העיר להביא אצלו מפירותיו לא יביאו לו ואם ערב הוא פירותיו כמוהו"],[[0,"הרי אתם עלי חרם","הכי קאמר ליה הרי ממונך עלי כסתם חרמים שהן לבדק הבית הלכך הנודר אסור ליהנות משל המודר דכתיב לא יחל דברו (במדבר ל׳:ג׳) ורשאי הוא לאסור עצמו בממון חברו:"],[0,"ומותרין בדברים של עולי בבל","שעשו בני הגולה לפי שהפקירום לכל ישראל ונתנום להם ולא להיותם שותפין בו שיהא להם כח לאסור זה חלקו על זה:"],[1,"של אותה העיר","שהן דרין בה מפני שהן שותפים בהן וזה אסור מפני חלקו של זה:"],[3,"הכא במאי עסקינן למלאות","הא דקתני ובור של אמצע הדרך מותרין לא לכל תשמיש הותרו כגון לירד ולרחוץ בתוכו דבירא דשותפין הוא וכשהתירו למלאות מימיו התירו דסמכינן אבריר' ואמרי' מר מדידיה קא ממלא מים שעלו בכדו הן המבוררין מן השמים לחלקו:"],[4,"האחים השותפין","אחים שהן שותפין בירושת אביהן:"],[4,"כשחייבין בקלבון פטורין ממעשר בהמה וכשחייבין במעשר בהמה פטורים מן הקלבון","כל ישראל הוזקקו לתת מחצית השקל לקרבנות צבור והטילו חכמים עליהם להוסיף מעה קטנה להיות קלבון לפרוטרוט מפני שהן חצאי שקלים חתיכות דקות ונוחין לאבד ופעמים שמחליפין אותן במנים ונותנין הקלבון בחלוף ואף כשמצטרפין שנים לתת שקל שלם הטילו עליהם שני קלבוני' שלא לפחות מחבריהם ולמעט את ההקדש אבל האב שוקל בשביל שני בניו שקל שלם ופטור מקלבון שני:"],[4,"","מעשר בהמה נוהג בכל שנה בולדות הנולדים ועדר של שותפין פטורים הולדות ממעשר כדתניא בבכורות (דף נו:) כל פטר שגר בהמה אשר יהיה לך (שמות י״ג:י״ב) ולא של שותפות ופרכינן והא בבכור כתיב ומשנינן אם אינו ענין לבכור דאיתיה בשותפות דכתיב ובכורות בקרכם וצאנכם (דברים י״ב:ו׳) תנהו ענין למעשר יכול אפי' קנו בתפיסת הבית כגון אחין שלא הספיקו לחלוק ירושתן עד שנולדו להם ולדות ת\"ל יהיה הלכך אחים שהן שותפין ששותפותן לאחר חלוקה כגון שחזרו ונשתתפו חייבין בקלבון כשאר שנים המתחברין לשקל שלם ופטורים ממעשר בהמה דשותפין בעלמא נינהו דבטלה לה תפיסת הבית וכשחייבים במעשר בהמה כגון שנשתתפו משנפלה להם הירושה דקיימא תפיסת הבית פטורין מן הקלבון כאילו היה אביהן קיים שממונן אחד ופוטרן יחד:"],[6,"ואמר רב ענן לא שנו","דבשביל חלוקה בטלה תפיסת הבית מנייהו:"],[6,"אלא כשחלקו","על פי שום בדמים גדים כנגד תישים זקנים או כנגד טלאים דבטלו מהן שם ירושה ונתנו בה תורת לקוחות וכי חזרו ונשתתפו הוו להו כלקח זה בשלו וזה בשלו מן השוק ונתערבו ואין כאן עוד שם תפיסת הבית אלא שם שותפות אבל חלקו טלאים כנגד טלאים וגדים כנגד גדים דזהו משפט ירושה לכל אחד חלק בכל מין ומין אומרים זה חלקו המגיעו דיש ברירה ועדיין שם . יורשים עליהן וכשחזרו ונשתתפו חזרה תפיסת הבית למקומה ויש פותרים הטעם משום לקוחות דתנן הלוקח פטור ממעשר בהמה (בכורות דף נה:) וטעות הוא בידם דכשהולדות לקוחין הן פטורין מלהתעשר אבל הלוקח עשר בהמות וילדו חייבין במעשר והכא לגמרי פטר להו:"],[8,"אין אומרים כו'","ופטור אלמא אין ברירה אלא על כרחך לרב נחמן בירא דהפקרא הוא מדאשתרו ביה מודרי הנאה גבי מילא ונתן לחברו:"],[9,"במגביה מציאה לחברו קא מפלגי","לא גרסינן במגביה מציאה קנה חברו קמפלגי ולא גרס מר סבר קנה חבירו כו' דאם כן קשיא דרב נחמן אדרב נחמן דאבעי לן לפרושי הכא דרב נחמן סבר קנה חברו דקאמר כרגלי מי שנתמלאו לו ובשנים אוחזין (ב\"מ דף י.) אמרינן רב נחמן ורב חסדא דאמרי תרוייהו המגביה מציאה לחברו לא קנה חברו אלא ה\"ג במגביה מציאה לחברו קא מפלגי ותו לא ופי' במגביה מציאה לחברו קא מפלגי ודכולי עלמא לא קנה חברו בהגבהתו של זה אלא אם קנה המגביה אם לא קנה פליגי רב נחמן סבר לא קנה המגביה דלאו אדעתיה למקני אלא מי שנתמלאו לו קנאם במשיכה כשיקבלם כשבאו לרשותו ודעתו לקנות דכי אמר לא קנה חברו כל זמן שהוא ביד המגביה אמרינן דיכול לומר אני אזכה בה לעצמי אבל משנתנה לו קנה דתנן התם [דף ט:] ואם משנתנה לו אמר זכיתי בה תחלה לא אמר כלום ורב ששת סבר קנה המגביה תחלה ומיד קבלם זה הלכך כרגלי הממלא ואית דגרס כמו שכתוב בספרים ומפרשין הכי רב נחמן סבר קנה חבירו משנתן לו ורב ששת סבר לא קנה חברו אלא המגביה:"],[10,"מתני' לא יביאו","מפירותיו הואיל והוא לא ערב לשם דהכל כרגלי הבעלים:"],[10,"ואם ערב הוא","ללכת לשם:"],[10,"פירותיו כמוהו","ומותר להביאם:"]],[[4,"","[והתנן השותפין. מגופיה הוי מצי למידק דאסר בה\"כ ובית המרחץ מטעם שותפין אלא זאת פשוט יותר]. ת\"י:"],[9,"","הכא במגביה מציאה לחברו קנה חבירו קמפלגי. דרב נחמן אית ליה קנה חברו ולכך קאמר כרגלי מי שנתמלאו לו כו' והקשה רש\"י דבהדיא קאמר רב נחמן בפ\"ק דב\"מ (דף י. ושם) דמגביה מציאה לחברו לא קנה חברו אלא נראה לרש\"י דה\"ג במגביה מציאה לחברו קמפלגי ותו לא וה\"פ רב נחמן סבר לא קנה המגביה דלא היה בדעתו למקני והוי הפקר עד שבאו ליד מי שנתמלאו לו והוא קנאם במשיכה דדעתו היה לקנות ואע\"ג דמגביה מציאה לחברו לא קנה חברו היינו כשעודה ביד המגביה לפי דמצי למימר אני זכיתי לעצמי אבל כשנטלה חברו זכה מן ההפקר כיון דמגביה לא הגביה לקנות לו כדתנן התם ואם משנתנה לו אמר אני זכיתי בה תחלה לא אמר כלום לכך הוי כרגלי מי שנתמלאו לו ורב ששת אמר מגביה מציאה לחברו קנה המגביה תחלה וזה קבלה מידו הלכך הוי כרגלי הממלא ודוחק הוא למחוק גרסת הספרים ועוד אין סברא לרב ששת שיקנה המגביה בלא מתכוין לכ\"נ לרשב\"ם לפרש שיש לישב גרסת הספרי' ומה שהקשה רש\"י לא קשה מידי דשאני התם דקאמר טעמא משום דהוי תופס לבעל חוב במקום שחב לאחרים דאחרים לא ימצאו המציאה אח\"כ לפיכך קאמר רב נחמן דלא קנה אבל הכא אית ליה לרב נחמן שפיר דקנה מי שנתמלאו לו דלא הוי חב לאחרים דהא איכא הרבה מים דיכולים אחרים למלאות ועוד אומר ר\"ת דיש לקיים גרסת הספרים וה\"פ מר סבר המגביה מציאה לחברו קנה חבירו היינו רב ששת ולכך קאמר כרגלי הממלא דמאיזה טעם אמרינן המגביה מציאה לחברו קנה חברו דמגו דזכי לנפשיה זכי נמי לחבריה והואיל ואתי מכחו דין הוא שיהא כרגלי הממלא ור\"נ ס\"ל לא קנה חברו והשתא ניחא ההיא דב\"מ דגם הוא לא קנה דלא נתכוון לקנות וא\"כ הרי הן הפקר כל זמן שלא באו לידי מי שנתמלאו לו ולכשיבאו לידו יזכה בהן מן ההפקר לפיכך הן כרגליו (לישנא אחרינא במגביה מציאה לחברו קא מפלגי ולא גרסינן מר סבר קנה חברו וכו' דא\"כ קשיא דר\"נ אדר\"נ דמבעיא לפרושי הכא ר\"נ סבר קנה חברו דקאמר כרגלי מי שנתמלאו לו ובשנים אוחזין רב נחמן ורב חסדא אמרי תרוייהו המגביה מציאה לחברו לא קנה חברו בהגבהתו של זה ולא קנה המגביה דלאו אדעתיה למקני אלא מי שנתמלאו לו קנאן במשיכה כשיקבלו שיבאו לרשותו ודעתו לקנות דכי אמרינן לא קנה כל זמן שביד המגביה אמר דיכול לומר לו אני אזכה לעצמו בה תחלה אבל משנתנה לו קנה דתנן התם אם משנתנה לו אמר אני זכיתי בה תחלה לא אמר כלום ורב ששת סבר קנה המגביה ומידו קבלה זה הלכך כרגלי הממלא ואית דגרס כמו שכתוב בספרים ומפרש הכי רב נחמן סבר קנה חברו משנתן לו רב ששת סבר לא קנה חברו אלא המגביה לשון הקונטרס):"]]],[["מי שזמן אצלו אורחים לא יוליכו בידם מנות אלא אם כן זכה להם מנותיהם מערב יו\"ט:","\u0001גמ׳\u0002 אתמר המפקיד פירות אצל חבירו רב אמר כרגלי מי שהפקידו לו ושמואל אמר כרגלי המפקיד לימא רב ושמואל דאזדו לטעמייהו דתנן אם הכניס ברשות בעל החצר חייב רבי אומר לעולם אינו חייב עד שיקבל עליו בעל הבית לשמור","ואמר רב הונא אמר רב הלכה כדברי חכמים ושמואל אמר הלכה כרבי לימא רב דאמר כרבנן ושמואל דאמר כרבי","אמר לך רב אנא דאמרי אפי' לרבי עד כאן לא קאמר רבי התם אלא דבסתמא לא קביל עליה נטירותא אבל הכא הא קביל עליה נטירותא","ושמואל אמר אנא דאמרי אפי' לרבנן עד כאן לא קאמרי רבנן התם אלא דניחא ליה לאיניש דניקום תוריה ברשותיה דבעל חצר דאי מזיק ליה לא מיחייב אבל הכא מי ניחא ליה לאיניש דליקום פיריה ברשותיה דחבריה","תנן ואם ערב הוא פירותיו כמוהו ואי אמרת כרגלי מי שהפקידו אצלו כי ערב הוא מאי הוי אמר רב הונא אמרי בי רב כגון שיחד לו קרן זוית","ת\"ש מי שזמן אצלו אורחים לא יוליכו בידם מנות אא\"כ זכה להם מנותיהם מערב יו\"ט ואי אמרת כרגלי מי שהפקידו אצלו כי זכה להם ע\"י אחר מאי הוי ה\"נ כיון שזכה להם ע\"י אחר כמי שיחד לו קרן זוית דמי","ואיבעית אימא זכה שאני","רב חנא בר חנילאי תלא בשרא בעברא דדשא אתא לקמיה דרב הונא א\"ל אי את תלית זיל שקיל ואי אינהו תלו לך לא תשקול","ואי איהו תלא מי שקיל והא רב הונא תלמיד דרב הוה ואמר רב כרגלי מי שהפקידו אצלו שאני עברא דדשא דכמי שיחד לו קרן זוית דמי","א\"ל רב הלל לרב אשי ואי אינהו תלו ליה לא שקיל והאמר שמואל שור של פטם הרי הוא כרגלי כל אדם","א\"ל רבינא לרב אשי ואי אינהו תלו ליה לא שקיל והאמר רבה בר בר חנה א\"ר יוחנן הלכה כר' דוסא א\"ל רב אשי לרב כהנא ואי אינהו תלו ליה לא שקיל והתנן הבהמה והכלים כרגלי הבעלים","אלא שאני רב חנא בר חנילאי דגברא רבה הוא וטריד בשמעתיה וה\"ק ליה אי את תלית אית לך סימנא בגוויה ולא מסחת דעתך מניה זיל שקול ואי אינהו תלו לך מסחת דעתך ולא תשקול:","\u0001מתני׳\u0002 אין משקין ושוחטין את המדבריות אבל משקין ושוחטין את הבייתות אלו הן בייתות הלנות בעיר מדבריות הלנות באפר:","\u0001גמ׳\u0002 למה לי למימר משקין ושוחטין מילתא אגב אורחיה קמ\"ל דלשקי אינש בהמתו והדר לשחוט משום סרכא דמשכא","ת\"ר אלו הן מדבריות ואלו הן בייתות מדבריות כל שיוצאות בפסח ורועות באפר ונכנסות ברביעה ראשונה ואלו הן בייתות כל שיוצאות ורועות חוץ לתחום ובאות ולנות בתוך התחום רבי אומר אלו ואלו בייתות הן אלא אלו הן מדבריות כל שיוצאות ורועות באפר ואין נכנסות לישוב לא בימות החמה ולא בימות הגשמים","ומי אית ליה לרבי מוקצה והא בעא מיניה ר' שמעון בר רבי מרבי פצעילי תמרה לר\"ש מהו א\"ל אין מוקצה לר\"ש"],[[0,"מי שזמן אצלו אורחים","מעיר אחרת ויבואו אצלו על ידי עירוב:"],[0,"לא יוליכו","לאחר סעודה מנות בידם לביתם לסעודת לילה:"],[0,"אלא אם כן זכה להם","ע\"י אחר:"],[0,"מנותיהם מערב יו\"ט","שמסרם בעל בית זה לאדם אחר במשיכה ואמר לו זכה במנות הללו לפלוני ולפלוני דזכין לו לאדם שלא בפניו והיו שלהם מבעוד יום לילך כרגליהם:"],[1,"גמ' אם הכניס ברשות","שורו וקדרותיו ופירותיו לחצר חברו בעל חצר חייב בנזקין ורישא דהך מתני' בבבא קמא דכי אמר ליה עול עול ואנטר קאמר ליה:"],[2,"לימא","הך פלוגתא דהכא כי הך אזלא משום דאמר רב הלכה כרבנן דקיימי ברשותיה לענין שמירה הוא הדין לתחומין:"],[3,"אמר לך רב","בהך אנא דאמרי אפי' לרבי דאילו רבי לא פליג אלא בדלא פריש אלא עול סתמא אמר ליה וסבר רבי עול ותנטר את קאמר ליה אבל מפקיד פירות דהכא לאו בסתמא עסקינן אלא בדקביל לנטירותא:"],[4,"ושמואל אמר אנא דאמרי","בהא אפי' לרבנן עד כאן לא קאמרי רבנן התם דקיימי ברשות בעל חצר אלא לענין שמירה דכיון דסבירא להו דמסתמא עול ואנטר לך קאמר ליה כ\"ש דבעל השור מינח ניחא ליה דמוקי שורו ברשותו דבעל חצר לשמרו דאי מזיק האי שור לבעל חצר לא מיחייב עליה אבל הכא לענין תחומין מי ניחא ליה לאיניש כו':"],[5,"תנן ואם ערב הוא פרותיו כמוהו","אלמא כרגלי המפקיד נינהו:"],[5,"שיחד לו קרן זוית","דאושליה ביתא הלכך ברשות המפקיד הן אבל הכא דמשכן שומר וקבל עליו שמירתן הרי הן כרגליו:"],[6,"אא\"כ זכה","וכי זכה מיהא מוליכין והרי בידו הופקדו לאחר זכיה וש\"מ כרגלי המפקיד הן:"],[7,"זכה שאני","שהרי כל עצמו לא עשה אלא להוציאו משביתתו ולהעמידו בשביתה שלהן וברשותן:"],[8,"תלא בשרא בעברא דדשא","בבית אושפיזכניה שנתנו לו טבחי העיר מבעוד יום והוא היה בן עיר אחרת שמערבין לו לבוא לכאן:"],[8,"ה\"ג א\"ל אם את תלית זיל שקיל ואי אינהו תלו לך","לצרכך לא תשקול להוליכן לעירך ולקמיה מפרש טעמא ואזיל:"],[8,"אי את תלית","מידי דעביד איניש בידיה לא מנשי ולא מסח דעתיה:"],[8,"ואי אינהו תלו לך","אתה לא היה דעתך לכך והם אינם זהירים בשלך ואסחו דעתייהו ולא תשקול לשון אחר משום מוקצה:"],[8,"א\"ל רבינא לרב אשי ואי אינהו תלו ליה לא שקיל והא\"ר יוחנן הלכה כר' דוסא","דאמר הרי הוא כרגלי הרועה אלמא כיון דאין רועה בעיר אלא הוא ואנן סהדי דכל מי שיש לו בהמה דעתו שתהא כרגליו אמרינן בתריה אזלה וכל שכן הכא דאוקמוה בהדיא ברשותיה ואדעתא דידיה תלו ליה:"],[9,"שאני עברא דדשא","כלומר שאני הכא דתלינהו איהו גופיה בעברא דדשא והם לא קבלוהו מידו לשמרו דכמי שיחד לו קרן זוית דמי:"],[10,"","א\"ל רב הלל לרב אשי ואי אינהו תלו ליה לא שקיל והאמר שמואל שור של פטם הרי הוא כרגלי כל אדם. אלמא כיון דאוקמיה במחשבתו ברשות כל מי שיקנהו מותר הקונה להוליכו למקומו והכא נמי הא ברשותיה אוקמיה במחשבתו ברשות כל מי שיקחנו:"],[11,"כרגלי הבעלים","וכיון דלצרכו תלאוה שם הוה ליה איהו בעלים:"],[12,"אלא שאני רב חנא בר חנילאי כו'","וטעמא לאו משום תחומין אלא רב הונא דאורי ליה הכי תלמידיה דרב הוה ורב אמר בשחיטת חולין (חולין דף צה.) בשר כיון שנתעלם מן העין אסור ואפי' תלוי ביתד בבית ישראל ורב חנא אגב טרדא דשמעתיה משכח שאר עסקיו:"],[12,"והכי קאמר ליה","רב הונא:"],[13,"מתני' אין משקין ושוחטין את המדבריות","משום מוקצה ובגמרא מפרש אמאי נקט משקין:"],[14,"גמ' מלתא אגב אורחיה","דתנא דה\"ל לאורויי בבהמות מי מותרת ומי אסורה נקט אורחיה בלישנא דמשמע מינה מילתא חדתי בדרך ארץ:"],[14,"משום סרכא דמשכא","שתהא נוחה להפשיטה שהוא נדבק יותר מדאי בבשר:"],[15,"ונכנסות","לישוב:"],[15,"ברביעה","במרחשון:"],[16,"פצעילי תמרה","תמרים שאין מתבשלות באילן לעולם וגודרין אותן מהאילן ועושין להן חותלות הן כלי כפות תמרים וכונסין אותן לתוכן ומתבשלות:"],[16,"מהו","לאכול מהן ביום טוב:"]],[[0,"","ת\"י [אלא אם כן זכה להן. תימה ל\"ל זכה אפי' בירר חלק כל אחד ואחד נמי מידי דהוה אשואל דאמרינן לעיל (ביצה דף לח.) אע\"פ שלא נתנו לו אלא ביו\"ט וכו' וי\"ל דשואל דעתיה טפי אכלי מאורחים על מנות]."],[5,"","[תנן ואם עירב הוא פירותיו כמוהו. מרישא דקתני ואם ערבו בני אותה עיר לא יביאו לא מצי למידק דאיכא למימר דלא ערבו הנפקדים]:"],[16,"","פצעילי תמרה. פ\"ה תמרים שאינם מתבשלין באילן לעולם וגודרין אותן מן הדקל ועושין להם חותלות וכונסין לתוכן ומתבשלות ומבעיא לר\"ש מהו לאכול מהן ביו\"ט ולא נהירא דפצעילי תמרה לא משמע הכי אלא פירושו דהוי פגי תמרה שסופן להיות נגמרין ומתוקין יפה יפה ועדיין לא נתבשלו ופוצעין אותם אחת לשנים בסכין ומעלין אותן לגג ליבשן ולא הוו כגרוגרות וצמוקין דלא דחינהו בידים דלא היו ראוין מעולם:"]]],[["אלא גרוגרות וצמוקין בלבד","איבעית אימא הני נמי כגרוגרות וצמוקין דמי ואיבעית אימא לדבריו דר\"ש קאמר וליה לא ס\"ל","ואיבעית אימא לדבריהם דרבנן קאמר להו לדידי אין מוקצה אלא לדידכו אודו לי מיהת היכא דיוצאות ורועות בפסח ונכנסות ברביעה ראשונה דבייתות הן ואמרו ליה רבנן לא מדבריות הן:","\u0001הדרן עלך משילין פירות וסליקא לה מסכת ביצה\u0002"],[[0,"אלא בגרוגרות וצמוקין","שהן מתחלה ראויין לאכילה והוא דחה אותן בידים להעלותן ליבשן ושוב אינן ראויין עד שייבשו אבל אלו לא דחה אותן בידים ואיכא דאכיל מנייהו הכי קא סלקא דעתיה מדפריש ליה מילתיה דר\"ש אלמא כר\"ש ס\"ל:"],[1,"איבעית אימא הני","מדבריות שאין נכנסות לישוב כלל כגרוגרות וצמוקין דמיין שמקצה אותן מאצלו בידים:"],[1,"ואיבעית אימא","אין מוקצה לר\"ש קאמר ליה אבל לדידי יש מוקצה:"],[2,"ואב\"א","מתני' לדבריהם דרבנן דאית להו מוקצה קאמר להו:"]],[]]]};
